locales_quest = locales_quest or {}
locales_quest['itIT'] = {
  [1] = {
    'Missione di Kanrethad',
    nil,
    nil,
  },
  [2] = {
    'L\'Artiglio di Grinfiafina',
    nil,
    nil,
  },
  [10] = {
    nil,
    nil,
    {'Scopri il destino di Junior Surveyor Scrimshank e porta lui o il suo equipaggiamento per il rilevamento al Senior Surveyor Fizzledowser di Gadgetzan.', },
  },
  [11] = {
    'Taglia sugli Gnoll Zampaumida',
    {'Gli Gnoll, delle creature selvagge che non dovrebbero abitare queste terre, sono stati avvistati lungo i confini della Foresta di Elwynn. Un grosso branco, composto da un numero di esemplari che non possiamo affrontare da soli, ha invaso i boschi a sud della torre di guardia. Un altro gruppo ha infestato le zone vicino al Lago del Memoriale a est.|n|nL\'Esercito di Roccavento ricompenserà chiunque dia una mano a eliminarli. Portami le Polsiere degli Gnoll Dipinte come prova della loro uccisione.', },
    {'Porta 8 Polsiere degli Gnoll Dipinte al Vicesceriffo Rainer nella Caserma.', },
  },
  [12] = {
    'Milizia Popolare',
    nil,
    nil,
  },
  [13] = {
    'Milizia Popolare',
    nil,
    nil,
  },
  [14] = {
    'Milizia Popolare',
    nil,
    nil,
  },
  [16] = {
    'Dissetare Gerard',
    nil,
    nil,
  },
  [22] = {
    'Torta di Fegato di Goretusk',
    nil,
    nil,
  },
  [23] = {
    'Zampa di Ursangous',
    nil,
    nil,
  },
  [24] = {
    'La Testa di Shadumbra',
    nil,
    nil,
  },
  [25] = {
    'Calmare le acque',
    nil,
    nil,
  },
  [26] = {
    'Una lezione da imparare',
    nil,
    nil,
  },
  [27] = {
    'Una lezione da imparare',
    nil,
    nil,
  },
  [28] = {
    nil,
    {'[For your first trial, search the depths of Lake Elune\'ara to locate a Shrine Bauble. It decays rapidly, so proceed with it to the Shrine of Remulos post haste. Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade\'s most trusted wardens.|n|nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves. Mental and physical dexterity will be critical to your success.|n|nGood luck, $N.]', },
    nil,
  },
  [29] = {
    nil,
    {'[For your first trial, search the depths of Lake Elune\'ara to locate a Shrine Bauble. It decays rapidly, so proceed with it to the Shrine of Remulos post haste. Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade\'s most trusted wardens.|n|nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves. Mental and physical dexterity will be critical to your success.|n|nGood luck, $N.]', },
    nil,
  },
  [31] = {
    'Forma Acquatica',
    {'[You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect. Go now back to your trainer, Turak Runetotem, in Thunder Bluff. Show him your pendant and prove to him you are ready to learn what he has to teach you. He will complete your training, allowing you to become one with the water.|n|nGoodbye, young druid. We shall speak again.]', },
    nil,
  },
  [35] = {
    'Altre preoccupazioni',
    nil,
    {'Il Maresciallo Dughan ti ha chiesto di parlare con la Guardia Thomas.', },
  },
  [36] = {
    'Sufato di Westfall',
    nil,
    nil,
  },
  [37] = {
    'Le guardie scomparse',
    {'Pochi giorni fa abbiamo inviato due guardie, Rolf e Malakai, in perlustrazione lungo il fiume. Non sono ancora tornate. Per completare il mio rapporto devo sapere che fine hanno fatto.|n|nRisali il fiume verso nord e trova le guardie... o quel che ne resta.', },
    {'La Guardia Thomas ti ha chiesto di risalire il fiume verso nord alla ricerca di Rolf e Malakai, le due guardie scomparse.', },
  },
  [38] = {
    'Sufato di Westfall',
    nil,
    nil,
  },
  [40] = {
    'Pericolo dall\'acqua',
    {'$N, c\'è una nuova minaccia nella Foresta di Elwynn! I Murloc stanno risalendo i corsi d\'acqua nella parte orientale di Elwynn, spaventando i pesci e attaccando la popolazione!|n|nHo avvertito il Maresciallo Dughan, ma non ha voluto darmi ascolto. Non crede che i Murloc rappresentino un pericolo, teme di più gli Gnoll e i banditi.|n|nTi prego, $N, va\' a parlare con Dughan e convincilo a mandare altre truppe a est!', },
    {'Remy "Due Volte" ti ha chiesto di parlare con il Maresciallo Dughan a Borgodoro.', },
  },
  [45] = {
    'Il destino di Rolf',
    {'<Dopo aver esaminato la zona in maniera più approfondita, scopri delle impronte palmate che si dirigono verso est, lungo la costa del Lago del Memoriale. In lontananza riesci a scorgere un villaggio dei Murloc.>|n|n<Forse Rolf ha trovato la morte proprio lì...>', },
    {'Perlustra il villaggio dei Murloc in cerca di Rolf o di prove della sua morte.', },
  },
  [46] = {
    'Taglia sui Murloc',
    nil,
    {'Consegna 8 Pinne di Murloc Strappate alla Guardia Thomas presso il ponte di Elwynn a est.', },
  },
  [47] = {
    'Alla ricerca della Polvere d\'Oro',
    nil,
    {'Consegna 10 Mucchi di Polvere d\'Oro a Remy "Due Volte" nella città di Borgodoro. Puoi raccogliere la Polvere d\'Oro dai Coboldi nella Foresta di Elwynn.', },
  },
  [48] = {
    nil,
    {'[In the land to the south where vines twist and creep|nLies a hidden well where the water runs deep|nPure as the Light\'s sacred Daughter|nBring to me now some Holy Spring Water.]', },
    nil,
  },
  [49] = {
    nil,
    {'[Amber is the hue of my life\'s longest love|nLike the last embers of dusk in the sky above|nRetrieve for me so that my love shall be born|nOne sack of each: barley, rye and corn.]', },
    nil,
  },
  [50] = {
    nil,
    {'[I\'ll mix and mix till we have a mash|nFor this will be our own private stash|nA still must be fashioned of metal strong|nBring me some Truesilver so I can finish this song.]', },
    nil,
  },
  [52] = {
    'Proteggere la frontiera',
    {'Salute, $N. Gli animali selvaggi diventano sempre più aggressivi man mano che ci allontaniamo da Borgodoro, e il Campo di Taglio di Vallevante è vittima di attacchi costanti da parte di lupi e orsi!|n|nAbbiamo bisogno del tuo aiuto.', },
    nil,
  },
  [53] = {
    nil,
    {'[Mellifluous liquid clear as a baby\'s tears|nTurns a lovely deep amber over the years|nBut before we proceed to get lit to the hilt|nA barrel of charred oak must be built.]', },
    nil,
  },
  [54] = {
    'Rapporto a Borgodoro',
    {'$N, hai dimostrato valore nel difendere la Contea del Nord. Ora, ti affido l\'incarico di proteggere l\'area circostante alla Foresta di Elwynn.|n|nSe decidi di accettare, sappi che ho preparato dei documenti che devono essere consegnati al Maresciallo Dughan a Borgodoro, lungo la strada che porta a sud, oltre la barriera di confine.', },
    nil,
  },
  [55] = {
    nil,
    {'[Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end...|n|nUse Morbent\'s Bane against him. It will render his protective magics powerless.|n|nSlay him. Slay him, and save us from his wickedness. Be the instrument of my revenge, and a hero of Duskwood!]', },
    nil,
  },
  [56] = {
    nil,
    {'[As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire. Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.|n|nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages. The undead threat must be thwarted!]', },
    nil,
  },
  [59] = {
    'Armature di stoffa e cuoio',
    nil,
    {'Consegna il Buono per un\'Armatura di Roccavento a Sara Timberlain.', },
  },
  [60] = {
    'Candele dei Coboldi',
    nil,
    {'Porta 8 Candele Grandi a William Pestel a Borgodoro.', },
  },
  [61] = {
    nil,
    {'[My brother Morgan is waiting in Stormwind for my shipment of candles. I don\'t have enough time to make the trip myself, but if you\'d like to take him the shipment, he\'ll pay you well.|n|nI\'ve packed up the candles, and you can find Morgan in our shop, Pestle\'s Apothecary, in the Stormwind Trade District.]', },
    nil,
  },
  [62] = {
    'La Miniera Antrocupo',
    {'La miniera della Contea del Nord non è l\'unica ad avere problemi! Secondo i rapporti che ho ricevuto, anche la Miniera Antrocupo a Elwynn è stata occupata dai Coboldi.|n|nLa miniera si trova a sud di Borgodoro, tra le fattorie dei Pietradura e dei Maclure. Vai là ed esplorala per confermare questi rapporti, poi torna da me.', },
    {'Esplora la Miniera Antrocupo, poi torna dal Maresciallo Dughan a Borgodoro.', },
  },
  [63] = {
    nil,
    {'[Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.|n|nTake the elemental\'s bracers, along with the remaining drops of Brine\'s potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.|n|nBring me proof the task is done, and I will reward you with your totem.]', },
    nil,
  },
  [66] = {
    'Leggenda di Stalvan',
    nil,
    nil,
  },
  [68] = {
    'Leggenda di Stalvan',
    {'[You find a Dusty Unsent Letter in the old footlocker.]', },
    nil,
  },
  [70] = {
    'Leggenda di Stalvan',
    {'[The name Stalvan rings a bell. I remember now.|n|nMany years back, on a stormy night, a messenger came in, seeking refuge for the night. Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear. Still wearing his bedclothes, he disappeared into the downpour.|n|nIn his haste he forgot his letters in the chest upstairs. He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind. Help yourself to it.]', },
    nil,
  },
  [71] = {
    'A rapporto da Thomas',
    {'Ora che hai entrambi i medaglioni, consegnali alla Guardia Thomas presso il ponte, in modo che sappia che le sue guardie sono state uccise.', },
    {'Consegna i Medaglioni di Rolf e Malakai alla Guardia Thomas presso il ponte di Elwynn a est.', },
  },
  [72] = {
    'Leggenda di Stalvan',
    {'[My father was the caretaker of the estate long before I was. He had to mop the blood up after the massacre. But that\'s neither here nor there.|n|nThe last funds of the Flintridge trust have dried up. Now the last of the family possessions are headed for auction. Blame the tax vultures. I guess if you\'re really itching to learn more you\'re free to look through this junk. Who knows what you might find.]', },
    nil,
  },
  [73] = {
    '&lt;TXT&gt; No Reward',
    nil,
    nil,
  },
  [74] = {
    'Leggenda di Stalvan',
    {'[Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books. Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.]', },
    nil,
  },
  [75] = {
    'Leggenda di Stalvan',
    {'[There was a bundle of parchments in the chest upstairs when I moved into this place. I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. |n|nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character. I\'m pretty sure there\'s a faded journal page that might be of interest to you. Bring it to me and I\'ll help in anyway I can.]', },
    nil,
  },
  [76] = {
    'La Miniera Venarossa',
    {'Grazie a te ora sappiamo che la Miniera Antrocupo è infestata dai Coboldi. Vorrei che esplorassi la Miniera Venarossa per verificare la presenza di quelle creature anche lì.|n|nPer raggiungere la miniera, segui la strada a est fino alla Torre di Azora e da lì dirigiti a nord. La miniera si trova ai piedi delle colline.', },
    {'Esplora la Miniera Venarossa, poi fai rapporto al Maresciallo Dughan nella città di Borgodoro.', },
  },
  [77] = {
    nil,
    {'[I possess original packaging materials for the ripple Dran Droffers seeks. I will assist you in packaging the ripple for Malton\'s abrasive father... for a fee of two additional bottles of said ripple. They are located in crates found in the abandoned Horde base near Skulk Rock.|n|nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze. Regardless, procure the ripple and return to me here for packaging.]', },
    nil,
  },
  [78] = {
    'Leggenda di Stalvan',
    {'[I know of someone who might be able to assist you. Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire. The Innkeeper there, Smitts, was quite an expert on the local lore. Show him this page and see what he has to say about it.]', },
    nil,
  },
  [79] = {
    'Leggenda di Stalvan',
    {'[I followed the legend of that Stalvan character for years. When those visiting nobles were slaughtered a few years back I went with Haggard to investigate. I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods. Your trail of evidence proves his guilt. Take this to Commander Ebonlocke immediately and fill her in on what you\'ve discovered!]', },
    nil,
  },
  [80] = {
    'Leggenda di Stalvan',
    {'[I have had my eye on that creep, Stalvan, for quite sometime. But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.|n|nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting. Show him this page and see if the writing matches that of the registry signature.]', },
    nil,
  },
  [81] = {
    nil,
    {'[I have taken the extra step of securing not only Dran\'s packaged ripple in the barrel, but also the extra bottles of ripple he is purloining. While I may not hold Dran very highly, there is nothing worse than jostled ripple. You\'re welcome.|n|nNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar. Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.]', },
    nil,
  },
  [83] = {
    'Capi di lino eleganti',
    nil,
    nil,
  },
  [84] = {
    'Ritorno da Billy',
    {'Ecco qua. Quando consegnerai questo pasticcio a Billy, digli che spero gli vada di traverso!', },
    {'Porta il Pasticcio di Carne di Cinghiale a Billy Maclure presso le Vigne dei Maclure.', },
  },
  [85] = {
    'La collana rubata',
    nil,
    {'Parla con Billy Maclure.', },
  },
  [86] = {
    'Un pasticcio per Billy',
    nil,
    nil,
  },
  [87] = {
    nil,
    nil,
    {'Porta la Collana di Bernice a "Zia" Bernice Pietradura nella Fattoria dei Pietradura.', },
  },
  [88] = {
    'Principessa deve morire!',
    nil,
    {'Uccidi Principessa, prendi il suo collare e riportalo a Ma Pietradura nella Fattoria dei Pietradura.', },
  },
  [92] = {
    'Gulasch alla Crestarossa',
    nil,
    nil,
  },
  [93] = {
    'Tortino di Granchio Scuro',
    {'[I\'ll let you in on a little secret - Dusky "Crab" Cakes are really made from spider legs! I know it\'s a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks! Bring me Gooey Spider Legs and I\'ll whip you up a few of them.|n|nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river. ]', },
    nil,
  },
  [94] = {
    nil,
    {'[My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge. I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.|n|nBut to study his thoughts ... I require further aid.|n|nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar. Place it upon the Lion Statue near the Tower.|n|nWhen this is done, the power of Azora will grant visions of Morganth\'s future plans.]', },
    nil,
  },
  [96] = {
    nil,
    {'[Take shard. Take shard and give life.|n|nGive life and understand. Understand water is life... corruption stops life.|n|nYou protect and give life with water\'s power.]', },
    nil,
  },
  [98] = {
    'Leggenda di Stalvan',
    {'[Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire. The Light only knows what sordid acts he is plotting. Travel to his cottage just north of town, $C, and execute Stalvan, once and for all.|n|nWhen the deed is done, travel to Madame Eva\'s and show her his family ring. After all, it was her premonition that led to this gruesome discovery. But Darkshire is safer because of her.]', },
    nil,
  },
  [100] = {
    nil,
    {'[Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.]', },
    nil,
  },
  [104] = {
    nil,
    {'Quando la mia vita si è infranta sulle rocce, non sapevo cosa mi sarebbe toccato nell\'aldilà. Quella notte, il faro era spento perché Vecchio Occhiobuio aveva spaventato la famiglia del custode, che però era riuscita a fuggire. Tornarono e riaccesero il faro, ma Vecchio Occhiobuio forzò i Murloc ad aiutarlo in una nuova aggressione. La famiglia non ebbe la fortuna della prima volta e venne massacrata sotto i miei occhi.|n|nSe lo incontri sulla spiaggia, uccidi Vecchio Occhiobuio e portami una delle sue scaglie. Ti ricompenserò.', },
    {'Porta una Scaglia di Vecchio Occhiobuio al Capitano Grayson presso il Faro delle Marche Occidentali.', },
  },
  [106] = {
    'Giovani amanti',
    {'Povera me! Sono innamorata di Tommy Joe Pietradura, ma la rivalità che divide le nostre due famiglie mi impedisce di vederlo. Quanto vorrei posare il mio sguardo sul suo incantevole viso...|n|nPrendi questa lettera e consegnala a Tommy Joe da parte mia. Di solito si trova nei pressi del fiume a ovest della Fattoria dei Pietradura, a ovest di qui.', },
    {'Consegna la Lettera d\'Amore di Maybell a Tommy Joe Pietradura.', },
  },
  [107] = {
    'Nota per William',
    {'Scommetto che William Pestel ha una pozione per riunire i nostri due giovani innamorati!|n|nTieni, consegna questa nota a William. Si trova nella Locanda del Fiero Leone a Borgodoro.', },
    {'Consegna la Nota di Nonna Pietradura a William Pestel.', },
  },
  [111] = {
    'A colloquio con la nonna',
    {'Ti prego, $N, parla con mia nonna. Lei è l\'unica che può aiutarmi a stare insieme a Maybell.|n|nSi trova nella nostra casa a est.', },
    {'Parla con Nonna Pietradura.', },
  },
  [112] = {
    'Raccolta alghe',
    nil,
    {'Porta 4 Fronde d\'Alga di Cristallo a William Pestel nella città di Borgodoro.', },
  },
  [114] = {
    'La fuga',
    {'Porta questo Liquore dell\'Invisibilità alla giovane Maybell. Dovrebbe durare abbastanza da permetterle di incontrare Tommy Joe.', },
    {'Consegna il Liquore dell\'Invisibilità a Maybell Maclure.', },
  },
  [123] = {
    'Il Collezionista',
    nil,
    nil,
  },
  [134] = {
    nil,
    {'Qualche settimana fa stavo raccogliendo delle erbe lontano da casa mia, quando sono stato attaccato da un gruppo di Ogre! Sono fuggito, lasciandomi dietro una cassa piena di attrezzi ed erbe preziose.|n|nDopo che hanno smesso di inseguirmi, gli Ogre sono tornati nel loro tumulo a Boscovespro meridionale. Sono sicuro che la mia cassa si trova da qualche parte vicino al tumulo.|n|nTi prego, $N, va\' a recuperarla per me.', },
    {'Riporta la Cassa di Abercrombie ad Abercrombie.', },
  },
  [136] = {
    nil,
    {'"Se stai leggendo questo messaggio, significa che il vecchio Capitano Sanders riposa in una tomba sott\'acqua. Il mio tesoro è tuo, sempre se riuscirai a seguire gli indizi."|n|n"Per prima cosa devi trovare il mio scrigno. Dev\'essere mezzo sepolto nella sabbia, lungo la costa ovest delle Marche Occidentali, vicino a uno dei relitti nell\'area, quello con l\'ancora arrugginita sulla costa. Trova l\'ancora e troverai lo scrigno! Dentro c\'è l\'indizio successivo."', },
    {'Trova lo scrigno del Capitano Sanders ed esaminalo a caccia d\'indizi.', },
  },
  [138] = {
    nil,
    {'<L\'indizio per il tesoro dice:>|n|n"Bel lavoro! Ora devi dirigerti a est, oltre i promontori, verso la strada. Cerca le rovine del vecchio camino vicino al sentiero. Lì troverai un barile dimenticato con il prossimo indizio."', },
    {'Trova il barile dimenticato vicino alle rovine del vecchio camino e cerca l\'indizio successivo.', },
  },
  [139] = {
    nil,
    {'<Esaminando il barile scopri un\'altra cartapecora che dice:>|n|n"Ora, rivolgiti a nord da questo barile. Continua a procedere dritto in linea d\'aria fino a quando non vedrai un fiasco vuoto accanto al mulino abbandonato, sui promontori a picco sul mare. Controlla all\'interno del fiasco e troverai ciò che stai cercando."', },
    {'Cerca il prossimo indizio nel Fiasco Vuoto vicino al mulino.', },
  },
  [140] = {
    nil,
    {'<Nel vecchio fiasco c\'è un altro indizio del tesoro di Sanders. L\'inchiostro è sbiadito e la carta puzza di whiskey, ma riesci a leggere parte del testo:>|n|n"Ora che hai trovato il mio vecchio fiasco di whisky, sei a un passo dal tesoro! Girati verso ovest dal fiasco e procedi lungo la riva. Una volta raggiunta l\'acqua, continua ad avanzare! Nuota dritto verso ovest fino all\'isola con la mia cassa del tesoro!"', },
    {'Trova la cassa del Capitano Sanders e aprila per ottenere la ricompensa.', },
  },
  [147] = {
    nil,
    {'Questo "Collezionista" sta rubando l\'oro dalle nostre miniere! Voglio che lo consegni alla giustizia e mi porti l\'anello citato nel programma di raccolta che mi hai consegnato. Potrebbe dirci per chi lavora...|n|nSecondo il programma, il Collezionista si nasconderebbe nel Campo di Zucche dei Pozzonero. Vai lì e trovalo.', },
    nil,
  },
  [149] = {
    'Filo di Capelli Spettrali',
    {'C\'è un povero spirito triste, Mary la Cieca, che infesta una vecchia fattoria tra le colline a sud di Borgoscuro.|n|nPrendi questo Pettine Spettrale e chiedi a Mary la Cieca di usarlo per pettinarsi. Riportamelo e recupererò i Capelli Spettrali che mi servono per realizzare il filo.|n|nSii prudente, perché ci sono presenze oscure che si aggirano intorno a quella casa...', },
    {'Consegna il Pettine Spettrale a Mary la Cieca.', },
  },
  [154] = {
    nil,
    nil,
    {'Riconsegna il Pettine con Capelli Spettrali a Dama Eva nel villaggio di Borgoscuro.', },
  },
  [157] = {
    nil,
    {'Ecco il tuo filo, $N. Ha mille usi, dal legare gli spiriti malvagi al dare vita agli oggetti inanimati.', },
    nil,
  },
  [158] = {
    nil,
    nil,
    {'Parla con il Taverniere Smitts.', },
  },
  [159] = {
    nil,
    {'Ecco il tuo Distillato di Zombi...|n|nFa\' attenzione con questa roba. È abbastanza forte da far resuscitare i morti!', },
    nil,
  },
  [160] = {
    nil,
    {'Consegna questa lettera a Ello Serranero, il Sindaco di Borgoscuro.|n|nSiamo vecchi amici... quando la leggerà e scoprirà ciò che hai fatto per me, sono certo che sarà contento quanto lo sono io! Ah ah ah!', },
    {'Consegna la Lettera di Abercrombie a Ello Serranero, Sindaco di Borgoscuro.', },
  },
