  [3088] = {
    'Cartapecora codificata',
    {'Ah. Mentre eri via $N, ti è arrivata della posta.|n|nQuando hai tempo, dagli una lettura. Se non mi sbaglio proviene da Rwag, l\'Istruttore dei Ladri. Quando sarai disponibile, vorrebbe scambiare due parole con te.', },
    {'Leggi la Cartapecora Codificata e parla con Rwag nella Valle delle Sfide.', },
  },
  [3089] = {
    'Cartapecora con rune',
    {'Ah. Mentre eri via $N, ti è arrivata della posta.|n|nQuando hai tempo, dagli una lettura. Se non mi sbaglio proviene da Shikrik, l\'Istruttore degli Sciamani. Quando sarai disponibile, vorrebbe scambiare due parole con te.', },
