  [3117] = {
    'Sigillo Intagliato',
    {'Questo sigillo mi è stato dato da un messaggero della nostra Istruttrice dei Cacciatori, Ayanna. Sembra che voglia parlare con te quando hai un attimo di tempo. Leggilo e portaglielo.', },
    nil,
  },
  [3118] = {
    'Sigillo Codificato',
    {'Questo sigillo mi è stato dato da un messaggero del nostro Istruttore dei Ladri, Frahun. Sembra che voglia parlare con te quando hai un attimo di tempo. Leggilo e portaglielo.', },
    nil,
