  [7944] = {
    'La tua fortuna ti attende...',
    {'"La tua fortuna ti attende all\'interno della Caverna dei Lamenti".|n|n<Il biglietto della fortuna che ti ha consegnato Sayge è leggermente tiepido al tocco. Stringendolo, vedi un\'immagine di una caverna nella parte sudoccidentale del Crocevia, nelle Savane. Guardando più attentamente l\'immagine, noti una serie di passaggi tortuosi che termina davanti a un portale luminoso, che conduce nel cuore della caverna stessa. Entrandoci, dal nulla appare uno strano forziere.>', },
    {'Raggiungi la Caverna dei Lamenti nelle Savane e cerca la tua fortuna.', },
  },
  [7945] = {
    'La tua fortuna ti attende...',
    {'"La tua fortuna ti attende fuori la Roccia dei Mantopallido".|n|n<Il biglietto della fortuna che ti ha consegnato Sayge è leggermente tiepido al tocco. Stringendolo, vedi un\'immagine della Roccia dei Mantopallido a Mulgore. Guardando più attentamente l\'immagine, scorgi un ceppo accanto all\'ingresso della caverna.>', },
    {'Raggiungi la Roccia dei Mantopallido a Mulgore e cerca la tua fortuna.', },
  },
