  [8770] = {
    'Obiettivo: Difensori dell\'Alveare Ashi',
    {'Con l\'aumentare degli sforzi bellici, la presenza dei Silitidi nell\'area rappresenta un crescente pericolo per le nostre operazioni. Sei <stato scelto/stata scelta> per partecipare a un assalto all\'Alveare Ashi, dove il tuo obiettivo principale sarà eliminare i Difensori dell\'Alveare Ashi.|n|nFai rapporto al Comandante Mar\'alith una volta completata la missione.', },
    {'Uccidi 30 Difensori dell\'Alveare Ashi e fai rapporto al Comandante Mar\'alith nella Fortezza Cenariana a Silitus. Per poter completare la missione, devi anche avere con te le Istruzioni per il Combattimento I.', },
  },
  [8771] = {
    'Obiettivo: Inseguitori delle Sabbie dell\'Alveare Ashi',
    {'Con l\'aumentare degli sforzi bellici, la presenza dei Silitidi nell\'area rappresenta un crescente pericolo per le nostre operazioni. Sei <stato scelto/stata scelta> per partecipare a un assalto all\'Alveare Ashi, dove il tuo obiettivo principale sarà eliminare gli Inseguitori delle Sabbie dell\'Alveare Ashi.|n|nFai rapporto al Comandante Mar\'alith una volta completata la missione.', },
    {'Uccidi 30 Inseguitori delle Sabbie dell\'Alveare Ashi e fai rapporto al Comandante Mar\'alith nella Fortezza Cenariana a Silitus. Per poter completare la missione, devi anche avere con te le Istruzioni per il Combattimento II.', },
  },
  [8772] = {
    'Obiettivo: Vigilanti dell\'Alveare Zora',
    {'Abbiamo richiesto rinforzi per l\'assalto all\'Alveare Zora. Sei <stato selezionato/stata selezionata> per colpire i Vigilanti dell\'Alveare Zora. Fai rapporto al Comandante Mar\'alith una volta completata la missione.', },
    {'Uccidi 30 Vigilanti dell\'Alveare Zora e fai rapporto al Comandante Mar\'alith nella Fortezza Cenariana a Silitus. Per poter completare la missione, devi anche avere con te le Istruzioni per il Combattimento VI.', },
  },
  [8773] = {
    'Obiettivo: Razziatori dell\'Alveare Zora',
    {'Abbiamo richiesto rinforzi per l\'assalto all\'Alveare Zora. Sei <stato selezionato/stata selezionata> per colpire i Razziatori dell\'Alveare Zora. Fai rapporto al Comandante Mar\'alith una volta completata la missione.', },
    {'Uccidi 30 Razziatori dell\'Alveare Zora e fai rapporto al Comandante Mar\'alith nella Fortezza Cenariana a Silitus. Per poter completare la missione, devi anche avere con te le Istruzioni per il Combattimento IV.', },
  },
  [8774] = {
