  [8801] = {
    'Il retaggio di C\'Thun',
    {'<Le mura di Ahn\'qiraj tremano. Una forza maligna, più antica del mondo stesso, è stata annientata.>|n|n<Mentre osservi i resti di quel colossale Abominio, il tuo cuore quasi si ferma. Persino dopo la morte di C\'Thun, avverti palpabile la forza maligna del suo retaggio.>|n|n<Hai compiuto un\'impresa che tutti credevano irrealizzabile.>|n|n<Cavi un occhio dal bulbo di quel demonio, mettendolo al sicuro nelle tue sacche.>|n|n<Porta l\'Occhio di C\'Thun ai draghi nella sala accanto.>', },
    {'Porta l\'Occhio di C\'Thun a Caelastrasz nel Tempio di Ahn\'qiraj.', },
  },
  [8802] = {
    'Il salvatore di Kalimdor',
    nil,
    {'Porta l\'Occhio di C\'Thun ad Anacronos nelle Caverne del Tempo.', },
  },
