  [9299] = {
    'Una nota dal fronte',
    {'<Hai trovato questa lettera addosso a uno dei tanti servi del Flagello che hai ucciso. A giudicare dall\'aspetto e dall\'odore, era in suo possesso da un bel po\' di tempo. Forse qualcuno alla Cappella della Luce è interessato a esaminarla...>', },
    {'Porta la Nota Rovinata al Custode degli Archivi nella Cappella della Luce delle Terre Infette Orientali.', },
  },
  [9300] = {
    'Una pagina dal fronte',
    {'<Hai trovato questa lettera addosso a uno dei tanti servi del Flagello che hai ucciso. A giudicare dall\'aspetto e dall\'odore, era in suo possesso da un bel po\' di tempo. Forse qualcuno alla Cappella della Luce è interessato a esaminarla...>', },
    {'Porta la Pagina Stracciata al Custode degli Archivi nella Cappella della Luce delle Terre Infette Orientali.', },
  },
  [9301] = {
    'Una busta dal fronte',
    {'<Hai trovato questa lettera addosso a uno dei tanti servi del Flagello che hai ucciso. A giudicare dall\'aspetto e dall\'odore, era in suo possesso da un bel po\' di tempo. Forse qualcuno alla Cappella della Luce è interessato a esaminarla...>', },
    {'Porta la Busta Macchiata di Sangue al Custode degli Archivi nella Cappella della Luce delle Terre Infette Orientali.', },
  },
  [9302] = {
    'Una missiva dal fronte',
    {'<Hai trovato questa lettera addosso a uno dei tanti servi del Flagello che hai ucciso. A giudicare dall\'aspetto e dall\'odore, era in suo possesso da un bel po\' di tempo. Forse qualcuno alla Cappella della Luce è interessato a esaminarla...>', },
    {'Porta la Lettera Sgualcita al Custode degli Archivi nella Cappella della Luce delle Terre Infette Orientali.', },
  },
  [9303] = {
    nil,
    {'Zhanaa ha bisogno del nostro aiuto per recuperare alcune parti della Exodar. Taerix ha preparato un cristallo da vaccinazione da somministrare ai Gufoidi Legnocelato che vivono nell\'area in cui si trovano le componenti da recuperare.|n|nAvvicinati ai Gufoidi non contaminati e usa il cristallo su di essi. Purtroppo, gli altri dovrai ucciderli. Troverai i Gufoidi nella Selva di Legnocelato e sulle Colline di Legnocelato a sud est di qui.', },
    {'Usa il Cristallo da Vaccinazione su 6 Gufoidi Legnocelato, quindi torna dal Vendicatore Aldar al Punto d\'Impatto nella Valle di Ammen.', },
  },
  [9304] = {
    'Un documento dal fronte',
    {'<Hai trovato questa lettera addosso a uno dei tanti servi del Flagello che hai ucciso. A giudicare dall\'aspetto e dall\'odore, era in suo possesso da un bel po\' di tempo. Forse qualcuno alla Cappella della Luce è interessato a esaminarla...>', },
    {'Porta il Documento Macchiato al Custode degli Archivi nella Cappella della Luce delle Terre Infette Orientali.', },
  },
  [9305] = {
    'Pezzi di ricambio',
    {'Siamo riusciti a recuperare dai rottami un proiettore olografico danneggiato. Riparandolo, avremo la possibilità di trovare i superstiti finiti fuori dalla Valle di Ammen.|n|nNell\'area tutt\'intorno vi sono delle componenti della nave che potrebbero essere recuperate, ma i Gufoidi locali le hanno portate via prima che potessimo prelevarle.|n|n$N, recati a sud alla Selva di Legnocelato e sulle Colline di Legnocelato e trova dei pezzi di ricambio.', },
    {'Recupera 4 Pezzi di Ricambio del Proiettore e torna dalla Tecnica Zhanaa al Punto d\'Impatto nella Valle di Ammen.', },
  },
  [9306] = {
    nil,
    nil,
    {'Parla con il Vendicatore Aldar al Punto d\'Impatto nella Valle di Ammen.', },
  },
  [9309] = {
    'L\'esploratore scomparso',
    {'Abbiamo ricevuto diverse segnalazioni di inusuali attività sulla Cresta dell\'Ombra.|n|nLa cosa ci turba: credevamo che le missioni esplorative già concluse fossero state esaustive. A ogni modo, uno dei miei esploratori non è ancora tornato a fare rapporto.|n|n$C, dovresti dirigerti a sud-ovest, raggiungere l\'altra sponda del Lago di Filargento e trovare Tolaan, per scoprire cosa l\'ha trattenuto.', },
    {'Trova Tolaan e parla con lui sulla Cresta dell\'Ombra nella Valle di Ammen.', },
  },
  [9310] = {
    'Cristallo Necrotico Debole',
    nil,
    {'Porta il Cristallo Necrotico Debole al Tenente Rukag nel Cortile di Sepulcra.', },
  },
  [9311] = {
    'Spia degli Elfi del Sangue',
    {'Ho un piano. Dobbiamo uccidere il loro capo. Senza una guida, forse si ritireranno per riorganizzarsi. E noi abbiamo solo bisogno di guadagnare tempo fino al completamento delle riparazioni.|n|nA quel punto andrà avvisato il Vendicatore Aldar. Uccidi l\'Ispettrice, quindi fai ritorno e riferiscigli le tue scoperte.', },
    {'Uccidi l\'Ispettrice Candress, quindi informa il Vendicatore Aldar al Punto d\'Impatto nella Valle di Ammen.', },
  },
  [9312] = {
    'Il proiettore',
    {'$N, mentre ti trovavi sulla Cresta dell\'Ombra, Zhanaa ha lavorato al proiettore olografico. Forse ti converrebbe andare a parlarle.', },
    {'Parla con la Tecnica Zhanaa al Punto d\'Impatto nella Valle di Ammen.', },
  },
  [9313] = {
    'Viaggio al Presidio Azzurro',
    {'In nome di ciò che ti è più caro, $N, devi recarti immediatamente al Presidio Azzurro e parlare con Dyvuun!|n|nC\'è un sentiero che conduce a ovest, fuori da questa piccola isola. Seguilo e attraversa il Fiume Cristallacqua fino ad arrivare alla parte più grande dell\'isola. Prosegui lungo il sentiero e dovresti trovare il Presidio Azzurro.|n|nCerca di convincerli a inviarci aiuti e provviste. Noi cercheremo di raggiungerti non appena potremo.|n|nGrazie, non ce l\'avremmo mai fatta senza di te!', },
    {'Parla con il Tecnico Dyvuun al Presidio Azzurro sull\'Isola Brumazzurra.', },
  },
  [9314] = {
    'Un messaggio dal Presidio Azzurro',
    {'$C! Delle bestie mutate mi hanno assalito, ferendomi a una gamba.|n|nIl Presidio Azzurro mi aveva mandato in missione esplorativa dopo aver ricevuto un messaggio da Zhanaa. Potresti andare a parlare con l\'assistente Chellan al posto mio? Deve sapere quante persone aspettarsi al Presidio Azzurro. Attraversa il Fiume Cristallacqua e prosegui lungo la strada fino a raggiungere il Presidio Azzurro.|n|nRicordati di chiederle un posto anche per te.', },
    {'Parla con l\'Assistente Chellan al Presidio Azzurro sull\'Isola Brumazzurra.', },
  },
  [9315] = {
    nil,
    nil,
    {'Uccidi Anok\'suten e torna dall\'Arcanista Vandril a Tranquillien nelle Terre Spettrali.', },
  },
  [9318] = {
    'Olio Magico Benedetto',
    nil,
    nil,
  },
  [9319] = {
    'Una luce nell\'oscurità',
    {'$N, Non siamo solo noi a celebrare questa festa. Tutte le creature e tutte le culture sono toccate dalla fiamma. Anche nei luoghi più bui, vengono accesi i fuochi.|n|nSe vuoi vederli di persona, addentrati nelle profondità. Cerca i falò che bruciano a Stratholme, Scholomance, fra gli Ogre di Maglio Infausto e nelle sale dei Bastioni di Roccianera. Io attenderò qui il tuo ritorno.', },
    {'Cerca e tocca i Falò nei Bastioni di Roccianera, nel Maglio Infausto, a Scholomance e Stratholme. Poi, torna <dal/dalla> Guardafiamme della Celebrazione.', },
  },
  [9320] = {
    'Pozione Eccellente di Mana',
    nil,
    nil,
  },
  [9321] = {
    'Pozione Eccellente di Cura',
    nil,
    nil,
  },
  [9322] = {
    'Fuochi selvaggi a Kalimdor',
    {'I Fuochi di Mezza Estate vengono celebrati in tutta Azeroth... e l\'inconsueta regione di Kalimdor non fa eccezione. Sembri in grado di affrontare un viaggio... forse persino un avventura.|n|nNon puoi apprezzare appieno la Mezza Estate, se non hai ammirato i fuochi blu all\'estero. I falò sono stati accesi nella gelida Fontefredda a ovest, nella nordorientale Azshara, vicino all\'Asilo dei Valorosi nelle distese di Silitus e vicino all\'entrata della lussureggiante Un\'Goro. Quando avrai finito di viaggiare, torna qui da me.', },
    {'Visita gli Accampamenti dei Fuochi di Mezza Estate ad Azshara, a Silitus, nel Cratere di Un\'Goro e a Fontefredda. Poi, torna <dal/dalla> Guardafiamme della Celebrazione.', },
  },
  [9323] = {
    'Fuochi selvaggi nei Regni Orientali',
    {'$C, il fuoco viene festeggiato su tutta la regione. Non c\'è posto che non venga toccato da calore della festa. I falò più forti sono quelli blu. Va\' a cercarli.|n|nNe troverai subito uno a nord dei Bastioni di Roccianera. Gli altri si trovano vicino a una città decrepita all\'interno delle Terre Infette Orientali, lungo la strada per le scogliere nelle montagnose Entroterre e sulla via per il Portale Oscuro delle Terre Devastate.|n|nAlla fine del viaggio, torna qui da me.', },
    {'Visita gli Accampamenti dei Fuochi di Mezza Estate nelle Terre Devastate, nelle Terre Infette Orientali, nelle Entroterre e nella Gorgia Rovente. Poi, parla con <il/la> Guardafiamme della Celebrazione.', },
  },
  [9324] = {
    'Il furto della Fiamma di Orgrimmar',
    {'<Questa fiamma, rubata nel cuore stesso di Orgrimmar, ti inonda di calore. Il suo potere grezzo ti è sconosciuto, ma lo Storico potrebbe saperne di più...>', },
    {'Porta la Fiamma di Orgrimmar allo Storico di Mezza Estate.', },
  },
  [9325] = {
    'Il furto della Fiamma di Picco del Tuono',
    {'<Questa fiamma, rubata allo Sciamano di Picco del Tuono, ti inonda di calore. Il suo potere grezzo ti è sconosciuto, ma lo Storico potrebbe saperne di più...>', },
    {'Porta la Fiamma di Picco del Tuono allo Storico di Mezza Estate.', },
  },
  [9326] = {
    'Il furto della Fiamma di Sepulcra',
    {'<Questa fiamma, rubata fra le rovine sopra Sepulcra, ti inonda di calore. Il suo potere grezzo ti è sconosciuto, ma lo Storico potrebbe saperne di più...>', },
    {'Porta la Fiamma di Sepulcra allo Storico di Mezza Estate.', },
  },
  [9327] = {
    'I Reietti',
    {'So che può sembrare strano, ma questi Reietti sono qui per aiutarci. Dovresti parlare con il loro capo, il Gran Esecutore Mavren. Si trova all\'interno della torre nella parte occidentale del villaggio.|n|n$C, quando hai finito di parlare con lui torna da me. C\'è una faccenda della massima urgenza della quale dobbiamo occuparci!', },
    {'Parla con il Gran Esecutore Mavren a Tranquillien nelle Terre Spettrali.', },
  },
  [9328] = {
    'Eroe dei Sin\'dorei',
    {'È l\'inizio di un nuovo capitolo nella storia della nostra razza, $N. Riavremo le nostre terre e consolideremo il legame con Sylvanas e i suoi alleati.|n|nPorta la testa del traditore al Reggente Lor\'themar Theron a Lunargenta. Sarà ansioso di udire le novità.', },
    {'Porta la Testa di Dar\'khan a Lor\'themar Theron a Lunargenta.', },
  },
  [9329] = {
    'I Reietti',
    {'So che può sembrare strano, ma i Reietti sono qui per aiutarci. Dovresti parlare con il loro capo, il Gran Esecutore Mavren. Si trova all\'interno della torre nella parte occidentale del villaggio.|n|n$C, quando hai finito di parlare con lui torna da me. C\'è una faccenda della massima urgenza della quale dobbiamo occuparci!', },
    {'Parla con il Gran Esecutore Mavren a Tranquillien nelle Terre Spettrali.', },
  },
  [9330] = {
