    nil,
  },
  [10464] = {
    'Il giuramento del Saggio',
    {'$C, hai confermato il tuo impegno. Ora sta a te tradurlo in pratica.|n|nServi bene le Scaglie delle Sabbie e sarai ben $Gricompensato:ricompensata;.|n|nFallisci e la linea temporale che conosciamo verrà distrutta!', },
    {'Porta la tua Vera dell\'Eternità a Soridormi nelle Caverne del Tempo dopo aver acquisito la reputazione Onorato con le Scaglie delle Sabbie.', },
  },
  [10465] = {
    'Il giuramento del Curatore',
    {'$C, hai confermato il tuo impegno. Ora sta a te tradurlo in pratica.|n|nServi bene le Scaglie delle Sabbie e sarai ben $Gricompensato:ricompensata;.|n|nFallisci e la linea temporale che conosciamo verrà distrutta!', },
