  [10475] = {
    'Il patto del Difensore',
    {'$N, le tue imprese sono andate al di là delle mie aspettative.|n|nTi muovi tra le pieghe del tempo con la familiarità di un Drago Bronzeo. Sei $Gdestinato:destinata; a ottenere grandi poteri e io sono più che lieta di aiutarti.|n|nContinua a servire le Scaglie delle Sabbie e io ti aiuterò a realizzare il tuo potenziale.', },
    {'Porta la tua Vera dell\'Eternità a Soridormi nelle Caverne del Tempo dopo aver acquisito la reputazione Osannato con le Scaglie delle Sabbie.', },
  },
  [10476] = {
    'Nemici feroci',
    {'Se vuoi dimostrarci la tua lealtà, non c\'è modo migliore di combattere contro i nostri nemici.|n|nTra di essi, nessuno è forte e feroce come gli Ogre. Portami gli amuleti di guerra che indossano come prova della loro morte e farò conoscere a tutti la tua abilità.', },
    {'Il Custode Moi\'bff Jill a Telaar ti ha chiesto di recuperare 10 Amuleti di Guerra d\'Ossidiana agli Ogre che popolano Nagrand.', },
  },
  [10477] = {
    'Altri amuleti di guerra',
    nil,
    nil,
  },
  [10478] = {
    'Altri amuleti di guerra!',
    nil,
    nil,
  },
  [10479] = {
    'Prova di forza',
    {'Anche se cerchiamo di vivere pacificamente, abbiamo molti nemici. Nessuno di loro, però, è in grado di rivaleggiare con la forza bruta degli Ogre.|n|nSe vuoi dimostrarci la tua abilità, portami gli amuleti di guerra che indossano. Racconterò agli altri delle tue gesta.', },
    {'Il Custode Bulrok a Garadar ti ha chiesto di recuperare 10 Amuleti di Guerra d\'Ossidiana dagli Ogre che popolano Nagrand.', },
  },
  [10480] = {
    'La rabbia degli spiriti dell\'acqua',
    nil,
    nil,
  },
  [10481] = {
    'La rabbia degli spiriti dell\'aria',
    {'Avventurati a sud-est. Quando troverai dei campi con cristalli blu giganti che spuntano dalla terra, avrai raggiunto la tua destinazione. È là, nei Campi degli Alafatua, che troverai gli spiriti dell\'aria infuriati. Si aggirano sulle rupi e alla base delle montagne che circondano i campi.|n|nDistruggi le loro forme tormentate e cattura le loro anime con il Totem degli Spiriti. Torna da me quando avrai finito.', },
    {'Il Curaterra Torlok all\'Altare della Dannazione nella Valle di Torvaluna ti ha chiesto di usare il Totem degli Spiriti per catturare 10 Anime Ariose.', },
  },
  [10482] = {
    'Raccattatori Vilorchi',
    {'I Raccattatori, Orchi appartenenti al Clan Tritaossa, sono appostati fra i merli fortificati in rovina lungo il Cammino della Gloria. Presumiamo che stiano recuperando parti di macchine da guerra per i loro padroni nella Cittadella del Fuoco Infernale e dobbiamo fermarli!|n|n$N, gli Orchi Tritaossa si trovano a nord: cercali e uccidili! Ma agisci con cautela. Sebbene appartengano al Clan orchesco meno importante, la loro forza non ha nulla da invidiare a quella degli Orchi verdi che abbiamo incontrato finora.', },
    {'Uccidi 20 Orchi Tritaossa, poi torna da Amadi nella Rocca dell\'Onore.', },
  },
  [10483] = {
    'Presagi funesti',
    {'$N, combattendo contro il Clan di Vilorchi dei Guerci Insanguinati, abbiamo scoperto qualcosa sul loro conto. Hanno raccolto i Fregi dei soldati della Rocca dell\'Onore caduti e li hanno usati per creare dei Talismani Maledetti. Temiamo che la magia oscura dei Guerci Insanguinati abbia trasformato i nostri Fregi in potenti amuleti malvagi da usare contro di noi!|n|nPrendine uno agli Orchi Guerci Insanguinati di Zeth\'gor, a est, e portalo al Caporale Crestaferro al Presidio della Spedizione, a nord-est di Zeth\'gor.', },
    {'Il Tenente Amadi nella Rocca dell\'Onore ti ha chiesto di portare un Talismano Maledetto al Caporale Crestaferro nel Presidio della Spedizione.', },
  },
  [10484] = {
    'Talismani Maledetti',
    {'$N, non possiamo permettere agli Orchi Guerci Insanguinati di possedere quei Talismani Maledetti! Devi portarceli, così potremo distruggerli e onorare il sacrificio dei soldati che li possedevano.|n|nVa\' a Zeth\'gor, il Bivacco maledetto dei Guerci Insanguinati, e compi la tua ingrata missione. Quando avrai raccolto i Talismani, torna da me.', },
    {'Porta 12 Talismani Maledetti al Caporale Crestaferro nel Presidio della Spedizione.', },
  },
  [10485] = {
    'Il Signore della Guerra dei Guerci Insanguinati',
    {'Sopravvivendo a Zeth\'gor, hai dimostrato di possedere un\'incredibile forza... e una fortuna altrettanto formidabile. Speriamo non ti abbandoni proprio ora, poiché ho un compito molto gravoso da assegnarti.|n|nIl Signore della Guerra Morkh comanda le sue Viltruppe dall\'interno delle Caserme di Zeth\'gor. Le sue tattiche sono tanto astute quanto crudeli. Devo ammettere che abbiamo subito notevolmente i suoi successi. Per questo motivo, $N, ti chiedo di abbatterlo. Portami la sua corazza: la mostreremo ai nostri soldati per spronarli.', },
    {'Porta la Corazza Infranta di Morkh al Caporale Crestaferro nel Presidio della Spedizione.', },
  },
  [10486] = {
    'Invasione selvaggia',
    {'Un tempo, prima di essere trasformati in Vilorchi tramite il sangue di Mannoroth, gli Spaccatuono costituivano un glorioso clan di Orchi.|n|nDi recente siamo riusciti a recuperare questa roccaforte degli Orchi dagli Ogre che infestano la gola. L\'avevano occupata quando il Clan Spaccatuono l\'aveva abbandonata.|n|nNoi intendiamo mantenere il controllo di questo posto e vorremmo che tu ci aiutassi a farlo.|n|nNella Cresta Frastagliata a sud e a ovest gli Oratori del Sangue cominciano a impensierirci. Mangiano e si riproducono senza sosta.|n|nUccidili e poi torna da me.', },
    nil,
  },
  [10487] = {
    'Polvere dai drachi',
    {'Di recente l\'Alleanza si è spostata a ovest dove, utilizzando la magia elfica, ha costruito un villaggio e fatto crescere un bosco in un brevissimo periodo. Dobbiamo mantenere deboli le loro difese, prima che diventino inattaccabili.|n|nOra, io ho un piano per ottenere questo e altro. Vorrei che superassi il ponte che a sud-ovest attraversa la Gola dei Magliorosso e conduce alla Selva Vivente.|n|nAttacca i Drachi Fatati a difesa della Selva Vivente e riporta la polvere magica che a volte ricopre le loro ali.', },
    nil,
  },
  [10488] = {
    'Rafforzare le difese',
    {'Grazie alla polvere magica che hai recuperato, ho realizzato un unguento magico in grado di rinforzare le nostre difese.|n|nI nostri Metalupi uniscono in sé le doti e le funzioni di cavalcature, sentinelle e amici. Purtroppo la perfida Alleanza ha iniziato a cacciarli nella Cresta Frastagliata.|n|n$N, desidero che prendi questo unguento e lo spalmi sui nostri amici Metalupi. Alla prossima battuta di caccia, l\'Alleanza riceverà una brutta sorpresa.|n|nFai attenzione, però: alcuni Metalupi potrebbero non gradire l\'unguento e rivoltarsi contro di te.', },
    nil,
  },
  [10489] = {
    'Abbattere un Antico',
    nil,
    nil,
  },
  [10498] = {
    'Tenere il meglio per ultimo',
    nil,
    nil,
  },
  [10499] = {
    'Tenere il meglio per ultimo',
    nil,
    nil,
  },
  [10500] = {
    'L\'Orda ha bisogno del tuo aiuto!',
    {'Salve. Sono lieto che tu abbia deciso di sentire ciò che ho da dirti. L\'Orda ha bisogno di tutto l\'aiuto possibile per prepararsi al meglio alla guerra di Ahn\'qiraj e questo significa che ha bisogno anche del tuo aiuto! Mentre parliamo, alcuni incaricati stanno supervisionando la raccolta delle scorte necessarie per l\'imminente scontro, ma senza il tuo aiuto, $N, non raggiungeremo mai le quote che ci eravamo prefissati!|n|nPerché non vai a parlare con il Signore della Guerra Gorchuk, che è a capo di tutta l\'operazione? Che ne dici, $C? Ci aiuterai a prepararci al meglio?', },
    {'Parla con il Signore della Guerra Gorchuk della Valle degli Spiriti a Orgrimmar.', },
  },
  [10501] = {
    'L\'Alleanza ha bisogno del tuo aiuto!',
    {'Salve. Sono lieto che tu abbia deciso di sentire ciò che ho da dirti. L\'Alleanza ha bisogno di tutto l\'aiuto possibile per prepararsi al meglio alla guerra di Ahn\'qiraj e questo significa che ha bisogno anche di te! Mentre parliamo, alcuni incaricati stanno supervisionando la raccolta delle scorte necessarie per l\'imminente conflitto, ma senza il tuo aiuto non raggiungeremo mai le quote che ci eravamo prefissati!|n|nPerché non vai a parlare con il Primo Maresciallo Nevealta, che è a capo di tutta l\'operazione? Che ne dici, $C? Ci aiuterai a prepararci al meglio?', },
    {'Parla con il Primo Maresciallo Nevealta della Guardia Militare di Forgiardente.', },
  },
  [10502] = {
    'Gli Ogre Magliorosso',
    {'Una minaccia attanaglia Sylvanaar, ancora più letale dell\'Orda stanziata nella Roccaforte degli Spaccatuono.|n|nParlo degli Ogre nativi di queste montagne. A sud-est, giù per la gola, vive il Clan Magliorosso. Non sono l\'unico gruppo locale di Ogre che ci minaccia, ma sono i più vicini.|n|nVorrei che attraversassi la Selva Vivente a sud e poi seguissi il sentiero a est che conduce al loro avamposto. Uccidi quanti più Ogre Magliorosso possibili all\'Avamposto dei Magliorosso.', },
    nil,
  },
  [10503] = {
    'La minaccia dei Lamacurva',
    {'La Roccaforte degli Spaccatuono è vittima di una minaccia più pericolosa persino dell\'Alleanza a Sylvanaar.|n|nMi riferisco agli Ogre di queste montagne. A ovest, giù per la gola, vive il Clan Lamacurva. Non sono gli unici Ogre della zona, ma sono i più vicini e soprattutto sono quelli che abbiamo sconfitto per insediarci qui.|n|nDirigiti a nord oltre la Cresta Frastagliata, quindi segui il sentiero che conduce alla Rocca dei Lamacurva. Lì e nei Terreni dei Lamacurva uccidi quanti più Ogre Lamacurva possibili, insieme ai loro raptor.', },
    nil,
  },
  [10504] = {
    'Gli Ogre Lamacurva',
    {'A nord del Clan Magliorosso si erge una minaccia ancora più grave: la Rocca dei Lamacurva.|n|nGli Ogre Lamacurva sono i più forti di tutta la regione e godono del favore del Gronn noto come Gruul l\'Ammazzadraghi e dei suoi sette figli.|n|nDecimati i Magliorosso, credo sia ora di rivolgere la nostra attenzione ai loro rivali.|n|nDall\'Avamposto dei Magliorosso dirigiti a nord attraversando la gola finché non giungi alla Rocca dei Lamacurva e ai Terreni dei Lamacurva. Uccidi quanti più Ogre Lamacurva possibili.', },
    nil,
  },
  [10505] = {
    'Gli Ogre Magliorosso',
    {'A sud del Clan Lamacurva si trova un\'altra minaccia: l\'Avamposto dei Magliorosso.|n|nAnche se gli Ogre Magliorosso non sono i più forti della regione in quanto non godono dei favori del Gronn noto come Gruul l\'Ammazzadraghi, non sono però da sottovalutare.|n|nNeutralizzati i Lamacurva, è tempo di puntare la nostra attenzione sui loro rivali.|n|nDalla Rocca dei Lamacurva dirigiti a sud attraversando la gola finché non arriverai all\'Avamposto dei Magliorosso. Uccidi tutti gli Ogre Magliorosso che trovi nelle vicinanze.', },
    nil,
  },
  [10506] = {
    'Una situazione terribile',
    {'L\'Orda sta cercando di rinfoltire il suo branco di lupi e purtroppo non deve cercare molto lontano.|n|nGli Ogre Magliorosso della gola in basso a est si servono di un branco numeroso per difendere il proprio territorio. Non mi ha fatto piacere incaricarti dell\'uccisione dei lupi degli Spaccatuono, quindi perché stavolta non proviamo qualcosa di diverso?|n|nDalla polvere che cade dalle ali dei nostri drachi ho ricavato una polvere magica. Spargila sui Metalupi Magliorosso per renderli indesiderabili all\'Orda.', },
    nil,
  },
  [10507] = {
    'Punto di svolta',
    {'È l\'occasione che aspettavamo, $N. Non solo abbiamo trovato le prove necessarie a rivelare chi sono i veri padroni di Kael\'thas, ma possiamo anche dimostrare la nostra forza sconfiggendoli.|n|nLa mia salute cagionevole m\'impedisce di aiutarti di persona, ma ti offro un oggetto che mi permetterà di proiettare i miei poteri dall\'altra parte del continente.', },
    {'Usa la Pietra del Teletrasporto di Socrethar al Portale di Invasione: Angoscia, a nord della Fornace Oblio, per trasportare il tuo gruppo all\'Approdo di Socrethar. Una volta là, usa la Presenza di Voren\'thal per sconfiggere Socrethar.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10508] = {
    'Un dono per Voren\'thal',
    {'Non voglio mandarti da Voren\'thal a mani vuote. Stupire è la cosa che so fare meglio.|n|nPer avere accesso al Trono di Socrethar a nord, dobbiamo usare i suoi teletrasporti... bloccati con la pietra del teletrasporto di Socrethar. La prima metà della pietra è in mano al Mastro Forgiatore Morug alla Fornace Oblio. Silroth alla Fornace Gehenna possiede la seconda metà.|n|nEntrane in possesso e lascerai senza parole Voren\'thal.', },
    {'Il Maestro di Spionaggio Thalodien all\'Area 52 ti ha chiesto di recuperare la Prima Metà della Pietra di Socrethar dal Maestro Forgiatore Morug alla Fornace Oblio e la Seconda Metà della Pietra di Socrethar da Silroth alla Fornace Gehenna.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10509] = {
    'Chi fa da sé, fa per tre!',
    {'Ora posso rimandarti a Shattrath in modo appropriato. Hai scoperto la prova che Kael\'thas stringe patti con la Legione Infuocata e hai la chiave per la porta sul retro del Supremo.|n|nAssicurati che Voren\'thal non cada per l\'emozione. Il vecchio comincia a essere fragile, se capisci cosa intendo. Lo troverai nella Biblioteca dei Veggenti alla Loggia dei Veggenti.', },
    {'Porta la Pietra del Teletrasporto di Socrethar a Voren\'thal il Veggente nella Loggia dei Veggenti a Shattrath.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10510] = {
    'Nella Miniera di Draenetista',
    {'Bene, fa molto piacere vedere qualcuno disposto a dare una mano!|n|nBorgrim e io facciamo parte della Lega degli Esploratori e siamo qui per scoprire tutto il possibile su questa zona montuosa. Abbiamo sentito ogni genere di storie e non vedo l\'ora di iniziare.|n|nUna cosa in particolare ha attratto la mia attenzione: gli Elfi della Notte parlano di un posto, giù nella gola a est, noto come Miniera di Draenetista. Si trova all\'estremità meridionale dell\'Avamposto dei Magliorosso. Mi piacerebbe entrare in possesso di alcuni dei cristalli che crescono spontaneamente lì.', },
    nil,
  },
  [10511] = {
    'Miscugli e intrugli',
    {'Se devo cominciare questa vacanza col piede giusto, allora quello che mi serve è della birra. Purtroppo gli Elfi ignorano del tutto l\'arte della fermentazione.|n|nHo però sentito che gli Ogre Magliorosso giù nella gola sono degli esperti. Ho voglia di provare la loro birra.|n|nMi fai un piacere? Attraversa la Selva Vivente a sud, poi scendi per il sentiero a est fino all\'Avamposto dei Magliorosso e procuramene qualche barile... ho sentito che in giro ce ne sono di belli grossi e che i loro mastri birrai li portano in giro per consegnarli agli altri Ogre.', },
    nil,
  },
  [10512] = {
    'Come far ubriacare i Lamacurva',
    {'Non berrò un sorso di più di quella brodaglia disgustosa! Però mi è venuta un\'idea.|n|n<A Borgrim brillano gli occhi.>|n|nEcco il mio piano: sappiamo che i Magliorosso praticamente vivono di questa schifezza, ma chissà cosa ne pensano i loro nemici, gli Ogre Lamacurva...|n|n$N, voglio che prendi il resto di questa porcheria e lo porti ai Lamacurva per vedere se riusciamo a farli ubriacare. Per trovarli, dirigiti a nord dell\'Avamposto dei Magliorosso attraversando la gola.', },
    nil,
  },
  [10513] = {
    'Oronok Cuorespino',
    nil,
    nil,
  },
  [10514] = {
    'Sono stato tante cose...',
    {'Sono stato tante cose, ma non è importante ciò che ero. Ciò che sono adesso è quello che importa. E ora sono un contadino.|n|nAddestravo Vilcinghiali per trovare tuberi sotto la dura terra delle Pianure Pietrose. Recentemente, però, alcuni Scorticatori che hanno il nido a nord-est hanno attaccato i miei animali, fermando la raccolta.|n|nTi spiacerebbe andare nell\'area a nord a raccogliere i tuberi per me? Usa questo fischietto quando ti trovi su un Bozzo di Tuberi e un cinghiale arriverà a dissotterrarli!', },
    {'Oronok Cuorespino alla Fattoria di Oronok nella Valle di Torvaluna ti ha chiesto di recuperare 10 Tuberi di Torvaluna nelle Pianure Pietrose.|n|nTi ha anche chiesto di restituirgli il Fischietto per Cinghiali di Oronok quando avrai finito.', },
  },
  [10515] = {
    'Lezione appresa',
    {'Dobbiamo mostrare a quegli Scorticatori cosa succede quando intralci Oronok!|n|nVoglio che torni sulle Pianure Pietrose e che tu distrugga ogni uovo di Scorticatore che trovi. Tieni gli occhi aperti, perché saranno in pieno territorio degli Scorticatori.', },
    {'Oronok Cuorespino alla Fattoria di Oronok nella Valle di Torvaluna ti ha chiesto di distruggere 10 Uova di Scorticatore Vorace sulle Pianure Pietrose.', },
  },
  [10516] = {
    'Ornamenti di una Vendicatrice',
    {'So che può sembrare strano, ma io voglio restare in questa gabbia: mi mette nelle condizioni ideali per fare ciò che sono venuta a fare, ossia raccogliere informazioni sui Lamacurva.|n|nPosso andarmene in qualsiasi momento, ma voglio riavere indietro la mia spada e il mio scudo.|n|nI miei ornamenti sono in possesso di due dei loro capi. Droggam ha la mia spada e Mugdorg il mio scudo.|n|nPotresti anche usare la birra dell\'Avamposto dei Magliorosso a sud per ridurre il numero dei rinforzi e anche per adescare quei due... ma fai attenzione alle loro guardie astemie!', },
    nil,
  },
  [10517] = {
    'Gorr\'dim, la tua ora è giunta...',
    {'Il capo della Rocca dei Lamacurva si chiama Gorr\'dim. Fidati... è brutto quanto il suo nome.|n|nTuttavia, è bene non sottovalutarlo: è stato abbastanza ingegnoso da elevare il proprio clan al rango di favorito presso Gruul l\'Ammazzadraghi e difatti ora sono i Lamacurva a dominare questa zona. Gorr\'dim è sempre circondato dai suoi uomini, tra cui delle guardie del corpo che hanno giurato di restare astemie.|n|nPer la sicurezza di Sylvanaar, devo chiederti di tornare lì e sbarazzarti di lui.', },
    nil,
  },
  [10518] = {
    'Lo stendardo della discordia',
    {'Voglio che rubi lo Stendardo dei Lamacurva a uno dei loro campioni e che lo porti a sud, all\'Avamposto dei Magliorosso, per piantarlo in cima alla Torre Maglio del Nord.|n|nI Magliorosso, infuriati, prenderanno ad attaccarti, concentrando così la loro furia sulla Rocca dei Lamacurva, lontano da Sylvanaar.|n|nLa tua missione sarà compiuta dopo che avrai sconfitto Gurn Grubnosh e gli avrai sottratto l\'elmo, che dovrai riportare a Sylvanaar.|n|nNon sarà facile. Ti consiglio di avventurarti con un paio di amici.', },
    nil,
  },
  [10519] = {
    'Il Cifrario della Dannazione: verità e storia',
    nil,
    {'Oronok Cuorespino alla Fattoria di Oronok nella Valle di Torvaluna ti ha chiesto di ascoltare la sua storia. Parla con Oronok perché inizi a raccontartela.', },
  },
  [10521] = {
    'Grom\'tor, Figlio di Oronok',
    {'Il mio primogenito, Grom\'tor, è partito per perquisire il Presidio dei Malaspira, a sud-ovest.|n|nÈ il guerriero della famiglia, con un pessimo carattere e assetato di sangue... Ha preso da sua madre. Cerca nei dintorni del Presidio dei Malaspira. Se vedi cadaveri di Naga, Grom\'tor sarà sicuramente vicino.|n|nQuando lo troverai, digli questo: "Verseremo sangue per una giusta causa". In questo modo capirà che sei $Gamico:amica; dei Cuorespino e non morirai prematuramente.', },
    {'Trova Grom\'tor, Figlio di Oronok al Presidio dei Malaspira nella Valle di Torvaluna.', },
  },
  [10522] = {
    'Il Cifrario della Dannazione: la missione di Grom\'tor',
    {'Questo rifiuto naga è il sesto che interrogo oggi. Aveva una bella armatura, così ho pensato che sapesse qualcosa. Gli altri si sono rivelati inutili.|n|n<Grom\'tor indica i cadaveri di Naga che lo circondano.>|n|nÈ bastato che lo colpissi una volta perché mi dicesse tutto.|n|nLa prima parte del Cifrario è nascosta in un forziere dei Naga al Presidio dei Malaspira o alla Cisterna dei Malaspira, a est. Dice che i Naga hanno le chiavi. Uccidili, prendi le chiavi e usale per aprire i forzieri dei Malaspira. Torna da me quando avrai trovato il Cifrario.', },
    {'Grom\'tor, Figlio di Oronok al Presidio dei Malaspira nella Valle di Torvaluna, ti ha chiesto di recuperare il Primo Frammento del Cifrario della Dannazione.', },
  },
  [10523] = {
    'Il Cifrario della Dannazione: primo frammento recuperato',
    {'<Grom\'tor arrotola i documenti e li chiude in uno scrigno.>|n|nPorta questo scrigno a mio padre. Attende il tuo ritorno alla fattoria, a nord-est.|n|nDigli che tornerò presto. Appena avrò finito di divertirmi...', },
    {'Porta lo Scrigno di Grom\'tor a Oronok Cuorespino alla Fattoria di Oronok nella Valle di Torvaluna.', },
  },
  [10524] = {
    'Manufatti del Clan Spaccatuono',
    {'<Dai segni del manufatto è chiaro che provengono dagli Orchi del Clan Spaccatuono. Prima di essere trasformati in Vilorchi, essi abitavano nella Roccaforte degli Spaccatuono.>|n|n<La Roccaforte per un certo periodo è stata utilizzata dagli Ogre Lamacurva, finché l\'Orda non è riuscita a scacciarli.>|n|n<Hai sentito parlare di altri manufatti perduti e ti vengono subito in mente, tra gli oggetti più ricercati, un tamburo, una freccia e una tavoletta.>|n|n<Decidi di cercarli nella Rocca dei Lamacurva e riportarli a Rokgah Spillasangue.>', },
    nil,
  },
  [10525] = {
    'Visione guida',
    nil,
    nil,
  },
  [10526] = {
    'La Thunderspike',
    {'Se la tua visione è vera, allora devi recarti giù nella gola e poi all\'estremità meridionale della Gola dei Magliorosso. Lì troverai la Miniera di Draenetista.|n|nRaggiungi il fondo della miniera e recupera la Piccatuono. Ignora qualsiasi altra cosa! Non m\'interessano né i cristalli presenti nella miniera, né gli Ogre che vi troverai.|n|nTorna da me non appena avrai recuperato la lancia!|n|nE fai molta attenzione... Non voglio neanche pensare a cosa ti succederebbe nel caso la rompessi.', },
    nil,
  },
  [10527] = {
    'Ar\'tor, Figlio di Oronok',
    {'Il più giovane dei miei figli, Ar\'tor, è partito per perquisire il Presidio degli Illidari, a sud-ovest, tra la Roccaforte della Legione e la Roccaforte dei Granmartello.|n|nNonostante Ar\'tor sia un cacciatore piuttosto abile e un braccatore esperto, temo che questa volta si sia messo nei guai. Il Presidio degli Illidari è il campo di prova per i demoni di Illidan. Sono demoni che hanno abbandonato la Legione Infuocata e si sono uniti al Traditore!|n|n$N, vai al Presidio degli Illidari e trova Ar\'tor.', },
    {'Trova Ar\'tor, Figlio di Oronok al Presidio degli Illidari nella Valle di Torvaluna.', },
  },
  [10528] = {
    'La prigione di cristalli demoniaci',
    {'<Osservando la scena, noti che Ar\'tor è bloccato da raggi d\'energia emanati dai cristalli che fluttuano intorno alla runa. Per quanto provi, non riesci a spostarlo.>|n|n<Noti che alla base dei cristalli c\'è un incavo vuoto, forse per una chiave. Sembra anche che le Succubi eseguano regolarmente una sorta di rituale.>|n|n<Cerca il capo del Presidio degli Illidari. Forse lei ha la chiave necessaria a liberare Ar\'tor.>', },
    {'Trova e uccidi la Signora del Dolore Gabrissa al Presidio degli Illidari e libera il cadavere di Ar\'tor, Figlio di Oronok, con la Chiave Cristallina.', },
  },
  [10531] = {
    'La battaglia per il Bacino d\'Arathi!',
    {'$N, la battaglia per il Bacino d\'Arathi è uno scontro per il territorio e le sue risorse. Per fornire alle nostre forze le necessarie scorte e materie prime, occorre controllare dei punti chiave. Per ora il tuo incarico consiste nell\'assaltare i punti più lontani dalla nostra base nel Bacino d\'Arathi.|n|nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllati dai nemici. Cerca lo stendardo nemico e strappalo dalla sua asta!|n|nQuando lo avrai fatto in tutti e quattro i posti, torna da me.', },
    {'Assalta la Miniera, la Segheria, la Fucina e la Fattoria, quindi torna dal Primo Maresciallo Oslight al Fosso dei Rifugiati.', },
  },
  [10537] = {
    'Lohn\'goron, Arco dei Cuorespino',
    {'È un segno, $N. Non posso essere fermato nemmeno dalla morte. Recuperare un frammento del Cifrario della Dannazione è il mio destino. Un destino che, con il tuo aiuto, sarà compiuto.|n|nPrima di iniziare il viaggio, mi serve il mio arco lungo, Lohn\'goron. È un cimelio di famiglia tramandato da Cuorespino a Cuorespino per generazioni.|n|nIl mio istinto mi dice che un demone l\'ha rubato dal mio cadavere. Uccidi i demoni che incontri qui finché non l\'avrai recuperato.', },
    {'Lo Spirito di Ar\'tor al Presidio degli Illidari nella Valle di Torvaluna ti ha chiesto di recuperare Lohn\'goron, Arco dei Cuorespino, dai demoni dell\'area.', },
  },
  [10538] = {
    'Sangue bollente',
    nil,
    {'Usa il Sangue dei Guerci Insanguinati nel Calderone Maledetto per ottenere del Sangue Bollito. Portane 12 Ampolle allo Speziale Albreck nel Presidio di Frangiguglia.', },
  },
  [10540] = {
    'Il Cifrario della Dannazione: la missione di Ar\'tor',
    {'Finalmente siamo pronti. Ti donerò un pezzo del mio spirito. Ti proteggerà e ti aiuterà nella battaglia contro il male.|n|nDevi andare a sud, verso il lato posteriore del Presidio degli Illidari. Nascosta nell\'etere, vi è una vile creatura nota come Veneratus il Molteplice. Il mio Spirito Cacciatore lo richiamerà quando sarà vicino.|n|nDistruggilo e prendi dal suo corpo il Secondo Frammento del Cifrario della Dannazione.', },
    {'Lo Spirito di Ar\'tor al Presidio degli Illidari nella Valle di Torvaluna ti ha chiesto di recuperare il Secondo Frammento del Cifrario della Dannazione da Veneratus il Molteplice.|n|nLe creature attaccate o ferite dallo Spirito Cacciatore non daranno bottino o esperienza.', },
  },
  [10541] = {
    'Il Cifrario della Dannazione: secondo frammento recuperato',
    nil,
    nil,
  },
  [10542] = {
    'La storia di T\'chali',
    {'T\'chali era nu bello Troll amichevole. Era venuto accà per insegnare ai Magliorosso come far fermentare la birra. Ma nun appena ha finito, i Magliorosso hanno sepolto T\'chali e l\'hanno lasciato accà a marcire!|n|nMa la parte peggiore di tutto chisto è che gli hanno rubato il Narghilè suo!|n|nAllora, vuoi aiutare T\'chali? Riportami il Narghilè. T\'chali pensa che li Ogre che gliel\'hanno rubato fossero diretti a sud-ovest, verso la miniera.|n|nGià che ci stai, piglia pure le birre!', },
    nil,
  },
  [10543] = {
    'Grimnok e Korgaah, la vendetta è servita',
    {'T\'chali nun ha fatto altro che aspettare il momento della vendetta sua!|n|nIl giorno in cui hanno seppellito T\'chali lasciandolo a schiattare, ci stava Grimnok Proleguerra a guidarli. E il giorno dopo fu Korgaah a venire a sud per saccheggiare e dare nu calcio in capa a T\'chali.|n|nLi voglio vedere schiattare!|n|nTroverai Grimnok in cima alla Torre Maglio del Sud, nell\'Avamposto dei Magliorosso. Korgaah, invece, sta in cima a nu edificio nell\'estremità settentrionale della Rocca dei Lamacurva. Korgaah tiene guardie del corpo astemie e non berranno, quindi dovrai usare la birra per fare allontanare isso da loro.', },
    nil,
  },
  [10544] = {
    'Maledire i clan',
    {'T\'chali vuole vendicarsi di tutti quanti li Ogre!|n|nIn vita, T\'chali era nu potente Taumaturgo. Se scavi nella tomba mia, troverai il Feticcio Potente e Terribile.|n|nInvoca la magia del feticcio presso li ingressi delli edifici e delle torri sia della Rocca dei Lamacurva, sia dell\'Avamposto dei Magliorosso. Chesta pratica vudù evocherà no Spirito maligno che dovrai sconfiggere. In chisto modo, l\'edificio sarà maledetto.|n|nFai attenzione, perché se provi a maledire nu edificio già maledetto, evocherai nu altro spirito maligno!', },
    nil,
  },
  [10545] = {
    'Il boccale dei Lamacurva',
    {'Come T\'chali ti stava dicendo, isso ha aiutato li amici Magliorosso suoi a produrre la birra loro. Ma T\'chali nun ti ha detto perché.|n|nI Magliorosso stanno in condizioni brutte assai. Il Clan Lamacurva li stava massacrando e i Magliorosso tenevano bisogno di n\'arma in più.|n|nA chello punto, a T\'chali è venuta na grande idea: perché nun creare la birra perfetta, na birra che rinforza te e indebolisce il nemico? Solo che T\'chali nun sa ancora se funziona.|n|nQuindi ti chiedo di portare chesta birra alla Rocca dei Lamacurva per vedere se funziona!', },
    nil,
  },
  [10546] = {
    'Borak Figlio di Oronok',
    {'Mentre Ar\'tor andava a caccia e Grom\'tor andava a combattere, Borak studiava. Alla fine, ha seguito la sua vocazione di studioso ed è partito per le terre selvagge di Draenor. Tornò qualche anno dopo totalmente cambiato.|n|nLa sua incredibile consapevolezza di quanto lo circondava e il suo acume lo avevano trasformato in un assassino silenzioso.|n|nOra, Orco potente e sicuro di sé, ha deciso di recuperare la parte più protetta del Cifrario.|n|nTrova Borak: si nasconde vicino al Presidio dell\'Eclisse, nel profondo sud. Osserva protetto dalle ombre del ponte.', },
    {'Trova Borak, Figlio di Oronok vicino al Presidio dell\'Eclisse nella Valle di Torvaluna.', },
  },
  [10547] = {
    'Cardisangue e uova...',
    {'Mi sarei arreso se non avessi notato questo... È drogato di cardi. Inizialmente non capivo, ma ci sono tutti i segni...|n|nSe riuscissimo a mettere le mani su del cardosangue, potremmo procedere.|n|nDurante i miei viaggi, ho incontrato un losco Corrotto a Shattrath, di nome Tobias.|n|nTobias si guadagnava da vivere scambiando, con gli Elfi del Sangue, Cardisangue con Uova di Arakkoa Marce.|n|nA ovest, ci sono delle rovine di Arakkoa. Cerca delle uova e poi vai alla Città Bassa di Shattrath. È lì che troverai Tobias.', },
    {'Borak, Figlio di Oronok, al ponte a nord del Presidio dell\'Eclisse, ti ha chiesto di trovare un Uovo di Arakkoa Marcio e di consegnarlo a Tobias il Mangiasporco a Shattrath, che si trova a nord-ovest della Foresta di Terokk.', },
  },
  [10549] = {
    'RIUSO',
    nil,
    nil,
  },
  [10550] = {
    'Il mucchio di cardosangue',
    nil,
    nil,
  },
  [10551] = {
    'Leale agli Aldor',
    nil,
    nil,
  },
  [10552] = {
    'Leale ai Veggenti',
    nil,
    nil,
  },
  [10553] = {
    'Voren\'thal il Veggente',
    {'Ora che hai scelto con chi schierarti, $N, dovresti incontrare il capo dei Veggenti.|n|nTroverai Voren\'thal il Veggente nella Biblioteca dei Veggenti alla Loggia dei Veggenti.|n|nScopri se puoi essergli d\'aiuto. Sarà felice di sapere che hai deciso di dar loro una mano.', },
    {'Parla con Voren\'thal il Veggente nella biblioteca della Loggia dei Veggenti a Shattrath.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10554] = {
    nil,
    {'Ora che hai deciso di schierarti con gli Aldor, farai meglio a presentarti al loro capo. Troverai la Gran Sacerdotessa Ishanah al Santuario della Luce Perpetua.', },
    {'Parla con Ishanah al Santuario della Luce Perpetua sul Poggio degli Aldor a Shattrath.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10556] = {
    nil,
    {'Dai simboli si capisce che occorre usare le piume per lanciare gli incantesimi presso i Cerchi del Potere di Vol Lashh.|n|nUn\'iconografia complessa sembra mostrare un Arakkoa in comunione con lo spirito di un Kaliri.', },
    nil,
  },
  [10557] = {
    'Volo di prova: Zephyrium Capacitorium',
    {'Ho costruito un macchinario stupefacente, lo Zephyrium Capacitorium, e sono anche certo che funzioni perfettamente, ma... potresti aiutarmi a provarlo?|n|nLe indennità per i rischi sono altissime!|n|nParla col mio gemello Rally. Buona fortuna, $N. Torna da me dopo l\'esperimento o, se non è possibile a causa del... concretizzarsi dei rischi, avvisa qualche tuo parente di venire a incassare l\'indennità.', },
    nil,
  },
  [10558] = {
    'Riveriti dalla Rocca dell\'Onore',
    {'$N, hai dimostrato il tuo valore e la dedizione alla nostra causa. Un giorno, una persona come te potrebbe diventare un gran capo.|n|nContinua a combattere contro i nemici nelle Sale della Devastazione per farti conoscere dai miei uomini. Se sarai all\'altezza delle aspettative, avrò missioni molto più importanti da affidarti.', },
    {'Il Comandante delle Forze Danath Cacciatroll alla Rocca dell\'Onore nella Penisola del Fuoco Infernale ti ha chiesto di ottenere la reputazione Riverito con la Rocca dell\'Onore, combattendo contro i Vilorchi nelle Sale della Devastazione della Cittadella del Fuoco Infernale.', },
  },
  [10560] = {
    'Il rispetto degli Sha\'tar',
    {'<I toni melodici e calmanti proiettati da A\'dal diventano più sommessi e sobri.>|n|n<Ti viene mostrata la grande struttura dei Naaru nota come Forte Tempesta. Ora è abitata dalle truppe di Kael\'thas e i suoi poteri sfruttati per fini nefasti. A\'dal ti promette imprese più grandiose una volta che avrai fatto la tua parte per riconquistare Forte Tempesta.>', },
    {'A\'dal a Shattrath ti ha chiesto di ottenere il rispetto degli Sha\'tar sconfiggendo le truppe di Kael\'thas dentro a Forte Tempesta.', },
  },
  [10561] = {
    'Riverito tra i Custodi del Tempo',
    {'$R, ci hai dimostrato il tuo valore, ma la linea temporale non è ancora al sicuro.|n|nAbbiamo bisogno di veri campioni e forse tu potresti diventarlo.|n|nContinua a proteggere gli eventi del passato dagli intrusi e acquisirai la fama che meriti.', },
    {'Andormu nelle Caverne del Tempo a Tanaris ti ha chiesto di ottenere la reputazione Riverito con i Custodi del Tempo continuando a proteggere gli eventi del Passato di Colletorto e della Palude Nera all\'interno delle Caverne del Tempo.', },
  },
  [10562] = {
    nil,
    {'Non abbassare la guardia, $R. Siamo sotto costante assalto della Legione Infuocata.|n|nI demoni inviano incessantemente Infernali dalla Roccaforte della Legione, a nord-ovest. Per quanto velocemente li uccidiamo, piombano qui nuove meteore e inizia un\'altra offensiva.|n|nI miei uomini sono malridotti ed esausti. Non so quanto resisteranno ancora. Ti prego, $N, aiutaci a difenderci. Prendi il tuo posto tra i ranghi e arresta l\'avanzata degli Infernali!', },
    {'Il Comandante di Squadriglia Nuainn, fuori dalla Roccaforte dei Granmartello, ti ha chiesto di uccidere 10 Attaccanti Infernali.', },
  },
  [10563] = {
    'Alla Roccaforte della Legione',
    nil,
    {'Entra nella Roccaforte della Legione e trova il Dispositivo di Comunicazione della Legione. Usa il travestimento mentre resti nei suoi pressi e scopri i piani della Legione. Una volta portata a termine la missione, torna dal Comandante di Squadriglia Nuainn alla Roccaforte dei Granmartello.', },
  },
  [10564] = {
    'Fai saltare gli Infernali!',
    {'Il dispositivo che abbiamo creato non vincerà una gara di bellezza, ma dovrebbe essere in grado di distruggere gli Infernali ammassati nella Roccaforte della Legione. A giudicare da come il nucleo energetico del Vilrazziatore ha ridotto la Pozza Fetida, dovrebbe avere ancora abbastanza potere detonante.|n|nSe farai saltare il dispositivo al centro del glifo verde nella roccaforte, l\'esplosione dovrebbe coinvolgere tutti gli Infernali.', },
    {'Usa la Vilbomba mentre ti trovi sul glifo verde nella Roccaforte della Legione e poi fai rapporto al Comandante di Squadriglia Nuainn alla Roccaforte dei Granmartello.', },
  },
  [10565] = {
    'Le Pietre Vekh\'nir',
    {'Gli Arakkoa Vekh\'nir sono per noi una spina nel fianco da molti anni, ormai. Seguono una strana religione che li vede impegnati tutti in una frenetica attività. Adesso portano tutti con sé dei cristalli che utilizzano per scopi oscuri.|n|nSo qualcosa dei loro rituali. Per esempio, portano i cristalli ai cerchi degli incantesimi per infondervi la magia. Ma noi qui al villaggio vorremmo saperne di più. Tendi degli agguati a qualche Arakkoa finché non recuperi un cristallo, poi caricalo e portamelo.', },
    nil,
  },
  [10566] = {
    'Tentativi ed errori',
    {'Ho realizzato quattro bacchette che credo siano in grado di potenziare i cristalli degli Arakkoa. Portale all\'Antro di Trogma e provale sugli Ogre schiavi.|n|nPrima, però, dovrai procurarti un cristallo infuso da un Arakkoa nell\'area.|n|nScopri quale bacchetta garantisce i risultati migliori, quindi torna da me.', },
    nil,
  },
  [10567] = {
    'La creazione del pendente',
    {'Gli Arakkoa del Bosco di Ruuan tengono in gran considerazione gli Alfieri del Corvo, ossia del loro dio.|n|nEssi credono che gli araldi li osservino e li proteggano dal cielo, dove ricevono gli insegnamenti del Corvo per poi trasmetterli alle creature ordinarie.|n|nGli araldi hanno molta influenza sulle anime degli Arakkoa. Essi utilizzano dei pendenti magici che ora servono anche a noi.|n|nAttira un araldo uccidendo le sue creature e strappando loro gli artigli. Per attirare la sua attenzione, colloca gli artigli sull\'altare.', },
    nil,
  },
  [10568] = {
    'Le Tavolette di Baa\'ri',
    {'Anni fa, il temuto Stregone noto come Gul\'dan fece eruttare il vulcano al centro di Torvaluna. Il villaggio draenei di Baa\'ri, a sud-ovest, fu sepolto dalla lava insieme agli abitanti e a manufatti di grande importanza religiosa.|n|nIllidan ha ordinato all\'infida tribù di Corrotti nota come Linguamorta di effettuare degli scavi nell\'area. Dobbiamo sfruttare quest\'opportunità per recuperare le Tavolette di Baa\'ri, un antico testo che si dice contenga i segreti di Karabor, ora noto come Tempio Nero.', },
    {'L\'Anacoreta Ceyla all\'Altare degli Sha\'tar ti ha chiesto di recuperare 12 Frammenti di Tavoletta di Baa\'ri negli scavi e ai Lavoratori Linguamorta nelle Rovine di Baa\'ri.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10569] = {
    'Le rovine di Sketh\'lon',
    {'I nostri esploratori ci hanno portato inquietanti notizie dagli accampamenti arakkoa nell\'area.|n|nI fantasmi di potenti Maghi arakkoa possiedono poteri che non pensavamo avessero. Sembra si stiano organizzando, come se si preparassero per qualcosa, ma non ne sappiamo molto. Non possiamo permetterci di ignorare le loro intenzioni!|n|nVai a nord, alle Rovine di Sketh\'lon, a nord-ovest di Forgiamorte e cerca di scoprire cosa intendono fare.', },
    {'Recupera la Pagina 1 del Diario del Comandante di Sketh\'lon, la Pagina 2 del Diario del Comandante di Sketh\'lon e la Pagina 3 del Diario del Comandante di Sketh\'lon dal Conclave Oscuro Arakkoa nelle Rovine di Sketh\'lon e portale al Cavaliere di Grifoni Kieran.', },
  },
  [10570] = {
    'Catturare una Testa di Cardo',
    {'<Borak prende il Mucchio di Cardosangue e lo annusa.>|n|nAcre...|n|nPrendi il mucchio e posizionalo all\'altra estremità del ponte. Quando l\'inviato farà il suo giro quotidiano, non potrà resistere e lo prenderà... senza la sua guardia del corpo. Gli Elfi del Sangue disprezzano chi mostra dipendenza dal cardosangue. Se qualcuno dei suoi compatrioti lo scoprisse...|n|nDevi solo aspettare che allontani la sua guardia. Quando sarà solo, attacca! Uccidilo e prendi la missiva.', },
    {'Borak, Figlio di Oronok, al ponte vicino al Presidio dell\'Eclisse nella Valle di Torvaluna, ti ha chiesto di recuperare la Lettera di Grantempesta.', },
  },
  [10571] = {
    'Oronu l\'Anziano',
    {'Secondo le tavolette, a Baa\'ri era conservato un manufatto conosciuto come Medaglione di Karabor. Questi oggetti venivano conferiti solo ai Sacerdoti draenei in cima alla gerarchia, poiché a loro era permesso l\'accesso senza restrizioni a Karabor.|n|nDobbiamo scoprire se i Linguamorta hanno recuperato il medaglione tenuto a Baa\'ri. Il suo potere ci sarebbe di grande aiuto nella lotta contro Illidan.|n|nAkama invia giornalmente ordini scritti al suo luogotenente a Baa\'ri, Oronu l\'Anziano. Prendili e portameli.', },
    {'L\'Anacoreta Ceyla all\'Altare degli Sha\'tar ti ha chiesto di recuperare gli Ordini di Akama a Oronu l\'Anziano nelle Rovine di Baa\'ri.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10572] = {
    'Piazzare la bomba',
    {'Non possiamo permettere alla Legione di mettere in atto il suo piano per distruggere la Roccaforte dei Granmartello mentre marciano sul Tempio Nero.|n|nC\'è solo un modo per fermarla, $N. Devi creare un esplosivo abbastanza potente da distruggere l\'intero arsenale di Infernali che la Legione tiene nella sua roccaforte.|n|nLa Pozza Fetida vicino alla Roccaforte della Legione contiene un vecchio nucleo energetico di Vilrazziatore che puoi usare come base per il tuo dispositivo. Cerca delle piastre rinforzate tra gli altri rottami vicino al Vilrazziatore: potremmo utilizzarle per creare un rivestimento.', },
    {'Trova un Nucleo Energetico del Vilrazziatore e una Piastra del Vilrazziatore e portali al Comandante di Squadriglia Nuainn alla Roccaforte dei Granmartello.', },
  },
  [10573] = {
    'Forgiamorte',
    {'Da quanto hai scoperto alla Roccaforte della Legione, sappiamo che gli alleati della Legione del Concilio dell\'Ombra producono Infernali a Forgiamorte. Ho inviato un piccolo gruppo di ricognizione per tenere d\'occhio l\'area, ma non sono in grado di fare tutto ciò di cui abbiamo bisogno.|n|nSe lasciamo Forgiamorte operativa, ricostruiranno gli Infernali che hai distrutto alla Roccaforte della Legione.|n|nVoglio che tu raggiunga l\'Assaltatore Ewan Alabrada alla Torre di Forgiamorte, a nord-ovest, sopra Forgiamorte stessa.', },
    {'Presentati a rapporto all\'Assaltatore Ewan Alabrada alla Torre di Forgiamorte.', },
  },
  [10574] = {
    'I Corruttori Linguamorta',
    {'Secondo la lettera di Akama, quattro frammenti del medaglione sono stati ritrovati e consegnati ai Corruttori Linguamorta. Un tempo, questi temuti esseri erano Sciamani potenti in grado di corrompere gli stessi elementi che veneravano.|n|nPuoi trovare Haalum, Corruttore dell\'Aria, al Passo degli Alafatua. Eykenen e Uylaru, Corruttori della Terra e del Fuoco, sono stati visti l\'ultima volta alle Fosse Vili, vicino alla Mano di Gul\'dan. Infine, si dice che Lakaan, Corruttore dell\'Acqua, si trovi vicino al Presidio dei Malaspira.|n|nTrovali e prendi i frammenti del medaglione.', },
    {'Prendi i quattro frammenti del medaglione a Haalum, Eykenen, Lakaan e Uylaru e torna dall\'Anacoreta Ceyla all\'Altare degli Sha\'tar nella Valle di Torvaluna.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10575] = {
    'La Prigione della Guardiana',
    {'I frammenti che hai ottenuto formano solo metà del medaglione. Il capo dei Linguamorta, Akama, deve aver tenuto l\'altra metà.|n|nTremo all\'idea di farti una richiesta simile: Akama è tanto malvagio quanto scaltro.|n|nSi dice che lui e i Congiurati Linguamorta, la più vile e brutale delle tribù, abbiano una camera di tortura nella Prigione della Guardiana.|n|nVoglio che la trovi e che tu scopra dove si nasconde Akama. Il suo secondo in comando è un Corrotto noto come Sanoru. Interrogalo, se devi.', },
    {'L\'Anacoreta Ceyla ti ha chiesto di entrare nella Prigione della Guardiana, a sud delle Rovine di Baa\'ri, e di interrogare Sanoru per scoprire dove si trova Akama.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10576] = {
    'L\'inganno di Torvaluna',
    nil,
    nil,
  },
  [10577] = {
    'Ciò che Illidan Vuole, Illidan ottiene...',
    {'Prendi il travestimento ed entra nel Presidio dell\'Eclisse. Una volta dentro, usalo per camuffarti. Gli Elfi del Sangue dell\'Eclisse non si accorgeranno del travestimento e potrai arrivare senza problemi dal Gran Comandante Ruusk.|n|nUna volta trovato Ruusk, digli dove dovrà trasferire il Cifrario. Dovrai recitare col cuore, $N. Comportati come se fossi superiore a lui e stessi consegnando un messaggio del suo padrone. Dovrebbe andare bene!|n|nOh, fai attenzione ai draghifalco perché possono smascherarti.', },
    {'Borak, Figlio di Oronok, al ponte vicino al Presidio dell\'Eclisse nella Valle di Torvaluna, ti ha chiesto di consegnare il Messaggio di Illidan al Gran Comandante Ruusk al Presidio dell\'Eclisse.', },
  },
  [10578] = {
    'Il Cifrario della Dannazione: la missione di Borak',
    nil,
    {'Borak, Figlio di Oronok, al ponte vicino al Presidio dell\'Eclisse nella Valle di Torvaluna, ti ha chiesto di recuperare il Terzo Frammento del Cifrario della Dannazione da Ruul l\'Oscuratore.|n|nÈ necessario un gruppo per questa missione.', },
  },
  [10579] = {
    'Il Cifrario della Dannazione: terzo frammento recuperato',
    {'Porta questa cassetta a mio padre. Si trova ancora alla Fattoria di Oronok, a nord, sopra la Cisterna dei Malaspira. Quando i tre frammenti saranno riuniti, riscopriremo le antiche parole.|n|nBuona fortuna, $N. Di\' a mio padre che tornerò presto.', },
    {'Porta lo Scrigno di Borak a Oronok Cuorespino alla Fattoria di Oronok nella Valle di Torvaluna.', },
  },
  [10580] = {
    'Dove sono finiti quei dannati Gnomi?',
    {'Nonostante il bene che abbiamo fatto qui, c\'è ancora un pensiero che mi tormenta: scacciare Toshley e i suoi Gnomi.|n|nNon abbiamo scelta: con le loro tecnologie e i loro esperimenti stanno ostacolando i nostri sforzi nel bosco.|n|nApprezzerei molto se scoprissi cosa ne è stato di loro. L\'ultima volta che li abbiamo visti erano diretti a est, oltre il ponte. Sicuramente poi avranno deviato verso sud, lontano dalla Roccaforte degli Spaccatuono.|n|nCerca indizi su dove sulla loro locazione nella zona meridionale della Cresta Frastagliata.', },
    nil,
  },
  [10581] = {
    'Seguire le briciole',
    {'BENE. TI AVVERTO CHE NON TROVERAI NULLA SULLA CRESTA.|n|nNON SEGUIRE LA SCIA DI PEZZI DI RICAMBIO CHE PORTA ALLA STAZIONE DI TOSHLEY! LÌ NON TROVERAI NÉ TOSHLEY, NÉ TUTTI GLI ALTRI GNOMI!', },
    nil,
  },
  [10582] = {
    'I servitori del Concilio dell\'Ombra',
    {'<Ewan ascolta il tuo resoconto degli eventi verificatisi alla Roccaforte della Legione, annuendo.>|n|nA questo punto, le nostre osservazioni hanno un senso. Abbiamo visto che lanciavano gli Infernali verso la Roccaforte, ma non siamo stati in grado di scoprire molto di più.|n|nIl Concilio dell\'Ombra ha sigillato Forgiamorte peggio di un nuovo barile di birra dei Birratuono. La prima cosa che dovrai fare è spaccare qualche testa per poter entrare e dare un\'occhiata in giro. Inizia a eliminare le guardie del Concilio dell\'Ombra che proteggono l\'entrata di Forgiamorte!', },
    {'L\'Assaltatore Ewan Alabrada alla Torre di Forgiamorte ti ha chiesto di uccidere 10 Guardiani Forgiamorte e 5 Evocatori Forgiamorte.', },
  },
  [10583] = {
    'Il destino di Flanis',
    {'Inizialmente, il Comandante di Squadriglia Nuainn aveva mandato tre soldati per tenere d\'occhio Forgiamorte e raccogliere informazioni. Flanis Alalesta si era offerto volontario per infiltrarsi a Forgiamorte, ma non abbiamo sue notizie da giorni.|n|nTemo il peggio, $N. Flanis è un abile esploratore, ma non abbiamo modo di sapere se si è messo nei guai. Cercalo a Forgiamorte e recupera qualsiasi informazione o oggetto che potrebbe aver raccolto.', },
    {'L\'Assaltatore Ewan Alabrada alla Torre di Forgiamorte ti ha chiesto di cercare Flanis Alalesta a Forgiamorte e di recupere lo Zaino di Flanis.', },
  },
  [10584] = {
    'Raccolta di convertitori energetici',
    {'Quegli stupidi Ogre dell\'Avamposto dei Lamacurva a nord di qui ci hanno rubato i convertitori energetici! E tu dovrai recuperarli per me, in un certo senso.|n|nSenza dubbio, con le loro goffe manone gli Ogre avranno danneggiato i convertitori. Quello che ti chiedo è di rilasciare l\'energia che hanno accumulato e poi recuperarla usando questo Magnete Proto-Voltaico sugli Elettromentali che ne ricaverai.|n|nProbabilmente non reagiranno bene, quindi dovrai "ucciderli" mentre si trovano all\'interno della sfera magnetica.', },
    nil,
  },
  [10585] = {
    'La Stanza dell\'Evocazione',
    {'Perché il Concilio dell\'Ombra riesca a costruire Infernali con la stessa rapidità con cui vendono utilizzati, devono avere un\'area preposta all\'evocazione degli elementali corrotti che fungono da anima per quelle creature.|n|nÈ probabile che la Stanza dell\'Evocazione si trovi sottoterra, vicino a una pozza di acqua o lava contaminata. Trovala e scopri come interrompere il rituale di evocazione. I Mo\'arg coinvolti nella produzione degli Infernali potrebbero avere qualcosa che ti aiuterà a spezzare la magia degli evocatori.', },
    {'Prendi un Distorsore Elementale a un Fabbro Forgiamorte o a un Meccanista Forgiamorte e usalo per interrompere il rituale nella Stanza dell\'Evocazione. Una volta portata a termine la missione, presentati a rapporto all\'Assaltatore Ewan Alabrada alla Torre di Forgiamorte.', },
  },
  [10586] = {
    'Uccidi l\'Araldo della Guerra!',
    {'Abbiamo fatto molti progressi per fermare le attività del Concilio dell\'Ombra a Forgiamorte, ma se vogliamo trionfare, dovremo sconfiggere il sovrintendente inviato dalla Legione.|n|nNello zaino di Flanis ho trovato una chiave. Sono certo che ci sarà utile per trovare l\'Araldo della Guerra Razuun che hai visto alla Roccaforte della Legione.|n|nDopo che l\'avrai rintracciato e ucciso, presentati a rapporto direttamente dal Comandante di Squadriglia Nuainn. Vorrà essere informato immediatamente!', },
    {'Sconfiggi l\'Araldo della Guerra Razuun, recupera gli Ordini di Razuun e presentati a rapporto dal Comandante di Squadriglia Nuainn alla Roccaforte dei Granmartello.', },
  },
  [10587] = {
    'I Campi d\'Addestramento di Karabor',
    {'I nostri esploratori segnalano un massiccio flusso di reclute Elfi del Sangue dei Furia del Sole che si dirige verso le Rovine di Karabor. Di norma, rappresenterebbe una mera minaccia militare, tuttavia, crediamo che qualcosa non quadri.|n|nMi è stato comunicato che il loro abbigliamento e la loro tecnica di combattimento sono estremamente simili a quelle di Illidan in persona. Onde evitare allarmismi infondati, voglio che mi porti le loro armi. In questo modo, potremo verificare se i miei timori sono fondati o meno.', },
    {'L\'Esarca Onaala all\'Altare degli Sha\'tar ti ha chiesto di recuperare 8 Lame da Guerra dei Furia del Sole ai Cacciatori di Demoni Supplicanti e ai Cacciatori Principianti di Demoni nelle Rovine di Karabor, a sud-est dell\'Altare degli Sha\'tar.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10588] = {
    'Il Cifrario della Dannazione',
    nil,
    {'Usa il Cifrario della Dannazione all\'Altare della Dannazione per evocare Cyrukh il Signore del Fuoco.|n|nDistruggilo e poi parla con il Curaterra Torlok, che si trova anch\'egli all\'Altare della Dannazione.', },
  },
  [10589] = {
    'Ottenere l\'accesso',
    {'Secondo gli ordini di Razuun, l\'enorme base operativa degli Infernali si chiama Portale di Invasione: Cataclisma e si trova sulle montagne settentrionali. L\'unico modo per raggiungerla è usando un teletrasporto situato nella Roccaforte della Legione.|n|nAlcuni membri della Legione possiedono dei dispositivi che gli permettono di attivare i teletrasporti. Devi impossessarti di uno di quei dispositivi per avere accesso al teletrasporto. Uccidi tutti i demoni se devi, ma non puoi tornare a mani vuote.', },
    {'Porta un Telecomando per il Teletrasporto della Legione al Comandante di Squadriglia Nuainn alla Roccaforte dei Granmartello. Ne sono in possesso i Fabbri d\'Armi Mo\'arg nella Roccaforte della Legione.', },
  },
  [10591] = {
    '[DESTROY THIS QUEST!]',
    nil,
    nil,
  },
  [10594] = {
    'La misura della frequenza di risonanza',
    {'Porta questi misuratori alla Cresta Risonante. Posandoli a terra secondo un certo schema, creerai dei campi sovrapposti in grado di misurare l\'ampiezza della frequenza dei cristalli. Poniti in mezzo a loro in modo da trovarti nel punto d\'intersezione di cinque campi d\'oscillazione e otterrò tutte le informazioni che cerco!|n|nPuoi persino sfruttare i misuratori posati a terra da qualcun altro.|n|nAh, ed è probabile che si formi una fenditura! Non ho idea di cosa potrebbe uscirne fuori, ma preparati al peggio.', },
    nil,
  },
  [10595] = {
    nil,
    {'<Gulmok guarda il cielo.>|n|nI nostri esploratori stanno combattendo bene, ma continuano ad arrivare Infernali!|n|nI demoni ci bombardano impunemente dalla Roccaforte della Legione a sud-ovest! Persino la Guardia Kor\'kron non riuscirà a fermarli per sempre.|n|nSto arruolando ogni $R <ritenuto idoneo/ritenuta idonea> perché faccia la propria parte nella difesa del Villaggio di Torvaluna. Non è un gioco, $C. C\'è di mezzo la sopravvivenza del villaggio. Fai il tuo dovere per l\'Orda e unisciti alla battaglia!', },
    {'La Guardia di Sangue Gulmok, fuori dal Villaggio di Torvaluna, ti ha chiesto di uccidere 10 Attaccanti Infernali.', },
  },
  [10596] = {
    'Alla Roccaforte della Legione',
    {'Il tuo bersaglio è la Roccaforte della Legione. Non avrai rinforzi, quindi un attacco frontale è fuori discussione.|n|nDa quel poco che sappiamo, la Legione prepara e ammassa gli Infernali nella Roccaforte. Con l\'aiuto di un travestimento che ti fornirò, dovrai intrufolarti nella Roccaforte della Legione e scoprire i loro piani.|n|nLa tua opportunità migliore sarà intercettare o ascoltare una comunicazione tra comandanti.', },
    {'Entra nella Roccaforte della Legione, trova il Dispositivo di Comunicazione della Legione e sfrutta il travestimento per scoprire i loro piani. Una volta completata la missione, torna dalla Guardia di Sangue Gulmok al Villaggio di Torvaluna.', },
  },
  [10597] = {
    'Piazzare la bomba',
    {'Non possiamo permettere che la Legione ci travolga mentre marcia sul Tempio Nero.|n|nTrova un modo per distruggere gli Infernali che vogliono usare contro di noi. Non te lo sto chiedendo, $N: è un ordine.|n|nLa Pozza Fetida vicino alla Roccaforte della Legione contiene un vecchio nucleo energetico di Vilrazziatore che puoi usare come base per una specie di Vilbomba. Cerca delle piastre rinforzate tra gli altri rottami vicino al Vilrazziatore. Dovresti essere in grado di creare una bomba abbastanza potente da eliminare gli Infernali e scuotere le fondamenta della Roccaforte!', },
    {'Trova un Nucleo Energetico del Vilrazziatore e una Piastra del Vilrazziatore e portali alla Guardia di Sangue Gulmok al Villaggio di Torvaluna.', },
  },
  [10598] = {
    'Fai saltare gli Infernali!',
    {'Il dispositivo che abbiamo creato non vincerà una gara di bellezza, ma dovrebbe essere in grado di distruggere gli Infernali ammassati nella Roccaforte della Legione. A giudicare da come il nucleo energetico del Vilrazziatore ha ridotto la Pozza Fetida, dovrebbe avere ancora abbastanza potere detonante.|n|nSe farai saltare il dispositivo al centro del glifo verde nella roccaforte, l\'esplosione dovrebbe coinvolgere tutti gli Infernali.', },
    {'Usa la Vilbomba mentre ti trovi sul glifo verde nella Roccaforte della Legione per distruggere gli Infernali e poi fai rapporto alla Guardia di Sangue Gulmok al Villaggio di Torvaluna.', },
  },
  [10599] = {
    'Forgiamorte',
    {'Mentre ti occupavi degli Infernali alla Roccaforte della Legione, ho esaminato i tuoi rapporti. Non abbiamo motivo di credere che la Legione abbia mentito su quanto avviene a Forgiamorte. Laggiù stanno davvero producendo Infernali. Quindi, ho mandato un gruppo di ricognizione per tenere d\'occhio la situazione.|n|nSe lasciamo Forgiamorte operativa, ricostruiranno gli Infernali che hai distrutto alla Roccaforte della Legione.|n|nPresentati a rapporto dall\'Esploratore Zagran in cima al Mastio dell\'Ombra, che sovrasta Forgiamorte, a sud-est.', },
    {'Presentati a rapporto dall\'Esploratore Zagran al Mastio dell\'Ombra.', },
  },
  [10600] = {
    'I servitori del Concilio dell\'Ombra',
    {'<Zagran ascolta il tuo resoconto degli eventi verificatisi alla Roccaforte della Legione, annuendo.>|n|nQuesto spiega molte cose. Abbiamo visto che lanciavano gli Infernali verso la Roccaforte, ma non siamo stati in grado di scoprire molto di più.|n|nIl Concilio dell\'Ombra ha sigillato Forgiamorte. Sembra che dovrai farti strada combattendo. Inizia a eliminare le guardie del Concilio dell\'Ombra che proteggono l\'entrata di Forgiamorte!', },
    {'L\'Esploratore Zagran ti ha chiesto di uccidere 10 Guardiani Forgiamorte e 5 Evocatori Forgiamorte.', },
  },
  [10601] = {
    'Il destino di Kagrosh',
    {'Inizialmente, il gruppo di ricognizione era composto da tre elementi. Sfortunatamente, Kagrosh ha deciso che voleva fare l\'eroe.|n|nSi è infiltrato a Forgiamorte e non abbiamo più avuto sue notizie.|n|nCon ogni probabilità, quello sciocco si è fatto ammazzare. I membri del Concilio dell\'Ombra non sono degli stupidi e Kagrosh non era noto per andarci coi piedi di piombo, sa capisci cosa intendo. Cercalo a Forgiamorte e recupera qualsiasi informazione o oggetto che potrebbe aver raccolto.', },
    {'L\'Esploratore Zagran al Mastio dell\'Ombra ti ha chiesto di cercare Kagrosh e lo Zaino di Kagrosh a Forgiamorte.', },
  },
  [10602] = {
    'La Stanza dell\'Evocazione',
    {'Perché a Forgiamorte riescano a sfornare Infernali con questa velocità, devono avere un\'area preposta all\'evocazione degli elementali che formano il nucleo degli Infernali.|n|nÈ probabile che la Stanza dell\'Evocazione si trovi sottoterra, vicino a una pozza di acqua o lava contaminata. Trovala e scopri come interrompere il rituale di evocazione. I Mo\'arg coinvolti nella produzione degli Infernali potrebbero avere qualcosa che ti aiuterà a spezzare la magia degli evocatori.', },
    {'Prendi un Distorsore Elementale a un Fabbro Forgiamorte o a un Meccanista Forgiamorte e usalo per interrompere il rituale nella Stanza dell\'Evocazione. Una volta portata a termine la missione, presentati a rapporto dall\'Esploratore Zagran al Mastio dell\'Ombra.', },
  },
  [10603] = {
    'Uccidi l\'Araldo della Guerra!',
    {'A Forgiamorte abbiamo fatto molti progressi contro il Concilio dell\'Ombra, ma è ora di finire il lavoro.|n|nTra le cose di Kagrosh, ho trovato una chiave. Sembra che sia riuscito a concludere qualcosa prima che lo uccidessero.|n|nTi sarà utile per trovare l\'Araldo della Guerra Razuun che hai visto alla Roccaforte della Legione.|n|nDopo che l\'avrai rintracciato e ucciso, presentati a rapporto direttamente dalla Guardia di Sangue Gulmok. Meglio non farlo aspettare.', },
    {'Sconfiggi l\'Araldo della Guerra Razuun, recupera gli Ordini di Razuun e presentati a rapporto dalla Guardia di Sangue Gulmok al Villaggio di Torvaluna.', },
  },
  [10604] = {
    'Ottenere l\'accesso',
    {'Secondo gli ordini di Razuun, l\'enorme base operativa degli Infernali si chiama Portale di Invasione: Cataclisma ed è situata sulle montagne oltre il nostro villaggio! L\'unico modo per raggiungerla è usando un teletrasporto situato nella Roccaforte della Legione.|n|nAlcuni servitori della Legione possiedono un dispositivo che gli permette di usare il teletrasporto. Devi impossessarti di uno di quei dispositivi per avere accesso al teletrasporto. Uccidi tutti i demoni se devi, ma non puoi tornare a mani vuote. Non perdere tempo, il nemico è alle porte.', },
    {'Porta un Telecomando per il Teletrasporto della Legione alla Guardia di Sangue Gulmok al Villaggio di Torvaluna. Ne sono in possesso i Fabbri d\'Armi Mo\'arg nella Roccaforte della Legione.', },
  },
  [10605] = {
    nil,
    nil,
    {'Parla con Carendin Halgar a Sepulcra.', },
  },
  [10606] = {
    'Arte della Manutenzione dei Vilrazziatori',
    {'Il modo migliore per distruggere il resto dei rifornimenti della Legione è rivoltargli contro le sue stesse armi. Ho ideato una modifica che ti permetterà di prendere il controllo dei Vilrazziatori Sentinella.|n|nTuttavia, devo ancora sistemare alcune cose. E per farlo, mi serve il manuale che il Dottor Gutrick tiene chiuso in un forziere in fondo alla rampa. Probabilmente, non ti consegnerà la chiave senza combattere, quindi dovrai prenderla con la forza. Portami il manuale del Vilrazziatore e io penserò al resto!', },
    {'Uccidi il Dottor Gutrick prendi la Chiave del Dottore. Usala per aprire il Forziere del Dottore e recuperare "Arte della Manutenzione dei Vilrazziatori". Consegna il libro a Plexi al Portale di Invasione: Cataclisma.', },
  },
  [10607] = {
    'Sussurri del Dio dei Corvi',
    {'A Grishna, i totem lasciati dagli Oracoli del Corvo permettono agli Arakkoa di udire la Parola del Corvo. Purtroppo la lingua degli Arakkoa è per noi indecifrabile.|n|nUtilizzando il Pendente dell\'Araldo, ora potremo finalmente capirla: stando in comunione con le anime degli Arakkoa, la loro lingua non avrà segreti per te. Mentre ti trovi in questo stato, visita i totem e apprendine i messaggi.|n|nSiamo nelle tue mani, $N.', },
    nil,
  },
  [10608] = {
    'Forte e chiaro',
    {'Quei dannati Sferzaroccia stanno ostacolando la mia ricerca giù alla Cresta Risonante! Il loro continuo scavare rovina i cristalli, negandomi la possibilità di studiare l\'armonia dei Cristalli Risonanti.|n|nTu hai l\'aria di $Guno:una; che potrebbe aiutarmi a risolvere questo problema. Recati a sud ed elimina quegli Scorticatori di Cristallo.', },
    nil,
  },
  [10609] = {
    'È nato prima l\'uovo o il draco?',
    {'Sto effettuando delle ricerche sulle applicazioni mediche delle essenze di draco. Secondo me potrebbero costituire una vera e propria panacea!|n|nMi serve che qualcuno vada a sud, alla Cresta Risonante, e me ne procuri un po\'.|n|nDovresti prendere il mio Modulatore di Fase Temporale e usarlo sui Draghetti Fatui che nascono dalle uova di Draco Fatuo. Recupera l\'essenza dalle forme in cui si trasformeranno.|n|nForme che purtroppo non so descriverti, visto che userai una tecnologia molto sperimentale.', },
    nil,
  },
  [10611] = {
    'Arte della Manutenzione dei Vilrazziatori',
    {'Il modo migliore per distruggere il resto delle provviste della Legione è rivoltargli contro le stesse armi sue. Ho ideato na modifica che ti permetterà di pigliare il controllo dei Vilrazziatori Sentinella.|n|nTuttavia, devo ancora sistemare alcune cose. E per farlo, mi serve il manuale che il Dottor Maleficus tiene chiuso in nu forziere in fondo alla rampa. Probabilmente nun ti consegnerà la chiave senza combattere, quindi dovrai pigliarla con la forza. Portami il manuale dei Vilrazziatore e io penserò al resto.', },
    {'Uccidi il Dottor Maleficus e prendi la Chiave del Dottore. Usala per aprire il Forziere del Dottore e recuperare "Arte della Manutenzione dei Vilrazziatori". Consegna il libro a Nakansi al Portale di Invasione: Cataclisma.', },
  },
  [10612] = {
    'Colpo gobbo a Torvaluna',
    {'<Plexi sfoglia il manuale.>|n|nBene, c\'è tutto quello di cui abbiamo bisogno, ma resta un problema. I Vilrazziatori non sono costruiti per essere comandati a distanza.|n|nPossiamo modificarne uno perché tu possa usarlo per breve tempo, ma dovrai fare alla svelta o chi può sapere cosa accadrà! E non mi stupirei se il tuo piccolo numero con il Vilrazziatore attirasse l\'attenzione dei cani della Legione. Tieni gli occhi aperti e, qualunque cosa tu faccia, non dimenticare di distruggere tutto ciò che puoi!', },
    {'Usa una Console di Controllo del Vilrazziatore per assumere il controllo di un Vilrazziatore Sentinella. Distruggi 60 Infernali Forgiamorte prima che il tuo Vilrazziatore cessi di funzionare. Quando avrai completato la missione, presentati a rapporto da Plexi al Portale di Invasione: Cataclisma.', },
  },
  [10613] = {
    'Colpo gobbo a Torvaluna',
    {'<Nakansi sfoglia il manuale.>|n|nCi stanno tutte quante le informazioni, ma fai attenzione. Chesti affari nun sono costruiti per essere comandati a distanza.|n|nPossiamo modificarne uno perché tu possa usarlo per breve tempo, ma dovrai fare alla svelta o chissà cosa potrebbe accadere! E nun mi stupirei se il piccirillo numero tuo con il Vilrazziatore attirasse l\'attenzione della feccia della Legione. Pensa a salvare la pelle, ma ricorda che la missione e la salvezza del Villaggio di Torvaluna vengono prima!', },
    {'Usa una Console di Controllo del Vilrazziatore per assumere il controllo di un Vilrazziatore Sentinella. Distruggi 60 Infernali Forgiamorte prima che il tuo Vilrazziatore cessi di funzionare. Quando avrai completato la missione, presentati a rapporto da Nakansi al Portale di Invasione: Cataclisma.', },
  },
  [10614] = {
    'Sussurri nel vento',
    {'Finora ho sempre inseguito le voci sui Mok\'Nathal per tutte le Terre Esterne, ma invano. Forse adesso li abbiamo finalmente trovati.|n|nMa ora che è giunto il momento che tanto aspettavo, sento un certo disagio. Un pensiero ha sempre tormentato le mie notti: sarò accettato?|n|nIo... conosco il nome del loro capo: Leoroxx. Cercalo. Dovrai andare tu in avanscoperta per me.', },
    nil,
  },
  [10615] = {
    'Bosco di Ruuan',
    {'Le informazioni che mi hai aiutato a scoprire sulla natura degli Arakkoa si riveleranno molto interessanti anche per un\'altra persona.|n|nAbbiamo ricevuto la visita di un membro della Spedizione Cenariana, anch\'egli preoccupato per le oscure intenzioni degli Arakkoa qui nelle Montagne Spinaguzza.|n|nDovresti cercarlo e parlargli. Si chiama Timeon e lo troverai a Boscovivo, nel Bosco di Ruuan. Da qui, segui la strada a ovest e dirigiti a nord all\'incrocio nella Cresta delle Lame. Infine, alla biforcazione nella Gola Tagliente, procedi verso ovest.', },
    {'Parla con Timeon a Boscovivo, che si trova al Bosco di Ruuan nelle Montagne Spinaguzza.', },
  },
  [10617] = {
    'Bozzoli di Alaseta',
    {'Qui al villaggio utilizziamo la seta dei Bozzoli di Alaseta in mille modi, tanto che non ci basta mai e ne vorremmo sempre dell\'altra.|n|nUna volta iniziato il processo di metamorfosi, è difficile recuperare la seta dei bozzoli dalle larve.|n|nI nostri guerrieri sono impegnati a respingere l\'assalto al villaggio. Se potessi aiutarci a raccogliere la seta, ci faresti un grande favore.', },
    nil,
  },
  [10618] = {
    'Le ali più soffici',
    {'Dare la caccia alle Larve di Alaseta rappresenta una sfida difficile per i nostri giovani guerrieri. Per fortuna, anche nel caso non riescano a raccogliere i bozzoli, possiamo sempre usare le ali degli Alaseta.|n|nAnzi, ti dirò: utilizziamo le ali anche più dei bozzoli, e anche di quelle non ne abbiamo mai abbastanza.|n|nSe per caso ti capitasse di raccoglierne e me le portassi, te ne sarei molto grata.', },
    nil,
  },
  [10619] = {
    'La Tribù Linguamorta',
    {'Tutti i Corrotti temono la Tribù Linguamorta. È formata dagli individui più malvagi e assetati di sangue, scelti personalmente da Akama. Sono feroci e spietati quanto qualsiasi Naga, demone o Elfo del Sangue dell\'esercito di Illidan e sono stati schierati in massa alle Rovine di Baa\'ri, a sud-ovest. Recati là e riduci le loro file prima che abbiano la possibilità di attaccarci.', },
    {'Il Vendicatore Aluumen ti ha chiesto di recarti alle Rovine di Baa\'ri e di uccidere 3 Addestratori Linguamorta, 4 Guerrieri Linguamorta e 6 Sciamani Linguamorta.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10620] = {
    'La minaccia dei Crestaguzza',
    {'Quando Toshley decise di trasferirsi nelle Terre Esterne, fummo assoldati per aiutarlo e da allora non ci siamo mai fermati.|n|nAdesso, finalmente, sembra che metteremo radici in questo posto. Tutti questi scienziati pazzi hanno i loro progetti a cui badare e noi Cavalieri Rozzi siamo qui per proteggerli.|n|nQuello che ci serve, in questo momento, è che tu ti diriga a nord alla Cresta delle Lame, o a est al Pianoro delle Scaglie, e che ci aiuti a tenerli al sicuro uccidendo le Inseguitrici. Si tratta di ragni che si aggirano furtivi tra gli spuntoni e saltano addosso ai passanti ignari.', },
    nil,
  },
  [10621] = {
    'Frammento dell\'Anatema degli Illidari',
    {'<Il frammento sembra far parte di un\'arma più grande. Le rune squadrate incise sul metallo brillano di una luce minacciosa.>|n|n<Non è chiaro per cosa debba essere usata l\'arma, ma non puoi ignorarla. Gran parte dei Mo\'arg alla Roccaforte della Legione sembra stia lavorando su frammenti dello stesso metallo che tieni in mano. Forse i fabbri d\'armi alla Roccaforte dei Granmartello saranno in grado di dirti qualcosa di più.>', },
    {'Porta il Frammento dell\'Anatema degli Illidari a Ordinn Tuonapugni alla Roccaforte dei Granmartello.', },
  },
  [10622] = {
    'Prova di lealtà',
    {'Akama ha seguito da vicino i tuoi progressi, $N.|n|nI Linguamorta che hai ucciso alle Rovine di Baa\'ri sono tra i Corrotti più malvagi... Scelti personalmente da Akama per preservare la facciata che vogliamo mostrare a Illidan. I Congiurati, tuttavia, sono a conoscenza delle vere intenzioni di Akama.|n|nMa, innanzitutto, dobbiamo essere certi che non sei $Galleato:alleata; con Illidan. Un Satiro conosciuto come Zandras ci spia dalle mura della prigione. Uccidilo come prova della tua lealtà ad Akama.', },
    {'Uccidi Zandras alla Prigione della Guardiana nella Valle di Torvaluna e torna da Sanoru.', },
  },
  [10623] = {
    'Frammento dell\'Anatema degli Illidari',
    {'<Il frammento sembra far parte di un\'arma più grande. Le rune squadrate incise sul metallo brillano di una luce minacciosa.>|n|n<Non è chiaro per cosa debba essere usata l\'arma, ma non puoi ignorarla. Gran parte dei Mo\'arg alla Roccaforte della Legione sembra stia lavorando su frammenti dello stesso metallo che tieni in mano. Forse i fabbri d\'armi al Villaggio di Torvaluna saranno in grado di dirti qualcosa di più.>', },
    {'Porta il Frammento dell\'Anatema degli Illidari a Grokom Occhionero al Villaggio di Torvaluna.', },
  },
  [10624] = {
    'Una storia di fantasmi',
    nil,
    {'Il Capo Speziale Hildagard al Villaggio di Torvaluna nella Valle di Torvaluna ti ha chiesto di portarle 15 Campioni di Cenere Eterna.', },
  },
  [10625] = {
    'Lenti Spiritate',
    {'Le chiamo "Lenti Spiritate". Intelligente, no? Una volta indossati questi occhiali, sarai in grado di vedere gli spiriti della Valle di Torvaluna.|n|nPrima di consegnarteli, però, devi promettermi che ci aiuterai a eliminare i fantasmi al villaggio.|n|nIndossa gli occhiali e distruggi tutti gli spiriti che vedi aggirarsi nel Villaggio di Torvaluna. Con un po\' di fortuna, distruggendo questi, gli altri saranno costretti ad andare altrove.', },
    {'Il Capo Speziale Hildagard al Villaggio di Torvaluna nella Valle di Torvaluna ti ha chiesto di uccidere 12 Zeloti di Torvaluna.', },
  },
  [10626] = {
    'Impossessati delle armi',
    {'Se avessimo una grossa quantità di questo materiale, potremmo forgiarti un\'arma.|n|nI due Signori delle Fosse alla Roccaforte della Legione, Makazradon e Morgroron, utilizzano già queste armi antidemoniache. Non possiamo sapere quante altre ne vuole produrre la Legione, ma se riuscissimo a impossessarci dei prototipi, potremmo portare avanti il nostro progetto.|n|n<Ordinn sorride.>|n|nDà una discreta soddisfazione usare le armi segrete della Legione contro i suoi soldati, non trovi?', },
    {'Ordinn Tuonapugni alla Roccaforte dei Granmartello ti ha chiesto di portargli la Guisarma di Makazradon e la Guisarma di Morgroron.', },
  },
  [10627] = {
    'Impossessati delle armi',
    {'Se avessi una grossa quantità di questo materiale, potrei forgiarti un\'arma.|n|nI due Signori delle Fosse alla Roccaforte della Legione, Makazradon e Morgroron, utilizzano già queste armi antidemoniache. Impossessandocene, dovremmo avere abbastanza materie prime per creare la tua arma e forse altre.|n|nNon vedo l\'ora di affrontare il nemico usando le sue stesse armi. Così, la Legione imparerà a giocare con la magia antidemoniaca.', },
    {'Grokom Occhionero al Villaggio di Torvaluna ti ha chiesto di portargli la Guisarma di Makazradon e la Guisarma di Morgroron.', },
  },
  [10628] = {
    nil,
    {'Hai dimostrato di stare dalla nostra parte. Ti rivelerò il rifugio del nostro capo.|n|nOltrepassa i saloni e sulla destra troverai un passaggio sotterraneo nascosto da una pozza d\'acqua.|n|nFai attenzione, però, $N: non devi parlare a nessuno di ciò che vedrai.', },
    {'Parla con Akama nella stanza segreta della Prigione della Guardiana.', },
  },
  [10629] = {
    'Un lavoro di melma',
    {'Finalmente il mio Segatronchi funziona, ma ho perso le chiavi. Il mio accampamento è protetto da un branco di Vilsegugi: non fanno bene il loro lavoro e gli piace un po\' troppo mordermi. Inoltre, amano gli oggetti luccicanti. Credo che questo Vilsegugio abbia ingoiato le chiavi del mio Segatronchi. Portalo a spasso e ti ricompenserò. Uccidi alcuni Cinghiali Infernali e faglieli mangiare, così farà ciò che deve. Quando avrà finito, cerca le chiavi nei suoi "ricordini".', },
    {'Usa il Fischietto del Vilsegugio per chiamare un Vilsegugio da Guardia. Portalo a spasso e uccidi alcuni Cinghiali Infernali Impazziti. Cerca le Chiavi del Segatronchi in mezzo ai "ricordini" del Vilsegugio da Guardia, poi riportale al Caposquadra Razelcraz vicino alla miniera a nord-ovest di Thrallmar.', },
  },
  [10630] = {
    'Sotto Thrallmar',
    {'Sto per rimettermi al lavoro, ma ho un problema: la miniera è invasa dai Gan\'arg. Non posso far entrare i miei Peoni. Inoltre, anche se riparassi il Segatronchi, non vorrei rischiare che andasse distrutto in combattimento. Nelle profondità della miniera, c\'è il capo dei Gan\'arg: uccidilo e forse fuggiranno, così potrò fare un po\' di soldi e andarmene da qui.', },
    {'Uccidi Urga\'zz, poi torna dal Caposquadra Razelcraz vicino alla miniera a nord-ovest di Thrallmar.', },
  },
  [10632] = {
    'Denti da affilare',
    {'Mi fa piacere che tu abbia aiutato Toshley e i suoi scienziati. Io, però, non posso permettermi il lusso di abbandonarmi ai miei interessi personali.|n|nSe vuoi fare la differenza qui, farai ciò che ti chiedo. In questo momento, mi servono armi.|n|nQuelle che abbiamo sono efficaci da lontano, ma quando quelle dannate bestie si avvicinano ci servono armi da mischia.|n|nDai denti dei Codafrusta Fauci Aguzze che vivono nell\'area settentrionale della Cresta delle Lame si possono ricavare delle lame ideali per delle vibro-armi. Portamene qualcuno.', },
    nil,
  },
  [10633] = {
    'Teron Malacarne: storia e leggenda',
    {'Circolano molte storie sulla vita di Teron Malacarne, ma gran parte di esse sono solo leggende. Non so cosa gli sia successo dopo che è tornato su Draenor.|n|nL\'unica cosa certa è che è già morto una volta.|n|nHo sentito gli esploratori parlare di un antico spirito d\'Orco che dimora all\'Altare delle Ombre, all\'estremo sud-est, oltre i Campi degli Alafatua e il Passo degli Alafatua. Prendi le Lenti Spiritate e trovalo. Ti saprà dare altre informazioni su Malacarne.', },
    nil,
  },
  [10634] = {
    'Divinazione: l\'Armatura di Malacarne',
    nil,
    {'Lo Spirito Antico di Torvaluna all\'Altare delle Ombre nell\'area sudorientale della Valle di Torvaluna ti ha chiesto di recuperare l\'Armatura di Malacarne.', },
  },
  [10635] = {
    'Divinazione: il Mantello di Malacarne',
    {'Ha compiuto molti atti crudeli, ma nessuno più terribile del massacro dei Chierici di Karabor.|n|nDopo che l\'Orda di Gul\'dan sconfisse i Draenei di Karabor, i Chierici di Karabor sopravvissuti furono condotti fuori. Gli dissero che sarebbero stati portati alla Cittadella del Fuoco Infernale come prigionieri di guerra.|n|nMalacarne, che non era ancora un Cavaliere della Morte, li uccise tutti a sangue freddo. Ora si aggirano davanti al Tempio Nero con la vendetta nel cuore.|n|nSono i Chierici di Karabor ad avere il Mantello di Malacarne.', },
    {'Lo Spirito Antico di Torvaluna all\'Altare delle Ombre nell\'area sudorientale della Valle di Torvaluna ti ha chiesto di recuperare il Mantello di Malacarne.', },
  },
  [10636] = {
    'Divinazione: il Randello di Malacarne',
    {'Uno a uno s\'inginocchiarono di fronte a lui, offrendogli le proprie vite in segno di lealtà. Malacarne prese la sua falce e li decapitò. Poco dopo questo massacro, si tolse la vita.|n|nMa non lo fece per rimorso! No, Malacarne cercava l\'immortalità! Dai corpi dei Cavalieri della Morte caduti sorsero i Cavalieri Spettrali di Karabor.|n|nOra percorrono le strade che circondano la Mano di Gul\'dan, attendendo il ritorno del loro padrone. Sono loro ad avere il Randello di Malacarne. Trovalo...', },
    {'Lo Spirito Antico di Torvaluna all\'Altare delle Ombre nell\'area sudorientale della Valle di Torvaluna ti ha chiesto di recuperare il Randello di Malacarne.', },
  },
  [10637] = {
    'Una distrazione necessaria',
    {'Le armi sono autentiche, come temevamo. Illidan sta addestrando Cacciatori di Demoni nelle Rovine di Karabor e dobbiamo impedirglielo.|n|nNon farti trarre in inganno dal loro nome, $N: il loro potere sarà usato tanto contro di noi quanto contro i demoni.|n|nI loro Stregoni evocano e soggiogano demoni per usarli nell\'addestramento delle reclute. Hanno bandito un Signore delle Fosse di nome Azaloth perché si è dimostrato troppo forte per essere usato negli addestramenti. Trova un modo per scatenarlo contro i suoi aguzzini. Dovrebbe darci il tempo che ci serve.', },
    {'L\'Esarca Onaala ti ha chiesto di tornare alle Rovine di Karabor e di trovare un modo per scatenare Azaloth contro i suoi aguzzini.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10639] = {
    'Teron Malacarne è il mio nome...',
    {'Ora che abbiamo recuperato gli oggetti di Malacarne non resta che un tassello per risolvere il mistero: un ospite.|n|n<Il volto dello Spirito Antico di Torvaluna si illumina di un sorriso perfido.>|n|nNon avrai creduto alla favola che ti ho raccontato? L\'Altare delle Ombre è la mia prigione. Senza il tuo aiuto, sarei rimasto rinchiuso qui per l\'eternità. Ora, m\'impossesserò del tuo corpo, distruggerai i miei aguzzini e spezzerai le catene che mi legano. Rifiutati e rimarremo entrambi bloccati qui per sempre.|n|nTeron Malacarne sarà libero!', },
    {'Non eri che una pedina nelle mani dello Spirito Antico di Torvaluna! Ora che hai riunito gli oggetti che ti aveva chiesto, ti ha rivelato di essere Teron Malacarne. Per liberarti dalla sua possessione, devi piegarti al suo volere e uccidere Karsius il Guardiano Antico.|n|nSe ci riuscirai, torna dal Capo Speziale Hildagard al Villaggio di Torvaluna.', },
  },
  [10640] = {
    nil,
    {'Di questi tempi, è raro scoprire che altri seguono la via dei Cacciatori di Demoni. Ancora più raro è trovare qualcuno che la segue e non sia alleato di Illidan.|n|nSi vocifera che un tale individuo si trovi nelle Terre Esterne. Un altro nome è temuto nei territori della Legione a Nagrand più di un esercito di Vendicatori Aldor. Si tratta di Altruis.|n|nRecati a Nagrand occidentale e trovalo. Forse, sarà disposto a darci maggiori informazioni sui nuovi campi d\'addestramento per Cacciatori di Demoni.', },
    {'Vai a Nagrand occidentale e trova Altruis il Sofferente.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10642] = {
    'Sotto la cenere',
    nil,
    {'Zorus il Giudicatore alla Roccaforte dei Granmartello nella Valle di Torvaluna ti ha chiesto di portargli 15 Campioni di Cenere Eterna.', },
  },
  [10643] = {
    'Gli Araldi di Torvaluna',
    {'Che non si dica in giro che Zorus non ha il senso dell\'umorismo.|n|nBasta chiacchiere. Indossa le Lenti Spiritate così sarai in grado di vedere gli spiriti degli Orchi di Torvaluna che vagano per la roccaforte. Non temere, perché siamo noi i veri invasori. Tuttavia, devono essere distrutti, perché la loro ora è giunta ormai da tempo.|n|nDistruggi gli Araldi di Torvaluna che infestano la Roccaforte dei Granmartello e torna da me.', },
    {'Zorus il Giudicatore alla Roccaforte dei Granmartello nella Valle di Torvaluna ti ha chiesto di uccidere 12 Araldi di Torvaluna.', },
  },
  [10644] = {
    'Teron Malacarne: storia e leggenda',
    nil,
    nil,
  },
  [10645] = {
    'Teron Malacarne è il mio nome...',
    {'Ora che abbiamo recuperato gli oggetti di Malacarne non resta che un tassello per risolvere il mistero: un ospite.|n|n<Il volto dello Spirito Antico di Torvaluna si illumina di un sorriso perfido.>|n|nNon avrai creduto alla favola che ti ho raccontato? L\'Altare delle Ombre è la mia prigione. Senza il tuo aiuto, sarei rimasto rinchiuso qui per l\'eternità. Ora, m\'impossesserò del tuo corpo, distruggerai i miei aguzzini e spezzerai le catene che mi legano. Rifiutati e rimarremo entrambi bloccati qui per sempre.|n|nTeron Malacarne sarà libero!', },
    {'Non eri che una pedina nelle mani dello Spirito Antico di Torvaluna! Ora che hai riunito gli oggetti che ti aveva chiesto, ti ha rivelato di essere Teron Malacarne. Per liberarti dalla sua possessione, devi piegarti al suo volere e uccidere Karsius il Guardiano Antico.|n|nSe ci riuscirai, torna da Zorus il Giudicatore alla Roccaforte dei Granmartello.', },
  },
  [10646] = {
    'Il pupillo di Illidan',
    {'$N, hai dimostrato la tua fedeltà. Devi perdonare la mia prudenza, ma in questo mondo le cose non sono come sembrano.|n|nTi parlerò di Varedis appena ti sentirai $Gpronto:pronta;.', },
    {'Ascolta la storia di Altruis.', },
  },
  [10647] = {
    'Ricercato: Uvuros, Flagello di Torvaluna',
    {'Ricercato, morto:|n|nUvuros, Flagello della Valle di Torvaluna.|n|nPer ordine del Supremo Or\'barokh, la vilbestia Uvuros dev\'essere uccisa a vista e la sua criniera rimossa dalla carcassa come prova dell\'impresa. Portate la criniera fiammeggiante all\'Invocatore della Guerra Sardon Tagliofine qualora doveste riuscirci.|n|nUvuros è stato visto l\'ultima volta alla Mano di Gul\'dan, situata nel cuore della Valle di Torvaluna, a est del Villaggio di Torvaluna.', },
    {'Uccidi Uvuros e ottieni la Criniera Fiammeggiante di Uvuros. Portala all\'Invocatore della Guerra Sardon Tagliofine al Villaggio di Torvaluna nella Valle di Torvaluna.', },
  },
  [10648] = {
    'Ricercato: Uvuros, Flagello di Torvaluna',
    {'Ricercato, morto:|n|nUvuros, Flagello della Valle di Torvaluna.|n|nPer ordine del Thane Yoregar, la vilbestia Uvuros dev\'essere uccisa a vista e la sua criniera rimossa dalla carcassa come prova dell\'impresa. Portate la criniera fiammeggiante all\'Invocatore della Guerra Grignabirra qualora doveste riuscirci.|n|nUvuros è stato visto l\'ultima volta alla Mano di Gul\'dan, situata nel cuore della Valle di Torvaluna, a nord-est della Roccaforte dei Granmartello.', },
    {'Uccidi Uvuros e recupera la Criniera Fiammeggiante di Uvuros. Portala all\'Invocatore della Guerra Grignabirra alla Roccaforte dei Granmartello nella Valle di Torvaluna.', },
  },
  [10649] = {
    'Il Libro dei Nomi Vili',
    {'Sono solidale col tuo proposito di fermare Varedis e i suoi seguaci, ma non hai alcuna possibilità contro di lui. A meno che, naturalmente, non trovi il manufatto che lo rende tanto potente.|n|nPare che il Libro dei Nomi Vili si trovi in possesso di Cuornero l\'Agitatore, nel Labirinto delle Ombre ad Auchindoun. Recuperarlo rappresenta la tua unica speranza contro Varedis.', },
    {'Avventurati nel Labirinto delle Ombre ad Auchindoun e recupera il Libro dei Nomi Vili da Cuornero l\'Agitatore. Portata a termine questa missione, torna da Altruis a Nagrand.', },
  },
  [10650] = {
    'Ritorno dagli Aldor',
    {'Questo libro... Potrei usarlo per decuplicare il mio potere... No! Finirebbe per corrompere la mia anima, ne sono certo. Torna da coloro che ti hanno mandato qui, $N.|n|nOra sei in grado di fermare Varedis. Aspetta che si manifesti nella sua forma demoniaca e poi brucia il libro in sua presenza. È l\'unico modo per riuscire a privarlo del suo potere.', },
    {'Parla con l\'Esarca Onaala all\'Altare degli Sha\'tar nella Valle di Torvaluna.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10651] = {
    'Varedis dev\'essere fermato',
    {'Dobbiamo sbarazzarci di questo nefasto manufatto, ma non prima di averlo usato per privare Varedis dei suoi poteri.|n|nDobbiamo eliminare per sempre i campi d\'addestramento delle Rovine di Karabor. Il che non solo significa uccidere Varedis, ma anche i tre maestri degli Elfi della Notte che lo aiutano: Alandien, Theras e Netharel.|n|nForma un gruppo per l\'impresa e torna alle Rovine di Karabor. Segui le istruzioni di Altruis per sconfiggere Varedis. Spero che funzionino. Per il bene di tutti.', },
    {'L\'Esarca Onaala ti ha chiesto di recarti alle Rovine di Karabor e di uccidere Alandien, Theras, Netharel e Varedis. Utilizza il Libro dei Nomi Vili per indebolire Varedis dopo che avrà usato Metamorfosi. Una volta completata la missione, riportalo all\'Esarca Onaala.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10652] = {
    'Oltre le linee nemiche',
    {'Ho organizzato il tuo trasferimento nel nascondiglio delle nostre spie. Torna da me quando sarai $Gpronto:pronta; e potrai partire.', },
    {'Parla con Veronia quando desideri partire per la Manaforgia Coruu. Una volta là, parla con Caledis Albaluce.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10653] = {
    'I Contrassegni di Sargeras',
    {'Ormai, ti sarà chiaro perché ci opponiamo alla Legione Infuocata e a quelli che li servono.|n|nSe vuoi dimostrare il tuo valore agli Aldor, portami le insegne degli alti ufficiali della Legione e dei loro seguaci del Concilio dell\'Ombra. Puoi trovare gli ufficiali di più alto grado nella Landa Fatua e nella Valle di Torvaluna.', },
    {'Porta 10 Contrassegni di Sargeras ad Adyen il Custode della Luce a Shattrath.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10654] = {
    'Altri Contrassegni di Sargeras',
    nil,
    nil,
  },
  [10655] = {
    'Singolo Contrassegno di Sargeras',
    nil,
    nil,
  },
  [10656] = {
    'Gli Anelli con Sigillo dei Furia del Sole',
    {'Come saprai, i Veggenti e gli eserciti di Kael\'thas sono in guerra. Kael ci vede come una minaccia per la sua influenza sugli Elfi del Sangue e ha cercato più volte di schiacciarci.|n|nSe vuoi aiutarci nella battaglia contro Kael\'thas, ci sono parecchi bersagli che puoi eliminare. Gli alti ufficiali di Kael indossano anelli con sigillo dei Furia del Sole a rimarcare il loro grado. Li troverai nella Landa Fatua e nella Valle di Torvaluna.', },
    {'La Magistra Fyalenn a Shattrath ti ha chiesto di portarle 10 Anelli con Sigillo dei Furia del Sole.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10657] = {
    'Caricarsi con le scariche',
    {'Non stiamo utilizzando lo Zephyrium Capacitorium entro i limiti che ci eravamo imposti. Ma, ora che ci penso, i serpenti del Pianoro delle Scaglie a est espirano elettricità e possiedono ghiandole che potrebbero tornarci utili.|n|nHo polarizzato il Magnete per assorbire le Scariche Elettriche. Voglio che ti rechi lì, lo attivi su di te e ricavi un po\' di energia gratis da quei serpenti.', },
    nil,
  },
  [10658] = {
    'Altri Anelli con Sigillo dei Furia del Sole',
    nil,
    nil,
  },
  [10659] = {
    'Singolo Anello con Sigillo dei Furia del Sole',
    nil,
    nil,
  },
  [10660] = {
    'Che strane creature...',
    nil,
    {'Il Ricercatore Tiorus al Villaggio di Torvaluna nella Valle di Torvaluna ti ha chiesto di recuperare 8 Milze di Vilfuoco.', },
  },
  [10661] = {
    nil,
    {'Hai mai sentito parlare di un piatto che si cucina da solo e rimane caldo all\'infinito? Sarebbe un sogno!|n|nMa forse non è un sogno! Fuori dalla fortezza, vicino alle pozze e ai flussi di lava, troverai degli animali che prosperano nel caldo infuocato. Si chiamano Diemetradonti del Vilfuoco.|n|nI Nani di questa zona mi dicono che hanno la milza più gustosa che abbiano mai assaggiato ed è già praticamente precotta! Portami le milze e ti pagherò.|n|nComincia a cercare a est di qui.', },
    {'Gnomus alla Roccaforte dei Granmartello nella Valle di Torvaluna ti ha chiesto di ottenere 8 Milze di Vilfuoco.', },
  },
  [10662] = {
    'Il fabbro eremita',
    {'<Ordinn esamina il risultato dei suoi tentativi di forgiare il metallo e scuote la testa.>|n|nÈ ben oltre le mie capacità, ma questo non significa che un\'arma non possa essere riforgiata in modo che tu sia in grado di utilizzarla.|n|nC\'era un fabbro di grande talento che accompagnava i Figli di Lothar su Draenor, David Wayne. Era davvero abile, ma decise di abbandonare la spedizione. Ora, vive in un piccolo accampamento sulla penisola a est del Presidio di Alardente, nella Foresta di Terokk. Prendi questi lingotti e scopri se è in grado di aiutarti.', },
    {'Porta la Scatola di Lingotti a David Wayne al Bivacco di Wayne nella Foresta di Terokk.', },
  },
  [10663] = {
    'Il fabbro eremita',
    {'<L\'Orco scuote la testa.>|n|nÈ ben oltre le mie capacità, ma questo non significa che un\'arma non possa essere riforgiata.|n|nMi ferisce suggerirti una cosa simile, ma la nostra unica speranza potrebbe essere un fabbro umano di nome David Wayne. Un tempo faceva parte della Spedizione dell\'Alleanza, ma è stato molti anni fa e ha abbandonato i Figli di Lothar. Ora vive in un piccolo accampamento sulla penisola a est del Presidio di Alardente nella Foresta di Terokk. Portagli i lingotti e scopri se può aiutarti.', },
    {'Porta la Scatola di Lingotti a David Wayne al Bivacco di Wayne nella Foresta di Terokk.', },
  },
  [10664] = {
    'Materiali aggiuntivi',
    {'I lingotti che hai portato contenevano gran parte del metallo che mi servirà per forgiare la lama della spada, ma mi servono diverse cose per creare le altre parti dell\'arma.|n|nVediamo, mi manca una struttura d\'adamantite, del cuoio nodoso e un Totem Scaccia-Demoni. Degli artigiani in gamba dovrebbero riuscire a produrre i primi due oggetti, ma il terzo lo troverai solo dal mercante di reagenti della Città Bassa di Shattrath, Fantei. Lo troverai insieme agli altri commercianti.', },
    {'David Wayne al Bivacco di Wayne ti ha chiesto di portargli una Struttura d\'Adamantite, 4 Pezzi di Cuoio Nodoso Pesante e un Totem Scaccia-Demoni.', },
  },
  [10665] = {
    'Fresco di Mecanar',
    nil,
    nil,
  },
  [10666] = {
    'Il Dizionario Demoniaco',
    {'Sono necessari diversi incantesimi pronunciati in lingua demoniaca per ricreare gli incantamenti della lama.|n|nNon me l\'hanno insegnata durante l\'apprendistato, ma esiste un altro modo. C\'è un libro, intitolato Dizionario Demoniaco, che mi fornirà gran parte delle parole che mi servono, ma è in mano a un potente Stregone del Concilio dell\'Ombra.|n|nLo possiede il Gran Maestro Vorpil, nelle profondità del Labirinto delle Ombre di Auchindoun. Usa qualsiasi mezzo necessario per impadronirti del libro e portamelo.', },
    {'Prendi il Dizionario Demoniaco al Gran Maestro Vorpil e portalo a David Wayne al Bivacco di Wayne.', },
  },
  [10667] = {
    'Argilla del Mondo Sotterraneo',
    {'La struttura che mi hai portato non sarà sufficiente a contenere il metallo fuso se non la rinforzo. È possibile usare un raro tipo di terra per raffreddare e indurire la struttura in modo da dare all\'adamantite una resistenza fuori dal comune.|n|nI Naga considerano di grande valore l\'Argilla del Mondo Sotterraneo. Pochi la possiedono e conosco solo un Naga nelle Terre Esterne che ne fa uso: l\'Idromante Thespia, nell\'Antro dei Vapori del Bacino degli Spiraguzza.', },
    {'Prendi un\'Ampolla d\'Argilla del Mondo Sotterraneo all\'Idromante Thespia e portala a David Wayne al Bivacco di Wayne.', },
  },
  [10668] = {
    'Lotta con gli Illidari',
    {'Rispetto ancora Illidan. Senza di lui, non avrei trovato la mia strada.|n|nTuttavia, non è più quello di una volta. La sua anima è stata corrotta dal potere e la sua mente deviata dalla sconfitta. È diventato ciò che ho giurato di distruggere e i suoi tirapiedi, gli Illidari, sono abomini quanto i demoni della Legione Infuocata.|n|nComincia a perdere il controllo delle Terre Esterne, ma il suo potere è ancora grande. Dimostra di non essere in combutta con lui e uccidi il suo luogotenente Lothros al Presidio degli Illidari nella Valle di Torvaluna.', },
    {'Altruis il Sofferente ti ha chiesto di uccidere Lothros al Presidio degli Illidari nella Valle di Torvaluna.', },
  },
  [10669] = {
    'Contro ogni probabilità',
    {'Alcuni demoni giurano fedeltà solo a se stessi. Tuttavia, $Gun vero nemico:una vera nemica; dei demoni trova e distrugge la sua preda indipendentemente dal suo schieramento.|n|nIl demone Xeleth, un disertore della Legione, un tempo era venerato come un dio dalle creature primitive delle Paludi di Zangar. Quando Draenor fu quasi distrutta, si ritirò in un sonno profondo in fondo al Lago di Luceamara. Trova il portale al lago e conficca questa lancia nel terreno.|n|nXeleth si risveglierà: uccidilo e dimostra di essere $Gun nemico:una nemica; di tutti i demoni.', },
    {'Altruis il Sofferente ti ha chiesto di prendere la Lancia d\'Argento Incantata e di usarla alla Radura del Portale vicino al Lago di Luceamara nelle Paludi di Zangar per risvegliare Xeleth. Torna da Altruis dopo che avrai ucciso il demone.', },
  },
  [10670] = {
    'La Lacrima della Madre Terra',
    {'Gli incantesimi della spada devono essere contenuti in un potente catalizzatore, come una gemma. Ne conosco una che potremmo usare a questo scopo, poiché ben poche sono in grado di contenere magie tanto intense senza finire in pezzi.|n|nLa gemma di cui abbiamo bisogno si chiama Lacrima della Madre Terra. Questo manufatto è in mano agli Ogre che l\'hanno creato e l\'Araldo della Guerra O\'mrogg, che lo possiede attualmente, ha molti alleati potenti nelle Sale della Devastazione della Cittadella del Fuoco Infernale. Fai attenzione mentre cerchi di recuperare la Lacrima, $N.', },
    {'Prendi la Lacrima della Madre Terra all\'Araldo della Guerra O\'mrogg e portala a David Wayne al Bivacco di Wayne.', },
  },
  [10671] = {
    'Più di mezzo chilo di carne',
    {'$N, ho un altro incarico da assegnarti. Uno dei nostri cervelloni vuole studiare le Bestie di Carne Demoniaca che vagano per l\'Approdo di Razaan, a nord della Cresta delle Lame.|n|nPer essere più precisi, vuole la carne delle Bestie di Carne Demoniaca.|n|n<Dizzy ha un\'espressione disgustata.>|n|nOvviamente, però, non vuole sporcarsi le mani. Quello che cerca, in realtà, è della Carne Eterizzata, che non troverai in tutte le bestie.|n|nIo dico che chi mendica non dovrebbe fare anche lo schizzinoso, ma che possiamo farci?', },
    nil,
  },
  [10672] = {
    'Francamente, non ha senso...',
    nil,
    {'Il Ricercatore Tiorus al Villaggio di Torvaluna nella Valle di Torvaluna ti ha chiesto di recarti al flusso di lava vicino alle Rovine di Baa\'ri e di usare l\'Unità di Controllo Arcano per comandare uno Scorpioarcano in modo da nuotare nella lava e marcare 8 Diemetradonti Superiori del Vilfuoco.', },
  },
  [10673] = {
    'Vilspina il Grandioso',
    nil,
    nil,
  },
  [10674] = {
    'Intrappolare la luce fantastica',
    {'Gli Eterei Razaaniani stanno sperimentando un\'interessante tecnologia all\'Approdo di Razaan a nord.|n|nSono sicuro che per loro non sarà un problema se userai questa trappola per raccogliere alcuni esemplari dei loro piccoli globi di luce rosa volanti... Tanto quasi certamente non li useranno.|n|nLa trappola è tale per cui, se aperta, attira i globi verso di essa. Naturalmente attirerà anche l\'attenzione dei Razaan.', },
    nil,
  },
  [10675] = {
    'La pietà degli Gnomi',
    {'<Toshley impallidisce in volto.>|n|nQuesti Globi sono costituiti da Energia Fatua e anime... e alcune sono Anime di Gnomo!|n|nCome osano! Allora sono stati loro a uccidere gli Gnomi diretti a nord!|n|n$N, devi porre fine a questa storia e l\'unico modo per farlo è eliminare il loro capo, Razaan il Principe del Nexus.|n|nPrima, però, dovrai stanarlo. Immagino che uccidere parecchi dei suoi Eterei possa spingerlo a uscire allo scoperto.|n|nPortami la collezione di anime che senza dubbio conserva da qualche parte.', },
    nil,
  },
  [10676] = {
    'L\'Anatema degli Illidari',
    {'<David raduna i materiali da fabbro.>|n|nSei <stato/stata> in gamba a trovare tutto ciò che mi serve per forgiare la lama antidemoniaca. Il tuo duro lavoro e la tua dedizione stanno per essere ripagati.|n|nÈ giunto il momento di forgiare la spada.', },
    {'Attendi che David Wayne finisca di forgiare la tua spada.', },
  },
  [10677] = {
    'La seconda portata...',
    {'Mi pare di aver visto dei Diemetradonti più grandi a est della Mano di Gul\'dan, vicino ai flussi di lava intorno alle Rovine di Baa\'ri. Ora voglio che mi porti gli enormi stomaci di Vilfuoco degli animali di quell\'area. Potresti essere $Gcostretto:costretta; a ucciderne diversi prima di trovare lo stomaco che ti ho descritto! Non arrenderti! Uno di loro avrà pure il mio prossimo pasto.', },
    {'Gnomus alla Roccaforte dei Granmartello nella Valle di Torvaluna ti ha chiesto di ottenere uno Stomaco di Vilfuoco Enorme.', },
  },
  [10678] = {
    'La portata principale!',
    {'Per farla breve, un tempo lavoravo per un Elfo del Sangue di nome Tiorus. La nostra società si è sciolta quando ho deciso di darmi alla gastronomia e Tiorus ha deciso di continuare da solo le nostre ricerche usando le MIE invenzioni. A ogni modo, ha mandato alcuni dei suoi scagnozzi dell\'Orda a esaminare i flussi di lava delle Rovine di Baa\'ri con le mie sonde scorpioarcane e ha scoperto la madre di tutti i Diemetradonti!|n|nDevi arrivare sul posto prima di lui e uccidere il Diemetradonte, Vilspina, e portarmi la sua pelle.|n|nSbrigati!', },
    {'Gnomus alla Roccaforte dei Granmartello nella Valle di Torvaluna ti ha chiesto di ottenere la Pelle di Vilspina.', },
  },
  [10679] = {
    'Temprare la lama',
    {'La lama è quasi finita!|n|nSi riesce quasi a sentire la magia che inizia a saldarsi all\'acciaio, ma resta una cosa da fare.|n|nDevi portare la lama forgiata alle Pozze Incandescenti vicino alla vetta della Mano di Gul\'dan nella Valle di Torvaluna e immergerla nelle pozze di lava per temprare la spada. Torna da me quando l\'avrai fatto.', },
    {'Vai alle Pozze Incandescenti vicino alla vetta della Mano di Gul\'dan e tempra la Lama Forgiata dell\'Anatema degli Illidari nelle pozze di lava. Quando avrai la Lama Temprata dell\'Anatema degli Illidari, torna da David Wayne al Bivacco di Wayne.', },
  },
  [10680] = {
    'Mano di Gul\'dan',
    {'Gli elementi hanno bisogno del tuo aiuto, $R! Malefici innominabili hanno colpito la Valle di Torvaluna. Gli spiriti sono ancora torturati da essi. Molti sono infuriati e si rifiutano di comunicare con il Circolo della Terra.|n|nAiuta il mondo a guarire.|n|nA nord-est dalla Roccaforte dei Granmartello, troverai un\'area nota come Altare della Dannazione. Raggiungila e parla con il Curaterra Torlok.', },
    {'Parla con il Curaterra Torlok all\'Altare della Dannazione nella Valle di Torvaluna.', },
  },
  [10681] = {
    'Mano di Gul\'dan',
    {'Gli elementi hanno bisogno del tuo aiuto, $R! Malefici innominabili hanno colpito la Valle di Torvaluna e torturano ancora gli spiriti. Molti sono infuriati e si rifiutano di comunicare con il Circolo della Terra.|n|nAiuta il mondo a guarire.|n|nA sud-est del Villaggio di Torvaluna, nel cuore della valle omonima, troverai un\'area nota come Altare della Dannazione. Raggiungila e parla con il Curaterra Torlok.', },
    {'Parla con il Curaterra Torlok all\'Altare della Dannazione nella Valle di Torvaluna.', },
  },
  [10682] = {
    'C\'è un tempo per negoziare...',
    {'Quando arrivammo al Bosco di Ruuan, i Cultisti dei Dragoni limitavano la propria presenza alla Congrega dell\'Ala Nera, accessibile dalla galleria a ovest. Adesso, però, si stanno avvicinando.|n|nDevi trovare il sovrintendente dei Cultisti dei Dragoni. Di lui sappiamo che pattuglia con regolarità i vari accampamenti nel Bosco di Ruuan.|n|nNegozia con lui. Fagli sapere che siamo disposti ad accordarci con loro, ma che non tollereremo il massacro ingiustificato della fauna e l\'abbattimento indiscriminato degli alberi.', },
    nil,
  },
  [10683] = {
    'Le Tavolette di Baa\'ri',
    {'Illidan ha ordinato ai Corrotti Linguamorta di effettuare degli scavi nelle Rovine di Baa\'ri, nell\'estremo nord. Sicuramente cercheranno manufatti draenei. Là vi erano parecchie reliquie di Baa\'ri prima che Gul\'dan seppellisse la città sotto la lava. Dobbiamo sfruttare quest\'opportunità per recuperare le Tavolette di Baa\'ri, un antico testo che si dice contenga i segreti di Karabor... Un luogo che forse conosci come il Tempio Nero.', },
    {'L\'Arcanista Thelias al Santuario delle Stelle ti ha chiesto di recuperare 12 Frammenti di Tavoletta di Baa\'ri negli scavi e ai Lavoratori Linguamorta nelle Rovine di Baa\'ri.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10684] = {
    'Oronu l\'Anziano',
    {'Secondo le tavolette, a Baa\'ri era conservato un manufatto conosciuto come Medaglione di Karabor. Questi oggetti venivano conferiti solo ai Sacerdoti draenei in cima alla gerarchia, poiché a loro era permesso l\'accesso senza restrizioni a Karabor.|n|nDobbiamo scoprire se i Linguamorta hanno recuperato il medaglione tenuto a Baa\'ri. Il suo potere ci sarebbe di grande aiuto nella lotta contro Illidan.|n|nAkama invia giornalmente ordini scritti al suo luogotenente a Baa\'ri, Oronu l\'Anziano. Prendili e portameli.', },
    {'L\'Arcanista Thelias al Santuario delle Stelle ti ha chiesto di recuperare gli Ordini di Akama a Oronu l\'Anziano nelle Rovine di Baa\'ri.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10685] = {
    'I Corruttori Linguamorta',
    {'Secondo la lettera di Akama, quattro frammenti del medaglione sono stati ritrovati e consegnati ai Corruttori Linguamorta. Un tempo, questi temuti esseri erano Sciamani potenti in grado di corrompere gli stessi elementi che veneravano.|n|nPuoi trovare Haalum, Corruttore dell\'Aria, al Passo degli Alafatua. Eykenen e Uylaru, Corruttori della Terra e del Fuoco, sono stati visti l\'ultima volta alle Fosse Vili, vicino alla Mano di Gul\'dan. Infine, si dice che Lakaan, Corruttore dell\'Acqua, si trovi vicino al Presidio dei Malaspira.|n|nTrovali e prendi i frammenti del medaglione.', },
    {'Prendi i quattro frammenti del medaglione a Haalum, Eykenen, Lakaan e Uylaru e torna dall\'Arcanista Thelis al Santuario delle Stelle nella Valle di Torvaluna.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10686] = {
    'La Prigione della Guardiana',
    {'I frammenti che hai ottenuto formano solo metà del medaglione. Il capo dei Linguamorta, Akama, deve aver tenuto l\'altra metà.|n|nTremo all\'idea di farti una richiesta simile: Akama è tanto malvagio quanto scaltro.|n|nSi dice che lui e i Congiurati Linguamorta, la più vile e brutale delle tribù, abbiano una camera di tortura nella Prigione della Guardiana.|n|nVoglio che la trovi e che tu scopra dove si nasconde Akama. Il suo secondo in comando è un Corrotto noto come Sanoru. Interrogalo, se devi.', },
    {'L\'Arcanista Thelias ti ha chiesto di entrare nella Prigione della Guardiana, a sud delle Rovine di Baa\'ri, e di interrogare Sanoru per scoprire dove si trova Akama.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10687] = {
    'I Campi d\'Addestramento di Karabor',
    {'I nostri esploratori segnalano un massiccio flusso di reclute Elfi del Sangue dei Furia del Sole che si dirige verso le Rovine di Karabor. Di norma, rappresenterebbe una mera minaccia militare, tuttavia, crediamo che qualcosa non quadri.|n|nMi è stato comunicato che il loro abbigliamento e la loro tecnica di combattimento sono estremamente simili a quelle di Illidan in persona. Onde evitare allarmismi infondati, voglio che mi porti le loro armi. In questo modo, potremo verificare se i miei timori sono fondati o meno.', },
    {'Larissa Sferzasole al Santuario delle Stelle ti ha chiesto di recuperare 8 Lame da Guerra dei Furia del Sole ai Cacciatori di Demoni Supplicanti e ai Cacciatori Principianti di Demoni nelle Rovine di Karabor, a nord-est del Santuario delle Stelle.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10688] = {
    'Una distrazione necessaria',
    {'Le armi sono autentiche, come temevamo. Illidan sta addestrando Cacciatori di Demoni nelle Rovine di Karabor e dobbiamo impedirglielo.|n|nNon farti trarre in inganno dal loro nome, $N: il loro potere sarà usato tanto contro di noi quanto contro i demoni.|n|nI loro Stregoni evocano e soggiogano demoni per usarli nell\'addestramento delle reclute. Hanno bandito un Signore delle Fosse di nome Azaloth perché si è dimostrato troppo forte per essere usato negli addestramenti. Trova un modo per scatenarlo contro i suoi aguzzini. Dovrebbe darci il tempo che ci serve.', },
    {'Larissa Sferzasole ti ha chiesto di tornare alle Rovine di Karabor e di trovare un modo per scatenare Azaloth contro i suoi aguzzini.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10689] = {
    nil,
    nil,
    {'Vai a Nagrand occidentale e trova Altruis il Sofferente.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10690] = {
    'La Madre dell\'Antro',
    {'RICERCATA!|n|nRema, Madre dell\'Antro e principale difensore della Cresta Frastagliata a sud della Roccaforte degli Spaccatuono.|n|nPuoi trovarla uscendo dal villaggio in direzione est e superando il ponte che attraversa la Gola dei Magliorosso. Si nasconde nella galleria scavata nella parete meridionale della cresta.|n|nTorna con la notizia della sua morte dal Comandante Ombrocielo di Sylvanaar.', },
    nil,
  },
  [10691] = {
    'Ritorno dai Veggenti',
    {'Questo libro... Potrei usarlo per decuplicare il mio potere... No! Finirebbe per corrompere la mia anima, ne sono certo. Torna da coloro che ti hanno mandato qui, $N.|n|nOra sei in grado di fermare Varedis. Aspetta che si manifesti nella sua forma demoniaca e poi brucia il libro in sua presenza. È l\'unico modo per riuscire a privarlo del suo potere.', },
    {'Parla con Larissa Sferzasole al Santuario delle Stelle nella Valle di Torvaluna.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10692] = {
    'Varedis dev\'essere fermato',
    {'Ovviamente, dobbiamo disfarci di questo libro, ma non prima di averlo usato per distruggere Varedis.|n|nSe vogliamo eliminare quest\'accademia di emuli di Illidan, oltre a Varedis dovremo anche occuparci dei tre maestri Elfi della Notte che lo aiutano: Alandien, Theras e Netharel.|n|nForma un gruppo per l\'impresa e torna alle Rovine di Karabor. Segui le istruzioni di Altruis per sconfiggere Varedis. Speriamo che il suo piano funzioni. In caso contrario... è stato un piacere lavorare con te.', },
    {'Larissa Sferzasole ti ha chiesto di recarti alle Rovine di Karabor e di uccidere Alandien, Theras, Netharel e Varedis. Utilizza il Libro dei Nomi Vili per indebolire Varedis dopo che avrà usato Metamorfosi. Una volta completata la missione, riportalo a Larissa Sferzasole.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
