  [10741] = {
    'Un servizio prestato con onore',
    {'$N, non ci hai delusi. Nutriamo sempre enormi speranze in te.|n|nContinua a servire l\'Occhio Violaceo e sarai $Gricompensato:ricompensata; a dovere.', },
    {'Porta il Sigillo Violaceo all\'Arcimaga Leryda nel Valico Ventomorto dopo aver ottenuto la reputazione Riverito conl\'Occhio Violaceo.', },
  },
  [10742] = {
    nil,
    {'Ecco il nostro piano: staneremo Goc e lo uccideremo. Dopo la sua morte, gli Ogre Lamacurva non costituiranno più una minaccia per i Mok\'Nathal. Recati all\'Altare di Goc all\'esterno dell\'Antro di Gruul e suona il mio corno. Ti raggiungerò presto e insieme affronteremo il figlio di Gruul.', },
    nil,
  },
  [10744] = {
    'Notizie di vittoria',
    {'Devi informare immediatamente Kurdran Granmartello del tuo successo! I suoi uomini, sotto la guida del Comandante di Squadriglia Nuainn, hanno combattuto incessantemente per proteggere la Roccaforte dei Granmartello e il tuo ritorno gli risolleverà il morale. Ora che la minaccia della Legione è stata eliminata, Kurdran può finalmente occuparsi delle truppe di Illidan. Non siamo ancora al sicuro, ma quella di oggi è stata una grande vittoria.', },
    {'Torna alla Roccaforte dei Granmartello e parla con Kurdran Granmartello.', },
  },
  [10745] = {
    'Notizie di vittoria',
    {'Devi informare subito il Supremo Or\'barokh del successo nuostr\'! Mo\' che abbiamo schiacciato la Legione e spazzato via le truppe loro nella Valle di Torvaluna, il Supremo può volgere l\'attenzione sua verso altri nemici.|n|nAnche se la Guardia Kor\'kron nun lo ammetterà mai, staranno contenti di nun dovere più combattere su due fronti.', },
    {'Torna al Villaggio di Torvaluna e parla con il Supremo Or\'barokh.', },
  },
  [10746] = {
    nil,
    {'$N, le tue imprese sono andate al di là delle mie aspettative.|n|nTi muovi tra le pieghe del tempo con la familiarità di un Drago Bronzeo. Sei $Gdestinato:destinata; a ottenere grandi poteri e io sono più che lieta di aiutarti.|n|nContinua a servire le Scaglie delle Sabbie e io ti aiuterò a realizzare il tuo potenziale.', },
    {'Porta la tua Vera dell\'Eternità a Soridormi nelle Caverne del Tempo dopo aver acquisito la reputazione Osannato con le Scaglie delle Sabbie.', },
  },
  [10747] = {
    'Draghetti del Culto dei Dragoni',
    {'Devo esaminare i draghetti che stanno allevando alla Congrega dell\'Ala Nera.|n|nNella caverna che usano come base dovresti trovare parecchi draghetti e anche un certo numero di uova le quali, se ti avvicinerai, molto probabilmente si schiuderanno.|n|nTi prego, $N, prendi la rete e cattura un po\' di draghetti vivi.|n|nPer trovarli, dirigiti a ovest oltre il Ponte Cranio del Drago e attraverso il Tunnel Cranio del Drago. Poi segui il sentiero fino alla fine, oltre Grishna e la Selva del Corvo.', },
    nil,
  },
  [10748] = {
    'Maxnar deve morire!',
    {'Non ci hanno lasciato scelta, $N. È giunta l\'ora di mettere fine alla Congrega dell\'Ala Nera eliminando il loro capo, Maxnar la Bocca delle Ceneri.|n|nNon so se l\'hai già visto mentre ti trovavi laggiù, ma è un dragoide, mezzo umano, mezzo drago. Ed è tosto, non sottovalutarlo!|n|nFiniscilo in fretta e con un po\' di fortuna questo basterà a rendere più sicuri Boscovivo e il Bosco di Ruuan.', },
    nil,
  },
  [10749] = {
    'Il veleno del Barone Nerocrine',
    {'Ecco, porta questo a Rexxar. Sono certo che i suoi sono scopi nobili.|n|nOh, e ricordagli che ora è in debito con me.|n|nLui sa cosa desidero e sono certo che, per recuperarlo, ricorrerà al tuo aiuto prima di quanto tu pensi.|n|nOra fai $Gil bravo:la brava; e porta questo a Rexxar.', },
    {'Consegna il Veleno del Barone Nerocrine a Rexxar nella Roccaforte degli Spaccatuono nelle Montagne Spinaguzza.', },
  },
  [10750] = {
    'Il Cammino della Conquista',
    {'Ho ricevuto notizie dai miei Cavalcavento, $N. Gli Elfi del Sangue dell\'Eclisse stanno preparando qualcosa di grosso. Hanno iniziato a riunire gli eserciti al Cammino della Conquista, a sud-est, vicino al Presidio dell\'Eclisse.|n|nVoglio che tu vada al Cammino della Conquista e che valuti la situazione. Una volta fatto, usa questa spararazzi per avvertire uno dei Cavalcavento: ti raggiungerà subito. Digli cos\'hai scoperto e riceverai i tuoi prossimi ordini.', },
    nil,
  },
  [10751] = {
    'Aprire la strada',
    {'Ci serve altro tempo, $R. Devo volare più avanti con altri Cavalcavento. Speriamo di riuscire ad avere altre informazioni. Voglio che tu spiani la strada e, assai più importante, che tu faccia in modo che quelle frecce non siano puntate contro di noi!|n|nChiama un Cavalcavento con la Spararazzi dei Kor\'kron quando avrai ridotto le loro file.', },
    nil,
  },
  [10753] = {
    'Natura corrotta',
    {'Il numero delle atrocità commesse dalla Legione Infuocata è smisurato. In questo stesso momento le sue forze sono impegnate a massacrare la fauna locale, inerme di fronte alla loro potenza. $N, aiutami a fermare questi crimini contro la natura e a distruggere tutto ciò che hanno corrotto.|n|nOltre la collina, a est di qui, vedrai gli effetti di tale abominio spandersi per tutta la Gola Tagliente. Uccidi i Vilcorruttori e quanti più Vilfedeli possibili.', },
    nil,
  },
  [10754] = {
    'Ingresso nella Cittadella',
    {'<Questo nuovo stampo è stato usato per creare una chiave. Dall\'immagine intagliata sul retro, sembrerebbe trattarsi della Cittadella del Fuoco Infernale.>|n|n<Forse potrebbe interessare a Danath, il comandante delle truppe alla Rocca dell\'Onore.>', },
    {'Porta lo Stampo della Chiave al Comandante delle Forze Danath alla Rocca dell\'Onore nella Penisola del Fuoco Infernale.', },
  },
  [10755] = {
    'Ingresso nella Cittadella',
    {'<Questo nuovo stampo è stato usato per creare una chiave. Dall\'immagine intagliata sul retro, sembrerebbe trattarsi della Cittadella del Fuoco Infernale.>|n|n<Forse, potrebbe interessare a Nazgrel, capo delle truppe dell\'Orda a Thrallmar.>', },
    {'Porta lo Stampo della Chiave a Nazgrel dentro Thrallmar nella Penisola del Fuoco Infernale.', },
  },
  [10756] = {
    'Il Gran Maestro Rohok',
    {'Il simbolo sull\'impugnatura della chiave... non è facile distinguerlo nello stampo, ma appartiene ai Manomozza.|n|nCi sono buone probabilità che questa chiave ti permetta di accedere alle Sale della Devastazione.|n|nParla con Rohok, il nostro fabbro. Se qualcuno può forgiare la chiave, quello è lui.', },
    nil,
  },
  [10757] = {
    'La richiesta di Rohok',
    {'I Vilorchi Forgiatori non saranno i più esperti al mondo, ma hanno qualche asso nella manica. In questo stampo può essere fuso solo del Vilferro, altrimenti la chiave non funzionerà. Qualsiasi altro materiale, probabilmente lo distruggerebbe.|n|nPortami dei Lingotti di Vilferro, un po\' di Polvere Arcana e dei Granuli di Fuoco. Ci proverò, ma non prometto nulla.', },
    {'Porta 4 Lingotti di Vilferro, 2 Dosi di Polvere Arcana e 4 Granuli di Fuoco a Rohok dentro Thrallmar nella Penisola del Fuoco Infernale.', },
  },
  [10758] = {
    'Più rovente dell\'inferno',
    {'$N, non funziona! Per quanto carbone io possa mettere nel fuoco, il calore non è mai sufficiente.|n|nC\'è solo una cosa abbastanza calda da temprare la chiave: l\'interno dei Vilrazziatori della Legione.|n|nNe ho visto uno abbattuto solo una volta e ricordo che, mentre cadeva, ha sprigionato fumo, unito a fiamme e vapore. Prendi lo stampo e immergilo in un Vilrazziatore caduto. Se vuoi abbatterne uno, ti consiglio di portare con te alcuni amici.', },
    {'Distruggi un Vilrazziatore nella Penisola del Fuoco Infernale e immergi lo Stampo della Chiave Freddo nei suoi resti. Porta lo Stampo della Chiave Carbonizzato a Rohok dentro Thrallmar.', },
  },
  [10759] = {
    'Trova il disertore',
    {'Ho la sensazione che abbiamo tutti i pezzi, ma non riesco a metterli insieme in modo che abbiano senso.|n|nPenso che la nostra pista migliore sia quella del disertore. Se ha abbandonato i suoi compagni, c\'è la possibilità di riuscire a convincerlo ad aiutarci a capire cosa sta architettando il Conclave Oscuro Arakkoa.|n|nInizia a cercarlo lungo la strada dei Campi del Magma, a nord-ovest. È un posto plausibile dove potrebbe aver cercato rifugio.', },
    {'Trova Parshah nei Campi del Magma e parla con lui.', },
  },
  [10760] = {
    'Le rovine di Sketh\'lon',
    {'Le Rovine di Sketh\'lon, a est, sono un luogo bizzarro. I Peoni credono che siano maledette.|n|nQui ci sono pochi alberi, quindi i Peoni non hanno scelta se non andare nelle rovine arakkoa per fare legna. Gli spiriti arakkoa attaccano i gruppi di lavoro, assorbendo la loro forza vitale e usandola per alimentare i loro rituali malvagi.|n|nDobbiamo scoprire cosa nasconde il Conclave Oscuro e fermarlo prima che la sua influenza si espanda ulteriormente. Cerca prove dei loro piani nelle Rovine di Sketh\'lon.', },
    {'Recupera la Pagina 1 del Diario del Comandante di Sketh\'lon, la Pagina 2 del Diario del Comandante di Sketh\'lon e la Pagina 3 del Diario del Comandante di Sketh\'lon dal Conclave Oscuro Arakkoa nelle Rovine di Sketh\'lon e portale al Sergente Kargrul nel Villaggio di Torvaluna.', },
  },
  [10761] = {
    'Trova il disertore',
    {'Qui non c\'è nulla che spieghi perché gli spiriti degli Arakkoa siano rimasti in questo mondo o perché siano assetati di sangue orchesco.|n|nCredo che la nostra pista migliore sia cercare di trovare il disertore di cui parlava il diario. Se ha abbandonato i suoi compagni, forse abbiamo una chance di convincerlo ad aiutarci a capire cosa stanno pianificando gli Arakkoa del Conclave Oscuro.|n|nInizia a cercarlo lungo la strada che attraversa i Campi del Magma e porta a sud-est.', },
    {'Trova Parshah nei Campi del Magma e parla con lui.', },
  },
  [10762] = {
    'Il Gran Maestro Dumphry',
    {'Il simbolo sull\'impugnatura della chiave... non è facile distinguerlo nello stampo, ma appartiene ai Manomozza.|n|nCi sono buone probabilità che questa chiave ti permetta di accedere alle Sale della Devastazione.|n|nParla con Dumphry, è un maestro nella sua arte! Se non riesce lui a forgiartene una, nessuno può farlo.', },
    {'Porta lo Stampo della Chiave a Dumphry nella Rocca dell\'Onore.', },
  },
  [10763] = {
    'La richiesta di Dumphry',
    {'I Vilorchi saranno pure dei barbari, ma le loro forgiature sono meno primitive di quanto potresti immaginare. In questo stampo può essere fuso solo del Vilferro, altrimenti la chiave non funzionerà. Qualsiasi altro materiale, probabilmente lo distruggerebbe.|n|nPortami dei Lingotti di Vilferro, un po\' di Polvere Arcana e dei Granuli di Fuoco. Ci proverò, ma non prometto nulla.', },
    {'Porta 4 Lingotti di Vilferro, 2 Dosi di Polvere Arcana e 4 Granuli di Fuoco a Dumphry alla Rocca dell\'Onore nella Penisola del Fuoco Infernale.', },
  },
  [10764] = {
    'Più rovente dell\'inferno',
    nil,
    {'Distruggi un Vilrazziatore nella Penisola del Fuoco Infernale e immergi lo Stampo della Chiave Freddo nei suoi resti. Porta lo Stampo della Chiave Carbonizzato a Dumphry nella Rocca dell\'Onore.', },
  },
  [10765] = {
    'Quando i mondi si scontrano...',
    {'Al limitare meridionale del Cammino della Conquista, vicino a una carovana ferma, abbiamo scoperto quello che sembra essere un incontro tra un gigante e un cancelliere degli Elfi del Sangue. Probabilmente, anche tu avrai già notato i giganti più piccoli sul Cammino. C\'è qualcosa che non mi torna, soldato.|n|nVoglio che ti apra un varco fino all\'incontro e gli rovini la festa. Recupera tutto quello che puoi dal luogo dell\'incontro e poi chiama uno di noi con la Spararazzi.', },
    nil,
  },
  [10766] = {
    'Portale di Invasione: Cataclisma',
    {'Ora che abbiamo accesso alla base della Legione al Portale di Invasione: Cataclisma, dobbiamo capire come mettere fine alle loro attività. La Roccaforte dei Granmartello non sarà al sicuro finché non cancelleremo la presenza della Legione dalla Valle di Torvaluna.|n|nHo mandato un gruppo in avanscoperta per aiutarti a pianificare la distruzione dei rifornimenti della Legione. Torna alla Roccaforte della Legione ed entra nel teletrasporto sormontato dai cristalli verdi. Troverai Plexi ad aspettarti a destinazione.', },
    {'Presentati a rapporto da Plexi al Portale di Invasione: Cataclisma.', },
  },
  [10767] = {
    'Portale di Invasione: Cataclisma',
    {'Ora che abbiamo accesso alla base della Legione al Portale di Invasione: Cataclisma, dobbiamo capire come mettere fine alle loro attività. Il Villaggio di Torvaluna non sarà al sicuro finché non cancelleremo la presenza della Legione dalla valle.|n|nHo mandato un gruppo in avanscoperta per aiutarti a pianificare la distruzione dei rifornimenti della Legione. Torna alla Roccaforte della Legione ed entra nel teletrasporto sormontato dai cristalli verdi. Troverai Nakansi ad aspettarti a destinazione.', },
    {'Presentati a rapporto da Nakansi al Portale di Invasione: Cataclisma.', },
  },
  [10768] = {
    'Le insegne degli Illidari',
    {'I Cavalcavento devono tornare al Villaggio di Torvaluna per prepararsi alla prossima fase dell\'assalto. Ora voglio che tu recuperi le insegne indossate dagli Elfi del Sangue.|n|nQuando ne avrai prese abbastanza, chiama un Cavalcavento con la Spararazzi dei Kor\'kron. Preparati a un po\' si spionaggio, $R!', },
    nil,
  },
  [10769] = {
    'Dissenso tra i ranghi...',
    {'Il Ricercatore Tiorus è stato così gentile da preparare questa mistura per l\'attacco finale. Basta versarla sull\'insegna che mi hai portato ed essa verrà imbevuta del lerciume Illidari.|n|nPrendi l\'insegna incantata e vai ai Campi dell\'Eclisse, a sud-ovest del Presidio dell\'Eclisse. Una volta là, usa l\'insegna per tramutarti in un agente di Illidan e uccidi i Colossi Frenetici che si aggirano per il campo. Penseranno a un attacco dell\'Eclisse e taglieranno ogni legame!', },
    {'Uccidi 5 Colossi Frenetici mentre indossi il travestimento da Elfo del Sangue Illidari e torna dal Supremo Or\'barokh al Villaggio di Torvaluna nella Valle di Torvaluna. Vorrà anche che tu gli restituisca la Spararazzi dei Kor\'kron.', },
  },
  [10770] = {
    'Bosco in cenere',
    {'A nord-est di qui, sull\'altopiano sopra di noi, giacciono le ceneri della mia antica patria. Prima che la Legione Infuocata inviasse i suoi Imp a bruciarci, lì fioriva un grande bosco. Ma le vittime furono così tante che, secoli dopo, il mio vecchio e stanco cuore sente ancora il bisogno di vendicarsi. Loro sono in troppi e per noi sarà dura riconquistare quelle terre, ma tu potresti farli spaventare.|n|nMi aiuterai, vero?', },
    {'Muschiame l\'Antico ti ha chiesto di uccidere 8 Imp Fiammeggianti e poi tornare da lui al Bosco di Ruuan.', },
  },
  [10771] = {
    'Dalle ceneri',
    {'Se segui la strada a est che s\'inerpica sulla montagna e poi svolti a nord, giungerai alla mia antica patria perduta.|n|nUn tempo lì c\'era un bosco, il cui nome è dimenticato. Molto tempo fa, la Legione Infuocata evocò Imp Fiammeggianti e altre creature del fuoco. La mia patria fu distrutta e la mia gente costretta a fuggire. Solo io sono rimasto.|n|nAvevo conservato dei Semi di Ferroverde da piantare in un fertile terreno vulcanico. La loro magia è potente. Piantali per me e condividerò con te i tesori di un\'era ormai dimenticata.', },
    {'Muschiame l\'Antico ti ha chiesto di recarti a Skald, piantare i Semi di Ferroverde in tre diversi tumuli di Suolo Vulcanico Fertile e poi tornare da lui al Bosco di Ruuan.', },
  },
  [10772] = {
    'Il Cammino della Conquista',
    {'I miei Cavalieri di Grifoni sono tornati con alcune notizie! Gli Elfi del Sangue dell\'Eclisse stanno preparando qualcosa di grosso. Hanno iniziato a riunire gli eserciti al Cammino della Conquista, a est, vicino al Presidio dell\'Eclisse.|n|nVoglio che tu vada al Cammino della Conquista e che valuti la situazione. Una volta fatto, usa questo spararazzi per avvertire uno dei Cavalieri di Grifoni: ti raggiungerà subito. Digli cos\'hai scoperto e riceverai i tuoi prossimi ordini.', },
    nil,
  },
  [10773] = {
    'Aprire la strada',
    {'Ci serve altro tempo, $R. Devo volare più avanti con altri Cavalieri di Grifoni. Speriamo di riuscire ad avere altre informazioni. Voglio che tu spiani la strada e, assai più importante, che tu faccia in modo che quelle frecce non siano puntate contro di noi!|n|nChiama un Cavaliere di Grifoni con la Spararazzi dei Granmartello quando avrai ridotto le loro file.', },
    nil,
  },
  [10774] = {
    'Elfi del Sangue + giganti = ???',
    {'Al limitare meridionale del Cammino della Conquista, vicino a una carovana ferma, abbiamo scoperto quello che sembra essere un incontro tra un gigante e un cancelliere degli Elfi del Sangue. Cosa ci fanno qui i giganti? C\'è qualcosa che non mi torna, soldato.|n|nVoglio che ti apra un varco fino all\'incontro e gli rovini la festa. Recupera tutto quello che puoi dal luogo dall\'incontro e poi chiama uno di noi con la Spararazzi.', },
    nil,
  },
  [10775] = {
    'Le insegne degli Illidari',
    nil,
    nil,
  },
  [10776] = {
    'Dissenso tra i ranghi...',
    {'Gnomus è stato così gentile da preparare questa mistura per l\'attacco finale. Basta versarla sull\'insegna che mi hai portato ed essa verrà imbevuta del lerciume Illidari.|n|nPrendi l\'insegna incantata e vai ai Campi dell\'Eclisse, a sud-ovest del Presidio dell\'Eclisse. Una volta là, usa l\'insegna per tramutarti in un agente di Illidan e uccidi i Colossi Frenetici che si aggirano per il campo. Penseranno a un attacco dell\'Eclisse e taglieranno ogni legame!', },
    {'Uccidi 5 Colossi Frenetici mentre indossi il travestimento da agente di Illidan e torna dal Thane Yoregar alla Roccaforte dei Granmartello nella Valle di Torvaluna. Vorrà anche che tu gli restituisca la Spararazzi dei Granmartello.', },
  },
  [10777] = {
    'Il totem di Asghar',
    {'Quanto hai letto nel diario del comandante è vero. Mentre l\'Orda orchesca si riuniva sotto Gul\'dan, il mio popolo cercò di difendersi dalla minaccia attaccandolo. Gul\'dan scoprì le loro intenzioni e lanciò un potente incantesimo che distrusse i nostri accampamenti e distorse gli spiriti dei miei fratelli.|n|nDevono essere fermati prima che scatenino un male ancora più grande. Cerca Asghar nelle Rovine di Sketh\'lon, a nord, e portami il totem che porta con sé. Con quello, potremo iniziare a intralciare i piani del Conclave Oscuro.', },
    {'Porta il Totem di Guerra di Sketh\'lon a Parshah nei Campi del Magma.', },
  },
  [10778] = {
    'La Verga di Lianthe',
    {'Il totem da solo non è sufficiente a contrastare i sinistri incantesimi del Conclave Oscuro.|n|nDobbiamo combinarlo con altri oggetti di potere, formando un bastone per focalizzare le energie. Non possiamo salvare i miei fratelli dagli abissi della loro depravazione, ma possiamo fermarli.|n|nUno degli oggetti che mi servono per il bastone è la Verga di Lianthe, in possesso degli Elfi del Sangue al Presidio dell\'Eclisse, a sud-est. La tengono in un padiglione nel livello più alto delle rovine e sarà sotto stretta sorveglianza. Fai attenzione, $N.', },
    {'Prendi la Chiave di Lianthe a un Elfo del Sangue al Presidio dell\'Eclisse e usala per aprire il Forziere di Lianthe e recuperare la Verga di Liante. Portala a Parshah nei Campi del Magma.', },
  },
  [10780] = {
    'Le piume di Sketh\'lon',
    {'Resta solo un oggetto da trovare per creare il bastone. Dobbiamo convogliare il potere del bastone verso gli spiriti del Conclave Oscuro.|n|nE possiamo farlo raccogliendo le piume sparse sul terreno al Campo Base di Sketh\'lon e unendole al bastone. Il campo base si trova a sud, a est della Roccaforte dei Granmartello.|n|nLa magia di Gul\'dan ha completamente distrutto i miei fratelli, lasciandone solo gli spiriti, ma non solo. Si è nutrita degli incantesimi che gli Arakkoa stavano preparando, plasmando una forza sinistra che ha inglobato gli spiriti.', },
    {'Trova 8 Piume di Sketh\'lon e portale a Parshah nei Campi del Magma.', },
  },
  [10781] = {
    'La battaglia della Terrazza Cremisi',
    {'Probabilmente ti stanno già cercando lungo il Cammino della Conquista. Devi fuggire, $R!|n|nLasciami qui, sono finito... Credo... Credo che stiano arrivando. Ora o mai più! Vattene! Se rimarrai, dovrai combattere!|n|nSe combatterai e riuscirai a sopravvivere, comunica quanto hai appreso qui ad A\'dal a Shattrath.', },
    {'Affronta le truppe di Illidan alla Terrazza Cremisi e sopravvivi!|n|nTorna da A\'dal a Shattrath qualora dovessi trionfare.', },
  },
  [10782] = {
    'Energizzare il pomolo',
    {'Il bastone è quasi ultimato!|n|nNon resta che infondere nel pomolo il potere che fluisce dagli echi di Gul\'dan in questo posto maledetto. A est, vicino alle Fosse Vili e a sud di Forgiamorte, troverai l\'Altare della Dannazione.|n|nLà, sono intrappolati dei frammenti del passato di Gul\'dan. Quando porterai il Pomolo Incompiuto nell\'area vicino all\'altare, non essere $Gsorpreso:sorpresa; se alcune entità reagiscono a esso. Quello che porti con te è un pericoloso oggetto fortemente legato al Cataclisma.', },
    nil,
  },
  [10783] = {
    'Il Barone Nerocrine',
    {'Ecco il mio piano: avveleneremo gli Ogre e poi distruggeremo il Gronn loro signore.|n|nNel corso della mia esplorazione di queste montagne, una volta incontrai Barone Nerocrine, un maestro delle arti alchemiche. Forse potremo convincerlo a collaborare con noi.|n|nLo troverai al Cerchio del Sangue, giù nel canyon, a nord di qui. Qualunque cosa ti chieda in cambio, lascio a te la decisione se accettare o no il suo aiuto.', },
    {'Parla con il Barone Nerocrine al Cerchio del Sangue nelle Montagne Spinaguzza.', },
  },
  [10784] = {
    'Assalto all\'Accampamento dei Magliorosso!',
    {'<Tor\'chunk si sporge per sussurrarti qualcosa.>|n|n$N, con le tue imprese contro gli Ogre ci hai reso tutti più che orgogliosi di te. E anche se ho piena fiducia nel piano di Rexxar, ti chiederei di massacrare ugualmente gli Ogre dell\'Accampamento dei Magliorosso prima di tornare.|n|nIn questo modo saremo doppiamente certi del buon esito della missione.|n|nPer raggiungerli, dirigiti a nord e scendi giù per la discesa, uscendo da Spaccatuono, quindi prosegui verso ovest attraversando la Caduta dei Draghi e verso nord oltre la Gola Brulicante e il Canyon delle Fauci Aguzze.', },
    nil,
  },
  [10785] = {
    'È una trappola!',
    {'A questo mondo non c\'è per me motivo di maggior collera di Gruul e dei suoi figli. Hanno massacrato la mia gente e i miei figli. È giunto il momento di vendicarsi!|n|nHo realizzato una trappola usando il fuoco di drago. Se sei abbastanza $Gastuto:astuta;, con essa dovresti poter uccidere un Gronn.|n|nSbrigati, porta la trappola a Rexxar. La mia sete di vendetta deve essere appagata!', },
    {'Consegna la Trappola di Dragonfuoco a Rexxar nella Roccaforte degli Spaccatuono nelle Montagne Spinaguzza.', },
  },
  [10786] = {
    'Massacro a Bolde\'mok',
    {'So che Rexxar intende inviarti a Bolde\'mok. Già che ti troverai lì, avrei una cosa da chiederti.|n|nDobbiamo sfruttare ogni occasione possibile per sbarazzarci degli Ogre di queste montagne, o saranno loro a sopraffarci e tutto il nostro sangue versato non sarà valso a nulla!|n|nBolde\'mok si trova a nord-ovest. Dirigiti verso nord fino al Bosco di Ruuan e da lì prosegui verso ovest, attraversando la galleria e la Selva del Corvo.|n|n$N, voglio che tu uccida gli Ogre Lamacurva di Bolde\'mok. Spazzali via!', },
    nil,
  },
  [10789] = {
    'Torna da Carendin Halgar',
    {'Ah, eccoti, $N.|n|nCarendin Halgar ha chiesto che tu vada da lui nel Quartiere della Magia di Sepulcra. Non è famoso per la pazienza, quindi eviterei di farlo aspettare.', },
    {'Parla con Carendin Halgar a Sepulcra.', },
  },
  [10791] = {
    'Accogliere lo Spirito Lupo',
    {'Ho quasi completato il paramento che indosserò durante la cerimonia. Mentre finisco gli ultimi ritocchi, vorrei che usassi questo incenso con le candele vicino alla pietra runica alla mia sinistra.|n|nCredo che ci aiuterà ad attirare l\'attenzione dello Spirito Lupo, dal momento che è stato creato ai tempi dei clan orcheschi. Riesco quasi a immaginare i miei antenati mentre lo usano nel corso di una cerimonia per onorare lo Spirito Lupo dopo una caccia fruttuosa.|n|nComincerò la cerimonia quando avrai posizionato l\'incenso.', },
    {'Usa l\'Incenso Cerimoniale vicino alle candele nel capanno di Malukaz e osserva la cerimonia. Una volta terminata, parla di nuovo con Malukaz.', },
  },
  [10792] = {
    'Zeth\'gor deve bruciare!',
    {'Il Clan Guerci Insanguinati ha tradito il nostro nobile retaggio! Noi, gli Orchi che hanno combattuto e sono morti per salvarsi dalla vile corruzione di Mannoroth, guardiamo i nostri indegni cugini e vediamo solo debolezza e ignominia. Per questo, devono bruciare!|n|nEntra a Zeth\'gor, il loro Bastione a est, e brucia gli edifici. Uccidi i Peoni per impadronirti delle loro torce, accendile alla Forgia e lanciale contro i Tuguri, la Scuderia e la Caserma. Brucia tutto e poi torna da me!|n|nPer l\'Orda!', },
    {'Uccidi i Peoni dei Guerci Insanguinati, prendi le loro torce, accendile alla Forgia di Zeth\'gor e lanciale contro gli edifici.', },
  },
  [10793] = {
    'Il diario di Val\'zareq: presagi di guerra',
    {'Questo diario documenta le recenti attività dell\'esercito di Illidan. Spiega anche perché Val\'zareq girasse baldanzoso per il Cammino della Conquista. Era personalmente responsabile della cattura di un Gran Generale degli Sha\'tar.|n|nÈ tenuto prigioniero in un luogo noto come la Terrazza Cremisi, situato al limitare meridionale del Cammino della Conquista. Una misteriosa fazione che si fa chiamare il Sigillo Cremisi si occupa della sua incarcerazione. È meglio che ti porti degli alleati, qualora tu decida di indagare.', },
    {'Trova Marcus Auralion, Gran Generale degli Sha\'tar, alla Terrazza Cremisi. Cerca in una prigione di cristallo.', },
  },
  [10795] = {
    'Un appuntamento con Dorgok',
    {'Bene, ti avevo già $Gnotato:notata; in giro e prima o poi sarei venuto a parlarti di una questione di una certa importanza.|n|nIn base ad alcuni rapporti, gli Ogre Magliorosso starebbero pianificando un\'offensiva contro Sylvanaar e il Bosco di Ruuan. Non sappiamo chi o cosa li stia spingendo a farlo, ma sappiamo che questo piano va sventato sul nascere!|n|nGli assalti partiranno dall\'Accampamento dei Magliorosso. Per raggiungerlo, dirigiti a nord-ovest giù per la discesa che esce dal Bosco di Ruuan. Voglio che tu uccida il loro capo, Dorgok!', },
    nil,
  },
  [10796] = {
    'Assalto all\'Accampamento dei Magliorosso!',
    {'Ho saputo delle tue gloriose imprese contro gli Ogre. Per questo ti chiederei di affrontarli di nuovo: devi schiacciare una volta per tutte quelli dell\'Accampamento dei Magliorosso!|n|nPer giungere fin laggiù, vai verso nord-ovest e prendi la strada in discesa che esce dal Bosco di Ruuan. Li troverai alla base della discesa.|n|nBuona fortuna, $C!', },
    nil,
  },
  [10797] = {
    'Nelle grazie dei Gronn',
    {'<Un emblema sotto forma di statuetta scivola a terra dalle mani senza vita di Dorgok. La somiglianza con i Gronn è notevole.>|n|n<Di certo il Comandante Haephus Pietramuro di Boscovivo nel Bosco di Ruuan, in fondo alla salita a est, lo troverebbe molto interessante!>', },
    {'Consegna la Predilezione di Gorgrom al Comandante Haephus Pietramuro a Boscovivo nelle Montagne Spinaguzza.', },
  },
  [10798] = {
    'Una visita al Barone',
    {'Questa è una brutta notizia. Dietro ai recenti piani di assalto a Sylvanaar dei Magliorosso c\'è Gorgrom il Mangiadraghi!|n|nNon so perché stia manipolando i Lamacurva e non semplicemente usandoli. Ma se dobbiamo affrontare i Gronn, abbiamo bisogno d\'aiuto.|n|nConosco un tizio molto competente in ogni sorta di magia esotica, il Barone Nerocrine. Puoi trovarlo al Cerchio del Sangue, scendendo giù per la discesa a nord-ovest e poi proseguendo a sud-ovest attraverso il canyon.|n|nChiedigli di progettare una trappola per i Gronn.', },
    nil,
  },
  [10799] = {
    'Nella Gola Brulicante',
    {'Molto bene. Realizzerò questa trappola, ma prima voglio qualcosa in cambio.|n|nGuarda caso c\'è un Gronn qui vicino in possesso di un oggetto che desidero, anche se tu non puoi affrontarlo... non ora, perlomeno.|n|nPer questo motivo prepareremo una polvere soporifera dal veleno degli Spaccacrosta.|n|nTroverai gli Spaccacrosta nella Gola Brulicante a sud-ovest. Portami un po\' delle loro ghiandole e cerca di fare alla svelta!', },
    nil,
  },
  [10800] = {
    'Buonanotte, Gronn',
    {'Ancora una volta, mi sono superato. Ho preparato una polvere soporifera da utilizzare su Grulloc, il Gronn in possesso di quell\'oggetto di cui ti dicevo.|n|nGrulloc risiede nell\'Anfratto Maledetto, un\'area nell\'estremità orientale della Caduta dei Draghi, dalla parte opposta del Cerchio del Sangue.|n|nSe fossi in te, non perderei troppo tempo dopo aver raccolto la sua sacca. Gli effetti della polvere non dureranno a lungo.', },
    nil,
  },
  [10801] = {
    'È una trappola!',
    {'Non c\'è nulla che odi di più a questo mondo dei figli di Gruul e del loro padre! Hanno massacrato la mia gente e i miei figli. È giunto il momento di vendicarsi!|n|nHo realizzato una trappola usando il fuoco di drago. Se sei abbastanza $Gastuto:astuta;, con essa dovresti poter uccidere un Gronn.|n|nSono certo che hai già un\'idea su chi uccidere, ma non m\'importa saperlo. Sbrigati: porta la trappola al tuo Comandante Pietramuro.|n|nLa mia sete di vendetta deve essere appagata!', },
    {'Consegna la Trappola di Dragonfuoco al Comandante Haephus Pietramuro nell\'avamposto di Boscovivo nelle Montagne Spinaguzza.', },
  },
  [10802] = {
    'Gorgrom il Mangiadraghi',
    {'Dobbiamo dimostrare agli Ogre che non possono metterci i piedi in faccia. Dobbiamo mandar loro un messaggio.|n|nRaggiungi Bolde\'mok e uccidi gli Ogre del luogo. Ricordati di recuperarne le teste.|n|nPoi recati all\'Altare di Gorgrom e colloca lì la trappola. Quando Gorgrom apparirà, dovrai attirarlo nella trappola. Dopo averlo ucciso, pianta dei Totem Raccapriccianti accanto al suo cadavere, in modo che gli Ogre possano guardare il loro capo e i loro fratelli caduti e sapere che con noi non si scherza.', },
    nil,
  },
  [10803] = {
    'Massacro a Bolde\'mok',
    {'So che siamo in procinto di inviarti a Bolde\'mok. Già che ti troverai lì, avrei una cosa da chiederti.|n|nDobbiamo sfruttare ogni occasione possibile per sbarazzarci degli Ogre di queste montagne, o saranno loro a sopraffarci e tutto il nostro sangue versato non sarà valso a nulla!|n|nBolde\'mok si trova a ovest. Dirigiti verso sud-ovest, attraversa il ponte e poi la galleria. All\'estremità occidentale della Selva del Corvo troverai gli Ogre Lamacurva di Bolde\'mok.|n|nSpazzali via, $N.', },
    nil,
  },
  [10804] = {
    nil,
    {'Qualcosa li ha spaventati, $R.|n|n<Mordenai indica i Drachi Fatui che volteggiano sopra di voi.>|n|nNon scendono nemmeno per mangiare. Ne ho visti diversi precipitare, morti per lo sfinimento ancor prima che toccassero terra.|n|nDobbiamo salvarli! Gli Scorticatori Unghiaroccia che si trovano vicino ai cristalli sono le loro prede naturali. Uccidili e prendi le loro carcasse. Posizionane una sul campo e rimani perfettamente immobile. Non ti attaccheranno se non farai movimenti aggressivi.', },
    {'Mordenai ai Campi degli Alafatua nella Valle di Torvaluna ti ha chiesto di nutrire 8 Drachi Alafatua Adulti.', },
  },
  [10805] = {
    'Massacro nell\'Antro di Gruul',
    {'Hai dimostrato un certo ingegno e ho quindi pensato di usarti nella mia battaglia personale contro Gruul e i suoi figli.|n|nIl Clan Lamacurva gode del favore dei Gronn e, anche se ne hai ridotto il numero altrove, devi ancora affrontare i loro elementi più forti.|n|nPer proteggere l\'ingresso del suo antro, Gruul si serve solo degli Ogre più forti e sono questi che dovrai uccidere. Attraversa il Canyon delle Fauci Aguzze a nord e in fondo a esso troverai l\'Antro di Gruul.', },
    nil,
  },
  [10806] = {
    nil,
    {'È giunta l\'ora di affrontare Goc, il signore degli Ogre Lamacurva. È anche giunta l\'ora che io prenda in mano la situazione ed elimini il Gronn personalmente.|n|nPrendi il mio anello con sigillo. Una volta $Ggiunto:giunta; all\'Altare di Goc, usalo e io ti raggiungerò.|n|nInsieme annienteremo Goc.', },
    nil,
  },
  [10807] = {
    'I Corrotti Linguamorta',
    {'Tutti i Corrotti temono la Tribù Linguamorta. È formata dagli individui più malvagi e assetati di sangue, scelti personalmente da Akama. Sono feroci e spietati quanto qualsiasi Naga, demone o Elfo del Sangue dell\'esercito di Illidan e sono stati schierati in massa alle Rovine di Baa\'ri, a nord. Recati là e riduci le loro file prima che abbiano la possibilità di attaccarci.', },
    {'Varen il Bonificatore ti ha chiesto di recarti alle Rovine di Baa\'ri e di uccidere 3 Addestratori Linguamorta, 4 Guerrieri Linguamorta e 6 Sciamani Linguamorta.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10808] = {
    'Ostacola il Conclave Oscuro',
    {'Gli spiriti del Conclave Oscuro cercano di evocare un antico e potente essere malvagio con un rituale condotto nelle fosse di lava a sud del Campo Base di Sketh\'lon.|n|nLa magia di Gul\'dan si è mescolata alla loro, dandogli il potere di aiutare questa creatura a entrare nel nostro mondo! Non possiamo permetterlo, $N. La morte e la distruzione che porterebbe sono inimmaginabili!|n|nPorta il bastone al luogo dell\'evocazione e usa la sua magia per fermare per sempre il Conclave Oscuro!', },
    {'Uccidi i Ritualisti del Conclave Oscuro e usa il Bastone di Parshah per porre fine al rituale d\'evocazione del Conclave Oscuro. Quindi, torna da Parshah nei Campi del Magma.', },
  },
  [10809] = {
    'Ricercato: Maestro dei Worg Kruush',
    {'Sul manifesto c\'è scritto:|n|n"Il Maestro dei Worg Kruush guida i Predoni Worg del Clan Guerci Insanguinati. C\'è una taglia sulla sua testa, poiché i suoi predoni razziano le carovane dei rifornimenti dirette al Presidio di Frangiguglia".|n|n"Gli esploratori lo hanno visto all\'interno di Zeth\'gor. Chi mi porterà la sua testa, otterrà una bella ricompensa e la gratitudine di tutta l\'Orda".|n|n"Capitano Urlonero"', },
    {'Uccidi il Maestro dei Worg Kruush e porta la sua testa al Capitano Urlonero nel Presidio di Frangiguglia.', },
  },
  [10810] = {
    'Maschera danneggiata',
    {'<Mentre esamini la maschera danneggiata, senti provenire degli strani suoni dal suo interno. Se la maschera fosse integra, potresti distinguere i suoni più chiaramente.>|n|n<O\'Mally Occhiofino al Bosco di Ruuan potrebbe aiutarti a ripararla.>', },
    nil,
  },
  [10811] = {
    'Cerca Neltharaku',
    {'Il loro signore vola alto nel cielo, $N. Forse, la gentilezza che hai mostrato verso i suoi figli l\'ha commosso. Cerca Neltharaku e chiedi il suo aiuto. Insieme, riuscirete a eliminare ciò che affligge i Drachi Alafatua.|n|n<Mordenai indica il cielo.>|n|nVola nel cielo...', },
    {'Cerca Neltharaku, Signore dello Stormo dei Draghi di Alafatua.', },
  },
  [10812] = {
    'La Maschera Misteriosa',
    {'Bene, adesso dovrebbe funzionare. Vuoi sapere di che si tratta, eh? Be\', è un dispositivo di comunicazione: permette a quegli idioti della Legione Infuocata di comunicare l\'uno con l\'altro. Ti consiglio di portare la maschera al Signore della Selva Antelarion. Si trova laggiù e non sta mai fermo.|n|nBe\', sbrigati: è parecchio tempo ormai che tenta di mettere le mani su una di queste.', },
    nil,
  },
  [10813] = {
    'Gli Occhi di Grillok',
    {'$N, sei $Gentrato:entrata; nell\'antro degli Orchi Guerci Insanguinati, hai sconfitto Zeth\'gor e sei $Grimasto:rimasta; in vita per raccontarlo! Forse possiedi la forza necessaria per aiutarmi. Voglio scrutare nei pensieri dello Sciamano più oscuro: Grillok!|n|nPrendi questo cristallo: usalo per stregare un Occhio di Grillok e vincolalo al tuo corpo. Torna qui e avvicinati al mio calderone, che prenderà l\'Occhio.|n|nOra va\', $N, e fa\' attenzione: se si aprirà anche solo di uno spiraglio, l\'Occhio di Grillok ti tradirà, consegnandoti ai nemici!', },
    {'Usa i Cristallo di Zezzak per catturare un Occhio di Grillok, poi avvicinati al Calderone di Zezzak per estrarlo. Dopo che l\'Occhio sarà stato rimosso, riconsegna il Cristallo a Zezzak.', },
  },
  [10814] = {
    'La storia di Neltharaku',
    {'Ho delle informazioni che potrebbero esserti utili. Ascolta quanto ho da raccontare, $R.', },
    {'Parla con Neltharaku e ascolta la sua storia.', },
  },
  [10815] = {
    'Il diario di Val\'zareq: presagi di guerra',
    {'Questo diario documenta le recenti attività dell\'esercito di Illidan. Spiega anche perché Val\'zareq girasse baldanzoso per il Cammino della Conquista. Era personalmente responsabile della cattura di un Gran Generale degli Sha\'tar.|n|nÈ tenuto prigioniero in un luogo noto come la Terrazza Cremisi, situato al limitare meridionale del Cammino della Conquista. Una misteriosa fazione che si fa chiamare il Sigillo Cremisi si occupa della sua incarcerazione. È meglio che ti porti degli alleati, qualora tu decida di indagare.', },
    {'Trova Marcus Auralion, Gran Generale degli Sha\'tar, alla Terrazza Cremisi.', },
  },
  [10816] = {
    'Riconquistare le terre sacre',
    {'Hai dimostrato coraggio contro i Corrotti a Baa\'ri, $N. Vediamo come te la cavi contro l\'esercito di Illidan più temuto.|n|nI Vilorchi del Clan Torvaluna occupano la Terrazza di Ata\'mal, un tempo luogo sacro dove i cristalli di Ata\'mal erano utilizzati in cerimonie spirituali.|n|nAbbiamo ragione di credere che nascondano un cristallo di Ata\'mal nelle vicinanze, ma non abbiamo scoperto nulla con la chiaroveggenza. Ciò nonostante, i Vilorchi insozzano le terre sacre dei Draenei e devono essere eliminati.', },
    {'Il Vendicatore Aluumen ti ha chiesto di uccidere 8 Sicari di Torvaluna, 8 Prescelti di Torvaluna e 4 Mistici Oscuri di Torvaluna.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10817] = {
    'Sommo castigo',
    {'Hai dimostrato abilità contro i Corrotti Linguamorta, $N. Ho un\'altra sfida da proporti, se te la senti.|n|nNon molto tempo fa, il Santuario delle Stelle subì un pesante attacco da parte dei Vilorchi di Illidan.|n|nAbbiamo scoperto che questo attacco fu scatenato dagli Orchi di Torvaluna che occupano la Terrazza di Ata\'mal.|n|nMostra loro che non bisogna sfidare i Veggenti.', },
    {'Varen il Bonificatore ti ha chiesto di uccidere 8 Sicari di Torvaluna, 8 Prescelti di Torvaluna e 4 Mistici Oscuri di Torvaluna.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10818] = {
    'Convocazione dal Barone Nerocrine',
    {'$N, mentre eri $Gimpegnato:impegnata; là fuori a seminare morte, il Barone Nerocrine ha inviato quassù il suo drago domestico con un messaggio.|n|nIl Barone ha chiesto espressamente di te. A quanto ho capito, vuole che tu lo vendichi contro i Gronn.|n|nA mio parere, in tutte le Terre Esterne sei certamente l\'individuo più qualificato, ma se fossi in te chiederei il supporto di un paio di amici prima di recarmi al Cerchio del Sangue.', },
    nil,
  },
  [10819] = {
    'Maschera Antigas dei Vilfedeli',
    nil,
    nil,
  },
  [10820] = {
    'Ingannare il nemico',
    {'Sappi che ogni momento in più di silenzio ti avvicina alla morte! PARLA!|n|nCosa? Fornace Collera è in rivolta? Non può essere! I miei seguaci non oserebbero mai sottrarsi alla mia autorità.|n|nMolto bene, allora. Pagheranno a caro prezzo questa insubordinazione. Mettili tutti a tacere e chiudi la questione! Ricontattami quando avrai finito o ne pagherai anche tu le conseguenze.', },
    nil,
  },
  [10821] = {
    'Sei licenziata!',
    {'Urlarovina non ha fatto nulla per fermare la rivolta? Come ha osato! Era già da qualche tempo che provava a minare la mia autorità. Adesso, però, ha superato ogni limite. Convocala da te e finiscila di persona.|n|nLe chiavi per evocarla a Fornace Collera sono in possesso delle sue Guardie della Collera. Recupera le cinque chiavi e attiva i cinque obelischi della Legione. Gli obelischi non rimangono attivi per molto, quindi assicurati di attivarli tutti contemporaneamente. Ricorda: puoi sempre recuperare altre chiavi dalle Guardie della Collera.', },
    nil,
  },
  [10822] = {
    'Singolo Anello con Sigillo dei Furia del Sole',
    nil,
    nil,
  },
  [10823] = {
    'Altri Anelli con Sigillo dei Furia del Sole',
    nil,
    nil,
  },
  [10824] = {
    'Gli Anelli con Sigillo dei Furia del Sole',
    {'Per sopravvivere, i Veggenti devono reclutare più soldati di Kael\'thas. Ogni pellegrino di Quel\'Thalas che si unisce a lui, lo fa avvicinare sempre di più alla vittoria. E il contrario vale per noi.|n|nPresto, tuttavia, non troveremo più reclute e tutto si ridurrà a chi riesce a uccidere prima la fazione opposta. Dimostra il tuo valore ai Veggenti portandomi gli Anelli con Sigillo dei Furia del Sole indossati dagli Elfi del Sangue di alto grado alleati con Kael\'thas e Illidan. Li troverai al Presidio dell\'Eclisse, a ovest, e nelle Rovine di Karabor, a nord-est.', },
    {'La Maga Guerriera Vyara al Santuario delle Stelle ti ha chiesto di portarle 10 Anelli con Sigillo dei Furia del Sole.|n|nCompletando questa missione per i Veggenti, il tuo livello di reputazione presso gli Aldor diminuirà.', },
  },
  [10825] = {
    'La verità dal globo',
    {'<Dalle piume di Arakkoa cade uno strano globo magico.>|n|n<Il globo, che emana una violacea luce sinistra, pulsa seguendo un ritmo silenzioso. Tenerlo in mano ti provoca un certo disagio, per cui lo collochi rapidamente in una delle tue sacche.>|n|n<Pensi che il Custode degli Alberi Chawn nel Bosco di Ruuan a ovest, oltre il Tunnel e il Ponte Cranio del Drago, potrebbe essere interessato a esaminarlo.>', },
    nil,
  },
  [10826] = {
    'I Contrassegni di Sargeras',
    {'Ormai, ti sarà chiaro perché ci opponiamo alla Legione Infuocata e a quelli che li servono.|n|nSe vuoi dimostrare il tuo valore agli Aldor, portami le insegne degli alti ufficiali della Legione e dei loro seguaci del Concilio dell\'Ombra. A Torvaluna, troverai truppe della Legione a ovest della Roccaforte della Legione e a Forgiamorte.', },
    {'Porta 10 Contrassegni di Sargeras all\'Araldo Saronen nella Valle di Torvaluna.|n|nCompletando questa missione per gli Aldor, il tuo livello di reputazione presso i Veggenti diminuirà.', },
  },
  [10827] = {
    'Altri Contrassegni di Sargeras',
    nil,
    nil,
  },
  [10828] = {
    'Singolo Contrassegno di Sargeras',
    nil,
    nil,
  },
  [10829] = {
    'Ramonest deve sapere',
    {'Questo è preoccupante! Gli Arakkoa stanno facendo sì che gli Antichi e i Protettori vengano posseduti da spiriti maligni!|n|nC\'è però un Antico che non può essere stato posseduto. Si chiama Ramonest. Se vogliamo salvare gli alberi della Selva del Corvo, devi andare subito da lui!|n|nTorna alla Selva del Corvo. Ramonest si trova all\'incrocio poco dopo Grishna.', },
    nil,
  },
  [10830] = {
    'Esorcizzare gli alberi',
    {'I Grishna hanno fatto sì che i Barbafoglia e gli Scorzapietra fossero posseduti dagli Spiriti Koi-Koi.|n|nDobbiamo salvare gli alberi o presto l\'intera Selva del Corvo sarà persa sempre!|n|nInfondi la magia delle Sfere di Grishna, che puoi trovare a Grishna, nelle Metapiume di Metacorvo.|n|nUsa le Piume per Esorcismo così ottenute per richiamare e uccidere gli Spiriti Koi-Koi il più velocemente possibile. Gli Scorzapietra sono troppo potenti per questo rituale, ma se salverai abbastanza Barbafoglia, gli Scorzapietra seguiranno.', },
    nil,
  },
  [10834] = {
    'Grillok &quot;Occhionero&quot;',
    nil,
    nil,
  },
  [10835] = {
    'Lo Speziale Antonivich',
    {'$N, ho stilato un rapporto preliminare delle mie scoperte sugli Orchi Guerci Insanguinati. Il mio collega di Thrallmar, lo Speziale Antonivich, sarà felice di leggerlo. Anche lui studia il fenomeno dei Vilorchi, nella speranza di prevenire una disgrazia del genere per i nostri alleati orcheschi.|n|nConsegnagli il rapporto, mentre io proseguo l\'esame del sangue che mi hai portato. Se la fortuna ci assiste, isoleremo la causa dell\'infezione dei Vilorchi.', },
    nil,
  },
  [10836] = {
    'Infiltrarsi nella Fortezza delle Fauci di Drago',
    {'Mi serve tempo per ideare un piano per salvare i miei figli e la mia compagna. Sarai tu a darmelo, mortale.|n|nEntra nella Fortezza delle Fauci di Drago, al confine orientale dei Campi degli Alafatua, e uccidi tutti gli Orchi delle Fauci di Drago che trovi. Il caos e la confusione che provocherai dovrebbero avere un certo impatto sui loro piani.|n|nFai attenzione: per alcuni miei simili non c\'è più speranza, le loro menti sono state corrotte dalle Fauci di Drago. Per loro, non resta che la morte. Hai il mio permesso di porre fine alle loro vite.', },
    {'Neltharaku, che vola sopra i Campi degli Alafatua nella Valle di Torvaluna, ti ha chiesto di uccidere 15 Orchi delle Fauci di Drago.|n|nVa bene qualsiasi Orco delle Fauci di Drago che troverai nella fortezza.', },
  },
  [10837] = {
    'Verso l\'Isola degli Alafatua!',
    {'Credo di poter infondere la mia essenza nei Cristalli di Cespofatuo. Il potere contenuto nei cristalli dovrebbe essere sufficiente per liberare i drachi schiavizzati dalle grinfie dei loro padroni.|n|nVai sull\'Isola degli Alafatua, situata dove la regione di Valle di Torvaluna si è spezzata, a sud-est. È sull\'Isola degli Alafatua che troverai i Cristalli di Cespofatuo. Torna da me quando avrai raccolto abbastanza cristalli da riempire le tue sacche.|n|n$N, fai attenzione. Ora è abitata dalle Fauci di Drago.', },
    nil,
  },
  [10838] = {
    'Il Veggente Demoniaco',
    {'Il Veggente Demoniaco è pronto. Portalo nella Conca del Fuoco Infernale, dietro la Cittadella del Fuoco Infernale, ed evocalo. Inizierà a entrare in sintonia con la Cittadella del Fuoco Infernale. Quando avrà finito, parlagli, trascrivi tutto ciò che ti dice e portami la trascrizione.|n|n$N, mettiti in cammino solo quando sarai $Gpronto:pronta;: senza dubbio, la Cittadella del Fuoco Infernale rileverà la presenza del Veggente e invierà dei Custodi per distruggerlo!', },
    {'Usa il Veggente Demoniaco nella Conca del Fuoco Infernale, attendi che entri in sintonia ed effettua un rilevamento.|n|nRiporta il Veggente Demoniaco e il Resoconto del Veggente Demoniaco allo Speziale Antonivich dentro Thrallmar.', },
  },
  [10839] = {
    'Vol Skith: Pietra Nera di Terokk',
    {'Vol Skith si trova a nord-ovest della carovana e a sud di Shattrath, in una radura nascosta all\'interno della foresta. Si dice che la colonia di Skettis abbia eretto un malefico altare per il culto. Questa Pietra Nera di Terokk deve essere purificata se gli Arakkoa di Skith vogliono sperare di essere redenti.|n|nPrendi questa Verga della Purificazione e usala sulla Pietra Nera. Grazie alla benedizione di A\'dal, la purezza della verga potrebbe essere sufficiente a donare limpidezza alla Pietra Nera. Ora va\', e che la Luce ti accompagni.', },
    nil,
  },
  [10840] = {
    'La Tomba delle Luci',
    {'A est, sepolta sotto la sabbia ardente, ci sta la Tomba delle Luci, nu luogo perduto dove riposano i morti. Prima che la carovana nuostr\' venisse attaccata, stavo andando alla tomba per liberarla dalli spiriti fetenti.|n|nMa nun sapevo che stava già infestata da nu altro tipo di malvagità. Mo\' proprio li Eterei profanano i corpi dei caduti per pigliarsi i monili e i gioielli che avevano dato loro secoli fa.|n|nPosso fare poco mentre la carovana nuostr\' lotta per campare.', },
    nil,
  },
  [10842] = {
    'Anime vendicative',
    nil,
    nil,
  },
  [10843] = {
    'Sin dalla notte dei tempi...',
    {'Sin dalla notte dei tempi, abbiamo sempre lottato contro gli Ogre Lamacurva.|n|nSiamo riusciti a respingerli tanto da lasciar loro solo l\'incerto controllo dell\'Avamposto dei Lamacurva. Si trova nella direzione da cui sei $Gvenuto:venuta;, sul versante sudoccidentale della Cresta delle Lame.|n|nDimostrami il tuo valore uccidendo il loro capo, Gnosh Brognat.|n|nVediamo di che pasta sei $Gfatto:fatta; quando si tratta di Ogre.', },
    nil,
  },
  [10844] = {
    'Fornace Collera',
    nil,
    nil,
  },
  [10845] = {
    'Uccidere la Madre della Stirpe',
    {'I miei cacciatori sono appena tornati da una missione di esplorazione nella Cresta Risonante. A quanto pare i Drachi Fatui che infestano i cristalli di quell\'area sono enormemente cresciuti di numero e minacciano di invadere il nostro territorio.|n|nFinora hai dimostrato di saperci fare con le uccisioni. Vediamo come te la cavi con un draco adulto.|n|nLa Cresta Risonante si trova a sud, oltre il Pianoro delle Scaglie. Uccidi la madre di quella stirpe, Blutenebra.', },
    nil,
  },
  [10846] = {
    'Comprendere i Mok\'Nathal',
    {'<Leoroxx ti fissa negli occhi con quel genere di sguardo che gela l\'anima.>|n|nTu sei <giunto/giunta> tra i Mok\'Nathal, ma non ci comprendi. Non comprendi la nostra lotta per la sopravvivenza.|n|nSe tu ci avessi compreso, allora prenderesti parte alla lotta.|n|nA sud ci sono gli Arakkoa Vekh\'nir. Hanno catturato e reso schiavo un gruppo di Ogre nelle caverne note come Antro di Trogma e il loro capo, Vekh, si trova lì.|n|nUccidilo!', },
    nil,
  },
  [10847] = {
    'Gli occhi di Skettis',
    {'Il fato incombe dalle cime di Skettis.|n|nLa mia gente, gli Arakkoa, affronta un destino avvolto da un male inspiegabile. Troppo spesso abbiamo abusato della magia oscura per compiere il male. Attraverso A\'dal ho scoperto la Luce e la redenzione.|n|nTerokk osserva le sue colonie da Skettis attraverso sfere incantate dall\'arte oscura. Ruba questi occhi da Vol Reskk e Vol Shienor nella parte nord di Terokk. Fammi vedere cosa vede Terokk. Fammi guardare attraverso gli occhi di Skettis.', },
    nil,
  },
  [10848] = {
    'Vol Rhaze: Male senza vita',
    {'Vol Rhaze era una colonia particolarmente empia di Skettis.|n|nNonostante la distruzione del villaggio da parte della calamità di Auchindoun, l\'influenza di Terokk è rimasta negli spiriti malefici che si trovano lì. Dirigiti a ovest fino a Vol Rhaze e uccidi quei maledetti assassini. Li troverai a ovest della Tomba delle Ombre, al confine delle Distese d\'Ossa e della Foresta di Terokk.|n|nSarà il nostro primo attacco contro Terokk e i Guardiani di Skettis.', },
    nil,
  },
  [10849] = {
    'Alla ricerca di Kirrik',
    {'Altri Arakkoa hanno preso parte al tradimento di Terokk.|n|nKirrik ha dichiarato che Terokk è un ciarlatano, non un Profeta. L\'unica profezia fatta da Terokk è stata la fatale esecuzione della sua stessa volontà.|n|nÈ stato Kirrik a guidarci con valore da Skettis. Dopo il nostro pellegrinaggio a Shattrath, Kirrik ha raggiunto le colonie in cerca di altri.|n|nQuesta lettera spiega ciò che gli Occhi hanno visto. Kirrik deve sapere! Segui la strada che parte a sud di Shattrath verso le Distese d\'Ossa e cerca la carovana.', },
    nil,
  },
  [10850] = {
    'Combustibile Fatuo in un motore a Vilfuoco',
    nil,
    nil,
  },
  [10851] = {
    'I totem del mio nemico',
    {'Esiste un modo giusto e un modo sbagliato per onorare i propri antenati.|n|nGli Ogre Lamacurva portano con sé dei totem, ma non li usano per dimostrare il proprio rispetto, bensì per cercare di manipolare e controllare.|n|nPoiché ne sono indegni, dovremmo rubarglieli! Noi sapremmo usarli come si deve.|n|nVai all\'Avamposto dei Lamacurva a ovest, appena a sud-ovest della Cresta delle Lame. Uccidi i Mistici e i Frantumatori Lamacurva e sottrai loro i totem che portano con sé!', },
    nil,
  },
  [10852] = {
    'Amici scomparsi',
    {'Ci siamo fermati qui perché delle persone sono venute di notte e hanno fatto tanto rumore. Ho avuto paura, non so quando ripartiremo.|n|nMa alcuni dei miei amici sono scomparsi. Non so dove sono. Credo che quei brutti uomini uccello li abbiano portati a nord-ovest. Forse li hanno messi in qualche gabbia. Se li trovassi... sarebbe fantastico. Sono preoccupato per loro.', },
    {'Ethan ti ha chiesto di trovare i suoi 12 amici scomparsi a Vol Skith e poi di tornare da lui alla Carovana dei Rifugiati.', },
  },
  [10853] = {
    'Invocazione dello spirito',
    {'Gli spiriti dei Drachi Fatui della Cresta Risonante hanno bisogno di essere liberati.|n|nI Drachi fatui non sono sempre stati Drachi Fatui. Un tempo erano Drachi Neri.|n|nPoi, però, con la distruzione di questo mondo, un\'ondata di Energia Fatua investì ogni cosa e produsse un effetto collaterale sulle uova dei drachi, mutandole.|n|nQuei drachi, perciò, non sono che una versione distorta di se stessi. Dobbiamo aiutarli a ritrovare la pace.|n|nPer farlo, uccidili vicino a un Totem dell\'Invocazione dello Spirito, quindi prendi i loro spiriti da esso.', },
    nil,
  },
  [10854] = {
    'La forza di Neltharaku',
    {'Prendi questi Cristalli di Cespofatuo Incantati e torna alla Fortezza delle Fauci di Drago. Una volta là, cerca i drachi prigionieri e invoca la magia dei Cristalli di Cespofatuo. Le mie energie fluiranno, liberando i drachi dalle catene dei loro aguzzini. Quando vedi che un draco si è liberato, aiutalo a sconfiggere il suo aguzzino! Sarà sicuramente debole per la prigionia.|n|nLiberane più che puoi e poi torna da me, $N.', },
    {'Neltharaku, che vola sopra i Campi degli Alafatua nella Valle di Torvaluna, ti ha chiesto di liberare 5 Drachi Alafatua Schiavizzati.', },
  },
  [10855] = {
    'Vilrazziatori, no grazie!',
    {'Ah sì, il Vilrazziatore! Di sicuro la creazione meccanica più terribile della Legione. Vi son non meno di tre di questi abomini a Guglia Tempestosa.|n|nFortunatamente per noi, non sono ancora attivi. Questo ci consente di occuparci di loro con il sabotaggio invece che con la forza bruta.|n|nOttieni del combustibile fatuo condensato dai Gan\'arg alla Fornace Oblio e usalo per riempire il serbatoio di un Vilrazziatore. Ho la sensazione che non piacerà molto al suo motore.', },
    {'Ottieni 5 Taniche di Combustibile Fatuo Condensato dai Mekgenieri Gan\'arg alla Fornace Oblio, a nord-ovest della Guglia Tempestosa e versale nel serbatoio di un Vilrazziatore Inattivo. Torna da Nauthis l\'Inseguitore Fatuo dopo aver completato l\'incarico.', },
  },
  [10856] = {
    'La miglior difesa',
    {'Gli atti coraggiosi di sabotaggio industriale non ci faranno arrivare lontano, $N. Così come la Fornace Oblio serve come centro d\'assemblaggio per i Vilrazziatori, la Fornace Gehenna funge da campo base per il loro esercito, poiché è lì che si trovano la maggior parte dei loro teletrasporti.|n|nVoglio che tu vada là e gli metta il bastone tra le ruote. Ormai avranno un reggimento intero di Araldi dell\'Ira e non possiamo permetterlo.', },
    {'Nauthis l\'Inseguitore Fatuo ti ha chiesto di uccidere 12 Araldi dell\'Ira alla Fornace Gehenna, a nord della Guglia Tempestosa.', },
  },
  [10857] = {
    'Teletrasporta questo!',
    nil,
    {'Nauthis l\'Inseguitore Fatuo ti ha chiesto di usare la Verga dell\'Interferenza Mentale sui Mo\'arg alla Fornace Gehenna e poi di usare la loro abilità Detonazione Teletrasporto sui tre teletrasporti della Fornace.', },
  },
  [10858] = {
    nil,
    nil,
    {'Cerca Karynaku nella Fortezza delle Fauci di Drago.', },
  },
  [10859] = {
    'Globi di luce',
    nil,
    nil,
  },
  [10860] = {
    'Prelibatezze Mok\'Nathal',
    {'Hai fame, $R? Il Grande Spirito aiuta chi si aiuta da sé. Se vuoi guadagnarti un pasto, ti consiglio di ascoltare attentamente, perché Braagor non ti darà nulla di buono gratis!|n|nI raptor e gli Alascaglia della Cresta delle Lame e del Pianoro delle Scaglie hanno tutto ciò che serve per preparare due dei più prelibati piatti mai cucinati. Portami Costolette di Raptor e Carne di Serpente e te li preparerò entrambi.|n|nSe ti sbrighi, potrei persino insegnarti a cucinarli.', },
    nil,
  },
  [10861] = {
    'Vol Lithic: Attacco preventivo',
    {'Nella malefica colonia a sud-ovest, conosciuta con il nome di Vol Lithic, i servitori di Terokk stanno tentando di contaminare i loro simili prima ancora che nascano. Gli oscuri Occultisti di Lithic avvolgono le uova in un maleficio. Quando la prole nasce, è pronta a servire Terokk senza alcuna volontà propria.|n|nVai a Vol Lithic e rompi le uova prima che la maledizione possa attecchire. Se non fai in tempo, uccidi chi è stato contaminato.|n|nRicorda, la Luce splende più forte nell\'oscurità.', },
    nil,
  },
  [10862] = {
    'Sottomissione all\'Orda',
    {'I vili Arakkoa ci attaccano ogni giorno. Tendono imboscate ai nostri cacciatori e a volte fanno addirittura irruzione all\'interno delle nostre mura. Li uccidiamo quando possibile, ma la loro magia è forte e spesso sfuggono ai nostri guerrieri.|n|nHo saputo che alcuni Arakkoa sostengono di essere amici dell\'Orda. Vivono a Shattrath, a nord-ovest. Il loro capo è Rilak il Redento. Cercalo nella Città Bassa e, quando lo trovi, ordinagli di sottomettersi all\'Orda.', },
    nil,
  },
  [10863] = {
    'Segreti degli Arakkoa',
    {'Qui alla frontiera dobbiamo vedercela ogni giorno con gli Arakkoa. Ci attaccano quando vogliono, razziando i nostri rifornimenti e uccidendo i nostri esploratori.|n|nEppure sappiamo pochissimo di queste enigmatiche creature. Sono stata informata che a nord-ovest di qui, a Shattrath, ci sono degli Arakkoa non ostili. Forse saranno disposti a condividere con noi i segreti della loro razza.|n|nIl loro capo è Rilak il Redento. Risiede nella parte settentrionale della Città Bassa.', },
    nil,
  },
  [10864] = {
    'Il peso delle anime',
    {'Il mio Veggente Demoniaco è uno strumento in grado di analizzare la Vilmagia. Vorrei che lo usassi, ma prima... devi convincerlo. Il fatto è che il Veggente ha intrappolato al suo interno una creatura molto intelligente e dalle necessità... be\', oserei definirle piuttosto "eccentriche".|n|nPer soddisfarlo, devi uccidere degli Orchi. Nello specifico, Orchi Manomozza. Il Veggente vuole le loro anime.|n|nTorna da me quando le avrai mietute. Gli Orchi si trovano a nord, a sud e... tutt\'intorno alla Cittadella del Fuoco Infernale.', },
    {'Uccidi 20 Orchi Manomozza, poi torna dallo Speziale Antonivich a Thrallmar.', },
  },
  [10865] = {
    'Leoroxx va informato!',
    {'Presto, devi informare Leoroxx di quel che sta accadendo all\'Approdo di Razaan!|n|nQuei globi erano in parte composti da anime, alcune delle quali di Mok\'Nathal!', },
    nil,
  },
  [10866] = {
    'Zuluhed l\'Esausto',
    {'Si nasconde nei miei pensieri, mortale. Aspetta che io ceda... che io mi pieghi al suo volere.|n|nE questa sarà la sua fine. Lo chiamerò, gli dirò che farò ciò che vuole. Quando apparirà, uccidilo e prendi la chiave!|n|nSappi che Zuluhed è un Orco antico, dai poteri sconosciuti. Sicuramente Illidan l\'avrà reso ancora più forte. Rischierai la vita facendo ciò che ti chiedo. Vuoi davvero compiere un simile sacrificio?', },
    {'Uccidi Zuluhed l\'Esausto e recupera la Chiave di Zuluhed. Usala per aprire le Catene di Zuluhed e liberare Karynaku.', },
  },
  [10867] = {
    'Si può rispondere in un solo modo',
    {'Si può rispondere in un solo modo a questa... questa PROFANAZIONE delle anime dei nostri antenati!|n|n$N, se vuoi aiutarci a restituire ai nostri morti le loro anime, vai all\'Approdo di Razaan.|n|nTorna lassù e uccidi Razaaniani su Razaaniani finché il loro capo, Razaan il Principe del Nexus, non mostrerà il suo volto codardo. Uccidilo e recupera quelle anime, quindi consegnale all\'Invocatore degli Spiriti Dohgar!', },
    nil,
  },
  [10868] = {
    'Arakkoa sul piede di guerra',
    nil,
    {'La Consigliera Faila ti ha chiesto di uccidere 14 Grinfianiti di Shienor e 6 Occultisti di Shienor e poi di tornare da lei al Mastio di Spaccapietra.', },
  },
  [10869] = {
    'Sfoltire lo stormo',
    {'Gli Arakkoa ci hanno nuovamente attaccato, questa volta di notte, e hanno usato la loro magia oscura per fuggire, prima che potessimo far entrare in azione i nostri soldati.|n|nVol Reskk e Vol Shienor sono a nord e a nord-ovest. Trova questi nidi di Arakkoa e uccidine più che puoi. Forse non avranno paura di noi, ma almeno diminuiremo il loro numero.', },
    {'Il Tenente Ghiaiabrulla ti ha chiesto di uccidere 14 Grinfianiti di Shienor e 6 Occultisti di Shienor e poi di tornare da lui alla Fortezza di Alleria.', },
  },
  [10870] = {
    'Alleato degli Alafatua',
    {'Permettimi di riportarti da Mordenai. Sono certa che vorrà rivederti.', },
    {'Permetti a Karynaku di riportarti da Mordenai nei Campi degli Alafatua.', },
  },
  [10871] = {
    'Alleato degli Alafatua',
    {'Permettimi di riportarti da Mordenai. Sono certa che vorrà rivederti.', },
    {'Permetti a Karynaku di riportarti da Mordenai nei Campi degli Alafatua.', },
  },
  [10872] = {
    'Zuluhed l\'Esausto',
    {'Si nasconde nei miei pensieri, mortale. Aspetta che io ceda... che io mi pieghi al suo volere.|n|nE questa sarà la sua fine. Lo chiamerò, gli dirò che farò ciò che vuole. Quando apparirà, uccidilo e prendi la chiave!|n|nSappi che Zuluhed è un Orco antico, dai poteri sconosciuti. Sicuramente Illidan l\'avrà reso ancora più forte. Rischierai la vita facendo ciò che ti chiedo. Vuoi davvero compiere un simile sacrificio?', },
    {'Uccidi Zuluhed l\'Esausto e recupera la Chiave di Zuluhed. Usala per aprire le Catene di Zuluhed e liberare Karynaku.', },
  },
  [10873] = {
    'Presi nella notte',
    nil,
    nil,
  },
  [10874] = {
    'Vol Shalas: Fuochi di segnalazione',
    nil,
    nil,
  },
  [10875] = {
    'Parla con Nazgrel',
    {'$N, mentre eri in viaggio con il Veggente Demoniaco, ho sparso la voce dei tuoi successi contro i Vilorchi. Nazgrel, il nostro illustre capo di Thrallmar, vuole parlarti. Credo che abbia in mente una missione sanguinaria...', },
    nil,
  },
  [10876] = {
    'Ai piedi della Cittadella',
    nil,
    nil,
  },
  [10877] = {
    'La Reliquia del Terrore',
    {'Tempo fa, una carovana si recò ad Auchindoun con la missione di recuperare una Reliquia del Terrore dalle antiche tombe sotto la necropoli. Ci riuscirono, ma la reliquia fu la loro rovina: è malvagia ed evoca il male quando viene toccata. La carovana venne distrutta da qualche parte a est.|n|nQuesto oscuro manufatto è la chiave per un terribile piano volto a distruggere Teribus il Maledetto, una creatura che sorvola le Distese d\'Ossa. Aiutami se lo desideri, ma sappi che metterai a repentaglio non solo la tua vita ma che la tua anima.', },
    {'Oakun ti ha chiesto di dirigerti verso est fino alla Carovana Abbandonata e di recuperare la Reliquia del Terrore. Quando hai finito, torna da Oakun.', },
  },
  [10878] = {
    'Prima che scenda l\'oscurità',
    {'Dopo che la nostra carovana è stata attaccata dai Cultisti Cabalisti del Concilio dell\'Ombra, sono stati inviati degli esploratori a Shattrath a chiedere aiuto. Le guardie pensano che per ora siamo al sicuro, ma sottovalutano questi pazzi.|n|nPer quanto mi riguarda, non ho intenzione di farmi sgozzare da un Iniziato Cabalista nel mezzo della notte. Facci un favore e affrontali, prima che ci attacchino loro.|n|nTroverai i nostri assalitori a sud di qui, all\'entrata settentrionale di Auchindoun.', },
    nil,
  },
  [10879] = {
    'L\'offensiva di Skettis',
    nil,
    nil,
  },
  [10880] = {
    'Ordini dei Cabalisti',
    {'<Questo messaggio reca un oscuro sigillo e, sebbene la lingua sembri familiare, a quanto pare è scritto in codice.>|n|n<Forse qualcuno alla Carovana dei Rifugiati ne sa qualcosa.>', },
    nil,
  },
  [10881] = {
    'Tomba delle Ombre',
    {'Molti credono che sia stato il Concilio dell\'Ombra a provocare l\'esplosione che ha distrutto Auchindoun. Si dice che abbia risvegliato una grande malvagità.|n|nSe è vero, quel male deve essersi ritorto contro di loro. Secondo questi ordini, parte del Concilio dell\'Ombra sta fuggendo da Auchindoun. Stanno utilizzando la Tomba delle Ombre per conservare potenti manufatti provenienti da Auchindoun.|n|nTre di questi sono sacri, perché appartenevano ai potenti Patriarchi Arunen, K\'alen e Atalor. Ti chiedo di recuperarli.', },
    {'Entra nella Tomba delle Ombre, a ovest della Carovana dei Rifugiati, e recupera il Drappo di Arunen, il Martellaccio di K\'alen e la Pergamena di Atalor. Quando hai completato questa missione, torna da Mekeda alla Carovana dei Rifugiati.', },
  },
  [10882] = {
    'Araldo della Rovina',
    {'<Avverti una nota discordante nella voce di A\'dal.>|n|nIl Principe Kael\'thas è stato poco avveduto nello scegliere la sua prigione e ora le entità che avevamo rinchiuso ad Arcatraz si stanno liberando.|n|nUna in particolare, un servitore degli Dei Antichi noto come Araldo Skyriss, cerca di realizzare la visione di conquista di tutti i mondi dell\'universo dei suoi padroni.|n|n$N, non devi permettergli di scappare. Torna a Forte Tempesta, entra ad Arcatraz e uccidi l\'Araldo Skyriss prima che sia troppo tardi!', },
    nil,
  },
  [10883] = {
    'La Chiave di Forte Tempesta',
    nil,
    {'Parla con A\'dal a Shattrath.', },
  },
  [10884] = {
    'Le prove dei Naaru: Pietà',
    nil,
    {'A\'dal a Shattrath ti ha chiesto di recuperare l\'Ascia Intonsa del Boia dalle Sale della Devastazione della Cittadella del Fuoco Infernale.|n|nQuesta missione deve essere compiuta al livello di difficoltà eroica.', },
  },
  [10885] = {
    'Le prove dei Naaru: Forza',
    {'Quattro prove devi superare per essere $Gritenuto degno:ritenuta degna; dai Naaru.|n|nLa prova di forza è divisa in due parti. Devi distruggere il capo dell\'Antro dei Vapori di Spinaguzza, il Signore della Guerra Kalithresh, e devi portarmi il suo tridente. Uccidi l\'essere extra-planare noto come Murmur, nel Labirinto delle Ombre ad Auchindoun, e portami la sua essenza.|n|nFallo e avrai superato la prova di forza.', },
    {'A\'dal a Shattrath ti ha chiesto di recuperare il Tridente di Kalithresh e l\'Essenza di Murmur.|n|nQuesta missione deve essere compiuta al livello di difficoltà eroica.', },
  },
  [10886] = {
    'Le prove dei Naaru: Tenacia',
    {'Quattro prove devi superare per essere $Gritenuto degno:ritenuta degna; dai Naaru.|n|nDurante i nostri viaggi abbiamo incontrato molti esseri pericolosi. Alcuni li abbiamo incarcerati in un luogo noto come l\'Arcatraz di Forte Tempesta.|n|nC\'è un prigioniero, tuttavia, vittima delle circostanze. Un clandestino che si trovava sul vascello dei Naaru sbagliato nel momento sbagliato.|n|nAvventurati ad Arcatraz e salva lo Gnomo, Millhouse Manalampo. Assicurati che sopravviva.', },
    {'A\'dal a Shattrath ti ha chiesto di salvare Millhouse Manalampo dall\'Arcatraz di Forte Tempesta.|n|nQuesta missione deve essere compiuta al livello di difficoltà eroica.', },
  },
  [10887] = {
    'Fuga dalla tomba',
    {'Grazie per l\'aiuto, $N. Ero certo che sarei stato ucciso.|n|nAndiamocene subito da qui. Non ci vorrà molto prima che arrivino altri Cultisti.', },
    nil,
  },
  [10888] = {
    'Le prove dei Naaru: Magtheridon',
    {'Quattro prove devi superare per essere $Gritenuto degno:ritenuta degna; dai Naaru.|n|nRimane solo un ostacolo, mortale. Raduna un esercito e recati nell\'antro di Magtheridon, nelle viscere della Cittadella del Fuoco Infernale. Arriva fino alla sala centrale e distruggi il vile corruttore!', },
    {'A\'dal a Shattrath ti ha chiesto di uccidere Magtheridon.', },
  },
  [10889] = {
    'Ritorno a Shattrath',
    {'Le tue azioni, seppur coraggiose, scateneranno di certo la vendetta di Terokk.|n|nCorri a Shattrath. Informa Rilak!', },
    nil,
  },
  [10890] = {
    '[[UNUSED] &lt;NYI&gt; ]',
    nil,
    nil,
  },
  [10893] = {
    'Codalunga è l\'elemento cardine',
    {'I Cultisti dei Dragoni Ala Nera si stanno ammassando nel tunnel e questo impegna tutte le nostre energie. Senza volerci girare intorno, sono molti più di noi.|n|nAnche se finora siamo riusciti a respingere quelli che avevano tentato di avvicinarsi troppo, rimane il fatto che il giorno in cui decidessero di attaccarci in massa, probabilmente verremmo sopraffatti.|n|nSe la situazione è questa, occorre che qualcuno raggiunga l\'altra estremità del tunnel e uccida il loro capo, Draaca Codalunga. Te la senti?', },
    nil,
  },
  [10894] = {
    'Guardiano del Cranio del Drago',
    {'Mmm, non saprei cosa fare. Non sono uno stratega militare.|n|nIl Guardiano Ombraluna saprà cosa fare. Adesso è impegnato ad allestire le nostre difese al Tunnel Cranio del Drago a ovest, in fondo al Ponte Cranio del Drago. Abbiamo dislocato delle truppe lì nel caso ai cultisti vengano strane idee in testa.|n|nTi prego, portagli subito la nota.', },
    {'Consegna la Nota per l\'Appuntamento al Guardiano Ombraluna all\'ingresso del Tunnel Cranio del Drago nelle Montagne Spinaguzza.', },
  },
  [10895] = {
    'Zeth\'gor deve bruciare!',
    {'È arrivato il momento di colpire Zeth\'gor dall\'alto! I nostri Cavalieri di Grifoni sono pronti a entrare in azione, ma hanno bisogno che qualcuno a terra diriga il fuoco. Ti senti $Gpronto:pronta; per una missione sotto copertura?|n|nPorta questi segnali fumogeni a Zeth\'gor, la Roccaforte occidentale dei Guerci Insanguinati. Vedrai quattro Torri: una vicino al muro settentrionale, una vicino a quello meridionale, una nei pressi della Forgia e l\'ultima annidata fra le Alture. Piazza un segnale sotto ogni Torre, così potremo bombardarle!', },
    {'Usa un Segnale Fumogeno con ogni Torre di Zeth\'gor, poi torna dal Comandante di Squadriglia Dabir\'ee al Presidio della Spedizione.', },
  },
  [10896] = {
    'I Protettori infestati',
    nil,
    nil,
  },
  [10898] = {
    nil,
    {'<Alaceleste ti vola intorno.>|n|n<Hai la sensazione che voglia che tu lo segua.>', },
    {'Accompagna Alaceleste e parla con Rilak il Redento a Shattrath City.', },
  },
  [10900] = {
    'Il marchio di Vashj',
    nil,
    nil,
  },
  [10901] = {
    'La mazza di Kar\'desh',
    nil,
    {'Skar\'this l\'Eretico nelle Fosse degli Schiavi del Bacino degli Spiraguzza ti ha chiesto di portargli il Sigillo Terrigeno e il Sigillo Fiammeggiante.', },
  },
  [10903] = {
    nil,
    {'$N, mentre eri in missione a Zeth\'gor, ho ricevuto delle notizie del Colonnello Jules, il mio Comandante. È stato infettato da una corruzione demoniaca mentre combatteva vicino all\'Avamposto di Gor\'gaz e le sue condizioni sono molto gravi.|n|nCi hai aiutati molto contro i Vilorchi e la tua forza in battaglia è indiscutibile... ma il tuo spirito?|n|nTi prego di tornare alla Rocca dell\'Onore per parlare con Klatu in una delle stanze superiori nella locanda della Rocca dell\'Onore.', },
    {'Parla con l\'Assistente Klatu nella locanda della Rocca dell\'Onore.', },
  },
  [10904] = {
    'Recuperare vil munizioni',
    {'Dobbiamo impedire l\'accesso della Legione Infuocata al Portale della Morte. Prima, però, dovrai distruggere i loro due Portali Distorcenti!|n|nIl problema è che non siamo riusciti neanche a scalfirli! Questo significa che dovrai utilizzare le loro stesse munizioni.|n|nLe munizioni dei Vilcannoni vengono maneggiate e spostate dalla Forza della Morte, dalla Guardia della Morte, dai Capi Fabbri Forgiamorte e dai Tecnici Forgiamorte.|n|nNormalmente, le vilmunizioni non avrebbero alcun effetto contro di loro, ma se mi porterai quelle Vilpalle di Cannone, le tratterò con l\'Ira Naturale!', },
    nil,
  },
  [10908] = {
    'Parla con Rilak il Redento',
    {'Ti sorprende parlare con me? Non posso biasimarti. La mia gente, gli Arakkoa, merita di essere temuta.|n|nParla con Rilak il Redento a Shattrath se vuoi sapere di più. Puoi trovarlo nella parte settentrionale della Città bassa, con gli altri Erranti di Skettis.|n|nRicorda, $N, noi parleremo ancora.', },
    nil,
  },
  [10909] = {
    'Vilspiriti',
    {'Il Colonnello Jules è stato maledetto mentre combatteva vicino all\'Avamposto di Gor\'gaz, un rifugio dei Vilorchi Manomozza. Barada, il mio padrone, lavora notte e giorno per curare il povero Umano, ma ha bisogno d\'aiuto. Lo spirito tormentato del Colonnello desidera la pace. Purtroppo, temo che la strada per ottenerla passi per la vendetta.|n|nPorta questa Reliquia dell\'Anacoreta all\'Avamposto di Gor\'gaz, posizionala a terra vicino agli Orchi Manomozza e sconfiggili. La Reliquia libererà i loro Vilspiriti, che dovrai uccidere per curare Jules.', },
    {'Klatu nella Rocca dell\'Onore ti ha chiesto di usare la Reliquia dell\'Anacoreta nell\'Avamposto di Gor\'gaz a sud-ovest della Rocca dell\'Onore. Lì dovrai uccidere i Berserker Manomozza vicino alla reliquia e annientare 10 Vilspiriti per vendicare il Colonnello Jules.', },
  },
  [10910] = {
    'Portale della Morte',
    {'Adesso la Legione Infuocata ci pone una minaccia ancora più grande. A sud c\'è un portale noto come il Portale della Morte, il quale si apre sul terribile mondo in cui la Legione alleva i suoi letali segugi.|n|nPer raggiungerlo, esci da Boscovivo andando a est su per la salita, segui il sentiero verso sud oltrepassando la Gola Tagliente, l\'Approdo di Raazan, la Cresta delle Lame e il Pianoro delle Scaglie, quindi scendi giù per la discesa che porta alla Spianata di Vekhaar e attraversa il tunnel a sud di Mok\'Nathal. A quel punto ti troverai dinanzi al portale.|n|nUna volta lì, usa questo Segnale del Druido.', },
    nil,
  },
  [10912] = {
    'Il Maestro dei Segugi',
    {'Baelmon il Maestro dei Segugi deve morire! È lui a officiare il rituale che mantiene aperto il Portale.|n|nIl Portale della Morte si trova all\'estremità settentrionale del canyon. Trovato il portale, troverai anche Baelmon.|n|nPer questa missione ti servirà un po\' di aiuto, quindi prendi questa bacchetta. Usala mentre combatti con il Maestro dei Segugi e un paio di miei amici accorreranno in tuo soccorso.|n|nUna volta sconfitto Baelmon, torna dal Signore della Selva Antelarion.|n|nE $N... grazie per tutto quello stai facendo per noi qui.', },
    nil,
  },
  [10913] = {
    'Una sepoltura sbrigativa',
    {'Non si può fare nulla per arrestare l\'ondata di corruzione? Ormai sono giorni che i miei soldati lottano con gli Auchenai, e non si vede una fine. Ogni caduto, Auchenai o Sha\'tar, viene portato via dal campo di battaglia, la sua anima presa e condotta chissà dove.|n|nNon posso permetterlo! Una sepoltura appropriata non è praticabile, ma quei maledetti non avranno le loro anime! Prendi questa torcia e vai sul campo di battaglia, subito a est di qui. Brucia tutti i cadaveri che vedi! Non alimenteremo i loro rituali.', },
    nil,
  },
  [10914] = {
    'Serve un eroe',
    {'Non basta. Serve un eroe. Le nostre forze vengono soverchiate mentre gli Auchenai continuano ad aumentare.|n|n<Il Comandante Ra\'vaj ti guarda.>|n|nSarai tu a incarnarlo? Torna al campo di battaglia e attacca i loro soldati. Tienili occupati affinché i miei esploratori possano superare le loro linee e scoprire cosa stanno macchinando.', },
    nil,
  },
  [10915] = {
    'L\'Esarca caduto',
    {'Con le anime che rubano nutrono una bara che hanno estratto dalle Cripte degli Auchenai. I miei esploratori pensano che la bara contenga il primo Esarca delle cripte. Vogliono resuscitare quell\'antica creatura!|n|nDevi farti strada fino al lato occidentale di Auchindoun e occuparti del contenuto di quella bara prima che venga nutrito a sufficienza. Se dovessi perderti, segui le anime erranti.|n|nQualunque cosa ci sia in quella bara... distruggila!', },
    nil,
  },
  [10916] = {
    'In cerca delle Perle della Preghiera',
    {'L\'Anacoreta Barada vuole esorcizzare la corruzione dal Colonnello Jules e ha bisogno dell\'aiuto di una persona preparata.|n|nMi vergogno a confessarlo, ma ho smarrito le mie Perle della Preghiera nel Cortile della Rocca dell\'Onore. Credo che il cane Fei Fei le abbia rubate e seppellite, ma non so dove. Parla con la sua padrona, l\'Ufficiale Specialista Tracy Prodepozze: forse lei sa dove Fei Fei nasconde i suoi "tesori".', },
    {'Recupera le Perle della Preghiera Draenei e portale all\'Assistente Klatu nella Rocca dell\'Onore.', },
  },
  [10917] = {
    'La promessa dell\'Errante',
    nil,
    {'Porta 30 Piume di Arakkoa a Vekax nella Città Bassa di Shattrath.', },
  },
  [10918] = {
    'Ancora piume',
    nil,
    nil,
  },
  [10919] = {
    'Bocconcino per Fei Fei',
    nil,
    nil,
  },
  [10920] = {
    'Per i caduti',
    {'Quando le Vedove Malazanna hanno attaccato il nostro avamposto, abbiamo sentito la voce dei Naaru che ci incitava alla battaglia. Abbiamo inseguito le creature nella notte. Alcuni dei nostri sono stati ritrovati morti, altri li abbiamo sentiti lottare contro i loro aguzzini.|n|nAl mattino siamo arrivati qui e abbiamo affrontato una dura battaglia, ma siamo stati sconfitti. Il veleno dei Malazanna prenderà presto i miei compagni e io non potrò resistere a lungo. Ma prima di morire voglio sapere che le Vedove Malazanna sono state sconfitte.', },
    {'Il Vendicatore Haylen ti ha chiesto di uccidere 20 Vedove Malazanna e poi di tornare da lui subito a ovest della Cresta di Telafatua.', },
  },
  [10921] = {
    nil,
    {'Hai ucciso molte Vedove Malazanna, ma continueranno a riprodursi e presto ci attaccheranno di nuovo. Nelle profondità della Cresta di Telafatua si trova la tana della Terokkarantola, la madre di queste raccapriccianti creature. Se vogliamo essere al sicuro, deve morire.', },
    {'Il Vendicatore Haylen ti ha chiesto di uccidere la Terokkarantola e poi di tornare da lui a ovest della Cresta di Telafatua.', },
  },
  [10922] = {
    'Rovistando tra le ossa',
    nil,
    nil,
  },
  [10923] = {
    'Il male si avvicina',
    {'Ora devi usare la Reliquia del Terrore in un malefico rituale negromantico, se vuoi sfidare Teribus il Maledetto. A nord-est, dopo Auchindoun, c\'è il Tumulo Inquieto, un luogo dove si radunano i negromanti.|n|nI Necroratori Auchenai e i Vati della Rovina hanno dei Teschi dell\'Apocalisse dotati di potenti incantamenti. Se trovi abbastanza teschi, puoi usare il loro potere insieme a quello della Reliquia del Terrore per ordinare a Teribus di affrontarti.', },
    {'Oakun ti ha chiesto di portare la Reliquia del Terrore al Tumulo Inquieto. Una volta lì, uccidi i Necroratori Auchenai e i Vati della Rovina fino a ottenere 20 Teschi dell\'Apocalisse. Poi trova il Circolo d\'Evocazione del Tumulo Inquieto e usa la Reliquia del Terrore per evocare e distruggere Teribus il Maledetto. Quando hai finito, torna da Oakun.', },
  },
  [10924] = {
    'È Imp-possibile!',
    {'Il sangue degli Inseguitori Distorcenti di quest\'area è un reagente raro e potente. È uno degli articoli che vendono di più.|n|nNormalmente, chiederei al mio Imp, Zeppit, di aiutarmi a raccoglierlo. Il Sangue degli Inseguitori Distorcenti è troppo acido per essere maneggiato da uno di noi, ma non crea problemi a Zeppit.|n|nIl negozio è sempre più affollato, quindi se mando Zeppit con te, lo aiuterai a raccogliere il sangue? Zeppit si distrae facilmente, quindi dovrai essere vicino all\'Inseguitore quando muore se vuoi che il mio Imp faccia il suo dovere.', },
    {'Porta 8 Fiale di Sangue d\'Inseguitore Distorcente a Sab\'aoth a Kosmika.', },
  },
  [10925] = {
    'Il male si avvicina',
    nil,
    nil,
  },
  [10926] = {
    'Ritorno al Campo Base Sha\'tari',
    {'Non riusciremo a tornare da soli. Il veleno dei Malazanna è troppo forte. Devi tornare per noi al Campo Base Sha\'tari. L\'Esploratore Navrin invierà una squadra di recupero a prenderci.', },
    nil,
  },
  [10927] = {
    'Uccidere i ragni',
    nil,
    nil,
  },
  [10928] = {
    'Uccidere i ragni',
    nil,
    nil,
  },
  [10929] = {
    nil,
    {'Che ne dici di lavorare ancora per la Lega degli Esploratori? Siamo tutti concentrati su questi vermi delle ossa.|n|nHo qui un tamburo che puoi usare nelle Distese d\'Ossa. Fatti una suonatina e vedi che succede. Se appare un verme, uccidilo e portaci la carcassa: la studieremo. Ce ne serviranno molte per avere un campione sperimentale valido.', },
    {'Nanowitz al Campo Base Sha\'tari nelle Distese d\'Ossa ti ha chiesto di portargli 8 Carcasse di Frangiossa Adulti.', },
  },
  [10930] = {
    'Il grosso verme delle ossa',
    nil,
    nil,
  },
  [10931] = {
    'Torna a Exodar',
    {'Il Maestro Caedmos a Exodar ha chiesto di vederti. Riguarda il tuo addestramento, ma non mi ha detto altro.', },
    {'Parla con Caedmos a Exodar.', },
  },
  [10932] = {
    'Torna a Exodar',
    {'Il Maestro Caedmos a Exodar ha chiesto di vederti. Riguarda il tuo addestramento, ma non mi ha detto altro.', },
    {'Parla con Caedmos a Exodar.', },
  },
  [10933] = {
    nil,
    {'Il Maestro Aldrae a Lunargenta ha chiesto di vederti. Riguarda il tuo addestramento, ma non mi ha detto altro.', },
    {'Parla con Aldrae a Lunargenta.', },
  },
  [10934] = {
    nil,
    {'Il Maestro Aldrae a Lunargenta ha chiesto di vederti. Riguarda il tuo addestramento, ma non mi ha detto altro.', },
    {'Parla con Aldrae a Lunargenta.', },
  },
  [10935] = {
    'L\'esorcismo del Colonnello Jules',
    {'$N, è arrivato il momento di salvare il Colonnello Jules. Le sue condizioni sono ulteriormente peggiorate e Barada teme che, se non eliminiamo la corruzione che lo affligge, lo perderemo per sempre.|n|nPorta le Perle della Preghiera che hai recuperato all\'Anacoreta Barada e parla con lui per dare inizio al rituale. Nulla deve disturbare l\'operazione: se tutto andrà bene, il Colonnello Jules sarà salvo. Quando sarà guarito, parla con lui e poi torna da me.', },
    {'Parla con l\'Anacoreta Barada. Usa le Perle della Preghiera per eseguire il rituale, poi parla con il Colonnello Jules quando sarà guarito. Infine, torna dall\'Assistente Klatu.', },
  },
  [10936] = {
    'Cacciatroll ti sta cercando',
    {'Mentre eravamo occupati, un messaggero attendeva nell\'atrio. Immagino che si sia stancato, o forse è fuggito appena ha visto Jules volteggiare per la stanza.|n|nIn ogni caso, il Comandante delle Forze Danath ti sta cercando. Ti consiglio di chiedergli udienza nella Caserma il prima possibile!', },
    {'L\'Assistente Klatu ti ha informato che il Comandante delle Forze Danath Cacciatroll ti sta cercando. Parla con lui nelle Caserme della Rocca dell\'Onore nella Penisola del Fuoco Infernale.', },
  },
  [10937] = {
    'Istruendo il Maestro Istruttore',
    {'Mi riferiscono che i Vilorchi Manomozza davanti alla Cittadella del Fuoco Infernale stiano organizzando quello che sembra un attacco in massa. Senza dubbio, i tuoi successi con tutti i Clan non li rendono felici.|n|nRaggiungi la base della Cittadella, laddove termina il Cammino della Gloria. Troverai i Vilorchi intenti nei preparativi, quindi li coglierai impreparati.|n|nElimina il capo di quell\'armata: uccidi il Maestro Istruttore Zurok!', },
    {'Il Comandante delle Forze Danath Cacciatroll ti ha ordinato di uccidere in tutta fretta il Maestro Istruttore Zurok. Poi, torna da lui nella Rocca dell\'Onore della Penisola del Fuoco Infernale.', },
  },
  [10938] = {
    'Mazzo delle Benedizioni di Lunacupa',
    nil,
    {'Consegna il Mazzo delle Benedizioni alla Fiera di Lunacupa quando arriva in città.', },
  },
  [10939] = {
    'Mazzo delle Tempeste di Lunacupa',
    nil,
    {'Consegna il Mazzo delle Tempeste alla Fiera di Lunacupa quando arriva in città.', },
  },
  [10940] = {
    'Mazzo delle Furie di Lunacupa',
    nil,
    {'Consegna il Mazzo delle Furie alla Fiera di Lunacupa quando arriva in città.', },
  },
  [10941] = {
    'Mazzo della Follia di Lunacupa',
    nil,
    {'Consegna il Mazzo della Follia alla Fiera di Lunacupa quando arriva in città.', },
  },
  [10942] = {
    'Settimana dei Bambini',
    {'Na bambina speciale sarà assai felice di tenerti come $Gamico:amica;, pure se per poco tempo.|n|nPiglia chisto fischietto. Grazie a esso, potrai chiamare la bambina della quale hai deciso di pigliarti cura. Terrà na durata limitata. Nun più della Settimana dei Bambini, a dire il vero.|n|nPer favore, $N, chiama l\'orfana tua. So che sarà assai emozionata al pensiero di conoscerti e di tenere l\'opportunità di esplorare le terre al di fuori della città!', },
    nil,
  },
  [10943] = {
    'Settimana dei Bambini',
    {'Na bambina speciale sarà assai felice di tenerti come $Gamico:amica;, pure se per poco tempo.|n|nPiglia chisto fischietto. Grazie a esso, potrai chiamare la bambina della quale hai deciso di pigliarti cura. Terrà na durata limitata. Nun più della Settimana dei Bambini, a dire il vero.|n|nPer favore, $N, chiama l\'orfana tua. So che sarà assai emozionata al pensiero di conoscerti e di tenere l\'opportunità di esplorare le terre al di fuori della città!', },
    nil,
  },
  [10944] = {
    'Il segreto compromesso',
    {'Grazie ancora, $N. Riconosco il tuo nome. Akama ha avuto fiducia in te, perciò ora l\'avrò anch\'io.|n|nI Naga hanno scoperto che sto lavorando ai danni di Illidan e hanno cercato di farmi parlare torturandomi. Io non ho parlato... Lo stesso Akama mi aveva insegnato a dominare il dolore tramite la meditazione.|n|nIllidan aveva chiesto ai Naga di portarmi da lui, che è in grado di vedere oltre la pelle e scoprire i segreti più nascosti.|n|nAkama dev\'essere avvisato. I nostri piani sono in pericolo!', },
    {'Raggiungi la Prigione della Guardiana nella Valle di Torvaluna e parla con Akama.', },
  },
  [10945] = {
    'Hch\'uu e il popolo fungo',
    {'Ho un\'amichetta di nome Hch\'uu. Mi aveva detto di essere finita all\'orfanotrofio perché si era persa mentre tentava di fuggire dai malvagi funghi giganti.|n|nEravamo molto amici, ma l\'anno scorso la sua gente se l\'è portata via. Ricordo che mi aveva detto che sarebbe andata a vivere in un posto chiamato Sporeggar.|n|nVorrei andare a trovarla e visitare il villaggio dei funghi. La Matrona mi ha detto che si trova sul lato occidentale delle Paludi di Zangar, tra il Lago di Sporavento e il Lago di Luceamara.|n|nAndiamo? Andiamo? Per favore!', },
    {'Porta Salandria a Sporeggar nelle Paludi di Zangar. Chiamala se non è presente al tuo arrivo. Quindi parla con Hch\'uu.', },
  },
  [10946] = {
    'Lo stratagemma dei Linguamorta',
    {'Il sacrificio di Olum è stato tremendo. Io stesso non gli avrei mai chiesto di dare la sua vita per la causa. Ma ormai è fatta.|n|nSe vogliamo dare a Illidan un falso senso di sicurezza, dobbiamo fare ciò che vuole, almeno per ora.|n|nAl mio comando ho un vasto esercito di Linguamorta ma, a parte i Congiurati, non c\'è da fidarsi di nessuno.|n|nTu dovrai fare ciò che Illidan ti chiede. Prendi questo cappuccio magico. Chiunque ti vedrà uccidere la fenice di Kael, Al\'ar, ti scambierà per uno dei miei uomini.', },
    {'Raggiungi Forte Tempesta e uccidi Al\'ar mentre indossi il Cappuccio dei Linguamorta. Una volta completata la missione, torna da Akama nella Valle di Torvaluna.', },
  },
  [10947] = {
    'Un manufatto dal passato',
    {'Grazie a te, l\'attenzione di Illidan è ora su Kael\'thas. È giunto il momento di fare la nostra mossa.|n|nHo avuto la visione di un manufatto che ci aiuterà nella battaglia finale, il filatterio di un Lich di nome Gelidaria. Purtroppo il suo potere è andato perduto per sempre dopo la sua sconfitta nella Battaglia per il Monte Hyjal.|n|nTuttavia, potrebbe esserci un modo per recuperare il manufatto. La leggenda parla di un luogo su Azeroth sorvegliato da Draghi di Bronzo... un luogo dove passato e presente si incontrano, nel quale troverai ciò che cerchiamo.', },
    {'Recati alle Caverne del Tempo a Tanaris ed entra nella Battaglia per il Monte Hyjal. A quel punto, sconfiggi Rabis Gelidaria e porta il Filatterio Temporalmente Sfasato ad Akama nella Valle di Torvaluna.', },
  },
  [10948] = {
    'L\'anima ostaggio',
    {'Potresti chiederti perché mi preoccupo tanto di nascondere le mie intenzioni. Perché non condividere apertamente la mia sorte con i Naaru?|n|nLa mia stessa essenza, la mia anima, è tenuta prigioniera all\'interno del Tempio Nero. Illidan poteva distruggermi in qualsiasi momento... ma ora non più! Questo Filatterio mi permetterà di riacquistare il controllo della mia anima.|n|nL\'ora è giunta, $N. Condurrò Maiev e i miei Congiurati contro Illidan.|n|nParla con A\'dal ed esponigli il nostro piano. Colpendo insieme, riusciremo a fare breccia nelle difese di Illidan.', },
    {'Raggiungi Shattrath ed esponi ad A\'dal la richiesta di Akama.', },
  },
  [10949] = {
    'Ingresso nel Tempio Nero',
    {'<A\'dal ti mostra l\'immagine di un Naaru fuori dal Tempio Nero mentre combatte al fianco di Vendicatori Draenei e Magistri Elfi del Sangue. Immediatamente capisci che questo è il diversivo di cui ha bisogno Akama.>', },
    {'Raggiungi l\'ingresso del Tempio Nero nella Valle di Torvaluna e parla con Xi\'ri.', },
  },
  [10950] = {
    'Auchindoun e l\'Anello dell\'Osservanza',
    nil,
    {'Porta Dornaa alla Pietra del Ritrovo dell\'Anello dell\'Osservanza nel centro di Auchindoun. Auchindoun si trova nel cuore delle Distese d\'Ossa della Foresta di Terokk. Chiamala se non è presente al tuo arrivo.', },
  },
  [10951] = {
    'Un viaggio al Portale Oscuro',
    {'Possiamo visitare tantissimi posti fantastici, ma non possiamo perderci il Portale Oscuro!|n|nGli adulti cercano sempre di spaventarci con storie su quanto sia pericoloso, perché ci fuoriescono dei demoni e altra gente come te...|n|n<Salandria rotea gli occhi.>|n|nMa tu sei con me e quindi niente può andare storto, vero?|n|nVorrei proprio vederlo. Sai che si trova sul confine orientale della Penisola del Fuoco Infernale?', },
    {'Porta Salandria sulla Scalinata del Destino per condurla davanti al Portale Oscuro nella Penisola del Fuoco Infernale. Chiamala se non è presente al tuo arrivo.', },
  },
  [10952] = {
    'Un viaggio al Portale Oscuro',
    {'C\'è un posto dove dobbiamo andare assolutamente, se non abbiamo altro da fare: il Portale Oscuro!|n|nLa Matrona cerca sempre di spaventarci con storie su quanto sia pericoloso, perché ci fuoriescono dei demoni e altra gente come te...|n|n<Dornaa rotea gli occhi.>|n|nMa tu sei con me e quindi niente può andare storto, vero?|n|nVorrei proprio vederlo. Sai che si trova sul confine orientale della Penisola del Fuoco Infernale?', },
    {'Porta Dornaa sulla Scalinata del Destino per condurla davanti al Portale Oscuro nella Penisola del Fuoco Infernale. Chiamala se non è presente al tuo arrivo.', },
  },
  [10953] = {
    'Gita al Trono degli Elementi',
    {'Hai mai sentito parlare del Trono degli Elementi? Si trova a Nagrand e ci vivono degli elementali molto potenti.|n|nSicuramente un giorno sarò una potentissima Maga, o magari una Strega. Comunque dovrò studiare alcune delle forze elementali!|n|nPensi che possiamo andarci?|n|n<Salandria ti guarda sorniona.>|n|nSu... dai, in fondo ci andiamo per motivi culturali. Si trova a nord di Garadar, sull\'altra sponda del Lago del Canto Celeste.', },
    {'Porta Salandria al Trono degli Elementi nella regione di Nagrand. Chiamala se non è presente al tuo arrivo. Quindi parla con l\'Elementalista Sharvak.', },
  },
  [10954] = {
    'Jheel è all\'Approdo di Aeris!',
    {'Mi manca mio fratello. Si chiama Jheel e ha un paio di anni più di me... Per questo gli hanno consentito di iniziare il suo apprendistato con l\'Etereo a Nagrand.|n|nMi piacerebbe fargli visita. Gli piaceva molto la geologia, quindi immagino che si stia divertendo un mondo.|n|nLa Matrona mi ha detto che si sta addestrando in un luogo chiamato Approdo di Aeris a Nagrand. Dovrebbe trovarsi sulla strada a ovest di Telaar e a nord-ovest della grande montagna Oshu\'gun.', },
    {'Porta Dornaa all\'Approdo di Aeris a Nagrand. Chiamala se non è presente al tuo arrivo. Quindi parla con Jheel.', },
  },
  [10955] = {
    '[Morthis Whisperwing]',
    nil,
    nil,
  },
  [10956] = {
    'Il Trono dei Naaru',
    nil,
    {'Porta Dornaa davanti a O\'ros in fondo al Trono dei Naaru a Exodar, sull\'Isola Brumazzurra. Chiamala se non è presente al tuo arrivo.|n|nRicorda che dentro la città puoi usare la mappa.', },
  },
  [10957] = {
    'Il riscatto dei Linguamorta',
    {'Quando Illidan si è alleato con i Corrotti, Akama era il nostro elemento più saggio. Egli sapeva che opporsi apertamente al Traditore avrebbe portato all\'estinzione della nostra razza.|n|nPiuttosto, ha tramato e complottato nel più assoluto segreto affinché giungesse questo momento. Il fallimento sarebbe una catastrofe... non solo per Akama e per i Corrotti, ma per tutte le Terre Esterne. Nessuno così vicino a Illidan è mai riuscito a sferrargli un colpo tanto tremendo.|n|nAiuta Akama a liberare la sua anima e lui ti darà accesso al Santuario di Illidan.', },
    {'Aiuta Akama a riprendere possesso della propria anima sconfiggendo l\'Ombra di Akama all\'interno del Tempio Nero. Una volta fatto ciò, torna dal Veggente Kanai.', },
  },
  [10958] = {
    'Alla ricerca dei Linguamorta',
    {'<Mentre guardi Xi\'ri, avverti in te grande concentrazione e determinazione. Il tuo compito qui non è ancora terminato: devi entrare nel Tempio Nero e trovare i seguaci di Akama.>|n|n<Molte cose dipendono dalla vittoria di Akama.>', },
    {'Trova i Congiurati di Akama all\'interno del Tempio Nero.', },
  },
  [10959] = {
    'La caduta del Traditore',
    {'Sconfitti i tenenti di Illidan, Akama potrà forzare le porte del santuario di Illidan. Preparati a portarvi le tue forze insieme a quelle di Akama.|n|nAncora non sappiamo cosa ne è stato di Maiev, ma dovremo fare la nostra mossa senza di lei.|n|nSpero che le tue forze siano all\'altezza della situazione. Illidan non sarà contento di vedere Akama.', },
    {'Il Veggente Kanai ti ha chiesto di uccidere Illidan all\'interno del Tempio Nero.', },
  },
  [10962] = {
    'E ora una visita alle caverne',
    {'Il vecchio Sacerdote che veniva a trovarci all\'orfanotrofio ci raccontò delle storie sulle Caverne del Tempo. Ci disse che si trovano al centro del tempo e che sono importantissime per mantenere l\'equilibrio.|n|nNon ci ho capito molto, ma ci ha detto che lì ci sono dei draghi che stanno aiutando a salvare il mondo! Voglio vedere un drago!|n|nPensi che possiamo andarci? Ci disse anche che l\'ingresso si trova sul bordo orientale di un grande deserto chiamato Tanaris.|n|nMagari quando siamo lì, potresti comprarmi un ricordino.', },
    {'Porta Dornaa a conoscere Zaladormu, il drago sulla pedana in mezzo alle Caverne del Tempo. Chiamala se non è presente al tuo arrivo.|n|nQuindi comprale un Drago Giocattolo da Alurmi, il Quartiermastro dei Custodi del Tempo, che si trova vicino al fondo del tunnel di ingresso.', },
  },
  [10963] = {
    'E ora una visita alle caverne',
    {'Il vecchio Sacerdote puzzolente che veniva a trovarci all\'orfanotrofio ci raccontò delle storie sulle Caverne del Tempo. Ci disse che si trovano al centro del tempo e che sono importantissime per mantenere l\'equilibrio.|n|nNon ci ho capito molto, ma ci ha detto che lì ci sono dei draghi che stanno aiutando a salvare il mondo! Voglio vedere un drago!|n|nDovremmo andarci. Ci disse anche che l\'ingresso si trova sul bordo orientale di un grande deserto chiamato Tanaris.|n|nMagari quando siamo lì, potresti comprarmi un ricordino.', },
    {'Porta Salandria a conoscere Zaladormu, il drago sulla pedana in mezzo alle Caverne del Tempo. Chiamala se non è presente al tuo arrivo.|n|nQuindi comprale un Drago Giocattolo da Alurmi, il Quartiermastro dei Custodi del Tempo, che si trova vicino al fondo del tunnel di ingresso.', },
  },
  [10966] = {
    'Ritorno all\'orfanotrofio',
    {'Accipicchia! Credo che sia ora di tornare all\'orfanotrofio di Shattrath.|n|nMi sono divertita moltissimo con te. Sei la persona migliore del mondo, $N, $Gil mio fratellone:la mia sorellona;!|n|n<Gli occhi di Dornaa si riempiono di lacrime.>|n|nMi mancherai molto! Da grande, sarò proprio come te!!!', },
    {'Riporta la tua protetta all\'orfanotrofio di Shattrath ridando il Fischietto dell\'Orfano Draenei alla Matrona degli Orfani Letizia nella Città Bassa.', },
  },
  [10967] = {
    'Ritorno all\'orfanotrofio',
    {'Accipicchia! Credo che sia ora di tornare all\'orfanotrofio di Shattrath.|n|nMi sono divertita moltissimo con te. Sei la persona migliore del mondo, $N, $Gil mio fratellone:la mia sorellona;!|n|n<Gli occhi di Salandria si riempiono di lacrime.>|n|nMi mancherai molto! Da grande, sarò proprio come te!!!', },
    {'Riporta la tua protetta all\'orfanotrofio di Shattrath ridando il Fischietto dell\'Orfana Elfa del Sangue alla Matrona degli Orfani Letizia nella Città Bassa.', },
  },
  [10968] = {
    'La chiamata del Chiaroveggente',
    {'Sento che quella bambina ha qualcosa di speciale.|n|nDovresti portarla a conoscere il Chiaroveggente Nobundo. Si trova sempre qui a Exodar. Credo che vi stia aspettando.|n|nCercalo sulla terrazza più alta della Sala di Cristallo.', },
    {'Porta Dornaa a fare visita al Chiaroveggente Nobundo nella Sala di Cristallo a Exodar, sull\'Isola Brumazzurra. Chiamala se non è presente al tuo arrivo.|n|nRicorda che dentro la città puoi usare la mappa.', },
  },
  [10969] = {
    'Alla ricerca di Ameer',
    nil,
    {'Cerca il Comandante Ameer al Presidio del Protettorato.', },
  },
  [10970] = {
    'Missione caritatevole',
    {'Abbiamo recuperato questo globo carcerario nell\'ultima missione ricognitiva in territorio Etereum. Non l\'avremmo mai trovato se non fosse stato per il debole segnale di soccorso che emetteva.|n|nPensiamo che alcuni dei nostri siano rinchiusi al suo interno, ma non abbiamo modo di aprirlo senza fare del male a qualunque cosa sia all\'interno.|n|nSappiamo che ogni membro degli Etereum potrebbe avere con sé in qualsiasi momento una chiave per aprire il globo. Recuperane una e fai ritorno qui, così potremo svelare i misteri del globo.', },
    {'Prendi la Chiave della Prigione degli Etereum Recuperata per il Comandante Ameer al Presidio del Protettorato nella Landa Fatua.', },
  },
  [10971] = {
    'I segreti degli Etereum',
    {'<Ameer solleva una medaglietta.>|n|nHo trovato una medaglietta identificativa di un prigioniero dell\'Avanguardia sconfitta. Posso dedurre che tutti i prigionieri siano identificati nello stesso modo.|n|nInizierò a catalogare le medagliette nella speranza di comprendere il loro sistema penale. Se durante le tue avventure dovessi trovare altre chiavi carcerarie degli Etereum, usale per aprire le prigioni nei Campi Base degli Etereum, a sud. Portami tutte le medagliette identificative che trovi.', },
    {'Il Comandante Ameer al Presidio del Protettorato nella Landa Fatua ti ha chiesto di portargli una Medaglietta Identificativa dei Prigionieri degli Etereum.', },
  },
  [10972] = {
    'Il registro identificativo dei prigionieri degli Etereum',
    {'$N, mi servono altre medagliette identificative. Quanto ho scoperto finora è che non è solo un modo per catalogare i prigionieri, ma anche l\'ubicazione dei documenti!|n|nQuando avrò violato il codice, sarò in grado di localizzare esattamente dove sono tenuti i nostri alleati e di liberarli con minima resistenza nemica.', },
    nil,
  },
  [10973] = {
    'Un migliaio di mondi',
    {'Ho violato il codice! Ogni medaglietta è divisa in svariati segmenti. La parte anteriore è sempre la stessa e riporta il messaggio: "Un migliaio di mondi"... Non sono certo del significato di questa frase, ma suona minacciosa.|n|nSul retro ci sono i dati vitali. La prima serie di rune indica l\'ubicazione e la seconda il tipo di prigioniero. Inoltre, sembra che le chiavi possano essere combinate per crearne una speciale che fornisce l\'accesso a un altro tipo di prigione. Ora mi servono solo altre chiavi...', },
    {'Il Comandante Ameer al Presidio del Protettorato nella Landa Fatua ti ha chiesto di portargli 5 Chiavi della Prigione degli Etereum.', },
  },
  [10974] = {
    'La camera di stasi di Bash\'ir',
    {'Gli Etereum hanno un insediamento sul pianoro più a nord delle Montagne Spinaguzza, noto come Approdo di Bash\'ir. Secondo la tavoletta chiave, a Bash\'ir ci sono versioni molto più grandi delle prigioni. Va anche notato che gli Etereum si riferiscono a quelle prigioni come camere di stasi.|n|nLa tavoletta chiave dà accesso a una camera di stasi ben precisa, nota come Camera di Stasi Alfa. Prendi la tavoletta e investiga.|n|nLa mia immagine attenderà il tuo ritorno all\'Approdo di Bash\'ir. Parleremo là.', },
    {'Usa la Tavoletta Chiave degli Etereum Alfa per aprire la Camera di Stasi Alfa all\'Approdo di Bash\'ir nelle Montagne Spinaguzza.|n|nRiporta le Prove dalla Camera di Stasi all\'immagine del Comandante Ameer all\'Approdo di Bash\'ir.', },
  },
  [10975] = {
    'Epurare le Camere di Bash\'ir',
    nil,
    nil,
  },
  [10976] = {
    'Il Marchio del Re del Nexus',
    {'Quello che ho bisogno di sapere adesso è cosa tenevano nelle Tombe del Mana di Auchindoun gli Etereum.|n|nDurante le tue battaglie contro le bestie nelle camere di stasi di Bash\'ir potresti imbatterti in un oggetto chiamato il Marchio del Re del Nexus. Se lo trovi, portamelo immediatamente! È l\'ultimo pezzo necessario per creare la chiave che ci consentirà di accedere alla camera di stasi nelle Tombe del Mana.', },
    {'L\'Immagine del Comandante Ameer all\'Approdo di Bash\'ir nelle Montagne Spinaguzza ti ha chiesto di portargli un Marchio del Re del Nexus.', },
  },
  [10977] = {
    'Le Camere di Stasi delle Tombe del Mana',
    {'Il Marchio del Re del Nexus che hai recuperato mi ha permesso di forgiare una nuova chiave per le camere di stasi all\'interno delle Tombe del Mana.|n|nSecondo i glifi sul marchio, ne esistono due: una vicino all\'ingresso e una vicino a Shaffar il Principe del Nexus. La chiave che sto per darti aprirà la camera di stasi vicino all\'ingresso.|n|nVoglio che ti rechi nelle Tombe del Mana ad Auchindoun e che tu apra la Camera di Stasi delle Tombe del Mana.', },
    {'L\'Immagine del Comandante Ameer all\'Approdo di Bash\'ir nelle Montagne Spinaguzza ti ha chiesto di usare la Chiave della Camera di Stasi delle Tombe del Mana per aprire la Camera di Stasi nelle Tombe del Mana ad Auchindoun.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [10981] = {
    'La camera personale di Shaffar Principe del Nexus',
    nil,
    nil,
  },
  [10982] = {
    'L\'Occhio di Haramad',
    nil,
    nil,
  },
  [10983] = {
    'Mog\'dorg il Corrugato',
    {'Mog\'dorg è saggio! Ha mandato Grok in città a cercare aiuto. Al Clan Magliorosso serve aiuto.|n|nMog\'dorg dice di mandare individui potenti dei piccoli popoli nelle Montagne Spinaguzza. Lui è in cima alla torre al Cerchio del Sangue. Mog\'dorg è saggio!', },
    {'Fai visita a Mog\'dorg il Corrugato in cima a una delle torri appena fuori dal Cerchio del Sangue nelle Montagne Spinaguzza.', },
  },
  [10984] = {
    'Due chiacchiere con l\'Ogre',
    {'<La voce di V\'eru risuona nella tua mente con tonalità e chiarezza cristallina.>|n|nNella Città Bassa, c\'è un Ogre che chiede aiuto ai passanti. Hanno scelto tutti di ignorarlo.|n|nCredi di poterlo aiutare?|n|nSi chiama Grok ed è seduto vicino ai mercanti a sud-est.|n|nGrazie, $N.', },
    {'Parla con l\'Ogre Grok, nella Città Bassa di Shattrath.', },
  },
  [10985] = {
    'Un diversivo per Akama',
    {'<Xi\'ri pulsa di luci mentre le forze degli Aldor e degli Scrutatori intorno a lui rispondono ai suoi ordini. L\'esercito di Xi\'ri è pronto a respingere le forze di Illidan e a creare il diversivo per Akama. Per dare inizio alla battaglia, il Naaru non attende che un tuo cenno.>', },
    {'Assicurati che Akama e Maiev entrino nel Tempio Nero nella Valle di Torvaluna dopo che le forze di Xi\'ri avranno creato il diversivo.', },
  },
  [10989] = {
    'Mog\'dorg il Corrugato',
    {'Mog\'dorg il Corrugato ti attende in cima alla torre. Mi ha detto di tenere gli occhi aperti per trovare un individuo come te, $C. Sicuramente parlerete di cose intelligenti.|n|nAdesso va\', ma non dirlo a nessuno. È un segreto!', },
    nil,
  },
  [10995] = {
    'Grulloc ha due teschi',
    nil,
    nil,
  },
  [10996] = {
    'La Cassa del Tesoro di Maggoc',
    {'Maggoc pattuglia l\'area della Cresta delle Lame, a sud-est. Suo padre gli aveva assegnato il titolo di guardiano del massiccio orientale e lui si diverte a terrorizzare qualsiasi creatura che incontra.|n|nIn quanto Figlio di Gruul, anche lui dev\'essere eliminato se vogliamo che il mio clan sopravviva. E qui entri in gioco tu.|n|nMaggoc porta sempre con sé una cassa del tesoro. Dimostrami che è stato ucciso portandomi la cassa. Potrai tenere per te tutto ciò che troverai al suo interno.', },
    nil,
  },
  [10997] = {
    'A ognuno il suo stendardo',
    {'Conosci Shattrath, $C? Sopra la città, a nord-ovest, ci sono i Monti Granbarriera, raggiungibili soltanto in volo.|n|nUno dei Figli di Gruul, Slaag, decise di isolarsi lassù e di comandare gli Ogre Gordunni che risiedono lassù. Anche se è molto distante da qui, non possiamo permetterci di lasciarlo in vita: potrebbe tornare una volta uccisi tutti i suoi fratelli.|n|n$N, raggiungilo e portami il suo stendardo come prova della sua morte.', },
    nil,
  },
  [10998] = {
    'Alza il volume!',
    nil,
    nil,
  },
  [11000] = {
    'Nel Tritaspiriti',
    {'Il grimorio sarà essenziale per uccidere Skulloc.|n|nPer iniziare il rituale, leggi il libro a voce alta al Riparo di Tritaspiriti. Apparirà un oggetto noto come il Tritaspiriti e, insieme a esso, i Fantasmi delle vittime di Skulloc, che cercheranno di distruggerlo. Tu devi impedirglielo, almeno finché Skulloc non avrà raggiunto del tutto questo mondo.|n|nPer recarti al Riparo, dirigiti a nord e attraversa il Canyon delle Fauci Aguzze, che si trova dall\'altra parte del Cerchio del Sangue. Lo troverai sulla destra, prima dell\'Antro di Gruul.|n|nRiportami l\'anima di Skulloc.', },
    nil,
  },
  [11001] = {
    'Sconfiggi il Dio dei Corvi',
    nil,
    nil,
  },
  [11002] = {
    'La caduta di Magtheridon',
    nil,
    {'Porta la Testa di Magtheridon al Comandante delle Forze Danath Cacciatroll nella Rocca dell\'Onore della Penisola del Fuoco Infernale.', },
  },
  [11003] = {
    'La caduta di Magtheridon',
    nil,
    {'Porta la Testa di Magtheridon a Nazgrel in Thrallmar, nella Penisola del Fuoco Infernale.', },
  },
  [11004] = {
    'Il mondo delle ombre',
    {'Il Comandante dei Cieli Adaris è stato gravemente ferito durante un\'incursione Skettis. Da allora perde continuamente conoscenza.|n|nTemo che sia stato sopraffatto dai deliri della febbre. Nei rari momenti di lucidità mi chiede di preparargli un elisir con la polvere d\'ombra degli Arakkoa. A quanto pare crede che gli permetterebbe di osservare un "mondo delle ombre" nel quale risiedono i veri capi degli Arakkoa.|n|nNon credo affatto a queste sciocchezze, ma temo che non si darà pace finché non gli procurerò questo elisir. Vuoi aiutarmi?', },
    {'Severin ti ha chiesto di andare a Skettis e di prendere 6 Polveri d\'Ombra dagli Arakkoa che vivono lì.', },
  },
  [11005] = {
    'Segreti dei Sacerdoti dell\'Artiglio',
    {'Grazie per aver ascoltato il mio sfogo. Da tempo cerchiamo di individuare e distruggere la catena di comando di Skettis; eravamo al corrente dell\'esistenza di tre Chierici noti come i Sacerdoti dell\'Artiglio, ma non li avevamo mai visti con i nostri occhi. Ora sappiamo perché.|n|nParla con Severin per avere ancora un po\' dell\'elisir che ha scoperto. Usalo per trovare e uccidere i tre Sacerdoti dell\'Artiglio: Ishaal, Skizzik e Zellek. Pare risiedano a Vol Ala\'rak, vicino alla costa orientale del Lago di Ventotetro.', },
    {'Procurati un Elisir delle Ombre da Severin e usalo per trovare e uccidere il Sacerdote dell\'Artiglio Ishaal, il Sacerdote dell\'Artiglio Skizzik e il Sacerdote dell\'Artiglio Zellek a Skettis. Una volta completata la missione, torna dal Comandante dei Cieli Adaris.', },
  },
  [11006] = {
    'Altra polvere d\'ombra',
    nil,
    nil,
  },
  [11007] = {
    'Kael\'thas e la sfera verdeggiante',
    {'<L\'aria intorno a te ronza... un brusio delicato. I Naaru sono al corrente della tua vittoria. Forse sono loro il motivo dell\'irresistibile impulso che ti ha spinto a raccogliere questa sfera dai resti ancora caldi di Kael\'thas Solealto. Quali segreti contiene?>|n|n<Forse A\'dal, a Shattrath, potrebbe comprenderne la natura.>', },
    {'Porta la Sfera Verdeggiante ad A\'dal a Shattrath.', },
  },
  [11008] = {
    'Fuochi su Skettis',
    {'Credi di avere le capacità per far parte dei Guardacieli? Vedremo come te la cavi in volo.|n|nGli Arakkoa stanno allevando un numero enorme dei loro famigli d\'attacco e li stanno usando contro i nostri esploratori. Voglio che usi queste cariche esplosive per distruggere gli Incubatori sulle abitazioni degli Arakkoa. Evita i mostruosi kaliri a guardia degli Incubatori. Ti disarcioneranno prima che te ne accorga.', },
    {'Trova le Uova di Kaliri Mostruoso sulla cima delle abitazioni degli Arakkoa e usa le Cariche Esplosive dei Guardacieli su di esse. Poi torna dal Capo Squadriglia Doryn.', },
  },
  [11009] = {
    'Il paradiso degli Ogre',
    {'Ora che ci hai liberato dai nostri vincoli, possiamo cominciare a riunire tutti i clan in uno solo. Occorrerà del tempo... i vecchi rancori non si superano dall\'oggi al domani.|n|nA ogni modo, ciò che adesso è veramente urgente è che ti rechi a Ogri\'la, nei cieli a ovest. Devi difendere Ogri\'la e noi da quelle forze superiori da cui i Gronn ci proteggevano: gli Eterei, i demoni e soprattutto lo Stormo dei Draghi Neri.|n|nQuando giungerai al paradiso degli Ogre, cerca il saggio Chu\'a\'lor per sapere cosa fare.', },
    {'Mog\'dorg il Corrugato ti ha chiesto di parlare con Chu\'a\'lor a Ogri\'la nelle Montagne Spinaguzza.', },
  },
  [11010] = {
    'Bombardamento',
    {'Hai una cavalcatura volante... e allora? Credi di saperla usare a dovere?|n|nFornace Ira e Fornace Terrore, a nord e a sud, sono due vere seccature, oltre che una minaccia alla pacifica Ogri\'la. Però, con tutti quei Vilcannoni che minacciano di abbattere i Guardacieli, non abbiamo il tempo per occuparcene.|n|nVuoi dimostrare il tuo valore? Prendi queste bombe e fai saltare in aria le loro pile di munizioni. E stai $Gattento:attenta; a non farti abbattere anche tu!', },
    nil,
  },
  [11012] = {
    'Il Giuramento di Sangue degli Alafatua',
    nil,
    nil,
  },
  [11013] = {
    'Al servizio degli Illidari',
    {'L\'Isola degli Alafatua... Un tempio bastione di sacralità per gli Alafatua, ora è la dimora delle Fauci di Drago. Anche se gli Orchi controllano il territorio, la nostra magia è ancora potente. Abbastanza potente da mascherare la tua vera identità e permetterti d\'infiltrarti tra i ranghi delle Fauci di Drago.|n|nHo preparato questa lettera che dovrai presentare al loro capo, il Supremo Mor\'ghor. Vola tra le fauci del nemico e cerca il Campo Base delle Fauci di Drago, dove inizierai la tua nuova vita come Vilorco di Illidan Grantempesta.', },
    nil,
  },
  [11014] = {
    'Entri il Coordinatore',
    {'<Mor\'ghor accartoccia i Documenti di Servizio e li getta via.>|n|nVa bene, vediamo di cominciare dalle cose fondamentali. Se intendi unirti al mio amato esercito delle Fauci di Drago, dovrai lavorare. Qui sull\'Isola, lavorano tutti. Trovati un lavoro, non combinare guai e vedrò se c\'è qualcosa di più interessante da farti fare.|n|nVai al parlare con il Coordinatore Varkule Ruttafuoco. È al centro della città. Valuterà le tue capacità e ti assegnerà l\'incarico che ritiene opportuno.|n|nOra levati di torno!', },
    {'Parla con il Coordinatore Varkule Ruttafuoco al Campo Base delle Fauci di Drago.', },
  },
  [11015] = {
    'I Cristalli degli Alafatua',
    nil,
    {'Il Coordinatore Varkule Ruttafuoco al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di portargli 30 Cristalli degli Alafatua.', },
  },
  [11016] = {
    'Pelli di Scorticatore Cavafatua',
    {'$GUno scuoiatore:Una scuoiatrice;, eh? Be\', qui troverai molte pelli! Devi cercare gli Scorticatori vicino alle formazioni cristalline. Uccidili e scuoiali. A volte, si ottengono delle pelli di valore. Portamele.', },
    {'Il Coordinatore Varkule Ruttafuoco al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di portargli 35 Pelli di Scorticatore Cavafatua.', },
  },
  [11017] = {
    'Polline di Nubefatua',
    {'Cogli fiori?!? Spassoso... Sfortunatamente, i nostri Maghi e i nostri Sciamani hanno bisogno dei tuoi servigi. I Cespugli di Nubefatua che crescono sull\'isola producono un polline speciale che sembra essere molto utile nelle faccende magiche. Portamelo e considererò completato il tuo incarico.', },
    {'Il Coordinatore Varkule Ruttafuoco al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di portargli 40 Pollini di Nubefatua.', },
  },
  [11018] = {
    'Faturcite',
    {'$GUn minatore:Una minatrice;!|n|n<Varkule ti saluta.>|n|nSegui le mie orme! È così che ha iniziato Varkule: facendo il minatore! Non c\'è niente di meglio che darsi da fare nelle miniere, vero?|n|nOra vai e trova i depositi di faturcite. Estrai tutto il possibile e portami il minerale.', },
    {'Il Coordinatore Varkule Ruttafuoco al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di portargli 40 Minerali di Faturcite.', },
  },
  [11019] = {
    'Il tuo amico nel sistema',
    nil,
    nil,
  },
  [11020] = {
    'Una morte lenta',
    {'Quassù, le Fauci di Drago hanno posizionato Peoni quasi a ogni formazione cristallina. Ucciderli attirerebbe troppa attenzione su di te, ma c\'è un modo per ridurre le loro file senza che Mor\'ghor sospetti nulla.|n|nAvventurati nelle terre selvagge della Valle di Torvaluna e uccidi gli animali contagiati. Prendi le loro vil ghiandole e usale su questo montone che servirò ai Peoni. Ne assaggeranno un morso e poi cadranno stecchiti!', },
    nil,
  },
  [11021] = {
    'Almanacco di Ishaal',
    {'<Questo tomo misterioso è stato rinvenuto sul corpo del Sacerdote dell\'Artiglio Ishaal. Contiene simboli arcani e carte dei corpi celesti al di là della tua comprensione.>|n|n<Le scritte sono tutte in una lingua che non conosci, sembra una versione antica di quella degli Arakkoa. Forse dovresti portarlo al Comandante dei Cieli Adaris.>', },
    {'Consegna l\'Almanacco di Ishaal al Comandante dei Cieli Adaris nell\'area nord di Skettis.', },
  },
  [11022] = {
    'Colloquio con Mog\'dorg',
    nil,
    {'Parla con Mog\'dorg il Corrugato. Si trova in cima alla torre sul lato orientale del Cerchio del Sangue nelle Montagne Spinaguzza.', },
  },
  [11023] = {
    'Bombardali ancora!',
    {'$N, quella Contraerea ci procura ancora dei fastidi.|n|nNon fraintendermi... Penso che la volta scorsa tu abbia fatto un ottimo lavoro... ma questo non cambia il fatto che quei dannati demoni ricostituiscono le loro riserve di munizioni più velocemente di quanto noi le distruggiamo. E questo significa che stiamo incontrando grosse difficoltà nel far giungere i nostri laggiù, senza considerare la minaccia posta dai demoni a Ogri\'la.|n|nChe ne dici? Vuoi fare un altro giro?', },
    nil,
  },
  [11024] = {
    'Un alleato nella Città Bassa',
    {'Nella Città Bassa si trova un Arakkoa di nome Rilak... Puoi fidarti di lui. Portagli... il libro.|n|n<Adaris perde conoscenza mentre ti passa il libro.>', },
    nil,
  },
  [11025] = {
    'I cristalli',
    {'Se trattati correttamente, i cristalli delle montagne dimostrano di possedere strani poteri, come la lucidità mentale che abbiamo trovato qui a Ogri\'la.|n|nTutte le creature delle montagne desiderano avidamente i frammenti di questi cristalli e se ne servono per i propri scopi. Su di essi è stato persino fondato un sistema economico.|n|nPer aiutarci, devi anzitutto saperne di più sulle Schegge Apexis. Portamene qualcuna. Oltre che addosso ad alcune creature locali, puoi trovarle nei punti in cui gli Scorticatori scavano tra i cristalli più grandi.', },
    {'Chu\'a\'lor ti ha chiesto di recuperare 5 Schegge Apexis e di portargliele a Ogri\'la, in cima alle Montagne Spinaguzza.', },
  },
  [11026] = {
    'Bandire i demoni',
    {'$GAmico mio, sei giunto:Amica mia; sei giunta; al momento giusto! Abbiamo urgente bisogno di aiuto. In cambio riceverai qualcosa di molto raro che alla fine tornerà utile a entrambi.|n|nNoi non siamo più degli Ogre violenti, ma i demoni qui vicino minacciano di sopraffare noi e i Guardacieli. Il problema con i demoni è che una volta uccisi rinascono in nuovi corpi!|n|nTuttavia, è possibile usare questo Cristallo per evocare un Portale dell\'Esilio. Se un demone muore vicino al portale, la sua essenza sarà risucchiata al suo interno e ricacciata da dove è venuta!', },
    nil,
  },
  [11028] = {
    'Conto alla rovescia verso la distruzione',
    {'Questo almanacco presagisce il ritorno di Terokk, il più potente e terribile Re di Skettis nella storia degli Arakkoa.|n|nHo sempre creduto si trattasse solo di una leggenda, $N. Il ritorno dei Sacerdoti dell\'Artiglio e il ritrovamento di questo tomo da parte tua indicano il contrario.|n|nOgni giorno, Terokk si vicina sempre più a riacquistare il pieno delle forze. La tua unica possibilità è portarlo prematuramente nel nostro mondo. Torna a Skettis e informa Adaris. Speriamo che abbia abbastanza senno per fare la cosa giusta.', },
    nil,
  },
  [11029] = {
    'Un maldestro travestimento',
    {'Apri la cassa, $N. È un travestimento. Non sembra molto convincente, vero?|n|nLi realizzo per i contrabbandieri Eterei che cercano libri rari. C\'è uno Scriba Arakkoa che vive nell\'isola centrale di Skettis, Requie di Terokk; si chiama Sahaak. È vecchio e quasi completamente cieco.|n|nUsa il travestimento per parlare con lui e farti consegnare il libro conosciuto come "Lignaggi Rivali". Fa\' attenzione, $N. Il travestimento non ingannerà gli altri Arakkoa.', },
    {'Usa il Maldestro Travestimento Arakkoa per prendere a Sahaak il libro "Lignaggi Rivali" e torna da Hazzik.', },
  },
  [11030] = {
    'Il nostro ragazzo vuole diventare un Incursore dei Guardacieli',
    {'$C, abbiamo un problema... Noi abbiamo molti figli e, da quando i Guardacieli si sono trasferiti qui vicino, non parlano d\'altro che di unirsi ai loro ranghi.|n|nDa bravi padri, vogliamo garantire che la loro domanda di arruolamento venga accettata. Non potresti andare alla Vilforgia di Cristallo nell\'accampamento a sud o in quello a nord e procurare un tonico magico per i nostri figlioli? Non puoi sbagliarti: li riconoscerai dal fumo verde.|n|nCredo ci vogliano dieci Schegge Apexis per prepararli. Te le daremmo noi, ma al momento non ne abbiamo.', },
    nil,
  },
  [11031] = {
    'Non più Arcimago',
    nil,
    nil,
  },
  [11033] = {
    'Non più Assassino',
    nil,
    nil,
  },
  [11035] = {
    'Cieli non molto amici...',
    {'Sulla costa nordorientale dell\'isola, c\'è una banchina usata per l\'imballaggio e la spedizione dei cristalli e delle reliquie degli Alafatua. I Trasportatori delle Fauci di Drago portano le merci alla Fortezza delle Fauci di Drago, mentre gli Ascesi delle Fauci di Drago li proteggono da terra da possibili assalitori.|n|nQuindi, puoi attaccarli solo in un punto: lo Stretto delle Fauci di Drago.|n|nVola alle isole dello Stretto delle Fauci di Drago e tendi un\'imboscata ai Trasportatori che utilizzano quel percorso. Recupera le reliquie rubate!', },
    {'Yarzill il Mercenario al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di recuperare 10 Reliquie degli Alafatua.', },
  },
  [11036] = {
    'Prodotti dell\'altro mondo!',
    {'Sono il primo ad ammettere di non capire quest\'ordine, ma le istruzioni dell\'Aviatore Granturbina sono molto specifiche: solo la frutta migliore, conservata in modo da resistere agli elementi e sostenere un lungo viaggio senza deperire.|n|nC\'erano anche altre indicazioni... tenerle a gravità zero o a bassa pressione, o qualcosa del genere. Non pretendo di capire: visto che paga bene, avrà quel che cerca. Consegnagli questa cassa nell\'Area 52. Dopo essere $Gentrato:entrata; a Landa Fatua, segui la strada finché non vedi la città.', },
    nil,
  },
  [11037] = {
    'Una Strana visione',
    {'Ho avuto una visione assai strana, $N, e non so come interpretarla. Ho visto una freccia, un\'immensa freccia che saliva in cielo lasciando una scia di fuoco. Una simile impresa è banale per un abile Mago, ma so che la freccia che ho visto non è il risultato di un incantesimo.|n|nSarà qualcosa mai visto prima d\'ora su Azeroth. $N, devi cercare le persone che stanno lavorando sulla freccia. Offrigli il tuo aiuto, perché senza di te, i loro sforzi potrebbero essere vani.', },
    {'Parla con l\'Aviatore Granturbina all\'Area 52.', },
  },
  [11038] = {
    'In aiuto dell\'Esarca Orelis',
    {'Non molto tempo fa, la Gran Sacerdotessa Ishanah inviò un piccolo gruppo di Anacoreti nella Landa Fatua, sotto il comando dell\'Esarca Orelis. Dovevano indagare sulle attività di Kael\'thas e dei suoi servitori, ma non abbiamo ancora ricevuto rapporti su quanto hanno scoperto.|n|nTemo che non abbiamo abbastanza truppe nell\'area per portare a termine la missione. Sono certo che all\'Esarca tornerebbero utili il tuo sapere e la tua esperienza. Saresti $Gdisposto:disposta; a recarti nell\'Area 52 per aiutarlo?', },
    {'Parla con l\'Esarca Orelis all\'Area 52.', },
  },
  [11039] = {
    'Rapporto al Maestro di Spionaggio Thalodien',
    {'Qualche tempo fa, Voren\'thal ha inviato un piccolo gruppo nella Landa Fatua per indagare sulle attività di Kael\'thas. Il nostro capo ha la massima fiducia nel Maestro di Spionaggio Thalodien e nei suoi compatrioti e ha deciso di accogliere la sua richiesta di rinforzi.|n|nIl resoconto di Thalodien era breve, ma ha reso chiaro che è incappato in qualcosa di grande importanza. Presentati a rapporto da lui nell\'Area 52 e aiutalo in ogni modo possibile, $N.', },
    {'Presentati a rapporto dal Maestro di Spionaggio Thalodien all\'Area 52.', },
  },
  [11040] = {
    'Pezzi per l\'Aviatore',
    {'Le volte che ho collaborato con un Goblin si possono contare sulle dita di una mano: noi Gnomi siamo più abituati a competere con loro. Tuttavia, quando ho ricevuto la richiesta dell\'Aviatore Granturbina non ho potuto rifiutare.|n|nQuesta cassa è piena di pezzi di ricambio inutilizzati che l\'Aviatore potrebbe sfruttare per il suo progetto. Saresti così gentile da consegnarglieli, se passi dalle parti dell\'Area 52?|n|nChissà, magari qualche pezzo di fine fattura gnomesca potrebbe impedire a quell\'aggeggio di esplodere!', },
    nil,
  },
  [11041] = {
    'Un lavoro lasciato a metà...',
    {'In nome del nostro grande maestro... Per la gloria di Illidan!|n|nPer ordine del Supremo Mor\'ghor, la grande piana dell\'Isola degli Alafatua dev\'essere conquistata. Ora che tutti i Drachi Alafatua sono stati catturati o scacciati, gli Sferzaroccia la fanno da padroni e mettono a rischio le nostre attività di raccolta dei cristalli.|n|nDistruggili tutti, compresa la Madre dell\'Antro e il suo consorte, Arvoar.|n|nMor\'ghor lo ordina!|n|n<Sembra che quest\'Orco non sia riuscito a conquistare la piana. È ora di dimostrare quanto vali a Mor\'ghor!>', },
    {'Uccidi 10 Scorticatori Cristallini e Barash la Madre dell\'Antro. Qualora dovessi riuscirci, torna dal Supremo Mor\'ghor al Campo Base delle Fauci di Drago.', },
  },
  [11042] = {
    'Una visione mistificatrice',
    {'$N, una strana visione mi tormenta. Vedo una nube di fumo che sale incessante verso il cielo, lasciata da un fuoco gigantesco che si allontana sempre più velocemente. Non è un fenomeno naturale né il risultato di un atto malvagio. Di questo sono certo.|n|nNon ho idea di che aspetto abbia, ma so che è il frutto del lavoro di molti. Tuttavia, senza l\'aiuto di altri, potrebbe non verificarsi mai.|n|nRecati nella Landa Fatua, $C. Trova i responsabili di questa creazione e offrigli il tuo aiuto.', },
    {'Parla con l\'Aviatore Granturbina all\'Area 52.', },
  },
  [11043] = {
    'Come migliorare un grifone',
    {'Ho sentito che i Nani Granmartello possiedono un Nido dei Grifoni nella loro fortezza nella parte meridionale della Valle di Torvaluna. Nel caso ti stessi recando laggiù, parleresti con loro a nome mio? Ho alcune idee su come migliorare i loro grifoni!|n|nPerché limitarsi a corazzarli, quando gli si potrebbe montare sopra un altimetro, uno specchietto retrovisore e un razzo? Immagina che velocità, con uno di quei giocattolini attaccati al tuo grifone! Lo chiamerò TurboGrifone 8000!', },
    nil,
  },
  [11044] = {
    'Visioni di distruzione',
    {'Una visione catastrofica disturba spesso il mio riposo. Una pioggia di fuoco verde, che decima i valorosi difensori di una possente fortezza. Sono settimane che mi tormenta, anche se è da poco che ne ho compreso il significato.|n|nMolto a est, nella Valle di Torvaluna, i Nani Granmartello sono sotto costante attacco della Legione Infuocata e di numerosi altri nemici. Combattono coraggiosamente, ma senza aiuto, i loro nemici trionferanno. $N, schierati al loro fianco. Aiutali nella loro battaglia.', },
    {'Parla con il Comandante di Squadrone Nuainn alla Roccaforte dei Granmartello.', },
  },
  [11045] = {
    'Zorus il Giudicatore',
    {'La Valle di Torvaluna ha una storia lunga e piena di sventure. In pochi ne parlano per timore di ridare vita alle innominabili atrocità che vi sono avvenute.|n|nTuttavia, non tutti sono così timorosi. Zorus il Giudicatore vuole scoprire la verità sui fantasmi del passato di Torvaluna. È un\'impresa colossale, per la quale accetterebbe volentieri aiuto.|n|nQualora dovessi avventurarti nella valle, cercalo alla Roccaforte dei Granmartello, nella parte centrale della regione meridionale della valle.', },
    {'Parla con Zorus il Giudicatore alla Roccaforte dei Granmartello.', },
  },
  [11046] = {
    'Capo Speziale Hildagard',
    {'La Valle di Torvaluna ha una storia lunga e piena di sventure. In pochi la studiano per timore di ridare vita alle innominabili atrocità che vi sono avvenute.|n|nTuttavia, non tutti sono così timorosi. Il Capo Speziale Hildagard vuole scoprire la verità sui fantasmi del passato di Torvaluna. È un\'impresa colossale, per la quale accetterebbe volentieri aiuto.|n|nQualora i tuoi viaggi ti dovessero portare in quell\'area, cercala al Villaggio di Torvaluna, nell\'area nordoccidentale della valle.', },
    {'Parla con il Capo Speziale Hildagard al Villaggio di Torvaluna.', },
  },
  [11047] = {
    'La richiesta dell\'Apprendista',
    {'Come Apprendista Maestro delle Viverne dei Venti, devo prendermi cura delle bestie quando non sono in volo. Il problema è che ne abbiamo così poche che i loro periodi di riposo sono molto ridotti.|n|nSe non ne riceveremo delle altre, temo che quelle che abbiamo moriranno di fatica. Al Villaggio di Torvaluna, nella parte occidentale della Valle di Torvaluna, c\'è una grossa scuderia. Lì Demi Manto Selvaggio supervisiona l\'allevamento e l\'addestramento delle Viverne dei Venti.|n|nLe parleresti a nome nostro, spiegandole la nostra situazione?', },
    nil,
  },
  [11048] = {
    'Il rapporto di Kroghan',
    {'I miei ordini originali erano di rimanere brevemente a Garadar e quindi proseguire e fare rapporto alla Guardia di Sangue Gulmok nel Villaggio di Torvaluna. Da quanto ho visto durante la mia permanenza qui, a Garadar sarebbe di grande aiuto un rapporto di lungo termine con l\'Orda.|n|nSo che la Guardia di Sangue Gulmok ha bisogno di tutte le truppe possibili, ma so anche che capirà che la mia missione qui non è ancora terminata. Vai al Villaggio di Torvaluna, nella parte nordoccidentale della Valle di Torvaluna e informa la Guardia di Sangue Gulmok del mio ritardo.', },
    {'Parla con la Guardia di Sangue Gulmok al Villaggio di Torvaluna.', },
  },
  [11049] = {
    'La grande caccia alle Uova di Alafatua',
    {'Se mai dovessi scoprire delle Uova di Alafatua mentre sei in esplorazione, portamele.|n|nSappi, però, che sono molto rare. Non farti prendere dalla frustrazione se non riesci a trovarne. Le Fauci di Drago sono stati molto meticolosi nel prenderne la maggior parte e farle portare chissà dove.|n|nPotresti trovarle su creature dell\'isola, vicino a formazioni cristalline, nelle miniere o persino dentro un Minerale di Faturcite o un Cespuglio di Nubefatua.|n|nNon attirare l\'attenzione. Non vogliamo che Mor\'ghor si accorga di qualcosa.', },
    {'Yarzill il Mercenario al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di recuperare un Uovo di Alafatua.', },
  },
  [11050] = {
    'Si accettano tutte le uova',
    nil,
    nil,
  },
  [11051] = {
    'Bandire altri demoni',
    {'Se conosciamo i demoni, e li conosciamo perché li abbiamo studiati a lungo, ripareranno velocemente qualsiasi danno subito dal loro prezioso Connettore.|n|nSe vuoi avere la possibilità di recuperare un\'altra Runa Oscura, torna con il nostro Cristallo dell\'Esilio ed elimina altri demoni. D\'altronde vuoi aiutarci a respingere la minaccia posta dai demoni, no?|n|nAbbiamo parlato di "possibilità" perché il nostro procedimento non sempre porta i risultati sperati. Potresti ottenere una Runa Oscura o qualcosa di completamente diverso.', },
    nil,
  },
  [11052] = {
    'La promessa di Akama',
    {'<Akama incastona il cristallo nel medaglione che tiene in mano.>|n|nNon sono più forte come un tempo, $N. Rimanere vicino al male per così tanto tempo... Non so se posso fidarmi di me stesso e tenere un manufatto tanto potente.|n|nPrendilo, come promessa che quando giungerà il momento di affrontare Illidan, sarò al tuo fianco. Portalo all\'unico essere a cui possiamo affidarlo in tutta sicurezza. Porta il medaglione ad A\'dal a Shattrath.', },
    {'Porta il Medaglione di Karabor ad A\'dal a Shattrath.', },
  },
  [11053] = {
    'Alzati, Sovrintendente!',
    {'È raro che $Gun:una; Peone sopravviva tanto a lungo quanto hai fatto tu. Ancora più raro è che si affermi fino a raggiungere un nuovo grado.|n|n<Varkule applaude.>|n|nIl Supremo ha chiesto di te. Ti aspetta senz\'altro un nuovo grado.', },
    {'Parla con il Supremo Mor\'ghor al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11054] = {
    'Sovrintendere: fare le scelte giuste',
    nil,
    nil,
  },
  [11055] = {
    'Lo Stivale Rotante: la cura definitiva per il Peone qualunque',
    nil,
    {'Il Gran Sovrintendente Granfango al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di disciplinare 20 Peoni delle Fauci di Drago Pigri. Dovrai anche restituire il tuo Stivale Rotante.', },
  },
  [11056] = {
    'L\'accordo di Hazzik',
    {'Non attiriamo l\'attenzione. Adaris non sarebbe d\'accordo.|n|nIo appartengo alla casta più bassa degli Arakkoa, $N. Sotto il regno di Terokk sarei stato sacrificato agli oscuri poteri venerati dai suoi Sacerdoti dell\'Artiglio. Se ciò che dici è vero e i Sacerdoti dell\'Artiglio vogliono il ritorno di Terokk, allora devi impedire che ciò avvenga, a prescindere da quanto dica il tuo capo!|n|nHo qualcosa da offrirti che ti sarà utile. Presso la mia vecchia abitazione a Vol Shil\'ak Superiore c\'è una cassa. Portamela!', },
    {'Prendi la Cassa di Hazzik dalla sua abitazione nella zona orientale di Skettis e riportagliela.', },
  },
  [11057] = {
    'Laggiù si sta male',
    nil,
    nil,
  },
  [11058] = {
    'Una Reliquia Apexis',
    {'Molto tempo fa, qui viveva una setta degli Arakkoa ormai estinta, nota come Apexis. Testimonianze della loro civiltà sono tuttora rintracciabili. Noi le chiamiamo Reliquie Apexis.|n|nDi esse sappiamo che, se usate correttamente, forniscono dei benefici. Ciascuna Reliquia presenta una sequenza colorata in cui i cristalli vanno premuti nell\'ordine corretto. Si tratta di una sfida che si estende per più livelli, sempre più difficili.|n|nPer attivare le Reliquie Apexis occorrono le Schegge Apexis. Torna da me quando avrai compreso il segreto delle Vibrazioni Apexis.', },
    nil,
  },
  [11059] = {
    'Il Guardiano del Monumento',
    nil,
    nil,
  },
  [11061] = {
    'Il dovere di un padre',
    {'Quanto all\'altro tonico magico, si può ottenere in un solo luogo: l\'Approdo di Bash\'ir. Si tratta di una base di Eterei, che come si sa non sono molto amichevoli con gli estranei, quindi ottenerlo potrebbe rivelarsi pericoloso.|n|nDov\'è l\'Approdo di Bash\'ir, mi chiedi? Be\', monta sul tuo destriero volante, dirigiti a nord e poi, una volta superata la Fornace Ira, a nord-est: alla fine lo troverai. La Forgia di Cristallo Bash\'ir si trova nell\'angolo nordorientale dell\'Approdo.|n|nTi ringraziamo, $N. Significa molto per i nostri figli!', },
    nil,
  },
  [11062] = {
    'L\'Avamposto dei Guardacieli',
    {'$N, ci chiedevamo se potessi far visita ai nostri amici a nord, all\'Avamposto dei Guardacieli...|n|nIl Comandante dei Cieli Keller sta conducendo, con i suoi Guardacieli, delle missioni difensive e ci ha chiesto di mandare lassù chiunque riteniamo possa aiutarlo con profitto.|n|nPotresti essere tu!|n|nRecati lì non appena possibile e salutalo da parte nostra.', },
    nil,
  },
  [11063] = {
    'Guadagnarsi le ali...',
    nil,
    nil,
  },
  [11064] = {
    'La corsa delle Fauci di Drago: la ballata di McVeck Il Vecchio',
    nil,
    {'Segui Murg "Il Vecchio" Faucilorde restando sulla tua Cavalcatura Volante. Se riuscirai a sconfiggere Murg "Il Vecchio" Faucilorde, comunica la tua vittoria a Ja\'y Nosliw al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11065] = {
    'Servono Mante Vacue!',
    nil,
    nil,
  },
  [11066] = {
    'Servono altre Mante Vacue!',
    nil,
    nil,
  },
  [11067] = {
    'La corsa delle Fauci di Drago: Trope lo Sputasporco',
    {'Le Fauci di Drago ti trattano come meriti, $N. Danno una possibilità persino a un relitto come me. Ora, se vuoi dimostrarti $Gdegno:degna; degli Spaccacieli, dovrai sconfiggermi.|n|nTi scrollerò di dosso come una fastidiosa zecca...|n|nDecolliamo quando vuoi.', },
    {'Segui Trope lo Sputasporco restando sulla tua Cavalcatura Volante. Se riuscirai a sconfiggere Trope lo Sputasporco, comunica la tua vittoria a Ja\'y Nosliw al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11068] = {
    'La corsa delle Fauci di Drago: Corlok il Veterano',
    {'Vuoi sfidare me? Non farmi ridere!|n|nFai sul serio? Molto bene! Devi solo cercare di non morire. Ce la puoi fare, vero??? Anche se ti lancio contro dei teschi e ti volo intorno deridendo la tua patetica abilità nel cavalcare?|n|nFammi sapere quando sei $Gpronto:pronta; e decolleremo.', },
    {'Segui Corlok il Veterano restando sulla tua Cavalcatura Volante. Se riuscirai a sconfiggere Corlok il Veterano, comunica la tua vittoria a Ja\'y Nosliw al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11069] = {
    'La corsa delle Fauci di Drago: il Comandante di Squadriglia Ichman',
    nil,
    {'Segui il Comandante di Squadriglia Ichman restando sulla tua Cavalcatura Volante. Se riuscirai a sconfiggere il Comandante di Squadriglia Ichman, comunica la tua vittoria a Ja\'y Nosliw al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11070] = {
    'La corsa delle Fauci di Drago: il Comandante di Squadriglia Mulverick',
    nil,
    nil,
  },
  [11071] = {
    'La corsa delle Fauci di Drago: il Capitano Spezzacielo',
    {'Osi sfidare Spezzacielo? Sprofonderai nelle tenebre, mentre il cielo sarà fatto a pezzi dalle mie meteore.|n|nNon hai possibilità, soldato. Tuttavia, se desideri morire...|n|nAsseconderò questa tua insana ossessione, anche solo per dare una lezione a tutti coloro che potrebbero avere lo stesso sciocco sogno.|n|nDecolliamo quando vuoi!', },
    {'Segui il Capitano Spezzacielo restando sulla tua Cavalcatura Volante. Se riuscirai a sconfiggere il Capitano Spezzacielo, comunica la tua vittoria a Ja\'y Nosliw al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11072] = {
    'Lignaggi Rivali',
    nil,
    nil,
  },
  [11073] = {
    'La caduta di Terokk',
    {'Io... ho chiuso un occhio sul tuo comportamento con il prigioniero Arakkoa, $N. A quanto pare la tua idea di collaborare con lui era sensata.|n|nDevi capire... nella mia situazione attuale, se avessi sostenuto i tuoi sforzi per portare Terokk in questo mondo, avrei dovuto affrontare un ammutinamento.|n|nPrendi gli oggetti che Hazzik ha preparato per te e procedi con il tuo piano. Al momento opportuno ordinerò ai miei uomini di aiutarti, ma ti consiglio di portare qualcuno con te. Temo che avrai solo una possibilità di riuscita.', },
    {'Porta l\'Offerta Preistorica preparata da Hazzik alla Pila di Teschi al centro di Skettis e poi evoca e sconfiggi Terokk. Una volta completata questa missione, torna dal Comandante dei Cieli Adaris.', },
  },
  [11074] = {
    'Cimeli dei discendenti',
    {'I discendenti tenuti prigionieri dai Sacerdoti dell\'Artiglio di Skettis sono elencati in questo libro: Gezzarak la Cacciatrice, Karrog il Gigante di Cristallo, l\'eretico conosciuto come Stridente Oscuro Akkarai e Vakkiz lo Sfuriavento. Devono essere tutti uccisi prima che Terokk ritorni in questo mondo.|n|nAvrai bisogno delle pergamene dell\'Arakkoa Preistorico e dovrai bruciarle presso i Circoli d\'Evocazione in tutta Skettis. Portami un cimelio di ciascuno di loro. Affronterai esseri potenti... quindi farai meglio a portarti dei compagni.', },
    {'Prendi 10 Pergamene Preistoriche dagli Arakkoa Perduti nel Tempo a Skettis e portale a una Pila di Teschi in un Circolo d\'Evocazione a Skettis. Evoca e sconfiggi i discendenti degli avversari di Terokk e torna da Hazzik con gli Artigli di Akkarai, la Spina di Karrog, la Scaglia di Vakkiz e gli Artigli di Gezzarak.', },
  },
  [11075] = {
    'Le Miniere degli Alafatua',
    {'Sovrintendente $N, è stato richiesto il tuo aiuto nelle Miniere degli Alafatua.|n|nDue giorni fa, le nostre attività di scavo si sono arrestate in seguito a una terribile scoperta. Un minatore che lavorava nelle gallerie più profonde, ha colpito con il piccone una formazione cristallina inusuale. Purtroppo, questa era attaccata a un Drago Fatuo molto arrabbiato. La bestia si è risvegliata e ha spazzato via tutti i nostri operai.|n|nPresentati dalla Signora delle Miniere. Ti aspettano all\'ingresso delle gallerie, a sud-ovest.', },
    {'Cerca la Signora delle Miniere sull\'Isola degli Alafatua.', },
  },
  [11076] = {
    'Raccogliere i pezzi...',
    {'Gran parte del frutto del nostro duro lavoro è sparsa per le miniere. Ci sono carrelli carichi fino all\'orlo ovunque! E con l\'infestazione, non possiamo recuperarne nessuno.|n|nE qui entri in gioco tu, $N. Il tuo incarico giornaliero alla miniera consiste nel recuperare i carichi abbandonati dai minatori e dagli operai che lavorano in profondità.|n|nRaccogli i carichi di Cavafatua e portali a me o a mia sorella.', },
    {'La Signora delle Miniere nelle Miniere di Alafatua della Valle di Torvaluna ti ha chiesto di recuperare 15 Casse di Carico di Cavafatua.', },
  },
  [11077] = {
    'I draghi sono l\'ultimo dei nostri problemi',
    {'Il drago che si è risvegliato ha fatto infuriare diverse creature fastidiose delle miniere. Due razze in particolare si stanno dimostrando una spina nel fianco per le Fauci di Drago: gli Scorticatori Cavafatua e i Devastatori Cavafatua. Devi aiutarci a ucciderli tutti. Ti chiedo solo di occupartene una volta al giorno.|n|nEntra e uccidine più che puoi!', },
    {'Il Caposquadra delle Fauci di Drago nelle Miniere di Cavafatua della Valle di Torvaluna ti ha chiesto di uccidere 15 Scorticatori Cavafatua e 5 Devastatori Cavafatua.', },
  },
  [11078] = {
    'Dominare i cieli',
    nil,
    nil,
  },
  [11079] = {
    'Una Vil Frusta per Gahk',
    nil,
    nil,
  },
  [11080] = {
    'Emanazioni della Reliquia',
    {'Ora che sei in grado di avvertire le illuminanti vibrazioni delle Reliquie Apexis, puoi comprenderne il funzionamento. Non vediamo l\'ora di ascoltare le tue analisi!|n|nMan mano che entrerai in armonia con le reliquie, acquisirai anche una conoscenza sempre maggiore che si manifesterà sotto forma di emanazioni da parte delle reliquie.|n|nTorna da noi quando avrai ottenuto tali emanazioni.', },
    nil,
  },
  [11081] = {
    'La grande rivolta dei Sanguebuio',
    {'Questo documento delinea una rivolta pianificata dai Corrotti Sanguebuio. Sembra che il drago dovesse fungere da diversivo per distogliere l\'attenzione dalla loro fuga. A giudicare dai cadaveri sparsi per la miniera, possiamo dire con sicurezza che il loro piano è fallito.|n|nPorta i piani d\'evasione alla Signora delle Miniere.', },
    {'Porta i Piani d\'Evasione dei Sanguebuio alla Signora delle Miniere.', },
  },
  [11082] = {
    'Alla ricerca della verità',
    {'I minatori sono troppo stupidi per ideare un piano di fuga. Dobbiamo trovare e punire la mente. Addentrati negli abissi della miniera e cerca i Sovrintendenti Sanguebuio. Si staranno nascondendo, sempre che non siano stati sopraffatti dagli abitanti della miniera.|n|nQuando ne avrai trovato uno, interrogalo finché non rivela l\'identità della vera mente dietro al piano di fuga. Torna da me con il nome del traditore e la mano del Sovrintendente.', },
    {'Trova un Sovrintendente Sanguebuio e interrogalo. Torna dalla Signora delle Miniere con le Informazioni sui Sanguebuio e con la Mano del Sovrintendente.', },
  },
  [11083] = {
    'Confusi e feroci',
    {'Non preoccuparti di questo drago, $N. Abbiamo in mente qualcosa per lui...|n|nPiù in profondità nella miniera, c\'è un gruppo di Sanguebuio impazziti. Sono rimasti isolati dopo che il drago è scappato. Per qualche motivo, dopo soli due giorni d\'isolamento, hanno dimenticato cosa fosse la decenza.|n|nSi sono dati al cannibalismo e alla distruzione. Non vogliamo che qui accadano certe cose. Trovali e uccidili. Tutti.', },
    {'Ronag lo Schiavista nelle Miniere degli Alafatua della Valle di Torvaluna ti ha chiesto di uccidere il Caposquadra Sanguebuio Frenetico e 5 Minatori Sanguebuio Frenetici.', },
  },
  [11084] = {
    'In piedi, Capitano!',
    {'Bene, bene, bene... Sei ancora in vita. È un bene, perché Mor\'ghor ha chiesto che tu lo raggiunga subito nella sua torre. Muoviti!', },
    {'Parla con il Supremo Mor\'ghor al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11085] = {
    'Fuga da Skettis',
    {'Salute, $N. Grazie per essere $Ggiunto:giunta; in mio aiuto.|n|nGli uccelli mostruosi degli Arakkoa mi hanno disarcionato dalla mia Manta Fatua mentre ero in missione esplorativa.|n|nAndiamocene da qui finché possiamo.', },
    {'Porta in salvo il Prigioniero dei Guardacieli e fai rapporto al Capo Squadriglia Doryn.', },
  },
  [11086] = {
    'La distruzione del Portale del Crepuscolo',
    {'Una delle tue responsabilità di capitano delle Fauci di Drago è individuare i movimenti della Legione Infuocata nelle Terre Esterne. È tuo dovere mettere a tacere coloro che sfidano Sire Illidan!|n|nI demoni cercano scioccamente di stabilizzare il portale trovato sulla Cresta del Crepuscolo a Nagrand occidentale. Devono pagare per la loro slealtà e sarai tu a riscattare il loro debito di fedeltà.|n|nVai alla Cresta del Crepuscolo e massacra i suoi abitanti. Dovrai sferrare almeno un attacco al giorno alle loro fortificazioni.', },
    {'Il Supremo Mor\'ghor al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha chiesto di uccidere 20 Agenti Ombromorte.', },
  },
  [11087] = {
    nil,
    {'Illidan recuperò sette fiale dal Pozzo dell\'Eternità. Tre le versò nel lago sopra al Monte Hyjal, creando un secondo Pozzo dell\'Eternità. Per anni tutte le altre furono credute perdute.|n|nCon l\'apertura del Portale Oscuro, siamo venuti a sapere che ne consegnò una a testa ai suoi luogotenenti Kael\'thas e Vashj. Recupera ciò che rimane di esse: ci serviranno come punti di focalizzazione per aprire un portale verso gli eventi, più o meno recenti, collegati al Monte Hyjal. L\'esito della Battaglia per il Monte Hyjal dev\'essere preservato.', },
    {'Soridormi alle Caverne del Tempo ti ha chiesto di recuperare la Fiala di Vashj da Dama Vashj nel Bacino degli Spiraguzza e la Fiala di Kael da Kael\'thas Solealto a Forte Tempesta.', },
  },
  [11089] = {
    'Il Cannone dell\'Anima di Reth\'hedron',
    nil,
    {'Il Signore Illidari Balthas al Campo Base delle Fauci di Drago nella Valle di Torvaluna, ti ha chiesto di portargli 2 Lingotti di Vilacciaio, una Struttura d\'Adamantite, un Nucleo Energetico di Korio e un\'Essenza Arcana Pura.', },
  },
  [11090] = {
    'Soggioga il soggiogatore',
    {'<Balthas ti mostra un dispositivo dall\'aspetto bizzarro.>|n|nQuesto è un Cannone dell\'Anima. Ha effetti devastanti una volta calibrato. E questo è calibrato con il mio sangue. Lo stesso sangue che scorre nelle vene di Reth\'hedron, mio fratello. Sì, la sua mancanza di lealtà nei miei confronti sarà la sua fine.|n|nPrendi il Cannone e vola alla Cresta del Crepuscolo a Nagrand occidentale. Trova Reth\'hedron e fai fuoco! Devi rimanere sulla cavalcatura ed entro la gittata perché abbia effetto. Non indietreggiare e non gli resterà alternativa se non la fuga!', },
    {'Il Signore Illidari Balthas al Campo Base delle Fauci di Drago nella Valle di Torvaluna ti ha incaricato di usare il Cannone dell\'Anima su Reth\'hedron il Soggiogatore a Nagrand.|n|nDevi anche restituire il Cannone dell\'Anima.', },
  },
  [11091] = {
    'Un ringraziamento speciale',
    {'Svolgendo gli incarichi che ti affidiamo, tu ci rendi onore. E ora c\'è qualcuno che desideriamo farti conoscere.|n|nJho\'nass è il nostro fidatissimo Quartiermastro. Egli ha dei prodotti in vendita solo per gli amici più fedeli di Ogri\'la.|n|nTu, $N, sei tra loro.|n|nQuando avrai un po\' di tempo, vai a parlare con lui. A quanto ho capito, ti ha preparato un piccolo pensiero per manifestarti il nostro apprezzamento.', },
    nil,
  },
  [11092] = {
    'Ti saluto, Comandante!',
    {'Capitano $N!|n|n<Il Coordinatore Varkule ti saluta.>|n|nIl Supremo Mor\'ghor vuole subito vederti nei suoi alloggi!', },
    {'Parla con il Supremo Mor\'ghor al Campo Base delle Fauci di Drago nella Valle di Torvaluna.', },
  },
  [11093] = {
    'Mante Fatue affamate',
    {'Le Mante Fatue, una volta addestrate correttamente, sono incredibilmente fedeli e obbedienti. Purtroppo la guerra contro Skettis le sta sfinendo.|n|nAbbiamo decine di sortite ogni giorno, e quelle poverette non si riposano praticamente mai. E con la scarsità di scorte di cibo, se non le uccidono quei dannati uomini uccello lo farà la fame.|n|nSe vuoi aiutarci, porta una delle nostre mante nei boschi a sud. Mangiano anche la carne di Inseguitore Distorcente, purché sia fresca.', },
    {'Usa la Gabbia per Manta Fatua nei boschi a sud dell\'Aerodromo di Ventotetro e uccidi degli Inseguitori Distorcenti Ventotetro vicino alla Manta Fatua Affamata. Torna dall\'Addestratore dei Guardacieli Deesak, quando hai completato questa missione.', },
  },
  [11094] = {
    'Uccidili tutti!',
    nil,
    nil,
  },
  [11095] = {
    'Il Comandante Hobb',
    {'Le Fauci di Drago osano attaccarci solo quando abbiamo la guardia abbassata. Perirebbero sicuramente se ci assalissero quando siamo preparati.|n|nVoglio che tu li lasci venire a noi, $N.|n|n<Thelis annuisce.>|n|nSì... una trappola. Prendi questa spararazzi che ti ha dato il loro Supremo e consegnala al Comandante Hobb. È di guardia proprio fuori da questo edificio.', },
    {'Dai la Spararazzi delle Fauci di Drago al Comandante Hobb al Santuario delle Stelle nella Valle di Torvaluna.', },
  },
  [11096] = {
    'Minaccia dall\'alto',
    {'Quindi vorresti unirti ai Guardacieli? Be\', so che sai volare... Ma sai combattere?|n|nI Guardacieli hanno giurato di proteggere Shattrath dai pericoli che incombono sopra di noi, vicini e lontani. Gli Ogre Gordunni che vivono sui Monti Granbarriera a nord sono una minaccia per noi.|n|nLe truppe di terra di Shattrath hanno avuto problemi nel raggiungerli. E qui entriamo in gioco noi. Vediamo cosa riesci a fare per aiutarci a contenerli.', },
    {'Uccidi 20 Ogre Gordunni sui Monti Granbarriera e torna da Yuula a Shattrath.', },
  },
  [11097] = {
    'La trappola più letale mai architettata',
    nil,
    nil,
  },
  [11098] = {
    'A Skettis!',
    {'I Monti Granbarriera sono solo uno dei fronti dove siamo stati inviati. Una minaccia meno immediata, ma molto più terribile, incombe da sotto i Monti Skethyl, dalla città arakkoa di Skettis.|n|nPochi mesi fa i nostri esploratori hanno riportato un notevole aumento dell\'attività degli Arakkoa in quella zona. In seguito ci sono stati diversi attacchi a Shattrath, e da allora abbiamo posizionato delle truppe fuori dalla loro città.|n|nPorta gli esplosivi al Capo Squadriglia Doryn all\'Aerodromo di Ventotetro, appena fuori Skettis. Digli che sei una nuova recluta.', },
    {'Porta il Pacco di Esplosivi al Capo Squadriglia Doryn all\'Aerodromo di Ventotetro fuori Skettis.', },
  },
  [11099] = {
    'Uccidili tutti!',
    nil,
    nil,
  },
  [11100] = {
    'Il Comandante Arcus',
    nil,
    {'Dai la Spararazzi delle Fauci di Drago al Comandante Arcus all\'Altare degli Sha\'tar nella Valle di Torvaluna.', },
  },
  [11101] = {
    'La trappola più letale mai architettata',
    {'Prendi queste medaglie degli Aldor. Mor\'ghor vorrà una prova della "vittoria" quando sarà tutto finito. Penserà che le hai prese dai cadaveri dei soldati Aldor caduti.|n|nNon resta altro che dare il segnale agli Incursori delle Fauci di Drago. Li schiacceremo appena sarai $Gpronto:pronta;. Attendo il tuo ordine.', },
    {'Aiuta il Comandante Arcus e gli Aldor a difendere l\'Altare degli Sha\'tar. Quando tutte le truppe delle Fauci di Drago saranno state sconfitte, torna dal Supremo Mor\'ghor con le Medaglie degli Aldor al Campo Base delle Fauci di Drago.', },
  },
  [11102] = {
    'Bombardamento',
    {'Sai volare... e allora? Anche i corvi volano! Hai mai distrutto qualcosa a terra mentre volavi? Vorresti farlo?|n|nFornace Ira e Fornace Terrore, a nord e a sud, sono due vere seccature, oltre che una minaccia alla pacifica Ogri\'la. Però, con tutti quei Vilcannoni che minacciano di abbattere i Guardacieli, non abbiamo il tempo per occuparcene.|n|nVuoi dimostrare il tuo valore? Prendi queste bombe e fai saltare in aria le loro pile di munizioni. E stai $Gattento:attenta; a non farti abbattere anche tu!', },
    nil,
  },
  [11103] = {
    'Non più Saggio',
    nil,
    nil,
  },
  [11105] = {
    'Non più Campione',
    nil,
    nil,
  },
  [11106] = {
    'Non più Difensore',
    nil,
    nil,
  },
  [11107] = {
    'Inchinatevi di fronte al Gran Signore',
    nil,
    nil,
  },
  [11108] = {
    'Sire Illidan Grantempesta',
    {'Vieni, $GGran Signore:Gran Signora; $N. Illidan in persona ci aspetta!', },
    {'Incontra Illidan Grantempesta. Cerca Barthamus nella Città Bassa di Shattrath qualora dovessi sopravvivere.', },
  },
  [11109] = {
    'Jorus il Draco Alafatua di Cobalto',
    nil,
    nil,
  },
  [11110] = {
    'Malfas il Draco Alafatua Viola',
    nil,
    nil,
  },
  [11111] = {
    'Onyxien il Draco Alafatua d\'Onice',
    nil,
    nil,
  },
  [11112] = {
    'Suraku il Draco Alafatua di Zaffiro',
    nil,
    nil,
  },
  [11113] = {
    'Voranaku il Draco Alafatua Violaceo',
    nil,
    nil,
  },
  [11114] = {
    'Zoya il Draco Alafatua Veridiano',
    nil,
    nil,
  },
  [11116] = {
    nil,
    nil,
    {'A\'dal a Shattrath ti ha chiesto di uccidere Magtheridon.', },
  },
  [11118] = {
    'La parata degli Elekk Rosa',
    nil,
    nil,
  },
  [11119] = {
    'Assalto all\'Approdo di Bash\'ir!',
    {'Ehi, $Gbello:bella;! Hai voglia di divertirti?|n|nOgni paio d\'ore, i miei Tecnofatui lanciano un assalto all\'Approdo di Bash\'ir, nell\'estremità nordorientale delle Montagne Spinaguzza. Loro affermano di andare lì per studiare la Forgia di Cristallo Bash\'ir, ma il loro è un assalto in piena regola, inutile girarci intorno. La Forgia di Cristallo ci serve per rifornirci di materiale e ne avanza sempre un po\' con cui tirar su qualche soldo.|n|nVai alla pista d\'atterraggio e parla con l\'Apprendista Tecnofatuo. Ti dirà per quando è programmata la prossima missione.', },
    nil,
  },
  [11120] = {
    'La parata degli Elekk Rosa',
    nil,
    nil,
  },
  [11122] = {
    'Andata e ritorno',
    {'Vuoi dare una mano alla Festa della Birra? Ho un incarico fatto apposta per te. Prendi uno dei miei montoni e cavalcalo fino a Kharanos.|n|nFlynn Fiammabirra ti aspetta su una collina insieme a un certo numero di barili. Ogni volta che ti avvicinerai, te ne lancerà uno. A quel punto torna qui di corsa e lancialo a Pol Ambraquieta. Puoi trasportarne solo uno alla volta.|n|n$GSei pronto:Sei pronta;?', },
    nil,
  },
  [11123] = {
    nil,
    {'Il povero James non si è più ripreso dopo la distruzione della Locanda Ombracalma e la morte della sua famiglia. I ragazzi e io stiamo facendo il possibile per trovare i responsabili.|n|nHo inviato alle rovine il nostro migliore investigatore, l\'Ispettore Tarem, ma è un lavoro troppo grande per un uomo solo. Apprezzeremmo molto se andassi là a dare una mano, ci serve tutto l\'aiuto possibile.|n|nLa strada principale ti condurrà alla Locanda, ma fa\' attenzione. I miei soldati non potranno proteggerti lungo il cammino.', },
    {'Parla con l\'Ispettore Tarem alla Locanda Ombracalma.', },
  },
  [11124] = {
    nil,
    {'Segui la strada a sud del villaggio e gira a ovest verso le Savane per raggiungere le rovine della Locanda Ombracalma.|n|nTheramore ha inviato un investigatore per far luce su quanto è accaduto. Avevo infiltrato una spia nella locanda perché non mi fido degli Umani.|n|nQualunque cosa dovessi scoprire, non farne parola con l\'investigatore. Tratteremo questa faccenda per conto nostro.', },
    {'Indaga sulla Locanda Ombracalma al confine con le Savane nella regione di Acquemorte.', },
  },
  [11126] = {
    nil,
    {'Lieta di vederti, $C. Sono venuta a Theramore per dare una mano a eliminare il problema dei disertori. Alcuni di essi, oltre ad abbandonare la propria postazione, sono addirittura rientrati in città.|n|nQuesti disertori stanno diffondendo la loro falsa propaganda per convincere altri a unirsi alle loro file.|n|nSi trovano praticamente a ogni posto di guardia in tutta la città e al porto. Trovali, smascherali e screditali. Al momento non possiamo andare oltre, o rischieremmo di farne dei martiri.', },
    nil,
  },
  [11128] = {
    nil,
    {'Gli agenti dei disertori non si accontentavano di fare il lavaggio del cervello alle guardie. Abbiamo trovato diversi volantini che erano riusciti a caricare su una nave ormeggiata al porto.|n|nLa nave si trova ancora a Theramore, nel molo più distante. Se riuscissi a introdurti a bordo e a rubare il resto dei documenti di propaganda, toglieremmo lo strumento più potente a disposizione dei loro agenti. Fa\' attenzione! La nave è in mano a marinai esperti ed è probabile che il carico si trovi negli alloggi del capitano.', },
    nil,
  },
  [11129] = {
    'Kyle è sparito!',
    {'Aiuto, $N! Il mio prezioso cucciolo, Kyle, è scappato! Sarà di sicuro nei pressi del Villaggio di Zoccolo Sanguinario, smarrito e affamato.|n|nPotresti cercarlo e dargli da mangiare? Quando sarà sazio, si calmerà e tornerà a casa.|n|nDovrai trovare del cibo da dargli. Ciò che preferisce è la tenera carne di zampalunga. Vai a est e dovresti trovare molti zampalunga. Cacciane uno e porta la sua carne succulenta a Kyle. Quando lo vedrai, metti a terra la carne e verrà lui da te.', },
    {'Ahab Grano Duro al Villaggio di Zoccolo Sanguinario ti ha chiesto di dare da mangiare al suo prezioso cucciolo, Kyle il Furioso.|n|nDagli della Tenera Carne di Zampalunga e torna da Ahab Grano Duro.', },
  },
  [11131] = {
    'Spegni i roghi!',
    {'Devi aiutarci! Il Cavaliere Senza Testa sta attaccando il villaggio. I roghi stanno divampando ovunque! I bambini non sono al sicuro!|n|n$N, ti prego, aiuta i pompieri. Prendi un secchio e getta l\'acqua sui roghi, oppure passalo a qualcuno più vicino al fuoco. Spegnili tutti e forse riusciremo a salvarci.', },
    {'La Matrona degli Orfani in Costume ti ha chiesto di aiutare a domare i roghi del villaggio. Quando li avrai spenti tutti, torna a parlarle.', },
  },
  [11133] = {
    nil,
    {'Ho alterato i volantini che hai rubato ai mercenari amici dei disertori al porto. Ora chiunque li legga si farà un\'idea completamente diversa sui disertori e sui loro obiettivi.|n|nSe ne distribuiamo abbastanza alle guardie, metteremo i disertori in un tale imbarazzo che non avranno più il coraggio di farsi vedere all\'interno delle nostre mura.|n|n<Calia ti consegna un mucchio di Volantini Alterati.>|n|nPerché non inizi a distribuirli, mentre io penso alla prossima mossa?', },
    nil,
  },
  [11134] = {
    nil,
    {'Ora che abbiamo eliminato i disertori da Theramore, è arrivato il momento di completare l\'opera. Secondo quanto mi hanno riferito i miei contatti locali, la base dei disertori si trova su una nave ormeggiata nei pressi di un isolotto a sud-est del porto.|n|nSe arrestiamo il loro capo, Gavis Scudogrigio, gli altri dovrebbero perdere il desiderio di combattere. Sali a bordo della nave, trovalo e convincilo ad arrendersi. Non mi sorprenderei se cercasse di opporre resistenza, ma sono sicura che alla fine cederà.', },
    nil,
  },
  [11135] = {
    'Cavaliere Senza Testa',
    nil,
    {'Trova il Santuario della Zucca del Cavaliere Senza Testa.', },
  },
  [11136] = {
    nil,
    {'Di recente, le nostre pattuglie di esploratori hanno denunciato la presenza di uomini con indosso le bandane rosse dei Defias che vagano per la Costa di Acquatruce, a nord delle mura di Theramore.|n|nIl relitto nella zona lascia intendere che siano i superstiti di un naufragio, ma le informazioni in nostro possesso sono scarse. Il Capitano Wymor al Presidio di Guardia, una torre a nord della città, sta cercando aiuto per indagare più a fondo.', },
    {'Incontra il Capitano Wymor al Presidio di Guardia.', },
  },
  [11138] = {
    nil,
    {'A giudicare dagli ordini che hai recuperato, sembra che la priorità dei Defias sia recuperare questo carico di cui parlano.|n|nL\'IR:7 aveva un sommozzatore di recupero di nome Renn McGill che per un po\' ha lavorato fuori da Theramore. Quando ha saputo del relitto, si è diretto a nord per esaminare i fondali vicino alle isole ora occupate dai Defias.|n|nAvremo bisogno del suo aiuto se vogliamo raggiungere questo carico prima dei Defias. Cercalo nelle acque a nord-est dell\'isolotto, a nord dell\'isola che hai visitato in precedenza.', },
    {'Consegna gli Ordini dei Defias a Renn McGill nelle acque al largo della Costa di Acquatruce.', },
  },
  [11139] = {
    nil,
    {'Ci sono parecchi relitti sui fondali marini da qui ad Alcaz. I Defias hanno già inviato dei sommozzatori per dare un\'occhiata. Con la loro attrezzatura, potremo equipaggiarti per unirti alla caccia. Prima però dovrai inventarti qualcosa per prenderla in "prestito".|n|nPerlustra quest\'isola in cerca di una cassa contenente attrezzatura da immersione e qualcosa per ripararla. Quando hai tutto, portamelo e ti preparerò la tua attrezzatura in un attimo!', },
    {'Porta il Kit di Riparazione e l\'Attrezzatura da Immersione Rovinata a Renn McGill ad Acquemorte.', },
  },
  [11140] = {
    nil,
    {'Sono riuscito a riparare quest\'attrezzatura quanto basta per permetterti di restare sott\'acqua per un po\', ma cerca di non esagerare.|n|nLa nave è finita completamente in pezzi, spargendo relitti galleggianti per tutto il tratto di mare che va dalla costa orientale di quest\'isola fino all\'Isola di Alcaz. Usa questo kit di recupero per esaminare i pezzi di relitto in cerca del carico, ma non avvicinarti troppo all\'Isola di Alcaz. Quelle idra sono pericolose.', },
    nil,
  },
  [11141] = {
    nil,
    {'Devi avvertire immediatamente Dama Jaina di ciò che abbiamo scoperto! Se i Defias stavano trasportando un prigioniero, non conosciamo la sua identità, né se sia ancora vivo!|n|nUna cosa è certa, $N... i Defias non passerebbero tutti questi guai per niente. Il loro prigioniero deve essere qualcuno di importante. Dama Jaina saprà interpretare questi ritrovamenti meglio di chiunque altro. La troverai in cima alla Torre del Mago al centro di Theramore.', },
    {'Parla con Dama Jaina Marefiero a Theramore.', },
  },
  [11142] = {
    nil,
    {'Sembra che i sospetti di Renn sull\'Isola di Alcaz fossero giusti. Dobbiamo perlustrare quell\'isola, ma ci vorrebbe un intero esercito per farci largo fin lì.|n|nLe difese di Theramore non possono permettersi di concedere tutti questi uomini, per questo ho chiesto a Cassia Alacremisi, l\'Apprendista del Maestro dei Grifoni di Theramore, di farci usare una delle sue bestie per perlustrare Alcaz dall\'alto.|n|nL\'Isola di Alcaz custodisce la chiave del mistero sul coinvolgimento dei Defias in questo rapimento.', },
    nil,
  },
  [11143] = {
    nil,
    {'Ho parlato con l\'Ispettore Tarem riguardo alle prove che hai raccolto nelle rovine della Locanda Ombracalma. È convinto che le impronte di zoccoli e lo scudo appartengano alla tribù tauren dei Totem Truce.|n|nNon può essere una coincidenza, considerati anche i rapporti che parlano di un aumento delle attività dei Totem Truce nella palude. Voglio che tu vada a parlare con il Capitano Darill, che è un esperto sui Totem Truce. Segui la strada a nord fuori dall\'isola verso la Torre Settentrionale. È il secondo avamposto lungo la strada.', },
    {'Fai rapporto al Capitano Darill nella Torre Settentrionale.', },
  },
  [11144] = {
    nil,
    {'I Totem Truce saranno anche i più guerrafondai tra tutte le tribù dei Tauren, ma non sono affatto sprovveduti. Se sono stati loro a dare fuoco alla Locanda Ombracalma, avranno ricevuto l\'ordine da uno degli anziani della tribù.|n|nA nord-ovest c\'è un grosso insediamento dei Totem Truce chiamato Villaggio di Zoccolo Nero. Lo usano come base per attaccare la torre. Scommetto che lì troverai gli ordini che stai cercando, addosso agli anziani del villaggio.', },
    nil,
  },
  [11145] = {
    nil,
    {'Stiamo facendo del nostro meglio per tenere a bada gli Incursori Totem Truce, ma essi continuano a sferrare attacchi contro la Torre. Come se non bastasse, sono riusciti a scoprire e a catturare le pattuglie inviate dal Capitano per raccogliere informazioni e sorvegliare la strada.|n|nCredo li abbiano portati nel Villaggio di Zoccolo Nero a nord-ovest. Conoscendo i Totem Truce, probabilmente i difensori del villaggio hanno le chiavi delle gabbie dei prigionieri. Rivoglio indietro i miei uomini vivi, $C, costi quel che costi.', },
    nil,
  },
  [11147] = {
    nil,
    {'Ora che abbiamo catturato i raptor, la prossima mossa consiste nell\'"incoraggiarli" ad attaccare i Totem Truce del Villaggio di Zoccolo Nero a nord-ovest.|n|nMi sono rimasti degli avanzi di... be\', non ha importanza di cosa. Saranno la tua esca. Sistemali a terra nel Villaggio di Zoccolo Nero, vicino al mulino al centro dell\'insediamento. Se l\'addestramento ha funzionato, i raptor dovrebbero occuparsi del resto.', },
    nil,
  },
  [11148] = {
    nil,
    {'Se l\'equipaggiamento che hai trovato nelle rovine della Locanda apparteneva a un gruppo di Totem Truce, è probabile che ce ne sia dell\'altro nel loro accampamento a nord-ovest.|n|nNon siamo riusciti a ottenere molte informazioni sul Villaggio di Zoccolo Nero, ma a giudicare dalle dimensioni dei gruppi d\'assalto, devono esserci parecchi Tauren lì.|n|nFai tutto il necessario per rubare parte del loro equipaggiamento, in modo che possiamo confrontarlo con quello che hai trovato nella Locanda.', },
    {'Il Capitano Darill alla Torre Settentrionale ti ha chiesto di portargli 7 Armamenti di Zoccolo Nero.', },
  },
  [11149] = {
    nil,
    {'Non ho uomini da assegnare alla ricerca di un secondo presidio dei Totem Truce, ma credo di conoscere qualcuno che può aiutarti.|n|nNelle profondità di Acque Stagnanti, a sud, c\'è una piccola cascina di proprietà di Tabetha. A prima vista potrebbe sembrare una vecchia eremita, ma in realtà è una Maga e una Scrutatrice rinomata. Segui la strada a sud fino alla sua cascina e chiedile di aiutarti a trovare i responsabili del massacro alla Locanda Ombracalma.', },
    {'Parla con Tabetha alla sua cascina.', },
  },
  [11150] = {
    nil,
    {'Non serve essere una Scrutatrice per vedere i guai che stanno creando i miei nuovi "vicini". Se è lo stesso gruppo che ha bruciato la Locanda Ombracalma, come sostieni, non c\'è ragione per tollerare oltre la loro presenza.|n|nPrendi questa torcia e brucia il loro accampamento! L\'Accampamento Corno Furente si trova a nord della mia tenuta, vicino alla strada. Lo riconoscerai dai totem che i Totem Truce hanno sistemato ovunque.', },
    nil,
  },
  [11151] = {
    nil,
    {'Anche se questi Totem Truce erano poco più che un fastidio per me, il Capitano Vimes sarà lieto di sapere ciò che hai fatto. Avvisalo che hai eliminato i responsabili dell\'incendio della Locanda Ombracalma.|n|nÈ troppo tardi per salvare la famiglia di Jim Hyal, ma forse ora i Totem Truce ci penseranno due volte prima di attaccare qualcuno legato a Theramore.', },
    {'Parla con il Capitano Garran Vimes nella Cittadella di Theramore a Theramore.', },
  },
  [11152] = {
    nil,
    nil,
    {'Il Capitano Garran Vimes della Cittadella di Theramore ti ha chiesto di depositare la Corona sulla Tomba della Famiglia Hyal.', },
  },
  [11153] = {
    'Sfonda la barricata',
    {'Le nostre navi sono tutte affondate! Devi aiutarci a sfondare la barricata dei pirati agli Stretti Infidi!|n|nPrendi questi esplosivi e fatti dare un passaggio sullo Zeppelin "preso in prestito" da Harrowmeiser. Ti porterà sopra quei maledetti pirati, così potrai dar loro una bella lezione!|n|nSe non riuscirai a eliminare le loro forze, temo che non oltrepasseremo mai la barricata.', },
    {'Prendi gli Esplosivi di Petrov e sganciali sui pirati per uccidere 25 Pirati della Barricata e distruggere 10 Cannoni della Barricata. Poi, torna dal Bombarolo Petrov al Forte di Guardia dell\'Ovest.', },
  },
  [11154] = {
    'Una pioggia di guano!',
    {'Tu! Sì, tu! Ho bisogno del tuo aiuto!|n|nPetrov mi ha inviato quaggiù a prendere del guano di pipistrello per gli esplosivi che sta creando al Forte. Praticamente mi ha mandato a morire!|n|nI Pipistrelli Morsoscuro si radunano nel Bosco di Legnotorvo a nord, ma io non metto piede fuori da questa piattaforma se non per tornare a casa!|n|nPotresti... pensarci tu al posto mio? Eh? Per favore?|n|nEcco, prendi questi petardi. Se li farai esplodere sotto i pipistrelli, per la paura produrranno un sacco di guano!', },
    {'Recupera 10 Campioni di Guano di Morsoscuro e consegnali all\'Ingegnere Feknut nella Chiusa d\'Acciaio.', },
  },
  [11155] = {
    'Vuoi dell\'altra zuppa di Zannapiatta?',
    {'Con le strane sparizioni del nostro bestiame, è meglio se iniziamo a fare rifornimenti, altrimenti tutte le bestiaccie qui intorno saranno l\'ultima delle nostre preoccupazioni!|n|nIl mio incarico è di sfamare tutti: avrei quindi bisogno che tu ti diriga a est e mi procuri un po\' di carne. Nello specifico, vorrei cucinare un po\' di carne tenera di Zannapiatta.|n|nMa fa\' attenzione: alcuni sono aggressivi!', },
    {'La Chef Bricconero ti ha chiesto di portarle 6 Pezzi di Carne di Zannapiatta al Forte di Guardia dell\'Ovest.', },
  },
  [11156] = {
    nil,
    {'I Totem Truce dell\'Accampamento Corno Furente a nord si stanno facendo sempre più intraprendenti. Spesso di notte cantano le loro gesta in battaglia contro coloro che hanno provato a stabilirsi qui.|n|nSono determinati a cacciarci dalla Cascina di Tabetha, dove ella addestra apprendisti da generazioni. Abbiamo cercato di fare del nostro meglio per difendere la cascina, ma l\'Apprendista Garion è rimasto ferito durante l\'ultimo attacco.|n|nVai all\'Accampamento Corno Furente e uccidi tutti i Totem Truce che trovi! Dobbiamo fermare gli attacchi.', },
    nil,
  },
  [11157] = {
    'Le grinfie del male',
    {'$N, mi posso fidare solo di te per questa missione. Ho bisogno che tu distrugga le Uova di Proto-Draco e i Cuccioli di Proto-Draco nella foresta che brucia a sud-est!|n|nDa quando siamo arrivati, la Selvardente è in fiamme: dev\'essere all\'opera qualche tipo di magia perversa. Ultimamente, la situazione sembra addirittura peggiorata. I miei uomini mi hanno detto che, se non faremo qualcosa in fretta, entro poche settimane saremo circondati dalle fiamme da ogni lato!|n|nVa\' laggiù ed elimina questa minaccia, distruggendo le Uova e i Cuccioli di Proto-Draco.', },
    {'Distruggi 15 Uova di Proto-Draco e 15 Cuccioli di Proto-Draco, poi torna dal Capitano Adams al Forte di Guardia dell\'Ovest.', },
  },
  [11158] = {
    nil,
    {'Sei $Gspaventato:spaventata; dall\'aspetto di Brogg? Non preoccuparti. I Goblin di Melmarmitta sono amici di Brogg e anche tu puoi diventarlo.|n|nBrogg ha lasciato Felcimura dopo che il nuovo Supremo ha deciso di non cercare vendetta contro lo Stormo dei Draghi Neri per aver distrutto la vecchia casa di Brogg e ucciso parecchi suoi amici. Brogg è venuto qui per dare pace agli spiriti degli amici e vendicarli, ma ha bisogno d\'aiuto. A Brogg servono penne magiche per il rituale, come quelle dei raptor nel Covo dei Codarossa a ovest.', },
    nil,
  },
  [11159] = {
    nil,
    {'Brogg ha terminato il totem che metterà a riposo gli spiriti dei suoi amici. Quando i dragoidi sono arrivati, hanno ucciso tutti i Mazzapietra rimasti. Brogg è fuggito insieme al Supremo Mok\'morokk, sperando di poter contrattaccare insieme ad altri superstiti Mazzapietra.|n|nIl contrattacco non c\'è mai stato e gli spiriti dei morti dei Mazzapietra tormentano ancora Brogg e gli altri. Porta questo totem a nord nelle Rovine dei Mazzapietra e usalo vicino agli scheletri degli Ogre per attirare i loro spiriti. Sconfiggili e dai loro l\'eterno riposo.', },
    nil,
  },
  [11160] = {
    nil,
    {'Quando i draghi hanno distrutto la vecchia casa di Brogg, gli Ogre Mazzapietra sono fuggiti abbandonando ogni cosa, incluso lo Stendardo del clan.|n|nLo Stendardo era conservato nelle profondità del Tumulo degli Ogre Mazzapietra, che ora si chiama Covo delle Fiamme. Brogg deve riavere lo Stendardo del clan per vendicarsi dei draghi che hanno ucciso i suoi amici.|n|nIl vecchio tumulo del clan di Brogg, il Covo delle Fiamme, si trova a nord-ovest di Melmarmitta ed è pieno di dragoidi. Lo Stendardo è lì dentro. Fa\' attenzione, $N.', },
    nil,
  },
  [11161] = {
    nil,
    {'Per usare il totem del rituale di Brogg occorrono le essenze delle creature che hanno ucciso i suoi amici. L\'odio e la rabbia dei nemici di Brogg alimenteranno la sua vendetta.|n|nTrova i Codanera Crestardente, gli Esploratori Crestardente o i Malascaglia Crestardente e usa il totem di Brogg sui loro cadaveri. I dragoidi rilasciano la loro essenza solo una volta morti.|n|nLe creature che cerchi si trovano nel Covo delle Fiamme a nord-ovest e nelle Rovine dei Mazzapietra a nord.', },
    {'Porta 10 Essenze dei Dragoidi Neri a Brogg nel villaggio di Melmarmitta.', },
  },
  [11162] = {
    nil,
    {'Brogg pregusta la vendetta contro lo Stormo Nero della palude. $N, spero di poter contare ancora sul tuo aiuto.|n|nPrendi lo Stendardo del clan di Brogg e dirigiti a est finché non vedrai una caverna che somiglia alle fauci di un drago. Pianta lo Stendardo dei Mazzapietra all\'ingresso della caverna e lancia la sfida a Onyxia da parte di Brogg.|n|nBrogg e i Mazzapietra riavranno indietro le loro terre!', },
    nil,
  },
  [11167] = {
    'La nuova Piaga',
    {'Poco dopo che Arthas ci ha condannati a questa miserabile esistenza, noi dell\'Ordine Reale degli Speziali abbiamo tentato di creare una nostra Piaga che divorasse le carni di chiunque: vivi, morti e non morti.|n|nCi siamo riusciti e ora siamo qui per consegnarla personalmente al Flagello.|n|nL\'Alleanza ha intercettato la nave che trasportava l\'ultimo ceppo modificato nei nostri laboratori di Sepulcra. Raggiungi il relitto a sud-est e recupera quanti più contenitori riesci.', },
    {'Lo Speziale Lysander all\'Attracco della Vendetta ti ha chiesto di recuperare 10 Contenitori della Piaga Intatti dal relitto a sud-est.', },
  },
  [11168] = {
    'Un ultimo ritocco alla ricetta',
    {'Ho la sensazione che il lungo viaggio via mare abbia diminuito l\'efficacia della nostra Piaga. Ci serve una potente tossina per potenziare l\'effetto.|n|nI granchi vicino a questa spiaggia sono parenti lontani dei piccoli Strisciamaree dal guscio bruno. I loro piccoli parenti producono una tossina abbastanza potente da mettere fuori gioco un Ogre.|n|nE sappiamo tutti che più qualcosa è grande e meglio è! Le gigantesche ghiandole della varietà locale dovrebbero essere più potenti. Portamene un po\'!', },
    {'Porta 3 Ghiandole Velenifere Giganti degli Strisciamaree Giganti allo Speziale Lysander nell\'Attracco della Vendetta del Fiordo Echeggiante.', },
  },
  [11169] = {
    nil,
    {'Sono rimasto ferito durante l\'ultimo attacco dei Totem Truce, ma non prima di aver rubato uno strano totem che i nostri nemici stavano usando contro di noi.|n|nIn battaglia sembrava emettere dardi di energia grezza, ma nonostante tutti i miei esperimenti non sono riuscito a capire come funzioni. Ti presterò il totem se accetti di aiutarmi a testarlo.|n|nLe zone acquatiche intorno alla cascina sono abitate da Crocolischi Bragosecco Chiazzati e da Fauciaguzze Bragosecco. Prova a combattere i crocolischi vicino al totem.', },
    nil,
  },
  [11170] = {
    'Prova del Mare',
    {'Ci hanno appena riferito che i rinforzi stanno accorrendo in aiuto dell\'Alleanza. Non avrebbero potuto scegliere un momento migliore!|n|nAbbiamo un disperato bisogno di cavie e i Riservisti della Flotta del Nord sono perfetti!|n|nPrendi queste Fiale della Piaga e va\' a parlare con Camille, l\'Addestratrice di Pipistrelli. Dille che hai bisogno di un Pipistrello Cavalcabile per un incarico speciale che ti abbiamo assegnato noi.|n|nQuando sarai sul mare, lascia cadere le fiale sulla flotta dei rinforzi. Non vedo l\'ora di scoprire l\'effetto!', },
    {'Parla con l\'Addestratrice di Pipistrelli Camille e usa un Pipistrello Cavalcabile per intercettare i rinforzi dell\'Alleanza. Quando sarai sopra la loro flotta, usa le Fiale della Piaga per infettare 16 Riservisti della Flotta del Nord.', },
  },
  [11171] = {
    'Il perfido? Ah!',
    nil,
    {'Budd Nedreck alle Colline della Mannaia ti ha chiesto di uccidere Malacrass il Perfido a Zul\'Aman.', },
  },
  [11172] = {
    nil,
    nil,
    {'Parla con Moxie Grigliafredda al Relitto di Beezil.', },
  },
  [11173] = {
    nil,
    {'Se c\'è una cosa che l\'Apprendista Morlann sa fare bene è lamentarsi dei reagenti.|n|nDi solito mi limito a ignorarlo, ma non funziona mai. Stavolta voglio adottare una tattica diversa.|n|nSe riuscissi a sostituire i reagenti mancanti senza che se ne accorga, forse mi lascerebbe in pace. Il reagente che usiamo più spesso è il Veleno della Palude, che si estrae dai Ragni Morsonero e dai Trinciatori Nocivi a nord della cascina. Portami il veleno e lo sostituirò senza che Morlann se ne accorga.', },
    nil,
  },
  [11174] = {
    nil,
    {'Da\' un\'occhiata a quest\'area! È invasa dalle Melme. Se non trovo un modo per tenerle a bada finiranno per corrodere il relitto e il carico dello Zeppelin!|n|nNon posso tornare indietro a mani vuote, $C! Aiutami a sciogliere queste Melme prima che digeriscano tutto quanto!|n|nQuesto dispositivo, una volta attivato, concentrerà energia sulle Melme, facendole esplodere. Il nucleo energetico frammentato dello Zeppelin dovrebbe alimentarlo. Quello vicino al luogo dello schianto principale funziona sempre, gli altri solo a volte.', },
    {'Moxie Grigliafredda ti ha chiesto di sciogliere 10 Melme e di tornare da lei al Relitto di Beezil.', },
  },
  [11175] = {
    'Mia figlia',
    {'Dimmi, è vero? Gli esploratori partiti per la Gola dei Sussurri sono impazziti?|n|nMia figlia è una sovrintendente della Lega degli Esploratori diretta a nord, verso una certa Chiusa d\'Acciaio. Visti gli orribili eventi che ci sono piombati addosso, inizio a temere per la sua incolumità.|n|nTi prego, $C! Io sono troppo vecchio per affrontare un viaggio del genere, andresti a controllare che stia bene? Il suo nome è Irena.', },
    {'Il Vecchio Pietramanto ti ha chiesto di trovare sua figlia, la Sovrintendente Irena Pietramanto, alla Chiusa d\'Acciaio.', },
  },
  [11176] = {
    'Sovrintendere alle operazioni',
    {'Il nostro lavoro è appena agli inizi... ma abbiamo portato qui le Macchine Volanti dal Forte di Guardia dell\'Ovest, dunque dovrebbe "decollare".|n|nIl problema è che non abbiamo abbastanza piloti qualificati. La situazione nel Bosco di Legnotorvo a nord sta peggiorando, quindi vorrei sbrigarmi a finire qui per tornare presto a casa.|n|nSe puoi aiutarci, va\' a parlare con uno dei miei Capi Archeologi. Li troverai al lato nord e al lato sud del sito, vicino alle Macchine Volanti.', },
    {'La Sovrintendente Irena Pietramanto ti ha chiesto di parlare con un Capo Archeologo della Chiusa d\'Acciaio alla Chiusa d\'Acciaio.', },
  },
  [11177] = {
    nil,
    {'C\'è un tizio che gli abitanti locali chiamano Jarl "Occhio Marcio" e che vive da solo nella palude. Qualche tempo fa ha "preso possesso" della Dimora Fuocofioco dopo che i suoi precedenti proprietari sono scomparsi in circostanze misteriose.|n|nOgni tanto mando qualcuno a controllarlo. Mi ricorda mio nonno, sai? Alcuni dicono che non ci stia troppo con la testa.|n|nSe sei $Gdiretto:diretta; a nord-ovest sulla strada che conduce fuori da Theramore, troverai la Dimora Fuocofioco nei pressi del Colle della Strega, prima che la strada giri verso ovest.', },
    {'Parla con Jarl "Occhio Marcio" alla Dimora Fuocofioco.', },
  },
  [11180] = {
    nil,
    {'Ho viaggiato fin qui per far visita a Jarl nella sua nuova dimora e da allora è stato tutto un susseguirsi di orrori! C\'è qualcosa che non va e non credo di essere l\'unico ad averlo notato...|n|nHai visto i fantasmi e i cadaveri che vagano per Colle della Strega? Ho la sensazione che loro sappiano cosa sta succedendo qui. Cerca le Salme Rianimate e gli Spiriti Rianimati nell\'area circostante e mettili a riposo una buona volta, quindi cerca di scoprire qualcosa da loro prima che questo male consumi Jarl!', },
    nil,
  },
  [11181] = {
    nil,
    {'Nei miei anni come erbalista ho notato spesso che la natura fornisce delle cure in grado di risolvere perfino i problemi più gravi. Ho letto che i maghi rinnegati e i taumaturghi usano il fumo prodotto da un\'erba chiamata Sfatastrega per attirare il male fuori dal suo nascondiglio.|n|nSe è vero, dovresti trovare della Sfatastrega vicino alle acque basse di Colle della Strega. La riconoscerai dalle sue foglie larghe e dal picciolo centrale rossastro. Portami l\'erba che riesci a trovare, $N. Potrebbe essere la nostra unica speranza.', },
    nil,
  },
  [11182] = {
    'Le cause primigenie',
    {'In natura, ogni cosa tende all\'equilibrio. Questo viene turbato solo dalle interferenze di coloro che non sono in armonia.|n|nUccidere drachi e draghetti è solo una perdita di tempo: i veri colpevoli dell\'espansione della foresta magica infuocata sono i Vrykul appena risvegliati... e il loro padrone, Skeld Dracogenito.|n|nSe vuoi macchiarti le mani di sangue, inizia con il loro. Troverai il loro covo nella parte meridionale della Selvardente.', },
    {'Uccidi 5 Addestratori Scorticadraghi e Skeld Dracogenito. Poi, torna da un Antico di Selvardente a Selvardente.', },
  },
  [11183] = {
    nil,
    {'La torcia è pronta. Sistemala in fondo al molo e preparati ad affrontare qualsiasi creatura si farà avanti.|n|nNon ho idea di cosa possa rivelare il fumo della torcia... sempre che funzioni. Ho i miei dubbi su questa magia popolare, ma non c\'è tempo per trovare un\'altra soluzione. Ti auguro buona fortuna, per il tuo bene e per quello dello Jarl.', },
    nil,
  },
  [11184] = {
    nil,
    {'I viandanti e il personale degli Spargifumo che lavora sul campo sono invitati a stare lontani dal Covo dei Codarossa a ovest del villaggio.|n|nLa zona è piena di raptor guidati dal feroce e astuto Artigliorosso il Vorace, che ha già ucciso almeno due ingegneri degli Spargifumo.|n|nDrazzit Svalvolato ha disposto una generosa ricompensa per chiunque riesca a liberare Melmarmitta da questa minaccia.', },
    {'Uccidi Artigliorosso il Vorace e torna da Drazzit Svalvolato a Melmarmitta.', },
  },
  [11187] = {
    'Il Tenente Mago Malister',
    {'TUTTO CIÒ È OLTRAGGIOSO! I Proto-Drachi attaccano il Forte!|n|nQuelle bestie sarebbero dovute fuggire via terrorizzate, quando hai eliminato le loro uova e i draghetti.|n|nLi hai eliminati, vero?|n|n$N, è necessaria un\'azione diretta. Parla con il mio consigliere, il Tenente Mago Malister. Ti fornirà i mezzi necessari per sbarazzarti di quelle creature infernali.', },
    {'Il Capitano Adams ti ha chiesto di parlare con il suo consigliere, il Tenente Mago Malister, al Forte di Guardia dell\'Ovest.', },
  },
  [11188] = {
    'Due torti...',
    {'Abbiamo infastidito i Proto-Drachi di Selvardente, quindi probabilmente continueranno ad attaccare il Forte e questo non possiamo permetterlo.|n|nOdio rimediare a un torto con un altro torto, ma in questo caso non abbiamo altra scelta che distruggere le creature. Si tratta di un\'azione deplorevole, ma dobbiamo portarla avanti fino alla fine.|n|nPrendi la mia bacchetta. Nonostante abbia fatto degli esperimenti per aumentarne la portata, non è molto potente. Comunque, attirerà l\'attenzione dei Proto-Drachi.', },
    {'Il Tenente Mago Malister al Forte di Guardia dell\'Ovest ti ha chiesto di uccidere 3 Proto-Drachi.', },
  },
  [11190] = {
    'La misura non è unica',
    nil,
    {'Il Cannoniere Ely ti ha chiesto di recuperare 10 Palle di Cannone della Guardia e di portargliele al Forte di Guardia dell\'Ovest.', },
  },
  [11191] = {
    nil,
    {'Il vecchio faro a est è fuori uso ormai da diverso tempo, ma Babs Frizzacoppia si è messa in testa di farlo funzionare di nuovo.|n|nNon so come abbia intenzione di riuscirci da sola, ma sostiene che migliorerà lo spostamento delle navi e delle merci nel porto, dunque non ho nulla da obiettare. Lavorare al porto non è poi così male, soprattutto se l\'alternativa è trovarsi in prima linea a combattere...', },
    {'Parla con Babs Frizzacoppia presso il faro sull\'isola a est di Theramore.', },
  },
  [11192] = {
    nil,
    {'Secondo il vecchio registro del faro, la lampada era alimentata con l\'olio ricavato dai Plesiosauri che vivono lungo la costa.|n|n<Babs arriccia il naso al pensiero di una tecnologia così datata.>|n|nImmagino sia una soluzione pratica, anche se poco elegante. Il registro dice che l\'olio preso dai Plesiosauri del Buio Giovani è il migliore e che quelle creature vivono sotto il Porto di Theramore.|n|nSei <disposto/disposta> a recuperare il carburante per il faro?', },
    nil,
  },
  [11193] = {
    nil,
    {'È incredibile quello che si può trovare in quel vecchio faro. Dopo che ho acceso la lampada, ho notato questo libro in uno dei bauli.|n|n<Babs prende il libro e ne legge il titolo con tono drammatico.>|n|n"Pericolosi abitanti degli abissi"!|n|nCredo che sverrei se ne incontrassi uno! Sono certa che questo libro sia buono per farci due risate, ma ora non ho tempo per leggerlo.|n|nSai a chi potrebbe interessare? A Michael Crowe il Sudicio, quel pescivendolo al porto. Colleziona vecchi libri.', },
    {'Consegna "Pericolosi abitanti degli abissi" a Michael Crowe il Sudicio al Porto di Theramore.', },
  },
  [11194] = {
    nil,
    {'Oh, sono sicuro che tu e Babs vi siete fatti delle grasse risate con le bizzarre descrizioni e i disegni contenuti nel libro, ma hai mai pensato che le leggende potessero nascondere un fondo di verità?|n|nSe ascolti attentamente, scommetto che puoi sentire ancora i marinai parlare di Tethyr, la creatura marina che secondo il libro vive qui! Ovviamente, se vuoi averne la certezza puoi sempre chiedere al vecchio Nat Pagle.|n|nHa un piccolo allevamento di pesci su un isolotto a Cala Ondarabbiosa, a sud-ovest oltre la Baia di Acquemorte.', },
    {'Parla con Nat Pagle nel Molo di Nat ad Acquemorte.', },
  },
  [11196] = {
    'Il Signore della Guerra degli Amani',
    nil,
    nil,
  },
  [11198] = {
    nil,
    {'Mostro marino o no, non ho alcuna intenzione di mettere in pericolo le nostre navi. Ho ordinato ai nostri migliori tiratori di prepararsi ad affrontare Tethyr. Gli artiglieri hanno migliorato le difese del porto con tre mortai.|n|nIo darò l\'ordine di accendere il faro. Se Tethyr ci attacca, tu dovrai azionare i mortai e abbattere quella bestia prima che possa uccidere tutti i nostri tiratori. Se vuoi un consiglio, continua a muoverti. Probabilmente i mortai attireranno l\'attenzione di quel mostro.', },
    nil,
  },
  [11199] = {
    'A rapporto dall\'Esploratore Knowles',
    {'$N, ora che ci siamo liberati di quelle maledette proto-creature, ho un\'altra missione da affidarti.|n|nUno dei miei esploratori ha parlato di attività sospette dei Reietti a sud. Sembrerebbe che stiano tramando qualcosa nel villaggio Vrykul di Halgrind.|n|nVoglio che tu conduca personalmente le indagini sul posto. Parla con l\'Esploratore Knowles e fatti riferire ciò che ha scoperto, dopodiché l\'operazione sarà nelle tue mani.|n|nL\'ultima posizione conosciuta dell\'esploratore è la Torre Lancia Rovente, a ovest di Halgrind.', },
    {'Il Capitano Adams ti ha chiesto di parlare con l\'Esploratore Knowles alla Torre Lancia Rovente.', },
  },
  [11201] = {
    nil,
    {'Ora che tutti sanno delle loro attività a Millepicchi, i Totem Truce sono visti con sospetto da parecchi Tauren. Abbiamo visto dei Totem Truce di alto rango macchiarsi di omicidi e rapimenti per perseguire i propri interessi e temo che noi saremo il loro prossimo obiettivo.|n|nIl Villaggio di Zoccolo Nero a nord-est, vicino a Motazzurra, è un grosso insediamento dei Totem Truce creato di recente. I loro capi, gli anziani, ricevono ordini direttamente da Picco del Tuono. Cerca di rubare e mettere insieme gli ordini per scoprire i piani dei Totem Truce.', },
    nil,
  },
  [11202] = {
    'Missione: Fiamma Eterna',
    {'I Reietti stanno tramando qualcosa e secondo me quei Carri della Piaga pieni di roba verde fanno parte del piano.|n|nSe posso permettermi, $GSignore:Signora;, suggerirei di distruggerli prima che possano usufruirne. Mi sono preso la libertà di procurarmi un po\' di torce da Selvardente. Sono giorni che bruciano!|n|nEccole. Sono sicuro che ne farai un uso migliore, utilizzandole per distruggere i carri.', },
    {'L\'Esploratore Knowles alla Torre Lancia Rovente ti ha consigliato di usare le Torce Eterne per distruggere i quattro Carri della Piaga che circondano Halgrind.', },
  },
  [11203] = {
    nil,
    {'Le armi che hai trovato nel Villaggio di Zoccolo Nero sono state usate solo per l\'addestramento, mai in battaglia. Questo significa che i Totem Truce che hanno distrutto la Locanda Ombracalma sono ancora a piede libero.|n|nA sud, nel cuore delle Acque Stagnanti, vive la Megera Tabetha. Anche se è un\'Umana, si è comportata bene con noi e ha addestrato alcuni dei nostri Maghi.|n|nChiedile aiuto per trovare i Totem Truce responsabili dell\'incendio alla locanda. L\'Alleanza non deve pensare che abbiamo qualcosa a che fare con quell\'attacco.', },
    {'Parla con Tabetha alla sua cascina nelle Acque Stagnanti.', },
  },
  [11204] = {
    nil,
    {'Spero di esserti stato utile. Mi dispiace non poterti fornire altre informazioni. I miei apprendisti e io produciamo un volume di armi e armature così grande che è praticamente impossibile ricordarsi i dettagli di un pezzo particolare.|n|nI nostri equipaggiamenti non finiscono solo nelle mani dei coraggiosi che difendono le terre dei Tauren. In particolare, i Totem Truce hanno una passione per i miei lavori. Un guerriero esperto sa riconosce un lavoro fatto ad arte.', },
    {'Parla con Krog a Felcimura.', },
  },
  [11205] = {
    nil,
    {'Non serve essere una Scrutatrice per vedere i guai che stanno creando i miei nuovi "vicini". Se è lo stesso gruppo che ha bruciato la Locanda Ombracalma, come sostieni, non c\'è ragione per tollerare oltre la loro presenza.|n|nPrendi questa torcia e brucia il loro accampamento! L\'Accampamento Corno Furente si trova a nord della mia tenuta, vicino alla strada. Lo riconoscerai dai totem che i Totem Truce hanno sistemato ovunque.', },
    nil,
  },
  [11206] = {
    nil,
    {'Dubito che i Totem Truce rinunceranno ai loro propositi di cacciare gli Umani dalla palude, anche se ho come l\'impressione che la cosa non ti interessi. Almeno abbiamo punito i responsabili dei crimini alla Locanda Ombracalma.|n|nVa\' a dire al tuo capo che la sua vendetta è stata compiuta.', },
    {'Torna da Krog a Felcimura.', },
  },
  [11207] = {
    nil,
    {'Questo Zeppelin stava trasportando rifornimenti per sei mesi a Melmarmitta! Sono certa che gli abitanti sono riusciti a far fronte alle difficoltà in qualche modo, ma non potranno resistere all\'infinito.|n|nMi hanno mandata qui per recuperare il carico che ha resistito allo schianto, ma purtroppo si è sparso per tutta la palude. Mi aiuteresti a recuperarne il più possibile?', },
    {'Moxie Grigliafredda al Relitto di Beezil ti ha chiesto di recuperare 8 Pezzi del Carico dello Zeppelin.', },
  },
  [11208] = {
    'Consegna per Drazzit',
    {'Drazzit attende mie notizie a breve, ma non credo che questo posto sia abbastanza al sicuro per andarmene. Se hai tempo, ti dispiacerebbe andare a Melmarmitta e consegnargli parte del carico recuperato?|n|nSe non ci sei mai $Gstato:stata;, è un piccolo insediamento a sud-ovest di qui, oltre le Rovine dei Mazzapietra. Puoi arrivarci anche prendendo la strada dalla Cascina di Tabetha. Quando arrivi a Melmarmitta, cerca Drazzit Svalvolato.', },
    {'Consegna il Carico dello Zeppelin a Drazzit Svalvolato nel villaggio di Melmarmitta.', },
  },
  [11210] = {
    nil,
    {'Sì, Tethyr esiste davvero e vive nelle acque al largo di Theramore.|n|nÈ attratto dalla luce forte. Per questo hanno dovuto spegnere il faro...|n|nSe lo riaccendete, tornerà. Nessuno sano di mente oserebbe fare una cosa del genere.|n|nImmagino che questo sia il tuo piano! È stato bello bere insieme a te, ma non prendertela con il vecchio Nat se Tethyr dovesse trasformarti DAVVERO in un\'esca per pesci. Se hai intenzione di andare fino in fondo, parla prima con il Sindaco Mills al Porto di Theramore.', },
    {'Parla con il Sindaco Mills al Porto di Theramore.', },
  },
  [11211] = {
    'Aiuto per Melmarmitta',
    {'Quando quella Goblin... com\'è che si chiama... Boxie, Foxy... ah sì, Moxie! Quando è passata di qui diretta verso il relitto dello Zeppelin, mi ha detto che Melmarmitta stava avendo dei problemi.|n|nLo Zeppelin precipitato conteneva delle provviste per il villaggio. Melmarmitta si trova lungo la strada a sud, oltre le Rovine dei Mazzapietra.|n|nPerché non vai là a parlare con Drazzit Svalvolato e vedi se c\'è qualcosa che puoi fare per renderti utile?', },
    {'Parla con Drazzit Svalvolato a Melmarmitta.', },
  },
  [11212] = {
    'Fattoria di Tabetha',
    {'Nel cuore della palude vive una vecchia di nome Tabetha. Non sappiamo molto sul suo conto, tranne che ha molti più anni di quelli che dimostra. Ogni tanto ci ha aiutati a mantenere la pace qui tra le nostre forze e l\'Orda.|n|nSiamo rimasti sempre in contatto, ma ora è da un po\' che non abbiamo più sue notizie.|n|nPotresti andare a controllare quando hai tempo? Basta che segui la strada oltre la Torre Settentrionale, dove gira verso sud e si immette nelle Acque Stagnanti. Puoi vedere la sua cascina dalla strada.', },
    {'Parla con Tabetha alla sua cascina nelle Acque Stagnanti.', },
  },
  [11213] = {
    'Una visita da Tabetha',
    {'C\'è una donna umana di nome Tabetha che vive in una piccola cascina vicino la parte centrale della palude. Di solito non faccio affari con gli Umani, ma il suo aiuto si è rivelato prezioso in più di un\'occasione.|n|nPurtroppo non abbiamo più sue notizie da un po\' di tempo e sto cercando qualcuno disposto a viaggiare fino alla sua cascina per verificare che sia tutto a posto.|n|nSe segui la strada a sud del villaggio, fino dentro la palude, troverai la sua cascina all\'interno delle Acque Stagnanti.', },
    {'Parla con Tabetha alla sua cascina nelle Acque Stagnanti.', },
  },
  [11214] = {
    nil,
    {'Recentemente, il Cartello degli Spargifumo ha stabilito un nuovo avamposto nella parte meridionale di Acquemorte. Se non ricordo male si chiama Melmarmitta ed è situato lungo la strada principale a sud della Cascina di Tabetha e delle Rovine dei Mazzapietra.|n|nQuesta è un\'ottima occasione per stabilire nuovi contatti commerciali. A tal proposito, Dama Jaina vuole che mandi lì un nostro rappresentante. Ti andrebbe di andarci?', },
    {'Parla con Drazzit Svalvolato a Melmarmitta.', },
  },
  [11215] = {
    'Aiutare Melmarmitta',
    {'Il nuovo avamposto del Cartello degli Spargifumo nella parte meridionale della palude non se la passa troppo bene. Lo Zeppelin che stava trasportando le provviste a Melmarmitta è precipitato, lasciando gli abitanti senza rifornimenti, cibo e medicine.|n|nSegui la strada a sud fino alla palude. Prima di arrivare a Melmarmitta dovrai passare per la Cascina di Tabetha e le Rovine dei Mazzapietra. Offri tutto l\'aiuto che puoi dare al capo del villaggio.', },
    {'Parla con Drazzit Svalvolato a Melmarmitta.', },
  },
  [11216] = {
    'L\'Arcimago Alturus',
    nil,
    {'Parla con l\'Arcimago Alturus fuori da Karazhan nel Valico Ventomorto.', },
  },
  [11217] = {
    nil,
    {'Lo schianto dello Zeppelin ha bloccato i rifornimenti e ora abbiamo esaurito le scorte di medicine e bende.|n|nCi stiamo arrangiando ma tra insetti, ferite e i nemici che si trovano qui, riesco a malapena ad andare avanti! Ho scoperto un\'erba che pare in grado di guarire le ferite e placare il dolore, ma siamo a corto anche di quella.|n|nSi chiama Codragone e cresce abbondante presso lo Stagno dei Draghi e il Brago dei Dragoni a est. Le piante hanno steli affusolati e sembrano pulsare quando le guardi.', },
    nil,
  },
  [11218] = {
    'Pericolo! Esplosivi!',
    {'$N, il Capitano mi ha affidato una missione e vorrei chiederti di aiutarmi.|n|nAlcuni miei compagni della Lega degli Esploratori sono impazziti scavando nella Gola dei Sussurri a nord. Attaccano chiunque tenti di entrare!|n|nIl Capitano è preoccupato che non arrivi più minerale al Forte. Fortunatamente, ho già pronta una soluzione.|n|nEntra nella gola, fa\' esplodere le vene di minerale e portalo qui con tutte le gemme che trovi. La gestione di questo posto costa cara!|n|nPerò fa\' attenzione: quel minerale è strano!', },
    {'Usa la Dinamite Infallibile di Duranello per raccogliere 6 Frammenti di Minerale della Gola dei Sussurri e 18 Gemme della Gola dei Sussurri. Poi, portali al Geniere Duranello nel Forte di Guardia dell\'Ovest.', },
  },
  [11219] = {
    'Spegni i roghi!',
    {'I figli dell\'Orda hanno bisogno di te, $N. Il Cavaliere Senza Testa, un tempo un Paladino degli Umani e ora uno spietato demonio, ha dato fuoco al villaggio! Devi spegnere quei roghi!|n|nPrendi un secchio e usalo per gettare l\'acqua sulle fiamme, oppure passalo a un compagno più vicino al fuoco. Spegni tutti i roghi per fermare il Cavaliere Senza Testa!', },
    {'La Matrona degli Orfani Mascherata ti ha chiesto di aiutare a domare i roghi del villaggio. Quando li avrai spenti tutti, torna a parlarle.', },
  },
  [11220] = {
    'Cavaliere Senza Testa',
    nil,
    {'Trova il Santuario della Zucca del Cavaliere Senza Testa.', },
  },
  [11221] = {
    'Notizie dal campo di battaglia',
    {'La nostra missione a Nordania è distruggere Arthas. L\'Alleanza è solo un ostacolo da schiacciare ogni volta che se ne presenti l\'occasione.|n|nSiamo riusciti a distruggere la sua flotta orientale, ma i superstiti si sono barricati sulla Riva del Conflitto a sud.|n|nLe nostre armate avrebbero dovuto distruggere le loro difese improvvisate molto tempo fa, ma ne abbiamo sottovalutato l\'istinto di sopravvivenza. Cerca i miei ufficiali sul campo, la Guardaboschi Oscura Lyana e l\'Inseguitore della Morte Razael, e fatti ragguagliare sulla situazione.', },
    {'Parla con la Guardaboschi Oscura Lyana e l\'Inseguitore della Morte Razael nel campo di battaglia della Valle Sanguinante, a sud dell\'Attracco della Vendetta. Poi, torna dal Gran Esecutore Anselm.', },
  },
  [11223] = {
    nil,
    {'Devo organizzarmi per annientare i resti dei Defias. Quando torni a Theramore, ringrazia Dama Jaina da parte mia. È sempre stata un\'amica fedele e un\'alleata affidabile.|n|nVai al Quartiere dei Maghi nella parte occidentale della città e parla con l\'Arcimago Malin ai piedi della torre. Egli ti farà tornare a Theramore in un baleno.', },
    nil,
  },
  [11224] = {
    'Torna a casa, mulo!',
    {'Ho sentito che sono successe delle brutte cose nella Gola dei Sussurri a nord. La maggior parte della Lega degli Esploratori è scesa laggiù e alcuni dicono che i suoi membri siano impazziti a causa di ciò che hanno scoperto.|n|nComunque, non cambia il fatto che abbiano portato con loro quasi tutti i nostri muli e l\'equipaggiamento. Non voglio perdere i muli!|n|nSe capiti da quelle parti, e trovi qualcuno dei miei muli, avvicinati e minacciali alzando una mano. Si spaventeranno e torneranno a casa.', },
    {'L\'Esploratrice Abigail ti ha chiesto di eseguire l\'emote /alza davanti a 10 Muli da Soma Abbandonati. Poi, torna da lei al Forte di Guardia dell\'Ovest.', },
  },
  [11225] = {
    nil,
    {'La palude sembra avere uno strano effetto sugli Umani. Alcuni impazziscono semplicemente vivendoci.|n|nChiunque abbia vissuto nella Dimora Fuocofioco è andato fuori di testa. L\'ultimo proprietario, un certo Jarl "Occhio Marcio", sta già dando segni di squilibrio.|n|nNon so cosa stia succedendo esattamente lì, ma ti sarei grato se andassi a controllare.|n|nLa dimora si trova al confine orientale della palude, su un terreno maledetto chiamato Colle della Strega. Per raggiungerla, procedi a est oltre Motazzurra e la Torre Settentrionale.', },
    {'Parla con Jarl "Occhio Marcio" alla Dimora Fuocofioco.', },
  },
  [11226] = {
    'Promozione del mazzo superiore - Tigre Spettrale Cavalcabile',
    nil,
    nil,
  },
  [11227] = {
    'Nutriamoli a corvi!',
    {'Il Gran Esecutore mi ha ordinato di usare i cani per fiutare gli esploratori nemici, ma questi Segugi Infetti non andranno da nessuna parte a stomaco vuoto.|n|nSe i militari non capiscono che sono bestie schizzinose e non mangiano la spazzatura che ricevo, allora che non si aspettino di poterli usare sul campo di battaglia!|n|nA occhio, direi che hai del tempo libero: perché non ne porti uno con te per una battuta di caccia di corvi a ovest di qui? Per noi, la carne di quei volatili è disgustosa... ma i miei ragazzi l\'adorano!', },
    {'Pontius, il Guardiano del Canile all\'Attracco della Vendetta, ti ha chiesto di usare la Gabbia per Segugio Infetto per evocare un Segugio Infetto Affamato e nutrirlo con la Carne di Corvo dei Fiordi a ovest dell\'Attracco della Vendetta.', },
  },
  [11228] = {
    'Ha nevicato all\'inferno',
    {'Se Domadraghi crede che il gruppetto di novellini che ha inviato a difendere il porto possa resistere ancora a lungo, si sbaglia di grosso.|n|n<Macalroy solleva un sopracciglio, mentre esamina il tuo equipaggiamento.>|n|nTu, d\'altra parte, potresti cavartela meglio.|n|nNon mi stancherò mai di ribadire l\'importanza di mantenere il controllo su questo porto. Inoltre, con quei mostri che ci volano sopra la testa, la situazione è appena cambiata di male in peggio.|n|nParla con il Viceammiraglio Keller, poco a nord-ovest di qui, e riferiscigli che sei <pronto/pronta> a spaccare qualche testa.', },
    {'Parla con il Viceammiraglio Keller nel Porto di Valguardia.', },
  },
  [11229] = {
    'La flotta della Regina',
    {'La Ventolesto, la Sfida Oscura e l\'Oblio stazionano a est della Riva del Conflitto. Ordina al Capitano Harker, il Comandante della flotta, di distruggere i Cannoni dell\'Alleanza.|n|nParla con l\'Addestratrice di Pipistrelli Camille e chiedile un passaggio verso la flotta. Fa\' in fretta, $N, ogni minuto passato a combattere l\'Alleanza è un minuto rubato alla guerra contro Arthas.', },
    {'Parla con l\'Addestratrice di Pipistrelli Camille all\'Attracco della Vendetta e ottieni un passaggio per la Ventolesto. Parla con il Capitano Harker a bordo della nave.', },
  },
  [11230] = {
    nil,
    {'Sarebbe dovuta essere una passeggiata! I nostri nemici sono feriti, affamati e mal equipaggiati. Eppure, non so come, siamo finiti dritti nella loro trappola.|n|nCi siamo avvicinati alle scogliere da sud per sfruttare la loro copertura, ma i cani dell\'Alleanza ci hanno subito abbordati.|n|nMi dispiace, ma se vuoi che usiamo i nostri cannoni per sparare, dovrai prima aiutarci a riconquistare le navi.', },
    {'Il Capitano Harker a bordo della Ventolesto ti ha chiesto di uccidere 15 Militari della Flotta del Nord.', },
  },
  [11231] = {
    'Chiavi e gabbie',
    {'Il Capitano se ne disinteressa ma, da quel poco che sappiamo, i Vrykul stanno conducendo dei riti atroci in una sorta di cerimonia del "risveglio" a Gjalerbron, a nord.|n|nSacrificano esseri viventi per alimentare questi empi rituali!|n|n$C, devi farli smettere! Non importa chi o che cosa ci sia in quelle gabbie, bisogna liberarli. Scommetto che le chiavi le hanno i Vrykul.|n|nLa Luce sa che l\'ultima cosa di cui abbiamo bisogno sono altri grotteschi Vrykul liberi di scorrazzare... o, peggio, che essi risveglino qualcosa di ancor più malvagio!', },
    {'Padre Levariol ti ha chiesto di recuperare un numero sufficiente di Chiavi delle Gabbie di Gjalerbron per liberare 10 Prigionieri di Gjalerbron. Poi, torna da lui al Forte di Guardia dell\'Ovest.', },
  },
  [11232] = {
    'Sii i nostri occhi',
    {'Dovremmo riuscire a farci strada con la forza verso le nostre armi. Sfortunatamente, la visibilità è più che ridotta e dovrai segnalarci i bersagli da terra.|n|nPrendi questi fumogeni e usali per indicare la posizione dei cannoni lungo il muro settentrionale della Riva del Conflitto a ovest, dove l\'Alleanza resiste.|n|nAppena la via sarà libera per far passare le truppe di terra, avvisa subito Lyana. Qui possiamo sbrigarcela da soli.', },
    {'Usa i Fumogeni sui Cannoni dell\'Alleanza sul muro settentrionale della Riva del Conflitto. Poi, parla con la Guardaboschi Oscura Lyana nella Valle Sanguinante.', },
  },
  [11233] = {
    'Sferrare il colpo di grazia',
    {'$N, ti sei $Gfatto:fatta; onore sul campo di battaglia e potresti aver ribaltato le sorti in nostro favore.|n|nHo un incarico molto importante da affidarti: non so quanto a lungo potremo sfruttare il punto debole che abbiamo scoperto, quindi dobbiamo usare il fattore sorpresa.|n|nApprofitta della confusione generata dal nostro attacco per attraversare le linee nemiche e uccidere i loro capi. In ordine gerarchico: il Capitano Olster, il Tenente Celeyne e il Sergente Lorric. Buona fortuna, $C.', },
    {'La Guardaboschi Oscura Lyana a sud dell\'Attracco della Vendetta ti ha chiesto di uccidere il Capitano Olster, il Tenente Celeyne e il Sergente Lorric alla Riva del Conflitto.', },
  },
  [11234] = {
    'A rapporto da Anselm',
    {'Andiamo a riferire le novità al vecchio Anselm. La vittoria si è fatta desiderare, ma meglio tardi che mai. Digli che le nostre armate impiegheranno al massimo qualche ora per eliminare gli ultimi sopravvissuti.|n|nGloria alla Regina Banshee!', },
    {'Fai rapporto al Gran Esecutore Anselm presso l\'Attracco della Vendetta del Fiordo Echeggiante.', },
  },
  [11235] = {
    'Il problema di Gjalerbron',
    {'Ora abbiamo un altro problema. Gli esploratori che sono tornati indietro vivi mi hanno informato che i Vrykul stanno tramando qualcosa nella loro fortezza a nord.|n|nIl posto si chiama Gjalerbron, anche se bisognerebbe pronunciare "Gj" come se fosse "Sh". Che creature bizzarre!|n|nMa torniamo alle cose importanti: devi ucciderne il più possibile, mentre tenti di capire cosa stanno architettando.|n|n$N, so che posso contare su di te.', },
    {'Il Capitano Adams ti ha chiesto di uccidere 15 Guerrieri di Gjalerbron, 8 Lanciarune di Gjalerbron e 8 Guardiasonno di Gjalerbron. Poi, torna da lui al Forte di Guardia dell\'Ovest.', },
  },
  [11236] = {
    'Il Necrosupremo Mezhen',
    {'Il Flagello ha con sé alcuni negromanti a Gjalerbron! Staranno lavorando per portare i Vrykul nell\'ovile di Arthas.|n|nVoglio che elimini il capo di questi necrosignori!|n|n$N, neutralizza il Necrosupremo Mezhen e sventa qualsiasi piano abbia in mente, a ogni costo!|n|nNon voglio vedere i Vrykul allearsi con il Flagello!|n|nCerca Mezhen sulla piattaforma nella sezione posteriore destra di Gjalerbron.', },
    {'Uccidi il Necrosupremo Mezhen. Poi, torna dal Capitano Adams al Forte di Guardia dell\'Ovest.', },
  },
  [11237] = {
    'I Piani d\'Attacco di Gjalerbron',
    {'<Questi piani indicano un attacco imminente al Forte di Guardia dell\'Ovest. Sembra che Glacion, il Dragone del Gelo che vola in circolo qui sopra, verrà usato per sferrare l\'offensiva.>|n|n<Il Tenente Mago Malister potrebbe essere d\'aiuto. Consegnagli i piani nel Forte a sud.>', },
    {'Consegna i Piani d\'Attacco di Gjalerbron al Tenente Mago Malister nel Forte di Guardia dell\'Ovest.', },
  },
  [11238] = {
    'Il Dragone del Gelo e il suo padrone',
    nil,
    {'Uccidi l\'Invocatore dei Dragoni Vile e usa il Corno dell\'Invocatore dei Dragoni per richiamare e uccidere Glacion. Poi, consegna il corno al Tenente Mago Malister nel Forte di Guardia dell\'Ovest.', },
  },
  [11239] = {
    'Al servizio della Luce',
    {'$N, la tua dedizione è esemplare, ma c\'è qualcosa che mi turba: il Flagello.|n|nLa Luce non può sopportare la sua presenza... e nemmeno noi. Spero di non chiederti troppo, ma vorrei che tornassi a Gjalerbron a nord e annientassi l\'empio Flagello in quell\'antro spregevole! Ricorda di cercare quei maledetti anche nei Saloni del Risveglio sotto Gjalerbron.|n|n$GFiglio mio:Figlia mia;, la purificazione è la chiave per la salvezza. Rendici orgogliosi!', },
    {'Uccidi 10 Guardiani Senzamorte, 4 Orrori Temibili e 2 Wight Putridi. Poi, riferisci il tuo successo a Padre Levariol nel Forte di Guardia dell\'Ovest.', },
  },
  [11240] = {
    'Il capo degli squilibrati',
    {'Mi dispiace dirtelo ma, mentre eri via, il Capitano ha sviluppato un certo interesse per quel posto.|n|nVuole che il mio vecchio capo della Lega degli Esploratori muoia. Secondo me ci prepariamo ad attaccare per sterminarli tutti e il Capitano vuole eliminare la testa del gruppo.|n|nMi faresti un favore? Torna nella Gola dei Sussurri e uccidi Squeeg Cacciaidoli. Se ricordo bene, dovrebbe trovarsi nella grotta all\'angolo nord-ovest.', },
    {'Uccidi Squeeg Cacciaidoli. Poi, parla con il Geniere Duranello al Forte di Guardia dell\'Ovest.', },
  },
  [11241] = {
    'Una scia di fiamme',
    {'$N, grazie per avermi tirato fuori dai guai. Non ero per niente curioso di scoprire cosa avessero in serbo per me quei maledetti dell\'Alleanza.|n|nAndiamocene da qui e pensiamo a come fargliela pagare. Un momento... Quello è un fuoco da campo?', },
    {'Scorta lo Speziale Hanes fuori dalla Riva del Conflitto. Poi, parla con lo Speziale Lysander all\'Attracco della Vendetta nel Fiordo Echeggiante.', },
  },
  [11242] = {
    'Libero, infine!',
    {'Ero prigioniero della rabbia, $N, e tu mi hai liberato. Prima credevo di essere nel giusto, ma ora il mio spirito soffre per tutta la morte e il terrore che ho causato su Azeroth.|n|nGrazie per avermi fatto tornare sulla via della Luce. E che io non perda più la retta via.|n|nPorta questo vecchio Libro di Preghiere a una Matrona degli Orfani, così i bambini sapranno che non li perseguiterò più.', },
    {'Porta il Tomo di Thomas Thomson alla Matrona degli Orfani in Costume presso Borgodoro, Kharanos o il Presidio Azzurro.', },
  },
  [11243] = {
    'Se Valguardia cade...',
    {'Se Valguardia cade, la nostra rotta di rifornimento principale con Nordania si interromperà. A quel punto, sarà solo questione di tempo prima di diventare tutti servitori del Re dei Lich. Io non ti conosco, ma a Elwynn ho moglie e tre figli: che io sia maledetto, se mi arrendo senza combattere!|n|nLa situazione è critica e abbiamo bisogno di tutto l\'aiuto che puoi darci. Raggiungi la porta frontale e aiuta le guardie a difendere la città dai mostri invasori!', },
    nil,
  },
  [11244] = {
    'Al salvataggio dei salvatori',
    nil,
    {'Il Viceammiraglio Keller al Porto di Valguardia nel Fiordo Echeggiante ti ha chiesto di salvare 8 Esploratori di Valguardia, che sono stati impalati e lasciati a morire.', },
  },
  [11245] = {
    'Le torri della morte certa',
    nil,
    {'Il Sergente di Guardia dell\'Ovest ti ha consigliato di usare il suo fumogeno su tutte e quattro le torri di Skorn per richiedere qualche colpo di cannone.', },
  },
  [11246] = {
    'Terribile, ma necessario',
    {'Abbiamo saputo che quei Vrykul possono tornare in vita: non sono molto diversi dal Flagello, ma comunque un altro tipo di non morti.|n|nNon dobbiamo rischiare.|n|nPrendete il mio machete. Mentre avanziamo, dovrete smembrare i resti dei Vrykul che uccideremo. Lo farei io, ma ho lo stomaco debole.|n|n<Il Sergente sogghigna.>|n|nHo passato tutta la mattina ad affilarlo, dovrebbe andar bene.', },
    {'Il Sergente di Guardia dell\'Ovest ti ha chiesto di usare il suo machete per smembrare 20 Vrykul della Tribù Geloskorn a Skorn.', },
  },
  [11247] = {
    'Brucia, Skorn! Brucia!',
    {'Il Capitano Adams mi dato delle istruzioni molto chiare per aiutarci a causare il maggior numero di danni possibili alle infrastrutture di questo posto.|n|nComunque siete voi al comando, quindi siete voi che dovete scegliere, $Gsignore:signora;.|n|nPosso suggerirvi di incendiare le due Caselunghe e la Caserma nella zona inferiore di Skorn? Dobbiamo solo entrare in ognuna delle tre strutture e appiccare il fuoco.', },
    {'Il Sergente di Guardia dell\'Ovest ti ha consigliato di usare la sua torcia per incendiare le Caselunghe a nord-est e a nord-ovest e la Caserma di Skorn.', },
  },
  [11248] = {
    'Operazione: Ira funesta',
    {'$N, devo chiederti di intraprendere una missione talmente pericolosa e letale che solo tu puoi riuscire a compiere!|n|nSkorn, la fortezza dei Vrykul, si trova al nostro confine orientale. Secondo i miei esploratori, i "giganti" stanno per attaccarci. Le mie armate sono sparpagliate per tutto il Fiordo, quindi non ho nessuno da inviare a occupare la fortezza.|n|nInvece di usare la forza, ho intenzione di sfruttare la tua astuzia. Ho mandato in avanscoperta un Sergente con tutti i dettagli sulla missione. Sfoggia questo Fregio del Comando quando sarai a Skorn: il Sergente si rivelerà a te ed eseguirà i tuoi ordini.', },
    nil,
  },
  [11249] = {
    'Fermare l\'Ascesa!',
    {'<Quest\'enorme rotolo è fatto di pelle di drago. Srotolato, è lungo più di tre metri. Le immagini dipinte sulla sua superficie a scaglie raffigurano un misterioso rituale Vrykul.>|n|n<Uno dei loro Thane, circondato da esseri dall\'aspetto angelico, ascende in cielo. Una figura misteriosa e oscurata è in agguato sullo sfondo.>|n|n<Un formicolio allo stomaco ti suggerisce che il Thane di Skorn sta per eseguire proprio questo rituale. Devi fermarlo! Davanti al suo rifugio, sulla cima di Skorn, c\'è un\'enorme pira.>', },
    {'Porta il Rotolo dell\'Ascesa Vrykul vicino alla Pira del Thane per chiamarlo e uccidilo. Poi, data la natura del rituale, assicurati che Padre Levariol al Forte di Guardia dell\'Ovest sia interessato a esaminare il rotolo.', },
  },
  [11250] = {
    'Onore e gloria al conquistatore di Skorn!',
    {'Abbiamo... anzi, AVETE fatto tutto ciò per cui siamo stati inviati qui, $GSignore:Signora;. Devo dire che è stato un piacere servire $Gun:una; così giovane e in gamba $R.|n|nIl Capitano vorrà sicuramente essere informato dei vostri successi. Ciononostante... Se, per qualsiasi motivo, preferiste rimanere qui, sono a vostra disposizione.', },
    {'Restituisci il Fregio del Comando di Guardia dell\'Ovest al Capitano Adams al Forte di Guardia dell\'Ovest.', },
  },
  [11251] = {
    'La riserva entra in campo',
    {'Ci è costato molto, ma abbiamo completato l\'ispezione di questo posto.|n|nLe novità non sono buone: sono stati uccisi o catturati quasi tutti. Solo poche guardie veterane mancano all\'appello.|n|nGli esploratori hanno fatto tutto il possibile, ora tocca a te proseguire da dove ci siamo fermati.|n|nDalla collina a nord-est provengono i suoni di una schermaglia. Va\' a dare un\'occhiata. Possiamo solo sperare che ci siano dei sopravvissuti... e che abbiano delle informazioni utili da usare contro il nemico.', },
    {'L\'Esploratrice Valory ti ha chiesto di indagare sui suoni di battaglia che provengono dalla zona nord-est di Cranio del Drago.', },
  },
  [11253] = {
    'Fiutando il nemico',
    {'Ora che ha la pancia piena, magari quella canaglia accetterà di collaborare. Ecco il suo guinzaglio: fallo uscire dalla gabbia quando sei $Gpronto:pronta; a portarlo a fare un giro.|n|nNon so Anselm cosa si aspetti che tu scopra, ma cerca indizi ovunque ti porti quel cane.', },
    nil,
  },
  [11254] = {
    'La Mappa di Pelle di Drago',
    {'<A un esame più approfondito, la pergamena risulta essere una mappa del Fiordo piena di illustrazioni. La posizione dei vari villaggi è raffigurata da quelli che sembrano essere simboli tribali.>|n|n<L\'Attracco della Vendetta è indicato da un teschio esageratamente grande.>|n|n<Sicuramente il valore militare di questa mappa sarà molto apprezzato dal Gran Esecutore Anselm.>', },
    {'Porta la Mappa di Pelle di Drago al Gran Esecutore Anselm nell\'Attracco della Vendetta.', },
  },
  [11255] = {
    'I prigionieri di Cranio del Drago',
    {'$N, la battaglia non è ancora finita. Se la nostra gente è ancora viva in quel villaggio, allora qualcuno deve andare a salvarla.|n|n<Il Viceammiraglio Keller annuisce rivolto a te.>|n|nDirigiti a nord, entra a Cranio del Drago e cerca i nostri. Se sono imprigionati, dovrai trovare il modo di farli evadere.|n|nForse potranno fornirci ulteriori informazioni su chi stiamo combattendo.', },
    {'Il Viceammiraglio Keller al Porto di Valguardia nel Fiordo Echeggiante ti ha chiesto di salvare 3 Soldati di Valguardia Catturati.', },
  },
  [11256] = {
    'Skorn deve cadere!',
    {'Skorn, la fortezza dei Vrykul è a sud. Recentemente, i suoi strani giganti di carne si sono risvegliati e hanno iniziato a vagare per il Fiordo, attaccandoci ogni volta che ne hanno avuta la possibilità.|n|nSecondo i miei esploratori, si preparano ad attaccare anche questo posto. Purtroppo, non siamo abbastanza forti da respingere un assalto di queste proporzioni, quindi ci prepariamo a migrare verso terre più tranquille a nord.|n|nTi chiedo di mettere a frutto la tua astuzia per farci guadagnare del tempo. Ho mandato un guerriero in avanscoperta con tutti i dettagli dell\'operazione: sfoggia questo emblema a Skorn, così si rivelerà a te e farà tutto il possibile per aiutarti.', },
    nil,
  },
  [11257] = {
    'Terribile, ma necessario',
    {'Secondo i nostri anziani, quei Vrykul potrebbero essere in grado di tornare in vita: non sono molto diversi dai morti viventi che chiamate Flagello, ma sono comunque un altro tipo di non morti.|n|nNon dobbiamo rischiare.|n|nPrendi il mio machete. Mentre avanziamo, dovrai smembrare i resti dei Vrykul che uccideremo.|n|nHo passato tutta la mattina ad affilarlo, dovrebbe trapassare persino le loro spesse ossa.', },
    {'Il Guerriero Zoccolo Artico ti ha chiesto di usare il Machete del Guerriero per smembrare 20 Vrykul della Tribù Geloskorn a Skorn.', },
  },
  [11258] = {
    'Brucia, Skorn! Brucia!',
    {'Il Capo Tribù Totem Sabbioso mi ha ordinato di distruggere più edifici possibili.|n|nComunque, sei tu che comandi, quindi la scelta spetta a te.|n|nTi suggerisco di incendiare le due Caselunghe e la Caserma nella zona inferiore di Skorn. Dobbiamo solo entrare in ognuna delle tre strutture e appiccare il fuoco.', },
    {'Il Guerriero Zoccolo Artico ti consiglia di usare la sua Torcia del Guerriero per incendiare le Caselunghe a nord-est e a nord-ovest e la Caserma di Skorn.', },
  },
  [11259] = {
    'Le torri della morte certa',
    {'Mentre avanziamo verso Skorn, dobbiamo distruggere quelle torri!|n|nGuardale bene e noterai che in cima ci sono delle file di incantatori. Se ci avvicineremo troppo, per noi sarà morte certa!|n|nComunque, possiamo richiedere qualche attacco aereo delle Viverne dei Venti dall\'Accampamento degli Zoccolo Artico. Per farlo, devi avvicinarti quanto basta per lanciare un Fumogeno sui bersagli.|n|nMa non avvicinarti troppo!', },
    {'Il Guerriero Zoccolo Artico ti ha consigliato di usare i suoi Fumogeni su tutte e quattro le torri di Skorn per richiedere qualche salva di cannone.', },
  },
  [11260] = {
    'Fermare l\'Ascesa!',
    {'<Quest\'enorme rotolo è fatto di pelle di drago. Srotolato, è lungo più di tre metri. Le immagini dipinte sulla sua superficie a scaglie raffigurano un misterioso rituale Vrykul.>|n|n<Uno dei loro Thane, circondato da esseri dall\'aspetto angelico, ascende in cielo. Una figura misteriosa e oscurata è in agguato sullo sfondo.>|n|n<Un formicolio allo stomaco ti suggerisce che il Thane di Skorn sta per eseguire proprio questo rituale. Devi fermarlo! Davanti al suo rifugio, sulla cima di Skorn, c\'è un\'enorme pira.>', },
    {'Porta il Rotolo dell\'Ascesa Vrykul vicino alla Pira del Thane per chiamarlo e uccidilo. Poi, data la natura del rituale, assicurati che la Madre Anziana Ankha all\'Accampamento degli Zoccolo Artico sia interessata a esaminare il Rotolo.', },
  },
  [11261] = {
    'La conquista di Skorn!',
    {'$C, hai fatto tutto ciò per cui siamo stati mandati qui. Lo ammetto: hai combattuto bene. Il tuo popolo non è così strano come pensavo.|n|nIl Capo Tribù Totem Sabbioso vorrà sicuramente essere informato dei tuoi successi. Ciononostante... Se, per qualsiasi motivo, preferissi rimanere qui, sono a tua disposizione.', },
    {'Porta l\'Emblema degli Zoccolo Artico al Capo Tribù Totem Sabbioso nell\'Accampamento degli Zoccolo Artico.', },
  },
  [11262] = {
    'Ingvar deve morire!',
    nil,
    nil,
  },
  [11263] = {
    'Il problema di Gjalerbron',
    {'Gli staffettisti che sono tornati indietro vivi mi hanno informato che i Vrykul si sono risvegliati nella loro fortezza principale ovest.|n|nÈ un luogo proibito chiamato Gjalerbron. Sempre secondo gli staffettisti, quei Vrykul starebbero compiendo degli strani rituali.|n|nNon possiamo permetterlo.|n|nCi aiuterai ancora? Ucciderai i Vrykul di Gjalerbron, prima che completino qualunque cosa stiano facendo e ci attacchino?', },
    {'Il Capo Tribù Totem Sabbioso ti ha chiesto di uccidere 15 Guerrieri di Gjalerbron, 8 Lanciarune di Gjalerbron e 8 Guardiasonno di Gjalerbron. Poi, torna da lui all\'Accampamento degli Zoccolo Artico.', },
  },
  [11264] = {
    'Il Necrosupremo Mezhen',
    {'I morti hanno alcuni negromanti a Gjalerbron?|n|nDobbiamo eliminare il capo di questi necrosignori!|n|n$N, neutralizza il Necrosupremo Mezhen e sventa qualsiasi piano abbia in mente, a ogni costo!|n|nNon possiamo permettere che i piani dei Vrykul con quelle creature non morte abbiano successo!|n|nCerca Mezhen sulla piattaforma nella sezione posteriore destra di Gjalerbron.', },
    {'Uccidi il Necrosupremo Mezhen. Poi, torna dal Capo Tribù Totem Sabbioso all\'Accampamento degli Zoccolo Artico.', },
  },
  [11265] = {
    'Chiavi e gabbie',
    {'Da quel poco che sappiamo, i Vrykul stanno conducendo dei riti innaturali in una cerimonia del "risveglio" a Gjalerbron, a ovest.|n|nSacrificano esseri viventi per alimentare questi rituali!|n|n$N, devi farli smettere! Non importa chi o che cosa ci sia in quelle gabbie, bisogna liberarli. Scommetto che le chiavi le hanno i Vrykul.|n|nL\'ultima cosa di cui abbiamo bisogno sono altri grotteschi Vrykul liberi di minacciarci... o, peggio, che essi risveglino qualcosa di ancor più malvagio!', },
    {'La Madre Anziana Ankha ti ha chiesto di recuperare un numero sufficiente di Chiavi delle Gabbie di Gjalerbron per liberare 10 Prigionieri di Gjalerbron. Poi, torna da lei all\'Accampamento degli Zoccolo Artico.', },
  },
  [11266] = {
    'I Piani d\'Attacco di Gjalerbron',
    {'<Questi piani indicano un attacco imminente all\'Accampamento degli Zoccolo Artico. Sembra che Glacion, il Dragone del Gelo che vola in circolo qui sopra, verrà usato per sferrare l\'offensiva.>|n|n<Celea Manto Gelato potrebbe essere d\'aiuto. Consegnale i piani nell\'Accampamento a est.>', },
    {'Consegna i Piani d\'Attacco di Gjalerbron a Celea Manto Gelato nell\'Accampamento degli Zoccolo Artico.', },
  },
  [11267] = {
    'Il Dragone del Gelo e il suo padrone',
    nil,
    {'Uccidi l\'Invocatore dei Dragoni Vile e usa il Corno dell\'Invocatore dei Dragoni per richiamare e uccidere Glacion. Poi, consegna il corno a Celea Manto Gelato all\'Accampamento degli Zoccolo Artico.', },
  },
  [11268] = {
    'Morti viventi',
    {'$N, il tuo aiuto è stato incredibile, ma c\'è qualcosa che mi turba: il cosiddetto Flagello.|n|nGli spiriti della terra, dell\'aria, dell\'acqua e del fuoco nel sottosuolo del pianeta non tollerano la sua presenza, ma non sembrano voler intervenire. Dovremo sbarazzarcene noi!|n|nSpero di non chiederti troppo, ma vorrei che tornassi a Gjalerbron a ovest e annientassi l\'empio Flagello in quell\'antro spregevole! Ricorda di cercare quei maledetti anche nei Saloni del Risveglio sotto Gjalerbron.', },
    {'Uccidi 10 Guardiani Senzamorte, 4 Orrori Temibili e 2 Wight Putridi. Poi, riferisci il tuo successo alla Madre Anziana Ankha nell\'Accampamento degli Zoccolo Artico.', },
  },
  [11269] = {
    'La scadenza si avvicina',
    {'L\'avanguardia dell\'Alleanza sarà qui fra pochi giorni. Il soldati si aspettano di trovare l\'attrezzatura invernale già pronta, ma non ho ancora finito di preparare i mantelli.|n|nStavo usando piume d\'Ippogrifo Maculato per le fodere, ma le mie scorte stanno per esaurirsi!|n|n$N, devi aiutarmi! Se i mantelli non saranno pronti in tempo, il Capitano Adams mi farà la pelle! Portami tutte le piume che riesci a trovare. Gli ippogrifi le perdono nel periodo della muta, mentre volano sopra le terre selvagge intorno al Fortilizio.', },
    {'Gil Grisert ti ha chiesto di portargli 10 Piume di Ippogrifo Maculato.', },
  },
  [11270] = {
    'La guerra è un inferno',
    {'Stiamo lentamente finendo i rimasugli della Flotta del Nord di Roccavento su questa costa. I cadaveri a ovest testimoniano la brutalità dello scontro.|n|nTutto ciò non urta il mio raffinato senso estetico, ma costituisce un pericolo per le nostre vite.|n|nNelle terre del Re dei Lich, i morti sono un\'arma che può essere usata contro di noi in qualsiasi momento. Prendi questa torcia e assicurati che ciò non accada.', },
    {'Il Gran Esecutore Anselm all\'Attracco della Vendetta ti ha chiesto di prendere la Torcia Bruciante e di usarla per bruciare 10 tra Cadaveri dell\'Alleanza e Cadaveri di Reietti a ovest della città.', },
  },
  [11271] = {
    'Preparativi affrettati',
    {'Le piume di Ippogrifo Maculato sono molto apprezzate dal mio popolo e vengono usate per tutto, dalle frecce agli abiti cerimoniali. Ci stiamo preparando ad abbandonare l\'accampamento, quindi per questa stagione è l\'ultima occasione per raccoglierle.|n|nGrazie al tuo aiuto, ne avrò a sufficienza per fare in modo che ognuno riceva l\'equipaggiamento necessario ad affrontare la lunga marcia sulle colline. Lassù le condizioni peggiorano molto rapidamente e le tempeste si abbattono senza preavviso.|n|nPuoi trovare le piume sparse al suolo un po\' dappertutto, nella zona che circonda l\'accampamento.', },
    {'Ahota Gelo Bianco all\'Accampamento degli Zoccolo Artico ti ha chiesto di portargli 10 Piume di Ippogrifo Maculato.', },
  },
  [11272] = {
    'Un conto in sospeso',
    nil,
    nil,
  },
  [11273] = {
    'La lega degli Umani',
    {'Eravamo sul punto di fare una scoperta archeologica rivoluzionaria, quando quei mostri ci hanno attaccati! Purtroppo, solo io sono riuscito a tornare a Valguardia. Non so se il resto della mia squadra sia viva o morta, ma bisogna assolutamente recuperare i manufatti che abbiamo scoperto durante gli scavi!|n|nSe ti stai dirigendo a Cranio del Drago, cercheresti la mia squadra? Se c\'è anche solo una piccolissima speranza di recuperare le informazioni, dobbiamo perseguirla!|n|nInizia cercando Pulroy: è stato l\'ultimo che ho visto, prima di fuggire.', },
    {'Cerca Pulroy a Cranio del Drago.', },
  },
  [11274] = {
    'Probabilmente Zedd è morto',
    {'A chiunque trovi questo diario...|n|nQuesti mostri assetati di sangue si sono stabiliti fra le rovine di Cranio del Drago. Cosa vogliano, o perché si trovino qui, rimane un mistero. In ogni caso, i manufatti non saranno mai al sicuro con queste bestie nei dintorni.|n|nMentre ci nascondevamo, io e Zedd abbiamo fatto una scoperta: un Cifrario per decodificare le Tavolette! Sfortunatamente, ieri notte sul tardi ci siamo divisi. Il Cifrario lo ha lui, invece Glorenfeld e Daegarn hanno le Tavolette. Non so dove si trovino.|n|nCercate Zedd.|n|nPulroy', },
    {'Cerca Zedd a Cranio del Drago.', },
  },
  [11275] = {
    'La creazione del Corno',
    {'Il mio popolo dà la caccia agli Yeti giganti di queste colline da generazioni. Quest\'anno sarà la prima volta che parteciperò anch\'io... e probabilmente anche l\'ultima, prima di abbandonare questo luogo per sempre.|n|nPer prepararmi alla caccia, devo costruirmi un corno da caccia dal migliore che riuscirai a procurarmi dai Montoni Selvatici che vagano nelle zone innevate vicino al nostro accampamento. Anche se può sembrare strano, secondo gli anziani il suo suono imita il richiamo della femmina Yeti.|n|n$N, portami le migliori Corna di Montone Selvatico che riesci a trovare e inizierò a lavorare sul migliore.', },
    {'Nokoma Scruta Neve all\'Accampamento degli Zoccolo Artico ti ha chiesto di portarle 6 Corna di Montone Intatte.', },
  },
  [11276] = {
    'Due piccoli Nani...',
    {'<Addosso a Zedd non trovi il Cifrario. Dopo aver esaminato accuratamente la zona, scopri una scritta per terra:>|n|n"Glor e Dae nelle Catacombe. Hanno Cifrario e Tavolette".|n|n<Dovresti dirigerti nelle Catacombe a nord per cercare Glorenfeld e Daegarn. Il ponte che attraversa la Fossa dei Worg ti condurrà alla galleria che scende nelle Catacombe.>', },
    {'Cerca Glorenfeld nelle Catacombe di Utgarde.', },
  },
  [11277] = {
    'Le profondità della depravazione',
    {'Hanno rinchiuso Daegarn in una gabbia vicino alla grande arena. Da quel che ho scoperto, gli Scorticadraghi costringono i prigionieri a combattere contro i loro gladiatori più forti. Chi perde, viene sbattuto nei sotterranei ed è trasformato in Ghoul dai negromanti del Flagello! Che cosa orribile!|n|nMa dobbiamo occuparci di una cosa alla volta! Le Tavolette sono sparse per tutta la caverna: recuperiamole, prima che ti venga in mente di lanciarti subito al salvataggio.', },
    {'Glorenfeld nelle Catacombe di Utgarde ti ha chiesto di recuperare 10 Tavolette di Cranio del Drago.', },
  },
  [11278] = {
    'Ritorno a Valguardia',
    {'È un peccato che abbiamo perduto due fra i nostri Nani migliori per recuperare queste reliquie. Si sono sacrificati per proteggere i segreti in esse contenuti.|n|n<Glorenfeld avvolge Cifrario e Tavolette in un panno cencioso.>|n|nPortali a Valguardia: McSorf saprà cosa farne.|n|nIo? Me la caverò, vedrai. In fondo, sono arrivato fin qui tutto intero!', },
    {'Porta il Pacchetto di Glorenfeld a Beltrand McSorf nel Porto di Valguardia.', },
  },
  [11279] = {
    'Uova verdi e draghetti',
    {'La nuova Piaga su cui stiamo lavorando è fantastica e dobbiamo ampliare la sperimentazione.|n|nChe ne dici di provarla sui Proto-Draghetti?|n|nPensa alle opportunità: potremmo infettare non solo gli umanoidi, ma anche altre creature!|n|nHo messo da parte un contenitore della Piaga per il luogo e il momento giusto e tu mi sembri la persona giusta.|n|nIrrora le uova di Selvardente a nord-ovest, poi portami i campioni di carne dei Proto-Draghetti Appestati appena nati.', },
    {'Falciaspettri l\'Araldo della Piaga ti ha chiesto di portargli 10 Campioni di Carne di Proto-Draghetti Appestati a Nuova Agamand.', },
  },
  [11280] = {
    'Gastrite draconica',
    {'Un momento, ho un\'idea! Forse i draghetti non sono morti perché abbiamo irrorato la parte esterna delle uova!|n|n$N, dobbiamo far penetrare la Piaga all\'interno!|n|nMa certo! Ecco un po\' di carne infetta: portala a Selvardente e falla mangiare ai draghetti!|n|nNo, stiamo pensando troppo in piccolo! Attiriamo a terra uno dei Proto-Drachi che volano qua sopra e facciamogli mangiare la carne.|n|nSì!|n|nResta nelle vicinanze e osserva ciò che accade. Potrebbe attaccarti, ma è il prezzo da pagare per il progresso.', },
    {'Falciaspettri l\'Araldo della Piaga a Nuova Agamand ti ha chiesto di usare la Carne Infetta di Tillinghast per attirare a terra un Proto-Draco e osservare la sua reazione dopo che l\'ha mangiata.', },
  },
  [11281] = {
    'Imitando il richiamo della natura',
    {'Il corno è quasi pronto ma, prima di procedere con le incisioni tradizionali, voglio assicurarmi che funzioni. Ahota mi ha detto che prova i suoi corni ai piedi della Cascata Ghiacciata a nord-est dell\'avamposto. Inoltre, sostiene che i nostri cacciatori abbiano sfruttato l\'acustica di quel luogo ghiacciato per generazioni. Non vedo l\'ora di saperne di più!|n|nMi aiuteresti a provare il corno? Sta\' in guardia: se ho fatto tutto come si deve, potresti addirittura attirare uno Yeti! Dopo averlo provato, riportarmi il corno.', },
    {'Prova il Corno Lavorato, poi riportalo a Nokoma Scruta Neve nell\'Accampamento degli Zoccolo Artico e riferiscile i risultati.', },
  },
  [11282] = {
    'La lezione del terrore',
    {'Quando hai combattuto tanto, come Gorth, impari che per dare bella lezione a nemico lo devi terrorizzare a morte!|n|nMa quei Vrykul non hanno paura di niente. Ne uccidi uno e ne arriva un altro, che strilla più forte e ha arma più grande.|n|nUnica cosa che fa paura ai Vrykul è quando uccidi il più grosso e cattivo fra loro.|n|nAttacca Geloskorn lungo la barricata, finché non si fanno vivi eroi di Vrykul! Falli secchi e pianta stendardo di Regina su loro cadaveri. Vrykul devono imparare ad avere paura!', },
    {'Gorth ti ha chiesto di uccidere Ulf lo Spargisangue, Oric il Bieco, Gunnar Thorvardsson e di piantare lo Stendardo dei Reietti nei loro cadaveri. Continua a uccidere i Vrykul lungo la barricata dei Reietti, finché non appaiono i tre eroi.', },
  },
  [11283] = {
    'La conta dei morti di Baleheim',
    {'Vrykul continuano ad arrivare da città a ovest!|n|nGorth ha idea. Entra in città e uccidi Geloskorn lì. Così la smetteranno di venire qui!', },
    {'Il Sergente Gorth ti ha chiesto di uccidere 16 Vrykul Geloskorn dentro Baleheim.', },
  },
  [11284] = {
    'Lo Yeti della porta accanto',
    {'Le guardie non vogliono aiutarmi, e tu? Sono il caposquadra della miniera dall\'altra parte del ponte. I miei uomini estraggono i minerali per le armi con cui la nostra Forza di Spedizione si apre una strada verso i Colli Bradi.|n|nUno Yeti enorme ha invaso la miniera, ostruendo la galleria che dobbiamo allargare! Abbiamo provato a scacciarlo con le urla e il fumo, ma non ha funzionato.|n|nGli porteresti della carne di Montone Gelocorno che vive nelle zone innevate intorno alla città? Forse così riesci a svegliarlo! Ti prego, siamo disperati!', },
    {'Il Caposquadra Colbey al Fortilizio di Wildervar ti ha chiesto di sconfiggere Cornorotto.', },
  },
  [11285] = {
    'Baleheim deve bruciare!',
    {'Uccidere Geloskorn forse non basta. Forse dobbiamo bruciare anche loro case! Ah... e ponti. Insomma, per essere sicuri dobbiamo bruciare tutta città!|n|nPrendi questa torcia. Vai a Baleheim, a ovest, e brucia TUTTO! Così imparano.', },
    {'Il Sergente Gorth ti ha chiesto di andare a Baleheim e usare la sua torcia per bruciare l\'Alloggio dei Geloskorn, la Torre di Guardia dei Geloskorn, il Ponte dei Geloskorn e la Caserma dei Geloskorn.', },
  },
  [11286] = {
    'I Manufatti della Chiusa d\'Acciaio',
    {'Sono qui per un altro motivo: un mio vecchio amico mi ha chiamato in sogno. Ma ora che ho visto quelle piccole creature scavare grossi buchi nel terreno con le loro macchine, mi sento il sangue ribollire.|n|nDa quel che ho capito, quei Nani stanno dissotterrando dei manufatti che potrebbero essere importanti per il nostro passato.|n|nVa\' laggiù, recuperali e portameli. Non permettere ad alcun Nano di ostacolarti.', },
    {'Il Saggio Calca Nebbia ti ha chiesto di recuperare 10 Manufatti della Chiusa d\'Acciaio. Quando li avrai tutti, torna da lui alla Chiusa d\'Acciaio.', },
  },
  [11287] = {
    'Trova il Saggio Calca Nebbia',
    {'$C... Mio figlio, il Saggio Calca Nebbia, manca da parecchio tempo e inizio a temere per la sua sorte. Questa terra è crudele e letale.|n|nMi aveva parlato di aver avuto diverse visioni di un lupo, così è andato a cercarne l\'origine a ovest, insieme a un piccolo gruppo di staffettisti. Se non sbaglio, ha detto che il luogo si chiamava Chiusa d\'Acciaio.|n|nAndresti a cercarlo? Voglio assicurarmi che non gli sia accaduto niente di male.', },
    {'La Madre Anziana Ankha ti ha chiesto di controllare le condizioni del Saggio Calca Nebbia. Ritiene che si trovi all\'interno o nelle vicinanze della Chiusa d\'Acciaio.', },
  },
  [11288] = {
    'La Luce brillante',
    nil,
    {'Ares il Giurato nelle Catacombe di Utgarde ti ha chiesto di recuperare il Manufatto Sacro.|n|nQuesta è una missione a tempo.', },
  },
  [11289] = {
    'Guidato dall\'onore',
    {'<Ares sorride.>|n|nGloria alla Luce! Ce l\'hai... fatta!|n|n<Ares tossisce.>|n|nPrendi il Manufatto e portalo... a Valguardia. Ser Irulon Veralama attende il suo ritorno.|n|nCombatti con onore. Sempre... con onore.|n|n<Ares esala l\'ultimo respiro.>', },
    {'Porta il Manufatto Sacro a Ser Irulon Veralama a Valguardia.', },
  },
  [11290] = {
    'Piani di Battaglia degli Scorticadraghi',
    {'Non siamo riusciti a scoprire molto sul nascondiglio di Ingvar, ma sappiamo che Yanis si trova in una grotta vicino alla Fossa dei Worg a Cranio del Drago.|n|nSecondo le informazioni dei soldati che hai liberato, è lui che conserva i Piani di Battaglia degli Scorticadraghi.|n|nDevi tornare a Cranio del Drago e recuperarli. Uccidi tutti i Vrykul che tenteranno di fermarti, compreso Yanis!', },
    nil,
  },
  [11291] = {
    'Al Forte di Guardia dell\'Ovest!',
    nil,
    nil,
  },
  [11292] = {
    'La legge della giungla',
    {'Felice di conoscerti. Sono venuto fin qui dai Colli Bradi per fare affari con i tuoi alleati. Laggiù, la mia gente gestisce un grande avamposto: farai bene a visitarlo, quando ti dirigerai a nord.|n|nHo piazzato delle trappole nella foresta e nelle zone innevate qui intorno. Mi aiuteranno a rifornirmi di carne e pellicce, così avrò molto da scambiare con gli abitanti della città.|n|nSe mi aiuterai a recuperare le prede dalle trappole, ti darò una parte dei profitti. Ma fa\' attenzione: non sarai $Gl\'unico predatore:l\'unica predatrice;, là fuori.', },
    {'Il Mastro Bracconiere Jethan al Fortilizio di Wildervar ti ha chiesto di portargli 8 Prede Intrappolate.', },
  },
  [11293] = {
    'Urla per i Maltorzo!',
    nil,
    {'Spargi la voce sulla Festa della Birra presso le bandiere fuori dalla Banca, nella Guardia Militare, nel Salone degli Esploratori e nella Guardia Mistica.', },
  },
  [11294] = {
    'Urla per i Birratuono!',
    nil,
    {'Spargi la voce sulla Festa della Birra presso le bandiere fuori dalla Banca, nella Guardia Militare, nel Salone degli Esploratori e nella Guardia Mistica.', },
  },
  [11295] = {
    'L\'offensiva ha inizio',
    {'Nessuno sa molto sui Vrykul. Sono secoli che non rileviamo segni d\'attività nelle loro terre. Eppure ecco che spuntano fuori appena iniziamo a muoverci contro Arthas.|n|nSecondo la mappa che hai recuperato, è evidente che dovremo sconfiggerli se vogliamo avanzare all\'interno di Nordania.|n|nLa barricata al di là dell\'ascensore è presidiata da uno dei miei migliori Sergenti, l\'Abominio Gorth. Aiutalo a sferrare un attacco preventivo contro Baleheim. Se i Vrykul attaccheranno, sarà sicuramente da lì.', },
    {'Parla con il Sergente Gorth alla barricata vicino all\'ascensore ovest nell\'Attracco della Vendetta del Fiordo Echeggiante.', },
  },
  [11296] = {
    'Gli Ostaggi del Bosco di Legnotorvo',
    {'Qualcosa agita le creature di questo luogo, probabilmente i morti viventi conosciuti come il Flagello.|n|nMentre scortavamo qui il Saggio, abbiamo perso molti cacciatori a causa delle Vedove Cupe, enormi ragni letali che abitano il Bosco di Legnotorvo a nord.|n|nIo devo restare qui per proteggere le poche unità che ci rimangono. Tu andresti a controllare se i miei staffettisti, intrappolati nei bozzoli delle Vedove Nere, sono ancora vivi?|n|nLo farai, $Gstraniero:straniera;?', },
    {'Lo Staffettista Nuvola Bianca ti ha chiesto di liberare 7 Staffettisti Zoccolo Artico. Poi, torna da lui alla Chiusa d\'Acciaio.', },
  },
  [11297] = {
    'Tenere d\'occhio gli Intrusi',
    {'Nemmeno la terra può trattenere la marea di morti che arrivano a ondate. I cadaveri camminano sulla regione, spargendo la loro putrefazione con velocità preoccupante.|n|nUna piccola spedizione si è avventurata sulle scogliere occidentali e si è fermata vicino alla Gola dei Sussurri. $N, va\' a dare un\'occhiata di persona. Cerca di scoprire il loro scopo e se sia possibile dissuaderli dall\'avvelenare le nostre terre. Recati a sud-ovest dall\'Avamposto, verso le scogliere che sovrastano la spiaggia occidentale. Il loro accampamento si trova a ovest degli scavi della Chiusa d\'Acciaio.', },
    {'Parla con lo Speziale Malthus all\'Accampamento dello Speziale.', },
  },
  [11298] = {
    'Cosa c\'è in quella birra?',
    {'A sud-est c\'è una zona chiamata Gola dei Sussurri, invasa da membri della Lega degli Esploratori impazziti! Hanno attaccato la nostra carovana e depredato i gruppi di rifornimento.|n|nDevo sapere qual è la causa di questa follia! Sospetto che abbia a che vedere con ciò che hanno bevuto dai barili sparsi per tutta la Gola. Rubali dai Nani, mentre sono impegnati a scavare.', },
    {'Lo Speziale Malthus all\'Accampamento dello Speziale ti ha chiesto di portargli 5 Barili Nanici.', },
  },
  [11299] = {
    'L\'Arena del Giudizio',
    nil,
    nil,
  },
  [11300] = {
    'Una sonora sconfitta nell\'Arena',
    nil,
    nil,
  },
  [11301] = {
    'Cervelli! Cervelli! Cervelli!',
    {'Malthus ti ha coinvolto nelle sue ciance su boccali e Nani pazzi?|n|nNon metto in dubbio che siano fuori di testa, ma non credo che rubare la loro birra serva a qualcosa.|n|nCi servono i cervelli. Un sacco di cervelli! Solo così riusciremo a venire a capo di questo mistero in breve tempo... e forse troveremo anche un nuovo componente per la Piaga.|n|nPrendi questa sega, va\' a sud-est nella Gola dei Sussurri e uccidi qualche Nano. Usa la sega per estrarre i cervelli e portali qui.', },
    {'Lo Speziale Grick all\'Accampamento dello Speziale ti ha chiesto di portargli 12 Cervelli di Esploratore Impazzito.', },
  },
  [11302] = {
    'L\'enigmatica Ninfa del Gelo',
    {'La prima volta che abbiamo esplorato la zona in cerca di un posto ove erigere il Fortilizio, abbiamo incontrato delle creature ostili in due delle radure qui a nord. Oltrepassata la zona innevata a sud della città, le Driadi hanno iniziato a osservarci con interesse, ma senza attaccare.|n|nEravamo stanchi e fiaccati dalle avverse condizioni meteorologiche, quindi avrebbero potuto ucciderci facilmente. Eppure non l\'hanno fatto.|n|nForse potremmo aver trovato delle alleate inaspettate. Andresti alla Radura Gelata per metterti in contatto con loro?', },
    {'Parla con Lurielle nella Radura Gelata.', },
  },
  [11303] = {
    'L\'imboscata',
    {'Non c\'è dubbio: i Vrykul di Baleheim sono sconfitti. Eppure, il loro capo è ancora in città e non si arrende.|n|nGorth ha inviato Lydell e i suoi assassini a tendere un\'imboscata a nord-ovest. Parla con Lydell e scopri come stanare il Capo Tribù Vrykul. Poi uccidi il Capo Tribù. Uccidilo come si deve.', },
    {'Parla con Lydell all\'Imboscata di Lydell.', },
  },
  [11304] = {
    'Nuova Agamand',
    {'Temo che la nostra attrezzatura qui all\'Attracco della Vendetta non sia il massimo. Dopotutto, è un avamposto militare.|n|nPorta un campione di questo ceppo al Capo Araldo della Piaga Harris a Nuova Agamand. Segui la strada che supera Baleheim a sud, quindi dirigiti a ovest. La loro attrezzatura è migliore e lui saprà cosa fare.|n|nSbrigati, $N: i nemici sono più forti e numerosi di noi. Dobbiamo sviluppare un\'arma valida per annientarli!', },
    {'Porta il Ceppo di Lysander al Capo Araldo della Piaga Harris a Nuova Agamand nel Fiordo Echeggiante occidentale.', },
  },
  [11305] = {
    'Una formula su misura',
    {'Stiamo irrorando il villaggio Vrykul di Halgrind da settimane, ma quelli non vogliono morire.|n|nAmmettiamolo, $N: finora la nostra Piaga è stata provata su Umani, Nani, cani, bestiame... un po\' con tutti, insomma. Ogni volta che i ceppi si adattavano agli organismi ospiti, nuove impurità si aggiungevano alla formula. Ciò che ci serve è un ceppo creato apposta per la biologia dei Vrykul.|n|nIl Capo Tribù di Halgrind è fuggito dalla città dopo che l\'abbiamo conquistata. Lo troverai a ovest. È un Patriarca del Clan Scorticadraghi, quindi il suo sangue è esattamente quello che cerchiamo.', },
    {'Ottieni il Sangue di Patriarca degli Scorticadraghi da Thorvald nell\'Accampamento di Thorvald e consegnalo al Capo Araldo della Piaga Harris a Nuova Agamand.', },
  },
  [11306] = {
    'Riscaldare e mescolare',
    {'$N, finora te la sei cavata benissimo. Vorrei insegnarti alcune fra le mie tecniche più avanzate, così potrai capire meglio come funziona la Piaga.|n|nPrendi questa bottiglia e riempila con il sangue nel calderone alla mia sinistra. Mescolalo ai campioni di Piaga alla mia destra, finché non raggiungerai un equilibrio ottimale.', },
    {'Riempi la Bottiglia Vuota dello Speziale al Calderone del Sangue Vrykul. Poi mescola il contenuto della Bottiglia del Sangue Vrykul con i Campioni di Piaga di Harris lì vicino, finché non avrai ottenuto un Preparato Bilanciato.|n|nAlla fine, torna dal Capo Araldo della Piaga Harris.', },
  },
  [11307] = {
    'Test sul campo',
    {'Ora che abbiamo un ceppo della Piaga adattato per i Vrykul, dobbiamo provarlo sui nostri esemplari a Halgrind. Se andrà tutto come previsto, la Piaga li divorerà dall\'interno e si disintegreranno all\'istante!|n|nHalgrind si trova a nord. I nostri Portatori della Piaga stanno diffondendo lì il ceppo precedente, quindi non ti sarà difficile trovarlo.', },
    {'Avventurati a Halgrind e usa lo Spargitore di Piaga con 10 Vrykul Scorticadraghi Appestati. Poi, torna dal Capo Araldo della Piaga Harris per riferirgli i risultati.', },
  },
  [11308] = {
    'L\'ora delle pulizie',
    {'Sono una persona dotata di senso pratico, quindi stabilisco che la nostra ricerca è stata un successo. Dopotutto, quale esercito non può essere fermato mettendo le sue armate una contro l\'altra?|n|nQuanto prima, riferirò della nostra conquista all\'Attracco della Vendetta. Ma prima devi ripulire il sito dai nostri esperimenti.|n|nCerca Jenny "Seghetto" e chiedile di crearti un Abominio personalizzato. Uno che abbia una personalità... esplosiva. Non so se mi sono spiegato.', },
    {'Parla con Jenny "Seghetto" a Nuova Agamand.', },
  },
  [11309] = {
    'Recuperando i pezzi',
    {'E così Harris vuole una bella demolizione, eh? Sì, posso aiutarti.|n|nPerò devi portarmi dei pezzi. Non posso usare i miei componenti migliori per qualcosa che deve esplodere.|n|nPrima di tutto mi servono dei Legamenti di Zannapiatta... sono migliori di quelli umani.|n|nPoi avrò bisogno di mezzo chilo di carne. Il mio amico Anton, che fa su e giù per la strada a ovest, la vende a buon mercato,.', },
    {'Jenny "Seghetto" a Nuova Agamand ti ha chiesto di recuperare 6 Legamenti di Zannapiatta e Mezzo Chilo di Carne Fresca.', },
  },
  [11310] = {
    'Attenzione: necessita di montaggio',
    {'Bene, eccoti qui! Il nostro amico sarà un po\'... instabile. Quindi ti suggerisco di non assemblarlo prima di aver raggiunto Halgrind.|n|nQuando sarai lì, usa l\'Abominio per attirare quanti più Vrykul possibile, prima di farlo autodistruggere.|n|nPoi, torna qui con tutto ciò che ne rimane: i pezzi di corpo mi fanno sempre comodo!', },
    {'Usa il Kit d\'Assemblaggio per Abominio a Halgrind e attira i Vrykul Appestati con il tuo Abominio Decerebrato. Uccidine almeno 20, poi torna da Jenny "Seghetto" a Nuova Agamand.', },
  },
  [11311] = {
    'Sopprimere gli elementi',
    {'Se vuoi sopravvivere qui come noi, devi imparare ad affrontare le sfide degli elementi. Se non resterai sempre all\'erta, prenderanno la tua vita... come dimostra il proliferare di elementali in queste colline settentrionali.|n|nDobbiamo sfoltire il numero degli elementali un\'ultima volta prima di andarcene. Ci aiuterai, mentre procediamo con i preparativi?|n|nDevi uccidere tutti gli Elementali Scheggiafredda o i Cicloni Ululanti che incontri sulle colline innevate intorno all\'avamposto.', },
    {'Il Domavento Kagan all\'Accampamento degli Zoccolo Artico ti ha chiesto di uccidere 8 Elementali di Montagna. Puoi scegliere fra Cicloni Ululanti e Elementali Scheggiafredda.', },
  },
  [11312] = {
    'La Radura Gelata',
    {'Per generazioni, il mio popolo ha narrato storie di Ninfe del Gelo che saltellavano allegre nelle Radure nascoste delle terre selvagge. Da bambina, ignorando i divieti dei miei genitori, passavo molto tempo a cercarle... finché una volta non sono quasi morta di freddo.|n|nOggigiorno, non è più necessario passare al setaccio le foreste per trovarle. Per motivi che posso solo immaginare, hanno deciso di mostrarsi. È un cambiamento che non può essere ignorato. Avventurati a sud-est, verso la Radura Gelata, e cerca le Ninfe. Fa\' attenzione: lungo il cammino, dovrai passare per la Radura Contorta.', },
    {'Parla con Lurielle nella Radura Gelata.', },
  },
  [11313] = {
    'Gli spiriti del ghiaccio',
    {'Un tempo, gli Elementali del Ghiaccio che circondano la nostra Radura erano nostri compagni. Poi, una forza volatile e distruttiva ha spazzato la regione, facendoli rivoltare contro di noi!|n|nQuesto è solo uno degli orrori che io e le mie sorelle abbiamo dovuto sopportare. Ci siamo rivelate a te, nella speranza che potessi aiutarci a combattere il decadimento che si è insinuato nella Radura e ha avvelenato le nostre sorelle!|n|nAbbiamo raccolto e conservato i Nuclei degli Elementali del Ghiaccio cosicché, un giorno, potremo riuscire a salvarli. Ci aiuterai?', },
    {'Lurielle nella Radura Gelata ti ha chiesto di portarle 15 Nuclei di Ghiaccio.', },
  },
  [11314] = {
    'Le sorelle cadute',
    {'A sud-ovest c\'era una Radura che somigliava molto a questa. Forze misteriose e magie esterne la stanno rimodellando: la Radura si è disgelata e le sorelle che vivevano lì sono impazzite a causa del cambiamento repentino.|n|nAbbiamo tentato di contattarle, ma ci hanno attaccate. Temo che ormai sia impossibile salvarle, ma non dobbiamo abbandonare la speranza.|n|nPrendi il mio Pendente, raggiungi la Radura Fremente a sud-ovest e usalo per tentare di liberare le mie sorelle dalla loro follia.', },
    {'Lurielle nella Radura Gelata ti ha chiesto di usare il suo Pendente su 7 Ninfe del Freddo.', },
  },
  [11315] = {
    'Viticci selvatici',
    {'Le sorelle che vivevano nella Radura Fremente a sud-ovest coltivavano dei meravigliosi letti di Edera Scarlatta. Purtroppo, la stessa forza che le ha fatte impazzire, ha trasformato la loro adorata edera.|n|nOra i viticci attaccano i piedi degli sprovveduti e sferzano chiunque si avvicini alla Radura. Prima di riconquistare la Radura, dobbiamo addomesticare e sradicare i viticci.|n|nEstirpa più edera possibile: ha già iniziato a crescere in modo incontrollato.', },
    {'Lurielle nella Radura Gelata ti ha chiesto di distruggere 8 Edere Scarlatte.', },
  },
  [11316] = {
    'Le creature della Radura Contorta',
    {'La Radura a ovest è stata trasformata in un luogo pericoloso, chiamato Radura Contorta. Bestie orribili si aggirano fra gli alberi, le pietre e i laghetti.|n|nNon so da dove provengano o quali orribili forze le animino, ma bisogna eliminarle!|n|nTemo che avveleneranno irrimediabilmente la Radura, se permetteremo loro di dominarla. Elimina le creature che hanno ucciso le nostre sorelle.', },
    {'Lurielle nella Radura Gelata ti ha chiesto di uccidere 10 Camminatori Vignaspina.', },
  },
  [11317] = {
    'La purificazione',
    {'Ci siamo avventurati nel Bosco di Legnotorvo a causa dei miei incubi su Ulfang, un mio vecchio amico Worg. Sta chiedendo aiuto e devi rispondere al suo appello.|n|nNon hai i mezzi per parlare con lui, o per camminare in mezzo agli altri Worg, ma io ho la soluzione.|n|nPrima, però, devi purificarti dai tumulti interiori.|n|nIn cima al Picco di Gelalama, a nord-est dell\'Accampamento degli Zoccolo Artico, c\'è un santuario. Esiste un solo sentiero per raggiungerlo, che parte dalle pendici occidentali della montagna.|n|nMedita lassù e poi torna da me.', },
    {'Il Saggio Calca Nebbia alla Chiusa d\'Acciaio ti ha consigliato di liberarti dal tuo tumulto interiore attraverso la meditazione presso il Santuario di Gelalama.', },
  },
  [11318] = {
    'Questa sì che è una Corsa dei Montoni... più o meno',
    {'Vuoi provare i Montoni da Corsa? Spero che la velocità non ti spaventi! Prima di lasciarti scorrazzare per il mondo, devi dimostrarmi di saper cavalcare queste belle creature.|n|nFacciamo così: ti presto delle redini da corsa e ti permetto di usare un montone. Tu dimostrami di saper cavalcare.|n|nConduci il montone al trotto, al piccolo galoppo e al galoppo per 8 secondi ciascuno. Se ti servono istruzioni, parla con Pol Ambraquieta, il mio apprendista.', },
    {'Hai 4 minuti per cavalcare il montone e devi mantenere ognuna delle 3 velocità per 8 secondi.', },
  },
  [11319] = {
    'I semi dei Protettori Animanera',
    {'La Radura a nord-ovest, quella che ora si chiama Radura Contorta, era la casa di alcuni Protettori. Insieme alle mie sorelle, si occupavano del mantenimento della Radura.|n|nQuando questa è cambiata, le mie sorelle sono morte, ma i Protettori sono sopravvissuti. Ora seminano la terra con spore velenose che fanno seccare la vegetazione.|n|nTi darò uno dei Nuclei degli Elementali del Ghiaccio. Ogni volta che distruggi una spora, usa il cristallo per congelarla e impedirle di rigenerarsi.', },
    {'Lurielle nella Radura Gelata ti ha chiesto di congelare 8 Spore.', },
  },
  [11320] = {
    nil,
    nil,
    {'[Log Descritpion ]', },
  },
  [11321] = {
    'Qualcuno ha detto "Souvenir?"',
    {'La Festa della Birra non è solo Montoni da Corsa, ma anche belle bevute! Appena hai un momento, porta questo buono a Belbi Cambiamarcia. Puoi trovarla sul retro dell\'Accampamento della Festa della Birra. Non preoccuparti se non riesci a vederla: lei ti vedrà di sicuro.|n|nComunque, portale questo buono e ti darà un Boccale della Festa della Birra in omaggio. Sarà più che felice di gestire tutte le operazioni della Festa della Birra.', },
    {'Consegna il Buono per il Boccale della Festa della Birra in Omaggio a Belbi Cambiamarcia nell\'Accampamento della Festa della Birra.', },
  },
  [11322] = {
    'La purificazione',
    {'Ultimamente, ho fatto degli incubi su un worg di nome Ulfang. Sta chiedendo aiuto e devi rispondere al suo appello.|n|nNon hai i mezzi per parlare con lui, o per camminare in mezzo agli altri Worg, ma io ho la soluzione.|n|nPrima, però, devi liberarti dai tumulti interiori attraverso la meditazione.|n|nIn cima al Picco di Gelalama, a nord-est, c\'è un Santuario. Esiste un solo sentiero per raggiungerlo, che parte dalle pendici occidentali della montagna.|n|nMedita lassù per liberare la tua mente e poi torna da me.', },
    {'La Guardiana Foglialuna alla Chiusa d\'Acciaio ti ha chiesto di liberarti dal tuo tumulto interiore attraverso la meditazione presso il Santuario di Gelalama.', },
  },
  [11323] = {
    'Nei panni del Worg',
    {'In sogno, ho appreso che Ulfang si trova in una grotta al confine innevato nordoccidentale del Bosco di Legnotorvo.|n|nCorre un grande pericolo!|n|nHo creato un travestimento magico, che ti farà apparire come un worg finché ti troverai all\'interno del Bosco di Legnotorvo. Non è molto potente e si basa sulla strana magia di quel bosco infestato. Ingannerà solo i worg, ma ti permetterà di avvicinarti a Ulfang.|n|n$C, trovalo, ti prego.', },
    nil,
  },
  [11324] = {
    'Il worg alfa',
    nil,
    {'Ulfang ti ha chiesto di uccidere Garwal. Poi, restituisci il Camuffamento da Worg al Saggio Calca Nebbia nella Chiusa d\'Acciaio.', },
  },
  [11325] = {
    'Nei panni del Worg',
    {'In sogno, ho appreso che Ulfang si trova in una grotta al confine innevato nordoccidentale del Bosco di Legnotorvo.|n|nCorre un grande pericolo!|n|nHo creato un travestimento magico, che ti farà apparire come un worg finché ti troverai all\'interno del Bosco di Legnotorvo. Non è molto potente e si basa sulla strana magia di quel bosco infestato. Ingannerà solo i worg, ma ti permetterà di avvicinarti a Ulfang.|n|n$C, trovalo, ti prego.', },
    nil,
  },
  [11326] = {
    'Il worg alfa',
    nil,
    {'Ulfang ti ha chiesto di uccidere Garwal. Poi, restituisci il Camuffamento da Worg alla Guardiana Foglialuna nella Chiusa d\'Acciaio.', },
  },
  [11327] = {
    'Missione: Recupero del Pacchetto',
    {'Maledizione, ci serve un po\' di quella roba... quella Piaga... qualunque cosa sia!|n|nLo so per certo!|n|nMentre distruggevi le taniche, ho visto i Vrykul che trascinavano uno Speziale di Nuova Agamand a Halgrind. Povero diavolo.|n|n$N, scommetto che quello speziale ha con sé quello stiamo cercando. Puoi andare a Halgrind e recuperare il suo Pacchetto?', },
    {'L\'Esploratore Knowles ti ha chiesto di recuperare il Pacchetto dello Speziale ad Halgrind. Poi, torna da lui nella Torre Lancia Rovente.', },
  },
  [11328] = {
    'Missione: Le informazioni dei Reietti',
    {'Allora... devi portare questa roba a Peppy Cioccarosa al Forte. Come alchimista è poco più che una dilettante... ma è anche l\'unica che abbiamo.|n|nUn avvertimento: a Peppy piace bere, quindi probabilmente la troverai in una taverna a "creare l\'atmosfera".|n|nSono sicuro che saprà cosa fare.', },
    {'L\'Esploratore Knowles ti ha chiesto di consegnare il Pacchetto dello Speziale a Peppy Cioccarosa nel Forte di Guardia dell\'Ovest.', },
  },
  [11329] = {
    'Proverò di tutto!',
    {'Non voglio vedere mai più un barile di pesce sotto sale finché vivo! Continuo a riempirli ma non finiscono mai!|n|nVorrei non aver usato tutta l\'esca che avevo comprato da Nat Pagle. Quella funzionava fin troppo bene, mentre ora sono fortunato se pesco un pesce all\'ora!|n|nHo saputo che i Barbi del Nord sono un\'ottima esca, ma chi sarebbe tanto pazzo da tuffarsi in un lago gelato e fendere le piante acquatiche per cercarli? Io no di sicuro. Ma forse... e dico forse... potrei convincerti a farlo al posto mio.', },
    {'Christopher Sloan al Fortilizio di Wildervar ti ha chiesto di portargli 5 Barbi del Nord.', },
  },
  [11330] = {
    'Assholutamente... funzionerà!',
    {'Et voilà, un vaccino ishtantaneo contro la piaga!|n|nUna cosha è certa: io non lo provo e shono shicura che nemmeno tu vuoi fare da cavia!|n|nAh, ho un\'idea!|n|nNelle celle shotto al Forte abbiamo un prigioniero Vrykul. Perché non prendi queshto bel cocktail che ho appena creato e lo fai bere a quel gigante... hic?', },
    {'Peppy Cioccarosa al Forte di Guardia dell\'Ovest ti ha suggerito di somministrare l\'Intruglio Speciale di Peppy al Prigioniero Vrykul Scorticadraghi per scoprirne gli effetti.', },
  },
  [11331] = {
    'Diglielo tu... Hic!',
    {'Ecco cosha faremo. Io non ci vado dal Capitano a riferirgli la cattiva notizia. Shono sholo un\'alchimista dilettante, non è il mio lavoro... e shono pure in pausha!|n|nPoi è un gran brontolone e tu lo conosci meglio di me!|n|nQuindi, shali in cima al Forte e diglielo tu. Shono shicura che la prenderà bene... hic.|n|n<Peppy ti volta le spalle e torna a bere.>', },
    {'Peppy Cioccarosa ti ha raggirato e ora devi riferire al Capitano Adams le cattive notizie sulla Piaga dei Reietti. Va\' da lui al Forte di Guardia dell\'Ovest.', },
  },
  [11332] = {
    'Missione: Infetta questo!',
    {'L\'Ordine Reale degli Speziali sta perfezionando una nuova Piaga, che ci scioglierà all\'istante?!|n|nNon se posso impedirlo!|n|nVa\' nel cortile e parla con Greer Battiori. Ti darà un grifone e alcune bombe. Devi bombardare i Carri della Piaga a Nuova Agamand!', },
    {'Il Capitano Adams ti ha ordinato di colpire con le bombe 5 Carri della Piaga a Nuova Agamand. Non tornare dal lui al Forte di Guardia dell\'Ovest finché non avrai compiuto la missione.', },
  },
  [11333] = {
    'Nel mondo degli spiriti',
    {'La Lega degli Esploratori scopre i dettagli più minuti del passato grazie ai reperti archeologici... Il Viceammiraglio estorce con la forza informazioni sul presente... Ma la verità la sanno solo gli Spiriti!|n|nUsando i reagenti giusti, posso vedere nel loro mondo: è lì che risiedono il passato, il presente e il futuro di Nordania!|n|nSe vuoi saperne di più, portami la mia Borsa dei Reagenti. L\'ho persa su una nave che ora si trova sul fondo della Baia delle Daghe a est.', },
    {'Thoralius il Saggio a Valguardia ti ha chiesto di cercare la sua Borsa dei Reagenti.', },
  },
  [11335] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'$GRagazzo:Ragazza;, la maggiore difficoltà di combattere su più fronti è il rischio di disperdere troppo le nostre forze, rischiando di trovarci poi senza!|n|nÈ vitale decidere giornalmente il posizionamento delle truppe più importanti. Oggi c\'è bisogno di rinforzi nel Bacino d\'Arathi.|n|nTorna da me con la notizia della nostra vittoria, $N. Non possiamo permettere che quelle risorse preziose finiscano nelle mani dell\'Orda. Ci appartengono di diritto!', },
    nil,
  },
  [11336] = {
    'Chiamata alle armi: Valle d\'Alterac',
    {'$GRagazzo:Ragazza;, la maggiore difficoltà di combattere su più fronti è il rischio di disperdere troppo le nostre forze, rischiando di trovarci poi senza!|n|nÈ vitale decidere giornalmente il posizionamento delle truppe più importanti. Oggi c\'è bisogno di rinforzi nella Valle d\'Alterac.|n|nVai ad aiutare il Clan Piccatonante, $N. Dobbiamo far pagare al Clan Lupi Bianchi le violenze commesse sui nostri fratelli!', },
    nil,
  },
  [11337] = {
    'Chiamata alle armi: Occhio del Ciclone',
    {'La battaglia contro l\'Orda prosegue senza quartiere, $N. Le dispute territoriali e i vecchi rancori bastano per far scoppiare la guerra anche nelle Terre Esterne.|n|nVai nell\'Occhio del Ciclone e combatti per far prevalere anche qui l\'Alleanza.', },
    nil,
  },
  [11338] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'Le Sentinelle Alargentea combattono per proteggere la foresta della Forra dei Cantaguerra. Le aiutiamo non perché siamo degli ecologisti, ma perché la foresta è una difesa naturale per il territorio dell\'Alleanza.|n|nMai come oggi hanno bisogno del nostro aiuto. Dobbiamo inviare subito rinforzi se non vogliamo che Valtetra venga annessa alle Savane!', },
    nil,
  },
  [11339] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'Il Bacino d\'Arathi sta per essere conquistato dall\'Alleanza. Dobbiamo inviare immediatamente rinforzi o tutti i nostri sforzi saranno stati vani.|n|nNon indugiare, $C, e vai nel Bacino d\'Arathi per affrontare il nemico. Vittoria all\'Orda!', },
    nil,
  },
  [11340] = {
    'Chiamata alle armi: Valle d\'Alterac',
    {'Siamo quasi riusciti a cacciare gli invasori Piccatonante dalla Valle d\'Alterac e stiamo inviando rinforzi per aiutare il Clan Lupi Bianchi.|n|nUna vittoria campale ci aiuterebbe a ottenere le risorse di cui abbiamo bisogno per distruggere l\'Alleanza su tutti gli altri fronti.|n|nVai, $N, e fatti onore rispondendo alla chiamata dei coraggiosi Guerrieri dei Lupi Bianchi.', },
    nil,
  },
  [11341] = {
    'Chiamata alle armi: Occhio del Ciclone',
    {'Affronteremo e schiacceremo i nemici ovunque li incontreremo. Sia Azeroth o le Terre Esterne, non fa alcuna differenza.|n|nNon possiamo permettere all\'Alleanza di sopravanzarci nell\'Occhio del Ciclone. Vai ad affrontarli oggi, perché domani potrebbe essere troppo tardi!', },
    nil,
  },
  [11342] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'L\'Alleanza è un nemico infido, $N. Affermano di difendere le foreste di Valtetra, ma stanno solo giustificando gli attacchi ai nostri territori nelle Savane.|n|nOggi abbiamo la possibilità di scacciarli dalle nostre terre una volta per tutte. Vai alla Forra dei Cantaguerra e riprendi ciò che è nostro di diritto!', },
    nil,
  },
  [11343] = {
    'L\'eco di Ymiron',
    {'Il mondo degli Spiriti è caduto sotto il dominio del Re dei Lich. Creature terrificanti, fatte della stessa materia degli incubi, fanno la guardia al regno degli elementi. Sento che quelle Val\'kyr proteggono un terribile segreto.|n|n$N, io sono troppo vecchio e debole per sopravvivere a un altro viaggio: dovrai andare tu al posto mio.|n|nPorta questo Incensiere a Cranio del Drago e usalo per entrare nel mondo degli Spiriti. Cerca la grande dimora a nord-est! Evita le Val\'kir a ogni costo, altrimenti rimarrai bloccato nel loro mondo.', },
    {'Thoralius il Saggio ti ha chiesto di cercare informazioni sui segreti di Cranio del Drago mentre sei nel mondo degli Spiriti.', },
  },
  [11344] = {
    'Il tormento di Nifflevar',
    {'Da quel che sappiamo dei Vrykul, sono apparsi a Nordania solo di recente. Ma allora perché sono nelle nostre visioni risalenti a 15.000 anni fa? Se avessero già abitato Nordania in precedenza, lo sapremmo sicuramente.|n|nDevi andare a Nifflevar. Mettiti in viaggio verso nord-est, attraversa Cranio del Drago e prendi il sentiero che attraversa la diga. Nifflevar si trova sul promontorio del Fiordo.|n|nQuando sarai lì, usa l\'Incensiere e cerca degli indizi.', },
    {'Thoralius il Saggio ti ha chiesto di cercare informazioni sui segreti di Nifflevar mentre ti trovi nel mondo degli Spiriti.', },
  },
  [11346] = {
    'Il Libro delle Rune',
    {'La vasta area rocciosa a sud-est, chiamata Percorso dei Giganti, è occupata dai Nani del Ferro. Gli esploratori ci hanno riferito di averli visti evocare dei Giganti della Pietra dal suolo per poi incidervi sopra delle rune.|n|nNon so che intenzioni abbiano, ma sospetto che vogliano trasformare i giganti in macchine da guerra. Gli Invocatori della Pietra del Ferro Runico e i Vincolatori del Ferro Runico trasportano pesanti tomi, che devono contenere le rune incise sui giganti.|n|n$N, recupera i pezzi di questo libro, assemblali e portali da me.', },
    {'Il Prospettore Belvar al Fortilizio di Wildervar ti ha chiesto di portargli il Libro delle Rune.', },
  },
  [11348] = {
    'La Runa del Comando',
    {'Senti il potere sprigionato dalle rune che ho inciso su questa tavoletta? Sono una versione ridotta di quelle usate dai Nani del Ferro. Le utilizzeremo per porre fine alle loro operazioni.|n|nPorta la Runa del Comando sul Percorso dei Giganti e usala su un Gigante della Pietra che non sia stato ancora alterato dai Nani.|n|nDovrebbe obbedirti, ma ho impostato le rune affinché l\'effetto sia solo temporaneo. Il gigante sarà un prezioso alleato nella battaglia contro il Vincolatore Murdis, capo dei Nani del Ferro sul Percorso dei Giganti.', },
    {'Il Prospettore Belvar al Fortilizio di Wildervar ti ha chiesto di provare la Runa del Comando su un Gigante della Pietra e di sconfiggere il Vincolatore Murdis.', },
  },
  [11349] = {
    'Padroneggiare le rune',
    {'Ho un nuovo set di picconi, martelli e scalpelli, ma non è adatto per incidere le rune. Gli strumenti dei Nani del Ferro sono infusi di magia nel momento in cui sono forgiati.|n|nQuando vengono utilizzati per incidere le rune, i simboli non sono più delle semplici parole, ma possiedono il potere di legare, costringere e corrompere.|n|nCredo di sapere come funzionino, ma non posso esserne sicuro senza quegli strumenti. Cerca un kit simile al mio sotto le tende nell\'accampamento dei Nani del Ferro, vicino al Percorso dei Giganti, e portamelo.', },
    {'Porta un set di Strumenti d\'Iscrizione Runica al Prospettore Belvar nel Fortilizio di Wildervar.', },
  },
  [11350] = {
    'Il Libro delle Rune',
    {'Il Capo Tribù Totem Sabbioso mi ha inviato a esplorare il Percorso dei Giganti, un ampio altopiano roccioso a sud-est, oltre la Radura Gelata.|n|nQuella zona è occupata dai Nani del Ferro, che alterano i giganti appena questi emergono dalla terra.|n|nGli Invocatori della Pietra del Ferro Runico e i Vincolatori del Ferro Runico trasportano pesanti tomi, che devono contenere le rune che stanno incidendo sui giganti.|n|n$N, recupera le parti di questo libro, assemblale e portale da me: è l\'unico modo per scoprire i piani dei Nani.', },
    {'Lo Staffettista Pembe all\'Accampamento degli Zoccolo Artico ti ha chiesto di portargli il Libro delle Rune.', },
  },
  [11351] = {
    'Padroneggiare le rune',
    {'Credo di aver capito cosa stanno facendo i Nani del Ferro. I loro strumenti sono infusi di magia nel momento in cui sono forgiati.|n|nQuando vengono utilizzati per incidere le rune, i simboli non sono più delle semplici parole, ma possiedono il potere di legare, costringere e corrompere.|n|nSe avessi un kit di quegli strumenti, potrei imitare le rune del libro. Ho trovato una cassetta in una tenda nel Percorso dei Giganti, ma era vuota. Cercane una simile e portami un kit di strumenti.', },
    {'Porta un set di Strumenti d\'Iscrizione Runica allo Staffettista Pembe nell\'Accampamento degli Zoccolo Artico.', },
  },
  [11352] = {
    'La Runa del Comando',
    {'Senti il potere sprigionato dalle rune che ho inciso su questa tavoletta? Sono una versione ridotta di quelle usate dai Nani del Ferro. Le utilizzeremo per porre fine alle loro operazioni.|n|nPorta la Runa del Comando sul Percorso dei Giganti e usala su un Gigante della Pietra che non sia stato ancora alterato dai Nani.|n|nDovrebbe obbedirti, ma ho impostato le rune affinché l\'effetto sia solo temporaneo. Il gigante sarà un prezioso alleato nella battaglia contro il Vincolatore Murdis, capo dei Nani del Ferro sul Percorso dei Giganti.', },
    {'Lo Staffettista Pembe all\'Accampamento degli Zoccolo Artico ti ha chiesto di provare la Runa del Comando e sconfiggere il Vincolatore Murdis.', },
  },
  [11354] = {
    'Ricercato: Frustino di Nazan',
    {'Oggi è arrivato un acquirente interessato a un oggetto custodito dalla cavalcatura dell\'alfiere di Illidan. Sto parlando naturalmente di Vazruden l\'Alfiere e del suo drago Nazan.|n|nSe vuoi la somma che offrirò a chi lo recupererà trova quei due, in volo sopra i Bastioni del Fuoco Infernale, e poi torna con il frustino del drago.|n|nLe mie fonti mi assicurano che l\'oggetto in questione è custodito personalmente dal drago. Si dice che Nazan si rifiuti di farsi colpire da Vazruden con esso.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Frustino di Nazan. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11355] = {
    'La marcia dei giganti',
    {'Sul Percorso dei Giganti a est, i Giganti della Pietra Runica hanno iniziato a migrare verso nord attraverso il Picco di Gelalama. Non so quale sia la loro destinazione.|n|nLe rune luminose, incise nei corpi di pietra dei giganti, li guidano nel loro cammino.|n|nUsa questo piccone per disattivare le rune sui cadaveri dei giganti e torna a riferirmi ciò che avrai scoperto.', },
    {'Il Ricercatore Aderan al Fortilizio di Wildervar ti ha chiesto di usare il Piccone Cercarune sui cadaveri di 4 Giganti della Pietra Runica.', },
  },
  [11356] = {
    'Matrona degli Orfani in costume',
    {'Durante la Veglia delle Ombre, gli orfanotrofi umani hanno organizzato delle gite per far visitare agli orfani i villaggi di campagna dell\'Alleanza. Quei poveri bambini saranno felici di vedere $Gun vero:una vera; $C come te!|n|nPerché non fai loro visita? Li troverai a Borgodoro nella Foresta di Elwynn, a Kharanos nella regione di Dun Morogh e nel Presidio Azzurro a Brumazzurra. Parla con la guardiana degli orfani, una Matrona in costume, per farti presentare i bambini.', },
    {'Parla con una Matrona degli Orfani in Costume a Borgodoro, a Kharanos o nel Presidio Azzurro.', },
  },
  [11357] = {
    'Matrona degli Orfani Mascherata',
    {'Durante la Veglia delle Ombre, i piccoli Orchi orfani sono stati portati in gita in vari villaggi dell\'Orda. Le Matrone pensano che farebbe loro bene conoscere dei veri eroi!|n|nPerché non li vai a trovare? I racconti delle tue gesta valorose rafforzeranno sicuramente i loro spiriti! Recati a Tranciacolle nella regione di Durotar, a Brill nelle Radure di Tirisfal o a Piazza del Falco nei Boschi di Cantoeterno. Parla con la Matrona degli Orfani Mascherata per farti presentare i bambini.', },
    {'Parla con una Matrona degli Orfani Mascherata a Tranciacolle, Brill o a Piazza del Falco.', },
  },
  [11358] = {
    'Come magnetite',
    {'Se riuscissimo a identificare cosa sta attirando i giganti a nord-ovest, potremmo fermarli prima che arrivino a destinazione.|n|nSono riuscito a decifrare molte rune dai campioni che mi hai portato, ma sono quelle che non conosco a preoccuparmi di più. Quando ho visitato il Percorso dei Giganti, ho notato una grossa tavoletta spezzata che sporgeva dal terreno nel punto in cui la parte nordorientale di quella zona incontra le nevi ai piedi del Picco di Gelalama. Prendi questo campione, confronta le rune con la tavoletta e cerca di scoprire qualcosa.', },
    {'Il Ricercatore Aderan al Fortilizio di Wildervar ti ha chiesto di confrontare il Campione di Rune con la Tavoletta Spezzata.', },
  },
  [11359] = {
    'Distruggere Megalith',
    {'Il Vincolatore Murdis ha creato Megalith, il Gigante Runico più potente, per guidare gli altri in missione. Senza di lui, i suoi compagni sarebbero persi e confusi. Quando la Forza di Spedizione sarà arrivata, i nostri soldati potranno sconfiggere i giganti rimasti e scacciare i loro padroni Nani del Ferro dagli Accampamenti.|n|nEsplora le alture del Picco di Gelalama, a nord del Percorso dei Giganti: quando avrai trovato Megalith, attaccalo e sconfiggilo!', },
    {'Uccidi Megalith e torna dal Ricercatore Aderan al Fortilizio di Wildervar.', },
  },
  [11360] = {
    'Addestramento da pompiere',
    {'Gli eroi di Borgodoro sono sempre pronti a formare una squadra di pompieri, nonostante la presenza del Cavaliere Senza Testa. Vuoi aiutarci?|n|nA nord di qui, le guardie hanno allestito un campo per fare pratica con gli incendi. Vacci e spegni dei roghi a secchiate. Puoi riempire il secchio con l\'acqua del barile.|n|nArrivederci, $N. Quando hai terminato il tuo addestramento da pompiere, torna a farci visita.', },
    nil,
  },
  [11361] = {
    'Addestramento con il fuoco',
    {'Fuori dal villaggio, i Grunt stanno allestendo un\'area per addestrarsi a spegnere gli incendi. In questi giorni non è raro che gli edifici di Tranciacolle prendano fuoco. Dovresti dare una mano e addestrarti per diventare $Gun pompiere:una pompiera;!|n|nDirigiti a ovest di Tranciacolle, quindi gira a destra appena hai superato le mura del villaggio. Trova l\'area di addestramento, afferra i secchi e getta acqua sui roghi accesi per fare pratica.', },
    nil,
  },
  [11362] = {
    'Ricercato: Bastone Piumato di Keli\'dan',
    {'I gusti sono gusti e su di essi non si può discutere. Prendi il mio ultimo cliente, per esempio.|n|nC\'è un Vilorco alla Cittadella del Fuoco Infernale noto come Keli\'dan il Demolitore. Egli è in possesso di un bastone particolarmente mondano, niente di eccezionale. Eppure è ciò che vuole il mio cliente.|n|nE chi sono io per dire di no?|n|nSe la mia ricompensa ti fa gola, troverai il Vilorco e il suo bastone nella Forgia del Sangue.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Bastone Piumato di Keli\'dan. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11363] = {
    'Ricercato: Sigillo di Manotagliente',
    {'Oggi è venuto da me un collezionista molto ricco in cerca di un pezzo unico.|n|nIl Capoguerra Kargath Manotagliente porta sempre con sé il suo sigillo di comando, che utilizza per firmare tutti i documenti ufficiali. Voglio che lo recuperi per me.|n|nTroverai il Capoguerra nelle stanze interne delle Sale della Devastazione. Senza dubbio dovrai aprirti un varco in mezzo a un vero e proprio esercito per giungere fino a lui, ma sono sicuro che tornerai vincitore.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Sigillo di Manotagliente. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11364] = {
    'Ricercati: Centurioni Manomozza',
    {'Tu oseresti discutere gli ordini del tuo padrone? Be\', non lo farebbe neanche Mah\'duun.|n|nQuello che cerco è il sangue del Clan Manomozza, che troverai nelle Sale della Devastazione della Cittadella del Fuoco Infernale.|n|nSe vuoi la taglia, non tornare finché non li avrai uccisi tutti.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 4 Centurioni Manomozza. Quando saranno tutti morti, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11365] = {
    'La marcia dei giganti',
    {'Sul Percorso dei Giganti a est, i Giganti della Pietra Runica hanno iniziato a migrare verso nord attraverso il Picco di Gelalama. Non so quale sia la loro destinazione, né il loro scopo.|n|nLe rune luminose, incise nei corpi di pietra dei giganti, li guidano nel loro cammino. Abbattine qualcuno.|n|nUsa questo piccone sui cadaveri dei giganti per disattivarle. Quando avrai fatto un po\' di tentativi con vari giganti, torna a riferirmi ciò che avrai scoperto.', },
    {'Il Saggio Edan all\'Accampamento degli Zoccolo Artico ti ha chiesto di usare il Piccone Cercarune sui cadaveri di 4 Giganti della Pietra Runica.', },
  },
  [11366] = {
    'Come magnetite',
    {'Dobbiamo scoprire cosa sta attirando i giganti a nord-ovest, così potremo fermarli prima che arrivino a destinazione.|n|nI campioni di rune che ci hai portato ci hanno fornito degli indizi, ma sono quelle sconosciute a preoccuparmi di più. Quando ho visitato il Percorso dei Giganti, ho notato una grossa Tavoletta Spezzata che sporgeva dal terreno nel punto in cui la parte nordorientale di quella zona incontra le nevi ai piedi del Picco di Gelalama. Prendi questo campione, confronta le rune con la tavoletta e cerca di scoprire qualcosa sulla natura di questa attrazione.', },
    {'Il Saggio Edan all\'Accampamento degli Zoccolo Artico ti ha chiesto di confrontare il Campione di Rune con la Tavoletta Spezzata.', },
  },
  [11367] = {
    'Distruggere Megalith',
    {'Il Vincolatore Murdis ha creato Megalith per essere una specie di fulcro dei Giganti Runici e guidarli in missione. Senza di lui, i suoi compagni sarebbero persi e confusi. Chiederò al Capo Tribù Totem Sabbioso di distaccare alcune delle nostre unità in marcia verso nord e dedicarle all\'eliminazione dei Giganti Runici. Senza di essi, i Nani del Ferro non avranno alcuna speranza.|n|nEsplora le alture del Picco di Gelalama, a nord del Percorso dei Giganti: quando avrai trovato Megalith, attaccalo e sconfiggilo!', },
    {'Uccidi Megalith e torna dal Saggio Edan all\'Accampamento degli Zoccolo Artico.', },
  },
  [11368] = {
    'Ricercato: Cuore di Bragatur',
    {'Ho una richiesta inusuale. Una certa ricca persona fuori da questo mondo con cui sono in contatto è interessata a un articolo un po\' macabro.|n|nNello specifico, desidera il Cuore di Bragatur.|n|nHo sentito dire che quella belva ne possiede tre, ma uno solo basterà ai nostri fini. Per quel che ne so, puoi trovare Bragatur a riposo in una profonda pozza d\'acqua nelle Fosse degli Schiavi.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di ottenere il Cuore di Bragatur. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11369] = {
    'Ricercato: Uovo di Camminatore Oscuro',
    {'C\'è una sola grande madre dei Camminatori delle Paludi nelle Paludi di Zangar ed è nota come il Camminatore Oscuro. Essa nasce dalle uova lasciate dalla madre quando muore.|n|nHo un acquirente interessato a una di quelle uova... pare voglia utilizzarla come attrazione in uno zoo.|n|nSe la ricompensa che ti offro ti pare stimolante, vai alla Torbiera Sotterranea, uccidi il Camminatore Oscuro e recupera l\'uovo.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare un Uovo di Camminatore Oscuro. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11370] = {
    'Ricercato: Trattato del Signore della Guerra',
    {'Anche se è noto che il Signore della Guerra Kalithresh dei Naga è un grande combattente, pochi sanno che ha anche codificato tutta la sua conoscenza.|n|nUno dei miei clienti, invece, lo sa e vorrebbe mettere le mani sul trattato.|n|nVorrei che andassi all\'Antro dei Vapori nel Bacino degli Spiraguzza e recuperassi quel libro per me.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Trattato del Signore della Guerra. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11371] = {
    'Ricercati: Mirmidoni Spiraguzza',
    {'Mah\'duun ascolta e obbedisce, e ora ti chiede di essere il suo strumento.|n|nMi è stato comunicato che i Mirmidoni della tribù Spiraguzza devono essere eliminati. Potrai trovarli dentro gli umidi confini dell\'Antro dei Vapori sotto il Bacino degli Spiraguzza.|n|nNon ammetterò nulla di meno del loro totale annientamento.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 14 Mirmidoni Spiraguzza. Quando saranno tutti morti, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11372] = {
    'Ricercate: Piume della Testa di Ikiss',
    {'Recentemente sono stato contattato da una Tauren il cui marito sta per essere nominato Capo Tribù. Desidererebbe arricchire il suo copricapo in modo speciale.|n|nNello specifico, vuole le piume della testa del vile Ikiss il Re Artiglio.|n|nSe la mia ricompensa ti fa gola, recati alle Sale dei Sethekk di Auchindoun e trovalo.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di ottenere le Piume della Testa di Ikiss. Consegnagliele nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11373] = {
    'Ricercato: Meraviglioso Amuleto di Shaffar',
    {'Oggi ho da farti una richiesta personale, ma non preoccuparti: la ricompensa sarà adeguata ai pericoli.|n|nLa mia famiglia ha, per così dire, una questione in sospeso con Shaffar il Principe del Nexus e i suoi seguaci. Se potessi avere l\'amuleto che egli indossa sempre, per lui sarebbe un colpo mortale.|n|nSe la ricompensa che offro ti interessa, allora recati nella sua tana alle Tombe del Mana di Auchindoun.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Meraviglioso Amuleto di Shaffar. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11374] = {
    'Ricercata: Gemma dell\'Anima dell\'Esarca',
    {'Nelle Cripte degli Auchenai di Auchindoun vengono condotti molti esperimenti... poco piacevoli, sì, ma rivolti a una più profonda comprensione delle arti negromantiche, anche se comportano la tortura o la distruzione di molti spiriti.|n|nOra, un mio cliente è interessato a liberare uno di quegli spiriti, il quale si trova all\'interno di una Gemma dell\'Anima in mano a nientemeno che l\'Esarca Maladaar in persona.|n|nCercalo all\'interno delle Cripte con la dovuta urgenza e poi torna da me con la gemma.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare la Gemma dell\'Anima dell\'Esarca. Consegnagliela nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11375] = {
    'Ricercato: Sussurro di Murmur',
    {'Quando avrò finito di parlare, potresti rifiutarti di accettare questo incarico.|n|nUn mio eccentrico cliente è specializzato nello studio delle realtà morte. Si dice che un essere di nome Murmur abbia distrutto l\'ultimo mondo da cui era stato evocato. A questo professore interessa analizzare il suo "sussurro" per capire come abbia potuto compiere una simile impresa.|n|nSei $Gdisposto:disposta; a recarti nel Labirinto delle Ombre di Auchindoun e recuperare quel "sussurro"?', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Sussurro di Murmur. Consegnaglielo subito nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11376] = {
    'Ricercati: Istruttrici Maligne',
    {'Mah\'duun ha sentito dire che non c\'è nessuno più crudele dei demoni a sei braccia del Labirinto delle Ombre.|n|nRecati ad Auchindoun, trovali e uccidili tutti.|n|nSe non riuscirai a portare a termine un compito così semplice, non avremo più nulla da dirci.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 3 Istruttrici Maligne. Quando saranno tutte morte, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11377] = {
    'Vendetta gustosa',
    {'Stasera mi occuperò del rinfresco per alcuni ospiti inusuali. Uno di loro stava sorvolando Skettis ed è stato abbattuto da un Kaliri Mostruoso e si è rotto una gamba.|n|nMi hanno chiesto un piatto speciale per la sua festa di guarigione: Stufato di Kaliri.|n|nPosso prestarti il mio pentolone in modo che tu possa preparare lo stufato al posto mio. La ricetta è semplice, ma ti servirà un\'Ala di Kaliri Gigante e delle Polpette Distorte.', },
    {'Rokk nella Città Bassa ti ha chiesto di preparare uno Stufato di Kaliri usando il suo pentolone. Torna da lui quando avrai finito.', },
  },
  [11378] = {
    'Ricercata: Testa del Cacciatore delle Ere',
    {'I gusti dei miei clienti vanno dal mondano all\'esotico. Talvolta vogliono fare qualcosa di molto mondano con oggetti molto esotici.|n|nQuesto è il caso della richiesta che ho appena ricevuto: il mio cliente, che desidera restare nell\'anonimato, vuole la Testa di un Cacciatore delle Ere per ornare una parete.|n|n$C, potresti trovare il modo di tornare indietro nel tempo al Passato di Colletorto e recuperare quella testa per il mio cliente cacciatore di trofei?', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di ottenere la Testa del Cacciatore delle Ere. Consegnagliela nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11379] = {
    'Stufato rovente',
    {'Sto cercando d\'inventare qualcosa dal sapore speciale, ma se devo essere onesto, ultimamente sono più un Goblin teorico che pratico. Ho perso il gusto dell\'avventura.|n|nMa tu... mi ricordi la mia gioventù; sempre $Gpronto:pronta; ad affrontare il mondo con la spada in una mano e una casseruola nell\'altra.|n|nVoglio che tu prenda il mio amato pentolone e ti diriga a Spinaguzza. Buttaci dentro delle costine e del serpente croccante, già cucinati per aggiungere sapore. Cuoci il tutto sul cadavere di un Abissale, l\'unica fonte di calore in grado di scaldare a dovere il pentolone.', },
    {'Rokk nella Città Bassa ti ha chiesto di preparare una Fantasia Demoniaca alla Brace usando il suo pentolone, 2 Costine dei Mok\'Nathal e un Serpente Croccante. Torna da lui quando avrai finito.', },
  },
  [11380] = {
    'Bacche manaliziose',
    {'Come al solito, quando penso che il mio menu sia aggiornato, ecco che arriva qualcuno a chiedermi qualcosa di inusuale: Delizia di Manabacche.|n|nSfortunatamente, le Manabacche crescono solo nelle Ecosfere della Landa Fatua. Non stare a cercare vicino alla Guglia Tempestosa: le hanno colte tutte.|n|nCogliere le bacche migliori è un compito che posso affidare solo $Gal:alla; migliore $Gdei cuochi:delle cuoche;. Non deludermi!', },
    {'Rokk nella Città Bassa ti ha chiesto di raccogliere 15 Manabacche nelle Ecosfere della Landa Fatua.', },
  },
  [11381] = {
    'Brodo per l\'anima',
    {'La morte è nell\'aria. Non ho mai ricevuto così tante comande per la mia famosa zuppa: risolleva il morale e calma l\'animo.|n|nE so riconoscere $Gun altro cuoco:un\'altra cuoca; quando $Glo:la; vedo! Hai voglia di darmi una mano e di prendere parte dei profitti?|n|nEcco, prendi il mio pentolone, trova della carne di mammuceronte e ti svelerò un piccolo segreto. Sai perché la mia zuppa fa bene all\'anima? Perché la cucino nelle Terre Ancestrali a Nagrand per impregnarla con le sue emanazioni spirituali.', },
    {'Rokk nella Città Bassa ti ha chiesto di preparare una Zuppa Spirituale usando il suo pentolone. Torna da lui quando avrai finito.', },
  },
  [11382] = {
    'Ricercata: Clessidra di Aeonus',
    {'Non c\'è altra spiegazione: alcuni miei clienti sono dei pazzi. Ci sono beni che si possono desiderare e altri a cui non si può nemmeno osare pensare!|n|nOra, quest\'ultimo cliente è più che folle: desidera la Clessidra di Aeonus.|n|nSì, hai sentito bene, lo stesso Aeonus dello Stormo dei Draghi dell\'Infinito!|n|nMa come posso discutere con chi offre una ricompensa pari al riscatto di un Re? Allora... sei $Gpronto:pronta; ad andare alle Caverne del Tempo ed entrare nella Palude Nera per recuperarla?', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare la Clessidra di Aeonus. Consegnagliela nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11383] = {
    'Ricercati: Signori della Faglia',
    {'Mah\'duun sa dove devi andare. Mah\'duun sa che devi uccidere i Signori della Faglia. Mah\'duun però non sa esattamente quando questo accadrà.|n|nSo che sembra avere poco senso, ma la voce del vento non è stata più specifica.|n|nRecati alla Palude Nera attraverso le Caverne del Tempo e tutto si chiarirà.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 4 Signori della Faglia. Quando saranno tutti morti, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11384] = {
    'Ricercato: Pezzetto di Scheggia Arcana',
    {'Non molto tempo fa sono stato contattato da una Druida Kaldorei, la quale aveva una richiesta che mi ha commosso. E molto oro, naturalmente!|n|nA quanto pare, le forze di Darnassus desiderano far ricrescere un Antico dell\'Arcano chiamato Scheggia Arcana. Quell\'albero gigante è stato confuso o corrotto, non ho capito bene, ma a ogni modo lo troverai a Botanica di Forte Tempesta.|n|nLa mia cliente mi ha detto che per farlo ricrescere hanno bisogno solo di un suo piccolo pezzetto.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare un Pezzetto di Scheggia Arcana. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11385] = {
    'Ricercati: Salmodianti dei Cercatori del Sole',
    {'È stato sussurrato a Mah\'duun che i Salmodianti dell\'unità militare nota come Cercatori del Sole devono essere uccisi oggi.|n|nLi troverai a Botanica di Forte Tempesta.|n|nSe vuoi la taglia, uccidi i Salmodianti.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 6 Salmodianti dei Cercatori del Sole. Quando saranno tutti morti, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11386] = {
    'Ricercato: Proiettore di Pathaleon',
    {'Ho sempre pensato che Pathaleon il Calcolatore utilizzasse la magia per proiettare la propria immagine nelle Terre Esterne, ma a quanto pare mi sbagliavo.|n|nUn mio cliente mi ha rivelato che, per comunicare con i capi dei progetti speciali del Principe Kael\'thas, quell\'Elfo del Sangue usa un dispositivo meccanico che, se non ho capito male, ha sottratto ai ribelli Zaxxis nella Landa Fatua.|n|nIl mio cliente desidera quel proiettore. Perché non fai una visitina a Pathaleon? Lo troverai nel Mecanar a Forte Tempesta.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare il Proiettore di Pathaleon. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11387] = {
    'Ricercati: Distruttori Forgiatempeste',
    {'A Mecanar ci sono dei costrutti meccanici che Mah\'duun ha ricevuto l\'ordine di far distruggere.|n|nRecati a Forte Tempesta, trova i Distruttori Forgiatempeste e distruggili.|n|nAllora potrai tornare per ricevere la taglia.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 5 Distruttori Forgiatempeste. Quando saranno tutti morti, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11388] = {
    'Ricercata: Pergamena di Skyriss',
    {'Il cliente di oggi desidera un oggetto davvero unico.|n|nSi dice che l\'Araldo Skyriss sia un servitore degli Dei Antichi. Si dice anche che abbia con sé una grande pergamena contenente le loro istruzioni per dominare la vita nell\'universo.|n|nIl mio cliente vuole mettere le mani su quella pergamena, anche se non sarà in grado di comprendere la lingua in cui è scritta.|n|nRecati all\'Arcatraz di Forte Tempesta e recuperala, $C!', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare la Pergamena di Skyriss. Consegnagliela nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo in modalità Eroica.', },
  },
  [11389] = {
    'Ricercate: Sentinelle di Arcatraz',
    nil,
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 5 Sentinelle di Arcatraz. Quando saranno tutte morte, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11390] = {
    'Ho una Macchina Volante!',
    {'Allora, cosa aspetti? C\'è del lavoro da sbrigare!|n|nEcco le chiavi della nostra Macchina Volante. Prendi tre Sacche di Reliquie e portale alle gru ai lati nord e sud della Chiusa d\'Acciaio. Ti segnalo le destinazioni.|n|nSbrigati, non abbiamo tutto il giorno!', },
    {'Il Capo Archeologo della Chiusa d\'Acciaio ti ha chiesto di trasportare 3 Sacche di Reliquie dal fondo del sito alla piattaforma sul lato nord o sud della Chiusa d\'Acciaio.|n|nPer farlo, usa il rampino della Macchina Volante.|n|nPoi, torna a parlare con il Capo Archeologo della Chiusa d\'Acciaio.', },
  },
  [11391] = {
    'La Pattuglia della Chiusa d\'Acciaio',
    {'Eh? Vuoi lavorare anche oggi?|n|nE va bene: ecco le chiavi. Oggi non abbiamo bisogno di trasportare nulla, quindi limitati a tenere gli occhi aperti e fai attenzione a qualunque cosa sospetta.|n|nHo equipaggiato la Macchina Volante con alcuni razzi e una mitragliatrice. Non si sa mai...', },
    {'Sei', },
  },
  [11392] = {
    'Evoca il Cavaliere Senza Testa',
    {'Questo Santuario della Zucca è adornato da candele tetre.', },
    {'Porta una Candela Tetra sul Terreno Smosso.', },
  },
  [11393] = {
    'Dov\'è l\'Esploratore Jaren?',
    {'$N, il mio promesso sposo Jaren si è recato a ovest con un gruppetto di esploratori per verificare la presenza di manufatti sulla Costa Ondafredda. Quella zona è infestata dai Murloc e inizio a temere il peggio.|n|nPuoi andare a controllare che stia bene? La strada per scendere in spiaggia è a sud-ovest, ma fa\' attenzione ai worg e alle altre creature in agguato nella foresta.', },
    {'La Sovrintendente Irena Pietramanto ti ha chiesto di trovare il suo promesso sposo, l\'Esploratore Jaren.', },
  },
  [11394] = {
    'Ti lamentavi dell\'odore dei Murloc?',
    {'Inizialmente, sono venuto qui per indagare sulle voci di manufatti da riportare alla luce. Sapevo della presenza dei Murloc lungo la costa, ma non avrei mai e poi mai pensato di vedere una cosa del genere.|n|n<L\'esploratore sporge la testa per guardare oltre l\'albero.>|n|nIl Flagello sta alterando i Murloc, e tutte le altre creature che trova, trasformandoli in morti viventi!|n|n$C, è nostro dovere fare qualcosa. Che ne dici di far fuori un po\' di servi del Flagello?', },
    {'L\'Esploratore Jaren ti ha chiesto di uccidere 15 unità qualsiasi del Flagello lungo la Costa Ondafredda. Poi, torna da lui.', },
  },
  [11395] = {
    'Uno strumento del Flagello',
    {'<La creatura del Flagello che hai ucciso teneva stretto fra le grinfie questo strumento. C\'è un gioiello innestato, simile a quello in cima ai Cristalli del Flagello.>|n|n<Sicuramente l\'Esploratore Jaren vorrà dargli un\'occhiata.>', },
    {'Consegna lo Strumento del Flagello all\'Esploratore Jaren sulla Costa Ondafredda.', },
  },
  [11396] = {
    'Abbattere gli scudi',
    {'Guarda il pulsante sul lato del marchingegno. Scommetto che, se riuscissi ad avvicinarti abbastanza a un Cristallo del Flagello, potresti disattivarne lo scudo. A quel punto, bisognerebbe solo distruggere il Cristallo prima lo scudo che si riattivi.|n|nChe ne dici, $N? Lo farai? In cambio, posso prometterti una lauta ricompensa.|n|nÈ il minimo che possiamo fare per impedire al Flagello di aumentare le sue file.', },
    {'L\'Esploratore Jaren sulla Costa Ondafredda ti ha chiesto di distruggere 3 Cristalli del Flagello.', },
  },
  [11397] = {
    'Ti lamentavi dell\'odore dei Murloc?',
    {'Sono venuta qui per indagare su una presunta presenza del Flagello nelle vicinanze. Sapevo che c\'erano dei Murloc lungo quella costa laggiù, ma non avrei mai pensato di vedere una cosa del genere!|n|nIl Flagello sta alterando i Murloc, e tutte le altre creature che trova, trasformandoli in morti viventi!|n|n$C, non permetteremo che creino altri esseri come loro... men che mai usando i Murloc! A nord-ovest dell\'Accampamento, c\'è una rampa che scende fino alla spiaggia. Sbarazzati in fretta del Flagello!', },
    {'La Speziale Anastasia ti ha chiesto di uccidere 15 unità qualsiasi del Flagello lungo la Costa Ondafredda. Poi, torna da lei all\'Accampamento dello Speziale.', },
  },
  [11398] = {
    'Uno strumento del Flagello',
    {'La creatura del Flagello che hai ucciso teneva stretta fra le grinfie questo strumento. C\'è un gioiello innestato, simile a quello in cima ai Cristalli del Flagello.|n|nSicuramente la Speziale Anastasia vorrà dargli un\'occhiata.', },
    {'Consegna lo Strumento del Flagello alla Speziale Anastasia nell\'Accampamento dello Speziale.', },
  },
  [11399] = {
    'Abbattere gli scudi',
    {'Guarda il pulsante sul lato del marchingegno. Scommetto che, se riuscissi ad avvicinarti abbastanza a un Cristallo del Flagello, potresti disattivarne lo scudo. A quel punto, bisognerebbe solo distruggere il cristallo prima che si riattivi lo scudo.|n|n$N, hai il coraggio di affrontare nuovamente il pericoloso viaggio fin laggiù? In cambio, posso prometterti una lauta ricompensa.|n|nCome puoi rifiutarti? Ridurremmo il numero di unità del Flagello... soprattutto quelle rappresentate dai Murloc.', },
    {'La Speziale Anastasia all\'Accampamento dello Speziale ti ha chiesto di distruggere 3 Cristalli del Flagello.', },
  },
  [11400] = {
    'I Montoni Cavalcabili della Festa della Birra',
    {'<Mostra questo timbro a Pol Ambraquieta, l\'Apprendista della Corsa dei Montoni: ti permetterà di acquistare dei Montoni Cavalcabili della Festa della Birra.>', },
    {'Mostra il Timbro "Birraio Onorario" a Pol Ambraquieta vicino all\'entrata della Sede della Festa della Birra a Dun Morogh.', },
  },
  [11401] = {
    'Evoca il Cavaliere Senza Testa',
    {'L\'inquietante e ghignante Santuario della Zucca è adornato da candele tetre...', },
    {'Porta una Candela Tetra sul Terreno Smosso.', },
  },
  [11403] = {
    'Libero, infine!',
    {'Ero prigioniero della rabbia, $N, e tu mi hai liberato. Prima credevo di essere nel giusto, ma ora il mio spirito soffre per tutta la morte e il terrore che ho causato alla gente di Azeroth.|n|nGrazie per avermi fatto tornare sulla via della Luce. E che io non perda più la retta via.|n|nPorta questo vecchio Libro di Preghiere a una Matrona degli orfani, così i bambini sapranno che non li perseguiterò più.', },
    {'Porta il Tomo di Thomas Thomson alla Matrona degli Orfani Mascherata nella regione di Durotar, presso Brill o Piazza del Falco.', },
  },
  [11404] = {
    'Evoca il Cavaliere Senza Testa',
    {'L\'inquietante e ghignante Santuario della Zucca è adornato da candele tetre...', },
    {'Porta una Candela Tetra sul Terreno Smosso.', },
  },
  [11405] = {
    'Evoca il Cavaliere Senza Testa',
    {'L\'inquietante e ghignante Santuario della Zucca è adornato da candele tetre...', },
    {'Porta una Candela Tetra sul Terreno Smosso.', },
  },
  [11406] = {
    'Dovrà essere tutto pronto',
    {'Il Capitano Adams si aspetta che tutto sia pronto al Fortilizio di Wildervar, quando la Forza di Spedizione inizierà a muoversi verso nord. Esploratori e artigiani sono stati incaricati di preparare equipaggiamento e razioni per i nostri uomini che scaleranno la collina.|n|nIl Capitano è famoso per la sua irascibilità, quindi voglio inviare qualcuno a controllare lo stato dei preparativi. Il Fortilizio di Wildervar si trova a nord-est, oltre Skorn, sulle zone innevate vicino al confine con i Colli Bradi. Quando sarai lì, cerca Gil Grisert e assicurati che sia pronto.', },
    {'Parla con Gil Grisert al Fortilizio di Wildervar.', },
  },
  [11407] = {
    'Urla per la Distilleria di Drohn!',
    nil,
    {'Spargi la voce sulla Festa della Birra presso le bandiere fuori della Casa d\'Aste nella Valle della Forza, nella Valle dell\'Onore, nella Valle della Saggezza e nella Valle degli Spiriti.', },
  },
  [11408] = {
    'Urla per il Birrificio Vudù di T\'chali!',
    nil,
    {'Spargi la voce sulla Festa della Birra presso le bandiere fuori della Casa d\'Aste nella Valle della Forza, nella Valle dell\'Onore, nella Valle della Saggezza e nella Valle degli Spiriti.', },
  },
  [11409] = {
    'Questa sì che è una Corsa dei Montoni... più o meno',
    {'Vuoi provare i Montoni da Corsa? I Nani credono di saperci fare, ma... parliamoci chiaro: la maggior parte del tempo sono ubriachi, quanto mai potrà essere difficile?|n|nPrima di iniziare a darti delle arie, devi dimostrarmi di saper cavalcare queste belle creature ottenute in modo del tutto legale.|n|nFacciamo così: ti presto delle redini da corsa e ti permetto di usare un montone. Tu dimostrami di saper cavalcare.|n|nConduci il montone al trotto, al piccolo galoppo e al galoppo per 8 secondi ciascuno.', },
    {'Hai 4 minuti per cavalcare il montone e devi mantenere ognuna delle 3 velocità per 8 secondi.', },
  },
  [11410] = {
    'Quello che è scappato',
    {'I Barbi che mi hai portato dovrebbero funzionare abbastanza bene come esca per la maggior parte dei pesci, ma temo che attirino anche una mia vecchia conoscenza!|n|nQuando sono arrivato qui la prima volta, ho agganciato al mio amo un po\' dell\'esca preferita di Nat Pagle e ho gettato la lenza in acqua. Ha abboccato un mostro enorme, con denti giganti e le pinne ricoperte di ghiaccio!|n|nSe non avessi tagliato la lenza, mi avrebbe trascinato nelle acque gelide! Non posso usare la nuova esca, finché il vecchio Pinnagelida sarà ancora in circolazione. Usa l\'esca vicino alla barca affondata in mezzo al lago: non potrà resistere!', },
    {'Christopher Sloan al Fortilizio di Wildervar ti ha chiesto di uccidere Pinnagelida.', },
  },
  [11411] = {
    'Accampamento degli Zoccolo Artico',
    {'Nei miei viaggi come Corriere, ho visto molti strani abitanti del Fiordo Echeggiante, ma un gruppo spiccava fra gli altri. Da lontano, sembrano Tauren. Visti da vicino, però, sono molto diversi: più robusti e irsuti.|n|nHo scoperto uno dei loro insediamenti lontano a nord, oltre Halgrind, Skorn e le foreste settentrionali. Lo chiamano Accampamento degli Zoccolo Artico e si trova fra le alture di Ghiacciacorno, vicino al confine con i Colli Bradi. Contattali e scopri se possono esserci d\'aiuto.', },
    {'Parla con il Capo Tribù Totem Sabbioso all\'Accampamento degli Zoccolo Artico.', },
  },
  [11412] = {
    'Andata e ritorno',
    nil,
    nil,
  },
  [11413] = {
    'Qualcuno ha detto "Souvenir?"',
    {'Non solo forniamo la birra, ma regaliamo anche i boccali! Boccali bellissimi e commemorativi, ottenuti con metodi assolutamente legali. Ecco un buono per riceverne uno.|n|nParla con Blix vicino al retro dell\'Accampamento della Festa della Birra. È un tipo strano, soprattutto ora che usa quegli occhiali. Si occuperà del tuo buono e di tutte le altre transazioni alla Festa della Birra.', },
    {'Consegna il Buono per il Boccale della Festa della Birra in Omaggio a Blix Aggiustatutto sul retro dell\'Accampamento della Festa della Birra.', },
  },
  [11414] = {
    'Fratelli coltelli',
    {'La Guardiana Foglialuna appare nei miei sogni! I suoi amici sono anche miei amici.|n|nFino all\'ultimo plenilunio, ero il maschio alfa. Poi, questo strano worg bianco di nome Garwal è arrivato da nord. Aiutato dai miei ex-fratelli, è riuscito rapidamente a prendere il mio posto. C\'è qualcosa di innaturale, in lui.|n|nSe vuoi aiutarmi, prima devi uccidere coloro che mi hanno tradito.|n|nBjomolf va a caccia a nord-ovest di un luogo chiamato Chiusa d\'Acciaio. Puoi trovare Varg a sud-est, vicino alla Torre Lancia dell\'Ovest.|n|nFai attenzione: loro non si lasceranno ingannare dal tuo travestimento.', },
    {'Ulfang ti ha chiesto di uccidere i worg traditori Bjomolf e Varg. Poi, <camuffato/camuffata>, torna da lui nel Bosco di Legnotorvo.|n|nSe perdi il Camuffamento da Worg, torna dalla Guardiana Foglialuna per riceverne un altro.', },
  },
  [11415] = {
    'Fratelli coltelli',
    {'Calca Nebbia appare nei miei sogni! I suoi amici sono anche miei amici.|n|nFino all\'ultimo plenilunio, ero il maschio alfa. Poi, questo strano worg bianco di nome Garwal è arrivato da nord. Aiutato dai miei ex-fratelli, è riuscito rapidamente a prendere il mio posto. C\'è qualcosa di innaturale, in lui.|n|nSe vuoi aiutarmi, prima devi uccidere coloro che mi hanno tradito.|n|nBjomolf va a caccia a nord-ovest di un posto che le creature su due zampe chiamano Chiusa d\'Acciaio. Puoi trovare Varg a sud-est, vicino alla Torre Lancia dell\'Ovest.|n|nLoro non si lasceranno ingannare dal tuo travestimento.', },
    {'Ulfang ti ha chiesto di uccidere i worg traditori Bjomolf e Varg. Poi, <camuffato/camuffata>, torna da lui nel Bosco di Legnotorvo.|n|nSe perdi il Camuffamento da Worg, torna dal Saggio Calca Nebbia per riceverne un altro.', },
  },
  [11416] = {
    'L\'Occhio dell\'Aquila',
    {'Garwal si fa scudo di una magia innaturale. Nessuno lo vede, a meno che non sia lui a volerlo. In ogni caso, abbiamo una possibilità.|n|nSi dice che gli occhi della mia nemica, la grande aquila Rabbiartiglio, possano vedere tutto. Se riuscissi a impossessartene, saresti in grado di vedere Garwal.|n|nIl nido di Rabbiartiglio si trova alla base di una cascata, a sud-ovest del luogo che i Vrykul chiamano Skorn. Tocca le uova in quel nido, così piomberà in picchiata dal cielo per ucciderti.|n|nPrendi i suoi occhi.', },
    {'Ulfang ti ha chiesto di ottenere gli Occhi dell\'Aquila. Poi, <camuffato/camuffata>, torna da lui nel Bosco di Legnotorvo.|n|nSe perdi il Camuffamento da Worg, torna dalla Guardiana Foglialuna per riceverne un altro.', },
  },
  [11417] = {
    'L\'Occhio dell\'Aquila',
    {'Garwal si fa scudo di una magia innaturale. Nessuno lo vede, a meno che non sia lui a volerlo. In ogni caso, abbiamo una possibilità.|n|nSi dice che gli occhi della mia nemica, la grande aquila Rabbiartiglio, possano vedere tutto. Se riuscissi a impossessartene, saresti in grado di vedere Garwal.|n|nIl nido di Rabbiartiglio si trova alla base di una cascata, a sud-ovest del luogo che i Vrykul chiamano Skorn. Tocca le uova in quel nido, così piomberà in picchiata dal cielo per ucciderti.|n|nPrendi i suoi occhi.', },
    {'Ulfang ti ha chiesto di ottenere gli Occhi dell\'Aquila. Poi, <camuffato/camuffata>, torna da lui nel Bosco di Legnotorvo.|n|nSe perdi il Camuffamento da Worg, torna dal Saggio Calca Nebbia per riceverne un altro.', },
  },
  [11418] = {
    'Lo chiamiamo Piumacciaio',
    {'Abbiamo visto un Ippogrifo coraggioso che volava intorno al Fortilizio, dopodiché si è gettato in picchiata e ha afferrato una preda. Jethan ha tentato di tirargli un paio di frecce, ma sono rimbalzate!|n|nAbbiamo deciso di chiamarlo Piumacciaio, ma non capiamo perché prediliga la zona intorno al Fortilizio di Wildervar. La maggior parte degli ippogrifi ha paura delle persone.|n|nIl Ricercatore Aderan ci ha aiutati a creare un talismano, usando una delle piume della creatura. Secondo lui, ci permetterà di vedere attraverso gli occhi di Piumacciaio.', },
    {'Cerca Piumacciaio, che vola intorno al Fortilizio di Wildervar, e usa il Talismano Piumato per scoprire il suo segreto. Riferisci ciò che avrai scoperto a Gil Grisert.', },
  },
  [11419] = {
    'I Montoni Cavalcabili della Festa della Birra',
    nil,
    nil,
  },
  [11420] = {
    'La strada per la vendetta',
    {'Due settimane or sono, il nostro Capo Ingegnere ha messo le mani su un Lancia Arpioni Vrykul, la stessa arma utilizzata dai Vrykul per assaltare le nostre navi. Studiandola a fondo, è riuscito a compilare un manuale d\'uso molto accurato.|n|nSfortunatamente, è stato rapito e portato a nord, a Cranio del Drago. Siamo riusciti a trovarlo, ma era agonizzante e non aveva più con sé il manuale. Le sue ultime parole ci hanno rivelato che il manuale è andato perduto nelle Catacombe di Utgarde, al confine nordoccidentale di Cranio del Drago. Ritrovalo e portamelo!', },
    {'Il Capitano della Guardia Zorek a Valguardia nel Fiordo Echeggiante ti ha chiesto di recuperare il Manuale d\'Uso del Lancia Arpioni.', },
  },
  [11421] = {
    'Spaccare il Cranio',
    {'Dobbiamo colpire mentre le forze Vrykul sono allo sbando! Porta il Controllo del Lancia Arpioni a Nifflevar e trova l\'edificio degli arpioni più a nord sul lato del villaggio che dà sui promontori.|n|nUna volta lì, usa uno dei Lancia Arpioni Vrykul per scatenare l\'inferno su Cranio del Drago! Distruggi la Casalunga, il Casotto, il Magazzino e tutti i Difensori che i Vrykul ti scaglieranno contro!|n|nSe ci riuscirai, la Baia delle Daghe diventerà un posto più sicuro!', },
    {'Il Tenente Acremartello nel Fiordo Echeggiante ti ha chiesto di distruggere la Casalunga degli Scorticadraghi, il Molo degli Scorticadraghi, il Magazzino degli Scorticadraghi e 8 Difensori Scorticadraghi.|n|nQuando avrai finito, riportagli i Controllo del Lancia Arpioni.', },
  },
  [11422] = {
    'Il tridente del figlio',
    {'<Distingui alcuni simboli fra i graffi che il Murloc sta incidendo nella pietra: un tridente, un Mur\'ghoul, un ciglio e il relitto di una nave e una sagoma che dovrebbe raffigurarti.>|n|n<Impieghi un po\' di tempo a capire che cosa stia tentando di comunicarti il Murloc. Evidentemente ti sta chiedendo di recuperare un Tridente dalla Costa Ondafredda, ma l\'immagine del ciglio ti confonde... finché non capisci che ha a che fare con suo figlio.>|n|n<Suo figlio è stato trasformato in un Mur\'ghoul! Sembra che ti stia chiedendo di cercarlo a sud, vicino al relitto della nave, e di tornare con il suo tridente.>', },
    {'Il Vecchio Pinnagelo ti ha chiesto di recuperare il Tridente di Branchiaguasta e di portarglielo sull\'isoletta della Costa Ondafredda.', },
  },
  [11423] = {
    'L\'eredità del nemico',
    {'I nemici incontrati dal nostro esercito attraversando Nordania non subiranno una semplice sconfitta: le loro case bruceranno, i loro cadaveri saranno divorati dalle nostre Piaghe e ogni traccia della loro esistenza verrà cancellata dalla faccia del pianeta. Come ricercatrice della conoscenza, questa cosa mi preoccupa.|n|nLa città orientale di Nifflevar sarà presto distrutta dalle nostre armate di stanza nell\'Attracco della Vendetta. Helgus, il Bardo Vrykul, viveva lì e ha scritto tre saghe: la Saga delle Gemelle, la Saga della Maledizione Invernale e la Saga delle Val\'kyr. Recuperale prima che Nifflevar venga distrutta.', },
    {'Entra a Nifflevar, a nord del Bivacco di Lama Spettrale, e cerca la Saga della Maledizione Invernale, la Saga delle Val\'kyr e la Saga delle Gemelle.', },
  },
  [11424] = {
    'Colle degli Scudi',
    {'In tempo di guerra, il mio lavoro dovrebbe essere semplicissimo: dovrei riuscire a trovare pezzi di corpo utilizzabili dappertutto.|n|nEppure non è così. I cervelloni creano Piaghe assassine di ogni tipo e le spargono sulle città nemiche, contaminando la maggior parte del materiale.|n|nPerò esiste un luogo dove ci sono dei campioni validi: il Colle degli Scudi a sud è un antico luogo di sepoltura dei Vrykul. Lì, i morti camminano ma non sono affetti da alcuna Piaga, né la nostra né quella del Re dei Lich. Portami delle ossa e ti ripagherò come si deve.', },
    {'Jenny "Seghetto" ti ha chiesto di portarle 5 Antiche Ossa di Vrykul dai Vrykul rianimati nel Colle degli Scudi, a sud di Nuova Agamand.', },
  },
  [11426] = {
    'Alla ricerca del meccanismo',
    {'Non temere, $N: questa storia ci farà fare dei grandi passi avanti! ENORMI! Devi solo fidarti di me e fare ciò che ti chiedo.|n|nPer passare alla fase successiva del piano, abbiamo bisogno del meccanismo descritto nel manuale. Ho il forte sospetto che lo troverai addosso a uno dei Vrykul che azionano i Lancia Arpioni a Cranio del Drago. Cercali sul lato est del villaggio, nel porto vicino alle Caselunghe.', },
    {'Il Capitano della Guardia Zorek a Valguardia nel Fiordo Echeggiante ti ha chiesto di portargli un Controllo del Lancia Arpioni.', },
  },
  [11427] = {
    'Incontra il Tenente Acremartello',
    nil,
    {'Il Capitano della Guardia Zorek ti ha chiesto di portare il Controllo del Lancia Arpioni al Tenente Acremartello di stanza fuori da Nifflevar.', },
  },
  [11428] = {
    'Il Protettore Avvizzafoglia',
    {'$N, sei $Gun grande amico e alleato:una grande amica e alleata;. Devo chiederti un ultimo favore.|n|nHai visto la corruzione della Radura Contorta e le bestie che vi abitano. I Protettori Animanera continueranno a far nascere quegli abomini dalle acque e dal terreno della nostra Radura, a meno che non corriamo ai ripari.|n|nIl più potente fra loro è il Protettore Avvizzafoglia. Uccidilo, $N, e spiana la strada alla redenzione della Radura, così come hai redento le mie sorelle.', },
    {'Lurielle nella Radura Gelata ti ha chiesto di uccidere il Protettore Avvizzafoglia.', },
  },
  [11429] = {
    'Con la bandiera in un pugno',
    nil,
    nil,
  },
  [11430] = {
    'Il Maestro degli Arpioni Yavus',
    nil,
    {'Il Tenente Acremartello nel Fiordo Echeggiante ti ha chiesto di uccidere il Maestro degli Arpioni Yavus a Nifflevar.', },
  },
  [11432] = {
    'Giganti assopiti',
    {'Ho sentito quello che vi siete detti tu e Padre Levariol. Permettimi di farti notare che non ti ha chiesto abbastanza.|n|nDevi occuparti anche dei Vrykul che giacciono addormentati nei Saloni del Risveglio sotto Gjalerbron!|n|nSono sicuro che i rituali per risvegliarli sono anche la chiave per la loro caduta. Ancor più probabile, i necrosignori hanno uno strumento che puoi usare per risvegliare prematuramente i Vrykul.|n|nSenza dubbio, uno shock del genere gli risulterebbe fatale.', },
    {'Il Tenente Mago Malister ti ha chiesto di uccidere 5 Vrykul Dormienti. Poi, torna da lui al Forte di Guardia dell\'Ovest.', },
  },
  [11433] = {
    'Giganti assopiti',
    {'Ho sentito quello che vi siete detti tu e la Madre Anziana Ankha. Con tutto il dovuto rispetto, non ti ha chiesto abbastanza.|n|nDevi occuparti anche dei Vrykul che giacciono addormentati nei Saloni del Risveglio sotto Gjalerbron!|n|nSono sicuro che i rituali per risvegliarli sono anche la chiave per la loro caduta. Ancor più probabile, i necrosignori hanno uno strumento che puoi usare per risvegliare prematuramente i Vrykul.|n|nSenza dubbio, uno shock del genere gli risulterebbe fatale.', },
    {'Ahota Gelo Bianco ti ha chiesto di uccidere 5 Vrykul Dormienti. Poi, torna da lui all\'Accampamento degli Zoccolo Artico.', },
  },
  [11434] = {
    'Tesoro Dimenticato',
    {'Ho fatto fortuna specializzandomi in tesori che i pirati normali non apprezzano: arte, pezzi d\'antiquariato, oggetti da collezione...|n|nLa flotta di Conrad il Nero è affondata anni fa a sud. Tutto l\'oro e i gioielli sono stati portati via dai pescatori, ma sono rimaste due antiche reliquie: la prima è un Vaso degli Amani da museo, l\'altra è una Statuetta d\'Aquila.|n|nRecuperale per me e metterò una buona parola in tuo favore con gli altri pirati. Anzi, ti darò anche una piccola ricompensa per rendere la tua avventura sottomarina più appetibile.', },
    {'Terry il Bello al Capo di Granfurto ti ha chiesto di portargli il Vaso degli Amani e la Statuetta d\'Aquila dal relitto a sud.', },
  },
  [11436] = {
    'Andiamo a fare surf',
    {'Spostarsi per i ripidi promontori del Fiordo Echeggiante è davvero snervante! Ho escogitato una soluzione per facilitare quest\'operazione, unendo la tecnologia dei Vrykul e l\'ingegno dei Nani. Manca solo qualche piccolo ritocco e il Controllo dei Lancia Arpioni di Acremartello sarà pronto! Ovviamente non è stato provato, ma è per questo che sei qui!|n|nPorta il Controllo al grande Lancia Arpioni di Nifflevar e usalo per lanciarti all\'interno di Valguardia. Riferisci la tua vittoria a Zorek. Ah, sì... puoi tenere il Controllo.', },
    {'Usa il grande Lancia Arpioni Vrykul a Nifflevar per lanciarti all\'interno di Valguardia. Riferisci la tua vittoria sui Vrykul al Capitano della Guardia Zorek.', },
  },
  [11439] = {
    'Addestramento da pompiere',
    {'Ora che c\'è in giro il Cavaliere Senza Testa, i coraggiosi Nani di Kharanos vogliono subito creare una squadra di pompieri. Ci aiuterai?|n|nA sud di qui, i Montanari hanno allestito un campo per fare pratica con gli incendi. Vacci e spegni dei roghi a secchiate. Puoi riempire il secchio con l\'acqua del barile.|n|nArrivederci, $N. Quando hai terminato il tuo addestramento da pompiere, torna a farci visita.', },
    nil,
  },
  [11440] = {
    'Addestramento da pompiere',
    {'Nonostante la minaccia del Cavaliere Senza Testa, i Pacificatori sono riusciti a formare una squadra di pompieri. Vuoi aiutarci?|n|nA ovest di qui, verso Exodar, i Pacificatori hanno allestito un campo per fare pratica con gli incendi. Vacci e spegni dei roghi a secchiate. Puoi riempire il secchio con l\'acqua del barile.|n|nArrivederci, $N. Quando hai terminato il tuo addestramento da pompiere, torna a farci visita.', },
    nil,
  },
  [11441] = {
    nil,
    {'Parla con l\'Organizzatore della Festa della Birra nella Sede della Festa della Birra fuori da Forgiardente per ricevere una birra gratis.', },
    {'Parla con l\'Organizzatore della Festa della Birra.', },
  },
  [11442] = {
    'La Festa della Birra!',
    {'Parla con l\'Organizzatore della Festa della Birra nella Sede della Festa della Birra fuori da Forgiardente per ricevere una birra gratis.', },
    {'Parla con l\'Organizzatore della Festa della Birra e ricevi una birra gratis.', },
  },
  [11443] = {
    'Un tuffo nella Baia delle Daghe',
    {'Ehi... ehm... come va? Che ci fai qui?|n|nIo? ah... be\', ecco... Io... ehm... sto tentando di ripulire questo posto! Ordine di Keller in persona! Mi ha detto:|n|n"Harry, metti in testa lo scafandro e va\' a cercare la NOSTRA roba fra i relitti della Baia delle Daghe..."|n|nSenti, perché non mi dai una mano, visto che sei quaggiù anche tu? L\'intera baia è disseminata di bottino... ehm, volevo dire di provviste. Portami tutto ciò che trovi. Usa questo casco da immersione, così non rimarrai senz\'aria.', },
    {'Harold Lagras sul fondo della Baia delle Daghe ti ha chiesto di recuperare 10 Casse di Rifornimenti di Valguardia.', },
  },
  [11446] = {
    nil,
    {'Parla con l\'Organizzatore della Festa della Birra nella Sede della Festa della Birra fuori da Orgrimmar per ricevere una birra gratis.', },
    {'Parla con l\'Organizzatore della Festa della Birra.', },
  },
  [11447] = {
    'La Festa della Birra!',
    {'Parla con l\'Organizzatore della Festa della Birra nella Sede della Festa della Birra fuori da Forgiardente per ricevere una birra gratis.', },
    {'Parla con l\'Organizzatore della Festa della Birra e ricevi una birra gratis.', },
  },
  [11448] = {
    'L\'Avamposto della Lega degli Esploratori',
    {'È solo un mucchio di enigmi senza senso! Anche con il Cifrario, queste Tavolette non hanno né capo né coda. Ammetto che la crittografia non è la mia specialità.|n|nDevi portare Cifrario e Tavolette a Stanwad, il nostro Criptografo. Sfortunatamente, non ho sue notizie da due settimane. Ha formato una squadra composta da venti scienziati e si è diretto verso i siti di scavo ai promontori sudorientali del Fiordo. Da allora, non si sa più nulla di lui. Tutto ciò che posso fare è chiedere a McGoyver di darti un passaggio sulla sua Macchina Volante.', },
    {'Consegna il Pacchetto di McSorf a Stanwad all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante.', },
  },
  [11449] = {
    'Addestramento con il fuoco',
    {'Fuori città, gli Inseguitori della Morte hanno allestito un\'area per addestrarsi a spegnere gli incendi. Non possiamo permettere che gli edifici di Brill subiscano altri danni. Dovresti dare una mano e addestrarti per diventare un pompiere.|n|nSegui la strada a ovest e supera il cimitero per trovare l\'area di addestramento.', },
    nil,
  },
  [11450] = {
    'Addestramento con il fuoco',
    {'Fuori città, le guardie hanno allestito un\'area per addestrarsi a spegnere gli incendi. Non possiamo permettere al Cavaliere Senza Testa di distruggere il frutto del nostro duro lavoro. Dovresti fare il tuo dovere e addestrarti per diventare $Gun pompiere:una pompiera;.|n|nEsci dal cancello, dirigiti a sud e raggiungi il crocevia. Lì troverai l\'area di addestramento.', },
    nil,
  },
  [11451] = {
    'La Poesia di Alicia',
    {'Salve, ho scritto una poesia per la mia amica Caylee. Le piace passare il tempo con gli Aldor a Shattrath. Sai, nelle Terre Esterne?|n|nPotresti consegnarle la mia poesia? Mamma dice che sono troppo piccola per andare a Shattrath!', },
    {'Ti è stato chiesto di consegnare la Poesia di Alicia a Caylee Dak a Shattrath nelle Terre Esterne.', },
  },
  [11452] = {
    'Il Re addormentato',
    {'<Una cartapecora cade dalla mano immobile del Necrosupremo. Su di essa, identifichi le linee guida dei rituali che hanno luogo nelle catacombe sottostanti.>|n|n<Sembra che Angrboda, la Regina dei Vrykul, stia incontrando delle difficoltà a risvegliare Re Ymiron. Il rito si sta svolgendo nella grande sala conosciuta come Terrazza dell\'Inverno, all\'estremità nord di Gjalerbron.>|n|n<Se ti sbrighi, puoi fermarla prima che sia troppo tardi.>', },
    {'Sconfiggi la Regina Angrboda e interrompi il rituale per risvegliare Re Ymiron. Poi, torna al Forte di Guardia dell\'Ovest e riferisci il tuo successo al Capitano Adams.', },
  },
  [11453] = {
    'Il Re addormentato',
    {'<Una cartapecora cade dalla mano immobile del Necrosupremo. Su di essa, identifichi le linee guida dei rituali che hanno luogo nelle catacombe sottostanti.>|n|n<Sembra che Angrboda, la Regina dei Vrykul, stia incontrando delle difficoltà a risvegliare Re Ymiron. Il rito si sta svolgendo nella grande sala conosciuta come Terrazza dell\'Inverno, all\'estremità nord di Gjalerbron.>|n|n<Se ti sbrighi, puoi fermarla prima che sia troppo tardi.>', },
    {'Uccidi la Regina Angrboda e interrompi il rituale per risvegliare Re Ymiron. Poi, torna all\'Accampamento degli Zoccolo Artico e riferisci il tuo successo al Capo Tribù Totem Sabbioso.', },
  },
  [11454] = {
    'In cerca dei Sabotatori',
    {'Gli Invasori Ferroscuro hanno perso questo pezzo di carta.|n|nI piani sono complessi e scritti in una specie di codice nanico, ma la firma in fondo è chiara: "Coren Birranera". Inoltre, viene menzionato il Torvo Beone nei Sotterranei di Roccianera. Cerca il mandante e poni fine a questi attacchi.', },
    {'Cerca Coren Birranera al Torvo Beone nei Sotterranei di Roccianera.', },
  },
  [11455] = {
    'Il profumo dei soldi',
    {'Noi pirati siamo famosi per molte cose, ma l\'igiene non è sicuramente una di queste. Sulla maggior parte delle nostre navi, ci sono almeno sei topi per ogni uomo.|n|nNon mi stupisce che tutti gli orsi di quest\'isola abbiano contratto la rabbia, appena siamo sbarcati. Per farla breve, il capo li vuole tutti morti.|n|nInoltre, conosco la formula di un profumo al Muschio d\'Orso molto popolare fra i nobili di Roccavento. Uccidiamo gli orsi e vendiamo il muschio: mi sembra un\'ottima prospettiva di guadagno, che ne pensi?', },
    {'Terry il Bello al Capo di Granfurto nel Fiordo Echeggiante ti ha chiesto di ottenere 4 Muschi d\'Orso dagli Orsi Bruni Rabbiosi dei dintorni.', },
  },
  [11456] = {
    'Nutrire i sopravvissuti',
    {'Noi Tuskarr ci affidiamo soprattutto alla pesca per il nostro sostentamento. Ciononostante, occasionalmente e in caso di necessità, cacciamo gli animali di terra.|n|nRecentemente, il villaggio di Iskaal qui vicino è stato attaccato dai pirati e i sopravvissuti continuano a cercare rifugio qui.|n|nQuesta settimana, la pesca non è stata molto fruttuosa... ma l\'isola è piena di Zannapiatta e la loro carne è succulenta.|n|nAiuta il mio popolo a cacciare quelle enormi bestie e a recuperare la loro carne.', },
    {'L\'Anziano Atuik a Kamagua nel Fiordo Echeggiante ti ha chiesto di recuperare 6 Pezzi di Carne di Zannapiatta Insulare sull\'Isola delle Lance.', },
  },
  [11457] = {
    'Armare Kamagua',
    {'Il mio popolo raffigura Issliruk, lo spirito della guerra, come un\'aquila d\'argento. Nelle nostre leggende, ha combattuto contro cento worg per salvare i suoi piccoli.|n|nÈ arrivato il momento anche per noi di affrontare i nemici per salvare i nostri fratelli. Dobbiamo creare delle nuove armi. Le Chimere Alazzurra, che abitano nelle zone innevate dell\'isola, hanno corna affilate e facilmente trasformabili in punte per le frecce. Portami le migliori che trovi.', },
    nil,
  },
  [11458] = {
    'Vendicare Iskaal',
    {'$N, il totem di Issliruk è pronto, grazie a te. Dobbiamo mettere da parte momentaneamente il pacifismo e attaccare chi ha assaltato la nostra terra e la nostra razza.|n|nI pirati schiavisti che hanno razziato Iskaal sono impazziti e hanno ucciso tutti i prigionieri. Va\' a Iskaal, a est di qui, e fa\' ciò che è necessario. Prendi questo corno: nel caso avessi bisogno d\'aiuto, suonalo per chiamare i miei fratelli.', },
    {'L\'Anziano Atuik ti ha chiesto di andare a Iskaal e uccidere 8 Schiavisti dei Mari del Nord. Qualora avessi bisogno d\'aiuto, suona il Corno di Kamagua.', },
  },
  [11459] = {
    'Parola di Zeh\'gehn',
    {'Cumpà, le cose stanno così! Vuoi l\'aiuto mio per scoprire nu figlio di trota che sta infiltrato nella ciurma?|n|nMi devi portare nu gracidone, cumpà, e poi ti dico chi è lo spione. Il gracidone nun lo vedi, però. Ti tocca aprire bene i fanali della capa!|n|nE portami pure nu taglione, tutto quanto insieme. A presto, cumpà.', },
    {'Torna da Terry il Bello per decifrare ciò che Zeh\'gehn ti ha chiesto.', },
  },
  [11460] = {
    'Fiducia conquistata',
    {'Nella falconeria, la cosa più importante è il legame fra il falconiere e il suo animale. È il padrone che deve conquistare la fiducia del volatile!|n|n<Hidalgo indica i falconi nella gabbia ai suoi piedi.>|n|nSe vuoi riuscirci, prima devi riempire i loro stomaci.|n|nQuesti sono falconi della Roccia dei Fiordi e mangiano principalmente bruchi. In tutto il Fiordo, troverai delle rocce allentate che sono l\'habitat naturale proprio per i bruchi: prendine uno e torna qui per darlo da mangiare al falcone in gabbia.', },
    {'Hidalgo all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di trovare un Bruco dei Fiordi e darlo da mangiare a uno dei falconi nella gabbia ai suoi piedi.', },
  },
  [11462] = {
    '[Handsome Terry]',
    nil,
    nil,
  },
  [11464] = {
    'Debiti di gioco',
    {'Ho sentito che hai fatto un lavoretto per Terry. Speravo proprio che qualcuno affidabile si facesse vivo da queste parti.|n|nAscolta... i pirati adorano scommettere, ma non amano altrettanto pagare i debiti di gioco.|n|nSe recupererai un po\' di monete per conto mio, sarò felice di dartene una parte.|n|nIniziamo con uno facile. Harry "Lunargenta" è un tipo un po\' eccentrico: la sua tenda è piena di costose carabattole degli Elfi del Sangue. Eppure, ogni volta che lo incontro, fa finta di essere al verde. Va\' a prendere il mio oro.', },
    {'Taruk nel Capo di Granfurto ti ha chiesto di riscuotere il Debito di Harry "Lunargenta".', },
  },
  [11465] = {
    'La carovana saccheggiata',
    {'Stavo guidando una carovana da Valguardia a qui, ma siamo stati attaccati dagli Scorticadraghi. Sono l\'unico sopravvissuto all\'imboscata. Purtroppo, non sono riuscito a salvare il carico di Tacchini dei Fiordi. È l\'occasione ideale per fare pratica con il tuo Falcone delle Rocce.|n|n<Hidalgo ti consegna una gabbia.>|n|nPrendi questa Gabbia del Falcone e dirigiti a ovest, lungo la strada che esce da questo accampamento. Usa il falcone per catturare i tacchini in fuga. Quando ne avrai recuperati a sufficienza, torna qui.|n|nRicorda di dare da mangiare al falcone!', },
    {'Hidalgo all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare il Falcone della Roccia Addestrato per catturare 5 Tacchini dei Fiordi.|n|nPoi, torna da Hidalgo con la Gabbia.', },
  },
  [11466] = {
    'A Jack piace bere',
    {'Jack Adams, il nostro prossimo cliente, non sarà facile come Harry. Passa tutto il giorno a bere con i suoi amici: un gruppetto di pirati davvero tosti. Stavolta non puoi usare la forza, andrebbe sicuramente a finire male.|n|nCerca di sfruttare il suo vizio del bere a tuo vantaggio. Una persona può bere solo fino a un certo punto, prima di svenire.|n|nMagari una delle servette della taverna potrà aiutarti. Quando avrà perso i sensi, infila la mano nelle sue tasche e prendi ciò che mi spetta.', },
    {'Taruk al Capo di Granfurto nel Fiordo Echeggiante ti ha chiesto di riscuotere il Debito di Jack Adams.', },
  },
  [11467] = {
    'Il debito del morto',
    {'Avrai sentito parlare di Conrad il Nero: è un pirata molto famoso, da queste parti.|n|nBe\', gli piaceva scommettere sui miei combattimenti... e gli piaceva non pagare.|n|nVorrei riscuotere il suo debito, ma c\'è un piccolo problema: è morto.|n|nStavo quasi per rinunciare, quando ho trovato questa...|n|n<Taruk srotola una mappa dell\'Isola delle Lance con una X su un on altopiano a nord-est.>|n|nHa nascosto il suo tesoro nel territorio Tuskarr. Vallo a prendere. Che io sia maledetto, se permetto a quella sanguisuga di morire senza pagarmi!', },
    {'Taruk al Capo di Granfurto ti ha chiesto di cercare il Tesoro di Conrad il Nero sull\'altopiano al confine nordorientale dell\'Isola delle Lance, poco a nord da Iskaal.', },
  },
  [11468] = {
    'Falcone contro falco',
    {'$N, lo senti quanto vi siete avvicinati? Sicuramente riesci a sentire che si sta formando un legame fra te e il tuo falcone. Mi crederesti se ti dicessi che, al momento giusto, potrai vedere attraverso gli occhi del tuo volatile? Proprio così, è l\'ultimo livello di falconeria.|n|nMa prima devi cacciare ancora! Il falcone deve affinare e migliorare i suoi riflessi. Mandalo contro un avversario più difficile! I Falchi dei Fiordi di questa regione fanno il nido sulle cime degli alberi intorno a noi. Saranno loro il tuo prossimo bersaglio!', },
    nil,
  },
  [11469] = {
    'Sapone da redazza',
    {'Sì, devo pulire da cima a fondo il ponte prima che torni Jonah "il Pazzo". Non ho intenzione di farlo a quattro zampe!|n|nIl problema è che abbiamo finito il sapone. Cioè... è un problema più tuo che mio: sei tu $Gil novellino:la novellina;, quindi ti mando a fare un bel viaggetto.|n|nSulla costa nordoccidentale di quest\'isola, c\'è un gruppo numeroso di Leoni Marini. Fra le Banchise Ghiacciate lì vicino, troverai Grande Roy, il loro maschio alfa. Portami il suo grasso e io creerò il sapone migliore mai esistito!', },
    {'Scuttle Pruafredda ti ha chiesto di recuperare il Grasso del Grande Roy per usarlo come ingrediente principale nel suo magico sapone da redazza. Poi, torna da lei sulla nave pirata orientale al Capo di Granfurto.', },
  },
  [11470] = {
    'Non c\'è onore fra gli uccelli',
    {'$N, sei $Gpronto:pronta; per passare al livello successivo di falconeria.|n|nPorta il tuo falcone addestrato a est, al Trespolo del Falco Vrykul vicino all\'Ascensore di Pietramuro. Quando sarai lì, manda il tuo falcone a rubare le uova dei falchi. I loro nidi si trovano nelle parti più lontane delle scogliere che circondano il posatoio. Trovali e usa il falcone per rubare le uova!|n|n$N, fa\' attenzione alla Matriarca di Falco dei Fiordi: se dovesse attaccarti, usa le abilità Fuga e Veleggiare del falcone per fuggire!', },
    {'Hidalgo all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare il tuo Falcone della Roccia Addestrato per recuperare 8 Uova di Falco dei Fiordi.|n|nPoi, torna da Hidalgo con la Gabbia.', },
  },
  [11471] = {
    'Il piano è stato scoperto',
    nil,
    {'Annie Bonn nel Capo di Granfurto ti ha chiesto di portarle il Cannocchiale di Jonah Sterling.', },
  },
  [11472] = {
    'La via per il cuore...',
    {'I Pirati dei Mari del Nord hanno ucciso il Leone Marino alfa delle isole, il Grande Roy. Ne hanno fatto del sapone per pulire i ponti delle loro navi!|n|n<Anuniaq sospira.>|n|nOra i Leoni Marini non potranno avere dei discendenti. Aiutami a ripopolarli.|n|nI Leoni Marini di Scogliera si trovano alle Rive Gemelle a sud-est. Adorano i Pesci Tropicali Saporiti, che popolano le acque sui lati est e ovest delle isole.|n|nPrendi questa rete e pescane a sufficienza, almeno una decina... ma anche di più. Potrai usarli per attirare un maschio verso una Leonessa Marina di Scogliera.', },
    {'Lancia del Pesce Tropicale Saporito a un Leone Marino di Scogliera per condurlo verso una Leonessa Marina di Scogliera. Quando avrai aiutato i due a trovare il vero amore, torna da Anuniaq a Kamagua.', },
  },
  [11473] = {
    'C\'è un traditore fra di noi',
    {'Ultimamente, la nostra seconda in comando, Annie Bonn, è diventata paranoica. Senti questa: è convinta che ci sia un infiltrato fra di noi!|n|nComunque, abbiamo un metodo infallibile per scoprire le spie: il vecchio Zeh\'gehn è un vero taumaturgo. La sua famiglia discende direttamente da Zul... qualcosa.|n|nVa\' da lui e digli che abbiamo bisogno delle sue arti divinatorie. Ti avverto, $N: solo pochi di noi riescono a capire quello che dice.', },
    {'Parla con Zeh\'gehn all\'Avamposto di Granfurto.', },
  },
  [11474] = {
    'Problemi in cima al promontorio',
    {'Come al solito, siamo io e la mia squadra a dover occuparci dei lavori che contano. Per fortuna, la squadra di McSorf non è morta invano. Il Cifrario che hanno recuperato ci aiuterà a decodificare le scritte che abbiamo trovato qui... sempre che riusciamo a raggiungerle di nuovo! Quei maledetti Nani del Ferro hanno invaso questo posto e ora vogliono riseppellire i siti! Riesci a crederci? Quei bastardi vogliono seppellire le nostre scoperte!|n|nVa\' a parlare con Walt, laggiù. Ti dirà cosa fare.', },
    {'Parla con Walt.', },
  },
  [11475] = {
    'I ferri del mestiere',
    {'$N, sono giorni che studio questo Costrutto Disattivato. Credo di poter creare un facsimile credibile del Golem, con dentro lo spazio per un passeggero. La mia idea è ingannare i Nani del Ferro per riuscire a entrare dentro Baelgun.|n|nNon riuscirò a concludere nulla con un martello e uno spuntone. Mi servono i miei attrezzi da lavoro! Sfortunatamente, li ho lasciati alle Rovine di Ivald quando i Nani del Ferro ci hanno attaccati la prima volta. Devi riportarmeli!|n|nLe Rovine di Ivald si trovano lontano a nord-est.', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di recuperare i suoi Attrezzi da Lavoro.', },
  },
  [11476] = {
    'Un taglione e un gracidone',
    {'Alcuni pirati di qui... usano un loro gergo speciale. Zeh\'gehn usa... molti gerghi diversi, mischiati insieme.|n|nDa quel che ho capito, vuole una rana e un coltello.|n|nHarry "Lunargenta" dovrebbe avere un coltello economico. Le rane si trovano in tutta la città: catturane una e portala a Zeh\'gehn insieme al coltello.|n|nNon vorrei proprio essere nei panni della povera bestia... non so se mi sono spiegato.', },
    {'Prendi un Coltello Lucente da Harry "Lunargenta" e cattura una Rana di Granfurto, poi porta tutto a Zeh\'Gehn nel Capo di Granfurto.', },
  },
  [11477] = {
    'Fuori dal mio elemento?',
    {'$R, abbassa la voce! I Nani del Ferro hanno il grilletto facile. Non lasciarti ingannare dalle attività negli scavi, questi abomini dalla pelle d\'acciaio non stanno estraendo un bel niente! $GNossignore:Nossignora;! Al contrario: stanno seppellendo il sito! Non si sa per quale stramaledetta ragione, ma vogliono che questo posto non venga scoperto da nessuno.|n|nQuale Nano che si rispetti seppellirebbe antiche reliquie e siti di scavo? Te lo dico io: il Nano che ucciderai senza pensarci due volte! Va\' lì e falli fuori!', },
    {'Donny alle Rovine di Ivald nel Fiordo Echeggiante ti ha chiesto di uccidere 10 Distruttori del Ferro Runico, 5 Braccianti del Ferro Runico e 2 Saggi del Ferro Runico.', },
  },
  [11478] = {
    'Quell\'Avamposto laggiù...',
    {'Non hai ancora incontrato i miei fratelli all\'Avamposto della Lega degli Esploratori, a sud di qui. Perché non fai un favore a Donny e recapiti questo messaggio a Stanwad? Sarà impaziente di sapere come procedono le attività dei Nani del Ferro.|n|nCome ti ho detto, salta in sella e dirigiti a sud. Vedrai l\'Avamposto appena prima di arrivare a Baelgun.', },
    {'Consegna la Lettera di Donny a Stanwad nell\'Avamposto della Lega degli Esploratori.', },
  },
  [11479] = {
    'Dan Gambacorvo',
    nil,
    nil,
  },
  [11480] = {
    'Incontro con la seconda in comando',
    {'$N, le tue gesta non sono passate inosservate. L\'adorabile Annie Bonn, nostra seconda in comando, è rimasta molto colpita da ciò che hai fatto finora e vuole incontrarti.', },
    {'Parla con Annie Bonn al Capo di Granfurto.', },
  },
  [11481] = {
    'Crisi al Pozzo Solare',
    {'In nome dei Naaru, $R, ti ringrazio per il tuo supporto.|n|nTuttavia, il nostro lavoro è ben lontano dall\'essere finito. Devo chiederti di intraprendere una missione di vitale importanza. Più di qualunque altra abbia mai intrapreso.|n|nLe nostre truppe sono sparpagliate. E come se non bastasse, abbiamo dovuto inviare un contingente su Azeroth per indagare sugli eventi della Cittadella del Pozzo Solare.|n|nÈ là che ho bisogno che tu vada, $N. Presentati a rapporto dal Capitano Theris Albafuoco. Digli che avrei voluto poter inviare più uomini.', },
    {'Adyen il Custode della Luce sul Poggio degli Aldor a Shattrath ti ha chiesto di recarti alla Cittadella del Pozzo Solare e di parlare con il Capitano Theris Albafuoco.', },
  },
  [11482] = {
    'Chiamata al dovere',
    {'Ascoltami, $R.|n|nÈ necessario che tu torni su Azeroth. Ogni elemento ritenuto idoneo deve presentarsi immediatamente a rapporto alla Cittadella del Pozzo Solare.|n|nTemo di non avere altre informazioni da fornirti, ad eccezione della seguente.|n|nParla con un Elfo del Sangue di nome Theris Albafuoco una volta sul posto.|n|nSembra che sia necessario mettere da parte le nostre divergenze, per questa volta, e fare fronte unito.|n|nPreparati. La situazione sembra piuttosto seria.', },
    {'Dathris Predasole nella Loggia dei Veggenti a Shattrath ha insistito perché tu vada subito su Azeroth e ti presenti a rapporto dal Capitano Theris Albafuoco al Pozzo Solare.', },
  },
  [11483] = {
    'Possiamo ricostruirlo',
    {'Attrezzi da lavoro? Ci sono. Materiali? Negativo.|n|nSe vogliamo costruire questo coso, devi portarmi i materiali.|n|nAndiamo con ordine: per la struttura scheletrica mi serve un Grosso Barile proveniente da Nifflevar, qualche Lingotto di Ferroscuro da Valguardia e una Corda Industriale da Baleheim.|n|nNifflevar e Baleheim sono due città dei Vrykul a nord-ovest. Valguardia si trova nella Baia delle Daghe, anch\'essa a nord-ovest. Parla con McGoyver per ottenere i lingotti: quando avrai finito, ti riporterà qui in volo.', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di portargli un Grosso Barile, una Corda Industriale e alcuni Lingotti di Ferroscuro.', },
  },
  [11484] = {
    'Abbiamo la tecnologia',
    {'In un macchinario come questo, la struttura portante è importante, ma non dobbiamo sottovalutare l\'aspetto del Costrutto. Se vogliamo ingannare i Nani del Ferro, la replica deve essere perfetta!|n|nPosso farcela.|n|nPortami la Pelle Primeva di uno Zannapiatta di questa regione e una Nervatura d\'Acciaio dei Vrykul di Nifflevar o Baleheim a nord-ovest.', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di portargli una Pelle Primeva di Zannapiatta e una Nervatura d\'Acciaio.', },
  },
  [11485] = {
    'Tu e i Costrutti del Ferro Runico: Salto Propulsivo',
    nil,
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare l\'abilità Salto Propulsivo del Costrutto del Ferro Runico con la Runa di Ferro incisa da lui.|n|nQuando avrai compiuto la missione, congeda il Costrutto nella finestra del famiglio.', },
  },
  [11488] = {
    'Terrazza dei Magisteri',
    {'Ti do il benvenuto al Pozzo Solare, $C. Ambientati e aiutaci come puoi. C\'è molto da fare!|n|nIo? Sì, io ho qualcosa da fare, ma non so se tu puoi aiutarmi.|n|nAvevamo un contatto alla Terrazza dei Magisteri che raccoglieva informazioni per noi. Ultimamente non sta più facendo rapporto, e inizio a preoccuparmi.|n|nLa terrazza è subito sull\'altura a est. Le informazioni che stava raccogliendo sono fondamentali per la nostra missione.|n|nPensi di farcela, $R?', },
    nil,
  },
  [11489] = {
    'Tu e i Costrutti del Ferro Runico: Raccolta Dati',
    {'Mentre sei al comando del Costrutto, la parte più importante del tuo lavoro è la raccolta dei dati. Ho posizionato una Reliquia dei Nani del Ferro in quel carrello laggiù. Si tratta di un cristallo volante, infuso di luce.|n|nSali sul banco da lavoro e ti riposizionerò all\'interno del Costrutto. Quando sarai nuovamente sul sedile del pilota, usa l\'abilità Raccolta Dati del Costrutto per ottenere i dati di prova.', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare l\'abilità Raccolta Dati del Costrutto del Ferro Runico mentre ti trovi davanti alla Reliquia dei Nani del Ferro.|n|nQuando avrai compiuto la missione, congeda il Costrutto nella finestra del famiglio.', },
  },
  [11490] = {
    'La sfera del Veggente',
    nil,
    {'Tyrith ti ha chiesto di usare la sfera sulla balconata della Terrazza dei Magisteri.', },
  },
  [11491] = {
    'Tu e i Costrutti del Ferro Runico: Inganno',
    {'Devi sempre avere un piano di riserva, nel caso quello principale fallisse! Per questo ho incluso alcuni sistemi anti-rilevamento nel Costrutto.|n|nMentre ti troverai agli Scavi di Baelgun, il tuo nuovo mezzo scintillante potrebbe destare qualche sospetto. A questo serve l\'abilità Inganno! Usala ogni volta che vieni affrontato e non subirai alcun danno.|n|nPer provarla, cammina sul tappeto di Lebronski. Appena inizia ad andare su di giri, usa l\'Inganno!|n|nQuando sei $Gpronto:pronta; per iniziare, sali sul banco da lavoro.', },
    nil,
  },
  [11492] = {
    'Duro da uccidere',
    nil,
    nil,
  },
  [11493] = {
    'NON USATO',
    nil,
    nil,
  },
  [11494] = {
    'Reliquie Infuse di Luce',
    {'Il tuo Costrutto è pronto a entrare in azione. Hai provato tutte le abilità e l\'ho programmato per comprendere e parlare la lingua dei Titani.|n|nPortalo agli Scavi di Baelgun, a sud di qui, e raccogli i dati sulle Reliquie Infuse di Luce che abbondano in quel luogo. Ricorda di ingannare i Nani del Ferro che potrebbero sospettare dell\'autenticità del tuo Costrutto. Infine, non dimenticare di usare il Salto Propulsivo da una Runa all\'altra per spostarti!|n|nQuando sei $Gpronto:pronta;, sali sul banco da lavoro!', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare l\'abilità Raccolta Dati del Costrutto del Ferro Runico per raccogliere 15 Set di Dati delle Rune di Ferro.|n|nQuando avrai compiuto la missione, congeda il Costrutto nella finestra del famiglio.', },
  },
  [11495] = {
    'Il delicato fragore del tuono',
    {'La caverna che abbiamo aperto a Baelgun era l\'unico posto dal quale tutti si tenevano alla larga... e avevano ragione! $N, da quella grotta è scaturito un tuono! Un tuono fragoroso e assordante!|n|nVerso la fine, credo sia stata abbandonata da tutti. A chi si è avventurato nell\'esplorazione, sono capitate cose molto brutte. Molti non sono mai tornati indietro.|n|nEsamina la grotta mentre ti trovi a Baelgun. Esplora l\'interno, intorno alla Statua del Titano, e torna a riferirmi ciò che hai scoperto.', },
    {'Walt all\'Avamposto della Lega degli Esploratori nel Fiordo Echeggiante ti ha chiesto di usare il Costrutto del Ferro Runico per esplorare la Grotta Tonante agli Scavi di Baelgun.|n|nQuando avrai compiuto la missione, congeda il Costrutto nella finestra del famiglio.', },
  },
  [11496] = {
    'Le difese del Santuario',
    {'La nostra priorità è conquistare il Santuario di Approdo del Sole. Poi saremo in grado di utilizzare la sua energia per aprire un portale da Shattrath.|n|nIl santuario è infestato dai Miserabili, un tempo Elfi del Sangue ma ormai soltanto folli simulacri della loro passata natura. In condizioni normali le difese del santuario avrebbero impedito questa intrusione, ma i Miserabili hanno rubato le fonti di energia dei Cristalli Difensivi.|n|nElimina i Miserabili e prendi i residui di mana in loro possesso. Usali per energizzare i Cristalli Difensivi.', },
    {'Il Capitano Theris Albafuoco alla Base Operativa del Sole Infranto ti ha chiesto di recuperare 4 Residui di Mana dai Demoni Miserabili e dai Divoratori Miserabili e di usarli per energizzare uno dei Cristalli Difensivi che circondano le strutture ad Approdo del Sole.', },
  },
  [11498] = {
    nil,
    {'Anche se alla lunga potrebbe danneggiare i miei affari, mi sembri una persona che sogna di volare tra le nuvole sulla propria cavalcatura piuttosto che farsi trasportare da un posto all\'altro.|n|nTi capisco perfettamente.|n|nTu, $Gamico mio:amica mia; devi andare al Villaggio di Torvaluna nell\'angolo nordoccidentale della Valle di Torvaluna. Una volta là, parla con Olrokk per avere lezioni di volo. Ricorda, però, che il suo addestramento non è a buon mercato. Penso, tuttavia, che scoprirai che ne vale la pena.', },
    {'Parla con Olrokk al Villaggio di Torvaluna nella Valle di Torvaluna.', },
  },
  [11499] = {
    'Ricercato: Anello con Sigillo del Principe Kael\'thas',
    {'$C, oggi ti chiedo l\'impossibile. Devi recuperare l\'Anello con Sigillo di Kael\'thas Solealto, il Signore degli Elfi del Sangue!|n|nÈ vero, le voci sulla sua morte a Forte Tempesta erano infondate, tant\'è che si è rifatto vivo, questa volta alla Terrazza dei Magisteri sull\'Isola di Quel\'Danas. Cosa ci faccia lì, non ti saprei proprio dire. Quello che so è che ho una fila di collezionisti interessati al suo anello e voglio procurarmelo.|n|nO meglio, voglio che tu me lo procuri.', },
    {'Il Commerciante del Vento Zhareem ti ha chiesto di recuperare l\'Anello con Sigillo del Principe Kael\'thas. Consegnaglielo nella Città Bassa di Shattrath per ricevere la ricompensa.|n|nQuesta missione può essere completata solo alla Terrazza dei Magisteri in modalità Eroica.', },
  },
  [11500] = {
    'Ricercate: Sorelle del Tormento',
    {'Un sussurro ha ordinato a Mah\'duun che le Sorelle del Tormento vanno ricacciate negli inferi da cui sono arrivate.|n|nMah\'duun sa che questi demoni possono essere trovati alla Terrazza dei Magisteri sull\'Isola di Quel\'Danas.|n|nUccidili e avrai la taglia; non farlo e resterai a mani vuote.', },
    {'Mah\'duun l\'Inseguitore Fatuo ti ha chiesto di uccidere 4 Sorelle del Tormento. Quando saranno tutte morte, torna da lui nella Città Bassa di Shattrath per ricevere la taglia.', },
  },
  [11501] = {
    'Novità da est',
    {'$N, Guardia dell\'Ovest deve sapere cosa sta succedendo quaggiù. Voglio che tu riferisca personalmente le novità al Capitano Adams.|n|nFammi sapere quando sarai $Gpronto:pronta; e ti riposizionerò all\'interno del Costrutto per un ultimo volo. Ti porterà al Forte di Guardia dell\'Ovest... o, più probabilmente, esploderà in volo.|n|nÈ stato bello conoscerti...', },
    {'Parla con il Capitano Adams al Forte di Guardia dell\'Ovest.', },
  },
  [11502] = {
    'In difesa di Halaa',
    {'$R, non siamo una razza di guerrieri. Tuttavia, quando la guerra arriverà nella nostra terra, non ci nasconderemo.|n|nL\'Alleanza e l\'Orda si affrontano nella città di Halaa, a nord-ovest. Non sappiamo cosa stiano complottando gli Elfi del Sangue, ma qualsiasi vittoria dell\'Orda porterà a un disastro. In passato, ogni incontro con gli Orchi è finito nel sangue e nel tradimento.|n|nUccidi il nemico a Halaa e ti ricompenseremo con denaro, onore e gloria.', },
    {'Sconfiggi 10 giocatori nemici a Halaa e torna da Lakoor a Telaar.', },
  },
  [11503] = {
    'Nemici vecchi e nuovi',
    {'I nostri antichi nemici, i Draenei, sono tornati con potenti alleati. Combattono a Halaa, a sud-ovest di qui.|n|nNon possiamo permettergli di vincere o Garadar sarà il loro prossimo obiettivo.|n|nVai a uccidere tutti gli alleati dei nostri antichi nemici.', },
    {'Sconfiggi 10 giocatori nemici a Halaa e torna da Karrtog a Garadar.', },
  },
  [11504] = {
    'I morti risorgono!',
    {'Il sentiero a est è uno dei principali percorsi di caccia dei Tuskarr. O perlomeno lo era...|n|nDi recente, i nostri cacciatori sono tornati a Kamagua dicendo che i morti sono risorti e sono assetati di sangue! Per questo io e mio figlio siamo qui: l\'Anziano Atuik ci ha chiesto di trovare una soluzione.|n|nCi darai una mano nel momento del bisogno? Ho bisogno di eroi disposti ad affrontare i pericoli del Colle degli Scudi a sud-est. Cerca degli indizi nelle tombe profanate, poi torna a riferirmi ciò che hai scoperto.', },
    {'Orfus di Kamagua alla Funivia Antica nel Fiordo Echeggiante ti ha chiesto di trovare l\'Indizio di Fengir, l\'Indizio di Rodin, l\'Indizio di Isuldof e l\'Indizio di Windan.', },
  },
  [11505] = {
    'Spiriti di Auchindoun',
    {'Gli Spiriti di Auchindoun non sono coinvolti del conflitto tra l\'Alleanza e l\'Orda, ma guadagnare il loro favore darà alla nostra fazione un vantaggio nella regione.|n|nLe antiche usanze impongono ai vivi di porgere i loro rispetti alle Torri dello Spirito nelle Distese d\'Ossa, ma in momenti specifici della giornata. Se riuscirai a mantenere al sicuro una torre durante questi momenti, contribuirai a portare gli spiriti dalla nostra parte.|n|nSe questo dovesse succedere, essi ci concederanno un dono che ci aiuterà nei nostri sforzi.', },
    {'Aiuta l\'Alleanza a mettere al sicuro una torre nelle Distese d\'Ossa.', },
  },
  [11506] = {
    'Spiriti di Auchindoun',
    {'I Draenei magari sono nemici nuostr\', ma li spiriti delli antenati loro nun tengono pace e manco colpe.|n|nSecondo i costumi Draenei, devono porgere li ossequi loro alle Torri dello Spirito varie volte al giorno. Se riesci a tenere sicure le torri in chesti momenti, aiuterai li spiriti a tornare in pace ad Auchindoun.|n|nL\'Alleanza proverà a conquistare le torri per assicurarsi il favore dei morti. E invece siamo noi che dobbiamo vincere.', },
    {'Aiuta l\'Orda a mettere al sicuro una Torre degli Spiriti nelle Distese d\'Ossa.', },
  },
  [11507] = {
    'Atuik l\'Anziano',
    {'<Orfus raduna gli indizi che gli hai portato.>|n|nPurtroppo, il mio popolo è costretto a una guerra contro i Filibustieri dei Mari del Nord. Se c\'è un Tuskarr che può aiutarci a raddrizzare i torti dei pirati, quello è l\'Anziano Atuik di Kamagua. Portagli subito questi indizi.|n|nLa Funivia Antica alle mie spalle ti porterà direttamente a Kamagua. Una volta lì, cerca l\'Anziano Atuik.', },
    {'Orfus di Kamagua nel Fiordo Echeggiante ti ha chiesto di consegnare il Pacchetto di Orfus all\'Anziano Atuik di Kamagua.', },
  },
  [11508] = {
    'Grezzix Giramorsa',
    {'I pirati hanno costruito un porto presso il Capo di Granfurto, molto a sud di qui. Sfortunatamente, lo hanno fortificato con un gran numero di difese letali.|n|nC\'è solo una persona che può aiutarci a entrare a Granfurto.|n|nSi tratta di un pirata mercenario di nome Grezzix Giramorsa. Ultimamente, è venuto nel nostro villaggio in cerca di cibo e riparo. In cambio, ci fornirà delle informazioni sui nostri nemici e li svierà con dei falsi piani d\'attacco. Cercalo sulla sua nave, attraccata davanti alla costa a sud-ovest.', },
    {'Parla con Grezzix Giramorsa.', },
  },
  [11509] = {
    'Una questione di rispetto',
    nil,
    nil,
  },
  [11510] = {
    'Scoodles',
    nil,
    nil,
  },
  [11511] = {
    'Il Bastone della Furia Tempestosa',
    nil,
    nil,
  },
  [11512] = {
    'Il Cuore Gelido di Isuldof',
    {'Secondo alcuni, Jonas è sempre stato un po\' toccato. Io però so la verità: è colpa del cuore, il maledetto Cuore Gelido di Isuldof! Ho visto cambiare Jonas nel secondo esatto in cui lo ha estratto dalla tomba. Ho visto il suo sangue gelare nelle vene... e la pazzia che si impossessava di lui.|n|nCi ha abbandonati a morire nella sua grotta sul lato nord dell\'isola. Da quel che ho sentito, ha gettato il cuore sul retro del suo covo, ma ormai era troppo tardi...|n|nSe solo ti azzardi a riportare qui il cuore, ti uccido con le mie mani!', },
    {'Recupera il Cuore Gelido di Isuldof e portalo a Orfus di Kamagua nel Fiordo Echeggiante.', },
  },
  [11513] = {
    'Intercettare le batterie di mana',
    {'Ho pensato a un piano per ottenere una fonte di energia abbastanza potente per creare il nostro portale.|n|nLe forze degli Eterei presso l\'Approdo di Bash\'ir, in cima alle Montagne Spinaguzza nordoccidentali, contrabbandano batterie di mana da Forte Tempesta e le portano al Pozzo Solare per Kael\'thas.|n|nHanno nascosto le batterie, ma c\'è un modo per trovarle: gli Eterei hanno degli apparecchi fasici che puoi utilizzare per individuare la merce di contrabbando.|n|nMa fai attenzione ai Dragoni Fasici a guardia delle batterie di mana.', },
    {'Recupera 10 Batterie di Mana di Contrabbando e portale all\'Esarca Nasuun nella Terrazza della Luce a Shattrath.', },
  },
  [11514] = {
    'Alimentare il portale per il Pozzo Solare',
    {'Dobbiamo alimentare l\'energia del nostro portale o collasserà. Le batterie di mana che gli Eterei all\'Approdo di Bash\'ir hanno nascosto potrebbero servire al nostro scopo. L\'approdo si trova sull\'angolo nordoccidentale delle Montagne Spinaguzza, all\'estremo nord.|n|nRicorda, prendi un apparecchio fasico a uno degli Eterei e usalo per individuare la merce di contrabbando.|n|nFa\' solo attenzione ai Dragoni Fasici che usano come guardiani delle batterie.', },
    {'Recupera 10 Batterie di Mana di Contrabbando e portale all\'Esarca Nasuun nella Terrazza della Luce a Shattrath.', },
  },
  [11515] = {
    'Sangue chiama sangue',
    {'Quando le forze di Kael si sono ritirate attraverso quel portale, i suoi tirapiedi più fedeli sono stati ricompensati con un dono abominevole. Sono rimasti indietro e hanno bevuto per giorni il sangue dei demoni.|n|nIl sangue li ha cambiati, dando loro nuovi poteri. Ma sarà anche la loro rovina.|n|nRaccogli dei campioni di sangue da altri demoni. Usali per alimentare questo Vilaspiratore e privare quegli stolti arroganti dei loro nuovi poteri. Uccidili mentre sono indeboliti e torna da me.', },
    {'La Magistra Seyla al Trono di Kil\'jaeden ti ha chiesto di uccidere 4 Vilsangue Indeboliti utilizzando il Vilaspiratore su di loro. Per alimentare il Vilaspiratore avrai bisogno di Sangue di Demone dai vicini Alfieri dell\'Ira.', },
  },
  [11516] = {
    'Distruggere il varco',
    {'Dobbiamo distruggere questo varco per impedire l\'arrivo dei rinforzi della Legione sull\'Isola di Quel\'Danas.|n|nPrendi queste braci, contengono una delle mie creazioni: una Fiammella Vivente. È progettata per agire come una potente forza distruttiva, posto che sia stata dotata di energia a sufficienza.|n|nTrova le Vilscintille che infestano l\'area e uccidile vicino alla Fiammella Vivente. Essa assorbirà ogni volta il potere, fino a diventare instabile.|n|nA questo punto accompagnala al varco. Essa saprà cosa fare.', },
    {'La Magistra Seyla al Trono di Kil\'jaeden ti ha chiesto di usare le Braci Sfrigolanti per evocare una Fiammella Vivente e uccidere le Vilscintille Incandescenti vicino a essa fino a farla diventare una Fiammella Vivente Instabile. Torna al Varco della Legione con la Fiammella Vivente Instabile per distruggerlo.', },
  },
  [11517] = {
    'Rapporto a Nasuun',
    {'Sono felice che tu sia qui, $C! Ora che ci siamo impadroniti di questo santuario, dobbiamo affrettarci a creare un portale magico che ci colleghi a Shattrath nelle Terre Esterne.|n|nIl mio signore, l\'Esarca Nasuun, sta coordinando gli sforzi dell\'offensiva in questa direzione. Mi ha chiesto di inviargli i candidati promettenti, quelli in grado di aiutare a creare il portale.|n|nRaggiungi Shattrath e parla con lui nella Sala di A\'dal nella Terrazza della Luce.', },
    {'Il Commerciante Portanuus ti ha chiesto di parlare con l\'Esarca Nasuun nella Terrazza della Luce a Shattrath.', },
  },
  [11519] = {
    'Lo Scudo Perduto degli Esiriti',
    {'Se ascolti attentamente, puoi sentire dei colpi di cannone provenire da nord-est. È la nave del Capitano Ellis, la Sorella Pietà. Il problema è che Ellis e tutta la sua ciurma sono stati uccisi circa un mese fa.|n|n<Harry annuisce.>|n|nUna nave fantasma...|n|nSe vuoi informazioni sullo scudo, devi chiedere a Ellis.|n|nOgni cinque minuti, la Sorella Pietà fa scalo nell\'isoletta a metà strada fra qui e la Costa di Sorlof per arruolare altre anime. Da queste parti le anime non mancano mai...', },
    {'Parla con il Capitano Ellis a bordo della Sorella Pietà.', },
  },
  [11520] = {
    'Alla scoperta delle tue radici',
    {'Salute, $R.|n|nTemo di avere poco da offrirti qui, finché non avrò i miei reagenti.|n|nTra i rifornimenti di cui ho bisogno c\'è un reagente speciale, la radice di Tranciaspina, che è particolarmente difficile da raccogliere.|n|nPer fortuna conosco un segreto...|n|nUsando le ghiandole degli Scorticatori di Tranciaspina è possibile controllare lì un devastatore e impiegarlo per trovare una radice.|n|nPer recuperare le radici, raggiungi le Terre Esterne e vola a nord-est da Shattrath fino all\'Altopiano di Tranciaspina.', },
    {'Mar\'nah al Porto di Approdo del Sole ti ha chiesto di raggiungere l\'Altopiano di Tranciaspina nelle Terre Esterne, trovare 5 Radici di Tranciaspina e tornare da lei.', },
  },
  [11521] = {
    'Alla riscoperta delle tue radici',
    {'Al momento le mie scorte sono sufficienti, ma ho sempre bisogno di molte radici di Tranciaspina per far fronte alla richiesta.|n|nRaccogliere le radici è difficile, ma io conosco un metodo speciale di estrazione.|n|nUsando le ghiandole degli Scorticatori di Tranciaspina è possibile controllare un devastatore e usarlo per trovare una radice.|n|nPer recuperare le radici, raggiungi le Terre Esterne e vola a nord-est da Shattrath fino all\'Altopiano di Tranciaspina.|n|n$N, torna da me quando avrai raccolto cinque radici.', },
    {'Mar\'nah al Porto di Approdo del Sole ti ha chiesto di raggiungere l\'Altopiano di Tranciaspina nelle Terre Esterne, trovare 5 Radici di Tranciaspina e tornare da lei.', },
  },
  [11523] = {
    'Armare le difese!',
    {'Siamo riusciti a riattivare i Cristalli Difensivi intorno al santuario, ma perché fermarci qui? Costruiremo difese intorno alle altre strutture, ma i Miserabili sono ostinati e continuano a sottrarre energia ai Cristalli Difensivi.|n|nUccidili e prendi i residui di mana che trasportano. Usali quindi per energizzare i Cristalli Difensivi. La sicurezza della nostra operazione dipende da questo.', },
    {'Il Capitano Theris Albafuoco alla Base Operativa del Sole Infranto ti ha chiesto di recuperare 4 Residui di Mana dai Demoni Miserabili e dai Divoratori Miserabili e di usarli per energizzare uno dei Cristalli Difensivi che circondano le strutture ad Approdo del Sole.', },
  },
  [11525] = {
    'Ulteriori conversioni',
    {'Il mio piano di sostituire i cristalli danneggiati degli Avvistatori Erranti è stato un successo. Con il loro aiuto siamo riusciti a conquistare il Santuario di Approdo del Sole.|n|nHo realizzato altri cristalli che ci permetteranno di controllarne altri; posizionali all\'interno degli avvistatori sconfitti. Una volta convertiti, li schiereremo su altri fronti.', },
    {'La Vendicatrice Xayann alla Base Operativa del Sole Infranto ti ha chiesto di posizionare i Nuclei di Cristallo Armonizzati dentro 5 Avvistatori Erranti sconfitti per trasformarli in unità amiche.', },
  },
  [11526] = {
    'La magistra scomparsa',
    {'Abbiamo inviato una delle nostre agenti a indagare sul Vilportale in Piazza dell\'Alba, a sud di qui. Non è mai tornata.|n|nPrendi questa pergamena che abbiamo trovato su uno dei cadaveri dei nemici. Pensiamo che ti permetterà di accedere al portale. Una volta dentro, trova la Magistra Seyla e fai di tutto per aiutarla.', },
    {'Usa la Pergamena Sottratta alla Legione vicino al portale in Piazza dell\'Alba. Una volta attraversato il portale, trova la Magistra Seyla.', },
  },
  [11527] = {
    'L\'ammutinamento della Pietà',
    nil,
    nil,
  },
  [11528] = {
    'Un regalo di Grande Inverno',
    nil,
    nil,
  },
  [11529] = {
    'Il tesoro di Sorlof',
    {'La ciurma sta preparando il Bombardone apposta per te, $Gcompagno:compagna;. Ora riposa tranquillo nella linea di prua, dall\'altra parte della nave. Vai e preparati a sparare appena Sorlof sarà in vista!|n|nQuando avremo eliminato quel marinaio d\'acqua dolce, dovrai recuperare il tesoro. Come vedi, non possiamo lasciare questa stramaledettissima nave! Riportami il tesoro e avrai la tua parte: lo Scudo.', },
    {'Usa il Bombardone per uccidere Sorlof, dopodiché prendi il suo tesoro e portalo al Capitano Ellis a bordo della Sorella Pietà.', },
  },
  [11530] = {
    'Lo Scudo degli Esiriti',
    {'Ecco il tuo scudo. Spero che non ti maledica come ha fatto con me e la mia ciurma. Mi dispiace, ma non puoi restare con noi... Sono sicuro che c\'è qualcuno interessato a riaverlo indietro.|n|nOra porta via quell\'affare dalla mia nave!', },
    {'Porta lo Scudo degli Esiriti a Orfus di Kamagua nella Funivia Antica del Fiordo Echeggiante.', },
  },
  [11531] = {
    'Pezzo di motore bizzarro',
    {'<Questo pezzo di motore bizzarro non sembra appartenere alla Pompa del Vapore. Forse K. Lee Fray potrebbe saperne qualcosa.>', },
    {'Porta il Pezzo di Motore Bizzarro a K. Lee Fray presso Telredor.', },
  },
  [11532] = {
    nil,
    nil,
    {'La Maga Guerriera Arynna ti ha chiesto di parlare con Ayren Franginuvole quando desideri sorvolare la Fenditura Morta. Una volta lì, usa le Cariche Arcane per uccidere 2 Supremi della Fossa, 3 Occultisti Eredar e 12 Scagnozzi dell\'Ira.', },
  },
  [11533] = {
    'Gli attacchi aerei devono continuare',
    {'Abbiamo sottratto l\'armeria al nemico grazie ai nostri attacchi aerei contro le forze della Legione nella Fenditura Morta.|n|nIl risultato è stato talmente un successo che proseguiremo le nostre incursioni. Prendi queste cariche arcane e usale contro le loro forze.|n|nParla con Ayren Franginuvole al Porto di Approdo del Sole, quando vuoi partire.', },
    {'La Maga Guerriera Arynna ti ha chiesto di parlare con Ayren Franginuvole quando desideri sorvolare la Fenditura Morta. Una volta lì, usa le Cariche Arcane per uccidere 2 Supremi della Fossa, 3 Occultisti Eredar e 12 Scagnozzi dell\'Ira.', },
  },
  [11534] = {
    'Rapporto a Nasuun',
    {'Sono felice che tu sia qui, $C! Quando abbiamo strappato questo santuario ai Miserabili ci siamo affrettati a creare un portale magico che conduce qui da Shattrath nelle Terre Esterne.|n|nIl mio signore, l\'Esarca Nasuun, sta coordinando gli sforzi dell\'Offensiva per mantenere il portale attivo. Mi ha chiesto di inviargli i candidati promettenti, quelli in grado di aiutare ad acquisire altra energia per farlo.|n|nRaggiungi Shattrath e parla con lui nella Sala di A\'dal nella Terrazza della Luce.', },
    {'Il Commerciante Portanuus ti ha chiesto di parlare con l\'Esarca Nasuun nella Terrazza della Luce a Shattrath.', },
  },
  [11535] = {
    nil,
    nil,
    {'Hauthaa all\'Armeria di Approdo del Sole ti ha chiesto di uccidere i Mirmidoni Liscanera a est e di usare le loro chiavi per rubare tre campioni di minerale dalle loro casse.', },
  },
  [11536] = {
    'Non fermarti adesso...',
    {'Ora che abbiamo un\'incudine, posso mettermi seriamente al lavoro.|n|nNon importa quanti rifornimenti otterremo, sarò sempre in grado di utilizzare al meglio il minerale di ferro dei Liscanera. Se vogliamo vincere questa guerra avremo bisogno di un rifornimento costante di armi e armature.|n|nSulla costa a est di qui c\'è un gruppo di Naga che sta raccogliendo minerale che mette in casse da inviare alla Legione.|n|nImpadronirsi di quel minerale sarebbe utile alla nostra causa in molteplici modi...', },
    {'Hauthaa all\'Armeria di Approdo del Sole ti ha chiesto di uccidere i Mirmidoni Liscanera a est e di usare le loro chiavi per rubare tre campioni di minerale dalle loro casse.', },
  },
  [11537] = {
    'La battaglia deve continuare',
    {'Dobbiamo continuare a sconfiggere e demoralizzare gli eserciti della Legione.|n|nGli Emissari dell\'Odio sono stati inviati dalla Legione per proteggere le sue postazioni strategiche. Il nemico si raduna intorno a loro perché li teme più di quanto non tema noi.|n|nOggi faremo in modo che tutto questo cambi. Prendi questo stendardo ed elimina i demoni della Legione. Quando trovi l\'Emissario, uccidilo e impalalo.', },
    {'L\'Araldo Inuuro ti ha chiesto di uccidere 6 Demoni della Legione Infuocata e l\'Emissario dell\'Odio a Piazza dell\'Alba. Usa lo Stendardo del Sole Infranto per impalare il cadavere dell\'Emissario dell\'Odio.', },
  },
  [11539] = {
    'Conquistare il porto',
    {'Una delle forze migliori di Kael, l\'esercito della Lama d\'Aurora, è stanziata al Porto di Approdo del Sole e a Stella dell\'Alba.|n|nIl porto è fondamentale per i nostri piani, dunque qualunque perdita che infliggerai alla Lama d\'Aurora sarà di grande aiuto. Kael\'thas maledirà il giorno in cui ha voltato le spalle alla sua gente per schierarsi con la Legione Infuocata.', },
    {'Il Magistro Ilastar all\'Armeria di Approdo del Sole ti ha chiesto di uccidere 6 Evocatori della Lama d\'Aurora, 6 Cavalieri del Sangue della Lama d\'Aurora e 3 Tiratori della Lama d\'Aurora.', },
  },
  [11540] = {
    'Annienta la Lama d\'Aurora',
    {'Abbiamo cacciato dal Porto di Approdo del Sole l\'esercito della Lama d\'Aurora. Tutto Approdo del Sole è nostro. Eppure... non sono del tutto soddisfatto.|n|nVoglio che ti rechi a Stella dell\'Alba, a ovest di qui, e uccida tutti i soldati della Lama d\'Aurora rimasti in vita. Il loro destino era segnato appena hanno seguito Kael qui.', },
    {'Il Magistro Ilastar all\'Armeria di Approdo del Sole ti ha chiesto di uccidere 6 Evocatori della Lama d\'Aurora, 6 Cavalieri del Sangue della Lama d\'Aurora e 3 Tiratori della Lama d\'Aurora.', },
  },
  [11541] = {
    'Distruggi la Costa dei Branchiaverde',
    {'I Naga hanno conquistato la Costa dei Branchiaverde a sud-est. Le loro femmine, le Sirene Liscanera, stanno utilizzando la magia per ridurre in schiavitù i Murloc del luogo.|n|nÈ mio dovere assicurarmi che qualunque cosa i Naga stiano facendo laggiù, venga fermata. E qui entri in gioco tu.|n|n$C, voglio che prendi le sfere di controllo alle Naga femmine e le getti vicino agli schiavi Branchiaverde, rompendole e liberando i Murloc.|n|nCredo che i Murloc si infurieranno e si rivolteranno contro i loro padroni.', },
    {'Il Capitano Valindria ti ha chiesto di liberare 10 Schiavi Branchiaverde. Quando hai finito, torna da lei a bordo dell\'Orgoglio di Lunargenta al Porto di Approdo del Sole.', },
  },
  [11542] = {
    'Intercetta i rinforzi',
    {'Ci stiamo impegnando a rafforzare il nostro controllo su Approdo del Sole conquistando il porto. Purtroppo una flotta di Riservisti della Lama d\'Aurora sta arrivando in supporto alle forze di Kael.|n|nPrendi quest\'olio e fatti dare un dragofalco da Ayren Franginuvole. Dovresti riuscire a raggiungere in volo le vele delle navi; quando sei abbastanza vicino, dai loro fuoco.|n|nAtterra su una delle navi e attacca i Riservisti. Con le vele della loro nave in fiamme non saranno in grado di difendersi a lungo.', },
    {'Il Vendicatore Kaalan all\'Armeria di Approdo del Sole ti ha chiesto di parlare con Ayren Franginuvole e di volare sulla flotta dei rinforzi della Lama d\'Aurora. Usa l\'Olio Infiammabile per incendiare le vele della nave mentre sei in volo e, dopo essere atterrato, uccidi 6 Riservisti della Lama d\'Aurora.', },
  },
  [11543] = {
    'Tenere a bada i nemici',
    {'Siamo riusciti a conquistare tutto l\'Approdo del Sole. Purtroppo, una flotta di Riservisti della Lama d\'Aurora sta arrivando a riprendersi il porto.|n|nPrendi quest\'olio e fatti dare un dragofalco da Ayren Franginuvole. Dovresti riuscire a raggiungere in volo le vele delle navi; quando sei abbastanza vicino, dai loro fuoco.|n|nAtterra su una delle navi e attacca i Riservisti. Con le vele della loro nave in fiamme non saranno in grado di difendersi a lungo.', },
    {'Il Vendicatore Kaalan all\'Armeria di Approdo del Sole ti ha chiesto di parlare con Ayren Franginuvole e di volare sulla flotta dei rinforzi della Lama d\'Aurora. Usa l\'Olio Infiammabile per incendiare le vele della nave mentre sei in volo e, dopo essere atterrato, uccidi 6 Riservisti della Lama d\'Aurora.', },
  },
  [11544] = {
    'Armamenti di Ata\'mal',
    {'La Terrazza di Ata\'mal nella zona orientale della Valle di Torvaluna è sacra per i Draenei, ma ora è invasa dai Vilorchi. Hanno estratto il minerale speciale di quella zona e realizzato armi e armature corrotte.|n|nHo bisogno degli armamenti per creare una lega con il minerale dei Naga. I nostri anacoreti hanno benedetto la mia incudine con la capacità di purificarli.|n|nPrendi gli armamenti dei Prescelti di Torvaluna, dei Sicari di Torvaluna e dei Mistici Oscuri di Torvaluna. Portali qui, scomponili e purificali sulla mia incudine e poi dammi quello che ottieni.', },
    {'Hauthaa ti ha chiesto di creare 5 Pezzi di Metallo Ata\'mal Purificato. Fallo scomponendo gli Armamenti di Ata\'mal sulla sua incudine presso l\'Armeria di Approdo del Sole sull\'Isola di Quel\'Danas.', },
  },
  [11545] = {
    nil,
    nil,
    {'L\'Anacoreta Ayuri ad Approdo del Sole ti ha chiesto di donare 10 monete d\'oro.', },
  },
  [11546] = {
    'In piena attività',
    {'Salute, $N.|n|nPosso aiutarti in molti modi nel corso delle tue imprese qui.|n|nPer esempio, ho scoperto di recente una ricetta per un elisir davvero unico.|n|nLa baccasangue cresce spontaneamente in molte regioni di Azeroth ed è sempre stata considerata solo una seccatura. Ma ho scoperto che se viene esposta al potere del Pozzo Solare, questa pianta acquisisce delle speciali proprietà che possono essere distillate e bevute per potenziare le proprie abilità.|n|nPortamene un po\' dai cespugli nelle vicinanze e ti spiegherò cosa intendo.', },
    {'Mar\'nah al Porto di Approdo del Sole ti ha chiesto di raccogliere 5 Bacchesangue dai cespugli di Quel\'Danas.', },
  },
  [11547] = {
    'Conoscere le linee di faglia',
    {'Sanguisughe!|n|nVolete tutti essere soddisfatti subito e non pensate mai a quanto sia complicato creare anche il portale più semplice.|n|nForse un po\' di cultura farà nascere in voi un po\' di gratitudine per i miei sforzi incessanti.|n|nPrendi questo cristallo. Sintonizzalo con il Cristallo di Sangue a ovest, con il portale di Piazza dell\'Alba a sud di qui e con il santuario dei Naga sulla Costa dei Branchiaverde a sud-est.|n|nForse allora apprezzerete le vostre preziose traslocazioni...', },
    {'L\'Astromante Darnarian nel Santuario di Approdo del Sole ti ha chiesto di usare il Cristallo dell\'Astromante al Cristallo del Sangue, al Portale di Piazza dell\'Alba e al Santuario dei Naga sulla Costa dei Branchiaverde.', },
  },
  [11548] = {
    'Il tuo continuo sostegno',
    {'Abbiamo costruito un monumento per commemorare i caduti. Magra consolazione per chi ha perso in battaglia qualcuno che amava.|n|nSto raccogliendo del denaro per aiutare i figli e le mogli dei nostri eroi di guerra. Se potessi fare una piccola donazione, sarebbe di grande aiuto.', },
    {'L\'Anacoreta Ayuri ad Approdo del Sole ti ha chiesto di donare 10 monete d\'oro.', },
  },
  [11549] = {
    'Un benefattore magnanimo',
    {'Hai fatto tanto per noi, $N. Il tuo aiuto è davvero apprezzato.|n|nForse sei a conoscenza degli sforzi dell\'Anacoreta Ayuri. Ha un grande cuore e la sua credibilità è notevole, ma le donazioni non rispecchiano le sue aspettative.|n|nSe volessi dare un sostanzioso contributo alla sua causa, farò in modo che la notizia della tua generosità venga diffusa ovunque. Che ne dici?', },
    {'L\'Anacoreta Kairthos ti ha chiesto di donare 1.000 monete d\'oro per sostenere gli sforzi dell\'Anacoreta Ayuri. Se completi questa missione tutti ti conosceranno come $N del Sole Infranto.', },
  },
  [11550] = {
    'Entri l\'Ingannatore...',
    {'Nonostante i nostri sforzi, il malvagio piano di Kael\'thas si sta realizzando. Il Pozzo Solare è stato riattivato in preparazione dell\'arrivo dell\'Ingannatore.|n|nL\'oggetto che si trova di fronte a me, e sotto A\'dal, è una rappresentazione dello stato attuale delle difese del Pozzo Solare. Sono state innalzate possenti barriere, che hanno bloccato i nostri attacchi alle camere interne. Il nostro mondo non ha mai avuto bisogno di aiuto quanto ora.|n|nFai rapporto all\'Arcimago Ne\'thul sull\'Isola di Quel\'Danas, a nord di Quel\'Thalas.', },
    {'Fai rapporto all\'Arcimago Ne\'thul sull\'Isola di Quel\'Danas, a nord di Quel\'Thalas.|n|nI maestri di volo di Forgiardente e Lunargenta ti porteranno a destinazione.', },
  },
  [11554] = {
    'Un aiuto al fronte',
    nil,
    nil,
  },
  [11555] = {
    'I tuoi alleati ti onorano',
    nil,
    nil,
  },
  [11556] = {
    'Riverito sul campo di battaglia',
    nil,
    nil,
  },
  [11557] = {
    'Il combattente migliore',
    nil,
    nil,
  },
  [11558] = {
    'Le relazioni pericolose',
    {'Quest\'epidemia d\'amore è sospetta. È disgustosa e ci porta ad abbassare le difese: potrebbe costituire una minaccia per tutti noi.|n|nÈ già abbastanza grave che così tanta gente si comporti in questo modo ridicolo... ma temo che la piaga si sia estesa fino ai nostri Guardiani, che dovrebbero essere immuni a cose del genere.|n|nCerca uno dei Guardiani e scopri se è rimasto vittima di questa follia.', },
    {'Recupera il Biglietto Ammuffito del Guardiano e portalo a Fenstad Argyle a Sepulcra.', },
  },
  [11559] = {
    'Commercio con i Pinnafredda',
    {'Ora che sei in grado di parlare con i Pinnafredda, è bene che ti faccia conoscere da loro. Uno dei modi migliori per farlo è concludere qualche affare.|n|nI Murloc apprezzano i bivalve sopra ogni altra cosa e l\'unico mercante a trattarli è Ahlurglgr. Fossi in te, accumulerei un po\' di Bivalve di Pinnafredda per donarglieli.|n|nI bivalve si trovano in tutta la fossa, ma anche nel Villaggio dei Pinnafredda e nelle loro caverne.', },
    {'Recupera 5 Bivalve di Pinnafredda e portali ad Ahlurglgr nel Rifugio dei Pinnafredda.', },
  },
  [11560] = {
    'Oh no, i girini!',
    {'Bene, sei $Gtornato:tornata;!|n|nQuando la frana nel villaggio dall\'altra parte del corso d\'acqua ha rivelato l\'ingresso delle caverne, un Aragoide malvagio, Claximus, è apparso e ha rapito i Girini Pinnafredda.|n|nA tutti i Murloc che l\'hanno seguito nelle caverne dev\'essere successo qualcosa, perché quando sono riemersi erano sotto il suo controllo.|n|n$C, devi nuotare fino all\'altra parte e salvare i Girini Pinnafredda nel villaggio e nelle caverne.|n|nIl futuro della Tribù Pinnafredda dipende da te!', },
    {'Il Re Mrgl-Mrgl ti ha chiesto di salvare 20 Girini Pinnafredda. In seguito torna da lui al Rifugio dei Pinnafredda.', },
  },
  [11561] = {
    nil,
    {'I nostri fratelli e le nostre sorelle dall\'altra parte sono diventati nostri nemici mortali. Hanno rapito i nostri girini, ci hanno scacciati dal nostro villaggio e hanno ucciso così tanti di noi che ho perso il conto.|n|nDimostra il tuo valore, $R! Nuota oltre la fossa e uccidili!|n|nNonostante la fiducia che il nuovo Re ti ha mostrato, questo è l\'unico modo che hai per farti accettare davvero. Fallisci e puoi anche andartene e non tornare mai più!', },
    {'Brglmurgl al Rifugio dei Pinnafredda ti ha chiesto di uccidere 15 Murloc Pinnafredda, siano essi Guerrieri, Oracoli o Sferzacoste.', },
  },
  [11562] = {
    'Mi stanno ricattando!',
    {'Ho una confessione imbarazzante da fare: mi stanno ricattando!|n|nMrmrglmr ha accettato di fare delle pulizie per me e ha scoperto il mio Costume da Murloc di ricambio. Ora minaccia di rivelare la mia vera natura agli altri Murloc.|n|nInutile che ti spieghi a quale disastro andremmo incontro! Inoltre, ho un piano che prevede l\'utilizzo di quel costume.|n|nTi prego, $N, vai da Mrmrglmr dall\'altra parte del Rifugio a nord e fa\' qualsiasi cosa ti chieda.', },
    {'Il Re Mrgl-Mrgl ti ha chiesto di parlare con Mrmrglmr al confine nordoccidentale del Rifugio dei Pinnafredda.', },
  },
  [11563] = {
    'Grmmurggll Mrllggrl Glrggl!',
    {'Se i tuoi piccoli, patetici occhi servissero a qualcosa, vedresti che nella parte settentrionale della baia le orche ci stanno massacrando!|n|nSe il tuo prezioso Re Elfo della Notte rivuole il suo costume indietro, allora tu dovrai farmi il favore di portarmi la testa del Re delle Orche, Glrggl, colui che nuota contro la marea del fato, annientando ogni speranza di vita per tutti quelli in grado di udire il canto di morte delle sirene sulle onde!|n|nSbrigati, $R! In questo stesso momento decine di Murloc Pinnafredda stanno morendo!', },
    {'Mrmrglmr ti ha chiesto di tornare da lui al Rifugio dei Pinnafredda con la Testa di Glrggl.', },
  },
  [11564] = {
    'Stufato d\'Orca Succulento',
    {'$GMio strano amico:Mia strana amica;, dicono che vuoi andare a caccia del Re delle Orche, Glrggl.|n|nSono con te, ma se vuoi assaggiare uno stufato per il quale vale davvero la pena vivere, allora portami il succulento grasso delle orche che nuotano nella Baia Scintillante.|n|nFai presto... se vuoi ricevere la ricompensa per i tuoi sforzi, avrò un bel daffare a tagliare la carcassa.', },
    {'Bmurglbrm la Mannaia ti ha chiesto di recuperare 7 Pezzi di Grasso d\'Orca Succulento e di portargliele al Rifugio dei Pinnafredda.', },
  },
  [11565] = {
    'Il travestimento di ricambio',
    {'Molto bene, il segreto del tuo Re con me è al sicuro, purché continui ad aiutarci contro i nostri nemici.|n|nTieni, portagli questa. L\'ho pulita per bene, anche se mi chiedo a cosa possa servirgli un secondo travestimento.|n|nForse ha in mente qualcosa per te?', },
    {'Porta il Travestimento di Ricambio di Re Mrgl-Mrgl al Re nel Rifugio dei Pinnafredda.', },
  },
  [11566] = {
    'Arrendersi... mai!',
    {'$N, è giunta l\'ora di mettere fine a questa situazione innaturale. Affinché i Murloc Pinnafredda abbiano anche solo la possibilità di un futuro, Claximus deve morire!|n|nVoglio che tu indossi il mio travestimento di ricambio ed entri nelle Caverne dei Pinnafredda fingendo la resa. Se sventolerai una bandiera bianca, i Murloc non ti attaccheranno.|n|nTroverai Claximus nell\'angolo sudoccidentale delle caverne. Quando sarai abbastanza $Gvicino:vicina;, uccidilo. Come prova di questa macabra operazione, portami una delle sue chele.', },
    {'Il Re Mrgl-Mrgl al Rifugio dei Pinnafredda ti ha chiesto di portargli una Chela di Claximus.', },
  },
  [11567] = {
    'L\'Antica Armatura dei Kvaldir',
    {'Ero sul vascello che trasportava l\'armatura. Eravamo appena saliti a bordo e ci dirigevamo qui, quando siamo stati attaccati da una nave da guerra dei Reietti.|n|nCi hanno abbordati, hanno portato via tutto il carico e hanno affondato la nave.|n|nÈ stata l\'ultima volta che ho visto quell\'armatura. Se la vuoi, usa il mio bombardiere per andare da Granfurto fino all\'isola maledetta su cui è attraccata la nave "Il Distruttore". Parla con la mia amica Alanya, qui fuori: sarà lei a farti salire a bordo del bombardiere.|n|nSe riuscirai a trovare l\'armatura, non ti azzardare a riportarla qui!', },
    {'Recupera l\'Antica Armatura dei Kvaldir e consegnala a Orfus di Kamagua nel Fiordo Echeggiante.', },
  },
  [11568] = {
    'Il meritato riposo',
    {'<Orfus ti consegna una sacca.>|n|nQui dentro ci sono i manufatti che hai recuperato. Trova i tumuli sepolcrali del Colle degli Scudi, a sud-est: è lì che i manufatti sono stati rubati ed è lì che devono tornare. Spero che basti a placare gli spiriti che infestano le nostre terre.|n|nSii forte, $N...', },
    {'Usa la Sacca con Manufatti dei Vrykul ai tumuli sepolcrali saccheggiati del Colle degli Scudi per restituire il Cuore Gelido di Isuldof, lo Scudo degli Esiriti, il Bastone della Furia Tempestosa e l\'Antica Armatura dei Kvaldir.|n|nPoi, torna da Orfus di Kamagua alla Funivia Antica.', },
  },
  [11569] = {
    'Il Mastro di Chiavi Urmgrgl',
    {'Devo uscire da queste caverne! Delle emanazioni magiche provenienti da Ibernia hanno colpito le menti di tutti quanti.|n|nNon voglio essere controllato come gli altri!|n|nIl Mastro di Chiavi Urmgrgl si trova nella caverna in basso e a sud, ed è lui ad avere la chiave della mia gabbia. Recuperala e portamela in modo che possa aprire la gabbia e fuggire da qui.|n|nPresto!', },
    {'Glrglrglr nelle Caverne dei Pinnafredda ti ha chiesto di recuperare la Chiave di Urmgrgl.', },
  },
  [11570] = {
    'Fuga dalle Caverne dei Pinnafredda',
    {'La serratura della mia gabbia non sembra particolarmente solida, ma non sono tanto sciocco da pensare di fuggire senza qualcuno che mi aiuti.|n|nMi scorteresti fuori dalle caverne? $R, non c\'è tempo da perdere.|n|nQuando tornerai al Rifugio, di\' al Re che sto bene. Sicuramente ti ricompenserà.', },
    {'Scorta Lurgglbr in salvo, quindi fai rapporto al Re Mrgl-Mrgl nel Rifugio dei Pinnafredda riferendo la buona notizia.', },
  },
  [11571] = {
    'Imparare a comunicare',
    {'Per poter essere d\'aiuto, devi imparare a parlare la lingua dei Pinnafredda. Per raggiungere questo scopo, useremo le forze della natura e della magia.|n|nPrendi questo guscio di lumaca vuoto. Sul fondo della fossa acquitrinosa laggiù si trova Scalder, una Furia dell\'Acqua ed Elementale dell\'Aria.|n|nSconfiggila, dopodiché usa il guscio sui suoi resti per catturarne il vapore magico. Riportami il guscio e ti infonderò la mia conoscenza della lingua dei Pinnafredda.|n|nPer fortuna un mio amico mi ha insegnato un incantesimo per respirare sott\'acqua, così anche questo problema è risolto.', },
    {'Re Mrgl-Mrgl ti ha dato un guscio da usare sui resti di Scalder. Portagli il Guscio del Re Pieno al Rifugio dei Pinnafredda.', },
  },
  [11572] = {
    'Torna da Atuik',
    {'Torna dall\'Anziano Atuik a Kamagua. Devi avvisare lui e il mio popolo della minaccia incombente in arrivo dal mare.|n|n<Orfus ha un brivido.>|n|nUsa la Funivia Antica per raggiungerlo. Ti prego, fa\' in fretta!', },
    {'Riferisci le cattive notizie all\'Anziano Atuik di Kamagua.', },
  },
  [11573] = {
    'Orfus di Kamagua',
    {'Salute, $Gviaggiatore:viaggiatrice;! Sono Lunk-Tusk dei Kalu\'ak. Il tuo popolo ci conosce con il nome di Tuskarr. Io e il mio compagno di viaggi siamo stati inviati a indagare su alcuni strani avvenimenti, che si sono verificati lungo uno dei nostri percorsi di caccia. Quando ci siamo avvicinati al cimitero chiamato Colle degli Scudi, i non morti ci hanno attaccati. Io sono stato fortunato e sono riuscito a tornare all\'accampamento, ma non so che cosa sia accaduto a Orfus.|n|nCi siamo separati alla Funivia Antica, a sud-est lungo il bordo del precipizio. Andresti a controllare se sta bene?', },
    {'Cerca Orfus di Kamagua alla Funivia Antica nel Fiordo Echeggiante.', },
  },
  [11574] = {
    'Vicini scomodi',
    {'Ho detto loro tutto ciò che ricordavo. Perché non mi credono?|n|nStavo raccogliendo delle erbe vicino alla fenditura. Dal nulla sono apparsi dei Maghi oscuri con delle bestie magiche e mi hanno circondata!|n|nSopra di me è apparsa una scatola magica, si è aperta e mi ha risucchiato al suo interno.|n|nAveva appena cominciato a richiudersi su di me, quando sono giunti i miei salvatori in groppa a dei Drachi Rossi. È stato straordinario!|n|nNon ho mai avuto l\'occasione di ringraziarli... Per favore, $C, cercali e ringraziali da parte mia.', },
    {'Endorah ti ha chiesto di recarti alla Scogliera d\'Ambra a nord del Forte dei Cantaguerra e ringraziare i suoi salvatori.', },
  },
  [11575] = {
    'Giusto in tempo',
    {'Ho detto loro tutto ciò che ricordavo. Perché non mi credono?|n|nStavo raccogliendo delle erbe vicino alla fenditura. Dal nulla sono apparsi dei Maghi oscuri con delle bestie magiche e mi hanno circondata!|n|nSopra di me è apparso un enorme cubo magico, si è aperto e mi ha risucchiato al suo interno. Giuro che è vero!|n|nAveva appena cominciato a richiudersi su di me, quando sono giunti i miei salvatori in groppa a dei draghi. È stato straordinario! I miei rapitori se la sono data a gambe e io sono fuggita.|n|nNon ho mai avuto l\'occasione di ringraziarli... Per favore, $C, se li vedi, ringraziali da parte mia.', },
    {'Midge al Forte degli Arditi ti ha chiesto di recarti alla Scogliera d\'Ambra a nord e ringraziare i suoi salvatori.', },
  },
  [11576] = {
    'Monitoraggio della fenditura: Anomalia di Rocciascissa',
    {'Salve, $R. Io sono Garren di Dalaran.|n|nNon molto tempo fa, la fenditura era un luogo tranquillo... almeno geotermicamente parlando.|n|nUltimamente, però, si sono verificate diverse scosse con frequenza allarmante, tali da spaccare il suolo ed esporre degli strani campi energetici di potere caotico.|n|nLa mia missione qui è di mappare e monitorare queste anomalie. Per esempio, i miei strumenti adesso indicano che ne è apparsa un\'altra sul versante sud-ovest della rupe.|n|nPrendi questo strumento e usalo su di essa.', },
    {'Garren alla Scogliera d\'Ambra ti ha chiesto di usare l\'Arcanometro presso l\'Anomalia di Rocciascissa.', },
  },
  [11580] = {
    'Dissacra questo Falò!',
    nil,
    nil,
  },
  [11581] = {
    'Dissacra questo Falò!',
    nil,
    nil,
  },
  [11582] = {
    'Monitoraggio della fenditura: Fondabisso',
    {'L\'hai sentita anche tu?!? Ed era solo una scossa d\'assestamento... avresti dovuto sentirla qualche minuto fa!|n|nTemo di dover ricorrere ancora una volta al tuo aiuto. I miei strumenti indicano la comparsa di un\'immensa anomalia appena a ovest di qui, sul fondo del mare.|n|nCome prima, quello che ti chiedo è di prendere l\'Arcanometro e misurare l\'anomalia.|n|nLancerò un incantesimo che ti permetterà di respirare sott\'acqua. Se il suo effetto dovesse svanire troppo presto, torna da me e lo lancerò di nuovo.', },
    {'Garren alla Scogliera d\'Ambra ti ha chiesto di usare l\'Arcanometro nei pressi dell\'Anomalia di Fondabisso e poi di tornare da lui con le misurazioni.', },
  },
  [11583] = {
    'Onora il Falò',
    nil,
    nil,
  },
  [11584] = {
    'Onora il Falò',
    nil,
    nil,
  },
  [11585] = {
    'Il presidio di Malogrido',
    {'Throm\'ka, $R! $GBenvenuto:Benvenuta; al Forte dei Cantaguerra. Il mio cuore si gonfia d\'orgoglio nel vedere $Gun tale eroe:una tale eroina; dell\'Orda rispondere alla nostra chiamata!|n|nQuesta fortezza imprendibile testimonia la tenacia dell\'Orda. Abbiamo dovuto lottare duramente per poterci insediare a Nordania. Da qui avrà inizio la nostra marcia verso la Corona di Ghiaccio ed è con la guida del figlio di Malogrido che trionferemo!|n|nGarrosh ti attende di sotto.|n|nLok\'tar ogar!', },
    {'Parla con Garrosh Malogrido al Forte dei Cantaguerra.', },
  },
  [11586] = {
    'Il presidio di Malogrido',
    {'Throm\'ka, $R! $GBenvenuto:Benvenuta; al Forte dei Cantaguerra. Il mio cuore si gonfia d\'orgoglio nel vedere $Gun tale eroe:una tale eroina; dell\'Orda rispondere alla nostra chiamata!|n|nQuesta fortezza imprendibile testimonia la tenacia dell\'Orda. Abbiamo dovuto lottare duramente per poterci insediare a Nordania. Da qui avrà inizio la nostra marcia verso la Corona di Ghiaccio ed è con la guida del figlio di Malogrido che trionferemo!|n|nGarrosh ti attende di sotto.|n|nLok\'tar ogar!', },
    {'Parla con Garrosh Malogrido al Forte dei Cantaguerra.', },
  },
  [11587] = {
    'Fuga di prigione',
    {'Salve, $C. Mi chiamo Donathan e sono un fedele rappresentante di Dalaran.|n|nPerdona la rudezza, ma ci troviamo nel bel mezzo di una crisi. In tutta Azeroth si stanno verificando rapimenti di Maghi e io sono stato autorizzato ad assoldare chiunque sia disposto a trovare la soluzione a questo mistero.|n|nLe nostre indagini iniziano dall\'accampamento a sud del nostro. Ti chiedo di salvare uno dei Maghi imprigionati laggiù. Per aprire la prigione arcana dovrai sottrarre una chiave a uno dei Cacciatori di Maghi.', },
    {'Il Bibliotecario Donathan alla Scogliera d\'Ambra ti ha chiesto di recuperare la Chiave della Prigione di Beryl da uno dei Cacciatori di Maghi di Beryl al Promontorio di Beryl e di usarla per liberare un Mago intrappolato in una Prigione Arcana.', },
  },
  [11588] = {
    'RIUSO',
    nil,
    nil,
  },
  [11589] = {
    'RIUSO',
    nil,
    nil,
  },
  [11590] = {
    nil,
    {'$N, ho una brutta notizia.|n|nHo appena saputo che una delle nostre Arcimaghe partita da Dalaran è scomparsa. Naturalmente i nostri sospetti ricadono sui Cacciatori di Maghi.|n|nÈ importante agire tempestivamente: se vogliamo avere qualche speranza di salvarla, dobbiamo scoprire al più presto cos\'è successo a Dama Evanor.|n|nPrendi questo dispositivo e torna al Promontorio di Beryl. Usa il dispositivo su un Occultista di Beryl vicino alla morte: le Catene Arcane dovrebbero tenerlo a bada abbastanza a lungo da portarlo qui per interrogarlo.', },
    {'Donathan ti ha chiesto di usare le Catene Arcane su un Occultista di Beryl ferito al Promontorio di Beryl e di tornare alla Scogliera d\'Ambra con lui.', },
  },
  [11591] = {
    'Fai rapporto alla Carovana di Mordiferro',
    {'Mordiferro, quello stupido cane, ha cercato di far passare la nostra carovana di scorte per una scorciatoia attraverso un cimitero taunka!|n|nAvevamo appena allacciato i rapporti con loro!|n|nOra la carovana giace in rovina, distrutta dagli Spiriti Taunka riemersi dalle tombe calpestate dalle ruote.|n|n$C, vai a sud e cerca di risolvere la situazione. Ho già mandato Grunt Pugnocrudele e altri per prestare i primi soccorsi.|n|nProva a dare anche tu una mano...', },
    {'Parla con Grunt Pugnocrudele alla Carovana di Mordiferro.', },
  },
  [11592] = {
    'Colpiamo!',
    {'Uno dei vostri Orchi, quello chiamato Mordiferro, ha cercato di risparmiare tempo prendendo una scorciatoia attraverso il nostro cimitero. $R, sarà meglio che questo non sia il normale comportamento dell\'Orda, o i Taunka saranno la vostra fine!|n|nTu però mi sembri disponibile a rimediare a questa spiacevole circostanza. Bene!|n|nLo spirito maledetto di Mordiferro adesso infesta questo luogo, disturbando i resti dei miei antenati. Va eliminato!|n|nSe sopravvivremo, fai rapporto al tuo Supremo di Bor\'gorok nell\'avamposto a nord.|n|nPosso contare su di te?', },
    {'Aiuta lo Staffettista Zoccolo Fiero e i suoi Incursori Cantaguerra a sopravvivere all\'assalto alla Carovana di Mordiferro e a eliminare lo spirito del Comandante delle Forze Mordiferro.|n|nIn caso di successo, fai rapporto al Supremo di Bor\'gorok nell\'Avamposto di Bor\'gorok.', },
  },
  [11593] = {
    'Morti da onorare',
    {'I nostri caduti meritano esequie da eroi, ma non possiamo seppellirli qui, su un suolo sacro ai Taunka.|n|nNon ti chiederò di trascinare fin qui i corpi, ma almeno prendi questa e addentrati nel cimitero. Quando trovi le guardie e i lavoratori morti della carovana, usa la torcia su di essi.|n|nRendi onore ai nostri morti, $C!', },
    {'Grunt Pugnocrudele alla Carovana di Mordiferro ti ha chiesto di usare la Torcia di Pugnocrudele per bruciare 10 tra Guardie e Lavoratori della Carovana Morti.', },
  },
  [11594] = {
    'Riposo eterno... di nuovo',
    {'La causa di questa tragedia è stata l\'idiozia del Comandante delle Forze Mordiferro. Cosa aveva in testa quando ha deciso di attraversare un cimitero taunka?|n|nIn ogni caso, ormai ciò che è fatto, è fatto. Ora sta a noi pagarne le conseguenze.|n|nIl Supremo di Bor\'gorok mi ha chiesto di aiutare lo Staffettista Zoccolo Fiero in qualsiasi modo. A sua volta, lo Staffettista ci ha chiesto di far ritrovare la pace agli spiriti dei suoi antenati.|n|nChe ne dici, $C? Sei forte abbastanza da risolvere questa situazione?', },
    {'Fai ritrovare la pace a 20 Spiriti Taunka tra Saggi Fantasma e Staffettisti Risorti, quindi fai rapporto a Grunt Pugnocrudele presso la Carovana di Mordiferro.', },
  },
  [11595] = {
    'La difesa del Forte dei Cantaguerra',
    {'Sulle spalle di Malogrido poggia il peso dell\'intera Orda. $N, non farti distogliere dai tuoi doveri di soldato a causa del suo temperamento.|n|n<Faucisaure annuisce tra sé.>|n|nCredevi che mi fossi dimenticato il nome di <un eroe/un\'eroina> di Orgrimmar? Non capita tutti i giorni di poter infilzare la testa di Nefarian con una picca!|n|nIl Flagello ha avviato il suo assalto a questa fortezza. I nostri soldati per ora difendono il perimetro, ma hanno un disperato bisogno di rinforzi. Fai rapporto a Razgor, appena all\'esterno del Forte dei Cantaguerra.', },
    {'Fai rapporto al Supremo Razgor nella capanna a sud del Forte dei Cantaguerra.', },
  },
  [11596] = {
    'La difesa del Forte dei Cantaguerra',
    {'$R, non lasciare che Malogrido ti distolga dai tuoi doveri di soldato dell\'Orda. Porta su di sé il peso di un terribile fardello in queste Distese Ghiacciate: la vittoria sul Flagello o l\'estinzione di ogni forma di vita su Azeroth. È per questo motivo che abbiamo bisogno della tua forza e della tua saggezza.|n|nIl Flagello ha avviato il suo assalto a questa fortezza. I nostri soldati per ora difendono il perimetro, ma hanno un disperato bisogno di rinforzi. Fai rapporto a Razgor, appena fuori dal Forte dei Cantaguerra.', },
    {'Fai rapporto al Supremo Razgor nella capanna a sud del Forte dei Cantaguerra.', },
  },
  [11597] = {
    'La difesa del Forte dei Cantaguerra',
    {'A quanto pare ci incontriamo sempre in situazioni disperate, $GSignore:Signora; degli Scarabei. L\'ultima volta che ci siamo visti non stavi salvando il mondo da distruzione certa?|n|n<Faucisaure ride.>|n|nIl tuo aiuto è il benvenuto qui a Nordania, nonostante quello che possa dire il giovane Capo Tribù.|n|nSe avessimo una decina di soldati del tuo livello, adesso siederemmo a Orgrimmar davanti a un bel focherello.|n|nFai rapporto al Supremo Razgor, appena all\'esterno dell\'ingresso principale del Forte dei Cantaguerra, a sud.', },
    {'Fai rapporto al Supremo Razgor nella capanna a sud del Forte dei Cantaguerra.', },
  },
  [11598] = {
    'La riconquista della Cava di Pietragrossa',
    {'Mentre il Forte dei Cantaguerra è protetto da tre metri di pietra e acciaio su tutti i lati, questa cava è indifesa e aperta agli attacchi dei Nerubiani.|n|n<Razgor indica a ovest.>|n|nOltre questa cava si trovano migliaia e migliaia di membri del Flagello in attesa dell\'ordine di attacco. Se i Nerubiani abbattessero le nostre difese interne, verremmo sopraffatti dalle legioni di non morti di Arthas.|n|nNon possiamo permettere una cosa del genere ed è per questo che attaccherai tu per <primo/prima>, massacrando i Nerubiani nella cava.|n|nSangue e tuono, soldato! Che entrambi siano con te!', },
    {'Il Supremo Razgor al Forte dei Cantaguerra ti ha chiesto di uccidere 15 Nerubiani Nerub\'ar.', },
  },
  [11599] = {
    'Thassarian, mio fratello',
    {'Recentemente ho saputo da William Allerton, un amico di famiglia, che mio fratello si è arruolato qui al Forte degli Arditi insieme a lui. Il fatto è che... mio fratello è morto da anni.|n|nHo venduto tutti i miei beni per venir qui a cercare Thassarian, solo per essere bloccata dal muro della burocrazia locale: sono persino stata minacciata di detenzione se avessi continuato a curiosare.|n|nHo bisogno di qualcuno che sia nelle grazie della gente che conta... qualcuno come te. Se potessi aiutarmi... Ho saputo che William è di stanza alla Miniera di Borgoardito.', },
    {'Cerca William Allerton nella Miniera di Borgoardito.', },
  },
  [11600] = {
    'Il fu William Allerton',
    {'<Il collo di William è stato squarciato da un oggetto affilato.>|n|n<Esaminando meglio il cadavere, scopri un indizio da portare a Leryssa: una Tessera di Arruolamento a nome di William Allerton.>', },
    {'Porta la Tessera di Arruolamento a Leryssa presso il Forte degli Arditi nella Tundra Boreale.', },
  },
  [11601] = {
    'Perduto e ritrovato',
    {'Il povero Allerton potrebbe ancora aiutarci a ritrovare mio fratello.|n|n<Leryssa tira fuori un grosso volume, simile al registro di arruolamento di un esercito.>|n|nL\'ho preso in prestito, d\'accordo? Vediamo... su quella Tessera di Arruolamento c\'è una data?|n|nWilliam diceva di aver visto Thassarian nella coda per l\'arruolamento. Sul registro dovrebbero trovarsi vicini... ed eccolo, infatti!|n|nEra stato assegnato a... all\'Unità S? Tutte le altre unità dell\'Alleanza prendono il nome dagli insediamenti.|n|nChi sta in quell\'unità? Dov\'è di stanza? Dobbiamo raccogliere informazioni. Vedi se il locandiere ha sentito qualcosa.', },
    {'Parla con James Deacon nella locanda del Forte degli Arditi.', },
  },
  [11602] = {
    'Isolare la fonte',
    nil,
    {'Il Supremo Razgor al Forte dei Cantaguerra ti ha chiesto di distruggere 10 Sacche di Uova Nerub\'ar.', },
  },
  [11603] = {
    'In vino veritas',
    {'L\'esercito era tutto per il Vecchio Colburn. Anche dopo essersi ritirato, ci si aggrappa come a una corda di salvataggio.|n|nLui conosce il nome di ogni generale, unità, brigata, distaccamento... qualunque cosa. Senza dubbio è lui l\'uomo che ti serve.|n|nIl fatto è che ha la mente un po\' confusa e non parla con nessuno se non beve il suo Vino di Kul Tiras, che lo riporta ai tempi in cui era in attività.|n|nPurtroppo non ricevo rifornimenti di quel vino da mesi, ormai. L\'ultimo mercantile partito da Kul Tiras è affondato a nord-est di qui. Potresti cercare di recuperare una bottiglia e portarla a Colburn.', },
    {'Recupera una bottiglia di Vino di Kul Tiras dal relitto affondato a nord-est del Forte degli Arditi e portalo al vecchio Colburn nella locanda del Forte degli Arditi.', },
  },
  [11604] = {
    'Un disertore',
    {'L\'Unità S... l\'Unità S... umpf... non ha senso... dovrebbe avere il nome di un insediamento...|n|nI ragazzi di Borgoscuro furono mandati a Dracombra, quelli di Borgodoro nel Fiordo. Dove l\'ho sentito...|n|nOh, sì... il disertore! C\'è un traditore nella prigione della caserma, catturato non molto tempo fa... ripeteva sempre che la "S" stava per Suicidio.|n|nCerca quel disertore: potrebbe avere l\'informazione che cerchi.', },
    {'Trova la prigione del Mastio Interno al Forte degli Arditi e parla con il disertore.', },
  },
  [11605] = {
    'Antenati da onorare',
    {'<Una voce distante riecheggia nella tua testa mentre osservi la statua di pietra.>|n|nNon spaventarti, <straniero/straniera>. Sono l\'Anziano Atkanok, un antico antenato dei Tuskarr, ai miei tempi abile artigiano e per secoli custode di questa cava.|n|nLa cava è stata invasa: molti spiriti degli antenati hanno lasciato le loro statue e ora vagano per il mondo. Puoi aiutarmi a raddrizzare questo torto?|n|nAnzitutto, devo conoscere i nomi degli antenati erranti. Cerca delle indicazioni nei pressi delle statue.', },
    {'L\'Anziano Atkanok all\'esterno della Cava di Rocciafredda ti ha chiesto di identificare le statue dell\'Anziano Kesuk, dell\'Anziano Sagani e dell\'Anziano Takret.', },
  },
  [11606] = {
    'La pazienza è una virtù di cui non abbiamo bisogno',
    {'Possiamo uccidere tutti i Nerubiani che vediamo e distruggere tutte le uova che troviamo, ma quei maledetti non finiranno mai finché non avremo fatto saltare le loro gallerie e i loro passaggi. Naturalmente, è impossibile farlo senza l\'attrezzatura adeguata. Purtroppo la maggior parte delle nostre scorte è usata dai Goblin e dai fabbri per i carri e le armi d\'assedio.|n|nAbbiamo però una buona riserva di esplosivo nella Cava di Pietragrossa... proprio sotto i piedi dei Nerubiani. Vai là e recuperane un po\'.', },
    {'Il Quartiermastro Holgoth al Forte dei Cantaguerra ti ha chiesto di recuperare 15 casse di Esplosivi dei Cantaguerra.', },
  },
  [11607] = {
    'Gli spiriti perduti',
    {'Quando la cava è stata presa d\'assalto, gli Sciamani e gli artigiani che lavoravano qui furono uccisi. La violenza ha sconvolto il mondo degli spiriti tanto che, se non troviamo il modo di calmare gli spiriti degli assassinati, non saremo in grado di guidare i nostri antenati al riposo eterno.|n|nGli aggressori non tengono in nessuna considerazione gli spiriti, ma i Segugi di Beryl che li accompagnano avvertono la loro presenza e li tengono prigionieri.|n|nUccidi i Segugi di Beryl e, sfruttando l\'energia grezza rilasciata, libera gli spiriti degli innocenti.', },
    {'L\'Anziano Atkanok, all\'esterno della Cava di Rocciafredda, ti ha chiesto di liberare gli spiriti di 3 Artigiani di Kaskala e di 3 Sciamani di Kaskala.', },
  },
  [11608] = {
    'Seppellisci quegli scarafaggi!',
    {'Nord, sud, est e ovest. Queste sono le aree da coprire. Intorno a questo Forte, all\'interno della Cava di Pietragrossa, vi sono quattro Depressioni di Nerub\'ar perfettamente posizionate.|n|n<Holgoth ti porge un pacchetto.>|n|nFai molta attenzione con questo, $N. Maneggialo con poca cura e sarai carne per cani.|n|nAll\'interno del pacchetto ci sono le Cariche di Profondità di Nitronite. Raggiungi ciascuna di quelle Depressioni di Nerub\'ar e piazza una carica di profondità al centro. Se tutto va bene, le gallerie crolleranno.|n|nForza, sbrigati!', },
    {'Il Quartiermastro Holgoth al Forte dei Cantaguerra ti ha chiesto di usare il Pacchetto con Cariche di Profondità di Nitronite per distruggere le Depressioni di Nerub\'ar a sud, est, ovest e nord del Forte dei Cantaguerra.', },
  },
  [11609] = {
    'Raccogliere i pezzi',
    {'Ora che abbiamo calmato gli spiriti degli artigiani e degli Sciamani uccisi, possiamo completare le cerimonie interrotte dall\'attacco. Assumerai tu il ruolo che di solito spetta a uno Sciamano Tuskarr, ma dovrai possedere tutti gli oggetti rituali necessari.|n|nNon c\'è tempo per realizzarne di nuovi, quindi dovrai perlustrare la cava alla ricerca di quelli lasciati cadere dalle vittime dell\'attacco. Maneggia quegli oggetti con cura, $N, perché alcuni sono molto antichi. Probabilmente alcuni dovrai sottrarli al nemico con la forza.', },
    {'Porta 6 Oggetti Rituali dei Tuskarr all\'Anziano Atkanok, che si trova all\'esterno della Cava di Rocciafredda.', },
  },
  [11610] = {
    'Ricondurre gli antenati a casa',
    {'Con il tuo aiuto, ora gli spiriti degli antenati finalmente potranno essere ricondotti nelle loro case, ossia le statue amorevolmente realizzate dagli artigiani e gli Sciamani di Kaskala.|n|nLe cerimonie sono state interrotte dall\'attacco alla cava e ora bisogna completarle. Prendi gli oggetti recuperati nella cava, poniti di fronte alle statue e recita questo salmo.|n|n<Delle parole di una lingua sconosciuta si riversano nella tua mente, ma sai che non avrai difficoltà a ripeterle al momento opportuno.>', },
    {'L\'Anziano Atkanok ti ha chiesto di guidare gli spiriti dell\'Anziano Kesuk, dell\'Anziano Sagani e dell\'Anziano Takret nelle loro statue di pietra.', },
  },
  [11611] = {
    'Catturati dal Flagello',
    nil,
    {'Il Caposquadra Mortuus al Forte dei Cantaguerra ti ha chiesto di liberare 5 Peoni Cantaguerra.', },
  },
  [11612] = {
    'Riconquistare la cava',
    {'Mi fa molto piacere vederti, $C. Il mio nome è Etaruk e un tempo ero un artigiano qui alla Cava di Rocciafredda.|n|nIo e i miei compagni stavamo preparando una serie di statue per dei riti, quando abbiamo visto quelle misteriose piattaforme blu giungere qui in volo.|n|nUna volta atterrate, i Maghi che trasportavano hanno assaltato la cava, saccheggiandola e uccidendo i miei compagni. Se non li fermiamo, distruggeranno le nostre statue e se ne andranno con i nostri manufatti. Mi aiuterai a fermare gli invasori?', },
    {'Etaruk, accampato nei pressi dell\'ingresso della Cava di Rocciafredda, ti ha chiesto di uccidere 12 Cacciatori di Tesori di Beryl.', },
  },
  [11613] = {
    'Il giuramento di Karuk',
    {'Si fanno chiamare Kvaldir. Ci sono delle leggende che li circondano... noi li chiamiamo Tuk-hariq, o camminatori della nebbia.|n|nIl mio villaggio fu distrutto da questi giganteschi mostri della nebbia. Tutte le persone che conoscevo furono uccise, compreso mio padre Ariut.|n|nSecondo la legge dei Tuskarr, io devo cercare vendetta contro coloro che hanno versato il sangue dei miei cari.|n|nIo non sono che un pescatore e non sono ancora un adulto... non posso affrontare faccia a faccia i Kvaldir.|n|nSe vendicassi tu i miei familiari per conto mio, ti sarei debitore.', },
    {'Karuk ti ha chiesto di uccidere 6 Incursori Skadir e 5 Scialuppieri Skadir.', },
  },
  [11614] = {
    'Verità nascoste',
    {'Noi siamo qui per ordine di Varimathras! La missione degli Inseguitori dell\'Ombra è semplice: spiare. Be\', spiare e ogni tanto uccidere qualcuno.|n|nUno dei miei migliori agenti sul campo è sparito. Da giorni non ne ho più notizie e comincio a temere il peggio. No, non la morte! La morte sarebbe perfetta. Temo invece che possa essersi messo in proprio... o che possa averci traditi.|n|nL\'ultima volta è stato visto alla Cava di Pietragrossa: stava raccogliendo informazioni sui Nerubiani. Trovalo.|n|nGli conviene essere morto...', },
    {'Trova l\'Inseguitore dell\'Ombra Luther alla Cava di Pietragrossa.', },
  },
  [11615] = {
    'I segreti dei Nerub\'ar',
    {'Scorri le pagine del volume alla ricerca di qualcosa d\'importante. L\'ultima pagina è coperta da appunti presi di fretta:|n|nNecrosignori. Almeno una decina, se ho contato bene.|n|nLe fattorie a ovest fungono da orribili Radure della Procreazione per il Flagello.|n|nFile e file di vittime.|n|nCredo sappiano di me. Mi sono rifugiato nella rocca, non intendo essere catturato vivo.|n|nEmotossina Nefasta. Qualora gli passasse per la testa di mangiarmi, li attende una bella sorpresa.|n|nRiferisci queste informazioni a Barthus.', },
    {'Porta il Diario di Luther all\'Inseguitore dell\'Ombra Barthus nel Forte dei Cantaguerra.', },
  },
  [11616] = {
    'Messaggio per Malogrido',
    {'<Barthus strappa l\'ultima pagina e l\'arrotola.>|n|nPortala subito a Malogrido! Intanto manderò una squadra a perlustrare la zona delle fattorie.|n|nRicordati di dire a Malogrido che abbiamo bisogno di rinforzi.', },
    {'Porta la Nota di Barthus a Garrosh Malogrido nel Forte dei Cantaguerra.', },
  },
  [11617] = {
    'Ostacolare la fuga nemica',
    {'Sono certo che hai visto quelle piattaforme blu e bianche fluttuare sopra la cava: sono i mezzi di trasporto che i Cacciatori di Maghi hanno usato per invaderci. Ora li stanno caricando di manufatti e frammenti delle nostre statue.|n|nDobbiamo fermarli prima che lascino la cava.|n|nLe piccole creature che scavano nella cava hanno degli esplosivi. Recuperali e usali per distruggere le piattaforme. Il capo degli invasori sta comandando l\'operazione da una quarta piattaforma, ma di lui ci occuperemo dopo.', },
    {'Etaruk, all\'esterno della Cava di Rocciafredda, ti ha chiesto di distruggere la Piattaforma Nord, la Piattaforma Est e la Piattaforma Ovest.', },
  },
  [11618] = {
    'Rinforzi in arrivo...',
    {'<Malogrido scuote la testa.>|n|n$R, forse non hai notato che qui stiamo cercando di vincere una guerra. Ho bisogno di tutti i soldati disponibili nei punti principali del fronte e questo significa che non ho veri soldati da impiegare per queste incursioni di poca importanza.|n|n<Malogrido si ferma a pensare.>|n|nSe Barthus vuole rinforzi alle fattorie...|n|n<Malogrido batte le mani.>|n|n...li avrà! Fai rapporto agli assassini di Barthus presso le fattorie, a ovest di qui. Fa\' sapere loro che i rinforzi sono arrivati.', },
    {'Cerca l\'Inseguitore dell\'Ombra Ickoris nel Presidio Agricolo dei Cantaguerra a ovest del Forte dei Cantaguerra.', },
  },
  [11619] = {
    'Gamel il Crudele',
    {'Mio padre fu ucciso da Gamel il Crudele, il capo di questi incursori, che adesso si è insediato in una delle caverne che danno sulla spiaggia.|n|nTi sei già $Goccupato:occupata; dei suoi uomini: porta a termine ciò che hai cominciato, $N. Vendica mio padre e io dividerò con te quel poco che mi è rimasto.', },
    {'Karuk ti ha chiesto di eliminare Gamel il Crudele alla Sponda degli Sferzalama.', },
  },
  [11620] = {
    'Le parole di un padre',
    {'C\'è qualcuno che potrebbe gettare luce su questo mistero. Si dice che i Kvaldir abbiano mantenuto una Sacerdotessa Naga viva nel tempio sul lato ovest della riva.|n|nSenza dubbio la Sacerdotessa proverà risentimento nei confronti di questi invasori Kvaldir. Forse mio padre si aspetta che lei collabori in qualche modo con te.', },
    {'Cerca Veehja al Santuario delle Squame sulla Sponda degli Sferzalama.', },
  },
  [11621] = {
    'La tavoletta di Leviroth',
    {'<Scorri rapidamente le incisioni sulla tavoletta alla ricerca di testo a te comprensibile. Finalmente trovi il seguente frammento:>|n|n"I figli della nebbia rivendicheranno mille anime per colui che risiede nelle acque oscure. Allora il suo emissario si risveglierà."|n|n<Questa informazione potrebbe interessare a Karuk.>', },
    {'Torna da Karuk con l\'informazione trovata sulla tavoletta.', },
  },
  [11622] = {
    'I segreti di Sferzalama',
    {'C\'è qualcuno che potrebbe gettare luce su questo mistero. Si dice che i Kvaldir abbiano mantenuto un gruppo di Sacerdotesse Naga vive nel tempio.|n|nLa Gran Sacerdotessa Veehja senza dubbio proverà risentimento nei confronti di questi invasori Kvaldir. Forse lei potrà spiegarti il significato delle parole sulla tavoletta.', },
    {'Cerca Veehja tra le rovine di Sferzalama nella Tundra Boreale.', },
  },
  [11623] = {
    'Una visita dal Curatore',
    {'Il capo delle forze dei Cacciatori di Maghi è una spaventosa creatura chiamata Curatore Insivius. Il mio popolo ha dato la caccia a queste creature del mare e della terra per innumerevoli generazioni, ma non ho mai visto nulla di simile a questo Curatore.|n|nLa sua piattaforma volante è atterrata sul margine della cava e da lì sta guidando l\'assalto. $N, a questo punto non posso fare a meno di pensare che siano stati gli antenati stessi a mandarti qui! Spero vorrai aiutarmi a scacciare i Cacciatori di Maghi da questa cava una volta per tutte!', },
    {'Etaruk, all\'esterno della Cava di Rocciafredda, ti ha chiesto di uccidere il Curatore Insivius.', },
  },
  [11624] = {
    'Il cielo lo saprà',
    {'Devo scoprire cos\'è successo al mio maestro, il Chiaroveggente Passo Tetro!|n|nPrima era impegnato a osservare i Magnatauri a Magmoth, ma uno dei suoi Grunt è appena tornato dicendo che il suo gruppo è stato annientato e che il Chiaroveggente è stato trascinato nelle profondità di quel posto.|n|nPrima di inviarti in una missione suicida, vorrei consultare gli spiriti per saperne di più.|n|nNelle Rovine di Eldra\'nath a ovest c\'è l\'Elementale dell\'Aria Imperean. È saggia e potrebbe darti le informazioni che cerchi.', },
    {'Parla con Imperean alle Rovine di Eldra\'nath.', },
  },
  [11625] = {
    'Il Tridente di Naz\'jan',
    {'Cinquecento anni fa, Azshara imprigionò in queste acque un essere di nome Leviroth. Ora questi barbari stanno cercando di disfare l\'opera della nostra regina!|n|nHanno conquistato la nostra città e iniziato a sacrificare i miei fratelli per risvegliare Leviroth! Esauriti i Naga, hanno continuato con i Tuskarr. I loro spiriti non conosceranno pace!|n|nTi aiuterò per saziare la mia fame di vendetta. Il loro capitano, Ragnar, dimora in profondità, nella zona nordorientale di Sferzalama, e possiede un tridente d\'oro. Portamelo!', },
    {'Veehja a Sferzalama ti ha chiesto di recarti nell\'estremità nordorientale delle Rovine degli Sferzalama e di uccidere Ragnar Drakkarlund, recuperando il Tridente di Naz\'jan per lei.', },
  },
  [11626] = {
    'L\'emissario',
    {'Quando Leviroth venne imprigionato, Raj Naz\'jan era l\'imperatore di Sferzalama. Azshara stessa benedisse il suo tridente, così che potesse uccidere quella bestia se avesse mai tentato di fuggire.|n|nPer quanto la cosa mi disgusti, ora è nelle tue mani, $R, e sarai tu a vendicarti per me su questi barbari giganti.|n|nPorta il tridente nelle profondità sotto Sferzalama. Troverai Leviroth sotto un iceberg all\'estremità settentrionale di Sferzalama.|n|nConficca il tridente nelle sue carni e uccidilo! Quando avrai fatto, torna da chiunque ti abbia $Gmandato:mandata; qui: io non voglio più vederti.', },
    {'Cerca Leviroth sotto l\'iceberg che galleggia nella parte settentrionale delle Rovine degli Sferzalama. Usa il Tridente di Naz\'jan per ucciderlo, quindi torna da Karuk nella parte settentrionale della Sponda degli Sferzalama.', },
  },
  [11627] = {
    'Il punto di ebollizione',
    {'Ah, cerchi delle informazioni: le condizioni e il luogo in cui si trova il tuo Chiaroveggente. Evidentemente non ha previsto quel che gli sarebbe capitato.|n|nA ogni modo, ti darò i mezzi per acquisire le informazioni che desideri. Prima, però, dovrai fare qualcosa per me.|n|nSenza dubbio hai assistito alla guerra tra l\'acqua e il fuoco a sud. Simmer continua a far bollire la pozza di Churn e i due si combattono da tempo immemore.|n|nRecati all\'Altura Carbonizzata e all\'Acquitrino Bollente, quindi convinci entrambi a cessare il loro infantile litigio.', },
    {'Imperean ti ha chiesto di sconfiggere e sottomettere Simmer e Churn, quindi di tornare da lei alle Rovine di Eldra\'nath.', },
  },
  [11628] = {
    'Effetto boomerang',
    {'A nord-est si erige l\'Acropoli di En\'kilah, l\'avamposto del Flagello nella Tundra Boreale. Dalle sue mura, il comandante del Flagello ha sguinzagliato i suoi Nerubiani per circondarci.|n|nRestare sulla difensiva si rivelerebbe un tragico errore per il nostro popolo, ma i miei consiglieri non riescono a mettersi d\'accordo. Durm lancerebbe un attacco frontale, mentre la Saggia Aeire preferirebbe agire furtivamente.|n|nL\'Acropoli, nel frattempo, ha fatto inaridire le terre e la fauna locali. Aeire ritiene che le pelli dei Mammut Contagiati possano servire per infiltrarsi tra gli invasori.', },
    {'Il Capo Tribù Bora Fredda a Taunka\'le ti ha chiesto di portargli 5 Pelli di Mammut Contagiati.', },
  },
  [11629] = {
    'Ritorno dalla Parlaspiriti',
    {'Hai fatto ciò che ti ho chiesto e ora ti darò ciò che desideri.|n|nConsegna questa essenza primordiale alla Parlaspiriti nell\'Avamposto di Bor\'gorok. Se è saggia, conoscerà il rituale necessario per ottenere le informazioni che cercate.', },
    {'Consegna l\'Essenza Primordiale di Imperean alla Parlaspiriti Ringhiazanna nell\'Avamposto di Bor\'gorok.', },
  },
  [11630] = {
    'La terra piagata',
    {'La Saggia Aeire ritiene, trattando le pelli con la terra contaminata all\'esterno dell\'Acropoli, di poter realizzare un mantello in grado di farti infiltrare tra i membri del Flagello. Dice che non ti noteranno neanche.|n|nSperiamo abbia ragione: non abbiamo altro modo di raccogliere le informazioni necessarie per pianificare un contrattacco.|n|nDovresti trovare la terra che le serve a sud e a ovest della fortezza. Raccogline un po\' e portamela.', },
    {'Porta 8 zolle di Terra Contaminata al Capo Tribù Bora Fredda nel villaggio di Taunka\'le.', },
  },
  [11631] = {
    'Visione dell\'aria',
    {'Ecco, $N, ho sintonizzato l\'essenza su di te.|n|nApri la tua anima in presenza del mio Totem dell\'Aria e concentrati sulla sorte del Chiaroveggente Passo Tetro.|n|nLo Spirito dell\'Aria tocca ogni cosa: con un po\' di fortuna, avrai una visione.', },
    {'Usa l\'Essenza Primordiale di Imperean per compiere un rituale presso il Totem di Ringhiazanna all\'Avamposto di Bor\'gorok e ottenere delle informazioni sul Chiaroveggente Passo Tetro.|n|nA rituale concluso, parla con la Parlaspiriti Ringhiazanna.', },
  },
  [11632] = {
    'Ciò che il gelido inverno porta con sé...',
    {'<Hai in mano il frammento del carapace di Ith\'rix il Falciatore e capisci che questo è solo l\'inizio. Anche la sensazione di vittoria appena provata è passeggera. Di certo il Re dei Lich dispone di mille altre bestie come Ith\'rix e attende solo di sguinzagliarle contro l\'Orda.>|n|n<Prendi il tuo trofeo e portalo al Gran Supremo Faucisaure nel Forte dei Cantaguerra. Senza dubbio gli interesserà sapere della tua vittoria su un potente membro del Flagello.>', },
    {'Porta il Carapace Rinforzato di Ith\'rix al Gran Supremo Faucisaure nel Forte dei Cantaguerra.', },
  },
  [11633] = {
    'Passare inosservati',
    {'La Saggia Aeire ha completato il mantello. Prendilo e recati all\'Acropoli di En\'kilah. Usa il mantello per passare $Ginosservato:inosservata; tra i membri del Flagello all\'interno delle mura della città. Questa è la nostra migliore occasione per raccogliere informazioni sui capi e sulle fortificazioni del nemico.|n|nIndossando il mantello, esplora le grosse guglie che si trovano in città. Ricorda che, se ti ci avvicini troppo, gli Abomini En\'kilah ti scopriranno.', },
    {'Il Capo Tribù Bora Fredda a Taunka\'le ti ha chiesto di indossare il Mantello della Mimesi all\'interno dell\'Acropoli di En\'kilah e di esplorare la Guglia del Sangue, la Guglia del Dolore e la Guglia della Decadenza.', },
  },
  [11634] = {
    'Il Maestro del Vento To\'bor',
    {'Tu sei un osso duro, $N, e credo che il tuo talento possa essere meglio impiegato altrove... per esempio alla radice di questa dannata faccenda!|n|n<Razgor indica a ovest.>|n|nMigliaia di membri del Flagello, almeno quattro Macchine della Morte fluttuanti e chissà cos\'altro.|n|nDovrai scoprirlo e occupartene. Proprio così: affronterai l\'esercito del Flagello che attualmente preme contro i nostri cancelli.|n|nRaggiungi la cima del Forte dei Cantaguerra e cerca il Maestro del Vento To\'bor: ti sta già aspettando.', },
    {'Fai rapporto al Maestro del Vento To\'bor nel Forte dei Cantaguerra.', },
  },
  [11635] = {
    'Lo spirito del Chiaroveggente Passo Tetro',
    {'Devi recarti a Magmoth, a est.|n|nLì dovrai scendere nelle profondità delle caverne.|n|nParla con lo spirito del Chiaroveggente Passo Tetro!', },
    {'Parla con lo spirito del Chiaroveggente Passo Tetro all\'interno di Magmoth.', },
  },
  [11636] = {
    'Passaggio sul tappeto volante',
    {'Carri, cumpà. Sto parlando di macchine d\'assedio! Abbiamo carri corazzati sulla costa a ovest, all\'Approdo di Garrosh. Dovrai raggiungere i carri e usarne uno per portare la giustizia dell\'Orda sul Flagello!|n|nLa parte difficile sta nel farti arrivare laggiù: per nessun motivo al mondo ti lasceremmo andare con le Viverne dei Venti nuostr\', è troppo rischioso.|n|nVedi chell\'Elfo biondo laggiù? Si chiama Yanni, cumpà. Isso ti può portare sulla costa in tutta sicurezza. Na volta $Garrivato:arrivata;, parla con Gorgia il Tritacorpi!', },
    {'Parla con Yanni al Forte dei Cantaguerra per organizzare un viaggio sicuro verso l\'Approdo di Garrosh. Una volta a destinazione, parla con Gorgia il Tritacorpi.', },
  },
  [11637] = {
    nil,
    {'Dopo che il mio manipolo di Grunt è stato annientato, sono stato trascinato qui e ucciso con un rituale. Il Neboldo responsabile della mia morte si chiama Kaganishu.|n|nAnche se hai neutralizzato i suoi aiutanti Sciamani, il mio spirito è ancora incatenato a questo posto: dopo avermi ucciso, Kaganishu ha usato il mio corpo per creare un feticcio che mi tiene legato qui. In questo modo, Kaganishu spera di apprendere tutto ciò che so sullo sciamanesimo.|n|nKaganishu si trova qui vicino, nelle caverne. Devi sottrargli il feticcio e usarlo sul mio spirito.|n|nSolo allora sarò veramente libero.', },
    {'Recupera il Feticcio di Kaganishu e usalo sui Resti del Chiaroveggente Passo Tetro.|n|nDovrai consegnare il feticcio allo spirito del Chiaroveggente Passo Tetro all\'interno di Magmoth.', },
  },
  [11638] = {
    'Rimpatrio dei resti',
    {'$N, ora che il mio spirito è libero, mi faresti l\'onore di consegnare i miei resti alla Parlaspiriti Ringhiazanna? Si trovano sul terreno sotto di me.|n|nSento che la Parlaspiriti si trova ancora all\'Avamposto di Bor\'gorok, più a ovest dell\'ultima volta in cui l\'ho vista.', },
    {'Consegna i Resti del Chiaroveggente Passo Tetro, che giacciono ai piedi del suo spirito, alla Parlaspiriti Ringhiazanna nell\'Avamposto di Bor\'gorok.', },
  },
  [11639] = {
    'La vendetta su Magmoth',
    {'Il Supremo si rifiuta di permettere allo Sciamano di curare le mie ferite. Dice che mi servirà da lezione e mi darà il tempo per riflettere sui miei fallimenti.|n|nPerò tu potresti vendicarti per me e per tutti gli altri caduti a Magmoth!|n|nConosco la Parlaspiriti che ti ha chiesto di andare a salvare il Chiaroveggente.|n|nDevi andare a est. Va\', $C... vai a uccidere i Magnatauri e i loro tirapiedi Neboldi. Recupera l\'onore dell\'avamposto!', },
    {'Uccidi 10 Sciamani di Magmoth, 5 Depredatori di Magmoth, 3 Frantumatori di Magmoth e 3 Compagne di Magmothregar, quindi torna da Ortrosh all\'Avamposto di Bor\'gorok.', },
  },
  [11640] = {
    'Le parole del potere',
    {'All\'interno delle guglie da te esplorate risiedono i principali luogotenenti del capo del Flagello, i Gran Sacerdoti. Essi non solo sono al comando delle forze del Flagello, ma possiedono anche la chiave per accedere alla necropoli soprastante e al loro comandante.|n|nSe non lo uccideremo, le forze del Flagello ci sommergeranno come una marea incontrollata. Anche se Durm vorrebbe attaccare il nemico apertamente, non posso rischiare di lasciare il villaggio sguarnito. Sta dunque a te, $N, uccidere i Gran Sacerdoti e recuperare le pergamene in loro possesso.', },
    {'Porta la Pergamena del Gran Sacerdote Naferset, la Pergamena del Gran Sacerdote Talet-Kha e la Pergamena del Gran Sacerdote Andorath al Capo Tribù Bora Fredda nel villaggio di Taunka\'le.', },
  },
  [11641] = {
    'Un assalto coraggioso',
    {'Sin dall\'inizio ho consigliato al Capo Tribù Bora Fredda di radunare i nostri potenti guerrieri e di attaccare la base nemica. Purtroppo il mio consiglio non è stato ascoltato e il Capo Tribù ha preferito temporeggiare, seguendo il piano della Saggia Aeire.|n|nIo, però, non intendo aspettare oltre. Se il Capo Tribù Bora Fredda è troppo codardo per inviare i nostri guerrieri in battaglia, forse tu potrai dimostrargli che un attacco diretto è quello che ci vuole. Assalta l\'Acropoli di En\'kilah e uccidi chiunque incontri sul tuo cammino, $N.', },
    {'Uccidi 15 Ghoul En\'kilah e 5 Negromanti En\'kilah, quindi fai rapporto a Durm Pelle Gelida nel villaggio di Taunka\'le.', },
  },
  [11642] = {
    'Il carro non si riparerà da solo',
    {'Dobbiamo rimettere in sesto questi carri! Non si ripareranno da soli. Sarà Mobu a occuparsene: parlagli per vedere di cosa ha bisogno. Forse potrai finalmente zittirlo prima che mi mandi definitivamente in bestia e mi costringa a spaccarlo in due!|n|nOdio i piccoletti...', },
    {'Parla con Mobu all\'Approdo di Garrosh.', },
  },
  [11643] = {
    'Martellatore Asintotico Pneumatico di Mobu',
    nil,
    nil,
  },
  [11644] = {
    'Piastre Metalliche Super Resistenti!',
    {'Mi serve del metallo per riparare i carri! Le Piastre Metalliche Super Resistenti si trovano disseminate per tutto l\'Approdo di Garrosh e in fondo alla baia.|n|nFai attenzione quando vai a raccoglierle: la nebbia è... ehm... AGGRESSIVA! È stata la nebbia a devastare l\'Approdo e il villaggio dei Tuskarr. Poveri, piccoli Tuskarr...', },
    {'Mobu alla Costa dell\'Eco nella Tundra Boreale ti ha chiesto di recuperare 10 Piastre Metalliche Super Resistenti.', },
  },
  [11645] = {
    'Quegli sporchi Neboldi puzzolenti!',
    {'Quegli sporchi Neboldi puzzolenti... hanno rubato tutte le mie provviste!|n|nCosa sono i Neboldi? Sono simili ai Coboldi, solo che servono i Magnatauri... se ne prendono cura, diciamo. Strano, lo so!|n|nA ogni modo, puoi aiutarmi? So per certo che quelle pesti se la sono svignata con la mia roba. Stupida io a pensare che sarebbe stata al sicuro, lì nella parte nord dell\'Aerodromo.|n|nFammi un favore: dirigiti a nord fino a Magmoth. Riportami la mia roba in fretta e ti darò una ricompensa in denaro!', },
    {'Recupera 10 Casse della Roba di Crafty e riportale a Crafty Ruotadentata nell\'Aerodromo di Frizzapistone.', },
  },
  [11646] = {
    'L\'inquisizione',
    {'Ascoltami bene, $N, perché non c\'è un momento da perdere.|n|nStiamo preparando il prigioniero all\'interrogatorio che avrà luogo qui nella torre. Nel caso non si dimostrasse particolarmente disponibile, potremmo aver bisogno del tuo aiuto.|n|nRaggiungi il luogo in cui è rinchiuso e di\' al Bibliotecario Normantis che ti ho $Gmandato:mandata; ad aiutarlo.', },
    {'Donathan ti ha ordinato di offrire il tuo aiuto al Bibliotecario Normantis nella Torre del Mago alla Scogliera d\'Ambra.', },
  },
  [11647] = {
    'Neutralizzare i calderoni',
    {'La presenza dei Calderoni della Piaga nell\'Acropoli di En\'kilah mi preoccupa molto, $N. È chiaro che il Capo Tribù Bora Fredda si fida del tuo giudizio e della conoscenza che hai del nostro nemico. Neutralizzeresti per me i calderoni mentre porti a termine la missione all\'Acropoli per il Capo Tribù?|n|nHo preparato un totem che attaccherà e neutralizzerà il contenuto dei calderoni. Tu dovrai trovare i calderoni e usare il totem nelle vicinanze di ciascuno di essi. Ogni arma del Flagello che distruggiamo ci fa avvicinare alla vittoria!', },
    {'La Saggia Aeire a Taunka\'le ti ha chiesto di usare il suo totem per neutralizzare il Calderone Orientale, il Calderone Centrale e il Calderone Occidentale dell\'Acropoli di En\'kilah.', },
  },
  [11648] = {
    'L\'arte della persuasione',
    {'È una fortuna che tu sia qui, $R.|n|nVedi, il codice deontologico del Kirin Tor ci vieta di adottare certe misure "estreme", anche in casi disperati come questo.|n|nPerò tu, in quanto $Gstraniero, non sei vincolato:straniera; non sei vincolata; a quelle restrizioni e puoi adottare ogni mezzo necessario per recuperare le informazioni che ci servono.|n|nFa\' ciò che devi. Dobbiamo sapere subito dove si trova Dama Evanor!|n|nNel frattempo, io mi terrò occupato riordinando questi scaffali. Oh, e tieni: forse questo ti tornerà utile...', },
    {'Il Bibliotecario Normantis alla Scogliera d\'Ambra ti ha chiesto di usare il Pungitore Neurale sull\'Occultista di Beryl Imprigionato finché non rivelerà dove si trova Dama Evanor.', },
  },
  [11649] = {
    'Gocce di tempesta',
    {'Ora che il loro piccolo contrasto è più o meno risolto, resta la questione del tuo Chiaroveggente.|n|nCome puoi vedere, i miei vassalli sono infuriati per la continua guerra tra acqua e fuoco. La situazione non cambierà da un giorno all\'altro, ma possiamo sfruttarla a nostro vantaggio.|n|nPer aiutarti nella tua ricerca, abbiamo bisogno delle loro gocce. Addentrati nelle rovine e recupera le gocce dalle Tempeste.', },
    {'Recupera 5 Gocce di Tempesta e consegnale a Imperean nelle Rovine di Eldra\'nath.', },
  },
  [11650] = {
    'Ancora una cosa...',
    {'Come forse hai notato, abbiamo costruito l\'Aerodromo appena a sud di una tana di Magnatauri!|n|n<Crafty mormora qualcosa di irripetibile su Frizzapistone.>|n|nIl vecchio mi ha incaricato di trovare una... ehm... soluzione creativa a questa situazione: se non ce ne sbarazzeremo al più presto, piomberanno su di noi e ci faranno a pezzi!|n|nE qui entri in gioco tu. Dovresti procurarmi tutto quello che trovi su questo elenco. Per favore.', },
    {'Recupera gli Attrezzi di Crafty, un Condensatore Sovraccaricato e una Manciata di Sabbia di Roccianar, quindi porta tutto a Crafty Ruotadentata nell\'Aerodromo di Frizzapistone.', },
  },
  [11651] = {
    'Grazie al carro!',
    nil,
    {'Parla con Gorgia il Tritacorpi alla Costa dell\'Eco.', },
  },
  [11652] = {
    'Le Pianure di Nasam',
    {'Quando sei $Gpronto:pronta;, sali a bordo di uno di questi carri e recati alle Pianure di Nasam, a sud-est di qui.|n|nUsa l\'arsenale bellico del carro per falciare l\'armata del Flagello. Se vieni circondato, il "Martellacarne" ti aiuterà a liberarti e le Mine faranno il resto! Se incontri qualcuno dei nostri soldati, fallo salire a bordo! Un\'ultima cosa: sparse per il campo di battaglia troverai taniche di carburante.|n|nCerca di avvicinarti quanto basta alla struttura al centro e cerca di scoprire cosa sta succedendo.|n|nSe dopo aver fatto tutto questo sarai ancora $Gvivo:viva;, vai da Malogrido!', },
    {'Usa il Carro d\'Assedio dell\'Orda per eliminare 100 Soldati del Flagello e salvare 3 Soldati Cantaguerra Feriti nelle Pianure di Nasam. Devi anche scoprire l\'identità del responsabile dell\'assalto del Flagello.|n|nA missione compiuta, fai rapporto a Garrosh Malogrido al Forte dei Cantaguerra.', },
  },
  [11653] = {
    'Ah... ora scappi, eh?',
    {'Ci siamo, capo! Ecco quello che ti chiedo di fare...|n|nPrendi il mio fulminatore e dirigiti a nord, verso Magmoth. Se vogliamo avere una chance contro quei mostri, dobbiamo ridimensionarli un po\'... letteralmente.|n|nPer verificarne l\'efficacia, devi uccidere i Magnatauri mentre gli effetti del fulminatore sono ancora attivi. I Frantumatori e le Compagne vanno bene, mentre puoi ignorare i cuccioli... sono troppo piccoli per creare problemi.', },
    {'Prova il Fulminatore Riducente Prototipo Super Avanzato di Crafty su 5 Frantumatori di Magmoth o Compagne di Magmothregar, quindi torna da lei all\'Aerodromo di Frizzapistone.', },
  },
  [11654] = {
    'La Guglia del Sangue',
    {'<Esaminando la fiala col sangue, ti accorgi che il suo contenuto è ancora caldo: dev\'essere appena stato raccolto e forse la vittima è ancora viva.>|n|n<Ma cosa può farsene il Flagello di questo sangue? In passato, i suoi membri non hanno mai mostrato interesse per dei prigionieri vivi. Forse individuando la fonte del sangue potrai scoprire cosa sta tramando il Flagello.>', },
    {'Esplora la Guglia del Sangue alla ricerca di informazioni sulla Fiala di Sangue Fresco.', },
  },
  [11655] = {
    'Nella nebbia',
    {'Oltre la nebbia a nord troverai l\'Approdo di Garrosh. A sud ci sono le rovine del mio vecchio villaggio, Pal\'ea. Entrambi i luoghi sono stati saccheggiati da un\'antica popolazione nota come i Kvaldir.|n|nQuegli spaventosi selvaggi hanno ucciso senza pietà la mia gente e costretto la tua a spostarsi nell\'entroterra.|n|nTutto ciò che rimane dei Tuskarr di Pal\'ea sono i nostri effetti personali, presi dai Kvaldir come reliquie. Anche se noi non siamo una razza vendicativa, va fatta giustizia. Le Reliquie Tuskarr non possono restare nelle loro mani. Addentrati nella nebbia e cercale...', },
    {'Waltor di Pal\'ea alla Costa dell\'Eco nella Tundra Boreale ti ha chiesto di uccidere i Kvaldir e recuperare 8 Reliquie Tuskarr.', },
  },
  [11656] = {
    'Rogo pubblico',
    {'La magia dei Tuskarr assomiglia a quello che voi chiamate sciamanesimo. Anche se noi serviamo gli elementi in modo diverso rispetto a voi, il potere che siamo in grado di evocare è formidabile.|n|n<Waltor fa oscillare una specie di torcia dinanzi a te.>|n|nVoglio che torni nella nebbia con questa Torcia Tuskarr per attaccare le imbarcazioni dei Kvaldir. Troverai tre imbarcazioni ormeggiate oltre la nebbia all\'Approdo di Garrosh, a nord di qui, e una ormeggiata sulla spiaggia di Pal\'ea, a sud. Brucia quelle imbarcazioni in modo che tutti vedano!', },
    nil,
  },
  [11657] = {
    'Afferrare al volo le torce',
    {'Ora sai lanciare una torcia, ma sei anche in grado di afferrarne una al volo?|n|nPrendi queste torce spente, raggiungi il falò e tirane una in aria. Prendila prima che tocchi terra e lanciala nuovamente! Afferrane quattro di fila e torna da me.|n|nAttenzione! Se toccano terra, diventano pericolose! E non mancare la presa, altrimenti dovrai tornare al falò e ricominciare da capo. Buona fortuna!', },
    {'Afferra 4 Torce di fila, poi parla con il Maestro Mangiafuoco.', },
  },
  [11658] = {
    'Piano B',
    {'Va bene, niente panico! Il fulminatore non ha funzionato, ma esistono delle soluzioni alternative.|n|n<Crafty schiocca le dita.>|n|nAllontaneremo la loro attenzione dall\'Aerodromo! Perché il diversivo funzioni, ci serviranno prima alcune cose.|n|n<Ruotadentata ti squadra come se ti stesse valutando.>|n|nLa Carovana di Mordiferro, appena a ovest di qui, ha stupidamente preso una scorciatoia attraverso un cimitero taunka ed è stata distrutta dagli Spiriti Risorti.|n|nRecati laggiù e recupera degli abiti dagli Orchi Morti. Ah, e raccogli anche uno dei loro stendardi!', },
    {'Recupera 10 Completi dei Cantaguerra e uno Stendardo dei Cantaguerra, quindi portali a Crafty Ruotadentata nell\'Aerodromo di Frizzapistone.', },
  },
  [11659] = {
    'Frantuma i globi!',
    {'Stanno... dissanguando i prigionieri... e raccolgono il sangue... in quei globi.|n|n<Gli occhi di Grumm si chiudono per un momento, mentre inclina la testa all\'indietro.>|n|nIl sangue... viene portato alla necropoli... per nutrire il Principe del Sangue...|n|n<Grumm respira a fatica.>|n|nP-promettimi che... distruggerai... quei globi... di sangue... Avverti... Junek.|n|n<Il Braccatore delle Nevi perde conoscenza.>', },
    {'Distruggi 5 Globi di Sangue e fai rapporto al Braccatore delle Nevi Junek nel villaggio di Taunka\'le.', },
  },
  [11660] = {
    'Il Corno del Vecchio Marinaio',
    {'È stato un tenente Kvaldir noto come Orabus a guidare la prima incursione contro la mia gente a Pal\'ea, ed è stato lui a provocare la distruzione di entrambi i villaggi per poi scomparire nella nebbia.|n|nIn quei primi giorni, si parlava spesso di un corno che Orabus avrebbe donato ai Mistici delle Nebbie Kvaldir, da usare per chiamarlo in caso di bisogno.|n|nDobbiamo recuperare quel corno dai Mistici delle Nebbie Kvaldir e richiamare Orabus. Forse, se morisse, questi selvaggi batterebbero in ritirata.|n|nCerca i Mistici delle Nebbie a Pal\'ea, a sud.', },
    {'Waltor di Pal\'ea alla Costa dell\'Eco nella Tundra Boreale ti ha chiesto di portargli il Corno del Vecchio Marinaio.', },
  },
  [11661] = {
    'Orabus il Timoniere',
    {'Prendi il corno e dirigiti a ovest, verso il Molo dei Cantaguerra. Percorri il molo fino in fondo e soffia nel corno. Il suono dovrebbe richiamare Orabus.|n|nUccidi quella bestia immonda e poi torna da me!', },
    {'Waltor di Pal\'ea alla Costa dell\'Eco nella Tundra Boreale ti ha chiesto di usare il Corno del Vecchio Marinaio per evocare Orabus il Timoniere. Una volta che lo hai evocato, uccidi Orabus il Timoniere.', },
  },
  [11662] = {
    'Alla ricerca di Karuk',
    {'Un altro superstite di Pal\'ea di nome Karuk è riuscito a raggiungere la base dei Kvaldir nella Tundra Boreale... molto a sud, dove un tempo la neve era abbondante. Karuk si nasconde sulle alture che si affacciano sulla Sponda degli Sferzalama.|n|nCercalo e riferiscigli ciò che hai fatto per la mia gente qui alla Costa dell\'Eco.|n|nLa via più sicura per raggiungerlo è quella che passa per la vostra fortezza. Dal Forte dei Cantaguerra, prendi la strada a sud e seguila fino a raggiungere la Sponda degli Sferzalama.', },
    {'Cerca Karuk alla Sponda degli Sferzalama.', },
  },
  [11663] = {
    'Riferire quanto appreso',
    {'Grazie, $C! Le informazioni che hai strappato al prigioniero sono di importanza vitale per il Kirin Tor.|n|nFai rapporto a Donathan. Noi intanto pianificheremo la liberazione di Dama Evanor.', },
    {'Normantis ti ha chiesto di fare rapporto al Bibliotecario Donathan alla Scogliera d\'Ambra.', },
  },
  [11664] = {
    'Fuggire dalla nebbia',
    {'Sento le creature della nebbia all\'esterno. Le loro urla mi stanno facendo impazzire, ma non oso provare a fuggire. Dove potrei andare, poi? Quanto tempo potrei durare, prima che mi prendano e mi uccidano come tutti gli altri?|n|nMi chiedo... per quanto si estende la nebbia, $Gstraniero:straniera;? Ricopre ormai tutto il continente?|n|nSei $Gdisposto:disposta; ad aiutarmi a fuggire dalla nebbia? Credo di sapere come fare per tornare da mio padre. Sento ancora il suo spirito vitale, dev\'essere qui vicino.', },
    {'Scorta Mootoo la Giovane fuori dalla nebbia, quindi parla con Mootoo l\'Anziano.', },
  },
  [11665] = {
    'Crocolischi in città',
    {'Salute, $Gragazzo:ragazza;. Sono felice che tu abbia deciso di fare due chiacchiere con questo vecchio. C\'è aria di guai in città.|n|nDi recente, un mercante viandante ha venduto dei cuccioli di crocolisco a degli ingenui bambini. I crocolischi sono bestie selvagge. Molti sono scappati e ora si nascondono nei condotti della città.|n|nPrendi la canna da pesca più resistente che hai, getta l\'amo a Roccavento o a Orgrimmar e portami uno di quei diavoletti. Sono ansioso di vederne uno.', },
    {'Porta un Cucciolo di Crocolisco al Vecchio Barlo. Lo trovi che pesca a nord-est di Shattrath, presso il Lago Silmyr.', },
  },
  [11666] = {
    'Assi della pesca',
    {'Probabilmente sai tutto sul Pesce Persico Dorato; è piuttosto diffuso nei fiumi della Foresta di Terokk ed è una prelibatezza per i Sacerdoti. Ma di sicuro non hai mai sentito parlare del Pesce Persico Pinnanera.|n|nÈ un pesce notoriamente astuto e difficile da pescare. Devi ritirare la lenza all\'ultimo momento, perché prima di abboccare, spiluccano l\'esca.|n|nVai a pescare nei fiumi di Terokk e portami un Pesce Persico Pinnanera. Evita i laghi, perché il Pinnanera vive solo nelle acque in movimento.', },
    {'Porta un Pesce Persico Pinnanera al Vecchio Barlo. Lo trovi che pesca a nord-est di Shattrath, presso il Lago Silmyr.', },
  },
  [11667] = {
    'Quello che è scappato',
    {'Il Pescefango Agile è un pesce di fondale incredibilmente veloce, che si trova nelle acque di Nagrand. Cresce lungo l\'intero arco della sua vita ed è noto per essere un combattente.|n|nAnni fa, ne pescai uno che, ne sono certo, era il pescefango più grande del mondo... ma la lenza si ruppe e la preda fuggì.|n|nNon devo certo dire cosa fare a un pescatore come te: il tuo destino ti attende nei laghi di Nagrand.', },
    {'Cattura il Pescefango più Grande del Mondo per il Vecchio Barlo. Lo trovi che pesca a nord-est di Shattrath, presso il Lago Silmyr.', },
  },
  [11668] = {
    'I gamberetti vanno sudati',
    {'Ci sono parecchi pesci grossi nei laghi delle Paludi di Zangar. Lo sai che cosa mangiano?|n|nGamberetti. Gamberetti Giganti d\'Acqua Dolce. Rokk dice che con i gamberetti si può cucinare un numero infinito di piatti.|n|nMa i gamberetti sono troppo piccoli per pescarli con una canna da pesca. Fai così: apri una Trota Marmorata rigonfia e se hai fortuna troverai uno o due gamberetti.', },
    {'Porta 10 Gamberetti Giganti d\'Acqua Dolce al Vecchio Barlo. Lo trovi che pesca a nord-est di Shattrath, presso il Lago Silmyr.', },
  },
  [11669] = {
    'Filetto di barracuda',
    {'Presto questo vecchio andrà a caccia. Voglio prendere uno Squalo Mammut al largo delle coste di Azshara.|n|nIl problema è che mi serve una tossina che resti sulla punta di una lancia anche sott\'acqua. Per realizzarla, ho bisogno delle ghiandole di un pesce velenoso: il Barracuda Assassino.|n|nQuesto pesce terribile vive solo nelle acque della Penisola del Fuoco Infernale e della Valle di Torvaluna. Portami uno di quei bestioni e sarò un vecchio felice.', },
    {'Porta un Barracuda Assassino Gigante al Vecchio Barlo. Lo trovi che pesca a nord-est di Shattrath, presso il Lago Silmyr.', },
  },
  [11670] = {
    'Sono stati gli Orchi, lo giuro!',
    {'Grazie a tutti quei completi che hai... ehm... recuperato, sono riuscita a realizzare un Camuffamento da Orco Cantaguerra. Ho anche avuto l\'idea geniale di unirlo a della vecchia roba che tenevo da parte dall\'ultima Veglia delle Ombre, per cui il travestimento dovrebbe essere a prova di bomba!|n|nTieni: in questa sacca ci sono il completo e lo stendardo che avevi preso. Recati nelle profondità di Magmoth e uccidi il Capo Tribù dei Magnatauri, Magmothregar.|n|nPianta lo stendardo indossando il camuffamento e li convincerai a concentrare la loro attenzione sugli Orchi Cantaguerra.', },
    {'Dopo aver indossato il Camuffamento da Orco Cantaguerra, pianta lo Stendardo dei Cantaguerra nel cadavere di Magmothregar, quindi torna con il camuffamento da Crafty Ruotadentata all\'Aerodromo di Frizzapistone.', },
  },
  [11671] = {
    'Una corsa contro il tempo',
    {'Dunque è vero: è loro prigioniera.|n|n$R, la nostra linea d\'azione è chiara: DOBBIAMO salvarla.|n|nIo devo restare qui per aiutare a progettare la liberazione, per cui ti chiedo di nuovo aiuto, questa volta per recuperare la chiave della prigione. Tutto ciò che sappiamo di questa Salrand è che non può essere ferita se prima non si distrugge il suo scudo.|n|nAbbiamo realizzato uno speciale esplosivo che dovrebbe distruggere quella protezione, permettendoti di fare ciò che devi. Una volta recuperata la chiave, torna da me.|n|nFai presto, $N. Dama Evanor sta soffrendo!', },
    {'Donathan alla Scogliera d\'Ambra ti ha incaricato di usare il Detonatore dello Scudo di Beryl per distruggere lo scudo al Promontorio di Beryl, quindi di sconfiggere Salrand e recuperare la chiave in suo possesso.', },
  },
  [11672] = {
    'Giorno di reclutamento',
    {'Sei qui per arruolarti, vero? Ordinariamente dovresti metterti in fila insieme alle altre aspiranti reclute. E ordinariamente avresti la sfortuna di scoprire all\'ultimo che manca il registro di arruolamento e che senza di esso io non posso arruolare nessuno.|n|nPer tua fortuna, $N, ho sentito parlare di te e delle tue imprese nelle Terre Esterne. A essere onesti, sei di parecchie spanne superiore a questi poveri disgraziati. Le code non fanno per te.|n|nVai alla caserma e parla col Generale Arlos: sarà più che felice di conoscere qualcuno del tuo calibro.', },
    {'Incontra il Generale Arlos nella caserma del Forte degli Arditi.', },
  },
  [11673] = {
    'Fammi uscire da qui!',
    {'Sapevo che prima o poi avrebbero mandato qualcuno a liberarmi... più poi che prima, a quanto vedo.|n|nEro venuto qui per negoziare con i Neboldi, ma il loro Sciamano, Kaganishu, ha deciso che sarei stato un ottimo spuntino per Magmothregar.|n|nUn momento... cosa?!? Non ti hanno $Gmandato:mandata; qui per liberarmi?!?|n|nSI SONO DIMENTICATI DI ME?!?|n|nVa bene, adesso sei qui e questo è ciò che conta.|n|nSpezza questa catena, così potremo tornare subito all\'Aerodromo. A quel punto potrai comunicare a Frizzapistone che sono tornato incolume.|n|nSempre che si ricordi ancora di me.', },
    {'Scorta Bonker Valvotron in un luogo sicuro e poi fai rapporto a Frizzapistone nell\'Aerodromo di Frizzapistone.', },
  },
  [11674] = {
    'La Saggia Alta Mesa è scomparsa',
    {'Di questi tempi i misteri sembrano moltiplicarsi. Una delle nostre sagge, Alta Mesa, si è sconsideratamente diretta a nord con un solo staffettista per indagare su qualcosa di strano nei pressi dell\'Antro del Trapasso.|n|nChe cos\'è l\'Antro del Trapasso? È un luogo sacro per i Magnatauri: vi si recano in tarda età per morire. Qualche giorno fa la nostra Saggia ha visto qualcosa cadere dal cielo e schiantarsi nelle vicinanze.|n|nSe vuoi guadagnarti la fiducia dei Taunka, aiutaci a ritrovarla. Non è così testarda da non accettare il tuo aiuto.', },
    {'Trova la Saggia Alta Mesa nei pressi dell\'Antro del Trapasso.', },
  },
  [11675] = {
    'Una morte appropriata',
    nil,
    {'Uccidi 10 Magnatauri Appestati, quindi torna dalla Saggia Alta Mesa a sud dell\'Antro del Trapasso.', },
  },
  [11676] = {
    'Liberi, finalmente!',
    {'I soldati che non vengono uccisi sono tenuti prigionieri in gabbie per tutta la campagna. Siamo riusciti a identificare la posizione di alcune chiavi, ma non possiamo avvicinarci abbastanza ai prigionieri per poterli liberare.|n|nAbbiamo bisogno del tuo "talento" per recuperare le chiavi e liberare i prigionieri. Schiaccia la testa ai necrosignori e alle loro aberrazioni e prendi le chiavi, quindi usale per liberare i Prigionieri del Flagello.', },
    {'L\'Inseguitore dell\'Ombra Canarius al Presidio Agricolo dei Cantaguerra ti ha chiesto di liberare 5 Prigionieri del Flagello.', },
  },
  [11677] = {
    'Fermare la Piaga',
    {'Sono convinta che la Piaga sia causata da qualcosa nelle caverne lassù.|n|n$C, prendi questi semi. Di solito li uso per proteggermi dal Flagello, ma forse possono essere usati anche per neutralizzare ciò che di maligno si trova in quegli antri.|n|nTrova la fonte della Piaga e lancia i semi su di essa.', },
    {'La Saggia Alta Mesa, che si trova appena a sud dell\'Antro del Trapasso, ti ha chiesto di usare i Semi Purificatori di Alta Mesa in uno dei Calderoni della Piaga dell\'Antro per neutralizzarlo.', },
  },
  [11678] = {
    'Trovare Corno Peloso',
    {'A quest\'ora, Corno Peloso dovrebbe essere già tornato.|n|nL\'altro motivo per cui eravamo venuti qui era per esplorare quella struttura del Flagello a ovest caduta dal cielo. Corno Peloso è un tipo impulsivo e probabilmente si è cacciato nei guai.|n|n$N, per favore, vai laggiù e trovalo.', },
    {'Trova lo Staffettista Corno Peloso a Talramas.', },
  },
  [11679] = {
    'Riforgiare la chiave',
    {'Un contrattempo dietro l\'altro... proprio l\'unica cosa che non possiamo permetterci adesso!|n|nPer quanto detesti disturbare Ser Surristrasz, egli rappresenta l\'unica possibilità per salvare la nostra amata Evanor.|n|nPortagli i frammenti della chiave e speriamo che sia di umore collaborativo.|n|nFai presto, $C: le nostre squadre d\'assalto stanno aspettando.', },
    {'Donathan ti ha chiesto di parlare con Surristrasz alla Scogliera d\'Ambra.', },
  },
  [11680] = {
    'Prendere il volo',
    {'La chiave è stata riforgiata.|n|nAdesso ascolta il mio consiglio, $R: porta a termine la tua impresa o muori provandoci, perché se ai miei drachi verrà ammaccata anche una sola scaglia, ti riterrò personalmente responsabile.|n|nOra va\'.', },
    nil,
  },
  [11681] = {
    'Salvare Evanor',
    {'Finalmente possiamo attaccare!|n|nUna volta liberata la piattaforma, userò la chiave.|n|nTu dovrai accertarti che, dopo la liberazione, a Dama Evanor non capiti nulla.|n|nAdesso sbrigati, dobbiamo andare!', },
    {'Anzim alla Scogliera d\'Ambra ti ha chiesto di volare insieme ai suoi Maghi da Guerra per andare a liberare Dama Evanor al Promontorio di Beryl. Al termine della missione, dovrai fare rapporto a lei nella Torre del Mago alla Scogliera d\'Ambra.', },
  },
  [11682] = {
    nil,
    {'Ho saputo di quanto hai compiuto qui di recente e, ancora una volta, ti ringrazio.|n|nQuanto a questa minaccia locale, abbiamo recuperato tutte le informazioni che ci servivano e presto sarà neutralizzata. Passiamo piuttosto a questioni più importanti...|n|nAzeroth ha bisogno di te. La regione appena a ovest di qui è improvvisamente diventata teatro di una grave crisi.|n|nLascerò i dettagli a Ser Surristrasz... vai subito a parlargli.|n|nBuona fortuna, $Gamico:amica; di Dalaran.', },
    {'Dama Evanor ti ha inviato da Surristrasz alla Scogliera d\'Ambra.', },
  },
  [11683] = {
    'La necropoli caduta',
    {'La necropoli caduta a ovest probabilmente pullula ancora di membri del Flagello.|n|nMentre ti trovi a Talramas, $C, ti chiederei anche di eliminare tutti i servitori del Re dei Lich che troverai lì e nelle pozze circostanti.', },
    {'Distruggi 20 unità qualsiasi del Flagello a Talramas e alle Pozze Purulente, quindi torna dalla Saggia Alta Mesa appena a sud dell\'Antro del Trapasso.', },
  },
  [11684] = {
    'Perlustrazione delle depressioni',
    {'Senti anche tu queste vibrazioni del suolo?|n|nI Nerubiani del Flagello si stanno muovendo sottoterra. Alcuni sono già emersi a nord-ovest, nelle Solfatare, e stanno assaltando le pattuglie inviate dal Capo Tribù Bora Fredda.|n|n<L\'anziano Taunka ti porge una mappa logora.>|n|nForse un singolo individuo può riuscire là dove le pattuglie hanno fallito. Porta questa con te alle Solfatare e annota la posizione delle Depressioni di Nerub\'ar.', },
    {'Il Padre Anziano Mahan a Taunka\'le ti ha chiesto di usare la Mappa delle Solfatare per contrassegnare la posizione della Depressione Meridionale, della Depressione Nordoccidentale e della Depressione Nordorientale.', },
  },
  [11685] = {
    'Il cuore degli elementi',
    {'Ora che conosciamo la posizione esatta delle Depressioni di Nerub\'ar, possiamo farle crollare e interrompere così l\'offensiva del Flagello, decimandone anche le forze. La Domavento Barah conosce un modo per sfruttare l\'energia degli elementali per far crollare le gallerie nerubiane, ma ha bisogno del tuo aiuto.|n|nA sud-est del villaggio, vicino alla costa oltre il Litorale Ghiacciato, troverai un\'area dominata dagli Elementali della Terra Congelati. Alla Domavento Barah servono i cuori di questi elementali.', },
    {'Porta 5 Cuori Elementali alla Domavento Barah nel villaggio di Taunka\'le.', },
  },
  [11686] = {
    'Il Presidio Agricolo dei Cantaguerra',
    {'Secondo gli appunti di Luther, il Flagello sta usando questo posto come luogo di procreazione di quei mostri che vedi vagare per i campi.|n|n<Ickoris ha un fremito.>|n|nUn tempo quei mostri erano Orchi... Tauren...|n|nPer poter elaborare un piano abbiamo bisogno di altre informazioni. Voglio che perlustri tre luoghi in cui si registra un\'intensa attività del Flagello: il Granaio dei Cantaguerra, a sud-ovest di qui, la Fattoria dei Torp, a ovest di qui, e il vecchio Macello dei Cantaguerra, a nord di qui.|n|nQuando hai finito, torna da me.', },
    {'L\'Inseguitore dell\'Ombra Ickoris al Presidio Agricolo dei Cantaguerra ti ha chiesto di perlustrare il Granaio dei Cantaguerra, la Fattoria dei Torp e il Macello dei Cantaguerra.', },
  },
  [11687] = {
    'Il Dottore e il Signore dei Lich',
    {'Ce ne sono due che... devono essere... uccisi.|n|nIl Dottore e... il Signore dei Lich... di sopra. Trovali... uccidili... prima...|n|n... che sia... troppo tardi...', },
    {'Uccidi il Dottor Ghignolama e il Signore dei Lich Gelinverno, quindi torna dalla Saggia Alta Mesa appena a sud dell\'Antro del Trapasso.', },
  },
  [11688] = {
    'Dannati sporchi suini',
    {'Guardali! I miei meravigliosi kodo sono inermi dinanzi a quei sudici maiali! $N, devi farmi guadagnare tempo. Credo di poter curare la malattia dei kodo, ma tu devi tenere lontani quei Suini Senza Vita, altrimenti non mi rimarrà più nulla da curare!|n|nVai là fuori e sotterra quei maiali una volta per tutte!', },
    {'Il Contadino Torp al Presidio Agricolo dei Cantaguerra ti ha chiesto di uccidere 10 Suini Senza Vita.', },
  },
  [11689] = {
    'Tornare con cattive notizie',
    {'La Madre Anziana deve saperlo.|n|nPotresti tornare a Taunka\'le e dirle che sarò lì tra breve?', },
    {'Parla con la Madre Anziana Taiga a Taunka\'le.', },
  },
  [11690] = {
    'Riportali vivi',
    {'$N, prendi questo morso. Noterai che sulla punta ho collocato un piccolo somministratore. Basterà che il kodo lo morda per venire curato dall\'infezione. Curali tutti e poi riportali a casa. Saranno molto deboli, quindi dovrai condurli con molta pazienza.|n|nRiportami i miei piccoli, $N!|n|nUn\'ultima cosa: hai dieci minuti per farlo! È questa la durata dell\'efficacia dell\'antidoto all\'interno del morso.', },
    {'Il Contadino Torp al Presidio Agricolo dei Cantaguerra ti ha chiesto di salvare 8 Bestie Kodo Infette.', },
  },
  [11691] = {
    'Evocate Ahune',
    {'I miei Sciamani e io abbiamo raccolto le forze per la battaglia che ci aspetta con il Signore del Gelo. $N, tu sarai l\'avanguardia della Madre Terra.|n|nPrendi questo Totem di Magma e usalo sulla Pietra Ghiacciata a nord-est. Ahune sta convogliando il suo potere in quella roccia. Speriamo che il Totem lo distrugga e spezzi il suo legame con i Piani Elementali.|n|nSe la fortuna ci sorride, forse riusciremo a sconfiggerlo.|n|nPreparati, $N. Se Ahune dovesse venire ad affrontarci, la sua furia sarà sconfinata.', },
    {'Porta il Totem di Magma del Circolo della Terra alla Pietra Ghiacciata.', },
  },
  [11692] = {
    'Rapporto da Bixie',
    {'Ti sei $Gdimostrato un vero eroe:dimostrata una vera eroina;, ma ora ho un altro problema!|n|nTinky si è recata a est insieme a Bixie Chiavetosta e io non riesco a far funzionare quest\'affare! Tinky è l\'unica in grado di ripararlo e abbiamo davvero bisogno che funzioni a pieno regime.|n|nCredi di poterle raggiungere? Bixie aveva accennato al fatto che avrebbero seguito un vecchio Magnatauro in un posto chiamato Antro del Trapasso.|n|nProbabilmente le troverai lì.|n|nPuoi farti dare un passaggio fin laggiù da Kara Trestelle alla pista.', },
    {'Mordle Ruotastretta ti ha chiesto di cercare Bixie Chiavetosta a sud dell\'Antro del Trapasso.', },
  },
  [11693] = {
    'Oh, fantastico... un Magnatauro Appestato!',
    {'Tinky e io siamo venute fin quaggiù per seguire un vecchio Magnatauro. A quanto pare, quelle caverne laggiù sono il posto in cui vanno a morire.|n|nNaturalmente non avevamo la minima idea che entrando là dentro si sarebbero appestati. Non possiamo permettere che delle creature appestate vadano in giro liberamente, non è sicuro.|n|nEhi, perché non abbatti un po\' di Magnatauri mentre io penso alla nostra prossima mossa?', },
    {'Uccidi 10 Magnatauri Appestati, quindi torna da Bixie Chiavetosta a sud dell\'Antro del Trapasso.', },
  },
  [11694] = {
    'Qualcosa non va in quelle caverne',
    {'Mentre tu eri in giro a massacrare quelle bestie appestate, io sono andata a dare un\'occhiata a quelle caverne.|n|nÈ tutta opera di alcuni cultisti che sono lì dentro!|n|nHanno preparato una mistura nociva in un calderone. Ho una polvere che di solito uso come antidoto. L\'ho mischiata ad altra roba e penso che possa neutralizzare quella miscela!|n|nPortala in una di quelle caverne e vedi se funziona.', },
    {'Bixie Chiavetosta, che si nasconde appena a sud dell\'Antro del Trapasso, ti ha chiesto di versare la Polvere Inibitoria di Bixie in uno dei Calderoni della Piaga per neutralizzarlo.', },
  },
  [11695] = {
    'Il Corno della Furia Elementale',
    {'Con questi pezzi di pietra inanimata posso creare la forma di un elementale, ma infondergli la vita è tutta un\'altra storia. Ci vorrà anche un po\' di fortuna.|n|nLa leggenda parla di un antico manufatto chiamato Corno della Furia Elementale, ricercato da un grande eroe. Ti presterò una pergamena con una copia del racconto. Non so se la leggenda si basi su fatti reali, ma non abbiamo altre soluzioni. Se la storia è vera, i frammenti del corno si trovano nelle Pianure Alluvionali che circondano il villaggio a nord e a sud-ovest.', },
    {'Recupera la Metà Inferiore del Corno e la Metà Superiore del Corno dal Capo Tribù Burblegobble e dal Capo Tribù Gurgleboggle, poi portali alla Domavento Barah nel villaggio di Taunka\'le.', },
  },
  [11696] = {
    'Ahune è qui!',
    {'$N, la tua presenza è una benedizione. Ahune giace in queste caverne, raccogliendo le energie per l\'assalto. Sono state già inviate le forze del Circolo della Terra, ma da sole non possono sconfiggerlo.|n|nVai in esplorazione, $N. Trova gli Sciamani del Circolo della Terra e parla con il loro capo, Luma Madre Celeste. Forse, con l\'aiuto delle tue capacità, riusciremo a battere Ahune prima che sia troppo tardi.', },
    {'Cerca Luma Madre Celeste nelle Fosse degli Schiavi.', },
  },
  [11697] = {
    'Dannazione, Tinky è andata alla necropoli!',
    {'Io l\'avevo detto a Tinky di non separarsi da me, ma lei doveva ASSOLUTAMENTE andare a dare un\'occhiata a quella necropoli caduta a ovest.|n|nSono sicura al cento percento che quei cultisti vengono da lì, il che significa che adesso Tinky è nei guai!|n|nTinky è il miglior ingegnere dell\'Aerodromo: senza di lei siamo spacciati!|n|nAndrei a cercarla io stessa, ma una di quelle cose mi ha colpita alla gamba prima che riuscissi a nascondermi. $N, se c\'è qualcuno che può tirarla fuori di lì, sei tu!', },
    {'Trova Tinky Fischiamiccia a Talramas.', },
  },
  [11698] = {
    'Perché non spazziamo via il Flagello?',
    {'Se i cultisti di quelle caverne sono sopravvissuti alla caduta di quella necropoli a ovest, allora possiamo ipotizzare che la necropoli sia ancora piena di membri del Flagello. Probabilmente ce ne saranno molti altri anche davanti alle pozze!|n|nGià che ti trovi a Talramas, non potresti neutralizzare i tirapiedi del Re dei Lich che troverai lì?', },
    {'Uccidi 20 Membri qualsiasi del Flagello a Talramas e alle Pozze Purulente, poi torna da Bixie Chiavetosta appena a sud dell\'Antro del Trapasso.', },
  },
  [11699] = {
    'Sono rinchiusa in questa gabbia... ma ancora per poco!',
    {'I cultisti mi hanno rinchiusa magicamente in questa gabbia senza via d\'uscita. Ignoravano però che all\'Aerodromo sono una dei maggiori esperti di transmateria!|n|nCon il tuo aiuto e un po\' di olio di gomito, non resterò chiusa qui dentro ancora per molto.|n|nMi servirà il Cristallo di Nucleo del Motore in possesso di uno dei Ghoul, il Giroscopio Magico del loro dottore e la Pietra del Flagello Timone del Signore dei Lich di sopra.|n|nCon tutte queste componenti dovrei riuscire a realizzare un dispositivo di teletrasporto e tornare a Frizzapistone alla maniera degli Gnomi!', },
    {'Recupera un Cristallo di Nucleo del Motore, un Giroscopio Magico e un Pietra del Flagello Timone, quindi porta tutto a Tinky Fischiamiccia nella necropoli di Talramas.', },
  },
  [11700] = {
    'Avvisare Bixie',
    {'La mia gemella malvagia è lì da qualche parte.|n|nSono sicura che non è tornata all\'Aerodromo. Anzi, in qualunque posto sia finita, fa certamente più freddo di qui. Sono riuscita a "sentire" la sua presenza solo per un momento.|n|nOh be\', sarà meglio che riconfiguri al più presto quest\'aggeggio e torni subito all\'Aerodromo. Nel frattempo, non potresti andare a est e avvisare Bixie che la aspetto lì?|n|nGrazie, $N!', },
    {'Parla con Bixie Chiavetosta appena a sud dell\'Antro del Trapasso.', },
  },
  [11701] = {
    'Ritorno all\'Aerodromo',
    {'Bene, credo che adesso mi avvierò anch\'io verso l\'Aerodromo. Naturalmente questa ferita alla gamba mi rallenterà un po\'.|n|nEhi, non potresti precedermi e dare tu la bella notizia al vecchio Frizzapistone? Scommetto che riceverai anche una bella ricompensa.|n|nGrazie, $N!', },
    {'Parla con Frizzapistone all\'Aerodromo di Frizzapistone nella Tundra Boreale.', },
  },
  [11702] = {
    'Il Re Mrgl-Mrgl',
    {'Ti parrà strano, $C, ma ci sta nu Murloc che chiede l\'aiuto nuostr\'!|n|nSi chiama Re Mrgl-Mrgl ed è il capo dei Murloc Pinnafredda. Isso e la gente sua sono stati scacciati dal villaggio loro e vogliono che li salvi.|n|nLo troverai a ovest e giù per il dirupo, nella parte meridionale del Rifugio dei Pinnafredda.', },
    {'Parla con il Re Mrgl-Mrgl al Rifugio dei Pinnafredda.', },
  },
  [11703] = {
    'Parlare con Getry',
    {'L\'agente del Flagello che sta supervisionando la cattura e la trasformazione dei soldati dell\'Orda in mostri non morti sta utilizzando la fattoria a nord-ovest come Radura della Procreazione. L\'Inseguitore dell\'Ombra Getry ha seguito quel mostro per settimane e ha raccolto informazioni vitali che potrebbero aiutarci a neutralizzare questa minaccia.|n|nRaggiungi Getry e vedi se puoi aiutarlo a fermare la catena di produzione del Flagello. Troverai Getry nella torre abbandonata al confine nord-ovest di questo presidio.', },
    {'Trova l\'Inseguitore dell\'Ombra Getry al Presidio Agricolo dei Cantaguerra.', },
  },
  [11704] = {
    'Il Re Mrgl-Mrgl',
    {'È una cosa stranissima, $C, ma c\'è un Murloc che ci ha chiesto aiuto!|n|nSi chiama Re Mrgl-Mrgl ed è il capo dei Murloc Pinnafredda. A quanto pare, lui e i suoi sudditi sono stati scacciati dal proprio villaggio e cercano qualcuno che vada in loro soccorso.|n|nQuel qualcuno, naturalmente, sei tu!|n|nTroverai il Rifugio dei Pinnafredda e il Re seguendo la strada a ovest fino alla scogliera. A quel punto, scendi seguendo l\'acqua vicino all\'Acquitrino Bollente.', },
    {'Parla con il Re Mrgl-Mrgl al Rifugio dei Pinnafredda.', },
  },
  [11705] = {
    'Sciocchi tentativi',
    nil,
    nil,
  },
  [11706] = {
    'Il crollo',
    {'Ho creato Alluvius con l\'aiuto del Corno della Furia Elementale. Recati nei pressi della depressione più a sud nelle Solfatare e suona il corno.|n|nAlluvius ti raggiungerà e scatenerà un terremoto che dovrebbe far crollare le gallerie nerubiane e porre fine al loro attacco. Non mi sorprenderebbe se, dopo il terremoto, scendesse in campo il comandante dei Nerubiani in persona. Se il crollo delle gallerie non dovesse bastare a spezzare l\'assalto dei Nerubiani, la morte del loro capo lo farà senz\'altro.', },
    {'La Domavento Barah a Taunka\'le ti ha chiesto di far crollare le Depressioni di Nerub\'ar usando il Corno della Furia Elementale e di sconfiggere Sire Kryxix.', },
  },
  [11707] = {
    'Richiesta di soccorso',
    {'Oh, bene, tu sei $N, vero?|n|nAbbiamo urgentissimo bisogno del tuo aiuto a nord, all\'Aerodromo di Frizzapistone! I Magnatauri, il Flagello, la Stazione di Pompaggio...|n|nÈ un casino, ti dico, un casino!|n|nDevi recarti laggiù e parlare col vecchio Frizzapistone il prima possibile!', },
    {'Parla con Frizzapistone all\'Aerodromo di Frizzapistone.', },
  },
  [11708] = {
    'I Meccanognomi',
    {'Bene, adesso ti racconterò per filo e per segno cosa sta succedendo qui.|n|nQuando avrò finito, esci e cerca il mio braccio destro, Jinky Alameccanica. Da quel momento in poi, sarà lei a occuparsi di tutto.', },
    {'Ascolta la storia di Frizzapistone, quindi cerca Jinky Alameccanica all\'Aerodromo di Frizzapistone.', },
  },
  [11709] = {
    'La carica di Nork Sangueduro',
    {'Anche se hai già fatto molto per rafforzare la nostra presenza in queste fredde terre desolate, nell\'ombra si aggirano ancora altri pericoli. Vorrei che aiutassi il Custode Nork Sangueduro, di stanza nel campo di prigionia appena fuori e immediatamente a sud-est del Forte dei Cantaguerra. Cercalo e offrigli la tua assistenza per il trasporto e lo scambio dei prigionieri.|n|nPuoi andare, $N.', },
    {'Parla col Custode Nork Sangueduro al Forte dei Cantaguerra nella Tundra Boreale.', },
  },
  [11710] = {
    'Transmateria in entrata',
    {'Ci sono Pezzi di Ricambio disseminati in tutta l\'area a est di qui, alle Pozze Sulfuree, alle Solfatare... diamine, forse anche alla Stazione di Pompaggio. Portamene un po\'. Forse riuscirò a riparare il teletrasporto in uscita e magari anche a riallineare il dispositivo transmaterico in entrata.|n|nNon vorrei ripetere quell\'incidente...', },
    {'Recupera 15 Pezzi di Ricambio di Frizzapistone e consegnali a Mordle Ruotastretta nell\'Aerodromo di Frizzapistone.', },
  },
  [11711] = {
    'Consegna di codardi: oltre i 30 minuti è gratis',
    nil,
    {'Porta il Disertore dell\'Alleanza all\'incrocio a est del Forte dei Cantaguerra e usa la tua Spararazzi dei Cantaguerra per segnalare la tua presenza all\'Alleanza.|n|nUna volta consegnato il Disertore dell\'Alleanza, fai rapporto all\'Esploratore Tungok.', },
  },
  [11712] = {
    nil,
    {'Se hai ascoltato bene il vecchio, allora saprai che là fuori ci sono degli Gnomi mutati. Il Mastro Meccanico Mecazod li ha infettati con qualcosa che ha invertito la "Maledizione della Carne", trasformandoli in robot!|n|nPer fortuna, crediamo di sapere come fare per maledirli di nuovo e farli tornare alla normalità. Tu dovresti prendere questo Iniettore Transmaterico Rimaledicente e usarlo su cadaveri dei Meccanognomi in cui ti imbatti.|n|nLa nostra speranza è che questa roba li curi e ci permetta di teletrasportarli via di lì.|n|nChe ne dici, $N?', },
    {'Jinky Alameccanica all\'Aerodromo di Frizzapistone ti ha chiesto di usare l\'Iniettore Transmaterico Rimaledicente su 6 Meccanognomi di Frizzapistone.', },
  },
  [11713] = {
    'Perlustrazione delle depressioni',
    {'Frizzapistone ha inviato uno squadrone di ricognizione aerea per mappare le Depressioni di Nerub\'ar della parte meridionale delle Solfatare, ma lo squadrone non è ancora rientrato. Non posso permettermi di attendere oltre le loro informazioni, per cui mi serve qualcuno che faccia lo stesso lavoro via terra.|n|nComprendo la pericolosità della missione e prometto una ricompensa adeguata. Porta questa mappa con te e annota ogni informazione vitale su ciascuna depressione in cui t\'imbatti.', },
    {'Abner Frizzacoppia all\'Aerodromo di Frizzapistone ti ha chiesto di usare la Mappa delle Solfatare per contrassegnare la posizione della Depressione Meridionale, della Depressione Nordoccidentale e della Depressione Nordorientale.', },
  },
  [11714] = {
    'Sterminio dei parassiti',
    nil,
    {'L\'Esploratore Tungok presso le Pianure degli Sporasangue nella Tundra Boreale ti ha chiesto di uccidere 8 Falciatori Sporasangue, 5 Piromani Sporasangue e 2 Bruciatori Sporasangue.', },
  },
  [11715] = {
    'Alimentare il progetto',
    {'Intendo costruire una macchina per far crollare le gallerie che il Flagello sta utilizzando per schierare i Nerubiani, ma poiché l\'impianto di trivellazione principale è guasto, dovremo recuperare il combustibile in un altro modo.|n|nNelle Solfatare a sud-est, lontane dall\'impianto principale, ci sono delle piccole pozze di petrolio. Se raccogliessi abbastanza petrolio da quelle pozze, potrei ricavarne del combustibile grezzo per la macchina.|n|nPosiziona il Raccoglitore accanto all\'impianto e il petrolio verrà pompato e raccolto nel serbatoio.', },
    {'Abner Frizzacoppia all\'Aerodromo di Frizzapistone ti ha chiesto di recuperare 8 Barili di Petrolio utilizzando il Raccoglitore di Petrolio Portatile.', },
  },
  [11716] = {
    'La meravigliosa Sporasangue',
    {'$N, qui stiamo assistendo a qualcosa di sorprendente. A pochi passi da noi, vive e respira un intero ecosistema finora ignoto! Immagino sia stata la Sporasangue a mettere tutto l\'ambiente in subbuglio.|n|nHo raccolto dei campioni di polline dagli esemplari maschi di Sporasangue nelle vicinanze ma ora, per l\'impollinazione, mi servono i recettori femminili. Portami un po\' di Fogliame Interno di Sporasangue: potrai trovarlo sulle piante più grosse qui intorno.|n|nFai attenzione ai loro guardiani! I Coboldi non ti lasceranno agire $Gindisturbato:indisturbata;!', },
    {'La Maga del Sangue Laurith presso le Pianure degli Sporasangue nella Tundra Boreale ti ha chiesto di recuperare 10 Campioni di Fogliame Interno di Sporasangue.', },
  },
  [11717] = {
    'Polline dalla fonte',
    nil,
    nil,
  },
  [11718] = {
    'Un robot travestito da mammut',
    {'Ho riconfigurato lo scheletro di un vecchio robot per causare un terremoto abbastanza potente da far crollare le gallerie. Tuttavia il macchinario è molto delicato e sensibile al freddo pungente di Nordania.|n|nHo ideato un modo per isolare la macchina utilizzando le pelli più spesse dei mammut locali, che vagano per le pianure a sud dell\'Aerodromo e adiacenti alle Solfatare. Portami le pelli che mi servono per completare la macchina e finalmente potremo metterla in funzione contro i Nerubiani!', },
    {'Abner Frizzacoppia all\'Aerodromo di Frizzapistone ti ha chiesto di portargli 6 Pelli di Mammut Spesse.', },
  },
  [11719] = {
    'Una cavia adatta',
    {'<Laurith ti guarda come per soppesarti.>|n|nAllora, abbiamo questo Fiore di Sporasangue Impollinato e nessuno su cui provarne gli effetti. Per caso non saresti <disposto/disposta> a strofinartelo sulla pelle per farmi vedere che effetto fa? Del resto, cosa potrebbe mai accadere?|n|nNon preoccuparti, $N! Su, prendi questo campione e strofinatelo sul volto.', },
    {'La Maga del Sangue Laurith presso le Pianure degli Sporasangue nella Tundra Boreale ti ha chiesto di usare il Fiore di Sporasangue Impollinato e di permetterle di vederne gli effetti.', },
  },
  [11720] = {
    'L\'invasione di Gammoth',
    nil,
    nil,
  },
  [11721] = {
    'Gammothra il Tormentatore',
    {'I Magnatauri vivono in branchi, come i leoni: uno o due maschi dominanti e diverse femmine con i piccoli. Nel caso di Gammoth, la tana dei Magnatauri a ovest di qui, il maschio dominante si chiama Gammothra. È lui ad avere il comando sui Magnatauri locali e dunque è lui che bisogna uccidere per eliminare alla radice qualsiasi rischio di attacco da quel fronte.|n|nPrendi questa sacca con fiori di Sporasangue frantumati e portala a Gammoth. Usa la polvere di Sporasangue per indebolire Gammothra e poi uccidilo! Come prova della sua morte, portami la sua testa.', },
    {'Uccidi Gammothra e porta la Testa di Gammothra a Corno Forte Primordiale presso le Pianure degli Sporasangue nella Tundra Boreale.', },
  },
  [11722] = {
    'Trofei di Gammoth',
    {'Non possiamo prenderci tutti i meriti per questa vittoria dell\'Orda. Sei $Gstato:stata; tu a rischiare la vita provando la Sporasangue sulla tua pelle e alla fine sei $Gstato:stata; tu a uccidere Gammothra.|n|nSarebbe un onore per noi se tornassi al Forte dei Cantaguerra e portassi la Testa di Gammothra a Malogrido.', },
    {'Porta la Testa di Gammothra a Garrosh Malogrido nel Forte dei Cantaguerra.', },
  },
  [11723] = {
    'Tremazinga in funzione!',
    {'Ammira la macchina che ci salverà dalla minaccia nerubiana!|n|n<Fiero e radioso, Abner presenta il robot completato.>|n|nPrendi questo telecomando, recati nelle depressioni delle Solfatare più a sud e usalo per attivare il Tremazinga 5000. Al resto ci penserà lui.|n|nNon sorprenderti se il terremoto attirerà l\'attenzione di un capo dei Nerubiani. Anzi, potresti cogliere la palla al balzo e infliggere un\'ulteriore battuta d\'arresto all\'offensiva nerubiana.', },
    {'Abner Frizzacoppia all\'Aerodromo di Frizzapistone ti ha chiesto di usare il Tremazinga 5000 per far crollare le gallerie nerubiane e di uccidere Sire Kryxix.', },
  },
  [11724] = {
    'Un\'enorme omelette di falena?',
    {'<Chiaramente quest\'uovo era importante per qualcuno, come può dimostrare il cadavere che gli sta accanto. Esaminando l\'uovo, noti che era già stato contrassegnato per essere spedito alle Pianure degli Sporasangue e consegnato alla Maga del Sangue Laurith, appena a est di qui!>|n|n<Raccogli l\'uovo e decidi di portarlo alla Maga del Sangue in attesa.>', },
    {'Porta l\'Uovo Rilucente Enorme alla Maga del Sangue Laurith presso le Pianure degli Sporasangue nella Tundra Boreale.', },
  },
  [11725] = {
    'Alla ricerca del Pilota Giracode',
    {'Sarei dovuto andare in missione io stesso. Non è che non mi fidi di Giracode... al contrario. Diamine, è uno dei migliori piloti con cui abbia mai volato.|n|nNo, è solo che dovevo essere io ad assumermi la responsabilità diretta di una missione di tale importanza.|n|nInvece ho inviato Giracode, insieme al più veloce squadrone di ricognizione che abbiamo, per raccogliere informazioni sull\'infestazione nerubiana nelle Solfatare.|n|nIn base all\'ultimo rapporto ricevuto, lo squadrone si trova nelle pozze appena a ovest e molto a sud delle depressioni nerubiane.|n|n$N, trova Giracode.', },
    {'Localizza Iggy "Giracode" Scambiaviti nelle Solfatare.', },
  },
  [11726] = {
    'Un po\' di spezie',
    {'Sin dal momento dell\'impatto, i lupi hanno fatto visita ai rottami, e temo che questi animali abbiano mangiato il microfilm con le informazioni raccolte.|n|nHo un piano per recuperare il microfilm, ma tu dovrai aiutarmi a metterlo in atto.|n|nA sud e a est, nelle Pianure Alluvionali, vivono delle creature chiamate Gorloc. Essi preparano il loro cibo con spezie velenose, che farebbero star male qualsiasi altra creatura. Se tu recuperassi abbastanza sacche di spezie dai Gorloc Sputavapore o dai Gorloc Vagabondi, potrei preparare un\'esca per i lupi.', },
    {'Iggy "Giracode" Scambiaviti alle Pozze Sulfuree ti ha chiesto di recuperare 4 Sacche di Spezie dei Gorloc.', },
  },
  [11727] = {
    'Il tempo degli eroi',
    {'È un piacere averti tra noi, $N: abbiamo tutti sentito parlare delle tue imprese.|n|nCome saprai, Re Wrynn sta inviando numerose armate a Nordania in vista dello scontro con Arthas. Le armate però sono poco utili se non sono ispirate e guidate da veri eroi.|n|nE io voglio che tu lo sia per i miei uomini. Combatti al loro fianco contro il Flagello che assedia la nostra roccaforte.|n|nFai rapporto al Sergente Mazzacolle fuori dal Mastio Interno. Forte degli Arditi non deve cadere. Il futuro della nostra campagna dipende da questo.', },
    {'Fai rapporto al Sergente Mazzacolle nel Forte degli Arditi.', },
  },
  [11728] = {
    nil,
    {'Qualsiasi cosa tu faccia, non mangiare questa esca. Collocala piuttosto nelle vicinanze di un Lupo Zuppo di Petrolio. Se erano tanto disperati da mangiare il microfilm, quando sentiranno l\'odore accorreranno immediatamente.|n|nAspetta che la natura segua il suo corso e poi non dovrai far altro che frugare nel, ehm... sottoprodotto alla ricerca del microfilm.|n|nPer questo compito ti offrirei il mio speciale Lupus Pupus Scupus, ma l\'ho lasciato all\'Aerodromo. Temo che dovrai condurre la... ehm... ricerca alla vecchia maniera.', },
    {'Iggy "Giracode" Scambiaviti alle Pozze Sulfuree ti ha chiesto di portargli 8 Pezzi del Microfilm.', },
  },
  [11729] = {
    'Il Cacciavite Ultrasonico',
    {'<L\'unità che hai appena smontato conteneva questo tra i meccanismi al suo interno.>|n|n<Sembra tutto molto complesso... Di sicuro qualcuno all\'Aerodromo sarà interessato a dare un\'occhiata. Forse Crafty Ruotadentata?>', },
    {'Consegna il Cacciavite Ultrasonico a Crafty Ruotadentata nell\'Aerodromo di Frizzapistone.', },
  },
  [11730] = {
    'Padrone e servitore',
    {'Il Cacciavite Ultrasonico rappresenta l\'attrezzo definitivo: puoi farci qualsiasi cosa!|n|nTorna alle Pozze e smonta alcuni dei robot di Mecazod, quindi usa il Cacciavite sui loro resti. Scommetto che li riprogrammerai in favore della nostra causa, anche se solo temporaneamente.|n|nSono certa che non funzionerà sui Meccanognomi, quindi non perdere tempo con loro.|n|nOh, e se vuoi prelevare qualsiasi cosa dall\'interno dei robot, fallo prima di usare il Cacciavite!', },
    {'Usa il Cacciavite Ultrasonico per riprogrammare 15 Robot, quindi torna da Crafty Ruotadentata all\'Aerodromo di Frizzapistone.|n|nSaccheggia i robot prima di riprogrammarli.', },
  },
  [11731] = {
    'Lanciare le torce',
    nil,
    {'Supera la prova di lancio delle torce, poi parla con il Maestro Mangiafuoco.', },
  },
  [11732] = {
    'Dissacra questo Falò!',
    nil,
    nil,
  },
  [11733] = {
    'Attraversare la fenditura',
    {'Ho seguito con attenzione i tuoi sforzi, mortale. Non fingere sorpresa: avrai di certo sentito il mio sguardo su di te.|n|nBene, è giunto il momento di liberare la tua mente da un primo strato di ignoranza: sei ormai $Gpronto:pronta; ad accettare alcune crude verità.|n|nMa al bando le chiacchiere: passeremo subito all\'esperienza diretta.|n|nTi consiglio di sistemare gli affari in sospeso, $C...', },
    {'Surristrasz ti ha chiesto di recarti a Ibernia. Una volta lì, dovrai parlare con l\'Arcimago Berinand.', },
  },
  [11734] = {
    'Dissacra questo Falò!',
    nil,
    nil,
  },
