  [13720] = {
    'L\'incarico del Valoroso',
    {'Nel corso dell\'addestramento tuo come Valoroso avrai la possibilità di mettere alla prova le capacità tue contro i Valorosi che rappresentano le altre città. Pure se le battaglie di nu Valoroso nun fanno formalmente parte della competizione, apprenderai cose assai importanti sulli stili di combattimento e sulle debolezze delli avversari tuoi.|n|nI Valorosi sono prodi guerrieri che si affrontano per fama e onore.|n|nProsegui l\'addestramento tuo da Valoroso finché nun pensi di poter sconfiggere l\'avversario tuo, poi portami i sigilli che hai ottenuto.', },
    {'Porta 25 Sigilli del Valoroso a Runok Manto Selvaggio nei Campi del Torneo d\'Argento.', },
  },
  [13721] = {
    'L\'incarico del Valoroso',
    {'Nel corso dell\'addestramento tuo come Valoroso avrai la possibilità di mettere alla prova le capacità tue contro i Valorosi che rappresentano le altre città. Pure se le battaglie di nu Valoroso nun fanno formalmente parte della competizione, apprenderai cose assai importanti sulli stili di combattimento e sulle debolezze delli avversari tuoi.|n|nI Valorosi sono prodi guerrieri che si affrontano per fama e onore.|n|nProsegui l\'addestramento tuo da Valoroso finché nun pensi di poter sconfiggere l\'avversario tuo, poi portami i sigilli che hai ottenuto.', },
    {'Porta 25 Sigilli del Valoroso all\'Inseguitore della Morte Visceri nei Campi del Torneo d\'Argento.', },
  },
  [13722] = {
    'L\'incarico del Valoroso',
    {'Nel corso dell\'addestramento tuo come Valoroso avrai la possibilità di mettere alla prova le capacità tue contro i Valorosi che rappresentano le altre città. Pure se le battaglie di nu Valoroso nun fanno formalmente parte della competizione, apprenderai cose assai importanti sulli stili di combattimento e sulle debolezze delli avversari tuoi.|n|nI Valorosi sono prodi guerrieri che si affrontano per fama e onore.|n|nProsegui l\'addestramento tuo da Valoroso finché nun pensi di poter sconfiggere l\'avversario tuo, poi portami i sigilli che hai ottenuto.', },
    {'Porta 25 Sigilli del Valoroso a Eressea Cantalba nei Campi del Torneo d\'Argento.', },
  },
  [13723] = {
    'La sfida del Valoroso',
    nil,
    {'Parla con lo Scudiero Danny per affrontare il tuo avversario. Una volta sconfitto il Campione d\'Argento, torna da Ambrose Sprazzavite ai Campi del Torneo d\'Argento.|n|nSe perdi la tua lancia, puoi prenderne un\'altra da una Rastrelliera delle Lance vicino alle scuderie o nel Padiglione del Patto d\'Argento.', },
  },
  [13724] = {
    'La sfida del Valoroso',
    nil,
    {'Parla con lo Scudiero Danny per affrontare il tuo avversario. Una volta sconfitto il Campione d\'Argento, torna da Colosos ai Campi del Torneo d\'Argento.|n|nSe perdi la tua lancia, puoi prenderne un\'altra da una Rastrelliera delle Lance vicino alle scuderie o nel Padiglione del Patto d\'Argento.', },
  },
  [13725] = {
    'La sfida del Valoroso',
    {'Sei quasi $Gpronto:pronta; a competere in nome di Darnassus nella Gran Mischia. Per dimostrarti $Gdegno:degna; di rappresentare la tua città devi sconfiggere un Campione della Crociata d\'Argento.|n|nRecati alle scuderie fuori dal padiglione, imbraccia la tua lancia e monta sulla cavalcatura. Parla con lo Scudiero Danny all\'Arena dei Valorosi d\'Argento sul lato occidentale dei campi. Quando sei $Gpronto:pronta;, lo scudiero chiamerà il tuo avversario.|n|nUna volta conclusa la battaglia, parleremo dell\'esito.', },
    {'Parla con lo Scudiero Danny per affrontare il tuo avversario. Una volta sconfitto il Campione d\'Argento, torna da Jaelyne Belcanto ai Campi del Torneo d\'Argento.|n|nSe perdi la tua lancia, puoi prenderne un\'altra da una Rastrelliera delle Lance vicino alle scuderie o nel Padiglione del Patto d\'Argento.', },
  },
