  [14170] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito Elfo della Notte Allegro nel Cimitero di Darnassus.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14171] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito Elfo del Sangue Allegro nel Cimitero di Lunargenta.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14172] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito Aldor Allegro nel Cimitero di Shattrath.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14173] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito Veggente Allegro nel Cimitero di Shattrath.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14174] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    nil,
