  [14175] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito d\'Orco Allegro nel Cimitero di Orgrimmar.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14176] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    nil,
  },
  [14177] = {
    'Il caro estinto',
    {'È bello tornare a fare visita ad amici e parenti, ma forse ho un po\' esagerato: ho già mangiato tutto quello che avevano preparato per me!|n|nPosso chiederti di portarmi dell\'altro delizioso Pane dei Morti? Te ne sarei molto grato.|n|nChapman vende la ricetta, se non sbaglio.', },
    {'Ottieni del Pane dei Morti e consegnalo allo Spirito Troll Allegro nel Cimitero di Orgrimmar.|n|nUsa una Calendula Arancione per vedere gli spiriti invisibili.', },
  },
  [14178] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'$GRagazzo:Ragazza;, la maggiore difficoltà di combattere su più fronti è il rischio di disperdere troppo le nostre forze, rischiando di trovarci poi senza!|n|nÈ vitale decidere giornalmente il posizionamento delle truppe più importanti. Oggi c\'è bisogno di rinforzi nel Bacino d\'Arathi.|n|nTorna da me con la notizia della nostra vittoria, $N. Non possiamo permettere che quelle risorse preziose finiscano nelle mani dell\'Orda. Ci appartengono di diritto!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [14179] = {
    'Chiamata alle armi: Occhio del Ciclone',
    {'La battaglia contro l\'Orda prosegue senza quartiere, $N. Le dispute territoriali e i vecchi rancori bastano per far scoppiare la guerra anche nelle Terre Esterne.|n|nVai nell\'Occhio del Ciclone e combatti per far prevalere anche qui l\'Alleanza.', },
    {'Vinci uno scontro sul campo di battaglia nell\'Occhio del Ciclone e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [14180] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'Le Sentinelle Alargentea combattono per proteggere la foresta della Forra dei Cantaguerra. Le aiutiamo non perché siamo degli ecologisti, ma perché la foresta è una difesa naturale per il territorio dell\'Alleanza.|n|nMai come oggi hanno bisogno del nostro aiuto. Dobbiamo inviare subito rinforzi se non vogliamo che Valtetra venga annessa alle Savane!', },
    {'Vinci uno scontro sul campo di battaglia della Forra dei Cantaguerra e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [14181] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'Il Bacino d\'Arathi sta per essere conquistato dall\'Alleanza. Dobbiamo inviare immediatamente rinforzi o tutti i nostri sforzi saranno stati vani.|n|nNon indugiare, $C, e vai nel Bacino d\'Arathi per affrontare il nemico. Vittoria all\'Orda!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [14182] = {
    'Chiamata alle armi: Occhio del Ciclone',
    {'Affronteremo e schiacceremo i nemici ovunque li incontreremo. Sia Azeroth o le Terre Esterne, non fa alcuna differenza.|n|nNon possiamo permettere all\'Alleanza di sopravanzarci nell\'Occhio del Ciclone. Vai ad affrontarli oggi, perché domani potrebbe essere troppo tardi!', },
    {'Vinci uno scontro sul campo di battaglia dell\'Occhio del Ciclone e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [14183] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    nil,
    nil,
  },
  [14184] = {
    'È giunta la mia ora',
    {'<Furien, indebolito, ti chiama a sé e si sforza di parlare.>|n|nL\'attacco dell\'Alleanza mi ha colto di sorpresa...|n|nDevi... avvertire mia sorella.|n|nPrendi la mia cavalcatura, $R... ti condurrà da lei...|n|n<Furien muore.>', },
    {'Furien a Tethris Aran ti ha chiesto di cavalcare il suo dragofalco fino all\'Accampamento di Furien per avvertire sua sorella Cerelia della sua morte.', },
  },
  [14188] = {
    'Vendica Furien!',
    {'Non può essere vero!|n|nIl mio adorato fratello... ucciso dalla feccia dell\'Alleanza!|n|nDevono soffrire quello che sto soffrendo io, $R! Trova un modo per fargliela pagare! Non avrò pace fino ad allora...|n|nFurien era andato in cerca di manufatti antichi nelle regioni orientali prima di morire. Parla con Sorrem. Forse lui saprà dirti dove si era diretto esattamente mio fratello.', },
    {'Cerelia ti ha chiesto di parlare con Sorrem all\'Accampamento di Furien.', },
  },
  [14189] = {
    nil,
    {'È vero che Furien ha dedicato gli ultimi giorni della sua vita a uno speciale progetto di ricerca, però non ha voluto dirmi di cosa si trattasse.|n|nPer fortuna ho trovato il suo diario, ma è scritto in codice e non sono riuscito a decifrarlo.|n|nForse la risposta si trova nella regione a est dove Furien si era diretto prima di morire.|n|nPrendi il diario, $C, e parla con Narimar quando sei $Gpronto:pronta; a indagare su questo mistero.', },
    nil,
  },
  [14190] = {
    'Il prisma perfetto',
    {'Deve pur esserci un modo per invertire il processo di pietrificazione causato dai basilischi. Quei dannati sabotatori elfici che si aggirano per la cava devono sapere qualcosa che noi ignoriamo: sembrano immuni allo sguardo di quelle bestie!|n|n$N, voglio che tu scopra il loro segreto. Elimina qualcuno dei sabotatori di Talrendis che si nasconde nel retro della cava e recupera un campione dell\'amuleto, o quel che è, che li rende immuni. Quando hai finito, contattami via radio dall\'edificio della forgia principale.', },
    {'Recupera un Pendaglio di Cristallo da un Sabotatore di Talrendis nella Cava di Piemontano.', },
  },
  [14191] = {
    'Sulle tracce di Furien',
    {'<Riesci a decifrare parti del testo, ma ci vorrà uno studio più approfondito prima di comprendere il lavoro di Furien.>|n|n<Volgendo il tuo sguardo a nord-est, ti sembra di riconoscere alcune delle rovine descritte nel diario.>|n|n<Da quello che hai scoperto, queste rovine sembrano essere importanti per la ricerca di Furien.>', },
    {'Le Antiche Tavolette al Santuario di Elune ti hanno <guidato/guidata> verso tre delle principali rovine di Sargeron.', },
  },
  [14192] = {
    nil,
    {'Se quel prisma che hai trovato riesce a rifrangere lo sguardo del basilisco, possiamo usare le proprietà del suo cristallo per invertire il procedimento. Tutto ciò che ci serve è una fonte d\'energia.|n|nNel Mobiletto delle Armi alla tua destra, troverai il nostro prototipo di Perforatore Laser. Adoravo quell\'arma, ma i casi quotidiani di mutilazione cominciavano a diventare una seccatura. Prendi il Perforatore Laser e scambia la lente con il cristallo...', },
    {'Porta il Pendaglio di Cristallo al Mobiletto delle Armi che si trova nel Quartier Generale della Cava di Piemontano.', },
  },
  [14193] = {
    'Con un paio di meloni si aggiusta tutto',
    {'<Dalle iscrizioni riportate su queste rovine ti è chiara una cosa: la vecchia fontana nel Santuario di Elune ha qualcosa di speciale.>|n|n<Sembra che sciacquarsi la faccia con l\'acqua della fontana permetta di ottenere un potere speciale. Per capire se è vero, bisognerà innanzitutto riempirla di qualcosa con cui lavarsi.>|n|n<Mentre rifletti sul da farsi, vedi un melone alla base di un albero vicino...>', },
    {'Raccogli 8 Meloni.', },
  },
  [14194] = {
    nil,
    {'<Una voce dalla radio lì vicino ti chiama.>|n|nEhi, $N, hai preso l\'arma? Bene! Non puntartela direttamente agli occhi.|n|nPuntala piuttosto verso i minatori pietrificati e la luce rifratta dovrebbe invertire il processo di pietrificazione. O fonderli. A ogni modo, riporta i miei lavoratori in uno stato tale da essermi redditizi! E se la... ricarnificazione li farà impazzire, uccidili, così almeno recuperiamo i premi dell\'assicurazione. Horzak CHIUDE!', },
    {'Usa il Ricarnificatore per depietrificare 8 Minatori di Piemontano nella Cava di Piemontano.', },
  },
  [14195] = {
    'Tutto è più chiaro',
    {'<È successo qualcosa... forse è un effetto collaterale del Rituale di Purificazione di Elune.>|n|n<La tua comprensione della lingua antica in cui è scritto il diario, sia pur non ancora perfetta, è notevolmente migliorata.>|n|n<Le rovine sulle montagne settentrionali di Sargeron sembrano aver catalizzato l\'attenzione di Furien. Doveva aver intuito che lì c\'era qualcosa che l\'avrebbe aiutato a cacciare l\'Alleanza da questa regione.>|n|n<Chiudi il diario, <determinato/determinata> a trovare queste rovine e a scoprirne i segreti.>', },
    {'Il Diario di Furien ti ha suggerito di trovare le Rovine del Palazzo di Elune a Sargeron settentrionale.', },
  },
  [14196] = {
    'Piromane',
    {'<Ora sei in grado di comprendere la scrittura nella quale è stato redatto il diario.>|n|n<Oltre al monolito, spiega che le gemme del monumento avevano il potere di evocare una Tempesta di Fuoco.>|n|n<La tempesta poteva ingrandirsi fino a diventare una potente arma attraverso la venerazione di Elune o caricandola con le energie spirituali dei caduti.>|n|n<Volgendo lo sguardo in basso, verso i fantasmi dei Discepoli di Elune appena comparsi, ti accorgi che non hai il tempo, né la volontà, di adorare la dea del tuo nemico...>', },
    {'Crea un Vortice Furioso sconfiggendo 7 Discepoli di Elune in presenza della tua Tempesta di Fuoco.|n|nSe dovessi perdere la Gemma del Vortice Furioso, potrai ottenerne una nuova dall\'Antico Monolito del Vortice.', },
  },
  [14197] = {
    'Quota da raggiungere',
    {'Il Ferro della Montagna è una lega fragile, ma con le mazzette giuste supera tranquillamente gli standard di sicurezza dei Goblin. Bottaforte sta incontrando dei problemi di produzione, ma questo non cambia le mie scadenze: ho una quota da raggiungere!|n|nScendi alla Cava di Piemontano e raccogli tutti i lingotti di Ferro della Montagna che trovi. Dovrebbero già essercene pile intere, pronte da spedire.', },
    {'Raccogli 20 Lingotti di Ferro di Piemontano dalla Cava di Piemontano ad Azshara.', },
  },
  [14198] = {
    'A cavallo della tempesta',
    {'<Provi un certo orgoglio per aver scoperto il segreto degli antichi adoratori di Elune che era andato perduto da tempo.>|n|n<Ora hai il potere per infliggere notevoli danni al tuo nemico.>|n|n<Dato che tutto ciò è stato reso possibile dall\'instancabile lavoro di Furien, ti sembra giusto che l\'arma venga scatenata sui responsabili della sua morte.>|n|n<La feccia dell\'Alleanza al Presidio di Nijel la pagherà cara per aver attaccato l\'Orda!>', },
    {'Usa la Gemma del Vortice Furioso alle Rovine del Presidio di Nijel. Mentre comandi la tua Tempesta di Fuoco, uccidi 40 Difensori del Presidio di Nijel e brucia 15 Mercanti del Presidio di Nijel.|n|nSe dovessi perdere la Gemma del Vortice Furioso, potrai ottenerne una nuova dall\'Antico Monolito del Vortice.', },
  },
  [14201] = {
    'Mille storie nella sabbia',
    {'Le rovine intorno al Lago Mennar, a est di qui, hanno molto da raccontare. Le razze inferiori, come quei goffi dei Nani, vanno alla ricerca della verità con badili e picconi. <Malynea arriccia il naso.> Noi useremo metodi più eleganti.|n|nLe mie doti di chiaroveggenza sono un po\' arrugginite, ma con il giusto monile dovrei essere in grado di scrutare al di là del velo del tempo. Le ossa dei miei antenati sono ormai irrecuperabili, ma ciò non vale per i tesori che avevano seppellito con sé. Portamene qualcuno.', },
    {'Raccogli 5 Manufatti Sepolti dalle rovine al Lago Mennar di Azshara.', },
  },
  [14202] = {
    'Periziare il lago',
    {'Tutte queste ingombranti antiche rovine dovranno essere spianate, se vogliamo sfruttare pienamente il potenziale di Azshara. Guarda questa mappa: tu, a est, vedi il Lago Mennar, giusto? Be\', ecco cosa ci vedo io: un futuro deposito di combustibile per razzi!|n|nTuttavia, prima di disboscare, spianare, riempire di terra e lastricare quel lago, abbiamo bisogno di informazioni dettagliate sull\'area. Tutti i miei ispettori hanno paura delle presenze che infestano la zona. Scorta lì uno dei miei allievi ispettori e recupera i dati dagli strumenti già installati.', },
    {'Scorta un Ispettore Goblin a ciascuno dei tre Strumenti da Rilevazione che circondano il Lago Mennar e difendilo mentre recupera i dati da essi. Puoi sempre chiamare un altro Ispettore tramite il tuo Cercapersone per Ispettori.', },
  },
  [14203] = {
    'Ricetta Fradicia',
    {'<Questi sembrano essere i resti di una mistura per un potente vino. Forse la proprietaria di Alla Salute a Dalaran potrebbe esservi interessata...>', },
    {'Porta la Ricetta Fradicia a Christi Stockton nella città di Dalaran.', },
  },
  [14204] = {
    'Dalle ombre',
    {'Si è trasformato in uno di loro, vero? Come facciamo ad affrontare un nemico in grado di farci questo?|n|nL\'arsenale di mio padre è sicuramente un buon punto di partenza.|n|nI Worgen si nascondono nei vicoli più avanti... prendi uno dei miei mastini per stanarli.|n|nDobbiamo liberare la strada se vogliamo spostare questi cannoni.', },
    {'Uccidi 6 Guardinghi Zannacremisi.', },
  },
  [14209] = {
    'Il bulldozer ingolfato',
    {'Quelle antiche rovine hanno resistito agli agenti atmosferici per diecimila anni, per cui, per spianarle, ho deciso di ricorrere al mio bulldozer più grosso e potente. Una macchina meravigliosa, l\'ho chiamata "Margene".|n|nUltimamente, però, ha fatto le bizze. $N, devi sapere che nel momento in cui è entrata in quei boschi infestati, il motore si è bloccato emettendo un rumore agghiacciante. Gli ingegneri mi dicono che qualcosa ha intasato le valvole. Dovresti recarti laggiù, ispezionare il vano motore di Margene e riportarmi un campione di ciò che l\'ha fatta ingolfare.', },
    {'Ispeziona Margene e recupera un Campione di Ectoschifezza che ne ha ingolfato il motore.', },
  },
  [14212] = {
    nil,
    {'Non sei $Gcostretto:costretta; ad aiutarci, $N. Hai già fatto molto per noi.|n|nSe però decidi di restare, sarei uno sciocco a non approfittarne.|n|nI miei uomini hanno rafforzato la loro posizione all\'interno della cattedrale e sono pronti a tutto.|n|nIo sto andando là per portarmi dietro quanti più Worgen possibili. Se vuoi unirti a me, non fare complimenti.', },
    {'Cavalca con Ser Darius Crowley e raduna 30 Inseguitori Zannacremisi.', },
  },
  [14213] = {
    'Vittime sacrificali',
    {'<Secondo il Diario di Furien, questo antico braciere fu messo qui per eseguire riti sacrificali.>|n|n<Da quello che hai capito leggendo l\'annotazione, chi mette la carne dei nemici di Elune sui carboni ardenti del braciere riceve una benedizione.>|n|n<Guardandoti intorno, ti accorgi che i Satiri che ora controllano questa regione sarebbero delle vittime perfette.>', },
    {'Raccogli 10 Pezzi di Carne di Satiro dai Satiri di Sargeron e sistemali sul Braciere di Elune.', },
  },
  [14214] = {
    'Messaggio a Mantogrigio',
    {'È ora, $N. Da qui in avanti ce ne occuperemo noi.|n|nDi\' a Re Mantogrigio che l\'arsenale di mio padre sarà a sua disposizione. Abbiamo una potenza di fuoco sufficiente a cacciare i Worgen da qui fino ai Mari del Nord.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14215] = {
    'Ricordi dei morti',
    {'Le rune su questo anello che hai trovato sono ancora leggibili. L\'anello era un dono per l\'ammissione all\'Accademia di una certa "Kalytha". Con il giusto incantesimo, questo monile personale può darci l\'accesso alla sua anima.|n|nRiporta l\'anello al Lago Mennar. Adesso dovresti poter vedere lo spirito di Kalytha sulla riva del lago. Toccala e l\'anello ti permetterà di vedere il mondo come lo vede lei, costretta a rivivere le ultime ore della sua vita per l\'eternità. Scruta la sua mente, $N! Parla con gli altri e scopri i segreti del Lago Mennar...', },
    {'Torna con l\'Anello di Kalytha sulla riva del Lago Mennar. Tocca lo spirito di Kalytha per far rivivere i suoi ricordi. Parla con gli altri spiriti finché non avrai scoperto il segreto del Lago Mennar.', },
  },
  [14216] = {
    'Il mistero della Pietra di Sarcen',
    {'<Prima che morisse, a Kalytha era stato dato il compito di seppellire qualcosa sotto il fondale del lago: un potente manufatto alla cui creazione gli Arcimaghi di Mennar avevano dedicato i loro ultimi istanti di vita. Senza dubbio Malynea Razziacielo vorrà vedere il manufatto, ammesso che esista ancora. Decidi di esplorare il fondale del Lago Mennar alla ricerca della Pietra di Sarcen.>', },
    {'Recupera la Pietra di Sarcen dal fondale del Lago Mennar.', },
  },
  [14217] = {
    'Dono dei Satiri',
    {'<Trovi piuttosto buffo che questa Reliquia Antica ti impartisca una benedizione pensata per i tuoi nemici.>|n|n<Decidi comunque di sfruttare al massimo questo dono involontario.>', },
    {'Raccogli 10 Pezzi di Carne di Satiro dai Satiri di Sargeron e sistemali sul Braciere di Elune.', },
  },
  [14218] = {
    'Di sangue e cenere',
    {'È giunta l\'ora, $N. Se vogliamo sfoltire le loro file questo è il momento giusto per farlo.|n|nAbbiamo preso posizione.|n|nAbbiamo la potenza di fuoco.|n|nOra non ci resta che vedere se abbiamo anche il coraggio... ma personalmente non ho dubbi.', },
    {'Uccidi 80 Inseguitori Zannacremisi usando i Cannoni dei Ribelli.', },
  },
  [14219] = {
    'A fil di lama!',
    {'<Questa statua è identica a una di quelle disegnate nel Diario di Furien.>|n|n<Anche se le parole scritte nell\'annotazione ti sfuggono, il disegno sembra spiegarsi da solo. Al termine della battaglia, le armi dei nemici venivano gettate nel catino in cambio di una sorta di dono divino.>|n|n<Mentre rifletti su questo rituale, il tuo sguardo viene attirato dal bagliore dell\'acciaio proveniente da una rastrelliera per le armi...>', },
    {'Raccogli 20 Sciabole dei Satiri dalle rastrelliere per le armi e dai Satiri nella regione, e poi sistemale sulla statua della Vergine di Elune.', },
  },
  [14221] = {
    'Ripiegare, mai arrendersi',
    {'Avevamo munizioni a sufficienza per proseguire la guerra civile per un altro mese, ma le abbiamo quasi terminate a causa di tutti quei Worgen.|n|nSarà meglio non farci trovare qui all\'aperto quando resteremo a secco. Ripieghiamo all\'interno della cattedrale e facciamo rapporto al capo. Sono certo che il vecchio Crowley saprà cosa fare dopo.', },
    {'Parla con Ser Darius Crowley dentro la Cattedrale di Albalucente.', },
  },
  [14222] = {
    'Ultima Difesa',
    {'La strettoia che questo luogo ci offre è un buon punto strategico, $N. Prega pure se vuoi.|n|nArmiamoci di coraggio e uccidiamo questi bastardi.', },
    {'Uccidi 8 Inseguitori Furiosi.', },
  },
  [14223] = {
    'Pace dei sensi',
    {'Noi siamo un avamposto di frontiera e abbiamo l\'ordine di tenere gli occhi aperti in caso di incursioni nemiche. Quando l\'Orda lancerà la propria offensiva per Desolanda, il nostro compito qui sarà assicurare che non vi siano sorprese.|n|nRecentemente, uno dei nostri esploratori è stato catturato e ucciso dalle Lame Ardenti nella loro roccaforte a est. Da allora, siamo stati minacciati e attaccati da un membro delle Lame Ardenti di nome Kohor.|n|nI loro giorni qui sono contati, ma ti pagherò bene se ucciderai quell\'essere al più presto!', },
    {'Sorrem dell\'Accampamento di Furien ti ha chiesto di uccidere Kohor.', },
  },
  [14225] = {
    'Lo riconoscerai quando lo vedrai',
    {'In punto di morte, Kohor ha parlato dell\'evocazione di un demone che potrebbe minacciare l\'intera regione.|n|nPotrebbe aver mentito, ma meglio non correre rischi.|n|nNon possiamo attendere che abbia inizio l\'invasione di Desolanda da parte dell\'Orda. Devi setacciare la Fortezza Ascia del Tuono in cerca di indizi e porre fine a questa potenziale minaccia.', },
    {'Sorrem dell\'Accampamento di Furien ti ha chiesto di trovare l\'Antico Rituale di Evocazione nella Fortezza Ascia del Tuono.', },
  },
  [14226] = {
    'Guai sotto i piedi',
    {'Ma guardati. Sempre a svolgere incarichi per gli altri. Molto responsabile da parte tua. Stai salendo su, su, su, vero? Su, su!|n|nMa attenzione ai demoni! Demoni di diversi tipi, tutti poco piacevoli. Demoni che troverebbero prelibate le tue interiora! Demoni di Legash diretti a sud-est! Ma non preoccuparti. No no, non c\'è nessun motivo per avere paura, perché io ti fornirò un assistente!|n|nMira, trasforma in insetto, schiaccia. Mira, trasforma in insetto, schiaccia! Molto efficiente. Anche se non troppo pulito... ma, ripeto, non preoccuparti. No no, non preoccuparti, anche perché dopo non saremo costretti a pulire!', },
    {'Usa il tuo Assistente Arcano Personale per trasformare 12 Demoni di Legash in insetti e poi schiacciali.', },
  },
  [14227] = {
    'Riunire le loro teste',
    {'Dunque è vero...|n|nLa cartapecora che hai trovato nella Fortezza Ascia del Tuono spiega nel dettaglio un potente rituale di evocazione, ancor più efficace di qualsiasi altro in possesso delle Lame Ardenti.|n|nBisogna fermarlo a ogni costo!|n|nForse, se questo demone venisse evocato prima del tempo, potremmo evitare una catastrofe.', },
    {'Raccogli 100 Teschi Sbiancati dalla Fortezza Ascia del Tuono, sistemali nel Cerchio di Evocazione delle Lame Ardenti e uccidi Nazargen.', },
  },
  [14230] = {
    'Un recupero da manuale',
    {'I demoni locali sembrano divertirsi parecchio a rubare i nostri manuali di magia arcana. Dubito fortemente che la maggior parte di loro sappia leggere, probabilmente lo fanno solo per dispetto.|n|nOra, della maggior parte dei libri che ci hanno rubato non m\'importa granché, ma ce n\'è uno, il Manuale dell\'Apostata, senza il quale non posso continuare ad aiutare gli apprendisti di Xylem come te a sopravvivere alle sue "prove". Cerca quei demoni nell\'Accampamento di Legash a sud-est e recupera il Manuale dell\'Apostata.|n|nÈ tutto. Ora va\'.', },
    {'Recupera il Manuale dell\'Apostata dall\'Accampamento di Legash.', },
  },
  [14232] = {
    'Orecchie ardenti',
    {'<Sorrem non ha mai nascosto il proprio disprezzo per le Lame Ardenti della Fortezza Ascia del Tuono.>|n|n<Apprezzerebbe sicuramente una prova della loro morte.>', },
    {'Ottieni 25 Orecchie delle Lame Ardenti e portale a Sorrem nell\'Accampamento di Furien.', },
  },
  [14233] = {
    'Gli Orchi sanno scrivere?',
    {'Rovistando tra gli oggetti dell\'Orco morto trovi un diario da campo. Anche se è usurato dall\'acqua, con un po\' di fatica è ancora leggibile.|n|nMentre sfogli le pagine, scopri una storia interessante. Per fortuna che hai scelto di studiare l\'orchesco.|n|nCome il panfilo del Principe del Commercio, anche gli Orchi sono stati colpiti dalle navi da guerra dell\'Alleanza. Ti ricordi di una nave da guerra orchesca che hai superato appena prima che l\'Alleanza aprisse il fuoco. Forse stavano sparando agli Orchi e non alla tua nave?|n|nStupidi Orchi! Ti hanno fatto affondare!', },
    {'Porta il Diario da Campo a Sassy Serrabullona presso il Lido dei Relitti sulle Isole Perdute.', },
  },
  [14234] = {
    'I nemici dei miei nemici',
    {'Mi dispiace chiedertelo, ma immagino sia perché a te pagano bene. Puoi consegnare quel diario da campo dell\'Orco morto al capo del loro accampamento?|n|nStando al contenuto del diario, dovrebbero trovarsi sulla vetta dell\'isola, in cima al pendio oltre la Caverna di Kaja\'mite a sud-est.|n|nBuona fortuna, $N. Ti ho sempre voluto bene.', },
    {'Consegna il Diario da Campo ad Aggra presso il Campo Base dell\'Orda sulle Isole Perdute.', },
  },
  [14235] = {
    'Valmorsa',
    {'Il nostro cacciatore, Kilag Zannabieca, è andato con alcuni esploratori nella valle lungo il sentiero a ovest. Stanno cercando un... \'prezioso carico\'... al quale stavamo facendo la guardia quando la maledetta Alleanza ha affondato la nostra nave.|n|nLa strada è bloccata da piante letali e non sono riusciti a passare.|n|n$N, dimostra il tuo valore di Goblin e di $C. Vai a Valmorsa e trova Kilag.', },
    {'Trova Kilag Zannabieca a Valmorsa sulle Isole Perdute.', },
  },
  [14236] = {
    'Tagliaerba',
    {'<Kilag ha a malapena il tempo di riconoscerti tra i proiettili, ma il suo sguardo indugia un momento soddisfatto sulla tua Goblincintura Tutto-In-1.>|n|nOra è il momento delle soluzioni creative. Tira fuori qualcosa da quella cintura e mettiti al lavoro!|n|n<Dopo un attimo di riflessione ti viene in mente un\'idea abbastanza folle da poter funzionare!>', },
    {'Usa il Tagliaerba nella tua Goblincintura Tutto-In-1 per falciare 100 piante a Valmorsa.', },
  },
  [14237] = {
    'Avanzare immediatamente',
    {'Kilag ormai dovrebbe essere in posizione. È ora che tu vada a Belvedere Selvaggio. Il resto dei nostri si sta preparando e partirà presto.|n|nSegui il sentiero a nord-ovest attraverso Valmorsa. Grazie a te, non morde più così tanto, vero?|n|nKilag e i suoi esploratori si terranno nascosti a ridosso del sentiero, ma gli Assassini dell\'IR:7 sicuramente li troveranno presto... quindi... sbrigati!', },
    {'Trova Kilag Zannabieca e i suoi esploratori a Belvedere Selvaggio sulle Isole Perdute.', },
  },
  [14238] = {
    'Infrarosso = Inframorto',
    {'Abbassa la voce. La radura a nord e a ovest di qui è piena di assassini dell\'Alleanza.|n|nPurtroppo non siamo riusciti a individuarli. Codardi! Si nascondono e non combattono a viso aperto.|n|nVoi Goblin siete famosi per i vostri incredibili visori. Per caso ne hai un paio in grado di vedere gli assassini?|n|nDevi unirti a uno dei miei esploratori e uccidere tutti gli Assassini dell\'IR:7 che riesci a individuare.', },
    {'Uccidi 10 Assassini dell\'IR:7.|n|nSe succede qualcosa all\'Esploratore Orco al tuo fianco, torna da Kilag e vedi se ne ha un altro da assegnarti.', },
  },
  [14239] = {
    'Non andare verso la luce!',
    nil,
    nil,
  },
  [14240] = {
    'Alle scogliere',
    {'Ho inviato l\'Esploratore Brax lungo la strada per le scogliere che dominano la spiaggia a ovest.|n|nTi metterò su Bastia. Percorri il sentiero e informa Brax che prenderemo una strada diversa.|n|nCi vedremo al momento dell\'attacco alla Testa di Ponte dell\'Alleanza!', },
    {'Parla con l\'Esploratore Brax sul sentiero lungo le scogliere a nord del Boschetto Selvatico sulle Isole Perdute.', },
  },
  [14241] = {
    'Al Girocottero!',
    {'L\'Alleanza ha rubato qualcosa di vitale importanza per l\'Orda. La tengono sulle loro navi.|n|nDall\'altro versante della spiaggia c\'è un Girocottero. I nostri Giurabattaglia ti copriranno.|n|nVai a recuperare le chiavi della macchina volante da uno dei loro agenti.|n|nVai alla loro ammiraglia, la Scia di Vendetta, e recupera il nostro carico prezioso!', },
    {'Recupera le Chiavi del Girocottero.', },
  },
  [14242] = {
    'Prezioso carico',
    {'Dicono che il loro "prezioso carico", qualunque cosa sia, si trova sulla nave dell\'Alleanza, la Scia di Vendetta.|n|nC\'è solo una cosa da fare... volare laggiù ed entrarne in possesso!', },
    {'Trova il prezioso carico sottocoperta sulla nave dell\'Alleanza, la Scia di Vendetta, al largo della costa delle Isole Perdute.', },
  },
  [14243] = {
    'La vendetta del Capoguerra',
    {'Fratelli della Terra e del Fuoco, ascoltatemi! Sorelle dell\'Acqua e dell\'Aria, udite la mia chiamata!|n|nAzeroth è in pericolo, la sua stessa esistenza è a repentaglio! Donatemi il vostro potere come ai tempi dei miei antenati. Consentitemi di canalizzare la vostra volontà attraverso questo figlio di Kezan.|n|nDistruggiamo coloro che vogliono impedirci di salvare il mondo!', },
    {'Usa i poteri del Ciclone degli Elementi per uccidere 50 Marinai dell\'Alleanza.|n|nUna volta fatto, verrai trasportato al Belvedere Selvaggio.', },
  },
  [14244] = {
    'Sempre più in alto!',
    nil,
    nil,
  },
  [14245] = {
    'Città-In-Scatola innescata',
    {'Il Principe del Commercio aveva un\'intera Città-In-Scatola nella stiva della nave! Sono riuscito a recuperarla mentre tu eri fuori a salvarci la pelle.|n|nVuoi avere tu l\'onore? Devi solo arrampicarti in cima a quell\'enorme pila di esplosivi, attivare il detonatore e... boom! Avremo la nostra città.', },
    {'Arrampicati in cima alla montagna di esplosivi e usa il Detonatore della Città-In-Scatola.', },
  },
  [14246] = {
    'Adozione anticipata',
    {'Con l\'aumento della vegetazione nella regione, le creature del deserto sono state costrette a vivere in spazi sempre più angusti.|n|nUna delle conseguenze più gravi è il pericolo di estinzione degli avvoltoi locali. I predatori si cibano degli uccelli e delle loro uova quando attaccano i nidi.|n|nHo preso delle uova di avvoltoio a Tanaris e le ho ricoperte con un feromone irresistibile. Mettine una in ogni nido che trovi e proteggila finché non arriva un avvoltoio a prenderla.|n|nDarai una grande mano a preservare l\'equilibrio di questa terra.', },
    {'Metti 3 Uova d\'Avvoltoio nei Nidi d\'Avvoltoio e proteggile finché non vengono raccolte.', },
  },
  [14247] = {
    'Terre testarde',
    {'Per autorità del Circolo Cenariano, ho l\'incarico di trasformare queste terre aspre in praterie verdeggianti.|n|nLe terre a sud hanno risposto bene, ma c\'è qualcosa qui che sta opponendo resistenza.|n|nForse i tuoi occhi avranno più successo dei miei.|n|nTi prego, $R, perlustra queste terre e scopri la fonte che impedisce alla vegetazione di prosperare.', },
    {'Thunk del Bivacco di Thunk ti ha chiesto di trovare l\'Affioramento Innaturale.', },
  },
  [14248] = {
    'Aiuto cercasi',
    {'Grandi notizie! Il Caposquadra Stoppaumida ha scoperto sull\'isola una caverna piena di kaja\'mite! Quante probabilità c\'erano?|n|nNaturalmente c\'è la parte negativa. Ha portato con sé alcuni dei superstiti per aiutarlo a estrarre il minerale, ma nessuno si è salvato.|n|nSo che è una follia, ma il Caposquadra ha detto che nella caverna ci sono delle scimmie... con i picconi! Stanno estraendo la kaja\'mite! Come accidenti è possibile?|n|nPuoi andare a sud-est, alla caverna? Il Caposquadra è proprio fuori dall\'entrata.', },
    {'Parla con il Caposquadra Stoppaumida fuori dalla Caverna di Kaja\'mite sulle Isole Perdute.', },
  },
  [14249] = {
    'Un mago implume',
    {'Sarò fantastico! Come Arcimago. Fantastico! Lui non si degna nemmeno di parlarmi, solo perché non ho una stupida tonaca e un cappello. Pffft.|n|nIl più fantastico Arcimago che questa terra abbia mai visto non può avere una tonaca e un cappello qualunque. Devo dimostrargli che sono speciale e ho un\'idea su come fare.|n|nVai a uccidere degli ippogrifi. Portami una MAREA di piume.|n|nCapito? Una marea! Ora va\'! Per quando sarai di ritorno avrò certamente finito di realizzare la tonaca.', },
    {'Recupera 80 Piume Intatte di Testatuono dagli ippogrifi nei pressi delle Rovine di Nordressa.', },
  },
  [14250] = {
    'Risorsa rinnovabile',
    {'Abbiamo bisogno di altro Basalto Animato. In zona ne esiste un\'unica fonte affidabile, un Gigante di Montagna di nome Balboa. Se vogliamo mantenere costanti nel tempo le nostre scorte non possiamo uccidere il Gigante, per cui finora ci siamo sempre limitati a ferirlo lievemente per staccarne dei piccoli pezzi.|n|nTroverai il suo sentiero a nord-est e a est di qui. Trovalo, piazza una carica esplosiva poco più avanti lungo il suo percorso e nasconditi in attesa dell\'esplosione. Una volta liberata l\'area, dovresti essere in grado di recuperare del basalto da portarmi.', },
    {'Usa la Carica Arcana per recuperare 5 Basalti Animati da Balboa vicino alle Rovine di Nordressa.', },
  },
  [14251] = {
    'Ricominciare da zero',
    nil,
    {'Ottieni 15 Pungiglioni di Scorpione.', },
  },
  [14252] = {
    'Monete tintinnanti per code vecchie',
    {'$C, mi servono parecchie code! Ma non code qualsiasi. Quelle che cerco sono vecchie, antiche. Più sono vecchie e meglio è.|n|nLe scaglie della coda dei basilischi hanno la proprietà unica di diventare più dure con il passare degli anni, senza rompersi. Queste scaglie rinforzate sono l\'ideale per certe armature.|n|nSono anni che vendo scaglie di lucertola, ma chissà, forse questo potrebbe rafforzare il mio carattere! Ammesso che ciò sia possibile...', },
    {'Ottieni 15 Code di Basilisco Invecchiate.', },
  },
  [14253] = {
    'Procurami delle piume!',
    {'Di\' un po\', $C, non è che mi faresti un favore già che sei $Gimpegnato:impegnata; a esplorare le distese desertiche?|n|nTieni gli occhi aperti per gli Avvoltoi del Terrore. Le loro piume oleose sono ottime per costruire le frecce e possono valere una fortuna se vendute al cliente giusto.|n|nPer tua fortuna, io conosco tutti i clienti giusti!', },
    {'Ottieni 25 Piume di Avvoltoio del Terrore.', },
  },
  [14254] = {
    'Metallo pesante',
    {'Hai la netta sensazione che questa roccia sia legata alla mancata ricrescita nella regione.|n|nGuardando verso ovest, noti una scia di detriti fumanti che sembra aver a che fare con questo mistero.|n|nPensi che ripulendo i detriti aiuterai Thunk.|n|nE chissà, magari potranno servire in futuro...', },
    {'Recupera 7 Pezzi di Elemento 116 e portali a Bizby presso la Carovana di Bizby.', },
  },
  [14255] = {
    nil,
    {'Abbiamo già abbastanza nemici in questa regione senza dover suscitare anche le ire del Circolo Cenariano.|n|nQuando ci siamo sistemati qui, ci era stato detto di tenere d\'occhio una delle loro ricercatrici.|n|nKorrah è stata vista l\'ultima volta presso la torre a ovest. Va\' a controllare per favore. È da un po\' che non abbiamo sue notizie.', },
    {'Cerelia dell\'Accampamento di Furien ti ha chiesto di parlare con Korrah a Ethel Rethor.', },
  },
  [14256] = {
    'La minaccia emergente',
    {'Io sono tutto ciò che resta della mia compagnia, che era stata inviata per controllare i numerosi cambiamenti su questa costa di Desolanda.|n|nHo denunciato il notevole incremento del numero dei Naga nella zona, ma non è servito a niente.|n|nI miei colleghi sono concentrati su altre faccende, dunque devo chiedere a te, $Guno straniero:una straniera;, di assistermi nella mia ricerca.|n|nPrima, però, lascia che ti mostri la minaccia che abbiamo di fronte.', },
    {'Korrah ti ha chiesto di parlare con lei quando sei <pronto/pronta> per illustrarti la minaccia dei Naga.', },
  },
  [14257] = {
    'Massacro dei Lamasalmastra',
    {'Spesso i Naga si sono rivelati un pericolo per l\'equilibrio della natura. Io non ho alcun problema a versare il loro sangue.|n|nCredo però che, anche con tutta la buona volontà, riusciresti a malapena a scalfire la loro presenza qui. Ogni volta che ne viene ucciso uno, pare che ne compaiano altri due per prenderne il posto.|n|nHo un piano, $C. Il tuo obiettivo non consiste solo nell\'uccidere i nemici, ma anche nel raccogliere i componenti necessari per la prossima fase della nostra indagine...', },
    {'Raccogli 10 Ossa dei Lamasalmastra dai Naga Lamasalmastra, 30 Scaglie dei Lamasalmastra dalle Occultiste Lamasalmastra e 4 Pinne dei Lamasalmastra dai Guerrieri Lamasalmastra.', },
  },
  [14258] = {
    'Munizioni in arrivo',
    {'Non appena abbiamo concluso la costruzione di questo terminale della razzovia, i Naga hanno iniziato a occupare la penisola. Ma non c\'è problema a questo mondo che non possa essere risolto da una potenza di fuoco sufficientemente elevata! Così mi diceva sempre il mio babbo. Prima dell\'incidente.|n|nTuttavia, ho quasi esaurito le munizioni. Non potresti farmi il piacere di andare a prendere le granate da mortaio che ho lasciato nel Laboratorio Segreto a ovest di qui? Non lasciarmi a mani vuote e ti lascerò coordinare l\'artiglieria di supporto!', },
    {'Raccogli 5 Granate da Mortaio dei Goblin dal complesso del Laboratorio Segreto di Azshara.', },
  },
  [14259] = {
    nil,
    nil,
    {'Raccogli 5 Granate da Mortaio dei Goblin dal complesso del Laboratorio Segreto di Azshara.', },
  },
  [14260] = {
    'In fondo al mar',
    {'Ho creato un talismano che ti permetterà di assumere l\'aspetto di un Naga per infiltrarti tra loro.|n|nCon questo travestimento potrai parlare e comprendere la loro lingua senza essere $Griconosciuto:riconosciuta;.|n|nSta\' alla larga però dagli squali e dalle altre creature marine, perché sveleranno a tutti la tua vera identità.|n|nOra vai. Parla con la Sacerdotessa di Azshara e fai ciò che è necessario per scoprire cosa stanno tramando quelle creature.', },
    {'Usa il Talismano dei Lamasalmastra.', },
  },
  [14261] = {
    'Freddo come il ghiaccio',
    {'Ho la soluzione perfetta per il nostro problema con i drachi: la mia Lente Criomatica 16.|n|nL\'avevo realizzata per congelare i miei lavoratori durante il trasporto o tra un turno e l\'altro, eliminando così la necessità di fornire loro vitto e intrattenimento, ma ci sono state delle... complicazioni. Però dovrebbe essere perfetta per abbattere quei drachi nel cielo!', },
    {'Usa la Lente Criomatica 16 per congelare e uccidere 8 Drachi Zibellini.', },
  },
  [14262] = {
    'Pesci da sbudellare',
    {'Difendermi da creature in grado di sparire sott\'acqua e di riemergere a loro piacimento mette a dura prova la mia pazienza. Ma finché non saranno spazzate via da Azshara, non mi arrenderò.|n|nI Naga Sferzarabbia sono arrrivati strisciando su per le scogliere e ci hanno messo sotto assedio, soprattutto da est. Annientali, $N. Falli a pezzettini, tutti, così conosceranno in pieno la furia della mia Orda.', },
    {'Uccidi 6 Scagliatuoni Sferzarabbia e 6 Invocatori del Mare Sferzarabbia.', },
  },
  [14263] = {
    'Non c\'è Timo da sprecare',
    {'Timo dell\'Ira Vivente. Me ne serve dell\'altro! Fai presto, d\'accordo?', },
    {'Raccogli 8 Mazzetti di Timo dell\'Ira Vivente nei pressi delle Rovine di Nordressa.', },
  },
  [14264] = {
    'Più che bagnato, fradicio',
    {'I servitori di Neptulon sono giunti qui e stanno facendo di tutto per ostacolarci. Devono aver scoperto le nostre intenzioni.|n|nCiò non fa che confermare i miei sospetti: quello che stiamo cercando si trova in queste rovine!|n|nQuesti Elementali dell\'Acqua non possono nulla contro le nostre forze! Prendi questo tridente e usalo per uccidere gli sciocchi servitori del Cacciatore delle Maree.|n|nDopo che avremo trovato ciò che cerchiamo, ci occuperemo anche di Neptulon!', },
    {'Uccidi 5 Servi di Neptulon (devi assumere l\'aspetto di un Naga quando li elimini).|n|nSe dovessi perdere il Tridente dei Lamasalmastra, parla con Valishj.|n|nSe dovessi smarrire il Talismano dei Lamasalmastra, parla con Korrah a Ethel Rethor.', },
  },
  [14265] = {
    'Il tuo istruttore',
    {'Molti di noi sono riusciti ad arrivare qui vivi... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era un tipo di nome Cleese che ti cercava. Ha detto che eri $Guno:una; dei suoi studenti e voleva assicurarsi che tu stessi bene.', },
    {'Parla con il Sergente Cleese nel Distretto Militare.', },
  },
  [14266] = {
    'Carica',
    nil,
    nil,
  },
  [14267] = {
    'Perlustrare il Santuario del Mare',
    {'Gli invasori Naga hanno eretto una serie di santuari lungo le scogliere. Non ne conosco lo scopo, $N, ma credo che servano a rinforzare il nostro nemico. Mi serve qualcuno che vada laggiù a estirpare questa minaccia.|n|nUno di questi santuari qui vicino è poco difeso: attraversa il primo ponte a est di qui e poi dirigiti a nord verso la baia. Lo troverai su un piccolo affioramento. Perlustra il santuario e torna con delle informazioni utili.', },
    {'Perlustra il Santuario dei Naga per conto di Torg Doppiocolpo.', },
  },
  [14268] = {
    'Impatto profondo',
    {'La Regina Azshara sta cercando di entrare nel piano dell\'acqua, anche se non ne conosco il motivo.|n|nCrede che gli antichi custodissero le chiavi per trovare la sua posizione.|n|nSono stata incaricata personalmente di perlustrare le rovine di questa regione, e nessuno si riposerà finché non avremo scoperto i segreti che ci interessano!|n|nA nord ci sono delle rovine sommerse. Usa questo bastone per cercare tra le macerie.|n|nTorna da me solo quando avrai trovato ciò che stiamo cercando!', },
    {'La Sacerdotessa Valishj ti ha chiesto di trovare le Antiche Incisioni di Neptulon.', },
  },
  [14269] = {
    'Qualcuno ti sta cercando',
    {'La maggior parte di noi sono riusciti ad arrivare qui vivi... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era una donna di nome Loren che ti cercava. Sembrava dispiaciuta quando le ho detto che stavi bene.|n|nPare ti debba dei soldi.', },
    {'Parla con Loren la Ricettatrice nel Distretto Militare.', },
  },
  [14270] = {
    'Il Frammento a Incastro',
    {'<Tutt\'intorno a questa strana pietra, l\'aria crepita. La pietra in sé è liscia e gelida al tatto. Toccandola, l\'avverti pulsare ritmicamente, cosa che ti fa venire in mente l\'abbattersi regolare delle onde sulla riva.>|n|n<Dalla superficie sembra mancare un frammento a forma di cuneo. Probabilmente quel frammento rappresenta la chiave per scoprire i segreti della pietra. Perlustra l\'area intorno al tempio alla ricerca del Frammento a Incastro.>', },
    {'Trova il Frammento a Incastro qui intorno.', },
  },
  [14271] = {
    'Ritorno da Doppiocolpo',
    {'<Una barriera magica ti pulsa intorno, gelandoti le ossa. All\'interno di questo muro incantato ti senti al sicuro.>|n|n<Torg Doppiocolpo vorrà sapere cos\'hai scoperto qui!>', },
    {'Torna da Torg Doppiocolpo al Terminale Sud della Razzovia di Azshara riferendogli la tua scoperta.', },
  },
  [14272] = {
    'Sventramento',
    nil,
    nil,
  },
  [14273] = {
    'Loschi compagni',
    {'La maggior parte di noi è riuscita ad arrivare qui viva... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era uno strano tipo di nome Vitus che ti cercava. Mi mette i brividi solo a guardarlo.|n|nNon ha fatto altro che parlare di una certa "conoscenza proibita" che dice di aver scoperto.', },
    {'Parla con Vitus Passoscuro nel Distretto Militare.', },
  },
  [14274] = {
    'Immolazione',
    nil,
    nil,
  },
  [14275] = {
    'Qualcuno ti sta seguendo',
    {'La maggior parte di noi sono riusciti ad arrivare qui vivi... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era un uomo di nome Blake che ti cercava. Ha parlato di un piano per fuggire nei boschi.', },
    {'Parla con il Predatore Blake nel Distretto Militare.', },
  },
  [14276] = {
    'Tiro Stabilizzato',
    nil,
    nil,
  },
  [14277] = {
    'Domande arcane',
    {'La maggior parte di noi sono riusciti ad arrivare qui vivi... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era una Maga di nome Myriam che ti cercava. Ha detto qualcosa riguardo al fatto che sei "$Gpronto:pronta;".', },
    {'Parla con Myriam Destincanto nel Distretto Militare.', },
  },
  [14278] = {
    'In cerca della Sorella',
    {'La maggior parte di noi sono riusciti ad arrivare qui vivi... ma ci sono Worgen anche in questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud dopo che avremo radunato tutti.|n|nA proposito... c\'era una Sacerdotessa, Sorella Almyra, che ti cercava. Ha detto che stavi correndo un grave pericolo e che avevi bisogno della protezione della Luce.|n|nSembrava molto preoccupata. Dovresti andare a parlarle.', },
    {'Parla con Sorella Almyra nel Distretto Militare.', },
  },
  [14279] = {
    'Cura Rapida',
    nil,
    nil,
  },
  [14280] = {
    'Pare che i venti conoscano il tuo nome',
    {'La maggior parte di noi sono riusciti ad arrivare qui vivi... ma i Worgen hanno occupato anche questa zona della città.|n|nAbbiamo intenzione di proseguire verso sud una volta che avremo radunato tutti.|n|nA proposito... c\'era quella megera mietitrice, Celestine, che ti cercava. Ha detto che i venti sussurrano il tuo nome.|n|nFaresti meglio a sbrigarti, $N. Avremo bisogno del tuo aiuto per affrontare i Worgen dopo che avrai parlato con la natura.', },
    {'Parla con Celestine del Raccolto nel Distretto Militare.', },
  },
  [14281] = {
    'Missili Arcani',
    nil,
    nil,
  },
  [14282] = {
    'Mistero risolto',
    {'<I tuoi sforzi e i grossi rischi che hai corso si sono rivelati utili.>|n|n<Hai scoperto l\'oggetto del desiderio dei Naga e il motivo per cui hanno invaso la costa di Desolanda.>|n|n<Per quanto riguarda le incisioni che hai trovato, il tuo compito è chiaro...>', },
    {'Consegna le Antiche Incisioni di Neptulon alla Ricercatrice Cenariana Korrah.', },
  },
  [14283] = {
    'Fuoco Lunare',
    nil,
    nil,
  },
  [14284] = {
    'La vendetta dello spettro',
    {'Io sono Idronis, uno dei servitori di Neptulon il Cacciatore delle Maree, Signore di tutte le acque.|n|nAzshara e i suoi malvagi Naga si sono uniti contro il mio padrone per muovergli guerra. Questa è solo la prima di tante battaglie.|n|nHo combattuto a lungo, $R, e ora sono stanco.|n|nSembra che la mia condotta abbia attirato l\'attenzione della loro Sacerdotessa.|n|nDa solo non ho la forza per sconfiggerla, ma forse insieme possiamo farcela.', },
    {'Idronis ti ha chiesto di salire su di lui per sconfiggere insieme la Sacerdotessa Valishj.', },
  },
  [14285] = {
    'Più siamo, meglio è',
    {'Questo è quanto posso insegnarti per ora, con tutti questi Worgen che cercano di farci a pezzi.|n|nDovremmo dirigerci a sud con gli altri superstiti. Re Mantogrigio si trova lì.|n|nUniti, le nostre possibilità di sopravvivenza aumentano... avere degli alleati robusti al tuo fianco è molto importante.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14286] = {
    'Più siamo, meglio è',
    {'Ti ho insegnato tutto ciò che può tornarti utile, per ora.|n|nÈ il momento di raggiungere gli altri superstiti. Re Mantogrigio e la sua Guardia Reale si trovano a sud.|n|nDobbiamo andare lì e unirci a loro per essere più al sicuro.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14287] = {
    'Più siamo, meglio è',
    {'Ti ho insegnato tutto ciò che può tornarti utile, per ora.|n|nÈ il momento di raggiungere gli altri superstiti. Re Mantogrigio e la sua Guardia Reale si trovano a sud.|n|nDobbiamo andare lì e unirci a loro per essere più al sicuro.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14288] = {
    'Più siamo, meglio è',
    {'Questo è quanto posso insegnarti per ora, con tutti questi Worgen che cercano di farci a pezzi.|n|nDovremmo dirigerci a sud con gli altri superstiti. Re Mantogrigio si trova lì.|n|nUniti, le nostre possibilità di sopravvivenza aumentano... avere degli alleati robusti al tuo fianco è molto importante.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14289] = {
    'Più siamo, meglio è',
    {'Ti ho insegnato tutto ciò che può tornarti utile, per ora.|n|nÈ il momento di raggiungere gli altri superstiti. Re Mantogrigio e la sua Guardia Reale si trovano a sud.|n|nAvranno bisogno dell\'aiuto della Luce in questi tempi difficili.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14290] = {
    'Più siamo, meglio è',
    {'Ti ho insegnato tutto ciò che può tornarti utile, per ora.|n|nÈ il momento di raggiungere gli altri superstiti. Re Mantogrigio e la sua Guardia Reale si trovano a sud.|n|nDobbiamo andare lì e unirci a loro per essere più al sicuro.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14291] = {
    'Più siamo, meglio è',
    {'Ti ho insegnato tutto ciò che può tornarti utile, per ora.|n|nÈ il momento di raggiungere gli altri superstiti. Re Mantogrigio e la sua Guardia Reale si trovano a sud.|n|nDobbiamo andare lì e unirci a loro per essere più al sicuro.', },
    {'Parla con Re Genn Mantogrigio nel Distretto Militare.', },
  },
  [14292] = {
    'Il nemico del nostro nemico',
    {'Ci hai reso un bel servizio, $C.|n|nAnche se il numero dei Naga resta imponente, sei $Griuscito:riuscita; a sottrarre loro un importante manufatto.|n|nScriverò ai miei colleghi per metterli al corrente delle tue scoperte. Nel frattempo, lo Spettro dell\'Acqua sull\'Isola di Ranazjar ha respinto da solo un assalto dei Naga.|n|nVorrei che lo trovassi e scoprissi se ha bisogno d\'aiuto.', },
    {'La Ricercatrice Cenariana Korrah ti ha chiesto di parlare con Sire Idronis.', },
  },
  [14293] = {
    'Salvare Krennan Aranas',
    {'Nonostante siano trascorsi tutti questi anni dall\'inizio della guerra, Crowley aveva ancora abbastanza potenza di fuoco nascosta in quei sotterranei da radere al suolo metà distretto.|n|nE purtroppo è quello che dovremo fare.|n|nTuttavia, non possiamo ancora aprire il fuoco... c\'è un civile intrappolato dall\'altra parte della prigione.|n|nNon si tratta di un civile come tanti, ma di Krennan Aranas, uno degli alchimisti più brillanti che il mondo abbia mai conosciuto.|n|nUna delle sue pozioni ha salvato mia figlia Tess dalla morte subito dopo la nascita.|n|nKrennan non deve morire. Prendi il mio cavallo e va\' a salvarlo.', },
    {'Salva Krennan Aranas.', },
  },
  [14294] = {
    'Raggrupparsi',
    {'Qui abbiamo finito. Avverti Re Mantogrigio che abbiamo guadagnato un po\' di tempo.|n|nHo la sensazione che presto i Worgen torneranno alla carica in forze.|n|nDobbiamo ripiegare verso la Corte dei Mantogrigio a ovest. È l\'ultimo posto che possiamo proteggere senza finire in trappola come topi.', },
    {'Parla con Re Genn Mantogrigio nella Corte dei Mantogrigio a Gilneas.', },
  },
  [14295] = {
    'Sorelle del mare',
    {'Due Streghe Naga stanno architettando un assalto contro questo avamposto. Finora hanno respinto gli attacchi diretti di alcuni dei nostri migliori guerrieri, ma tu puoi riuscire là dove gli altri hanno fallito.|n|nCerca e uccidi Dama Silisthra e Dama Vesthra. Dovresti trovarle sul versante orientale delle scogliere, nei pressi delle rovine dell\'antico colosso degli Elfi della Notte. Prima, naturalmente, dovrai distruggere le Pietre del Potere. Non deludermi, $C!', },
    {'Uccidi Dama Silisthra e Dama Vesthra dopo aver neutralizzato le loro Pietre del Potere.', },
  },
  [14296] = {
    'Occhio a dove metti i piedi',
    {'Si tratta di una cosa semplice e al tempo stesso complicata. Fin lassù si stendono dei Condotti Energetici. Proprio come questo qui, oserei dire! Anzi, lo dico proprio.|n|nE ora a te. Devi usare i miei Saltatori Automatici per salire su per il Pinnacolo e lungo la strada devi toccare tutti i Condotti che vedi. Quando mi avrai raggiunto in cima, sarai $Gtutto carico:tutta carica; d\'energia... e del resto non vedo buoni motivi per non esserlo!|n|nRicordati di spostarti continuamente, o potresti essere $Gsbalzato:sbalzata; molto lontano!', },
    {'Ricevi 6 Scariche Energizzanti dai Condotti Energetici man mano che risali lungo il Pinnacolo Arcano.', },
  },
  [14297] = {
    nil,
    {'Avevo capito che ci avrebbero creato dei problemi sin da quando abbiamo iniziato a costruire la torre. Hanno disdegnato i nostri tentativi di corruzione. Ci hanno rubato i lavoratori.|n|nE con tutte le attività edilizie in corso ad Azshara, la manodopera è cara. Quegli uomini mi servono!', },
    {'Usa le Chiavi in Ferro Battuto dei Cultisti e dei Dragoidi per liberare 4 Lavoratori Goblin a Cresta Fuligginosa.', },
  },
  [14299] = {
    'Il Rifugio di Xylem',
    {'Davvero stupendo! È proprio un piacere osservarti e studiarti.|n|nVai adesso, ritirati nella mia torre. Joanna risponderà alle tue domande. Entra nel portale che aprirò per te.', },
    {'Entra nel portale che conduce alla Torre dell\'Arcimago Xylem e cerca Joanna al suo interno.', },
  },
  [14300] = {
    'La Prova del Fuoco',
    nil,
    {'Completa la Prova del Fuoco restando sulle rune del fuoco senza farti colpire dalle fiamme per 10 sbuffi consecutivi.', },
  },
  [14301] = {
    'Torna e fai rapporto',
    {'È finita! Insieme abbiamo sconfitto un pericoloso avversario.|n|nNeptulon verrà informato di ciò che hai fatto qui, $C. Permettimi di ringraziarti a nome suo...|n|nOra è meglio che tu vada. Questo posto non resterà al sicuro ancora per molto. Presto i Naga cercheranno di vendicare la morte della loro Sacerdotessa.', },
    {'Torna dalla Ricercatrice Cenariana Korrah a Ethel Rethor.', },
  },
  [14302] = {
    'Stima ufficiale',
    {'Hai fatto già molto contro i Naga, $N. Temo però che non sia ancora sufficiente...|n|nQuesta è la mia stima ufficiale sulla presenza dei Naga.|n|nSono convinta che i miei colleghi nelle terre fertili prenderanno i provvedimenti necessari.|n|nConsegna questo rapporto a Karnum nel bosco al centro delle Terre Fertili Cenariane a sud-est. Egli saprà cosa fare.|n|nGrazie, $N, e addio.', },
    nil,
  },
  [14303] = {
    'Torna da Aggra',
    {'Torna al Campo Base dell\'Orda e riferisci ad Aggra che siamo ancora vivi, $N.|n|nDille che sto andando a Belvedere Selvaggio e che ci vedremo tutti sul versante nord-ovest dell\'isola. Ti aspetto là.|n|nTroveremo quei cani dell\'Alleanza e li uccideremo dal primo all\'ultimo!', },
    {'Informa Aggra al Campo Base dell\'Orda sulle Isole Perdute di quanto accaduto.', },
  },
  [14304] = {
    'Teoria del sangue',
    {'La terra non è la sola cosa a essere cambiata a Desolanda. La fauna locale ha reagito al nuovo ambiente in maniera strana e a volte intrigante.|n|nMi interessano in particolare i Sauri del Tuono Ringiovaniti che si trovano a ovest.|n|nHo bisogno di un campione del loro sangue.|n|nPotresti cominciare ad aiutarmi usando questo vaso di sanguisughe su alcuni dei loro esemplari.|n|nQuando si saranno riempite del sangue di quelle bestie, riportale da me.', },
    {'Recupera 10 Sanguisughe Sanguinose.', },
  },
  [14305] = {
    'Il momento della raccolta',
    {'Nessuno meglio del Circolo Cenariano sa che quest\'oasi verdeggiante potrebbe seccarsi con la stessa velocità con la quale è fiorita.|n|nDobbiamo fare attenzione a non interferire con i processi che avvengono qui, ma anzi supportarli e preservarli.|n|nUna nuova specie di piante, che abbonda nella regione circostante, è apparsa dopo il grande cambiamento.|n|nRaccogli dei campioni di queste piante per me, in modo che possa studiarle.', },
    {'Raccogli 10 Foglie di Aloe.', },
  },
  [14306] = {
    'Estirpare le erbacce',
    {'Con un cambiamento così improvviso dell\'ecosistema, c\'era da aspettarselo che qualche esemplare della flora e della fauna non reagisse bene come speravamo.|n|nUn esempio sono le Piante Sferzanti Estirpate, che vagano per i campi a est e a sud causando danni alla regione. Devono essere eliminate.|n|nDistruggile se ti capita di incontrarle.', },
    {'Elimina 7 Piante Sferzanti Estirpate.', },
  },
  [14307] = {
    'Venti ostinati',
    {'Non c\'è dubbio che i venti del cambiamento stiano soffiando, $R.|n|nCi sono molte questioni della massima urgenza che richiedono la nostra attenzione e il nostro intervento. La principale riguarda l\'espansione della nostra oasi.|n|nLa sua crescita è andata al di là di ogni più rosea aspettativa, ma ora ha trovato un ostacolo.|n|nA ovest, dove l\'erba incontra la sabbia, i turbini impediscono all\'oasi di espandersi verso il deserto.|n|nVa\' ed elimina questi ostacoli alla vita!', },
    {'Distruggi 5 Turbini delle Tempeste.', },
  },
  [14308] = {
    'Quando la scienza attacca',
    {'Hai visto le esplosioni, entrando? Il Laboratorio Segreto è avvolto dalle fiamme! Di nuovo! Se non le spegniamo, raggiungeremo la temperatura critica e si scatenerà una terribile fusione a cascata.|n|nTieni, ti affido un campione di gel liquido pressurizzato iperraffreddato sperimentale, il più instabile agente ritardante noto alla scienza! (Tieni il contenitore lontano dalle fiamme vive). Spegni gli incendi e salva i miei assistenti, poi contattami tramite il Raucofono nella postazione di controllo centrale.', },
    {'Usa l\'Eliminafuoco X-21 per estinguere 8 incendi e salvare 6 Assistenti di Ricerca dall\'inferno del Laboratorio Segreto.|n|nSe perdi il tuo Eliminafuoco, torna dall\'Assistente Greely al Terminale Sud della Razzovia.', },
  },
  [14309] = {
    'Calmare i kodo',
    {'Avrai notato che le rapide modifiche avvenute in questa regione hanno avuto sia effetti positivi sia negativi sulle creature locali.|n|nA sud e a est di qui i Kodo Rabbiosi rappresentano una minaccia costante per chiunque si trovi nei paraggi.|n|nÈ giunto il momento di mettere alla prova la mia teoria. Ho usato il sangue dei Sauri del Tuono Ringiovaniti per preparare questa mistura. Spero servirà a calmare i Kodo quando la berranno.|n|nMettila vicino a un Kodo Rabbioso e tieniti a distanza di sicurezza!', },
    {'Usa la Mistura dei Kodo vicino a 5 Kodo Rabbiosi.', },
  },
  [14310] = {
    'Errore di segmentazione: distacco del nucleo',
    {'Una volta svuotato il reattore centrale, devi riportarmi il nucleo. Si tratta di cristallo di azsharite purissimo al 100 percento, un oggetto tanto potente quanto pericoloso. E adorabile. Oh, preziosa azsharite, modellatrice del futuro!|n|nL\'enorme leva alla tua sinistra farà staccare il nucleo e me lo invierà tramite un sistema automatizzato. Il nucleo sarà più che surriscaldato, quindi lungo la strada dovrai raffreddarlo frequentemente con l\'Eliminafuoco... Non lasciare che raggiunga la temperatura critica!', },
    {'Attiva la Console di Controllo del Reattore e scorta il Nucleo di Azsharite fino al Terminale Sud della Razzovia. Usa l\'Eliminafuoco X-21 sul nucleo non appena vedi che sta per surriscaldarsi.', },
  },
  [14311] = {
    'Prendere parte',
    {'Viviamo in un\'epoca magnifica!|n|nLe vecchie terre selvagge di Desolanda stanno sbocciando. Immagina, $C, se tutte le terre selvagge di Azeroth si risvegliassero in questo modo! Chissà, un giorno forse...|n|nÈ vero che ci sono questioni più urgenti qui, ma perché non prendersi un attimo per apprezzare lo splendido miracolo al quale stiamo assistendo?|n|nE perché non parteciparvi direttamente? Questi sono Semi Cenariani. Usali nei punti più fertili delle terre.|n|nÈ la medicina perfetta per risollevare un\'anima stanca!', },
    {'Usa i Semi Cenariani vicino a 5 Tumuli Fertili nelle Terre Fertili Cenariane.', },
  },
  [14312] = {
    'Prima le presentazioni',
    {'Ho sentito parlare delle tue imprese a Desolanda, $N. Siamo in debito con te.|n|nTemo però di doverti coinvolgere in un\'altra faccenda più urgente.|n|nLo scenario qui non è cambiato molto di recente. Vecchi conflitti hanno lasciato spazio a nuovi, più cruenti. Il nostro ospite ti spiegherà meglio come stanno le cose...|n|nIl Khan Leh\'prah è uno degli ultimi membri della tribù Kolkar che un tempo possedeva tutta la Desolanda orientale. Lo abbiamo trovato quasi morto ai nostri confini. Ascolta quello che ha da dirti.', },
    {'Garren Ventocupo nella Selva di Karnum ti ha chiesto di parlare con il Khan Leh\'prah.', },
  },
  [14313] = {
    nil,
    {'E così la pozione di Krennan non ti ha $Gucciso:uccisa;? Questo significa che la tua parte umana ha il controllo sul resto.|n|nVorrà dire che non ti sparerò... almeno per ora.|n|nVa\' a parlare con Krennan Aranas per dargli la buona notizia. È a capo del luogo dove teniamo... quelli come te.|n|nRicordati che ti tengo d\'occhio, $N, dunque non fare scherzi se non vuoi ritrovarti una pallottola in mezzo agli occhi.', },
    {'Parla con Krennan Aranas a Borgotetro.', },
  },
  [14314] = {
    nil,
    {'Tutto ebbe inizio con un sogno ricorrente che mi metteva in guardia da un imminente pericolo. Ho visto le legioni demoniache uccidere la nostra gente e conquistare le nostre terre.|n|nIl sogno è diventato realtà. Le Lame Ardenti e i loro signori demoni hanno cacciato i Magram dalle loro terre a sud. Successivamente, i Magram hanno attaccato il mio popolo e si sono presi le nostre case.|n|nÈ stata una battaglia feroce. Solo un manipolo di Kolkar sono riusciti a sopravvivere. Vorrei che visitassi quella che un tempo era la mia terra a est e li liberassi dalla loro prigione.', },
    {'Uccidi il Custode Magram e libera i Prigionieri Kolkar al Villaggio dei Magram.', },
  },
  [14315] = {
    nil,
    nil,
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14316] = {
    'Proprietà cenariana',
    {'Da quando i demoni hanno invaso le loro terre, i Magram hanno rotto ogni legame con gli stranieri.|n|nSono ostili e diffidenti nei confronti di tutti e hanno cominciato a rubare invece di provvedere da soli al loro sostentamento.|n|nMolte delle nostre provviste sono sparite di recente e sospettiamo che i colpevoli siano i Magram.|n|nTi prego, $N, vai nelle loro terre a est e recupera le nostre cose.', },
    {'Recupera 7 Casse di Provviste Cenariane dalle Terre dei Magram.', },
  },
  [14318] = {
    'Negoziati difficili',
    {'C\'è un solo modo per ottenere la fiducia e la lealtà dei Magram.|n|nRicorrere all\'uso della forza.|n|nHanno subito parecchie perdite nella guerra contro il mio clan. Ora vivono in una terra che non conoscono, dove faticano anche solo a trovare di che sfamarsi.|n|nQuesto è il momento giusto per colpire.|n|nParla con me quando sei $Gpronto:pronta;, quindi va\' e pianta la mia lancia nella Roccia dei Padri. Se riusciamo a uccidere abbastanza Centauri, il loro Khan si piegherà al nostro volere.', },
    {'Il Khan Leh\'prah ti ha chiesto di piantare la Lancia del Khan dei Kolkar nella Roccia dei Padri e di proteggerla dai Magram fino all\'arrivo del Khan Kammah.|n|nParla con il Khan Leh\'prah quando sei <pronto/pronta> a dirigerti sul luogo della battaglia.', },
  },
  [14319] = {
    nil,
    nil,
    {'Parla con Krennan Aranas a Borgotetro.', },
  },
  [14320] = {
    'In cerca di ingredienti',
    {'Ah, sì... per quanto ne sappiamo non è possibile guarire completamente dagli effetti della Maledizione.|n|nTuttavia, con le dovute cure, potrai conservare la tua mente e non trasformarti in una bestia selvaggia.|n|nSiamo fortunati che la cura abbia funzionato su di te... di solito è in grado di guarire solo le infezioni recenti.|n|nDobbiamo continuare se vogliamo invertire gli effetti della Maledizione.|n|nMi serve dell\'Essenza di Mandragora per preparare un\'altra scorta del mio siero. C\'è una cassa sotto a un capanno a sud-ovest della città...', },
    {'Recupera la Cassa di Essenza di Mandragora.', },
  },
  [14321] = {
    'Invasione',
    {'<Dalla schiena del miliziano spunta un lungo coltello con un teschio sull\'elsa. Mentre ti guardi intorno in cerca di indizi, scorgi un paio di navi da guerra dall\'aspetto sinistro a riva.>|n|n<Stanno invadendo Gilneas. Devi avvisare il Sindaco di Borgotetro, Gwen Bracciofermo.>', },
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14322] = {
    'Cattiva, scienza! Cattiva!',
    {'Stavo cercando di addomesticare gli ippogrifi indigeni con una serie di scosse elettriche debilitanti quando, per qualche motivo, sono impazziti! E ora le mie cavie stanno facendo a pezzi questo posto senza alcun motivo! $C, stermina i miei esperimenti falliti prima che essi sterminino me.', },
    {'Uccidi 8 Ippogrifi Elettrificati.', },
  },
  [14323] = {
    nil,
    {'Mi serve un\'altra cosa. Dell\'acqua calda.|n|nNon è facile da trovare da queste parti. Senza sorgenti è dura, ma un modo esiste. Prendi questa spugna... è ultra-assorbente! Imbevila di Onde Vili presso il banco di sabbia a est.|n|nQuando hai finito, strizzala vicino alla torre per evocare un enorme elementale. Lui ha l\'acqua calda.', },
    {'Recupera 20 Gocce d\'Acqua Bollenti dalle Onde Vili a est delle Rovine di Arkkoran.', },
  },
  [14324] = {
    'Pieni d\'acqua calda',
    {'Ergll ti ha spiegato che dovresti poter usare la Spugna Marina Rigonfia di Azshara per evocare un "enorme" elementale vicino alla Torre di Eldara a nord-est.', },
    {'Ottieni una Sfera d\'Acqua Bollente da un Signore dell\'Acqua Cocente alla Torre di Eldara.', },
  },
  [14325] = {
    'A pancia piena si ragiona meglio',
    {'<Il Khan Kammah ti ascolta mentre gli racconti della minaccia demoniaca e delle visioni del Khan Leh\'prah.>|n|nNessuno può darci lezioni sui demoni, $R. Sono stati loro a cacciare il nostro clan dalle nostre terre ancestrali.|n|nSono stati loro a scacciarci nelle regioni selvagge dei Kolkar, dove fatichiamo anche solo a sopravvivere.|n|nIl mio popolo ha pagato a caro prezzo la guerra contro i Kolkar. I pochi superstiti rimasti sono stanchi e affamati.|n|nProcuraci del cibo e dopo parleremo dei demoni.', },
    {'Procurati 5 Costate di Basilisco.', },
  },
  [14326] = {
    'Ci vediamo su',
    {'Non avrei mai pensato di essere nuovamente prigioniero dell\'Alleanza. Non so dirti quanto ti sono grato... $N, giusto?|n|nCi vediamo in cima, e da lì ci occuperemo di loro.', },
    {'Raggiungi il ponte superiore della Scia di Vendetta al largo della costa delle Isole Perdute e parla con Thrall.', },
  },
  [14327] = {
    'Ogni promessa è debito',
    {'Pare che non abbiamo altra scelta.|n|nPer quanto non mi piaccia l\'idea di collaborare con i Kolkar, c\'è della saggezza nelle parole del loro Khan.|n|nPuoi dargli la mia parola: combatteremo al loro fianco con le nostre lance.', },
    {'Il Khan Kammah ti ha chiesto di parlare con il Khan Leh\'prah.', },
  },
  [14328] = {
    'I tre principi',
    {'I Gelkis vivono nella parte sudoccidentale di Desolanda. Sono testardi quanto i Magram, ma nettamente più forti, dal momento che non hanno combattuto la guerra, né sono stati costretti a cambiare casa.|n|nSottomettere i Gelkis richiederà una notevole dimostrazione di forza.|n|nIl Khan Shodo e i suoi tre figli governano il clan. Shodo è vecchio e sofferente per antiche ferite di guerra. Non abbandona mai i recessi della sua caverna. La forza del suo regno risiede nei suoi figli.|n|nUccidili e convinci il Khan ad abbracciare la nostra causa.', },
    {'Uccidi Rhoho, Sherik e Jorreth.', },
  },
  [14329] = {
    'Non così in fretta!',
    nil,
    nil,
  },
  [14330] = {
    'Sotto chiave',
    {'Hai scoperto dove si trova la figlia del Khan Shodo, Kherrah. È tenuta prigioniera oltre i cancelli di Maraudon!|n|nSalvarla è certamente un\'impresa difficile, ma se vuoi che il Clan Gelkis collabori, dovrai liberare la figlia del Khan.', },
    nil,
  },
  [14332] = {
    'Tempo di cambiare',
    {'<Kherrah ti ascolta mentre la metti al corrente degli ultimi eventi.>|n|nCondivido le parole del Khan dei Kolkar. Il tempo degli antichi rancori è finito. È un peccato che ci sia voluto un attacco dei demoni per unire le tribù.|n|nTornerò da mio padre e lo convincerò a unirsi alla tua causa. Accetterà, ti do la mia parola.|n|nTorna dal Khan Leh\'prah e digli che i Gelkis si faranno trovare pronti quando ci sarà bisogno di loro.', },
    {'Kherrah ti ha chiesto di parlare con il Khan Leh\'prah.', },
  },
  [14333] = {
    'Già che sei qui',
    {'I Maraudon hanno attaccato i campi dei Gelkis per molti anni, rubando tutto ciò che trovavano.|n|nUno dei loro divertimenti preferiti consisteva nel prendere le reliquie di potere, sacre per i Gelkis, e portarle qui per profanarle.|n|nIl Clan Gelkis ti sarebbe grato se trovassi e distruggessi questi manufatti corrotti.', },
    {'Perlustra la Valle delle Lance e distruggi una Reliquia Corrotta.', },
  },
  [14334] = {
    nil,
    {'Ué, cumpà!|n|nTi va di aiutarci?|n|nTeniamo nu problema con na balena che è troppo grande per li arpioni nuostr\'.|n|nWilly diventa sempre più chiatta e si mangia tutto il pesce che ci serve per campare!|n|nVai là fuori, trovala e pigliala a mazzate, così impara a strafogarsi!', },
    {'Mai\'lahii ti ha chiesto di uccidere Willy.', },
  },
  [14335] = {
    'A caccia di granchi',
    {'Avrai sicuramente notato come i recenti cambiamenti della terra hanno prodotto diversi effetti collaterali. Alcuni di questi sono positivi, mentre altri pongono seri problemi.|n|nA sud di Predombra, gli Aragoidi stanno emergendo dal mare e stanno invadendo la strada che conduce al villaggio.|n|nTi prego, $C, intervieni e riduci il loro numero.', },
    {'Uccidi 5 Crostacei Schioccosecco e 5 Pinzatori Schioccosecco.', },
  },
  [14336] = {
    'Uccidere o morire',
    {'Le scogliere ci hanno sempre protetto dagli attacchi provenienti dal mare. Il terremoto deve aver aperto un passaggio per le navi dei Reietti.|n|n$GSvelto:Svelta;, $N, rallenta gli assalitori mentre io preparo il resto della milizia.|n|nSe non sbaglio, il Principe e alcuni dei miei uomini stanno combattendo contro i Reietti in questo stesso istante. Parla con Liam e vedi come puoi renderti utile.|n|nAh... e fai in modo che non si faccia ammazzare. Temo possa essere un po\' più avventato del solito nel suo stato attuale.', },
    {'Parla con il Principe Liam Mantogrigio fuori Borgotetro.', },
  },
  [14337] = {
    'Villaggio Shadowprey',
    {'Lieto di rivederti, $C.|n|nHo saputo che Predombra ha bisogno d\'aiuto. Al momento siamo impegnati qui, dunque devi occupartene tu.|n|nil villaggio si trova sulla costa a sud-ovest. Quando arrivi, cerca Mai\'lahii.', },
    {'Karnum Plasma Paludi ti ha chiesto di parlare con Mai\'lahii.', },
  },
  [14338] = {
    'Presidio delle Ombre',
    {'Salute, $C.|n|nSono felice di vedere che tu sia ancora $Gvivo:viva;. Ho bisogno del tuo aiuto.|n|nA sud-ovest di questo bosco si trova il Presidio delle Ombre. Lì troverai un Reietto di nome Maurin Rompiossa.|n|nPotrebbe avere la soluzione per uno dei problemi che ci affliggono.|n|nParla con lui e fai ciò che ti chiede per aiutarlo.', },
    {'Karnum Plasma Paludi ti ha chiesto di parlare con Maurin Rompiossa.', },
  },
  [14339] = {
    'Cavie da laboratorio',
    {'Ho un incarico speciale da affidarti, che porterà dei benefici sia al Circolo Cenariano, sia a me.|n|nDevi sapere, $C, che sono sotto pressione per creare una mistura per così dire... speciale. Credo che il mio lavoro sia terminato, ma per averne la certezza devo fare una prova.|n|nLe cavie di questo test saranno i Naga che minacciano questa regione da ovest. La loro eliminazione gioverebbe molto al Circolo.|n|nPer prima cosa, però, mi serve qualcosa in cui mettere la mistura. I corni scavati dei kodo morti dovrebbero andar bene.', },
    {'Maurin Rompiossa ti ha chiesto di ottenere 3 Corni di Kodo Scavati dai Kodo Morti.', },
  },
  [14340] = {
    'In ghingheri',
    {'Evidentemente, tutti abbiamo qualcosa da imparare.|n|nEcco, prendi il mio Cappello Magico. Sono certo che non avrà nulla da obiettare nel prenderti come apprendista, specie se sembri del mestiere... al massimo dovrai saltare attraverso dei cerchi. Piccoli cerchi fiammeggianti sospesi su delle punte, con lame rotanti all\'altra estremità.|n|nDovresti trovare l\'Immagine di Xylem in cima a quella collina a nord-est.', },
    {'Indossa il tuo nuovo Cappello Magico e poi parla con l\'Immagine dell\'Arcimago Xylem a nord-est dello Scambio Settentrionale della Razzovia.', },
  },
  [14341] = {
    'Imbracature di Smeed',
    {'Chiedo scusa, giovane $R.|n|nAvrei bisogno d\'aiuto. Ho appena completato un ordine per delle imbracature che vanno consegnate immediatamente.|n|nSono troppo vecchio per mettermi in viaggio, soprattutto considerando i pericoli che ci sono ultimamente.|n|nTi andrebbe di consegnarle al posto mio?|n|nIl destinatario è Smeed, un Goblin che vive a sud-est di qui.', },
    nil,
  },
  [14342] = {
    'Invasione infernale',
    {'I demoni si stanno muovendo, $R!|n|nSe non facciamo qualcosa, verremo sopraffatti nel giro di poche settimane. Sono appena tornato dalla Congrega di Mannoroc, dove ci sono gli Infernali che cadono dal cielo!|n|nDobbiamo prendere tempo. Vai laggiù e continua il mio lavoro!', },
    {'Felgur Doppiotaglio ti ha chiesto di distruggere 10 Infernali Inferiori.', },
  },
  [14343] = {
    'Mistura di Maurin',
    {'<Maurin sigilla attentamente la sua mistura nei Corni di Kodo Scavati.>|n|nEcco qua, $C.|n|nConsegnala a Karnum. Deciderà lui come usarla sui Naga.|n|nIo assisterò per verificare l\'efficacia della mia formula!', },
    nil,
  },
  [14344] = {
    'Rovina di Jugkar',
    {'<La riconosci come l\'essenza di un demone evocato.>|n|n<Energie pericolose e oscure danzano sulla sua superficie.>|n|n<Fissandola, hai una visione: un\'immagine di te che controlli degli schiavi demoniaci. Una scarica d\'adrenalina scorre nelle tue vene mentre ti immagini a esercitare un simile potere.>|n|n<Guardandoti intorno ti chiedi come sia possibile usare questo tesoro contro questo nemico demoniaco...>', },
    {'Usa il Nucleo Energetico Infernale per assumere il controllo di Azrethoc all\'Altare di Jugkar e sfrutta i suoi poteri per uccidere Jugkar Vergatruce.', },
  },
  [14345] = {
    'Scaricati',
    {'Fantastico!|n|nAzy è sempre alla ricerca di manufatti magici su cui mettere le mani. Ha detto che stava cercando di farsi amico quell\'Arcimago... Xylem!|n|nXylem ha MOLTI apprendisti. Ne accetta di tutti i tipi, li spreme e poi li scarica senza tanti complimenti. Cambi su cambi.|n|nL\'ultimo è avvenuto la notte scorsa. Quel povero sventurato era diretto verso quella specie di grossa torre dei Goblin, molto a ovest. Forse lui può aiutarti a incontrare Xylem e forse Xylem sa dove si trova Azy!|n|nNon fare mosse avventate!', },
    {'Parla con Sorata Fiammatorta allo Scambio Settentrionale della Razzovia.', },
  },
  [14346] = {
    'Ripulire il nostro crepaccio',
    {'Come ben saprai, $N, i Naga rappresentano una seria minaccia per la regione. È arrivato il momento di ricacciarli in mare!|n|nQuando sei $Gpronto:pronta;, Piumatruce ti condurrà al crepaccio dove stanno preparando un attacco su vasta scala. Una volta lì, usa la Mistura di Maurin per dar loro una lezione che non dimenticheranno tanto facilmente.', },
    {'Karnum Plasma Paludi ti ha chiesto di usare la Mistura di Maurin per uccidere 10 Invasori Lamasalmastra, 10 Sirene Lamasalmastra e 3 Giganti del Mare.', },
  },
  [14347] = {
    'Mantenere la posizione',
    {'$N, non sono ancora sicuro se tu sia $Gvivo o morto:viva o morta;... $GUmano:Umana; o Worgen...|n|nNon sono nemmeno così convinto di essere sveglio, ma di una cosa sono CERTO...|n|nOggi uccideremo un bel po\' di questi dannati Reietti.', },
    {'Uccidi 10 Reietti Invasori.', },
  },
  [14348] = {
    'L\'unione fa la forza',
    {'$N, guarda, arrivano quelli grossi... li chiamano Abomini. Non sono facili da eliminare, dunque non provare a farlo da $Gsolo:sola;.|n|nMi è venuta un\'idea... è talmente folle che potrebbe funzionare. O probabilmente finirà col farti ammazzare, se non stiamo attenti.|n|nCi sono dei barili di polvere da sparo sotto ai capanni e accanto ai mulini. Prendili e lanciali sulle teste degli Abomini. Io mi occuperò del resto con questo vecchio e fidato schioppo.', },
    {'Usa i Barilotti di Polvere da Sparo Nera per far esplodere 4 Abomini Orridi.', },
  },
  [14352] = {
    'Un\'alleanza empia',
    nil,
    nil,
  },
  [14353] = {
    'Un\'alleanza empia',
    nil,
    nil,
  },
  [14354] = {
    'Doni di Elune',
    {'È inaccettabile!|n|nI Satiri stanno profanando le nostre terre sacre...|n|nHanno i giorni contati, $R, ci puoi scommettere. Non appena raduneremo un gruppo abbastanza numeroso, guiderò un attacco per liberare questa terra da quelle creature malefiche.|n|nPer il momento, potresti fare qualcosa per darmi un po\' di sollievo.|n|nDirigiti a est di qui verso Sargeron e perlustra le rovine. Trova le Reliquie di Elune e assicurati che siano in buone condizioni.|n|nIn cambio ti pagherò bene.', },
    {'Visita le Reliquie di Elune a Sargeron.', },
  },
  [14357] = {
    'A fil di lama!',
    {'<Per la Vergine di Elune! È ancora più bella di quello che si dice.>|n|n<Non appena ti avvicini alla reliquia, ti vengono in mente le leggende sul suo conto.>|n|n<Nei tempi antichi, al termine della battaglia, le armi dei nemici venivano gettate nel catino in cambio di una sorta di dono divino.>|n|n<Mentre pensi a questo rituale, il tuo sguardo viene attirato dal bagliore dell\'acciaio proveniente da una rastrelliera per le armi...>', },
    {'Raccogli 20 Sciabole dei Satiri dalle rastrelliere per le armi e dai Satiri nella regione.', },
  },
  [14358] = {
    'Vittime sacrificali',
    {'<Secondo un\'antica leggenda, questo braciere fu messo qui per eseguire riti sacrificali.>|n|n<Da quel poco che ti ricordi, chi mette la carne dei nemici di Elune sulle braci ardenti del braciere riceve una benedizione.>|n|n<Guardandoti intorno, ti accorgi che i Satiri che ora controllano questa regione sarebbero delle vittime perfette.>', },
    {'Raccogli 10 Pezzi di Carne di Satiro dai Satiri di Sargeron e sistemali sul Braciere di Elune.', },
  },
  [14359] = {
    'Benedizioni dall\'alto',
    {'<Dopo aver ricevuto l\'antica benedizione impartita da questa reliquia, avverti un profondo legame con il passato.>|n|n<Decidi di sfruttare al massimo questo dono divino.>', },
    {'Raccogli 10 Pezzi di Carne di Satiro dai Satiri di Sargeron e sistemali sul Braciere di Elune.', },
  },
  [14360] = {
    'Con un paio di meloni si aggiusta tutto',
    {'<Dalle iscrizioni riportate sulle Rovine di Sargeron e da quelle che hai scorto nel Diario di Furien, ti è chiara una cosa:>|n|n<la vecchia fontana nel Santuario di Elune ha qualcosa di speciale.>|n|n<Sembra che sciacquarsi la faccia con l\'acqua della fontana permetta di ottenere un potere speciale. Per capire se è vero, bisognerà innanzitutto riempirla di qualcosa con cui lavarsi.>|n|n<Mentre rifletti sul da farsi, vedi un melone alla base di un albero vicino...>', },
    {'Raccogli 8 Meloni e spremi il loro succo nella Coppa di Elune a Sargeron.', },
  },
  [14361] = {
    'Pace dei sensi',
    {'Noi siamo un avamposto di frontiera e abbiamo l\'ordine di tenere gli occhi aperti in caso di possibili attacchi nemici. Quando l\'Alleanza lancerà la propria campagna per Desolanda, il nostro compito qui sarà assicurare che non vi siano sorprese.|n|nRecentemente, uno dei nostri esploratori è stato catturato e ucciso dalle Lame Ardenti nella loro roccaforte a ovest. Da allora, siamo stati minacciati e attaccati da un membro delle Lame Ardenti di nome Kohor.|n|nI loro giorni qui sono contati, ma ti pagherò bene se ucciderai quell\'essere al più presto!', },
    {'Uccidi Kohor.', },
  },
  [14362] = {
    'Orecchie ardenti',
    {'<Il Capitano Pentigast non ha mai nascosto il proprio disprezzo per le Lame Ardenti della Fortezza Ascia del Tuono.>|n|n<Apprezzerebbe sicuramente una prova della loro morte.>', },
    {'Raccogli 25 Orecchie delle Lame Ardenti.', },
  },
  [14363] = {
    'Lo riconoscerai quando lo vedrai',
    {'In punto di morte, Kohor ha parlato dell\'evocazione di un demone che potrebbe minacciare l\'intera regione.|n|nPotrebbe aver mentito, ma meglio non correre rischi.|n|nNon possiamo attendere che abbia inizio l\'invasione di Desolanda da parte dell\'Alleanza. Devi setacciare la Fortezza Ascia del Tuono in cerca di indizi e porre fine a questa potenziale minaccia.', },
    {'Trova l\'Antico Rituale di Evocazione nella Fortezza Ascia del Tuono.', },
  },
  [14364] = {
    'Riunire le loro teste',
    {'Dunque è vero...|n|nLa cartapecora che hai trovato nella Fortezza Ascia del Tuono spiega nel dettaglio un potente rituale di evocazione, ancor più efficace di qualsiasi altro in possesso delle Lame Ardenti.|n|nBisogna fermarlo a ogni costo!|n|nForse, se questo demone venisse evocato prima del tempo, potremmo evitare una catastrofe.', },
    {'Raccogli 100 Teschi Sbiancati dalla Fortezza Ascia del Tuono, quindi sistemali nel Cerchio di Evocazione delle Lame Ardenti e uccidi Nazargen.', },
  },
  [14365] = {
    nil,
    {'Recentemente abbiamo ricevuto una richiesta d\'aiuto da parte di una ricercatrice del Circolo Cenariano.|n|nAl momento non abbiamo nessuno da mandare, dunque ti chiederei di farle visita a nome nostro.|n|nKorrah si trova vicino alla torre diroccata di Ethel Rethor, lungo la costa a ovest.', },
    {'Il Caporale Melkins ti ha chiesto di parlare con Korrah a Ethel Rethor.', },
  },
  [14366] = {
    'Tenere duro',
    {'Da qui in avanti possiamo occuparcene noi, $N. Vai dal Sindaco Bracciofermo.|n|nQuesta è solo una minima parte delle forze dei Reietti. Se non agiamo in fretta saranno guai seri.|n|nVedi quello che puoi fare per affrontare l\'esercito dei Reietti nel punto in cui sono sbarcati.', },
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14367] = {
    'Lo scantinato degli Allen',
    {'Ser Godfrey dirige l\'attacco nei pressi della zona di sbarco dei Reietti. Aiutaci a respingerli, $N.|n|nHo saputo che Godfrey ha scelto come base operativa lo scantinato della Fattoria degli Allen a ovest. Vai lì e cercalo.', },
    {'Parla con Ser Godfrey nello scantinato della Fattoria degli Allean a Gilneas.', },
  },
  [14368] = {
    'Salva i bambini!',
    {'I miei bambini sono ancora nella fattoria, ma i militari non mi permettono di uscire dallo scantinato! Ti prego, devi andare a cercarli.|n|nI Reietti non hanno alcun riguardo verso gli innocenti... i miei bambini sono in grave pericolo!|n|nSi chiamano Cynthia, Ashley e James. Se li trovi, portali qui e avrai la mia eterna gratitudine.', },
    {'Salva Cynthia, Ashley e James nella Tenuta degli Hammond.', },
  },
  [14369] = {
    'Scatenare la bestia',
    {'Sarò sincero, $N... non mi piace affatto l\'idea di avere $Gun:una; Worgen tra le nostre file.|n|nChi ci garantisce che non ci salterai addosso per divorarci una volta svanito l\'effetto della pozione di Krennan?|n|nFino ad allora, però, la tua ferocia ci tornerà utile.|n|nRaggiungi il campo di battaglia e uccidi quanti più Reietti possibili, senza alcuna pietà.|n|nDobbiamo fare in modo che temano i Worgen, $N.', },
    {'Uccidi 8 Soldati Reietti o Marinai Reietti.', },
  },
  [14370] = {
    'Azsharite misteriosa',
    {'Azsharite! Questa misteriosa sostanza cristallina è stata usata per forgiare armi di spregevole potenza, ma da quel poco che abbiamo potuto scoprire, sappiamo che è in grado di canalizzare enormi quantitativi di energia. Potrebbe rivelarsi la più grande scoperta dei Goblin dai tempi della kaja\'mite.|n|nMa che cos\'è? Da dove viene? Perché si trova solo qui? La scienza esige delle risposte! Mi servono altri campioni per le mie ricerche. Perché non cerchi dei depositi di azsharite nelle alture qui intorno?', },
    {'Raccogli 5 Campioni d\'Azsharite nelle alture vicine.', },
  },
  [14371] = {
    'Uno spuntino gigantesco',
    {'Giacché ti trovi a esplorare le alture, forse puoi aiutarmi anche in un altro modo. I giganti che abitano da queste parti sono qui sin dai tempi in cui si formarono le montagne. Forse loro sanno da dove viene l\'azsharite. È nel nostro interesse farceli amici e vedere se sanno qualcosa.|n|nQuello che ti chiedo è di mettere insieme un pasto gigantesco da offrire loro come gesto amichevole! Uccidi le Chimere Alabruma, che del resto non fanno altro che rallentare le nostre ricerche, e raccogli le loro carcasse.', },
    {'Raccogli 8 Carcasse di Chimere Alabruma Mutilate.', },
  },
  [14372] = {
    'Bivacco di Thargad',
    {'Mi fa piacere che tu sia ancora $Gvivo:viva;, $C. Ho saputo che l\'attività dei demoni a sud si è intensificata.|n|nC\'è un campo al confine che rischia di essere distrutto se i demoni dovessero avanzare verso nord.|n|nNon è che potresti dare una mano?|n|nIl capo del campo si chiama Thargad. Lui saprà come guidarti.|n|nGrazie, $Gamico:amica;. Buona fortuna.', },
    {'Karnum Plasma Paludi ti ha chiesto di parlare con Thargad.', },
  },
  [14373] = {
    'Invasione infernale',
    {'Apri bene le orecchie e da\' un\'occhiata qui.|n|n<Thargad indica verso est.>|n|nVedi quelle grosse sfere verdi luminose che cadono dal cielo?|n|nQuelli sono un gruppo di demoni che vagano tranquilli... o quasi. Con me hanno trovato pane per i loro denti.|n|nChe ne dici di proseguire il mio lavoro?', },
    {'Distruggi 10 Infernali Minori.', },
  },
  [14374] = {
    'Portali della Legione',
    nil,
    {'Distruggi 6 Portali alla Congrega di Mannoroc.', },
  },
  [14375] = {
    'Ultima speranza per l\'umanità',
    nil,
    nil,
  },
  [14376] = {
    'Rovina di Jugkar',
    {'<La riconosci come l\'essenza di un demone evocato.>|n|n<Energie pericolose e oscure danzano sulla sua superficie.>|n|n<Fissandola, hai una visione: un\'immagine di te che controlli degli schiavi demoniaci. Una scarica d\'adrenalina scorre nelle tue vene mentre ti immagini a esercitare un simile potere.>|n|n<Guardandoti intorno ti chiedi come sia possibile usare questo tesoro contro questo nemico demoniaco...>', },
    {'Usa il Nucleo Energetico Infernale per assumere il controllo di Azrethoc all\'Altare di Jugkar e sfrutta i suoi poteri per uccidere Jugkar Vergatruce.', },
  },
  [14377] = {
    'Un gigante per amico',
    {'Da un rapido esame dell\'azsharite che mi hai portato, ho potuto stabilire che non è di natura biologica, né si forma naturalmente. Esiste un\'altra creatura ad Azshara dalle proprietà simili: i Giganti delle Colline che abitano queste alture.|n|nUno dei giganti sembra essere disposto ad aiutarci nelle nostre ricerche. Porta la carne che hai raccolto a Gormungan, il gigante che si trova a ovest di qui. Stringi amicizia con lui e poi mettilo sotto torchio: scopri se conosce il segreto dell\'azsharite!', },
    {'Parla con Gormungan, che si trova all\'esterno del Terminale Sud della Razzovia, e scopri il segreto dell\'azsharite.', },
  },
  [14378] = {
    'Sulle tracce di Brendol',
    {'Sono troppo impegnato a raccogliere manufatti per occuparmi d\'altro, ma c\'è un problema qui che vorrei risolvere.|n|nC\'è uno Speziale Reietto che si aggira da queste parti da un po\' di tempo ormai. Normalmente lo ignorerei, ma sono già tre volte che si introduce nel mio campo per rubare le provviste. Anche la mia pazienza ha un limite!|n|nTrova il ladro e portami ciò che resta delle mie cose!', },
    {'Recupera la Sacca di Brendol.', },
  },
  [14379] = {
    'Aragoide delle Rocce!',
    {'Thargad lavora ininterrottamente alla ricerca delle antiche reliquie dei Titani. È talmente impegnato che se non fosse per me, probabilmente si dimenticherebbe anche di mangiare!|n|nA proposito di mangiare, vorrei cucinargli qualcosa di speciale. Ti va di aiutarmi?|n|nLa costa a ovest è piena di Aragoidi. Non riuscirei mai a catturarne uno con le mie mani, ma se mi porti alcune delle loro code potrei cucinarci un ottimo piatto!', },
    {'Ottieni 7 Code di Aragoide Tenere.', },
  },
  [14380] = {
    'Una scoperta importante',
    {'<Thargad fruga nella borsa e tira fuori uno strano oggetto.>|n|nQuesto sì che è bizzarro... un Corno di Kodo Scavato, con una specie di pozione all\'interno.|n|n<Thargad annusa la pozione.>|n|nBLEAH! Sicuramente non è un elisir di guarigione. Questo miscuglio serve per una cosa sola... uccidere.|n|nChe ne dici di portarlo a Karnum? Forse lui saprà cosa farne...', },
    nil,
  },
  [14381] = {
    'Ripulire il nostro crepaccio',
    {'So quanto sia malvagia questa creazione. Si tratta di un male terribile, che uccide quasi all\'istante e in maniera violenta. Per quanto mi disgusti l\'idea di ricorrere a simili mezzi, temo che non abbiamo molta scelta.|n|nCome ben saprai, i Naga rappresentano una seria minaccia per la regione. È arrivato il momento di ricacciarli in mare!|n|nQuando sei $Gpronto:pronta;, Piumatruce ti condurrà al crepaccio dove stanno preparando un attacco su vasta scala.|n|nUsa la mistura sui Naga e i loro alleati per salvare Desolanda!', },
    {'Usa la Mistura di Maurin per uccidere 10 Invasori Lamasalmastra, 10 Sirene Lamasalmastra e 3 Giganti del Mare.', },
  },
  [14382] = {
    'Due piccioni con una fava',
    {'Le Catapulte dei Reietti ci stanno massacrando, $N. Anche se dovessimo distruggerle, hanno due navi pronte con diverse file di cannoni.|n|nHo un piano per prendere due piccioni con una fava, e tu sarai la fava.|n|nUccidi i macchinisti delle catapulte, quindi usale per lanciarti a bordo delle navi dei Reietti.|n|nSe hai una mira decente, dovresti riuscire ad atterrare $Gsano e salvo:sana e salva;. Una volta a bordo, dirigiti sottocoperta e sbarazzati del capitano di ciascuna nave. Buona fortuna, $C.', },
    {'Usa le Catapulte dei Reietti per salire a bordo delle navi dei Reietti e uccidere il Capitano Morris e il Capitano Anson.', },
  },
  [14383] = {
    'Gli odiosi ficcanaso dei Confini Spezzati',
    {'Farabutti! Infedeli! Da quando ho avviato le mie ricerche qui ad Azshara, la famiglia Primaciarpa non ha fatto altro che ostacolarle e sabotarle. E ora un manipolo di spregevoli ficcanaso di second\'ordine è giunto in loro soccorso! Io ho delle questioni piuttosto importanti a cui badare, sbarazzati tu di quegli Gnomi.|n|nRecati ai Confini Spezzati lungo la costa, a sud del mio Laboratorio Segreto, e fai rotolare alcune delle loro teste sproporzionatamente grosse per me.', },
    {'Massacra Bingham Primaciarpa nei Confini Spezzati, insieme a 4 Gnomi Sparareti e 6 Gnomi Folgoratori.', },
  },
  [14384] = {
    nil,
    {'Alt!|n|nPer conto della Guardia del Presidio di Nijel ho l\'ordine di inviare tutti gli alleati idonei a rapporto direttamente dal Caporale Melkins.|n|nNon sono autorizzata a darti altre informazioni.|n|nQuello che posso offrirti è un trasporto. Puoi usare la mia cavalcatura. Ti condurrà a destinazione.|n|nOra va\'.', },
    {'L\'Ufficiale Jankie ti ha chiesto di prendere la sua cavalcatura e raggiungere il Presidio di Nijel per parlare con il Caporale Melkins.', },
  },
  [14385] = {
    'Azsharite: esperimento numero uno',
    {'Allora, mi è venuto in mente un modo sicuro per far correre i Giganti delle Colline al bagno, ma non ti piacerà. Quello che ci serve è un enorme... lassativo. Ehi! Sai che gli Gnomi hanno proprio ciò che fa al caso nostro? Non può essere una coincidenza. Chissà a cosa gli serve!|n|nSecondo le nostre informazioni riservate, il lassativo è stato consegnato alla Torre di Primaciarpa, lungo la costa, a sud del Laboratorio Segreto. Recuperalo e fallo ingerire a Gormungan!', },
    {'Recupera un Lassativo Gigante dalla torre degli Gnomi nei Confini Spezzati, quindi cerca di farlo ingerire al Gigante Gormungan.', },
  },
  [14386] = {
    'Capobranco',
    {'Fin qui hai fatto un lavoro eccellente, $N. I nostri esploratori hanno individuato la responsabile dell\'attacco terrestre dei Reietti.|n|nUna delle Guardaboschi Oscure scelte da Sylvanas sta sorvegliando il fronte della battaglia dalla casa di Walden nei pressi della spiaggia. Prendi questo richiamo e usalo quando ti trovi vicino a lei.|n|nIo darò ordine ai miei uomini di liberare i mastini per ucciderla. Fa\' attenzione, $N... non affrontarla da $Gsolo:sola;.', },
    {'Usa il Richiamo del Mastino per avere supporto nell\'uccisione della Guardaboschi Oscura Thyala.', },
  },
  [14387] = {
    'Geografia fisica',
    {'$GBenvenuto:Benvenuta; a Desolanda, $R.|n|nTi chiedo scusa per l\'insistenza, ma noi siamo un piccolo avamposto e ci sono grossi problemi in questa regione, la maggior parte dei quali piuttosto urgenti.|n|nIn breve, ci serve tutto l\'aiuto che riusciremo a ottenere.|n|nPer cominciare, c\'è il nostro amico Vahlarriel laggiù che è molto agitato. Insiste che dovremmo inviare un contingente per controllare le rovine a est.|n|nPerché non vai da lui e ti presenti?', },
    {'Il Capitano Pentigast ti ha chiesto di parlare con Vahlarriel al Presidio di Nijel.', },
  },
  [14388] = {
    'Azsharite: esperimento numero due',
    {'Allora, ho un altro piano. Gliela faremo FARE SOTTO dalla paura! In base alla mia esperienza, le creature mastodontiche sono sempre terrorizzate da quelle molto più piccole, come i ratti per esempio. Mmm. Questo posto brulica di ratti, ma come facciamo a portarli dal gigante?|n|nEhi! Ti dispiace se disgrego e poi riassemblo la tua matrice cellulare? Fa male solo durante il processo. Potrei ridurti alle dimensioni di un ratto e tu potresti cavalcarne uno fino al gigante. È un\'idea così folle che non può non funzionare! Torna da me quando sei $Gpronto:pronta; a farti rimpicciolire...', },
    {'Parla con l\'Assistente Greely per farti rimpicciolire fino alle dimensioni di un ratto. Monta su un ratto della Razzovia e usalo per far spaventare il Gigante Gormungan.', },
  },
  [14389] = {
    'Non era ovvio?',
    {'Azuregos! Sì, ma certo. Quel vecchio drago, sempre pensieroso ma adorabile. Non credo che tutti questi anni di assalti da parte di vagabondi gli abbiano fatto bene. In questi ultimi tempi si comporta in modo molto strano.|n|nE non molto tempo fa, quando siamo tornati dal nostro Spirito Guaritore locale, Anara, non ho potuto fare a meno di notare che lei e Azuregos sembravano andare parecchio d\'accordo. Immagino le stia ancora tenendo compagnia.|n|nProbabilmente il modo più rapido per raggiungerla è il portale alle mie spalle. Potrebbe fare un po\' male, però.', },
    {'Usa il portale alle spalle di Joanna nella Torre di Xylem per trovare lo Spirito Guaritore Anara e, con un po\' di fortuna, Azuregos.', },
  },
  [14390] = {
    'Se è facile, è noioso',
    {'Dopo una lunga ricerca con diversi colpi di scena discutibili, finalmente hai trovato Azuregos.|n|nOra si tratta solo di convincerlo a incontrare Kalecgos e mettere fine alla minaccia dello Stormo dei Draghi Neri di Azshara.', },
    {'Convinci Azuregos a tornare nel mondo dei vivi e incontrare Kalecgos.', },
  },
  [14391] = {
    'Ribaltamento tattico',
    {'Azuregos e Kalecgos si incontreranno al Terminale Settentrionale della Razzovia. Dovresti raggiungerli per accertarti che Kalecgos non abbia ancora bisogno del tuo aiuto.|n|nQualora preferissi non essere $Gmorto:morta;, puoi chiedere aiuto ad Anara.', },
    {'Parla con Anara per tornare nel mondo dei vivi, quindi raggiungi Kalecgos al Terminale Settentrionale della Razzovia.', },
  },
  [14392] = {
    'Addio, piccola creatura',
    {'Grazie, piccola creatura.|n|nA volte è facile smarrirsi tra i sospiri d\'amore e perdere di vista tutto il resto, anche per un drago. Adesso voglio dedicarmi completamente a un nobile scopo: impedire che Kalec prenda il posto di Malygos. Non mi viene in mente niente di più degno.|n|nTu, invece, faresti bene a tornare al porto. Credo che lì ci sia qualcuno ad aspettarti.|n|nCerca di non farti schiacciare o mangiare da nessuno.', },
    {'Parla con Sorata Fiammatorta al Porto degli Acqualorda.', },
  },
  [14393] = {
    'Nel vivo della lotta!',
    {'Per troppe generazioni i clan dei Centauri hanno combattuto tra loro, ma ora non più.|n|nGrazie alle tue imprese, ci troviamo qui l\'uno al fianco dell\'altro per affrontare un nemico comune. Ci riprenderemo le nostre terre ancestrali da questi demoni, o moriremo come fratelli.|n|nTu cosa farai, $N?|n|nTi sei $Gguadagnato:guadagnata; il diritto di combattere con noi. Ho un gruppo dei miei migliori Centauri che attendono solo di essere guidati in battaglia.|n|nAccetti questo compito?', },
    {'Il Khan Leh\'prah ti ha chiesto di uccidere 15 Stregoni delle Lame Ardenti, 3 Demoni Guardiani Invasori e la Sacerdotessa Than\'darissa.|n|nParla con il Khan Leh\'prah per prendere parte alla battaglia.', },
  },
  [14394] = {
    'Morte ad Agogridon',
    {'Il nostro obiettivo è a portata di mano, $N!|n|nPossiamo piegare la volontà di questa armata di demoni eliminando colui che la guida. Se ci riusciamo, Desolanda sarà nostra!|n|nQuando sei $Gpronto:pronta;, guida un gruppo di Centauri attraverso il passo verso sud, nella Gola delle Ombre Infrante. Scopri dove si nasconde Agogridon!|n|nIo radunerò gli altri Khan e ci ritroveremo lì per affrontarlo in battaglia.', },
    nil,
  },
  [14395] = {
    'All\'ultimo respiro',
    {'$N! Ero in viaggio quando è successo.|n|nNon c\'è tempo da perdere... metà del corpo di guardia del villaggio si trovava nella zona sommersa. Vai lì e salva più uomini che puoi.|n|nTrascinali fuori dall\'acqua fino a riva. Io farò in modo che ricevano gli aiuti necessari.', },
    {'Salva 4 Sorveglianti Moribondi.', },
  },
  [14396] = {
    'Maremoto',
    {'Che diavolo è stato, $N?|n|nDi sicuro non era rumore di cannoni, né di catapulte.|n|nEsci fuori e cerca di capire cosa sta succedendo.', },
    {'Parla con il Principe Liam Mantogrigio alla Fattoria degli Allen.', },
  },
  [14397] = {
    nil,
    {'Siamo scampati alla morte per un pelo, $N, ma a quanto pare la fortuna ci ha abbandonati.|n|nLa costa sta venendo sommersa proprio in questo momento e sembra che la terra sotto di noi non si sia ancora placata.|n|nNon avrei mai voluto dirlo, ma dobbiamo andarcene. Accidenti, $N... sarebbe già la seconda volta che perdo la mia terra natale, ma non c\'è niente da fare contro questi terremoti.|n|nDi\' a Gwen Bracciofermo di prepararsi all\'evacuazione.', },
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14398] = {
    'Nonna Wahl',
    {'Non sarà facile convincere Nonna Wahl a venire con noi. Usa ogni mezzo per riuscirci.|n|nLa troverai nella Villa dei Wahl. Ti prego, $N, non perdere la pazienza con lei. È anziana e non ci sta più tanto con la testa.', },
    {'Trova Nonna Wahl nella Villa dei Wahl.', },
  },
  [14399] = {
    'Il libro della Nonna',
    {'Andarmene? Ora?|n|nBe\', se è necessario lo farò. Prima, però, saresti così gentile da trovare una cosa per me?|n|nHo perso il mio libro preferito e non ho intenzione di andarmene senza di esso.|n|n<Dopo averle spiegato la gravità della situazione, Nonna Wahl annuisce con la testa.>|n|nSì... tu trova il mio libro, d\'accordo?', },
    {'Trova il Libro Avvolto nel Lino.', },
  },
  [14400] = {
    'Il vestito della Nonna',
    {'Cos\'è che volevi?|n|nOh, già, l\'evacuazione.|n|nBe\', non posso mica presentarmi in pubblico conciata così, non trovi?|n|nVai a prendere il mio vestito buono. È steso fuori.|n|n<Cerchi invano di convincere Nonna Wahl che qualsiasi cosa indossi andrà bene.>|n|nVoi giovani non conoscete l\'educazione. Siete stati cresciuti dagli Ogre per caso? Ora fila a prendere il mio vestito.', },
    {'Prendi il Vestito Buono della Nonna.', },
  },
  [14401] = {
    'Il gatto della Nonna',
    {'Ah, sì, l\'evacuazione... me ne ero quasi dimenticata.|n|nNon posso andarmene senza il mio gatto. È un delizioso soriano arancione.|n|nC\'è un carro rotto vicino a un pergolato a nord-est di qui. Pacchio adora andarci a giocare.|n|nRiportamelo e ce ne andremo tutti insieme.', },
    {'Recupera Pacchio.', },
  },
  [14402] = {
    'Pronta a partire',
    {'Immagino che questo sia il momento giusto per andarsene.|n|nHo il mio vestito buono, il mio libro preferito e il mio adorato gatto.|n|nSpero di non dimenticare nulla.|n|nDi\' al sindaco che la raggiungerò presto. Ci vediamo al villaggio con gli altri!', },
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14403] = {
    'I fratelli Tagliafieno',
    {'A sud si trova il Porticciolo dei Tagliafieno. È gestito da anni dai fratelli Tagliafieno.|n|nVengono al villaggio solo ogni tanto per vendere il loro pesce. Avvisali dell\'evacuazione.', },
    {'Parla con Sebastian Tagliafieno al Porticciolo dei Tagliafieno.', },
  },
  [14404] = {
    'Non siamo ancora pronti',
    {'Evacuazione, hai detto? Avevamo avuto la stessa idea dopo la comparsa di questi Reietti.|n|nPensavamo che l\'acqua fosse la via di fuga più sicura.|n|nPurtroppo, però, le nostre barche sono state danneggiate dall\'ultimo terremoto.|n|nMi servono i miei attrezzi, legno e catrame per terminare le riparazioni. Procurameli, così i miei fratelli e io potremo andarcene da qui.', },
    {'Procurati Assi di Legno, Catrame e Attrezzi da Carpentiere.', },
  },
  [14405] = {
    'Fuga via mare',
    {'Grazie per il tuo aiuto, $N. Questa nave è pronta a salpare.|n|nOra va\' dalla signora Bracciofermo e dille che non prenderemo parte all\'evacuazione via terra.|n|nNoi Tagliafieno siamo marinai da generazioni. Se proprio dobbiamo lasciare la nostra casa, lo faremo per mare.', },
    {'Torna da Gwen Bracciofermo a Borgotetro.', },
  },
  [14406] = {
    'Il Frutteto dei Crowley',
    {'Ti ricorderai sicuramente di Lorna, la figlia di Ser Darius Crowley.|n|nNon si è mai ripresa del tutto dopo la morte di suo padre a Gilneas. Da allora si è isolata da tutto e da tutti. L\'unico visitatore che ha accolto nella sua casa è stato Krennan... ma lui non ha intenzione di avvertirla.|n|nDevi avvisare Lorna dell\'evacuazione, $N.', },
    {'Parla con Lorna Crowley al Frutteto dei Crowley.', },
  },
  [14407] = {
    'Richiesta di aiuto',
    {'Ehi! Ti stavo cercando.|n|nSono qui per conto del mio padrone, Kalec. Egli ha bisogno del tuo aiuto. Lo troverai nei bassifondi, sotto il ponte. Raggiungilo il prima possibile!', },
    {'Incontra Kalec al Porto degli Acqualorda.', },
  },
  [14408] = {
    'Piano nove',
    nil,
    {'Recupera i Progetti del Razzo Segreto dagli Archivi del Laboratorio, l\'edificio posto nell\'estremità orientale del complesso del Laboratorio Segreto. Suona il campanello e uccidi il Direttore del Laboratorio non appena lo incontri.', },
  },
  [14410] = {
    'Le terre selvagge di Feralas',
    {'Sei davvero $Gcoraggioso:coraggiosa; ad aiutarci a proteggere queste terre. Se vuoi, ce ne sono altre che hanno bisogno del tuo aiuto.|n|nLe verdeggianti foreste di Feralas si trovano a sud. Una volta lì, cerca Telaron Volavento all\'ombra dei giganteschi Colossi Gemelli. Al Riposo del Sognatore, lui e i suoi Druidi dell\'Artiglio hanno trovato indizi di qualcosa di malefico e inquietante.|n|nPotrebbero aver bisogno del tuo aiuto, $C. Vai in pace.', },
    {'Raggiungi Feralas e parla con Telaron Volavento al Riposo del Sognatore.', },
  },
  [14412] = {
    'Pericolo a riva',
    {'Le navi di quei Reietti sono affondate vicino al nostro porticciolo. Tutti i superstiti si stanno trascinando qui a riva e, come puoi vedere, ci troviamo in inferiorità numerica.|n|nAiutaci a tenerli a bada finché non termino di riparare le barche.', },
    {'Uccidi 6 Naufraghi Reietti.', },
  },
  [14413] = {
    'Pinnacolo dell\'apprendimento',
    {'Com\'è eccitante! Cosa è eccitante, ti chiederai? Ma QUESTO, naturalmente!|n|nÈ giunta l\'ora della prova... o meglio, è giunta l\'ora della TUA prova. Quante sfide da superare, quante lezioni da incamerare. Tu impari attraverso le prove e io scopro qualcosa in più su di te.|n|nVa\', dunque. Al mio Pinnacolo Arcano. Naturalmente ci rincontreremo lì, perché io sono dappertutto.', },
    {'Parla con l\'Immagine dell\'Arcimago Xylem alla base del Pinnacolo Arcano.', },
  },
  [14416] = {
    'L\'Ettin affamato',
    {'Ascolta, $N. Non andremo molto lontano senza un mezzo di trasporto.|n|nAnche se dovessimo fuggire da qui in fretta, i Reietti ci raggiungerebbero in un attimo.|n|nRadunare alcuni cavalli dalle stalle a sud-est di solito sarebbe una passeggiata, ma c\'è un problema.|n|nL\'ultimo terremoto deve aver spaventato l\'Ettin Koroth, facendolo scendere dalle montagne. Se non prendiamo presto i cavalli, temo che lo farà lui.', },
    {'Porta 5 Cavalli di Montagna a Lorna Crowley nel Frutteto dei Crowley.', },
  },
  [14422] = {
    'Razzo Raptor Raptor',
    {'Poco dopo il potenziamento del mio intelletto, mi sono accoppiata con il Soggetto Quattro in modo da creare una super-razza di raptor cognitivamente superiori. Successivamente, il Soggetto Quattro non si è più fatto sentire o trovare: la prossima volta che ci incontreremo, ho intenzione di sbudellarlo.|n|nA ogni modo, i piccoli raptor imprigionati in questo laboratorio sono già sufficienti per fornire una copertura genetica adeguata per la ripopolazione della mia razza. Ti prego di liberarli dalle loro gabbie e di portarli al razzo.', },
    {'Libera 5 Cavie Raptor dalle gabbie del Laboratorio Segreto e portale al razzo accanto al Soggetto Nove.', },
  },
  [14423] = {
    nil,
    {'...Avremo bisogno di un Sacerdote!|n|nPer fortuna riservo sempre parte dei fondi per la benedizione dei macchinari. Prendi questa spararazzi e torna da Margene, la mia povera macchinetta indifesa. Spara il razzo di segnalazione e uno dei nostri migliori sacerdoti aviotrasportati dovrebbe precipitarsi e prendere in mano la situazione. Quando il mio bulldozer sarà stato "esorcizzato", torna da me!', },
    {'Usa la Spararazzi Benedetta nei pressi di Margene per chiamare aiuto, quindi esorcizza il bulldozer.', },
  },
  [14424] = {
    'Alla scienza non c\'è mai fine',
    {'<Clubnik si asciuga una lacrima, poi sporge il mento con determinazione.>|n|nMai più, $N! Nessun bulldozer merita la fine della mia Margene. Dovremo attuare un piano contro i fantasmi su scala industriale. Questo è un lavoro per i nostri scienziati migliori e io conosco proprio la donna che fa al caso nostro! Cerca l\'Assistente Greely al Terminale Sud della Razzovia. Lei è l\'amministratrice del famosissimo Laboratorio Segreto di Azshara e mi deve un favore.', },
    {'Cerca l\'Assistente Greely al Terminale Sud della Razzovia. La Razzovia dei Goblin permette di spostarsi rapidamente per tutta Azshara.', },
  },
  [14428] = {
    'Il diario di Ambravento',
    {'Se le mie fonti sono attendibili, è la Storica Ambravento a sovrintendere alla perlustrazione delle rovine a est da parte dell\'Alleanza. Purtroppo non ho ancora un\'idea precisa delle sue capacità: spero che tu possa farmi avere notizie più dettagliate dopo averla affrontata e uccisa.|n|nDato il titolo di Storica, immagino che Ambravento avrà con sé un diario, dal quale potremo ricavare cosa stanno tramando quegli Elfi della Notte. Recupera quel diario. Non avrai neanche bisogno di tornare qui da me: potrai usare i loro stessi Remotovisori per contattarmi senza muoverti da lì.', },
    {'Uccidi la Storica Ambravento nel Campo Base Darnassiano e recupera il suo diario.', },
  },
  [14429] = {
    'Decostruzione arcana',
    {'I Costrutti Arcani sono creature generate puramente da mana e intelletto. Nelle mani giuste, i costrutti permettono di assimilare rapidamente profonde conoscenze arcane. Non illuderti, $N, sono pericolosi, intelligenti e potenti! Ma anche molto vulnerabili alle interferenze esterne...|n|nDiamo una lezione a questi principianti usando la loro stessa magia contro di essi. Uccidi gli Apprendisti e recupera le loro Pietre Runiche. Quando hai finito, mettiti in contatto con me tramite il Remotovisore Inferiore.', },
    {'Uccidi gli Apprendisti Investigatori e gli Apprendisti Illuminati per raccogliere 10 Pietre Runiche Attivate.', },
  },
  [14430] = {
    'Costrutto da decostruire',
    {'Ora penetreremo nella mente di quel Costrutto Arcano e ce ne serviremo per seminare il caos. $N, hai già esperienza di questo tipo di magia? No? Ah! Questo rende il mio piano ancora più divertente. Lì vicino dovresti vedere quel formidabile Costrutto Arcano che hanno evocato. Grazie alle Pietre Runiche che hai recuperato, sappiamo come comunicare con esso. Parla al costrutto e di\': "Al\'teth la c\'tolgar". Hai capito? Puoi ripeterlo? D\'accordo, più o meno ci siamo. Poi contattami di nuovo e fammi sapere che cosa è successo!', },
    {'Parla con il Costrutto Arcano del Campo Base Darnassiano e pronuncia le parole del potere arcano.', },
  },
  [14431] = {
    'La faglia degli Zannanera',
    {'Nel corso della nostra progressiva colonizzazione di Azshara, le relazioni tra i Mezzorsi Zannanera che vivono in quest\'area e i loro compagni Mordilegno si sono deteriorate. Sono impazziti, $C, e ci attaccano di continuo. Peggio ancora, li abbiamo visti discutere amabilmente con gli Elfi della Notte di Talrendis. Non possiamo permettere una loro alleanza!|n|nA sud-ovest di qui troverai una larga faglia nella terra. Lì, secondo i miei esploratori, si riuniscono gli Elfi della Notte. Uccidili e raccogli ogni indizio utile che troverai.', },
    {'Uccidi 8 Biologi di Talrendis e raccogli informazioni sugli Zannanera da uno dei cadaveri.', },
  },
  [14432] = {
    'L\'infuso dei poliglotta',
    {'A quanto pare, i nostri nemici dell\'Alleanza hanno migliorato le loro relazioni con gli Zannanera conducendo i negoziati nella lingua dei Mezzorsi. Se vogliamo sabotare la loro intesa, dovremo fare lo stesso.|n|n$N, non è difficile come sembra. Gli Zannanera sono famosi per un loro infuso, i cui fumi sono in grado di mettere chiunque in uno stato di trance, permettendogli di parlare lingue altrimenti sconosciute. Come quella degli Zannanera, per esempio. Recati alla Tana degli Zannanera a sud-ovest di qui e recupera alcuni campioni di Erba Poliglotta!', },
    {'Raccogli 10 Campioni di Erba Poliglotta all\'esterno della Tana degli Zannanera.', },
  },
  [14433] = {
    'Diplomazia alternativa',
    {'Per infiltrare e sabotare i negoziati degli Zannanera, dobbiamo anzitutto scoprire dove si svolgono. Sospetto che potresti trovare degli ambasciatori elfici proprio nella Tana degli Zannanera a sud-ovest, intenti a prepararsi per l\'incontro.|n|n<Haggrum sputa per terra.>|n|nUccidili come meglio ti aggrada e cerca nella zona documenti di qualche importanza. Oh, e recupera una delle loro vesti: ci servirà.', },
    {'Recupera l\'Agenda dei Negoziati con gli Zannanera alla Tana degli Zannanera, uccidi un\'Ambasciatrice di Talrendis e recupera la Veste da Ambasciatore.', },
  },
  [14435] = {
    'Doppio gioco',
    {'Andorel mi ha preparato un piccolo ma utilissimo incantesimo. Vieni, mettiti accanto al fuoco e respira a fondo i fumi dell\'infuso. Indossa la veste e gli Zannanera ti crederanno un ambasciatore elfico.|n|nTravestiti e cerca Andorel qui nell\'accampamento. Ti teletrasporterà nella Tana degli Zannanera, proprio dove avrà luogo l\'incontro decisivo. Parla con il Capo Tribù Ungarl e fai saltare le trattative. Poi, sulla via del ritorno, uccidi quanti più Zannanera possibile!', },
    {'Indossa il Travestimento da Ambasciatore e parla con Andorel Giurasole per farti teletrasportare nella Tana degli Zannanera. Parla con Ungarl per mandare all\'aria i negoziati, poi uccidi 4 Guerrieri Zannanera e 4 Sciamani Zannanera sulla via del ritorno.', },
  },
  [14436] = {
    'Scavi nanici',
    {'I Nani stanno preparando un sito di scavo a nord-ovest. Credono che la terra nasconda dei segreti. Ed è vero, ma scavare dissacrandola non è il modo giusto per ricevere i suoi insegnamenti.|n|nRaccogli gli utensili di scavo dei Nani, distruggili e portameli.|n|nPuoi distruggerli in una forgia. Ne puoi trovare una a Picco del Tuono, ma qualsiasi forgia, anche una nell\'accampamento dei Nani, andrà bene.', },
    {'Recupera 5 Picconi da Prospettore e distruggili in una forgia per creare degli Utensili Rotti.|n|nPorta 5 Utensili Rotti ad Ahmo Corno Tonante al Villaggio di Zoccolo Sanguinario.', },
  },
  [14438] = {
    nil,
    {'$N, molti sono i conflitti che straziano questa terra. Spero che non dovrai assistere a così tanti di essi quanto i nostri avi. Tuttavia, ce n\'è uno che dovrai scatenare tu $Gstesso:stessa;. Ti farò capire quanto terribile per la terra possa diventare una piccola minaccia se non viene controllata.|n|nGli Gnoll Mantopallido si sono insediati a sud di Zoccolo Sanguinario e in una caverna a ovest. Disprezzano i nostri tentativi di comunicare con loro e massacrano la fauna di Mulgore senza ritegno.|n|nLe parole non sono più la soluzione migliore.', },
    nil,
  },
  [14439] = {
    'Viaggio a Picco del Tuono',
    nil,
    {'Parla con Baine Zoccolo Sanguinario a Picco del Tuono.', },
  },
  [14441] = {
    'Autografo di Garrosh',
    nil,
    nil,
  },
  [14442] = {
    'Il mio Soggetto preferito',
    {'Non so se l\'hai notato, $N, ma questo laboratorio è ormai in grave declino! Non ho avuto problemi a cancellare il progetto sugli ippogrifi, ma adesso è scomparso anche l\'esperimento a cui tenevo di più: il Soggetto Nove!|n|nIl Soggetto Nove è una raptor che abbiamo importato dalle Savane. Chissà se è ancora viva. Prova a cercarla nel complesso principale, a ovest di qui. Vicino a quel gigantesco razzo top secret. Non puoi sbagliarti.', },
    {'Localizza il Soggetto Nove all\'interno del complesso del Laboratorio Segreto di Azshara.', },
  },
  [14443] = {
    'L\'elsa rovinata',
    {'<Questa vecchia spada rovinata ha visto giorni migliori. Prima che l\'elsa fosse separata dalla lama, doveva essere una vera opera d\'arte.>|n|n<A giudicare dai simboli eleganti e dalle gemme esotiche che adornano l\'elsa, apparteneva a una persona importante. Sicuramente il Patto d\'Argento sarà interessato al recupero di un manufatto del genere. Cerca uno dei suoi rappresentanti alla Requie di Quel\'Delar, a sud dei Campi del Torneo d\'Argento.>', },
    {'Porta l\'Elsa Rovinata a Caladis Lanciachiara nella Requie di Quel\'Delar a sud dei Campi del Torneo d\'Argento.', },
  },
  [14444] = {
    'La conoscenza dei draghi',
    {'Non c\'è dubbio: quest\'elsa appartiene a un\'arma antica e molto potente. Ma quale? Non ricordo di aver visto o sentito parlare di una spada con questi segni. Comunque, non vuol dire che dobbiamo perdere le speranze!|n|nKorialstrasz, meglio conosciuto come Krasus, è amico di lunga data dei Quel\'dorei e del Kirin Tor. Grazie alla sua vasta conoscenza e alle risorse a sua disposizione, saprà sicuramente qualcosa. Sali in cima al Tempio della Lega dei Draghi e chiedi il suo aiuto, poi parla con l\'Arcanista Tybalin nell\'Enclave d\'Argento di Dalaran.', },
    {'Parla con Krasus in cima al Tempio della Lega dei Draghi.', },
  },
  [14445] = {
    'Addio, per il momento',
    {'I nostri destini saranno per sempre intrecciati. Gli eventi attuali stanno riplasmando il mondo, e finiranno per distruggerlo. Dobbiamo fermarli prima che sia troppo tardi.|n|nSappi che potrai sempre contare su di me, $Gfratello:sorella;! Ci ritroveremo sull\'isola più grande. Che fino allora tu possa trovare la pace, $N.', },
    {'Parla con Sassy Serrabullona al Belvedere Selvaggio sulle Isole Perdute.', },
  },
  [14446] = {
    nil,
    {'Ascolta le mie parole, $C!|n|nI venti del cambiamento hanno formato un violento uragano che imperversa su Azeroth.|n|nPossiedi il coraggio necessario per affrontare la vera causa della nostra sofferenza?|n|nFa\' appello al tuo coraggio, $R, e prega di avere la forza e la buona sorte di superare le prove che ti attendono.|n|nUn alleato inatteso ha chiamato tutti coloro che sono in grado di udirlo. Immergi lo sguardo nelle Acque della Lungimiranza e contempla il destino del mondo!', },
    {'Nambria ti ha chiesto di scrutare le Acque della Lungimiranza.', },
  },
  [14447] = {
    'Il simile conosce il suo simile',
    nil,
    {'Il Razziatore dei Cieli Korm ti ha chiesto di parlare con Koltira Plasmamorte a bordo del Martello di Orgrim.', },
  },
  [14448] = {
    'Il simile conosce il suo simile',
    nil,
    {'Il Razziatore dei Cieli Korm ti ha chiesto di parlare con Koltira Plasmamorte a bordo del Martello di Orgrim.', },
  },
  [14449] = {
    'I primi passi',
    {'Ciò che vedi è opera dei Verrospino, giovane. Ogni anno invadono sempre di più il nostro villaggio. Il grande Cataclisma li ha scacciati dalle loro tane e si sono diffusi per tutta la terra come locuste e questi sono i risultati. Mia madre è morta a causa della loro ferocia.|n|nOggi entri nel mondo adulto. Oggi impugnerai le armi, combatterai per la tribù e vendicherai la Madre Anziana. Segui il sentiero che porta a est e trova mio figlio, Grull. Ti guiderà durante l\'attacco contro i Verrospino.', },
    {'Segui il sentiero che conduce a est fuori dal Campo Narache e trova Grull Vento Agile.', },
  },
  [14450] = {
    'Progressione di ritrovamento di oggetti casuali',
    {'Questa missione serve per testare la progressione di ritrovamento di oggetti casuali.', },
    {'Recupera 10 Meccanismi Progressivi.', },
  },
  [14451] = {
    'Probabilità di ritrovamento di oggetti casuali',
    {'Questa missione serve per testare la probabilità di ritrovamento di oggetti casuali.', },
    {'Recupera 10 Meccanismi Piatti.', },
  },
  [14452] = {
    nil,
    {'Guarda, $N. La presenza stessa dei Mantotergo è una piaga. Nulla resta dopo il loro passaggio tranne cadaveri e terra bruciata. Al Campo Narache potrebbe toccare la stessa sorte tra pochi giorni se non reagiamo.|n|nQuesto sarà il tuo Rituale della Forza, la prima cerimonia di un aspirante combattente Tauren. Inoltrati nel cuore di Spinairta e uccidi i Verrospino Mantotergo. Poi torna da me.', },
    {'Uccidi 6 Invasori Mantotergo.', },
  },
  [14455] = {
    'Fermate le Invocatrici delle Spine',
    {'Conoscere le abitudini delle prede è un altro aspetto della caccia. Nelle terre da cui provengono, i Mantotergo vivono al riparo di enormi radici spinose. Quando si spostano, le loro Sciamane piantano i semi e fanno crescere nuove radici in cui vivere.|n|nEsse sfigurano la terra e strangolano gli altri esseri, trasformando il territorio in una landa desolata. Vai a sud e ferma le Invocatrici delle Spine prima che possano continuare, $N.', },
    {'Uccidi 7 Invocatrici delle Spine Mantotergo.', },
  },
  [14456] = {
    'Il Rituale del Coraggio',
    {'Una delle prime lezioni che dovresti imparare, $N, è non sottovalutare mai la tua preda.|n|nMentre eravamo distratti dall\'attacco al Campo Narache, altri Mantotergo sono arrivati senza che ce ne accorgessimo e hanno rubato una cassa di archibugi. Ora li puoi vedere a sud, che fanno piovere piombo.|n|nQuesto è il tuo Rituale del Coraggio: coraggio di affrontare il fuoco degli archibugi, coraggio di dare la caccia ai ladri d\'armi Mantotergo e riportare indietro le nostre armi.', },
    {'Recupera 7 Archibugi Rubati dai Ladri d\'Armi Mantotergo.', },
  },
  [14457] = {
    'Il piano dei Predatori del Sole',
    {'Uno dei miei contatti nei Sotterranei ha visto un Agente dei Predatori del Sole che acquistava dei reagenti da un fornitore al Mercato Nero. Solitamente, i Predatori del Sole si disinteressano a ciò che accade nelle fogne, quindi sicuramente stanno pianificando qualcosa.|n|nScendi nei Sotterranei, trova questo Agente dei Predatori del Sole ed eliminalo. Esamina il suo cadavere in cerca di qualsiasi indizio sul luogo in cui si trova il Tomo della Lega dei Draghi. Non possiamo permettere che venga portato alla Corona di Ghiaccio.', },
    {'Recupera gli Ordini dei Predatori del Sole.', },
  },
  [14458] = {
    'Incontro con Adana',
    {'Abbiamo inferto un duro colpo ai Verrospino. Io resterò qui e difenderò la posizione, ma tu devi proseguire.|n|nCerca Adana Corno Tonante. Si è diretta verso sud-ovest con alcuni guerrieri per eliminare il resto dei Mantotergo.', },
    {'Raggiungi Adana Corno Tonante a sud-ovest.', },
  },
  [14459] = {
    nil,
    {'Ci sono altre minacce di cui devi occuparti. I Mantotergo stanno domando i cinghiali selvaggi per usarli contro di noi.|n|nI Cinghiali da Guerra hanno subito troppi abusi e devono essere soppressi, per la nostra sicurezza e la loro pace. Vai ai recinti a sud e uccidili, $N. Quindi, torna da me.', },
    {'Uccidi 10 Cinghiali da Guerra Corazzati.', },
  },
  [14460] = {
    'Il Rituale dell\'Onore',
    {'È il Capo Strillatore Mantoirsuto a guidare i Mantotergo. Fu lui a togliere la vita alla Madre Anziana Vento Agile e a condurre l\'attacco al Campo Narache. Dopo i suoi vili gesti è scappato e si è nascosto, ma l\'abbiamo trovato. È rintanato a ovest, nel suo malefico covo di spine, da dove respinge tutti i guerrieri che gli mandiamo contro.|n|nHai dimostrato grande coraggio nel difendere la nostra gente, $N. Uccidi Mantoirsuto e porta la sua criniera al Capo Vento Agile, in onore della Madre Anziana!', },
    {'Uccidi il Capo Strillatore Mantoirsuto e porta la sua criniera al Capo Vento Agile.', },
  },
  [14461] = {
    'Il cibo del male',
    {'Dobbiamo fare ben più che cacciare cinghiali. Dobbiamo eliminare la piaga che affligge la nostra terra.|n|nPer renderli assetati di sangue, ai cinghiali da guerra viene data carne cruda. Prendi questa torcia e usala per ridurre in cenere le mangiatoie e quanto contengono.', },
    {'Usa la Torcia di Adana per dare fuoco alle 3 Mangiatoie nei Recinti dei Cinghiali da Guerra.', },
  },
  [14462] = {
    'Dov\'è la mia testa?',
    {'$N, è qui! Il Capitano Grunwald è un ufficiale di alto rango dell\'Alleanza. Viene dalla Fortezza dei Custodi del Nord e senza dubbio è qui per coordinare un assalto contro Orgrimmar con i suoi alleati Elfi della Notte. L\'abbiamo visto entrare nella torre a sud-ovest di qui. Voglio la sua testa, $C. E voglio rispedirla ai Custodi del Nord per seminare il panico tra i nostri nemici!|n|nAvevo inviato alla torre una Goblin, l\'assassina Slinky Spadalesta, ma non è ancora tornata. Vai a cercarla. E portami quella testa!', },
    {'Hai ricevuto l\'incarico di trovare la Goblin assassina Slinky Spadalesta alla base della torre nord del Bivacco di Talrendis.', },
  },
  [14463] = {
    'Cavalli per Borgotetro',
    {'Quei cavalli potrebbero salvare il resto degli abitanti. Ci sono parecchi carri a Borgotetro ma poche bestie per trainarli.|n|nVai dal Sindaco Bracciofermo e dille che i cavalli che hai recuperato sono a sua disposizione.|n|nIo sistemerò le ultime cose qui e in breve tempo mi unirò a te.', },
    {'Parla con Gwen Bracciofermo a Borgotetro.', },
  },
  [14464] = {
    'Assassinio lampo',
    {'La base della torre è pattugliata dalle guardie d\'élite del Capitano. Questo è quello che faremo: ci arrampicheremo fino in cima, faremo a pezzettini il bersaglio e poi fuggiremo usando il mio paracadute portatile da bassa quota. Infine, faremo esplodere la torre grazie all\'esplosivo che avrò piazzato. Tu assicurati di recuperare la testa del Capitano Grunwald per Chawg. Tutto chiaro?|n|nNON accettare questa missione a meno che tu non sia pronto per una dose di BELLA E SANA VIOLENZA. Ripeto, è tutto chiaro?', },
    {'Parla con Slinky Spadalesta per arrampicarti sulla torre e assassinare il Capitano Grunwald. Ottieni la Testa di Grunwald.', },
  },
  [14465] = {
    'Al Maniero dei Mantogrigio',
    {'È il momento di metterci tutti in salvo, te $Gcompreso:compresa;, $N. Dirigiti al Maniero dei Mantogrigio, gli altri ti raggiungeranno a breve.|n|nNon preoccuparti per me... resterò qui per assicurarmi che tutti riescano ad andarsene sani e salvi. Sì, anche quelle poche bestie che abbiamo nei recinti.|n|nUna volta al maniero, informa la Regina Mantogrigio sulla gravità della situazione.', },
    {'Parla con la Regina Mia Mantogrigio nel Maniero dei Mantogrigio.', },
  },
  [14466] = {
    'L\'osservatorio del Re',
    {'Devi parlare con Genn. Si è chiuso nel suo osservatorio da quando è iniziata tutta questa faccenda.|n|nSono sicura che sta lavorando a un piano per la sua gente... è un uomo molto testardo.', },
    {'Parla con il Re Genn Mantogrigio nell\'osservatorio del Maniero dei Mantogrigio.', },
  },
  [14467] = {
    'Ahimè, Gilneas!',
    nil,
    nil,
  },
  [14468] = {
    'Un altro corpo caldo',
    {'Senti, ho un affare da proporti! Immergerti in una cultura esotica, prendere parte ad avventure leggendarie, far esplodere di tutto e venire anche $Gpagato:pagata; per farlo! Troppo bello per essere vero? Invece no, questo è proprio il nostro lavoro!|n|nSe la prospettiva ti pare interessante, recati alla Postazione Difensiva di Gallywix sulla Dorsale Tetra a nord e cerca il Comandante Molotov.', },
    {'Parla con il Comandante Molotov sulla Dorsale Tetra.', },
  },
  [14469] = {
    nil,
    {'Per prima cosa\'s prima - abbiamo bisogno di più rifornimenti per te e le altre nuove reclute. Ci sono alcuni pacchetti di problemi standard perfettamente validi sui corpi del nostro ultimo round di reclute, nel campo minato a nord. |n|nPer imparare a memoria le loro lezioni, ti consiglio di evitare di calpestare le mine da soli.', },
    {'Recupera 12 Rifornimenti Militari dal Campo Minato Centrale.', },
  },
  [14470] = {
    'Un\'arma speciale',
    {'Abbiamo perso i contatti con il Sergente Dynamo, che si trovava sulla dorsale a nord del Campo Minato Centrale. Probabilmente lui e i suoi sono stati sopraffatti.|n|nPurtroppo, con sé aveva il nostro ultimo Lanciarazzi Terra-Faccia. Vai laggiù e recuperalo. Già che ci sei, elimina tutti i Naga presenti sul posto.', },
    nil,
  },
  [14471] = {
    'Mortaio di primo grado',
    {'Ehilà! Ti piacciono le esplosioni? Ma certo che sì... a chi non piacciono le esplosioni?!?|n|nHo schierato dei mortai sulla dorsale a est per tenere a bada i Naga. Forza, recluta... dagli di mortaio! Dagli di mortaio su tutti loro! Ah ah ah ah!', },
    nil,
  },
  [14472] = {
    'In faccia!',
    {'I Naga si stanno servendo di quei giganti per aprirsi un varco attraverso i nostri campi minati. Mi sembra un ottimo momento per adoperare l\'LTF!|n|nRecati all\'ingresso del Campo Minato Meridionale. Il resto puoi immaginarlo anche da $Gsolo:sola;.', },
    {'Usa l\'LTF per uccidere un Figlio di Arkkoroc Schiavizzato nel Campo Minato Meridionale.', },
  },
  [14473] = {
    'Ora è un nostro problema',
    nil,
    {'Uccidi 6 Cuccioli di Teraptor.', },
  },
  [14474] = {
    'Capsule di salvataggio dei Goblin',
    {'$N, mi dispiace, ti credevo $Gmorto:morta;!|n|nÈ una follia. Siamo finiti nel mezzo di uno scontro tra l\'Alleanza e l\'Orda!|n|nI nostri fratelli e le nostre sorelle devono essere ancora salvati.|n|n<Indica tutte le capsule di salvataggio nell\'acqua intorno a voi.>|n|nCredo che starò ancora un po\' qui seduto a riprendere fiato. Puoi farti una nuotata e liberarli? Prendi le mie pinne termoidrate per spostarti più velocemente.|n|nDi\' a Sassy che arriverò presto.', },
    {'Salva 6 Sopravvissuti Goblin.', },
  },
  [14475] = {
    nil,
    {'$N, vedi queste Viverne dei Venti? Noti qualche problema? Be\', non stanno cavalcando il vento! Del resto, ogni volta che mi servo di una di loro, i cecchini degli Elfi della Notte la bersagliano.|n|nQuei cecchini si nascondono nella torre più a sud, quella con le montagne alle spalle. Avevo mandato uno di quei piccoli Goblin a occuparsi della torre, ma da allora non ho più avuto sue notizie. Trova il Capitano Bombarolo Fumonero e percuotilo col bastone della fretta!', },
    {'Trova il Capitano Bombarolo Fumonero nella torre elfica più a sud nel Bivacco di Talrendis.', },
  },
  [14476] = {
    'Pronto a esplodere',
    {'Questa torre era fuori dalla portata dei cannoni, così avevo pensato di farla saltare in aria all\'antica: di persona. Abbiamo già piazzato le cariche principali, ma le guardie ci hanno respinto prima che potessimo armare i detonatori.|n|n$N! Vai laggiù e arma i tre detonatori che abbiamo piazzato alla base della torre. Sono collegati a una pila di esplosivi che avevo piazzato su per tutta la verticale... Sarà uno spettacolo!', },
    {'Arma le 3 Cariche Esplosive situate alla base della torre più a sud nel Bivacco di Talrendis.', },
  },
  [14477] = {
    'Premi il pulsante!',
    {'Fammi controllare i collegamenti... e siamo pronti. A te l\'onore, $N. Premi, premi il pulsante!|n|nPremi il pulsante, $N!|n|nDopo i fuochi d\'artificio, torna da Kroum a Valormok e riferisci che i cieli adesso sono sgombri.|n|nPremi il pulsante!', },
    {'Fai detonare gli esplosivi!', },
  },
  [14478] = {
    'Operazione Sbudellapesce',
    {'Il Battaglione degli Acqualorda cerca nuove reclute per l\'OPERAZIONE SBUDELLAPESCE.|n|nLa paga consiste in un 1 moneta d\'oro, da pagarsi a tutti i soldati ancora vivi al termine dell\'operazione. In caso di morte, non si avrà diritto a nulla. Ogni risurrezione durante lo stato di servizio avrà un costo di 20 monete d\'argento.|n|nTutte le reclute devono fare rapporto direttamente al Comandante Molotov, sotto il cannone principale.', },
    {'Parla con il Comandante Molotov sotto il cannone principale del Porto degli Acqualorda.', },
  },
  [14479] = {
    'Ce ne sono tanti come lui',
    {'Basta chiacchiere. Datti una mossa e sali su un razzo, soldato.|n|nE ricorda: se ti ammazzano, non verrai pagato.', },
    {'Usa un razzo per raggiungere la Costa Infranta e poi fai rapporto al Tenente Drex.', },
  },
  [14480] = {
    nil,
    {'Il tuo compito è neutralizzare l\'infestazione di Naga. Sei $Gautorizzato:autorizzata; all\'utilizzo della forza letale.|n|nIn questa missione sarai $Gsupportato:supportata; dalla Squadra Gob, per cui dovrebbe essere una passeggiata.', },
    {'Uccidi 30 Naga Sferzarabbia nelle Rovine di Eldarath.', },
  },
  [14482] = {
    'Richiamo del dovere',
    {'$GCittadino:Cittadina;!|n|nForse saprai che l\'Orda sta attaccando al largo delle nostre coste. La lotta è violenta e senza quartiere.|n|nAbbiamo bisogno di tutte le braccia disponibili per respingere il nemico!|n|nPresentati subito al molo più a nord per essere $Gtrasportato:trasportata; in battaglia.|n|nAh, le nostre navi da guerra ufficiali sono, ehm... leggermente in ritardo sul rientro previsto. Ma non temere, nel mentre abbiamo predisposto dei vascelli mercenari.|n|nFai presto dunque, $C. Roccavento ha bisogno di te!', },
    {'Veleggia con la nave mercenaria fino alla battaglia.', },
  },
  [14483] = {
    'C\'è qualcosa nell\'aria (e non è amore)',
    {'All\'interno del biglietto sono scarabocchiati i dettagli di un folle piano per infettare la maggior parte di Azeroth. Mostralo immediatamente a un investigatore di Spargifumo!', },
    {'Consegna il Biglietto d\'Auguri Amoroso Sbiadito all\'Investigatore Snap Catenaccio di Orgrimmar.', },
  },
  [14484] = {
    'La testa del serpente',
    {'Al corso per ufficiali ci hanno insegnato che bisogna sempre tagliare la testa al serpente. Al tempo mi sembrava una stupidaggine, visto che non abbiamo mai combattuto contro dei serpenti, ma adesso credo di aver capito.|n|nAddentrati nel tempio con i tuoi uomini e uccidi Sire Kassarus.', },
    {'Uccidi Sire Kassarus nel Tempio di Zin-Malor.', },
  },
  [14485] = {
    'Serve Schiaffo',
    {'Schiaffo, il nostro miglior esperto di demolizioni, è attualmente all\'opera con la Squadra Gob. Con sé ha MOLTI più esplosivi di quelli necessari a far saltare tutte le Pietre Runiche presenti nelle rovine.|n|nTu non devi far altro che raggiungerlo e scortarlo. Lui farà il resto.', },
    {'Scorta Schiaffo nelle rovine e coprilo mentre piazza gli esplosivi vicino a 3 Pietre Runiche degli Sferzarabbia.', },
  },
  [14486] = {
    'Tavolette a peso d\'oro',
    {'Ehilà, $Gamico:amica;, vuoi guadagnare dei soldi facili?|n|nPortami tutte le Tavolette degli Alti Nobili che troverai nelle rovine.', },
    {'Recupera 12 Tavolette degli Alti Nobili dalle Rovine di Eldarath.', },
  },
  [14487] = {
    'Cuore ancor battente',
    {'Il Comandante Molotov ha trovato qualcuno del Laboratorio Segreto disposto ad acquistare il manufatto che hai individuato.|n|nSenza dubbio si trova ancora nel cuore delle rovine e in mano alla Gran Sacerdotessa, proprio dove l\'avevi localizzato l\'altra volta. Torna qui $Gtutto intero:tutta intera;, soldato.', },
    {'Ottieni il Cuore di Arkkoroc dal centro delle Rovine di Eldarath.', },
  },
  [14488] = {
    'Sei servito!',
    {'Finalmente ce l\'hai fatta. Bene, avevo proprio bisogno di una mano. Questo è il momento migliore per agire, giusto?|n|nPrendi questo corredo, entra e consegna i documenti a Hummel, il capo di quelle dannate industrie. Il biglietto è all\'interno, insieme a una cosetta per proteggerti da eventuali scherzetti chimici. Al momento giusto, usa un neutralizzatore. Chiaro?', },
    {'Consegna la Citazione in Giudizio allo Speziale Hummel nel Forte di Zannascura.', },
  },
  [14491] = {
    'L\'irrequieta terra',
    {'Poco tempo fa, un gruppo di Nani si era introdotto nelle nostre terre a ovest, squarciando insensatamente il terreno alla ricerca di tesori. Quando la terra stessa è stata fatta a pezzi, gli spiriti che la abitavano si sono adirati e si sono vendicati.|n|nGli Spiriti Agitati della Terra ora si aggirano nel luogo degli scavi, $N. Dobbiamo fare loro un\'offerta di pace.|n|nPrendi questo tamburo, dirigiti a ovest e suona per gli spiriti. Forse il ritmo calmerà la loro furia e la loro confusione.', },
    {'Usa il Tamburo della Terra Pacifica per calmare 6 Spiriti Agitati della Terra.', },
  },
  [20438] = {
    'Un buon travestimento',
    {'Farti entrare nel Santuario dei Predatori del Sole non sarà facile quanto sembra. L\'ingresso è consentito solo a coloro che possiedono le Insegne dei Predatori del Sole. Se riusciamo a recuperarne una, basterà un semplice incantesimo e il gioco sarà fatto.|n|nSulla balconata sopra i Fili del Fato, troverai Shandy Splendiluce: l\'ho aiutato così tante volte in passato, che mi deve un favore. Lava il bucato di molta gente in città: forse riesce a "prestarti" un\'insegna.', },
    {'Ottieni un\'Insegna in Prestito da Shandy Splendiluce.', },
  },
  [20439] = {
    'Appuntamento con il Magistro',
    {'Ho incantato l\'Insegna: ti permetterà di oltrepassare le difese del Santuario dei Predatori del Sole per un breve periodo. Dovresti avere tempo a sufficienza per entrare nella Belva Assetata e incontrare il contatto dei Predatori del Sole, un certo Magistro Hathorel.|n|nPrima che il travestimento svanisca, prendi la copia di Antiche Lame Forgiate dai Draghi ottenuta in prestito dalla Lega dei Draghi e portala da me.', },
    {'Recupera il tomo Antiche Lame Forgiate dai Draghi dal Magistro Hathorel.', },
  },
  [20440] = {
    nil,
    {'I nostri pozzi sacri sono stati avvelenati e mi serve il tuo aiuto per rimediare.|n|nPer purificare ogni pozzo, devo prima creare un totem purificatore. Devi quindi portarlo al pozzo ed eseguire il rituale di purificazione.|n|nPrima creeremo un totem purificatore per il Pozzo degli Zoccolo Artico. Per farlo, la terra dovrà darci il suo aiuto. Dai la caccia ai Lupi della Prateria per prendere le loro zampe e agli Zampalunga delle Pianure adulti per prendere i loro artigli. Si trovano a sud-ovest.|n|nTorna da me quando avrai zampe e artigli, $N.', },
    {'Recupera 6 Zampe di Lupo della Prateria e 4 Artigli di Zampalunga delle Pianure.', },
  },
  [20441] = {
    nil,
    {'Ancora una volta, assicurati di essere $Gpronto:pronta; a lasciarti alle spalle il Villaggio di Zoccolo Sanguinario, $N. Il tuo viaggio ti porterà molto lontano da qui.|n|nLa tua strada continua, oltre i campi di Mulgore. Gli occhi della Madre Terra sono sempre su di te. Quando vorrai partire, bevi l\'acqua vicino al falò tribale. Una volta ingerita l\'acqua sacra, i tuoi occhi si apriranno e gli spiriti ti guideranno.', },
    {'Bevi l\'Acqua della Visione di fronte al falò tribale al Villaggio di Zoccolo Sanguinario.', },
  },
  [23733] = {
    nil,
    {'Oggi hai superato un rito di passaggio molto più arduo di quelli a cui sottoponiamo i nostri giovani. Siine $Gfiero:fiera;. Ora, è giunto il momento che continui il tuo viaggio.|n|nA ovest, oltre il nostro sacro luogo di sepoltura, troverai un sentiero che si arrampica sulla mesa. Seguilo fino in cima e parla con Dyami Plana Vento.|n|nCammina con la Madre Terra. Ti accoglieremo sempre.', },
    {'Parla con Dyami Plana Vento in cima alla Mesa Sguardo Lungo.', },
  },
  [24215] = {
    'Il Rituale dei Venti',
    {'Guarda, $N. Le pianure ondulate di Mulgore si estendono davanti a te: la nostra casa, patria della Madre Terra. Qui ci fornisce tutto ciò di cui possiamo avere bisogno. È una terra pacifica e rigogliosa. Ecco cosa proteggi.|n|nIl tuo viaggio ti porterà lontano dalle sue braccia protettive, nelle regioni più remote e crudeli di questo mondo. E oltre.|n|nSotto di noi c\'è il Villaggio di Zoccolo Sanguinario. È giunto il momento di fare il primo passo sulla tua vera strada. Bevi l\'Acqua della Visione e lascia che gli spiriti ti guidino.', },
    nil,
  },
  [24216] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    nil,
    nil,
  },
  [24217] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    nil,
    nil,
  },
  [24218] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'Le Sentinelle Alargentea combattono per proteggere la foresta della Forra dei Cantaguerra. Le aiutiamo non perché siamo degli ecologisti, ma perché la foresta è una difesa naturale per il territorio dell\'Alleanza.|n|nMai come oggi hanno bisogno del nostro aiuto. Dobbiamo inviare subito rinforzi se non vogliamo che Valtetra venga annessa alle Savane!', },
    {'Vinci uno scontro sul campo di battaglia della Forra dei Cantaguerra e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24219] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'Le Sentinelle Alargentea combattono per proteggere la foresta della Forra dei Cantaguerra. Le aiutiamo non perché siamo degli ecologisti, ma perché la foresta è una difesa naturale per il territorio dell\'Alleanza.|n|nMai come oggi hanno bisogno del nostro aiuto. Dobbiamo inviare subito rinforzi se non vogliamo che Valtetra venga annessa alle Savane!', },
    {'Vinci uno scontro sul campo di battaglia della Forra dei Cantaguerra e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24220] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'$GRagazzo:Ragazza;, la maggiore difficoltà di combattere su più fronti è il rischio di disperdere troppo le nostre forze, rischiando di trovarci poi senza!|n|nÈ vitale decidere giornalmente il posizionamento delle truppe più importanti. Oggi c\'è bisogno di rinforzi nel Bacino d\'Arathi.|n|nTorna da me con la notizia della nostra vittoria, $N. Non possiamo permettere che quelle risorse preziose finiscano nelle mani dell\'Orda. Ci appartengono di diritto!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24221] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'Il Bacino d\'Arathi sta per essere conquistato dall\'Alleanza. Dobbiamo inviare immediatamente rinforzi o tutti i nostri sforzi saranno stati vani.|n|nNon indugiare, $C, e vai nel Bacino d\'Arathi per affrontare il nemico. Vittoria all\'Orda!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24222] = {
    nil,
    {'Affronteremo e schiacceremo i nemici ovunque li incontreremo. Sia Azeroth o le Terre Esterne, non fa alcuna differenza.|n|nNon possiamo permettere all\'Alleanza di sopravanzarci nell\'Occhio del Ciclone. Vai ad affrontarli oggi, perché domani potrebbe essere troppo tardi!', },
    {'Vinci uno scontro sul campo di battaglia dell\'Occhio del Ciclone e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24223] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'$GRagazzo:Ragazza;, la maggiore difficoltà di combattere su più fronti è il rischio di disperdere troppo le nostre forze, rischiando di trovarci poi senza!|n|nÈ vitale decidere giornalmente il posizionamento delle truppe più importanti. Oggi c\'è bisogno di rinforzi nel Bacino d\'Arathi.|n|nTorna da me con la notizia della nostra vittoria, $N. Non possiamo permettere che quelle risorse preziose finiscano nelle mani dell\'Orda. Ci appartengono di diritto!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24224] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    {'Le Sentinelle Alargentea combattono per proteggere la foresta della Forra dei Cantaguerra. Le aiutiamo non perché siamo degli ecologisti, ma perché la foresta è una difesa naturale per il territorio dell\'Alleanza.|n|nMai come oggi hanno bisogno del nostro aiuto. Dobbiamo inviare subito rinforzi se non vogliamo che Valtetra venga annessa alle Savane!', },
    {'Vinci uno scontro sul campo di battaglia della Forra dei Cantaguerra e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24225] = {
    'Chiamata alle armi: Forra dei Cantaguerra',
    nil,
    nil,
  },
  [24226] = {
    'Chiamata alle armi: Bacino d\'Arathi',
    {'Il Bacino d\'Arathi sta per essere conquistato dall\'Alleanza. Dobbiamo inviare immediatamente rinforzi o tutti i nostri sforzi saranno stati vani.|n|nNon indugiare, $C, e vai nel Bacino d\'Arathi per affrontare il nemico. Vittoria all\'Orda!', },
    {'Vinci uno scontro sul campo di battaglia del Bacino d\'Arathi e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24227] = {
    nil,
    {'La battaglia contro l\'Orda prosegue senza quartiere, $N. Le dispute territoriali e i vecchi rancori bastano per far scoppiare la guerra anche nelle Terre Esterne.|n|nVai nell\'Occhio del Ciclone e combatti per far prevalere anche qui l\'Alleanza.', },
    {'Vinci uno scontro sul campo di battaglia nell\'Occhio del Ciclone e torna dal Brigadier Generale dell\'Alleanza in una qualsiasi delle capitali dell\'Alleanza, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24426] = {
    'Chiamata alle armi: Valle d\'Alterac',
    {'Siamo quasi riusciti a cacciare gli invasori Piccatonante dalla Valle d\'Alterac e stiamo inviando rinforzi per aiutare il Clan Lupi Bianchi.|n|nUna vittoria campale ci aiuterebbe a ottenere le risorse di cui abbiamo bisogno per distruggere l\'Alleanza su tutti gli altri fronti.|n|nVai, $N, e fatti onore rispondendo alla chiamata dei coraggiosi Guerrieri dei Lupi Bianchi.', },
    {'Vinci uno scontro sul campo di battaglia della Valle d\'Alterac e torna dall\'Araldo della Guerra dell\'Orda in una qualsiasi delle capitali dell\'Orda, a Lungoinverno, Dalaran o Shattrath.', },
  },
  [24427] = {
    'Chiamata alle armi: Valle d\'Alterac',
    nil,
    nil,
  },
  [24428] = {
    'Un evento sconcertante',
    {'<Hai compiuto l\'impossibile. La Madre della Stirpe dei Draghi Neri giace morta ai tuoi piedi. Tagliale la testa e consegnala a Zardeth Graffionero.>', },
    {'Porta la Testa di Onyxia a Zardeth Graffionero nella cantina dell\'Agnello Sgozzato.', },
  },
  [24429] = {
    'Un evento sconcertante',
    nil,
    nil,
  },
  [24430] = {
    'Annerire i cieli',
    {'$N! Vuoi darci una mano? Il nostro Gorsch ha avuto una brutta esperienza in uno di quei posti in cui si può mangiare pesce a volontà a prezzo fisso, e ora siamo a corto di un pilota.|n|nIl mio compito è quello di eliminare quei Lancialame Elfici prima che possano decimare le nostre unità aeree. Salta a bordo di questa Viverna dei Venti e decolla! Con te verrà uno dei miei amici bombaroli che colpirà i bersagli al tuo comando.|n|nAh, e lancia una bomba sul Centro di Comando elfico, il grande edificio a sud di qui, accanto al ponte. Sarà fantastico!', },
    {'Sali a bordo di una Viverna dei Venti a Terra e vola verso il Bivacco di Talrendis. Distruggi 6 Lancialame di Talrendis e bombarda il Centro di Comando.', },
  },
  [24431] = {
    'Ricetta Fradicia',
    {'<Questi sembrano essere i resti di una mistura per un potente vino. Forse la proprietaria di Alla Salute a Dalaran potrebbe esservi interessata...>', },
    {'Porta la Ricetta Fradicia a Christi Stockton nella città di Dalaran.', },
  },
  [24432] = {
    'Piede marino',
    {'$GBenvenuto:Benvenuta; alla Lancia Salmastra, $C.|n|nIl mio nome è Erunak, l\'unico passeggero sopravvissuto di questo fiero vascello.|n|nMi duole, ma i tuoi travagli sono appena all\'inizio. I Naga ci attaccano senza tregua.|n|nNon hai l\'equipaggiamento appropriato per essere d\'aiuto, ma posso fare qualcosa per rimediare.|n|nSubito fuori da questa nave vive una razza speciale di stelle di mare. Portamene qualche esemplare insieme a una conchiglia. Preparerò un incantesimo che dovrebbe aiutarti a restare in vita.', },
    {'Erunak, alla Lancia Salmastra, ti ha chiesto di portargli tre Stelle di Mare e una Conchiglia dalla Tomba dei Marinai.', },
  },
  [24433] = {
    'Il ruolo del terrore',
    {'I nostri guerrieri sono forti, ma non hanno iniziativa. Adesso sono impegnati a combattere in prima linea, senza possibilità di avanzare. Ma un individuo singolo come te, $C, potrebbe scivolare dietro le linee avversarie e seminare il caos nel cuore dell\'avamposto nemico.|n|nLascia una scia di morte nel cuore di Talrendis, $N! Uccidi i nostri nemici in un territorio che ritengono sicuro, seminando distruzione e panico.', },
    {'Apriti un varco fino al Bivacco di Talrendis, uccidendo 12 Difensori di Talrendis e 6 Sentinelle di Talrendis.', },
  },
  [24434] = {
    'Commando in arrivo',
    {'$N, sei sensibile alle scosse lungo le linee di faglia locali? Io ogni tanto riesco a sentire un piccolo rumore, come lo strimpellare di una corda. Proprio il tipo di risonanza che ci si potrebbe aspettare da un incantesimo di evocazione a lungo raggio. Le storiche di Talrendis, con la loro risibile, primitiva magia, stanno cercando di evocare rinforzi da Darnassus.|n|nNoi possiamo volgere la situazione a nostro vantaggio. $N, se riuscissi a compromettere la loro Pietra d\'Evocazione, potremmo teletrasportare una squadra di commando specializzati proprio dietro le linee nemiche.|n|nTrova la Pietra d\'Evocazione a Talrendis!', },
    {'Uccidi 5 Storiche di Talrendis e trova la loro Pietra d\'Evocazione all\'interno del Bivacco di Talrendis.', },
  },
  [24435] = {
    'Pulizia della spiaggia',
    nil,
    {'Uccidi 12 Naga Sferzarabbia sulla Costa Infranta.', },
  },
  [24436] = {
    'Sacerdoti parà',
    {'Abbiamo un mucchio di "soldati" sparsi per tutta la spiaggia che muoiono pur di non lavorare. Trova quegli scansafatiche e usa la Spararazzi per chiedere l\'intervento di un Sacerdote che si occupi di loro.|n|nNon possiamo lasciar credere ai nostri uomini che sia così facile sfuggire al dovere.', },
    {'Richiedi l\'intervento dei Sacerdoti Aviotrasportati per salvare 8 Soldati Feriti sulla Costa Infranta.', },
  },
  [24437] = {
    'Chi primo arriva, meglio alloggia',
    {'Lungo la costa vi sono delle aree davvero meravigliose. Potrei rivenderle a 10 volte il prezzo che spenderei per edificarle.|n|nI punti migliori sono rappresentati dalla Pagoda dei Naga a sud, dalla torre proprio sulla riva e dalle rovine all\'estremità nord della spiaggia. Se li rivendicherai per conto mio prima della conclusione della battaglia, ti pagherò in moneta sonante.', },
    {'Pianta la Bandiera di Rivendicazione Territoriale di Ruckus nei pressi delle migliori aree edificabili della Costa Infranta.', },
  },
  [24438] = {
    nil,
    {'Non abbiamo altra scelta, $N. Dobbiamo spingerci oltre verso l\'interno.|n|nL\'idea non mi piace affatto, ma qui siamo vulnerabili.|n|nTorna alle stalle sotto al maniero. Fai salire tutti sui carri e dirigili verso est. Spero solo che non sia troppo tardi.', },
    {'Sali su una carrozza sotto al Maniero dei Mantogrigio.', },
  },
  [24439] = {
    'La conquista di Azshara',
    {'$N! Sei $Gstato:stata; tu a pilotare la Viverna dei Venti che ha bombardato il Centro di Comando? L\'hai centrato in pieno!|n|nI miei esploratori mi hanno riferito che hai gravemente ferito Jarrodenus, Maestro di Volo dei Predacielo elfici e comandante de facto dei nostri avversari.|n|nNon ho il tempo per organizzare un assalto su larga scala, dobbiamo sfruttare subito l\'opportunità di colpire. Corri al Centro di Comando e uccidi il Comandante Jarrodenus prima che arrivino i rinforzi. Portami la sua testa... e Azshara sarà nostra!', },
    {'Uccidi il Comandante Jarrodenus al Bivacco di Talrendis e prendi la sua testa.', },
  },
  [24440] = {
    nil,
    {'Ho creato il totem per purificare il Pozzo degli Zoccolo Artico. Ora, devi portarlo al pozzo ed eseguire il rituale di purificazione. Il pozzo si trova a sud-est, ma fai attenzione: chiunque l\'abbia avvelenato, potrebbe ancora trovarsi là.|n|nPotrebbe essere pericoloso, $N. Fai attenzione, ma non lasciare che i profanatori del pozzo scappino.', },
    {'Usa il Totem Purificatore degli Zoccolo Artico sul Pozzo degli Zoccolo Artico.', },
  },
  [24441] = {
    nil,
    {'C\'è altro lavoro da fare. Devo creare un nuovo totem per purificare il Pozzo dei Corno Tonante.|n|nDevi raccogliere gli artigli dei predatori delle pianure di Mulgore. Dai la caccia agli Inseguitori delle Praterie e ai Puma delle Pianure per prendere i loro artigli e poi torna da me.|n|nTroverai gli Inseguitori delle Praterie e i Puma delle Pianure a est e ovest.', },
    {'Recupera 6 Artigli di Inseguitore e 6 Artigli di Puma.', },
  },
  [24442] = {
    'I Piani di Battaglia dei Kvaldir',
    {'<Osservando i piani di battaglia rubati, scopri una mappa dei Regni Orientali e di Kalimdor: sopra, sono segnati gli insediamenti principali. Leggi gli ordini e apprendi che i Capitani dei Kvaldir hanno pianificato una serie di incursioni devastanti.>|n|n<L\'inizio è previsto dopo che Yngvar l\'Evocanebbie avrà "consultato il Cuore delle Nebbie". Rubando il presagio dalla Grotta dell\'Evocanebbie nella parte occidentale dell\'Approdo di Hrothgar, e facendolo sapere alla Giustiziera Mariel Cuorsincero, potresti riuscire a ritardare gli attacchi.>', },
    {'Recupera il Cuore delle Nebbie e portalo insieme ai Piani di Battaglia dei Kvaldir alla Giustiziera Mariel Cuorsincero nei Campi del Torneo d\'Argento.', },
  },
  [24448] = {
    'Promozione sul campo',
    {'Il Comandante Molotov ha deciso di inviarti al nostro avamposto. Stiamo preparando le squadre da inviare alle rovine per scacciare i Naga e recuperare il manufatto, e lui vorrebbe che tu ne guidassi una.|n|nRecati all\'estremità nordoccidentale della spiaggia e segui il sentiero fino all\'avamposto.', },
    {'Fai rapporto al Capitano Tork nell\'Avamposto nelle Rovine di Eldarath.', },
  },
  [24449] = {
    'In partenza',
    {'Ormai la situazione può dirsi sotto controllo. È stato davvero un piacere lavorare con te, soldato.|n|nSe sei $Gpronto:pronta; a trasportare il manufatto, c\'è un Girocottero pronto a riportarti al Porto degli Acqualorda. Così potrai consegnare il manufatto allo Zio Bedlam di persona.', },
    {'Porta il Cuore di Arkkoroc allo Zio Bedlam al Porto degli Acqualorda.', },
  },
  [24451] = {
    'A udienza dall\'Arcanista',
    {'Ho incantato l\'Insegna: ti permetterà di oltrepassare le difese dell\'Enclave d\'Argento per un breve periodo. Dovresti avere tempo a sufficienza per raggiungere il livello superiore e incontrare il contatto del Patto d\'Argento, un certo Arcanista Tybalin.|n|nPrima che il travestimento svanisca, prendi la copia di Antiche Lame Forgiate dai Draghi ottenuta in prestito dalla Lega dei Draghi e portala da me.', },
    {'Recupera il Tomo Antiche Lame Forgiate dai Draghi dall\'Arcanista Tybalin.', },
  },
  [24452] = {
    'Ricognizione a scopo di lucro',
    {'Le cose sembrano essersi calmate un poco. Probabilmente Gallywix continuerà a sganciare grana per tenerci qui, ma ho come la sensazione che dall\'accordo potremmo ricavare qualcosina in più.|n|nI Naga e i Giganti del Mare non sono mai stati amici, quindi i Naga devono averli in qualche modo sotto controllo. Prendi questo Generatore del Campo di Invisibilità, vai in quelle rovine e avvertimi se trovi qualcosa che ti sembra molto prezioso.', },
    {'Usa il Generatore del Campo di Invisibilità per introdurti nelle Rovine di Eldarath e trova il Cuore di Arkkoroc.', },
  },
  [24453] = {
    'Due chiacchiere in privato',
    {'Ascolta... ti chiedo un ultimo favore prima di lasciarti andare.|n|nIl Soldato Worcester si trova ancora alla torre a "reclutare". Vai da lui e digli che siamo pronti a partire. Torneremo a casa.|n|nÈ stato un piacere lavorare con te, recluta.', },
    {'Parla col Soldato Worcester allo Scambio della Razzovia di Orgrimmar.', },
  },
  [24454] = {
    'Torna da Caladis Lanciachiara',
    {'Dobbiamo portare immediatamente questo libro a Caladis Lanciachiara. Puoi pensarci tu? Non mi fido di nessun altro e hai dimostrato di saper tenere a bada i Predatori del Sole.|n|nPortalo alla Requie di Quel\'Delar, a sud dei Campi del Torneo d\'Argento nella Corona di Ghiaccio. Caladis e la spada ti attendono. Prima riusciremo a identificare la lama, prima potremo impossessarcene.', },
    {'Porta Antiche Lame Forgiate dai Draghi a Caladis Lanciachiara nella Requie di Quel\'Delar.', },
  },
  [24455] = {
    'Schieramento immediato',
    {'Entrerai in servizio attivo immediatamente. Il Capitano Desoto sta supervisionando lo schieramento delle truppe ai piedi della rampa alla Stazione di Lancio dei Razzi.|n|nRendici ricchi, soldato. Puoi andare!', },
    {'Recati dal Capitano Desoto del Porto degli Acqualorda per farti schierare.', },
  },
  [24456] = {
    nil,
    {'I Totem Truce sono una tribù che crede che Kalimdor debba appartenere solo ai Tauren. Odio e rabbia li hanno portati sulla corrotta via della sete di potere. Magatha, il loro capo, ha avvelenato il nostro Gran Capo Tribù, Cairne Zoccolo Sanguinario, e ha tentato di prendere per sé Picco del Tuono. Fu sconfitta e i Totem Truce esiliati.|n|nOra cercano di rovinare la stessa Mulgore perché sono stati scacciati. Presto, $N, devi andare al Pozzo dei Corno Tonante a nord ed eseguire il rituale!', },
    {'Usa il Totem Purificatore dei Corno Tonante sul Pozzo dei Corno Tonante.', },
  },
  [24457] = {
    nil,
    {'Non potrò mai ringraziarti abbastanza per aver purificato il pozzo della mia tribù, $N. E per aver affrontato i selvaggi Totem Truce per farlo. Ma non è ancora giunto il momento per te di riposare e ora il tuo viaggio deve portarti oltre il Villaggio di Zoccolo Sanguinario.|n|nZarlman Due Lune siede vicino al fuoco, al limitare settentrionale del villaggio. Parla con lui e scopri qual è il prossimo rituale che ti attende.', },
    {'Parla con Zarlman Due Lune al Villaggio di Zoccolo Sanguinario.', },
  },
  [24458] = {
    'Prova sul campo',
    {'$N, ho preso il campione di azsharite che hai recuperato dal laboratorio e l\'ho adattato a fini bellici. Se i miei calcoli sono corretti, la sua esplosione sarebbe in grado di radere al suolo un\'intera città.|n|nSe sono errati, potremmo spezzare il pianeta in due.|n|nBe\', l\'unico modo per scoprirlo è una prova sul campo! Consegna il Nucleo di Azsharite presso il cannone gigante ad Acqualorda e parla con Bleenik Cortinnesco. Il mio pilota da noleggio Friz Schiantobasso può darti un passaggio.|n|nIo ti seguirò... a distanza di sicurezza.', },
    {'Consegna il Nucleo di Azsharite Innescato a Bleenik Cortinnesco nel Porto degli Acqualorda. Parla con Friz Schiantobasso per farti dare un passaggio.', },
  },
  [24459] = {
    'Morin Bracca Nubi',
    {'Avrai sentito parlare della S.P.R. & Co. È un "cartello" di Goblin, qualcosa di simile a una tribù.|n|nMentre uno di questi cartelli si è unito all\'Orda, la S.P.R. & Co. è leale solo alla cupidigia. Già in passato quegli avidi Goblin e i loro impiegati hanno cercato di sfruttare le risorse di Mulgore, con scarsi risultati.|n|nUna delle nostre staffette, Morin Bracca Nubi, è andata a controllare i resti di una carovana dei Goblin. Se vuoi aiutarla, segui la strada orientale che conduce fuori dal villaggio.', },
    {'Trova Morin Bracca Nubi a est del Villaggio di Zoccolo Sanguinario.', },
  },
  [24461] = {
    'Riforgiare la spada',
    {'Non possiamo permettere che Quel\'Delar resti a pezzi. Prendi i resti della spada, insieme all\'Elsa Rovinata che hai trovato, e raggiungi la Fossa di Saron nella Rocca della Corona di Ghiaccio.|n|nAl suo interno, gli schiavi del Re dei Lich estraggono, lavorano e trasformano il Minerale di Saronite. È proprio il materiale che ci serve per ricostruire Quel\'Delar.|n|nRecupera delle Lingotti di Saronite Infusi e ruba il Martello del Mastro Forgiatore, poi porta tutto all\'Incudine del Mastro Forgiatore e riforgia la spada.', },
    {'Recupera 5 Lingotti di Saronite Infusi e il Martello del Mastro Forgiatore, poi usali per creare Quel\'Delar Riforgiata.', },
  },
  [24463] = {
    'Indagini a Valtetra',
    {'Anche se la feccia darnassiana si sta ritirando da Azshara, continuo a ricevere rapporti poco ottimisti dai miei predoni a Valtetra, a ovest di qui. Gli Elfi della Notte potrebbero tentare un assalto ai nostri territori nelle Savane.|n|n$C, voglio che oltrepassi il confine e parli con uno dei miei esploratori. Cerca Kulg Sputamorte. Dovrebbe trovarsi appena oltre il ponte, all\'estremità sudoccidentale del Bivacco di Talrendis. Scopri cosa sta accadendo in quei boschi!', },
    {'Parla con Kulg Sputamorte a Valtetra.', },
  },
  [24466] = {
    'Urlo di Battaglia',
    nil,
    nil,
  },
  [24467] = {
    'Dissolvenza in nero',
    {'Bisogna mettere fine a questa follia. Dobbiamo annientare lo Stormo dei Draghi Neri da Azshara prima che possano tornare con informazioni utili per il loro padrone.|n|nAncora non so che asso abbiano nella manica, per cui ho un ultimo favore da chiederti: vai a Cresta Fuligginosa e uccidi i loro capi, la Dama del Crepuscolo Katrana e Malicion.|n|nSe le cose si mettono male, verrò a darti una mano. Non voglio rischiare di cadere nella trappola che devono aver teso ad Azuregos.', },
    {'Uccidi la Dama del Crepuscolo Katrana e Malicion a Cresta Fuligginosa.', },
  },
  [24468] = {
    'Bloccati nell\'acquitrino',
    {'Gli Ogre hanno attaccato due delle nostre diligenze: questa qui e quella che è caduta nell\'acquitrino a nord.|n|nVoglio che tu vada là e porti in salvo i superstiti mentre noi pensiamo a un piano per liberarci di questi Ogre.', },
    {'Salva 5 Sopravvissuti all\'Impatto nell\'Acquitrino Legnomarcio.', },
  },
  [24469] = {
    'Difendi la posizione!',
    {'Ehi, tu, laggiù! Sembri fare al caso nostro, puoi darci una mano?|n|nPare che il grande terremoto di oggi abbia spinto un pugno di quei barbari Trogg a fuoriuscire dal terreno e pare anche che abbiano qualche motivo per essere così furiosi. I miei uomini stanno facendo il possibile per tenerli a bada, ma un aiuto ci tornerebbe comodo.|n|nFai la tua parte: recati a sud di qui e aiuta i miei Montanari a non finire in guai più grossi. Dobbiamo mantenere la posizione!', },
    {'Uccidi 6 Invasori Faucisalde.', },
  },
  [24470] = {
    'Puniamoli!',
    {'Bene, $N, ascolta. Io so un paio di cose sui Trogg e una di queste è che i Trogg più rispettati sono quelli più grossi e forti. Quei bruti considerano la forza al di sopra di ogni altra cosa.|n|nVedi quei grossi Trogg seduti al di là del fronte? Sono ciò che più di vicino hanno al nostro concetto di capi. Eliminane alcuni e fagli vedere cosa significa pestare i piedi ai figli di Forgiardente!', },
    {'Uccidi 3 Sgherri Faucisalde.', },
  },
  [24471] = {
    'Soccorso ai feriti',
    {'$N, ascolta! A differenza di Joren, io non ho bisogno della tua spada, quanto di una mano ferma e di un po\' di coraggio.|n|nI nostri Montanari sono addestrati per proteggere il villaggio dall\'occasionale attacco dei lupi... non da un\'invasione di Trogg in piena regola! Molti dei nostri migliori combattenti sono deboli e feriti, e mi serve il tuo aiuto per medicarli.|n|nTieni, prendi il mio Kit di Primo Soccorso e curane il più possibile.', },
    {'Usa il Kit di Primo Soccorso di Sten su 4 Montanari di Crestafredda Feriti.', },
  },
  [24472] = {
    'Il nemico infuriato',
    {'Abbiamo i Reietti alle calcagna, $N, e ora questi Ogre stanno cercando di circondarci.|n|nSono servitori dell\'Ettin Koroth, l\'essere più malvagio e distruttivo di tutta Gilneas.|n|nSe riusciamo a far sì che Koroth attacchi le prime linee dei Reietti, dovremmo coprirci la ritirata e guadagnare tempo.|n|nL\'unico modo per raggiungere il nostro scopo è far infuriare Koroth. Non basterà uccidere i suoi servitori... dobbiamo rubargli ciò a cui tiene di più: uno stendardo in pelle di tigre.', },
    {'Uccidi 4 Servitori Ogre e ruba lo Stendardo di Koroth nel Rifugio di Koroth.', },
  },
  [24473] = {
    'Tutti a Forgiamara',
    {'Apprezziamo il tuo aiuto da queste parti, ma forse ci sono posti in cui saresti più utile.|n|nA causa dell\'attacco dei Trogg e senza considerare quell\'ultima, terribile, scossa di terremoto, stiamo portando tutti i civili nella città di Forgiamara, sulla collina a nord-ovest.|n|nVai a parlare con mia moglie, Jona, a Forgiamara. Sono certo che avrà bisogno dell\'aiuto di una persona forte come te.', },
    {'Parla con Jona Ferrocaldo a Forgiamara.', },
  },
  [24474] = {
    'Prima di tutto: ci serve della birra',
    {'Non capisco come qualcuno possa anche solo ASPETTARSI che ci si metta al lavoro se non abbiamo un goccio di birra! Le scorte di birra qui a Forgiamara sono pericolosamente scarse.|n|nPer fortuna avevamo conservato alcuni barili per i casi di necessità. A ovest di Forgiamara, lungo il confine settentrionale della valle, troverai barili di Birra Scura della Tempesta e di Birra Chiara di Theramore. Appena a est di qui, invece, troverai scorte di Gnomenbrau, la mia preferita.', },
    {'Recupera un Barile di Birra Scura della Tempesta, un Barile di Birra Chiara di Theramore e un Barile di Gnomenbrau.', },
  },
  [24475] = {
    'Tutto il resto',
    {'Se dovremo restare bloccati qui dentro a lungo, avremo bisogno di cibo e di coperte per tenere al caldo i più piccoli. Ti dispiacerebbe uscire dalla città per recuperare delle scorte?|n|nScoprirai che la carne dei cinghiali più piccoli non è affatto male per un banchetto. Inoltre dovremo procurarci le pelli di giovani lupi.|n|nTutti questi animali li troverai ovunque, qui a Crestafredda.', },
    {'Ottieni 3 Cosciotti di Cinghiale e 4 Pelli di Lupo Stracciate.', },
  },
  [24476] = {
    'Temprando la lama',
    {'Finalmente, tutti i pezzi di Quel\'Delar sono riuniti e la spada è intera. Ciononostante, non potrai usarla in battaglia prima di averla temprata. Il filo di Saronite non è affilato, quindi è fragile. Si romperà al primo contatto con qualcosa.|n|nNelle profondità della Forgia delle Anime, all\'interno della Rocca della Corona, c\'è un posto in cui temperare le lame in tutta sicurezza. Porta Quel\'Delar alla dimora del Divoratore di Anime e cerca il Crogiolo. Immergi la lama al suo interno per temperarla, poi riportala da me nelle Sale Gelide.', },
    {'Tempra Quel\'Delar Riforgiata nel Crogiolo delle Anime.', },
  },
  [24477] = {
    'Manufatti nanici',
    {'$N, $Gfigliolo:figliola;! Ti interessa l\'archeologia?|n|nCi è giusto capitata un\'occasione d\'oro a due passi da qui. Le scosse dell\'evento sismico di ieri hanno disseppellito diversi manufatti tutt\'intorno al nostro accampamento. Perlustra il confine settentrionale della valle e dovresti trovare ogni sorta di tesori. Portamene qualcuno e forse potremo studiarli insieme.|n|nForza, allora! Vai!', },
    {'Recupera 5 Manufatti Nanici Dimenticati.', },
  },
  [24478] = {
    'La Prova del Gelo',
    {'Sai, alcuni miei apprendisti dicono che sono una persona molto fredda. Io però sostengo che non bisogna lasciare che la temperatura corporea ostacoli il proprio personale percorso di apprendimento.|n|nPer raggiungere la Prova del Gelo, tocca il Cristallo di Ghiaccio e si aprirà il portale. Una volta lì, lo scopo è semplice: raccogliere le piccole sfere di ghiaccio fluttuanti.|n|nA rendere le cose più interessanti ci pensa il Gelo Intenso. Se poi vuoi affrontare la prova con stile, puoi servirti delle trappole runiche per superarlo con un balzo. Elegante, no?', },
    {'Completa la Prova del Gelo raccogliendo 20 Essenze del Ghiaccio senza farti colpire dal Gelo Intenso.', },
  },
  [24479] = {
    'La Prova dell\'Ombra',
    {'Perché farsi limitare dal repertorio magico dei maghi ordinari? Io, per esempio, non sono un classista. Anche la negromanzia può essere divertente!|n|nTocca il Cristallo d\'Ombra per aprire il portale e accedere alla Prova dell\'Ombra. Una volta lì, quando sei $Gpronto:pronta; per iniziare, recati all\'Altare.|n|nLe Anime Piangenti inizieranno a inseguirti... e il tuo obiettivo è semplicemente quello di attirarle nelle trappole. Stando $Gattento:attenta; a non farti toccare da loro...', },
    {'Completa la Prova dell\'Ombra attirando 20 Anime Piangenti nelle rune d\'ombra senza farti toccare.', },
  },
  [24480] = {
    'Sale dei Riflessi',
    {'Hai riforgiato e temprato la spada, eppure resta a riposo nel suo fodero... senza mostrare segni del potere che dovrebbe possedere. Dici di sentirti tirare, come se possedesse volontà propria?|n|nHai il coraggio di seguirla dove vuole andare? Non è normale che sia così silenziosa e insistente. Temo che, se non la porteremo alla destinazione che desidera, non scopriremo mai il motivo del suo strano comportamento. Portala nelle Sale dei Riflessi, nella Rocca della Corona di Ghiaccio, ma fa\' attenzione! Io ti attenderò nelle Sale Gelide.', },
    {'Porta Quel\'Delar Temperata all\'Altare della Spada nelle Sale dei Riflessi.', },
  },
  [24482] = {
    'Parola del Potere: Fermezza',
    nil,
    nil,
  },
  [24483] = {
    nil,
    {'I nostri cocchieri hanno ricevuto l\'ordine di raggrupparsi nel villaggio di pescatori di Valtempesta. Secondo i nostri esploratori, lì ci sarebbero riparo e provviste.|n|nRaggiungi Valtempesta e cerca Gwen Bracciofermo, che si prenderà cura della nostra gente.', },
    {'Parla con Gwen Bracciofermo a Valtempesta.', },
  },
  [24484] = {
    'Disinfestazione',
    {'In tutto questo tempo Valtempesta è rimasta pressoché intatta. Chi l\'avrebbe mai detto, $N?|n|nPeccato che i Reietti stiano ancora avanzando nell\'entroterra. A ogni modo, questo posto ci permetterà di riposarci per una notte o due.|n|nL\'altra parte del villaggio è infestata dai ragni, dunque ho chiesto agli abitanti di tenersi alla larga da lì.|n|nTi andrebbe di darci una mano a ripulire la zona? Sono sicura che i nostri feriti dormirebbero più tranquilli sapendo che qualcuno sta tenendo a bada quelle bestie a otto zampe.', },
    {'Uccidi 6 Ragni Saltatori Stirpevile a Valtempesta.', },
  },
  [24485] = {
    nil,
    {'Io sono un apprendista me stesso, $N, ma posso ancora darti una lezione per ringraziarti. |n |nAmmi a insegnarti come riempirti con la luce di An \' lei, e abbatti i tuoi nemici con', },
    nil,
  },
  [24486] = {
    'Approfittane finché sei in tempo',
    {'Il villaggio dei Trogg a sud-ovest ha subito danni comparabili ai nostri. Logica vorrebbe, perciò, che dal suolo siano emersi antichi manufatti dei Trogg, come è accaduto per noi!|n|nPurtroppo, pare che la maggior parte di essi sia già stata recuperata da loro. Ti prego, prova a portarmene qualcuno! Che tu ci creda o no, conoscendo meglio i Trogg, potremmo finire col conoscere meglio anche i potenti Nani!', },
    {'Recupera 5 Manufatti Inestimabili dei Faucisalde dai Saprofagi Faucisalde.', },
  },
  [24487] = {
    'Barbabianca ha bisogno di te',
    {'Qui ci hai reso dei grandi servizi, ma temo di dover rinunciare a te.|n|nUn mio caro amico, Grelin Barbabianca, mi ha detto che ha bisogno di rinforzi vicino agli accampamenti dei Troll a sud-ovest. Segui la strada a ovest e dovresti trovarlo facilmente.|n|nAbbi cura di te, $N. I Trogg possono essere seccanti, ma i Troll sono sicuramente peggio.', },
    {'Fai rapporto a Grelin Barbabianca presso il suo accampamento nella Valle Crestafredda.', },
  },
  [24488] = {
    'Le riserve',
    {'Ho tutti i giocatori infortunati! I nostri Segatronchi sono tutti kaput! L\'arbitro sta per dare il via alla partita!|n|nIl tempo stringe e ho bisogno di te!!!|n|nRimettiamo in sesto uno di quei Segatronchi: ci sono pezzi di ricambio sparsi per tutto l\'Attracco degli Acqualorda. Qualsiasi Kezaniano degno di questo nome te li donerà volentieri, se potrà aiutare i Bucanieri a vincere.|n|nInsegneremo a quei buoni a nulla degli Squali degli Spargifumo come si gioca a calciobomba!', },
    {'Recupera 6 Pezzi di Ricambio.', },
  },
  [24489] = {
    'Informazioni sui Troll',
    {'Tutti sanno che non so leggere bene le espressioni facciali dei Troll. Tuttavia, questi Troll non mi sembrano furiosi... mi sembrano confusi, forse un po\' spaventati.|n|n$N, qui è successo qualcosa di strano. Io dico di condurre qualche indagine, prima di uccidere ogni Troll a vista.|n|nIn questa zona ci sono tre accampamenti di Troll: uno a sud-est, uno a sud-ovest e uno a ovest. Ogni accampamento ha il suo Indovino... prova ad avvicinarti quel tanto per capire cosa dicono.', },
    {'Resta vicino a un Indovino Mantogelido in ciascuno degli accampamenti dei Mantogelido e ascolta ciò che ha da dire.', },
  },
  [24490] = {
    'Un viaggio a Forgiardente',
    {'La presenza di un Elementale del Fuoco qui a Crestafredda non è questione di poca importanza. Il terremoto ha prodotto effetti ben più gravi che disturbare un pugno di Trogg... ha cambiato il mondo tanto da lacerare il Piano Elementale. Dobbiamo inviare subito un rapporto a Forgiardente.|n|nChe ne dici di andarci tu? Non preoccuparti, sento che te la caverai benissimo. Parla con Hands Giraruota presso la galleria sul versante orientale della valle. Lui ti darà ogni indicazione necessaria.', },
    {'Fai rapporto a Hands Giraruota nella Valle Crestafredda.', },
  },
  [24491] = {
    'Segui quel Girocottero!',
    {'H-h-hai visto? Come ha fatto a crollare, quella caverna? Sei $Gstato fortunato:stata fortunata; a giungere qui al momento giusto e non un attimo prima.|n|nAnche se questi sviluppi rendono molto più facile il mio compito di sorveglianza dell\'ingresso della caverna, immagino che complicherà il tuo, se dovevi andare a Kharanos.|n|nEhi, aspetta, ho un\'idea! Non lontano da qui c\'è un Percorso Aereo degli Avieri di Gnomeregan! Manderò un segnale e loro non dovrebbero tardare a venire qui. Probabilmente atterreranno a Forgiamara.', },
    {'Fai rapporto a Milo Vitefitta vicino a Forgiamara.', },
  },
  [24492] = {
    'Preparare i bagagli',
    {'Il limite di peso sul mio Girocottero mi costringe a portare solo un passeggero. Che fortuna, $R!|n|nLa Nana Jona mi ha detto che la maggior parte dei tuoi effetti personali sono stati trasferiti a Forgiamara. Raccogli ciò che ti serve, sistema tutti gli affari in sospeso e torna da me quando sarai $Gpronto:pronta; a decollare.', },
    {'Recupera una Caraffa di Birra di Crestafredda, un Mantello di Pelliccia di Lupo Stracciata e della Carne di Cinghiale Avanzata.', },
  },
  [24493] = {
    'Non dimenticarti di noi',
    {'Stai partendo? Ricordati di fare scorta di provviste prima di andare.|n|nMa, soprattutto, una volta $Garrivato:arrivata; a Kharanos, parla con Tharek Rocciascura. Riferiscigli quanto è successo qui a Crestafredda e digli che non ci dispiacerebbe ricevere aiuti. Speriamo di ottenere qualcosa.', },
    {'Fai rapporto a Tharek Rocciascura nel villaggio di Kharanos.', },
  },
  [24494] = {
    'Runa Potenziata',
    nil,
    nil,
  },
  [24495] = {
    'Frammenti dal passato',
    {'Ho trovato il diario di un tizio di nome Bradshaw. Purtroppo mancano diverse pagine, soprattutto verso la fine.|n|nSe riuscissi a trovarne abbastanza potrei ricostruire ciò che è successo qui dopo che si è diffusa la Maledizione.|n|nChissà... magari gli abitanti di questo villaggio sono riusciti a fuggire. Forse ci sono ancora dei superstiti là fuori.|n|nForse mio padre è ancora vivo.', },
    {'Procurati 6 Pagine di Vecchio Diario.', },
  },
  [24496] = {
    'La Runa Arcana',
    {'$N, mi hanno consegnato questa runa per te. Non appena puoi, leggila con attenzione. Credo venga dall\'Istruttrice dei Maghi Teegli. Dalle un\'occhiata e poi vai a trovarla a Forgiamara.', },
    {'Leggi la Runa Arcana e parla con Teegli Merrowith nella Valle Crestafredda.', },
  },
  [24497] = {
    'Di nuovo in cielo',
    {'Abbiamo appena ricevuto un messaggio da Valormok. Dicono che non possiamo più inviare Cavalcavento in quella direzione, a meno che non vogliamo che vengano abbattuti dai Cecchini di Talrendis. Se vogliamo un passaggio sicuro per Valtetra, non possiamo rinunciare a Valormok. Dovremo perciò trovare una soluzione.|n|nI Sacerdoti Aviotrasportati si sono gentilmente offerti di portare qualcuno dei nostri a un\'altitudine fuori dalla portata dei cecchini. Recati nell\'area militare e prenota un posto su uno di quei voli. Raggiungerai Valormok $Gtutto intero:tutta intera; e con un po\' di fortuna potrai far tornare sicure le rotte dei nostri Cavalcavento.', },
    {'Prenota un posto per Valormok dai Sacerdoti Aviotrasportati nella zona orientale del Porto degli Acqualorda.', },
  },
  [24498] = {
    'La via per la Rocca',
    nil,
    {'Libera 15 Schiavi dell\'Alleanza e uccidi il Mastro Forgiatore Gargelo.', },
  },
  [24499] = {
    'Gli echi delle anime torturate',
    nil,
    {'Uccidi Bronjahm e il Divoratore di Anime per garantire l\'accesso alla Fossa di Saron.', },
  },
  [24501] = {
    'Paura dei ragni?',
    {'Il numero dei ragni continua ad aumentare in maniera preoccupante, $N. Dovrai andare nella loro tana e uccidere la madre della stirpe.|n|nAbbiamo individuato il ragno gigante noto come Rygna al confine di Bosconero, in una zona ricoperta da spesse ragnatele. È pericoloso, ma abbiamo tutti fiducia in te.', },
    {'Uccidi Rygna nella sua tana.', },
  },
  [24502] = {
    'Brutalità necessaria',
    {'C\'è rimasto un solo Segatronchi. Mentre nessuno mi guardava, l\'ho caricato con... diciamo delle Pallabombe modificate.|n|nDevi salire su quel Segatronchi e scatenare l\'inferno!', },
    {'Sali sul Bucaniere degli Acqualorda e lancia la Pallabomba contro 8 Squali degli Spargifumo.', },
  },
  [24503] = {
    'Dritto in porta',
    {'Dipende tutto da te. Hai devastato gli Squali degli Spargifumo, quindi non ti resta altro da fare che segnare il punto della vittoria.|n|nDetto fra noi, penso che dovremmo farlo come si deve. Non voglio che ti limiti a segnare... voglio che calci così lontano da raggiungere le due ciminiere dietro la porta!|n|nHo modificato la Pallabomba per fornirti la forza in più necessaria.|n|nRendimi orgoglioso!', },
    {'Segna il punto della vittoria, tirando la Pallabomba in mezzo alle due ciminiere dietro la porta avversaria.', },
  },
  [24504] = {
    'Libera l\'Altavia',
    {'Da questa parte, $C! Vedo che hai scoperto l\'Altavia.|n|nL\'Alleanza spera di bloccare i nostri collegamenti con Petrartiglio, ma dimentica che sono generazioni che cacciamo in queste terre. Conosciamo ogni tornante delle colline e ogni pista di caccia da qui a Millepicchi.|n|nMa affinché queste vie rimangano aperte, dobbiamo impedire agli Umani di mapparle.|n|nPattuglia il sentiero a est e uccidi qualunque Esploratore dell\'Altavia che trovi lungo la strada, poi parla con Tunawa Vento Calmo alla fine del sentiero.', },
    {'Uccidi 3 Esploratori dell\'Altavia.', },
  },
  [24505] = {
    'Resistenza al Colle del Cacciatore',
    {'Il Bastione dell\'Onore può esser stato perso, ma il suo spirito non è mai stato schiacciato. Anche adesso i sopravvissuti stanno resistendo in un presidio chiamato "Colle del Cacciatore".|n|nContinua a seguire l\'Altavia e più avanti troverai il nostro accampamento. Quando arrivi lì, parla con Onatay e informala che il sentiero, per ora, è ancora libero.', },
    {'Parla con Onatay al Colle del Cacciatore nelle Savane Meridionali.', },
  },
  [24506] = {
    'Nella Rocca del Gelo',
    {'$C! Presto, vieni qui: devo parlarti!|n|nLa mia regina, Dama Sylvanas Ventolesto, ha scoperto una breccia nelle difese della Rocca della Corona di Ghiaccio. Si trova in un posto chiamato "Forgia delle Anime". Prima di partire, mi ha chiesto di cercarle dei validi combattenti. Credo che tu possa fare al caso nostro.|n|n$C, raggiungila all\'entrata della Forgia.', },
    {'Entra nella Forgia delle Anime dal lato della Rocca della Corona di Ghiaccio e cerca Dama Sylvanas Ventolesto.', },
  },
  [24507] = {
    'La via per la Rocca',
    nil,
    {'Libera 15 Schiavi dell\'Orda e uccidi il Mastro Forgiatore Gargelo.', },
  },
  [24510] = {
    'Nella Rocca del Gelo',
    {'$C! Presto, vieni qui: devo parlarti!|n|nLa mia signora, Dama Jaina Marefiero, ha scoperto una breccia nelle difese della Rocca della Corona di Ghiaccio. Si trova in un posto chiamato la "Forgia delle Anime". Prima di partire, mi ha chiesto di trovare tutto l\'aiuto possibile... e io ho pensato subito a te.|n|nTi prego, corri a cercarla.', },
    {'Entra nella Forgia delle Anime dal lato della Rocca della Corona di Ghiaccio e cerca Dama Jaina Marefiero.', },
  },
  [24511] = {
    'Gli echi delle anime torturate',
    nil,
    {'Uccidi Bronjahm e il Divoratore di Anime per garantire l\'accesso alla Fossa di Saron.', },
  },
  [24512] = {
    'La redenzione dei guerrieri',
    {'Quelli che si sono arresi quando il Bastione dell\'Onore è caduto non sono più degni dell\'Orda, $C. Ma non voglio abbandonarli. La prigione della torre sotto di noi è poco controllata. Diamo a quei prigionieri un\'ultima possibilità di morire con onore.|n|nHo preparato delle funi che ti permetteranno di scalare e discendere rapidamente la montagna. Calati, prendi le armi confiscate e arma i prigionieri nella torre.|n|nE $N, resta vicino alla torre! Non siamo ancora equipaggiati per un attacco alla base.', },
    {'Recupera 5 Casse di Armi Confiscate dal Bastione dell\'Onore e riequipaggia 5 Prigionieri di Petrartiglio. Usa le funi nelle vicinanze per entrare e uscire rapidamente dall\'accampamento dell\'Alleanza.', },
  },
  [24513] = {
    'Occhio per occhio',
    {'Chi è là? Non hai il passo indolente di una guardia.|n|n$C, dici? Ancora prode e in libertà? Per me non c\'è speranza. Ho perso la vista e non posso più combattere.|n|nHo osato protestare quando il Capitano ha selvaggiamente pestato uno dei prigionieri. In risposta mi ha dato un calcio in testa. E un altro. E altri ancora. Fino ad accecarmi, $R.|n|nTroverai il Capitano Peake in cima alla sua torre. Se vuoi fare giustizia, portami i suoi occhi.|n|nSe non vuole darteli di sua spontanea volontà... fai quel che devi.', },
    {'Uccidi il Capitano Peake e porta i suoi Bulbi Oculari a Oltarg.', },
  },
  [24514] = {
    'Pezzi di raptor',
    {'Siamo sotto assedio, $C, e tra quel baratro e la minaccia dell\'Alleanza siamo a corto di provviste. Ma andiamo avanti con quello che abbiamo, come facciamo da sempre noi Tauren.|n|nIn mancanza di una forgia, un esperto conciatore può rinforzare e riparare le nostre armature danneggiate con pelli di buona qualità.|n|nQui sotto c\'è il territorio di caccia dei Raptor Zannaorrida. Non è facile ucciderli, anche per la durezza della loro spessa pelle. Cacciali, $N, e portami la loro pelle!', },
    {'Ottieni 8 Pelli di Zannaorrida dagli Zannaorrida Scattanti e dai Mietisauri Zannaorrida.', },
  },
  [24515] = {
    'Segni nel cielo',
    {'Volgi lo sguardo a sud-est. Vedi il fumo del fuoco da campo dell\'Accampamento Una\'fe?|n|nNeanche dieci minuti fa ho visto delle grandi nuvole di fumo bianco salire in cielo dal centro del campo. Era un vecchio segnale utilizzato dal mio villaggio per coordinare la caccia a grande distanza ma, questa volta, si trattava di una richiesta d\'aiuto.|n|n$N, mio fratello Makaba si è inoltrato in quella giungla innaturale. Ti prego, trovalo e assicurati che non sia nei guai.|n|nCi sono pochi sentieri: cerca le tende nelle terre selvagge.', },
    {'Viaggia fino all\'Accampamento Una\'fe nel Labirinto Verde delle Savane Meridionali e parla con Makaba Zoccolo Piatto.', },
  },
  [24517] = {
    'Terrorizzali',
    {'Vedi il sentiero sotto di noi, $N? Quello è il MIO sentiero. E se i cani dell\'Alleanza vogliono usarlo, faranno meglio a guardarsi le spalle.|n|nÈ il momento di agire! Uccidi i soldati del Bastione dell\'Onore e vediamo se non riusciamo a rimandarli di corsa alle loro mura.|n|nAssicurati di eliminare, almeno, uno dei loro ufficiali che pattugliano la strada. Devono capire che nessuno è al sicuro.', },
    {'Uccidi 8 Coscritti del Bastione dell\'Onore e un Ufficiale del Bastione dell\'Onore.', },
  },
  [24518] = {
    'Bassavia',
    {'<Questo mucchio di carte è stato trovato in una sacca di pelle nascosta sotto i vestiti dell\'ufficiale.>|n|n<Le mappe di battaglia della regione raffigurano il Bastione dell\'Onore, collegato a quella che sembra una grande strada in costruzione che attraversa tutte le Savane da Theramore. A quanto pare, l\'Alleanza vuole costruire una strada dalla costa direttamente nel cuore di Kalimdor!>|n|n<Kilrok Sanguemartello la deve vedere.>', },
    {'Consegna i Progetti Stradali a Kilrok Sanguemartello al Colle del Cacciatore nelle Savane Meridionali.', },
  },
  [24519] = {
    'Fermare l\'ispettore',
    {'Tutte queste mappe sono state disegnate dalla stessa mano esperta. Ho visto un ispettore degli Umani percorrere su e giù la strada tra la roccaforte e la giungla a est.|n|nPossiamo rovinare i loro piani trasformando questo ispettore in un esempio, $N.|n|n<Kilrok indica la firma sotto le mappe.>|n|nSecondo te che c\'è scritto? "Zykes"? Anche i nomi degli Umani sono deboli e insignificanti. Uccidilo.', },
    {'Trova e uccidi l\'ispettore Henry Zykes.', },
  },
  [24520] = {
    'Bisogna dare la buona notizia a Sassy',
    {'$N, mi piacerebbe festeggiare insieme a te, ma sembra che il drago abbia fatto un bel po\' di danni al vecchio monte Kajaro. Io... ehm... credo che prenderò le mie cose e salirò sulla prima nave che lascia l\'isola!|n|nComunque, credo che dovresti tornare al quartier generale e dire a Sassy che hai vinto lo scudetto di calciobomba per noi. Sono sicuro che anche lei vuole sapere del drago e del Monte Kajaro.|n|nBuona fortuna!', },
    {'Parla con Sassy Serrabullona nel Quartier Generale della SCK a Kezan.', },
  },
  [24521] = {
    nil,
    nil,
    {'Parla con l\'Allenatore Lippo nello Stadio di Kajaro a Kezan.', },
  },
  [24522] = {
    'In viaggio verso il Pozzo Solare',
    {'$N, porta Quel\'Delar al Pozzo Solare il prima possibile. Devi credere a Uther, quando afferma che non sarai in grado di controllare la lama fino a quando sarà sotto l\'influsso malvagio del Re dei Lich. Raggiungi l\'Isola di Quel\'Danas e cerca l\'entrata del Pozzo Solare: solo lì potrai purificare la spada.|n|nI guardiani del Pozzo Solare non ti lasceranno entrare: cerca Halduron Alachiara, che li starà ispezionando.', },
    {'Parla con Halduron Alachiara all\'entrata della Cittadella del Pozzo Solare sull\'Isola di Quel\'Danas.', },
  },
  [24523] = {
    nil,
    {'Resta solo un pozzo da purificare, che prende il nome dalla tribù Manto Selvaggio. Per purificarlo, la terra deve offrire i denti di un feroce predatore, il Lupo Alfa della Prateria. Cerca gli alfa a nord e torna da me quando la caccia sarà conclusa.|n|nGli alfa spesso si aggirano vicino alla base della nostra città, Picco del Tuono.', },
    {'Ottieni 4 Denti di Lupo Alfa dai Lupi Alfa della Prateria.', },
  },
  [24524] = {
    nil,
    {'Gli spiriti parlano della tua purificazione del Pozzo degli Zoccolo Artico e dei Corno Tonante, giovane $N. Il Totem dei Manto Selvaggio è pronto e il tuo ultimo incarico ti attende.|n|nIl Pozzo dei Manto Selvaggio si trova a nord di Picco del Tuono. Esegui il rituale! Cura la terra dai veleni dei Totem Truce! Che le acque scorrano nuovamente!', },
    {'Usa il Totem Purificatore dei Manto Selvaggio sul Pozzo dei Manto Selvaggio.', },
  },
  [24525] = {
    'Tenere a bada i cani',
    {'Non tutti coloro che sono fuggiti da Taurajo sono arrivati a Una\'fe, $N. Alcuni sono morti lungo la strada per via delle ferite riportate. Altri sono stati aggrediti da sciacalli Verrospino.|n|nMi occuperò dell\'ingrato compito di trovare e radunare i corpi. Ma c\'è qualcosa che puoi fare per me.|n|nI Saprofagi Zannaviolenta infestano le terre a sud di qui e profanano i cadaveri, banchettando con le viscere e strappando arti. Uccidine qualcuno, affinché io possa celebrare i riti funerari appropriati.', },
    {'Uccidi 6 Saprofagi Zannaviolenta.', },
  },
  [24526] = {
    'Riempire il libro di incantesimi',
    nil,
    nil,
  },
  [24527] = {
    'Il tuo percorso inizia da qui',
    nil,
    nil,
  },
  [24528] = {
    'Il potere della Luce',
    nil,
    nil,
  },
  [24529] = {
    'Situazione disperata',
    {'Quando i rifugiati sono scappati a nord di Taurajo, alcuni si sono separati al calare dell\'oscurità. Molti sono stati fatti prigionieri dai Verrospino di Mantotergo che hanno allestito accampamenti a ovest e a sud-ovest da qui.|n|nNon so cosa sperassero di ottenere i Verrospino rapendo i nostri rifugiati, ma hanno solo provocato la mia ira, e in cambio non avranno che vendetta.|n|nSalva i miei fratelli e le mie sorelle in trappola e uccidi i loro carcerieri per inviare un messaggio ai Verrospino.', },
    {'Salva 5 Rifugiati di Taurajo Ingabbiati e uccidi un totale di 8 tra Mistici delle Spine Mantotergo o Custodi di Spade.', },
  },
  [24530] = {
    'Vivere per cacciare',
    nil,
    nil,
  },
  [24533] = {
    'Le parole del potere',
    nil,
    nil,
  },
  [24534] = {
    'Parlare la loro lingua',
    {'I Verrospino stanno attaccando perché percepiscono debolezza. La forza è l\'unica lingua che comprendono. Quindi gli parleremo con la forza.|n|n<Makaba prende un grande corno dalla sua sacca.>|n|nÈ un metodo brutale, ma funzionerà. I capi dei Mantotergo utilizzano corni come questo per sfidarsi a vicenda per la supremazia.|n|n$N, voglio che sfidi a singolar tenzone il campione dei Mantotergo, Musoaguzzo. Sconfiggilo davanti ai suoi seguaci. Suona il corno nell\'Arena della Sfida dei Mantotergo a sud di qui.', },
    {'Suona il Corno della Sfida nell\'Arena della Sfida dei Mantotergo e sconfiggi Musoaguzzo in un duello a singolar tenzone.', },
  },
  [24535] = {
    'Thalorien Cercalba',
    {'$N, se davvero hai con te Quel\'Delar, forse posso farti accedere al Pozzo Solare. Se conosci la storia della lama, saprai che è stata brandita da Thalorien Cercalba per difendere il Pozzo Solare dal Flagello. Egli cadde in quella che ora si chiama Fenditura Morta, concedendo ai suoi uomini il tempo necessario per prepararsi. Troverai i suoi resti su quest\'isola, vicino al confine meridionale della Fenditura Morta. Va\' a visitarli: se il suo spirito ti concederà la sua benedizione, allora ti permetterò di accedere al Pozzo Solare.', },
    {'Visita i Resti di Thalorien Cercalba e ottieni da lui il permesso di usare Quel\'Delar.', },
  },
  [24536] = {
    'Qui qualcosa puzza',
    nil,
    {'Usa l\'Analizzatore d\'Aria di Catenaccio per esaminare l\'aria intorno a 6 Guardie molto profumate, poi torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24539] = {
    'L\'attacco delle piante',
    {'Questo accampamento è stato costruito ai margini di questa giungla, ed è già stato travolto dalla crescita delle piante. Qui sta succedendo qualcosa di innaturale!|n|nPrima ho fatto l\'errore di mandare alcuni dei rifugiati più robusti a raccogliere noci e bacche. Quelli che sono tornati hanno raccontato che le piante li hanno afferrati per le gambe o addirittura strappati da terra. Temo per quelli che non sono ancora tornati.|n|nTi prego, $C, salva i rifugiati intrappolati nel Labirinto Verde che circonda l\'accampamento.', },
    {'Salva 5 Rifugiati di Taurajo uccidendo le Piante Ghermitrici che li tengono in trappola.', },
  },
  [24540] = {
    'Danza di guerra',
    {'Alcuni vedono i membri del nostro popolo come giganti gentili, altri come nobili selvaggi. Non ci hanno mai visto combattere contro i nostri fratelli... Contro traditori appartenenti alla nostra razza.|n|nFummo pietosi con i Totem Truce mandandoli in esilio. Eppure, hanno sfregiato la loro stessa terra per colpire noi. Non saranno più tollerati a Mulgore.|n|nAbbiamo già inviato i nostri guerrieri per scacciarli dal Passo di Petrartiglio, a nord. Hai combattuto coraggiosamente contro i Totem Truce, $N; perciò, ti chiedo di unirti nuovamente alla battaglia. Vai e aiutaci a sferrare il colpo di grazia.', },
    {'Sconfiggi Orno Totem Truce al Passo di Petrartiglio.', },
  },
  [24541] = {
    'Furto di profumo',
    nil,
    {'Indossando il travestimento da corriere, raggiungi la scorta delle Industrie F.lli Corona fuori dalle porte di Orgrimmar. Consegna la cassa che ti lanceranno all\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24542] = {
    'Una strana fioritura',
    {'Il grande Arcidruido Naralex è di recente apparso qui nelle Savane. O è lui il responsabile di questo disastro, o sta cercando di risolvere la situazione. A ogni modo, dovresti cercare di parlare con lui prima che questa giungla soffochi il mondo intero! Si trova in un piccolo accampamento dei Tauren a sud-est.|n|nSarebbe utile se lungo la strada raccogliessi dei campioni da fargli esaminare. I germogli dei fiori più recenti gli faranno capire molte cose sugli ultimi mutamenti della giungla.', },
    {'Raccogli 10 Germogli di Fiori Insoliti dai Fiori Germoglianti nel Labirinto Verde.', },
  },
  [24543] = {
    'Una famiglia divisa',
    {'I bambini che vedi qui sono stati tutti salvati da Taurajo quando è iniziata la battaglia. Sto cercando di rintracciare i loro genitori.|n|nUno dei rifugiati che hai salvato dai Verrospino ha riconosciuto il bambino più forte come il figlio di Kirge e Mawre Corno Severo. Ha detto inoltre che Kirge era accampato ai Campi del Sangue, subito a nord di dove si è svolto il massacro di Taurajo.|n|nTi prego, $N, vai laggiù e di\' a Kirge Corno Severo che suo figlio è sano e salvo!', },
    {'Trova Kirge Corno Severo al Presidio Vendetta nelle Savane Meridionali.', },
  },
  [24545] = {
    'Il sacro e il corrotto',
    {'$R, ti chiedo di affrontare questa missione malvolentieri, poiché probabilmente terminerà con la tua morte.|n|nSe deciderai di ignorare le mie titubanze e di imbarcarti nell\'impresa, ti fornirò la conoscenza e le risorse per portarla a termine.|n|nDevi tornare nella Caverna di Gelidamina e recuperare il martello perduto di Arthas: Vendetta della Luce. Riforgiato con la Saronite e imbevuto nel sangue acido degli Abomini del Re dei Lich, costituirà le basi del nostro lavoro.', },
    {'Inserisci la Vendetta della Luce, 25 Pezzi di Saronite Primordiale, del Sangue Acido di Facciamarcia e del Sangue Acido di Panzaguasta nella Forgia delle Rune del Gran Signore Mograine dentro la Rocca della Corona di Ghiaccio.|n|nPuoi ottenere il Sangue Acido di Facciamarcia e il Sangue Acido di Panzaguasta solamente nella modalità da 25 giocatori della Rocca della Corona di Ghiaccio.', },
  },
  [24546] = {
    'Una riga nella polvere',
    {'L\'Alleanza sta seminando una scia di morte nelle Savane. Dobbiamo fermarla, o per noi sarà la fine.|n|nNei Campi del Sangue c\'è una serie di colline strategiche, segnalate con torri di legno e stendardi neutrali grigi. Dobbiamo conquistare e mantenere queste colline, se vogliamo avere una speranza di rallentare l\'avanzata dell\'Alleanza!|n|nCerca le torri a nord, est e sud di quello che resta di Taurajo. Conquista uno stendardo neutrale e difendi la collina dal contrattacco!', },
    {'Conquista una Collina Neutrale nei Campi del Sangue e difendila dal contrattacco dell\'Alleanza.', },
  },
  [24547] = {
    'Un banchetto di anime',
    nil,
    nil,
  },
  [24548] = {
    'Il trono frantumato',
    {'Un tempo, il trono del Re dei Lich era la sua prigione. Kil\'jaeden in persona ha creato il contenitore dei cristalli ghiacciati provenienti dalla Distorsione Fatua, al solo scopo di trattenere lo spirito vendicativo di Ner\'zhul.|n|nQuando Arthas ha colpito il cristallo con Gelidanima, ha liberato lo spirito di Ner\'zhul, permettendogli di fondersi con il suo. Le schegge scaturite da quel colpo si sono sparse per la Rocca.|n|nPer consolidare il potere della tua ascia, ho bisogno proprio di quelle schegge. Ora sono possedute solo dai servitori più potenti del Re dei Lich.', },
    {'Il Gran Signore Darion Mograine ti ha chiesto di recuperare 50 Schegge di Ombrogelo.|n|nLe schegge possono essere ottenuti solamente in modalità da 25 giocatori.', },
  },
  [24549] = {
    nil,
    nil,
    {'Il Gran Signore Darion Mograine ti ha chiesto di portargli la Lama dell\'Ombra.', },
  },
  [24550] = {
    'Viaggio a Picco del Tuono',
    {'I pozzi sono stati purificati e le acque di Mulgore sono nuovamente fresche e limpide. Ci hai salvato, ma hai scoperto gravi misfatti. Le azioni dei Totem Truce devono essere rese note.|n|nÈ giunto il momento che tu entri a Picco del Tuono, la nostra grande città in cima alla Mesa. Vai dal nostro capo, Baine Zoccolo Sanguinario, figlio di Cairne. Deve essere informato.', },
    {'Parla con Baine Zoccolo Sanguinario a Picco del Tuono.', },
  },
  [24551] = {
    'Il nuovo capo',
    {'Sotto la guida di Gar\'dul non siamo riusciti a difendere bene le Savane, $N. Garrosh ha mandato il Signore della Guerra Elsarossa per prendere in mano la situazione. È qui nell\'accampamento, e se vuoi fare una buona impressione, devi mostrare di avere iniziativa.|n|nVai a est, nei Campi del Sangue, e trova le unità di ricognizione dei Custodi del Nord. Se porterai al nuovo Signore della Guerra un mucchio dei loro distintivi di merito, la tua reputazione crescerà!', },
    {'Uccidi le pattuglie di Ricognitori dei Custodi del Nord e prendi 10 Distintivi di Merito di Theramore.', },
  },
  [24552] = {
    'Il fiero leone',
    {'Se vuoi vendetta contro i nostri invasori dell\'Alleanza, faresti bene a osservare i predatori più feroci delle Savane.|n|nI leoni che puntano la preda nell\'erba alta sono astuti, furtivi e potenti. Impara da loro e comprenderai che tipo di guerra dobbiamo combattere.|n|nCaccia le predatrici delle pianure e i fieracriniera, poi torna da me per parlare di ciò che hai appreso. Spesso potrai trovarli all\'ombra di grandi alberi.', },
    {'Uccidi una qualunque combinazione di 5 Predatrici delle Pianure o Fieracriniera delle Pianure.', },
  },
  [24553] = {
    'La purificazione di Quel\'Delar',
    {'Immergi Quel\'Delar Temprata nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
    {'Immergi Quel\'Delar Temprata nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24554] = {
    'L\'elsa rovinata',
    {'<Questa vecchia spada rovinata ha visto giorni migliori. Prima che l\'elsa fosse separata dalla lama, doveva essere una vera opera d\'arte.>|n|n<A giudicare dai simboli eleganti e dalle gemme esotiche che adornano l\'elsa, apparteneva a una persona importante. Sicuramente i Predatori del Sole saranno interessati al recupero di un manufatto del genere. Cerca uno dei loro rappresentanti alla Requie di Quel\'Delar, a sud dei Campi del Torneo d\'Argento.>', },
    {'Porta l\'Elsa Rovinata a Myralion Soleardente nella Requie di Quel\'Delar, a sud dei Campi del Torneo d\'Argento.', },
  },
  [24555] = {
    'La conoscenza dei draghi',
    {'Non c\'è dubbio: quest\'elsa appartiene a un\'arma antica e molto potente. Ma quale? Non riconosco questi segni, ma non siamo ancora in un vicolo cieco!|n|nKorialstrasz, meglio conosciuto come Krasus, è un amico di lunga data dei Quel\'dorei e del Kirin Tor. Grazie alla sua vasta conoscenza e alle risorse a sua disposizione, saprà sicuramente qualcosa. Sali in cima al Tempio della Lega dei Draghi e chiedi il suo aiuto, poi parla con il Magistro Hathorel nel Santuario dei Predatori del Sole di Dalaran.', },
    {'Parla con Krasus in cima al Tempio della Lega dei Draghi.', },
  },
  [24556] = {
    'Un buon travestimento',
    {'Farti entrare nell\'Enclave d\'Argento non sarà facile quanto sembra. L\'ingresso è consentito solo a coloro che possiedono le Insegne del Patto d\'Argento. Se riusciamo a recuperarne una, basterà un semplice incantesimo e il gioco sarà fatto.|n|nSulla balconata sopra i Fili del Fato, troverai Shandy Splendiluce: l\'ho aiutato alcune volte in passato e mi deve un favore. Lava il bucato di molta gente in città: forse riesce a "prestarti" un\'insegna.', },
    {'Ottieni un\'Insegna in Prestito da Shandy Splendiluce.', },
  },
  [24557] = {
    'Il piano del Patto d\'Argento',
    {'Uno dei miei contatti nei Sotterranei ha visto un Agente del Patto d\'Argento che raccoglieva informazioni nella taverna Canti e Incanti. Solitamente, i membri del Patto d\'Argento non frequentano le fogne, quindi sicuramente stanno pianificando qualcosa.|n|nScendi nei Sotterranei, trova questo Agente del Patto d\'Argento ed eliminalo. Esamina il suo cadavere in cerca di qualsiasi indizio sul luogo in cui si trova il Tomo della Lega dei Draghi. Non possiamo permettere che quegli ipocriti del Patto d\'Argento lo riportino alla Corona di Ghiaccio prima di noi.', },
    {'Recupera gli Ordini del Patto d\'Argento.', },
  },
  [24558] = {
    'Torna da Myralion Soleardente',
    {'Dobbiamo portare questo libro a Myralion Soleardente. Puoi pensarci tu? Non mi fido di nessun altro e hai dimostrato di saper sfuggire agli uomini del Patto d\'Argento.|n|nPortalo alla Requie di Quel\'Delar, a sud dei Campi del Torneo d\'Argento nella Corona di Ghiaccio. Myralion ti attende. Se riuscirà a identificare la lama, potremo impossessarcene nel nome di Aethas il Predatore del Sole e mostrare a Dalaran e all\'Alleanza che saremo noi a condurre la carica contro il Re dei Lich.', },
    {'Porta Antiche Lame Forgiate dai Draghi a Myralion Soleardente nella Requie di Quel\'Delar.', },
  },
  [24559] = {
    'Riforgiare la spada',
    {'Non possiamo permettere che Quel\'Delar resti a pezzi. Prendi i resti della spada, insieme all\'Elsa Rovinata che hai trovato, e raggiungi la Fossa di Saron nella Rocca della Corona di Ghiaccio.|n|nAl suo interno, gli schiavi del Re dei Lich estraggono, lavorano e trasformano il Minerale di Saronite. È proprio il materiale che ci serve per ricostruire Quel\'Delar.|n|nRecupera delle Lingotti di Saronite Infusi e ruba il Martello del Mastro Forgiatore, poi porta tutto all\'Incudine del Mastro Forgiatore e riforgia la spada.', },
    {'Recupera 5 Lingotti di Saronite Infusi e il Martello del Mastro Forgiatore, poi uniscili ai Resti di Quel\'Delar per creare Quel\'Delar Riforgiata.', },
  },
  [24560] = {
    'Temprando la lama',
    {'Finalmente, tutti i pezzi di Quel\'Delar sono riuniti e la spada è intera. Ciononostante, non potrai usarla in battaglia prima di averla temprata. Il filo di Saronite non è affilato, quindi è fragile. Si romperà al primo contatto con qualcosa.|n|nNelle profondità della Forgia delle Anime, all\'interno della Rocca della Corona, c\'è un posto in cui temperare le lame in tutta sicurezza. Porta Quel\'Delar alla dimora del Divoratore di Anime e cerca il Crogiolo. Immergi la lama al suo interno per temperarla, poi riportala da me. Ti aspetterò nelle Sale Gelide.', },
    {'Tempra Quel\'Delar Riforgiata nel Crogiolo delle Anime.', },
  },
  [24561] = {
    'Sale dei Riflessi',
    {'Hai riforgiato e temprato la spada, eppure resta a riposo nel suo fodero... come una spada normale. Dici di sentirti tirare, come se possedesse volontà propria?|n|nHai il coraggio di seguirla dove vuole andare? Non è normale che sia così silenziosa e insistente. Temo che, se non la porteremo alla destinazione che desidera, non scopriremo mai il motivo del suo strano comportamento. Portala nelle Sale dei Riflessi, nella Rocca della Corona di Ghiaccio, ma fa\' attenzione! Io ti attenderò nelle Sale Gelide.', },
    {'Porta Quel\'Delar all\'Altare della Spada nelle Sale dei Riflessi.', },
  },
  [24562] = {
    'In viaggio verso il Pozzo Solare',
    {'$N, porta Quel\'Delar al Pozzo Solare il prima possibile. Devi credere a Uther, quando afferma che non sarai in grado di controllare la lama, nel momento in cui sarà sotto l\'influsso malvagio del Re dei Lich. Raggiungi l\'Isola di Quel\'Danas e cerca l\'entrata del Pozzo Solare: solo lì potrai purificare la spada.|n|nI guardiani del Pozzo Solare tenteranno di fermarti. Presentati a Halduron Alachiara, che li starà ispezionando.', },
    {'Parla con Halduron Alachiara all\'entrata della Cittadella del Pozzo Solare sull\'Isola di Quel\'Danas.', },
  },
  [24563] = {
    'Thalorien Cercalba',
    {'Lavori con Myralion Soleardente, vero? Conosco un modo per mettere alla prova la spada.|n|nSe conosci la storia della lama, saprai che è stata brandita da Thalorien Cercalba per difendere il Pozzo Solare dal Flagello. Egli cadde in quella che ora si chiama Fenditura Morta, concedendo ai suoi uomini il tempo necessario per prepararsi. Troverai i suoi resti su quest\'isola, vicino al confine meridionale della Fenditura Morta. Va\' a visitarli: se il suo spirito ti concederà la sua benedizione, allora ti permetterò di accedere al Pozzo Solare.', },
    {'Visita i Resti di Thalorien Cercalba e ottieni da lui il permesso di usare Quel\'Delar.', },
  },
  [24564] = {
    'La purificazione di Quel\'Delar',
    {'$N, il Pozzo Solare e la fine dell\'esilio di Quel\'Delar ti attendono.|n|nAll\'interno, troverai il Gran Magistro Rommath e Lor\'themar Theron, Reggente di Quel\'Thalas. Non fidarti e non lasciarti intrappolare nei loro complotti politici.|n|nInvece, resta $Gconcentrato:concentrata; sulla tua missione. Parla con un Custode del Pozzo Solare per accedere al Pozzo Solare. Per completare la ricostruzione di Quel\'Delar, immergila nel Pozzo Solare. Poi, mostra la lama a Myralion Soleardente nella Requie di Quel\'Delar.', },
    {'Immergi Quel\'Delar Temprata nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24565] = {
    'Intervento biologico',
    {'Le energie scatenate qui hanno penetrato la fauna e la flora, trasformandole in qualcosa di potente e instabile. Se permettiamo loro di muoversi liberamente, distruggeranno l\'ecosistema esistente divorando le prede locali e allontanando le creature naturali più deboli.|n|nDevi uccidere la popolazione del Labirinto Verde. Torna quando hai finito.', },
    {'Uccidi 5 Zannaorrida Degeneri e 5 Zampalunga Degeneri delle Pianure.', },
  },
  [24566] = {
    'Trovare una soluzione',
    {'In base a quello che mi hai portato, forse abbiamo trovato una soluzione. Ho infuso di energie curative i semi di sferzavite.|n|nDovrebbe bastare il contatto con questi semi per trasferire alle creature del luogo abbastanza energia da eliminare l\'influenza corrotta.|n|nCerca di guarire i raptor e gli zampalunga mutati gettandovi sopra questi semi e poi torna a riferirmi il risultato.', },
    {'Usa i Semi Curativi su 6 Zannaorrida Degeneri o Zampalunga Degeneri delle Pianure e osserva i risultati.', },
  },
  [24567] = {
    nil,
    {'$N, l\'Allenatore Lippo ti sta cercando. È il capo della nostra intrepida squadra di calciobomba: i Bucanieri degli Acqualorda.|n|nDice che è in ballo lo scudetto e solo tu puoi portarlo a casa contro gli Squali degli Spargifumo!|n|nRaggiungi la città a ovest, non puoi mancare lo Stadio di Kajaro.|n|nUna stella del calciobomba... sarà un toccasana per la tua immagine!', },
    {'Parla con l\'Allenatore Lippo nello Stadio di Kajaro a Kezan.', },
  },
  [24569] = {
    nil,
    {'$N, hai dimostrato il tuo valore nei Campi del Sangue. Ma l\'Alleanza continua a minacciare i nostri amici Tauren.|n|nLe macchine d\'assedio fuori dalle porte di Mulgore sono come una lancia puntata sul nostro cuore. Voglio che ti rechi alle porte, a sud di qui, e togli di mezzo quelle macchine d\'assedio.|n|nTieni, usa queste Bombe Appiccicose, sono un dono dei nostri nuovi alleati Goblin. Hanno infilato della polvere esplosiva in quelli che sembrano... calzini ricoperti di grasso. Ma faranno il loro dovere.', },
    {'Distruggi 4 Macchine d\'Assedio dei Custodi del Nord alle Porte di Mulgore.', },
  },
  [24570] = {
    'Vipere da laboratorio',
    {'La corruzione che dilaga qui deve essere studiata se vogliamo trovare il modo di affrontarla.|n|nPer fortuna non tutte le creature sono mutate. I serpenti più piccoli bevono pochissima acqua e non mangiano piante, quindi la loro esposizione alle energie del luogo è stata minima. Ne hanno assorbita solo il tanto che è bastato a far loro cambiare colore.|n|nVai a prendere questi serpenti nel Labirinto Verde e portameli, così potremo scoprire cosa sta succedendo alle creature di questo luogo.', },
    {'Cattura 5 Vipere Indebolite.', },
  },
  [24571] = {
    'Semi di sferzavite',
    {'Deve esistere un modo per curare queste povere creature senza togliere loro la vita. Ho un\'idea, ma avrò bisogno del tuo aiuto, $C.|n|nLe sferzaviti che vagano qui hanno dei semi pieni dell\'energia primordiale di questo luogo. Portameli e vedremo se è possibile fare qualcosa.', },
    {'Ottieni 4 Semi Inquieti dalle Sferzaviti.', },
  },
  [24572] = {
    'Riprendere Taurajo',
    {'Fantastico lavoro alle porte, $N! L\'armata principale dell\'Alleanza sta battendo in ritirata. Ma non sono ancora soddisfatto.|n|nHanno saccheggiato Taurajo, che non era un semplice accampamento di cacciatori. Questa "Alleanza" finalmente si è rivelata per quella che è: una banda di macellai senza scrupoli.|n|nPersino ora, un gruppo di Umani si attarda a profanare i resti di Taurajo in cenere.|n|n<Elsarossa lancia un\'ascia a terra.>|n|nFalli soffrire.', },
    {'Uccidi 8 Saccheggiatori di Taurajo alle Rovine di Taurajo.', },
  },
  [24573] = {
    'Onore ai morti',
    {'Ora che la minaccia più immediata è stata sventata, puoi aiutarmi in un compito poco piacevole?|n|nNoi Tauren non seppelliamo i nostri morti, ma prepariamo il corpo affinché faccia ritorno agli elementi e lo poniamo nei nostri luoghi sacri di sepoltura. Coloro che sono stati uccisi nel massacro di Taurajo non hanno avuto un funerale, e temo che degli ignoranti soldati dell\'Alleanza brucino i loro corpi prima che vengano compiuti i riti appropriati.|n|n$N, porta questo totem a Taurajo e celebra i riti funebri per Krulmoo, Dranh, Yonada e Omusa. Loro... non ce l\'hanno fatta.', },
    {'Usa il Totem Funerario sui cadaveri di Krulmoo, Dranh, Yonada e Omusa alle Rovine di Taurajo.', },
  },
  [24574] = {
    'La raccolta del caos',
    {'Se davvero ho seminato il caos, ora è tempo di raccolta.|n|nLe erbacce lignee delle piante si aggirano nel corso d\'acqua infuso, $N. Sono una manifestazione diretta delle forze instabili che stanno mutando questa zona. Uccidine il più possibile, e forse potremmo riuscire a rallentare la diffusione del Labirinto Verde.|n|nE già che ci sei... fa\' attenzione a eventuali parti particolarmente corrotte. Se le trovi, portamele.', },
    {'Uccidi 5 Erbacce e trova un Cuore Orrendo.', },
  },
  [24575] = {
    'Il giorno della liberazione',
    {'Di recente abbiamo scoperto che gli abitanti di Pietrardente sono sopravvissuti ai danni causati dalla Maledizione.|n|nPurtroppo, il loro villaggio non è stato altrettanto fortunato durante l\'invasione dei Reietti.|n|nI Reietti hanno fatto prigionieri gli abitanti e li costringono a lavorare nella vicina miniera come schiavi.', },
    {'Libera 5 Abitanti Schiavizzati dentro la Miniera di Pietrardente.', },
  },
  [24576] = {
    'Una chiacchierata amichevole...',
    nil,
    nil,
  },
  [24577] = {
    'Ispezione a Forte Desolazione',
    {'Grazie a te la minaccia più immediata è stata sventata. Ma il mio lavoro qui alle Savane è appena cominciato.|n|nBastione dell\'Onore è stato conquistato e Taurajo saccheggiato mentre il Signore della Guerra Gar\'dul era a capo della regione. Il Capoguerra mi ha inviato qui a sistemare questo disastro.|n|nVorrei che mi precedessi a sud, a Forte Desolazione, e informassi Gar\'dul che è giunta l\'ora della resa dei conti.|n|nParla con me quando vuoi partire, e ti farò accompagnare dalla mia Avanguardia.', },
    {'Parla con il Signore della Guerra Elsarossa, poi vai a Forte Desolazione e informa che il Signore della Guerra Elsarossa sta arrivando.', },
  },
  [24578] = {
    'Bosconero',
    {'C\'è voluto un po\', ma alla fine credo di aver ricostruito ciò che è successo qui... almeno in parte.|n|nAlcuni abitanti di questo villaggio riuscirono a sopravvivere alla Maledizione e si unirono ad altri sulle montagne, nella Riva della Tempesta.|n|nPartirono tutti tranne il vecchio Bradshaw, l\'autore di questo diario. Egli si era accorto che gli attacchi dei Worgen erano cessati improvvisamente e aveva deciso di avventurarsi a Bosconero.|n|nA nord-est del villaggio c\'è un vecchio mulino abbandonato che Bradshaw elesse a sua dimora. Potrebbe contenere degli indizi.', },
    {'Ispeziona il Mulino di Bradshaw fuori da Valtempesta.', },
  },
  [24579] = {
    'Sartharion deve morire!',
    {'Sartharion, il Guardiano d\'Onice, veglia sulle uova dello Stormo dei Draghi del Crepuscolo. Si trova nel Santuario d\'Ossidiana, nella Stanza degli Aspetti, sotto il Tempio della Lega dei Draghi.|n|nIl Consiglio dei Sei ha decretato che Sartharion deve morire!', },
    {'Uccidi Sartharion.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24580] = {
    'Anub\'rekhan deve morire!',
    {'Anub\'rekhan, un tempo possente Signore dei Ragni dell\'Impero dei Nerubiani, è stato catturato e corrotto dal Re dei Lich in un non morto.|n|nDivenuto Signore delle Cripte, siede nel suo parlatorio nell\'Ala degli Aracnidi a Naxxramas, tessendo strategie per Kel\'Thuzad.|n|nIl Consiglio dei Sei ha decretato che Anub\'rekhan deve morire!', },
    {'Uccidi Anub\'rekhan.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24581] = {
    'Noth l\'Araldo della Piaga deve morire!',
    {'Noth l\'Araldo della Piaga, traditore e codardo! Secondo solo al Re dei Lich per il numero di anime Piagate!|n|nRecati subito a Naxxramas. Lo troverai nell\'Ala della Pestilenza, nascosto dietro i suoi servitori non morti.|n|nDistruggilo! Il Consiglio dei Sei ha decretato che Noth deve morire!', },
    {'Uccidi Noth l\'Araldo della Piaga.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24582] = {
    'L\'Istruttore Razuvious deve morire!',
    {'L\'Istruttore Razuvious si aggira soddisfatto per l\'Ala dei Combattenti di Naxxramas. Si dice che solo un Cavaliere della Morte addestrato da lui sarebbe in grado di resistere alla sua spada.|n|nTu e il tuo gruppo dimostrerete che non è vero.|n|nIl Consiglio dei Sei ha decretato che Razuvious deve morire!', },
    {'Uccidi l\'Istruttore Razuvious.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24583] = {
    'Pezzacarne deve morire!',
    {'Il cosiddetto "Avatar della Guerra", Pezzacarne, altro non è che un abominio. E sta mietendo molte vittime tra le nostre truppe a Dracombra.|n|nVoglio che raggruppi i tuoi compagni e ti avventuri nell\'Ala dei Costrutti a Naxxramas. Smontalo.|n|nIl Consiglio dei Sei ha decretato che Pezzacarne deve morire!', },
    {'Uccidi Pezzacarne.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24584] = {
    'Malygos deve morire!',
    {'Le nostre risorse scarseggiano. Malygos, il Plasmamagie, sta assorbendo tutta la magia del mondo, consolidandola nell\'Occhio dell\'Eternità. Senza magia, siamo condannati.|n|n$C, dobbiamo porre fine alla Guerra del Nexus. Il Consiglio dei Sei ha decretato che Malygos deve morire!', },
    {'Uccidi Malygos.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24585] = {
    'Il Leviatano delle Fiamme deve morire!',
    {'All\'interno dei Campi di Formazione si trova la prima linea di difesa di Ulduar: il Leviatano delle Fiamme.|n|nIl Kirin Tor ha fornito informazioni che sembrano indicare che questo macchinario creato dai Custodi sarà presto trasportato in un luogo non meglio precisato e liberato per portare distruzione tra i mortali di Azeroth.|n|nNon possiamo permetterlo. Il Consiglio dei Sei ha decretato che il Leviatano delle Fiamme deve morire!', },
    {'Uccidi il Leviatano delle Fiamme.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24586] = {
    'Scagliafusa deve morire!',
    nil,
    {'Uccidi Scagliafusa.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24587] = {
    'Il Maestro della Forgia Ignis deve morire!',
    {'Il Maestro della Forgia Ignis, il grande Gigante del Fuoco, lavora duramente nella Forgia Colossale di Ulduar. Dietro ordine di Loken, Ignis crea armi dal potere terrificante.|n|nIl Consiglio dei Sei ha decretato che Ignis deve morire!', },
    {'Uccidi il Maestro della Forgia Ignis.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24588] = {
    'Il Demolitore XT-002 deve morire!',
    {'Un altro strano costrutto di Mimiron, il Demolitore XT-002, crede di essere il figlio del Custode. Non farti ingannare dalla sua falsa innocenza. È una macchina di morte!|n|nLo troverai nel Cantiere di Demolizione di Ulduar. Il Consiglio dei Sei ha decretato che il Demolitore XT-002 deve morire!', },
    {'Uccidi Noth il Demolitore XT-002.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24589] = {
    'Sire Jaraxxus deve morire!',
    {'L\'Arcimago Timear ha previsto un orribile evento che sta per avvenire. Uno sciocco Gnomo Stregone sta per evocare accidentalmente un Signore Eredar della Legione Infuocata nel mezzo dell\'Ordalia dei Crociati.|n|n$C, dovrai essere là quando ciò accadrà. Se Sire Jaraxxus scappasse, aprirebbe un portale e la Legione Infuocata entrerebbe di nuovo nel nostro mondo.|n|nIl Consiglio dei Sei ha decretato che Sire Jaraxxus deve morire!', },
    {'Uccidi Sire Jaraxxus.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24590] = {
    'Sire Ossamorte deve morire!',
    {'Sire Ossamorte è il guardiano del Trono di Ghiaccio nella Sala della Spira. Creato dal Re dei Lich con le ossa di migliaia di avventurieri sconfitti, Ossamorte utilizza il potere del trono stesso.|n|nSe non distruggeremo questa Presenza d\'Ossa, non avremo speranze di prendere la Rocca della Corona di Ghiaccio.|n|nIl Consiglio dei Sei ha decretato che Sire Ossamorte deve morire!', },
    {'Uccidi Sire Ossamorte.|n|nQuesta missione può essere completata a qualsiasi livello di difficoltà o con un\'incursione di qualsiasi dimensione.', },
  },
  [24591] = {
    'Cambio di Gar\'dul',
    {'Quando arriva Elsarossa vorrei, uhm, parlarci in privato. Puoi accompagnarmi per assicurarti che la situazione sia sotto controllo? Questo Elsarossa è un... uhm... è una mina vagante.|n|n<Gar\'dul cerca di darsi un tono.>|n|nCi vediamo in cima alla torre nord e parleremo insieme con Elsarossa.', },
    {'Vai in cima alla torre nord di Forte Desolazione e aiuta il Signore della Guerra Elsarossa a "sollevare" Gar\'dul dal comando.', },
  },
  [24592] = {
    'Tradimento a Riva della Tempesta',
    {'Re Mantogrigio è stato fatto prigioniero da Ser Godfrey a Riva della Tempesta!|n|nÈ riuscito a convincere due signori dell\'est a seguire il suo piano. Quello sciocco crede di poter raggiungere un accordo con i Reietti consegnandogli Mantogrigio.|n|nAscoltami bene, $N. Dobbiamo risolvere questa faccenda con il minor spargimento di sangue possibile.|n|nQuesta pozione ti permetterà di passare $Ginosservato:inosservata;. Devi uccidere i signori traditori prima che la situazione ci sfugga di mano!', },
    {'Bevi la Pozione d\'Invisibilità di Krennan a Riva della Tempesta e uccidi il Barone Cinereus e Ser Walden.', },
  },
  [24593] = {
    'Né umani né bestie',
    {'È ora, $N. Questo... effetto alchemico che ha tenuto a bada la bestia che c\'è in te non durerà a lungo.|n|nI primi Worgen maledetti furono dei Druidi Elfi della Notte, come i nostri nuovi alleati. Essi tuttavia abbandonarono l\'equilibrio accolto dal resto della loro razza e consentirono alla bestia di assoggettare le loro menti.|n|nIl destino vuole che i loro fratelli ora ci stiano aiutando a guarire dalla Maledizione. Va\', $C. Bevi dalle acque di Tal\'doren e fai pace con te $Gstesso:stessa;.', },
    {'Bevi dal Pozzo della Tranquillità, dal Pozzo dell\'Equilibrio e dal Pozzo della Furia.', },
  },
  [24594] = {
    'La purificazione di Quel\'Delar',
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24595] = {
    'La purificazione di Quel\'Delar',
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24596] = {
    'La purificazione di Quel\'Delar',
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
    {'Immergi Quel\'Delar Corrotta nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24597] = {
    'Un dono per il Re di Roccavento',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per il Re di Roccavento? Sicuramente lo faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    nil,
  },
  [24598] = {
    'La purificazione di Quel\'Delar',
    {'$N, il Pozzo Solare e la fine dell\'esilio di Quel\'Delar ti attendono.|n|nAll\'interno, troverai il Gran Magistro Rommath e Lor\'themar Theron, Reggente di Quel\'Thalas. Non fidarti e non lasciarti intrappolare nei loro complotti politici.|n|nInvece, resta $Gconcentrato:concentrata; sulla tua missione. Per completare la ricostruzione di Quel\'Delar, immergila nel Pozzo Solare. Poi, mostrala a Myralion Soleardente nella Requie di Quel\'Delar. Quando sei $Gpronto:pronta; per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
    {'Immergi Quel\'Delar Temprata nel Pozzo Solare. Quando sei <pronto/pronta> per entrare nella Cittadella del Pozzo Solare, parla con un Custode del Pozzo Solare.', },
  },
  [24601] = {
    'Faglia dell\'Incubo',
    {'Ecco la conferma. Questa crescita spropositata non è provocata semplicemente da un eccesso di energia.|n|nCapisci? Questo va oltre ciò che è accaduto alla Caverna dei Lamenti. Una fenditura nell\'Incubo deve aver spaccato nel mezzo la terra sulla quale ci troviamo! E se penso che è colpa mia...|n|nBasta, è il momento di agire davvero. Vai a ovest, al centro del Labirinto Verde. Ti raggiungerò là. Andremo al cuore di questa corruzione e risolveremo il problema!', },
    {'Aiuta Naralex a sigillare la Faglia dell\'Incubo.', },
  },
  [24602] = {
    'Mettere a riposo gli antenati',
    {'$N, nella fretta di metterci in salvo abbiamo disturbato i luoghi di riposo dei nostri antenati.|n|nLa tradizione vuole che dei piccoli cimeli vengano sepolti quasi in superficie in ogni cimitero di Gilneas. La gente in fuga attraverso queste gallerie ha riportato alla luce questi cimeli e fatto arrabbiare gli spiriti.|n|nTrovali e portameli. Faremo in modo che i defunti possano tornare al loro eterno riposo.', },
    {'Procurati 5 Cimeli Dissotterrati.', },
  },
  [24603] = {
    'Desolazione senza fine',
    {'Per un attimo ho pensato che il mio odio si fosse esaurito. Mia moglie riposava in pace, e avevo placato il suo spirito tormentato con un\'ultima offerta del sangue dei suoi assassini. Ho pensato che questo mi avrebbe dato la pace.|n|nMi sbagliavo.|n|nNon avrò pace finché ogni singolo, sporco e lurido Verrospino non sarà morto e schiacciato! Non posso ucciderli abbastanza velocemente con le mie sole mani. Uccidine tu altri per me, $R.', },
    {'Uccidi 13 Verrospino Chiomaguzza.', },
  },
  [24604] = {
    'Preoccupazione per Mankrik',
    {'Vorrei chiederti un favore, $C.|n|nPoco tempo fa è passato dal nostro accampamento un guerriero di nome Mankrik. Viaggiava da solo. Sua moglie è stata uccisa dai Verrospino, molto tempo fa, ed è ancora in cerca di vendetta. Non posso dimenticare i suoi occhi... ardevano di un odio implacabile, incessante.|n|nNon abbiamo parlato molto, ma non sopporto il pensiero di saperlo ancora in cerca di vendetta, solo. Ti prego, porta questo a Mankrik e digli che è da parte mia...', },
    {'Consegna il Dono di Mahka a Mankrik, a sud del Bivacco Pietra Calda.', },
  },
  [24606] = {
    'Sangue delle Savane',
    {'<Questa pietra rossa brillante, trovata in mano a un Verrospino, è stata accuratamente intagliata a forma di grande cinghiale, con viti appuntite che fuoriescono dal dorso. La superficie è brillante e levigata con cura.>|n|n<Che sia opera dei Verrospino? Se ne trovi altre, forse uno degli Sciamani al Bivacco Pietra Calda potrà dirti di più.>', },
    {'Recupera 6 Ninnoli di Frammenti di Sangue ai Verrospino Chiomaguzza.', },
  },
  [24607] = {
    'L\'ascesa dei Lanciascura',
    {'I membri della tribù Lanciascura sono stati a lungo delle vittime, dei reietti. Abbiamo dovuto fuggire dalle case nuostr\' a più riprese... ma chesta volta è diverso.|n|nVol\'jin ci ha guidati con saggezza e ci ha tenuti in vita per tutto chisto tempo. Mo\' chella stessa saggezza prevede nu futuro caotico per l\'Orda sotto il comando di Garrosh Malogrido.|n|nNo, chesta volta nun scapperemo. Chesta volta combatteremo per na casa che duri nel tempo.|n|nÈ giunta l\'ora di cominciare l\'addestramento tuo, $N. Parla con Nortet a est.', },
    {'Vai da Nortet nei Campi d\'Addestramento dei Lanciascura.', },
  },
  [24608] = {
    nil,
    {'Non cerco più né onore né gloria, $C. Voglio solo che i Verrospino muoiano, con ogni mezzo, e per mano di chiunque.|n|nSquarciadenti, il capo di quei Chiomaguzza, siede nel suo antro a nord-ovest, in cima a una collina. Uccidilo.|n|nIo resterò qui, e continuerò ad ammassare cadaveri finché nessuno di questi vermi avrà più il coraggio di uscire grugnendo da Lamaspina e affrontarmi...', },
    {'Uccidi Squarciadenti.', },
  },
  [24609] = {
    'Un dono per il Signore di Forgiardente',
    nil,
    nil,
  },
  [24610] = {
    'Un dono per la Gran Sacerdotessa di Elune',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per la Gran Sacerdotessa di Elune? Sicuramente la faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    {'Dona i Braccialetti Portafortuna Amorosi a Tyrande Soffiabrezza a Darnassus.', },
  },
  [24611] = {
    'Un dono per il Profeta',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per il Profeta di Exodar? Sicuramente lo faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    {'Dona i Braccialetti Portafortuna Amorosi al Profeta Velen a Exodar.', },
  },
  [24612] = {
    'Un dono per il Capoguerra',
    nil,
    nil,
  },
  [24613] = {
    'Un dono per la Regina Banshee',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per la Regina Banshee? Sicuramente la faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    {'Dona i Braccialetti Portafortuna Amorosi a Dama Sylvanas Ventolesto di Sepulcra.', },
  },
  [24614] = {
    'Un dono per il Gran Capo Tribù',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per il Gran Capo Tribù? Sicuramente lo faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    nil,
  },
  [24615] = {
    'Un dono per il Reggente di Quel\'Thalas',
    {'Vuoi forgiare i Braccialetti Portafortuna Amorosi per il Reggente di Quel\'Thalas? Sicuramente lo faresti felice.|n|nHai già un Corredo da Collezionista di Portafortuna Amorosi?', },
    {'Dona i Braccialetti Portafortuna Amorosi a Lor\'themar Theron a Lunargenta.', },
  },
  [24616] = {
    'Far perdere le tracce',
    {'Devi avere molte domande, $N. Col tempo riceverai una risposta a tutte. So perché sei qui e cosa stai cercando, ma non posso condurti lì con il nemico alle calcagna.|n|nUna delle esploratrici di Sylvanas ti sta seguendo. Non puoi portare i Reietti nel posto che stai cercando di raggiungere. Prendi questo talismano e percorri la strada a nord.|n|nLascia che l\'esploratrice ti attiri nella sua trappola e usa il potere del talismano per liberarti e contrattaccare.', },
    {'Usa il Talismano di Belysra per sconfiggere l\'Esploratrice Oscura.', },
  },
  [24617] = {
    'Tal\'doren, la dimora selvaggia',
    {'Ci sono altri come te, $N, anche loro smarriti e confusi.|n|nC\'è un luogo al quale appartenete.|n|nTal\'doren, la dimora selvaggia, un tempo era la casa di un ordine di Druidi che hanno assunto la forma di lupi.|n|nLì troverai le risposte che cerchi, oltre a un vecchio amico che può offrirti aiuto.', },
    {'Parla con Darius Crowley a Tal\'doren, nel cuore di Bosconero.', },
  },
  [24618] = {
    'Reclama la Fossa di Guerra',
    {'Siamo arrivati a un punto morto con l\'Alleanza qui, anche se la terra si apre sotto i nostri piedi. A est troverai la Fossa di Guerra, un\'ampia striscia di terreno devastato. È poco più di una linea nella sabbia, ma dev\'essere la NOSTRA linea.|n|nAl centro della fossa troverai uno stendardo che stabilisce chi la controlla. Raggiungilo!|n|nSe non è ancora nostro, conquistalo in nome dell\'Orda, e la battaglia volgerà a nostro favore. Ispeziona la fossa e uccidi chiunque vi troverai!', },
    {'Vai alla Fossa di Guerra. Trova lo stendardo e uccidi 10 Soldati dell\'Avanguardia del Trionfo.|n|nCatturando lo stendardo, tutti i giocatori dell\'Orda avranno un vantaggio di combattimento nella Fossa.', },
  },
  [24619] = {
    nil,
    {'Ho sempre voluto provare a creare un Abominio. Sembra piuttosto semplice, ma sai come funziona quando impari qualcosa da un libro. La pratica è la migliore maestra!|n|nPer prima cosa avrò bisogno di parti. Tante parti. E tu me le procurerai.|n|nNon serve essere schizzinosi: parti di Umani, di Orchi... non fa nulla. Le parti sono parti.|n|nAssicurati solo che i cadaveri da cui le prelevi vengano dalla Fossa di Guerra, devo essere certo che siano fresche.|n|n<Con un sorriso disarmante, Calder ti mette in mano un segaossa insanguinato e arrugginito.>', },
    {'Usa il Segaossa di Calder sui cadaveri nella Fossa di Guerra e ottieni 15 Arti Amputati.', },
  },
  [24620] = {
    nil,
    {'Queste parti erano adorabili! Muscoli, tendini e dita... Ho TANTA fame ora.|n|nMa prima il lavoro. Una volta unite queste parti avrò bisogno di un cuore abbastanza forte da pompare fango in questo ammasso di vene. Userei il mio di cuore, ma è un guscio arido che somiglia a una rapa.|n|nNo, mi serve della forza vera. Portami un cuore di kodo, di uno di quei Kodo Squassaterra Adulti a sud della Fossa di Guerra.', },
    {'Uccidi un Kodo Squassaterra Adulto a sud della Fossa di Guerra e prendi un Cuore Gigante di Kodo.', },
  },
  [24621] = {
    nil,
    {'La mia mostruosità sta prendendo forma! Non resta che riempirgli il cranio con qualcosa di utile.|n|nParlo di un cervello, $N. E in questo la scelta dovrà essere accorta. Il processo di abominificazione provoca ingenti danni cerebrali, quindi è meglio partire con qualcosa di particolarmente acuto.|n|nUno degli ufficiali dell\'Alleanza dovrebbe andare bene. Trova uno dei capitani dall\'altro lato della Fossa di Guerra e cerca di non danneggiarlo mentre lo uccidi.', },
    {'Uccidi un Capitano del Trionfo dall\'altro lato della Fossa di Guerra e prendi un Cervello Fresco.', },
  },
  [24622] = {
    'Il migliore amico dei Troll',
    {'Se vuoi renderti utile, teniamo bisogno di qualcuno che ci aiuti a spostare altri raptor nei recinti. Vai sull\'isola a sud d\'accà e parla con i custodi nuostr\'.|n|nSono sicura che apprezzeranno l\'aiuto tuo. Na mano sta sempre gradita.', },
    {'Parla con Kijara sulla Spiaggia dei Grinfiarossa.', },
  },
  [24623] = {
    'Salvare i piccoli',
    {'A dire il vero, tengo qualcosa di molto importante che potresti fare per me, cumpà.|n|nQualcuno dell\'isola vicina ha rubato i cuccioli nuostr\'. Prima credevo fossero scappati o che la natura li avesse richiamati, ma ora ne sono spariti più di na decina.|n|nTi prego, va\' alla Caduta di Zalazane a nord-ovest e riporta indietro chelle povere creature.', },
    {'Usa il Richiamo dei Grinfiarossa per salvare 12 Cuccioli Perduti di Grinfiarossa.', },
  },
  [24624] = {
    'Pietà per i perduti',
    {'Il demone che ha rubato i raptor nuostr\' li ha corrotti con na specie di magia. Mo\' che sono cresciuti con chesta corruzione dentro di essi, temo nun ci sia niente da fare per salvarli, a parte acciderli. Vai alla Caduta di Zalazane, a nord-ovest d\'accà, e pensaci tu.|n|nSpero tu tenga il fegato per farlo. Io nun potrei riuscirci mai, anche se so che è na cosa che va fatta.', },
    {'Uccidi 8 Raptor Grinfiarossa Corrotti.', },
  },
  [24625] = {
    'Il Consorte della Strega di Mare',
    {'Ho indagato sulla corruzione dei Grinfiarossa nuostr\' e credo di aver trovato la fonte. Il responsabile è nu solo Naga. Teneva in mano nu globo rosso sopra i piccirilli nuostr\' quando li ho visti... cambiare.|n|nSono sicuro che isso crede che nessuno l\'abbia visto, dunque dovresti riuscire a pigliarlo di sorpresa. Accidi chisto Naga e portami il globo. Lo troverai a nord-ovest, presso la Caduta di Zalazane.', },
    {'Uccidi Naj\'tess e recupera il suo globo.', },
  },
  [24626] = {
    'Giovane e vivace',
    {'Tu sei in gamba, $N.|n|nMoraya mi aveva chiesto alcuni raptor da addestrare. Nun possiamo farla aspettare a lungo! Ho incaricato altre reclute di portargliene qualcuno, ma ce ne sta uno speciale che le avevo promesso già da nu po\'.|n|nZannalesta è uno dei raptor nuostr\' più veloci e coraggiosi, ma sa essere nu poco indisciplinato. Ti darò nu lazo. Voglio che lo catturi accà sull\'isola e lo porti verso i recinti sull\'isola principale. Dubito che si farà prendere facilmente.', },
    {'Cattura Zannalesta e riportalo nei recinti vicino alla Fortezza dei Lanciascura.', },
  },
  [24627] = {
    'Sulla soglia di casa',
    {'Gli Elfi della Notte ci hanno insegnato molte cose in tutto questo tempo, $N. Ci hanno insegnato chi siamo e da dove veniamo.|n|nGrazie a loro... grazie a questo posto... non siamo più semplici bestie, ma abbiamo ottenuto nuovamente la nostra volontà.|n|nI Reietti non sono qui solo per prendersi la nostra terra.|n|nStanno cercando qualcosa in nostro possesso, un manufatto in grado di diffondere la Maledizione in maniera incontrollata su tutta l\'umanità. Non possiamo permettere che lo trovino.|n|nLe Banshee di Sylvanas sono molto vicine. Aiuta i miei braccatori a eliminarle.', },
    {'Uccidi 6 Banshee Ululanti.', },
  },
  [24628] = {
    nil,
    {'Quella che tu conosci come la Maledizione è cominciata come un\'eresia tra i nostri fratelli.|n|nDi fronte alla prospettiva di perdere la battaglia contro le forze demoniache, i Druidi del Branco tradirono l\'equilibrio che avevano giurato di rispettare e consentirono alla bestia di prendere il sopravvento.|n|nFurono banditi nel Sogno di Smeraldo e si stabilirono sotto un albero identico a questo in uno stato di eterno riposo, non prima però che la loro maledizione venisse diffusa agli altri.|n|nOggi la nostra cerimonia riporterà l\'equilibrio tra la tua gente. Portami le foglie che crescono solo nelle vicinanze di Tal\'doren.', },
    {'Porta 6 Foglieluna a Vassandra.', },
  },
  [24629] = {
    'Una perfetta nuvola di profumo',
    {'$C, mi sembri una persona che sa quello che vuole. Che ne dici di un\'offerta in cui hai solo da guadagnare?|n|nIndustrie F.lli Corona vogliono distribuire campioni dei nostri ultimi prodotti festivi al maggior numero possibile di potenziali clienti. Aiutaci a spargere un po\' d\'amore e ti offriremo degli sconti sul nostro meraviglioso catalogo!|n|nIl tuo tempo in cambio del nostro denaro. Che ne dici?', },
    {'Irrora 10 persone usando il Vaporizzatore di Profumo delle Industrie F.lli Corona.', },
  },
  [24630] = {
    'La strega della galleria',
    nil,
    nil,
  },
  [24631] = {
    nil,
    {'L\'Alleanza ha reclutato dei Mercenari dei Granmartello per controllare i cieli sulla Fossa di Guerra. Credo si tratti degli stessi cavalieri di grifoni che hanno bombardato Taurajo durante l\'attacco.|n|nVoglio che i nostri cieli vengano ripuliti.|n|nI Nani Granmartello volano abbastanza bassi da permettere a $Gun:una; potente $C dall\'ottima mira di agganciarli. Prendi. Punta i loro grifoni e disarciona i piloti... Una volta a terra, nessuna pietà.', },
    {'Usa l\'Uncino di Tomusa sui Grifoni da Guerra del Trionfo per disarcionare e uccidere 5 Mercenari dei Granmartello.', },
  },
  [24632] = {
    'La vendetta dei Tauren',
    {'La mia gente non è violenta di natura, ma a volte la sete di giustizia ci fa impugnare le armi in preda alla rabbia.|n|nQuando ha appreso del massacro a Taurajo, il mio vecchio amico Gann Spina Dura è diventato furibondo. Gli anziani della tribù non riuscivano più a contenere la sua rabbia.|n|nOra si è quasi del tutto allontanato dall\'Orda. Sta agendo per conto suo, $N, e vuole affrontare l\'Alleanza con un piccolo gruppo di compagni che la pensano come lui.|n|nSe anche tu cerchi vendetta, lo troverai a sud-est di qui, ai piedi di Bael Modan.', },
    {'Trova Gann Spina Dura a Punta di Lancia nelle Savane Meridionali.', },
  },
  [24633] = {
    'La supplica di Mahka',
    {'Non riesco a togliermelo dalla testa, $N. A volte, durante la notte, sento i suoi lamenti di rabbia e dolore che echeggiano nelle pianure. Immaginarlo lì, solo e sofferente...|n|nTi prego, devo chiederti un favore. Recati da Mankrik e digli di venire da me.', },
    {'Parla con Mankrik.', },
  },
  [24634] = {
    'Guerra di spionaggio',
    {'Sono convinto che l\'Alleanza usi delle spie per tenere d\'occhio il campo e trasmettere informazioni. Sapevano di poter attaccare Taurajo mentre i cacciatori non c\'erano. E hanno risposto a ogni mossa di Gar\'dul come se la conoscessero in anticipo.|n|nBe\', $N, io non mi farò fregare. Non qui. Vinceremo noi la guerra di spionaggio.|n|nAnche ora mi comunicano di agenti dell\'Alleanza che si aggirano nell\'ombra fuori da queste stesse mura. Uccidili e portami qualche informazione utile.', },
    {'Uccidi un Agente Operativo delle Savane e recupera le Istruzioni dell\'IR:7.', },
  },
  [24635] = {
    'Una nuvoletta di colonia',
    {'$C, mi sembri una persona intraprendente. Ti andrebbe di collaborare con noi?|n|nIndustrie F.lli Corona vogliono distribuire campioni dei nostri ultimi prodotti festivi al maggior numero possibile di potenziali clienti. Aiutaci a spargere un po\' d\'amore e ti daremo qualcosa dal nostro meraviglioso catalogo!|n|nIl tuo tempo in cambio del nostro denaro. Che ne pensi?', },
    {'Irrora 10 persone usando il Vaporizzatore di Colonia delle Industrie F.lli Corona.', },
  },
  [24636] = {
    'Dolciumi gratis!',
    {'$C, si capisce subito che sai cogliere al volo le opportunità. Ti andrebbe di guadagnare qualche moneta insieme a noi?|n|nIndustrie F.lli Corona vogliono distribuire campioni dei nostri ultimi prodotti festivi a ogni potenziale cliente in città. Aiutaci a spargere un po\' d\'amore e noi condivideremo con te parte del nostro meraviglioso catalogo!|n|nIl tuo tempo in cambio del nostro denaro. Affare fatto?', },
    {'Lancia Campioni di Cioccolato delle Industrie F.lli Corona a 10 persone.', },
  },
  [24637] = {
    'Il Macellaio di Taurajo',
    {'Questo agente doveva mettere in sicurezza le strade tra il Comando dell\'Alleanza e la Roccaforte del Trionfo. Il Generale Biancospino si sta muovendo.|n|n<Elsarossa accartoccia i documenti nel pugno.>|n|nÈ LUI, $N! Biancospino, che sia maledetto! È lui che ha ordinato l\'attacco a Taurajo! Ora sappiamo quando e dove colpirlo. Presto, segui la strada settentrionale della Fossa di Guerra e unisciti al mio assassino, Karthog. SCHIACCIA Biancospino e trascina il suo cadavere lungo la strada!', },
    {'Parla con Karthog, poi esci allo scoperto e uccidi il Generale Biancospino.', },
  },
  [24638] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto a ovest, fuori dalle Porte di Orgrimmar! Non mi piace per niente. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Lacchè dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona a ovest delle Porte di Orgrimmar a Durotar. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24639] = {
    'Le basi: colpire gli oggetti',
    {'Vabbuo\', cumpà. Cominceremo dalle basi. Voglio assicurarmi che tu sappia come usare chell\'arma che ti porti appresso.|n|nDistruggi quei Bersagli Tiki. Procedi lentamente seguendo il ritmo della natura. Osserverò lo stile di combattimento tuo e procederemo da lì.', },
    {'Distruggi 6 Bersagli Tiki.', },
  },
  [24641] = {
    'Un inizio difficile',
    {'Mettiamo all\'opera le abilità tue. Cominceremo con na cosa semplice.|n|nCi stanno dei felini fetenti che stanno accidendo i cinghiali nuostr\'. La carne di chelle bestie appartiene a noi. Dobbiamo proteggerle se vogliamo tenere cibo per cena.|n|nStanno sparse per tutta quanta l\'isola. Portami un po\' delle pellicce loro.', },
    {'Ottieni 6 Pellicce di Felino Mantoselvaggio.', },
  },
  [24642] = {
    'Fossa delle prove',
    {'Te la sei cavata piuttosto bene, $C. Tengo ancora nu paio di cose da insegnarti, ma nun voglio farti perdere altro tempo con i Bersagli Tiki.|n|nTi ho preparato nu ultimo test, cumpà. Dirigiti verso la fossa di prova al centro di chest\'area per affrontare nu nemico davvero fetente, deciso ad acciderti. Parla con il carceriere vicino alla fossa quando stai $Gpronto:pronta;.', },
    {'Parla con il Carceriere Lanciascura, quindi entra nella fossa di prova e uccidi l\'Esploratore Scagliatruce Prigioniero.', },
  },
  [24643] = {
    'Oltre ogni previsione',
    {'Sei $Gandato:andata; al di là delle aspettative, cumpà. Sono sicuro che mo\' ci stanno cose più importanti per cui usare i talenti tuoi. Nun dovrai più addestrarti con le reclute.|n|nDirigiti verso il villaggio a sud-est e metti le abilità tue al servizio delli altri. Sono certo che aumenterai presto il prestigio tuo dando na mano accà e là.', },
    {'Fai rapporto a Vol\'jin nella Fortezza dei Lanciascura.', },
  },
  [24645] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto appena fuori dal Mulino d\'Ambra della Selva Pinargento. Non mi piace per niente. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Teppisti dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona fuori dal Mulino d\'Ambra della Selva Pinargento. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24646] = {
    'Riprendiamoci ciò che è nostro',
    {'Da quando i Reietti hanno invaso Gilneas abbiamo cercato di tenere segreto il luogo dove è custodita la Falce di Elune. L\'abbiamo spostata di notte in uno dei nostri rifugi sicuri. Le Guardaboschi Oscure si sono avvicinate, ma non sono riuscite a trovarla... per ora.|n|nL\'ultima volta sono state viste vicino al Casotto della Radura, a ovest di qui. Suona questo corno quando le avrai trovate e Tobias e i suoi braccatori le attaccheranno.|n|nSolo allora potrai avventurarti in sicurezza all\'interno del casotto per recuperare la falce. Fa\' presto, $N. Non deve cadere nelle mani di Sylvanas.', },
    {'Suona il Corno di Tal\'doren al Casotto della Radura e recupera il Manufatto Misterioso nascosto all\'interno.', },
  },
  [24647] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto appena fuori dal villaggio di Colletorto, fra le Alture di... Indovina? Esatto, di Colletorto. Non mi piace per niente. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Concimatori dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona appena fuori dal villaggio di Colletorto, fra le Alture di Colletorto. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24648] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto vicino al Presidio di Guardia appena fuori da Theramore alle Acquemorte. E non guardarmi a quel modo: è un problema anche per noi! Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Vandali dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona fuori da Theramore ad Acquemorte. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24649] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto a est del Picco dell\'Aquila nelle Entroterre. E non guardarmi a quel modo: è un problema anche per l\'Orda! Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Agenti dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona a est del Picco dell\'Aquila nelle Entroterre. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24650] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto a Fontefredda, a est di Lungavista. Questa è una faccenda personale. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Irroratori dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona a est di Lungavista nella valle di Fontefredda. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24651] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto appena a est di Shattrath, nella Foresta di Terokk. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    nil,
  },
  [24652] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto nella Selva Triste della Foresta di Cristallo, a nord-ovest dello Specchio del Crepuscolo. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Spargitori dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona nella Selva Triste della Foresta di Cristallo. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
  [24653] = {
    'Echi di Agamaggan',
    {'Credo che i Verrospino siano guidati da qualcosa che va oltre la mera bramosia. Mi aiuteresti a indagare?|n|nA ovest, sparsi tra gli insediamenti e gli accampamenti dei Verrospino, ho notato dei teschi di cinghiale. Brillano a distanza, sono lisci e lucidi... diversi dai resti ammassati nella loro immondizia. Credo che potrebbero essere oggetto di venerazione.|n|nPortamene qualcuno da studiare, $N.', },
    {'Trova 3 Teschi di Cinghiale Lucidati.', },
  },
  [24654] = {
    nil,
    {'I Silitidi! Sono insetti, $N. O qualcosa del genere. Non sono naturali... e noi abbiamo costruito una fortezza sull\'equivalente di un formicaio.|n|nPrendi questa pece ardente. Darà alle fiamme quegli insettacci e contemporaneamente tapperà i loro cunicoli. Fai attenzione quando userai la pece: i Silitidi verranno fuori a sciami!|n|nCerca i tumuli di Silitidi fuori da Forte Desolazione. Sembrano mucchi di sabbia. Uccidi tutto quello che ne esce.', },
    {'Usa il Secchio di Pece Ardente sui Tumuli di Silitidi e uccidi 10 Brulicatori Silitidi non appena escono.', },
  },
  [24655] = {
    'Qui qualcosa puzza',
    nil,
    {'Usa l\'Analizzatore d\'Aria di Catenaccio per esaminare l\'aria intorno a 6 guardie molto profumate, poi torna dall\'Ispettore Snip Catenaccio a Roccavento.', },
  },
  [24656] = {
    'Furto di profumo',
    nil,
    {'Indossando il travestimento da corriere, raggiungi la scorta delle Industrie F.lli Corona fuori dalle porte di Roccavento. Consegna la cassa che ti lanceranno all\'Ispettore Snip Catenaccio a Roccavento.', },
  },
  [24657] = {
    'Una chiacchierata amichevole...',
    {'<Marion ascolta inorridita mentre le spieghi per quale motivo stai cercando Snivel.>|n|nStai dicendo che ha usato qualche tipo di sostanza chimica su di me? Non posso credere di essermi innamorata di quel truffatore!|n|nSe ha già sbrigato le commissioni, ora sarà in cammino verso il Porto in cerca di una nave per i Mari del Sud! $N, non fargliela passare liscia!|n|nCorri al Porto di Roccavento o ti sfuggirà!', },
    {'Vai al Porto di Roccavento e interroga Snivel Razzovecchio riguardo alle forniture. Torna indietro con qualsiasi prova riuscirai a ottenere da lui.', },
  },
  [24658] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto a nord-est del Presidio Rivombroso, fuori dalla Foresta di Elwynn! Non mi piace per niente. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Lacchè dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona a nord-est del Presidio Rivombroso nella Foresta di Elwynn. Poi, torna dall\'Ispettore Snip Catenaccio a Roccavento.', },
  },
  [24659] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto appena a sud del Bosco degli Antichi sulla Rivafosca. Non mi piace per niente. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Teppisti dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona a sud del Bosco degli Antichi sulla Rivafosca. Poi, torna dall\'Ispettore Snip Catenaccio a Roccavento.', },
  },
  [24660] = {
