  [28805] = {
    'L\'occhio del ciclone',
    nil,
    {'Il Chiaroveggente Krogar ti ha chiesto di scrutare le Acque della Lungimiranza.', },
  },
  [28806] = {
    'Non temere alcun male',
    {'Hai già accolto la Luce Sacra, $Gfratello:sorella;? Sarà la Luce Sacra a darci la salvezza! È la Luce Sacra che mi permette di curare le gravi ferite di questi soldati! Ed è grazie alla Luce Sacra che riuscirai ad avventurarti nel campo a nord per salvare i fratelli caduti!|n|nPorta con te questo libro di preghiere e lancia il Tocco Curativo della Luce sui feriti.', },
    {'Cura 4 Gregari di Roccavento Feriti.', },
  },
  [28807] = {
    'Il parere dell\'esperto',
    {'<Anduin tiene sollevati gli emblemi identici.>|n|nIl medaglione che abbiamo trovato nella fattoria è identico a quello in mezzo ai documenti di Samuelson! Non può essere una coincidenza. Credo che Samuelson stia macchinando qualcosa, ma ci serve una prova schiacciante prima di accusare una delle guardie più leali di mio padre.|n|nC\'è solo una persona di cui mi fido che può aiutarci: Mathias Shaw, il Direttore dell\'IR:7. Mostragli questi emblemi e senti che ne pensa. Nel frattempo io tornerò al forte e seguirò Samuelson come un\'ombra!', },
    {'Porta gli Emblemi Sospetti a Mathias Shaw presso il quartier generale dell\'IR:7 a Roccavento.', },
  },
  [28808] = {
    'Non temere alcun male',
    {'Hai già accolto la Luce Sacra, $Gfratello:sorella;? Sarà la Luce Sacra a darci la salvezza! È la Luce Sacra che mi permette di curare le gravi ferite di questi soldati! Ed è grazie alla Luce Sacra che riuscirai ad avventurarti nel campo a nord per salvare i fratelli caduti!|n|nPorta con te questo libro di preghiere e lancia il Tocco Curativo della Luce sui feriti.', },
