  [28824] = {
    'Figlio ribelle',
    {'Uno dei miei figli non è con me, $N.|n|nÈ rimasto con il Martello del Crepuscolo al Nucleo di Pietra, all\'interno del Tempio della Terra.|n|nHo mandato gli altri miei figli a liberarlo dalla magia oscura che di certo gli impediva di tornare qui, ma... non esisteva alcuna magia del genere.|n|nVai nel Nucleo di Pietra e distruggi Ozruk. Deve tornare alla terra.', },
    {'Uccidi Ozruk.', },
  },
  [28825] = {
    'Una chiamata personale',
    {'<Una sensazione sconosciuta emerge dentro di te, avvolgendo la tua mente di immagini e pensieri.>|n|nAscolta le mie parole, $N.|n|nIl nostro mondo è in preda a una crisi terribile.|n|nMi rivolgo a te per chiedere aiuto in questa ora disperata.|n|nIo sono Naraat.|n|nCercami subito, e il senso della tua chiamata ti sarà chiaro.|n|nTi attendo al Santuario Orientale della Terra a Roccavento.', },
    {'Parla con Naraat l\'Oratore della Terra a Roccavento.', },
  },
  [28826] = {
    'L\'occhio del ciclone',
    nil,
    {'Naraat l\'Oratore della Terra ti ha chiesto di scrutare le Acque della Lungimiranza.', },
  },
  [28827] = {
    'Acque profonde',
    {'Il Circolo della Terra ha individuato nel regno sottomarino di Vashj\'ir una sorgente delle energie distruttive degli avversari.|n|nNon è chiaro quali pericoli dovrai affrontare, quindi qualsiasi informazione che riuscirai a raccogliere sarà di aiuto.|n|nL\'Alleanza sta inviando delle navi da guerra nella regione. Per ottenere un passaggio, dirigiti a nord-ovest di Roccavento e parla con il Reclutatore Burns nel Porto di Roccavento.|n|nChe gli spiriti ti accompagnino nel tuo cammino, $N.', },
    {'Parla con il Reclutatore Burns al Porto di Roccavento.', },
  },
  [28828] = {
    'Uovo avvistato mezzo mangiato',
    {'Non ho un palato raffinato, ma persino io non riesco a sopportare il sapore delle chimere che bazzicano qui intorno. Le loro uova, comunque, sono tutta un\'altra storia.|n|nSono le più ricche e burrose a nord di Orgrimmar. Migliori di quelle di gufo, che un po\' ormai hanno stufato, e meno acide di quelle dei silvagufo.|n|nPrenderò tutte quelle che riuscirai a portarmi. Vai a nord-est e cerca i loro nidi nella neve.', },
    {'Recupera 40 Uova di Ventofreddo.', },
  },
  [28829] = {
    'Becchi aguzzi e corna appuntite',
    {'Cosa mi è successo? Stammi a sentire, $C, la mia è una storia tragica...|n|nSono stato mandato nella Selva Ala di Gufo per trovare delle reliquie, ma sono riuscito ad arrivare soltanto fin qui prima di essere sopraffatto da una tempesta di ali e artigli.|n|nChe ruggiti e che beccate, $C!|n|nOra eccomi qua, un Orco finito con in testa soltanto la vendetta. Ti prego, $C, se hai un briciolo di senso dell\'onore, vai nella Selva Ala di Gufo e aiutami a riprendere il mio.', },
    {'Uccidi 12 Bestiagufo Frenetici nella Selva Ala di Gufo.', },
  },
  [28830] = {
    'Famiglie spezzate',
    {'I miei benefattori misteriosi mi avevano assegnato più di un compito. Il secondo mi portò a sud, nella Gola Eco Freddo. Fui sorpreso di scoprire che il ponte era spaccato in due e che non era possibile viaggiare da un lato all\'altro.|n|nInoltre, le giovani Furie Magliofreddo erano state divise dai loro familiari adulti. Credevo di poterle sconfiggere in battaglia.|n|nMa mi sbagliavo. Fui costretto alla fuga.|n|nDai una lezione a quei bestioni, $N. Combatti e vinci.', },
    {'Uccidi 8 Furie Magliofreddo.', },
  },
  [28831] = {
    'Che tu sia maledetto, Gelicus',
    {'I Giganti Magliofreddo non avrebbero rappresentato un grosso problema, se non fosse stato per quel maledetto Freddilicus. Quando la terra ha tremato e il ponte si è spaccato, lui e i suoi Elementali dell\'Acqua sono sorti dalla terra e hanno occupato la Gola Eco Freddo, cacciando i giganti.|n|nChe tu sia maledetto, Gelicus!|n|nMi faresti un grande onore se ricacciassi da dove è venuto, $C. Lo troverai a sud, in fondo alla gola.', },
    {'Uccidi Gelicus.', },
  },
  [28832] = {
    'Riva del Crepuscolo',
    {'Bene dunque, salta sull\'aereo marino dietro di me e ti porterò direttamente nelle Alture.|n|nDobbiamo fare rapporto a un certo "Tenente Fawkes". Ho promesso al Re che saremmo arrivati lì in un lampo, quindi mi sono preso la libertà di disfarci del peso in eccesso. Cinture di sicurezza. Paracadute. Mappe. Stabilizzatori. Strumentazione per l\'atterraggio.|n|nTanto non "atterro" mai davvero con questi cosi.', },
    {'Parla con il Tenente Fawkes ad Altariva nelle Alture del Crepuscolo.', },
  },
  [28833] = {
    'Salvare Parlapietra',
    {'Bene! Hai portato degli alleati.|n|nDevi fare in fretta se vogliamo salvare Erunak.|n|nFatti strada nelle stanze di Neptulon. Trova lo Sciamano e liberalo da quei vermi... se è ancora vivo.|n|nNon preoccuparti di possibili attacchi alle spalle. Nessuno mi oltrepasserà!', },
    {'Salva Erunak Parlapietra.', },
  },
  [28834] = {
    'Salvare Parlapietra',
    {'Bene! Hai portato degli alleati.|n|nDevi fare in fretta se vogliamo salvare Erunak.|n|nOra vai. Fatti strada nelle stanze di Neptulon. Trova lo Sciamano e liberalo da quei vermi... se è ancora vivo.|n|nNon preoccuparti di possibili attacchi alle spalle. Non permetterò a nessuno di oltrepassarmi!', },
    {'Salva Erunak Parlapietra.', },
  },
  [28835] = {
    nil,
    {'Nella Valle delle Sfide fa un caldo soffocante.|n|n<Galgar si asciuga la fronte.>|n|nSe soltanto avessi delle mele di cactus, potrei creare il mio famoso Sformato di Mele di Cactus! Non c\'è niente che rinfreschi più rapidamente.|n|n$N, sai che ti dico? Se mi porti 6 mele di cactus ti darò un po\' della mia specialità, che potrai così portare con te nelle tue avventure. Se sei <interessato/interessata> potrai trovare le mele di cactus vicino ai cactus sparsi nei dintorni.', },
    {'Raccogli 6 Mele di Cactus.', },
  },
  [28836] = {
    'I peccati della Strega di Mare',
    {'Quella dannata merita di morire mille volte!|n|nNon sarà facile. Lei e i suoi servitori sono strettamente legati a questo luogo, ma è certamente stremata dalla sua lotta contro Neptulon.|n|nOra è il momento di colpire! Non avremo un\'altra opportunità del genere.|n|nDistruggila, $N!', },
    {'Uccidi Dama Naz\'jar nel Trono delle Maree.', },
  },
  [28837] = {
    'Bestie alterate',
    {'Noi Draghi Blu siamo stati cacciati dalla nostra casa, Mazthoril. Un impostore, Umbranse, ci ha colpiti quando eravamo più deboli e ora occupa la grotta.|n|nMazthoril è un luogo pregno di magia, magia che lui non sa usare. Anche la fauna ne soffre.|n|nLe bestie nei dintorni sono mutate. Ti prego, $R, mi serve un favore. Raccogli i loro cervelli così che io possa provare a cancellare la magia di Umbranse.', },
    {'Ottieni 5 Cervelli Consumati dal Mana dalle Bestie Alterate.', },
  },
  [28838] = {
    'Le difese dei Bestiagufo',
    {'Che vergogna. Qualunque cosa abbia fatto Umbranse, non riesco a cancellare la sua magia.|n|nÈ più abile di quanto credessi.|n|nComunque ho un piano di riserva. Ho visto dei Bestiagufo entrare e uscire da Mazthoril anche dopo l\'occupazione di Umbranse. La loro antica magia druidica dovrebbe essere in grado di neutralizzare Umbranse. Fortunatamente conosco bene le loro abitudini.|n|nVai a sud, a Dun Mandarr. Troverai una cassa con dentro un acchiappasogni.|n|nÈ il primo passo da compiere.', },
    {'Recupera l\'Acchiappasogni dei Bestiagufo a Dun Mandarr.', },
  },
  [28839] = {
    'Magia preistorica',
    {'Le grotte sacre dei Bestiagufo si trovano a est. Dentro ci troverai molti totem. Voglio che ti avvicini ai totem e raccogli quanta più essenza possibile. L\'acchiappasogni dovrebbe assorbirla, in modo poi da essere usata all\'interno di Mazthoril.', },
    {'Assorbi l\'Essenza del Totem dell\'Artiglio, l\'Essenza del Totem della Vita e l\'Essenza del Totem della Luna.', },
  },
  [28840] = {
    'Acqua Invernale',
    {'Non voglio che il nostro tentativo fallisca, $N. Una sconfitta attirerebbe soltanto l\'attenzione verso di noi, dando a Umbranse la possibilità di potenziare le difese. No, dobbiamo farcela al primo tentativo.|n|nLa Gola Eco Freddo a sud permette di entrare in contatto con i potenti Elementali del Ghiaccio. Le acque degli elementali dovrebbero potenziare l\'Acchiappasogni.|n|nPrendi quelle acque, $N, e ritorna al nostro accampamento.', },
    {'Ottieni 7 Fiale di Acqua Invernale dagli Avatar del Ghiaccio nella Gola Eco Freddo.', },
  },
  [28841] = {
    'La Tempesta Arcana perfetta',
    {'Se usata male, la magia innata di Mazthoril può causare morte e distruzione. Gli incantesimi sregolati di Umbranse hanno aperto dei tesseract, ovvero dei portali dimensionali: un collegamento con altri mondi. Se voglio rientrare a Mazthoril, quei portali vanno chiusi.|n|nL\'acchiappasogni ti permetterà di farlo, garantendoti l\'accesso al covo di Umbranse. Dai la precedenza all\'eliminazione di qualsiasi cosa esca dai portali, quindi usa l\'acchiappasogni per chiuderli, evitando che partoriscano altro.', },
    {'Usa l\'Acchiappasogni Potenziato per chiudere 5 Tesseract Arcani dentro Mazthoril.', },
  },
  [28842] = {
    'La fine di Umbranse',
    {'Umbranse si trova in fondo a Mazthoril. Il suo tempo è giunto.|n|nSfortunatamente, non posso accompagnarti nella missione. Anche se non sogno altro che di mettere le mani su quella serpe, in questo stato la magia di Mazthoril mi farebbe a pezzi. No, devi pensarci tu.|n|nQuando avrai fatto, usa questo talismano. Ti riporterà al ritrovo.', },
    {'Uccidi Umbranse il Medium.', },
  },
  [28843] = {
    'I peccati della Strega di Mare',
    {'Naz\'jar! È lei la responsabile di tutto questo.|n|nÈ qui da qualche parte, $N. Deve essere stremata dalla sua lotta contro Neptulon.|n|nOra è il momento di colpire! Non avremo un\'altra opportunità del genere.|n|nIo mi occuperò di qualunque cosa venga ad aiutarla da questa direzione.|n|nTrovala, $N, e distruggila!', },
    {'Il Legionario Nazgrim ti ha chiesto di uccidere Dama Naz\'jar.', },
  },
  [28845] = {
    'Pinnacolo del Vortice',
    {'Uno dei nostri capi civili è stato fatto prigioniero dagli Elementali dell\'Aria.|n|nProbabilmente ora lo stanno torturando per estorcergli informazioni.|n|nVai al Pinnacolo del Vortice, da dove provengono queste creature malvagie, e cerca Itesh.|n|nTroverai l\'ingresso del Pinnacolo del Vortice sospeso al largo della costa sudorientale di Uldum.', },
    {'Trova Itesh al Pinnacolo del Vortice.', },
  },
  [28847] = {
    'Alla ricerca di Umbranse',
    {'Abbiamo individuato il nascondiglio di Umbranse qui a Fontefredda.|n|nCome sospettavo, è a Mazthoril, la grotta a sud-ovest che un tempo apparteneva allo Stormo dei Draghi Blu. Lì troverai ad accoglierti mia madre Haleh... fuori dalla grotta, in un piccolo accampamento, in compagnia di altri sopravvissuti.|n|nCercala.', },
    {'Parla con Haleh al Ritrovo di Beryl nella regione di Fontefredda.', },
  },
  [28848] = {
    'Sulle tracce del Medium',
    {'Ho sentito parlare di Umbranse, anche se non l\'ho mai conosciuto di persona. Si dice che stia accumulando manufatti magici, ma non so per quale motivo.|n|nMeglio passare l\'informazione a un alleato fidato. L\'Alto Elfo Nymn si trova a Lungavista, la grande città dei Goblin a nord-est. Raccontagli quello che abbiamo scoperto.', },
    {'Parla con Nymn a Lungavista nella regione di Fontefredda.', },
  },
  [28849] = {
    'Cieli del Crepuscolo',
    {'Ho appena ricevuto da Orgrimmar la notizia che il Capoguerra vuole che partiamo. Non saremmo stati pronti senza il tuo aiuto!|n|nIl piano prevede che la flotta aerea decolli immediatamente... e che la marina segua a breve distanza. Malogrido accompagnerà la flotta aerea e ha richiesto la tua presenza.|n|nNon c\'è tempo da perdere! Vai al Terminale Sud della Razzovia qui ad Azshara e fai rapporto a Friz Schiantobasso. Io verrò a prenderti con lo zeppelin.', },
    {'Fai rapporto a Friz Schiantobasso presso il Terminale Sud della Razzovia di Azshara.', },
  },
  [28850] = {
    'I tetti della prigione',
    {'Non capisco perché il re si ostini a perdere tempo per salvargli la pelle, ma se vuoi rischiare la vita, accomodati pure.|n|nCrowley e i suoi uomini si sono rintanati al piano di sopra e probabilmente stanno complottando contro il re in questo stesso momento!', },
    {'Parla con Ser Darius Crowley al piano superiore nella Prigione di Guardiapietra a Gilneas.', },
  },
  [28851] = {
    nil,
    nil,
    {'Parla con Sullah alla Postazione di Sullah.', },
  },
  [28852] = {
    'Sfoltiscili',
    {'Finalmente i rinforzi! Sono felice che tu sia qui. Non potevamo immaginare quanto fossero solide e numerose le forze del Martello del Crepuscolo!|n|nDiversi dei nostri drachi sono stati catturati dentro al salone principale. Devi liberarli.|n|nDopo potremo ripulire insieme queste sale con il fuoco. Monta su un Draco Rosso ed elimina i tuoi obiettivi. Bisogna sfoltire le file nemiche prima di addentrarci ulteriormente nelle rovine.', },
    {'Libera un Draco Rosso dentro Grim Batol e usalo per distruggere 30 Trogg e 15 Servitori del Martello del Crepuscolo.', },
  },
  [28853] = {
    'Uccidere il braccio destro',
    {'Grazie, $C, per aver sfidato gli orrori di questo luogo oscuro e terribile.|n|nLe profondità di Grim Batol sono il cuore della macchina da guerra di Cho\'gall. Dobbiamo saperne di più a riguardo se vogliamo fermare i suoi complotti in tutte le Alture.|n|nCerca Drahga Strinaombre nelle profondità di Grim Batol. È il braccio destro di Cho\'gall, l\'anello di congiunzione tra questo posto e il Bastione del Crepuscolo. Bisogna scoprire quali segreti porta con sé.', },
    {'Uccidi Drahga Strinaombre e ruba la sua Missiva per Cho\'gall.', },
  },
  [28854] = {
    'Chiudere un capitolo buio',
    {'Questo terribile luogo era l\'incubo di Alexstrasza. Durante quella che i mortali chiamano la Seconda Guerra, ella fu incatenata nelle profondità e la sua progenie tormentata fu costretta a servire l\'Orda corrotta dai demoni.|n|nAlexstrasza è libera, ma la bestia nota come Erudax corrompe ancora la sua stirpe.|n|n<Il corpo di Fiammantica si contrae dalla rabbia.>|n|nDistruggilo, $C. Fallo a pezzi in modo da porre fine a questi orrori una volta per tutte!', },
    {'Uccidi Erudax, il Duca delle Profondità.', },
  },
  [28856] = {
    'Il deserto di Silitus',
    nil,
    {'Parla con l\'Invocatore del Vento Fierocorno alla Fortezza Cenariana di Silitus.', },
  },
  [28857] = {
    'Terre Devastate: Dall\'altra parte del mondo',
    {'Vai a parlare con il Quartiermastro Lungertz al Forte di Guardiafatua nelle Terre Devastate. Si trova dall\'altra parte del mondo!|n|nLe informazioni a mia disposizione dicono che stanno avendo dei problemi con l\'Orda. Mmm... non sapevo neanche che l\'Orda avesse un avamposto nelle Terre Devastate! Da quello che ho capito hanno preso un po\' sottogamba i rivali, occupandosi di demoni.|n|nPer arrivare, devi attraversare il Grande Mare, quindi dirigerti a sud dalla Palude del Dolore.|n|nTi interessa?', },
    {'Parla con il Quartiermastro Lungertz al Forte di Guardiafatua.', },
  },
  [28858] = {
    'Terre Devastate: Dall\'altra parte del mondo',
    {'Davvero interessante. Dice che i membri dell\'Orda dovrebbero andare a parlare con Okrilla nella Rocca dei Maglioinfame.|n|nMmm... non sapevo neanche che la Rocca dei Maglioinfame fosse sotto il controllo dell\'Orda! Okrilla ha bisogno di aiuto per combattere contro degli Ogre e l\'Alleanza. Penserai... non bastavano già tutti quei demoni, eh?|n|nPer arrivare, devi attraversare il Grande Mare, quindi dirigerti a sud dalla Palude del Dolore.|n|nTi interessa?', },
    {'Parla con Okrilla alla Rocca dei Maglioinfame nelle Terre Devastate.', },
  },
  [28859] = {
    'Le dune di Silitus',
    {'Cumpà, la Fortezza Cenariana di Silitus è uno dei più grandi insediamenti dei Druidi di tutta quanta Kalimdor.|n|nMagari nu giorno Zen\'aliri andrà alla Fortezza Cenariana... mazzierà qualche Martello del Crepuscolo... la ripulirà dai Silitidi... ma mo\' il maestro suo ha detto a isso di stare buono.|n|nE Zen\'aliri sta buono.|n|nIl modo migliore per raggiungerlo è il sentiero che passa per le alture a nord-ovest del Cratere di Un\'Goro.|n|nSe nun tieni nu maestro, chi ti trattiene?', },
    {'Parla con l\'Invocatore del Vento Fierocorno alla Fortezza Cenariana di Silitus.', },
  },
  [28860] = {
    'Tenere a bada le Fauci di Drago',
    {'Con il tuo aiuto abbiamo inferto un duro colpo alle Fauci di Drago, ma continuano comunque ad attaccare quotidianamente i confini di Tuonocupo. Non dobbiamo fermarci!|n|nPrendi parte alla battaglia che infuria nelle Rovine di Tuonocupo a sud e a sud-ovest. Uccidi i Predoni delle Fauci di Drago e prendi i fregi che indossano i loro migliori guerrieri.', },
    {'Uccidi i Predoni delle Fauci di Drago e prendi 8 Fregi delle Fauci di Drago. Anche i personaggi di rilievo all\'interno delle Rovine di Tuonocupo possiedono dei fregi.', },
  },
  [28861] = {
    'Combatti come un Granmartello',
    {'<Blundy rovescia il suo boccale.>|n|nHo finito la birra, $N!|n|nVai alle Rovine di Tuonocupo e vedi se ce n\'è rimasta un po\', prima che quei miserabili delle Fauci di Drago ci mettano le loro manacce sopra.|n|nBevine pure qualche sorso. Un boccale della migliore birra di Tuonocupo aumenterà le tue capacità di combattimento.', },
    {'Recupera 10 Barili di Birra di Tuonocupo alle Rovine di Tuonocupo. Attenzione: è piuttosto forte!', },
  },
  [28862] = {
    'Mai perdersi una cena',
    {'I rifugiati stanno ancora arrivando a Tuonocupo dopo la battaglia... e io ho fame! Cioè, hanno. I rifugiati, hanno fame.|n|nProcurami del cibo alle Rovine di Tuonocupo! Perlustrale a sud, est e sud-ovest, alla ricerca di provviste rimaste. Specialmente quei grossi prosciutti. Li adoro! Ehm, i rifugiati li adorano.|n|nVedi se riesci a trovare degli stuzzichini da cocktail.', },
    {'Recupera 10 Scorte Alimentari dei Granmartello dalle Rovine di Tuonocupo.', },
  },
  [28863] = {
    'Il Signore della Guerra Halthar è tornato',
    {'È tornato, $N. il Signore della Guerra Halthar... il terrore della contea. Lui e il suo draco sono stati visti creare problemi a sud, nelle Rovine di Tuonocupo.|n|nUccidi Halthar, $N! Ti manderemo dei Guerriglieri di supporto appena avrai cominciato a combattere.', },
    {'Uccidi il Signore della Guerra Halthar.', },
  },
  [28864] = {
    'Voglia di birra',
    {'Dopo il matrimonio di mia sorella, ho scoperto quant\'è buona la Birra dei Birratuono che Kurdran ha importato da Dun Morogh. Ne sta arrivando dell\'altra, ma la nostra carovana continua a essere assalita dalle Fauci di Drago!|n|nDirigiti al versante sud-est del Monte del Fulmine e unisciti alla carovana. Cerca un tizio di nome Jax, sul bordo della strada, e aiutalo a passare con la birra.|n|nArriva fino a Borgogaio, da lì ci penseremo noi.', },
    {'Parla con Jax sulla strada a sud-est del Monte del Fulmine e scorta a Borgogaio una carovana di rifornimenti.', },
  },
  [28865] = {
    'La chiamata della Matrona della Guerra',
    {'La nostra venerabile Matrona della Guerra, Okrilla, mi ha inviato in tutti gli angoli del mondo per cercare $Geroi:eroine; che si uniscano alla nostra causa. T\'interessa rafforzare la presenza dell\'Orda nei Regni Orientali? Allora, entra in questo portale per andare nelle Terre Devastate e presentati a rapporto da Okrilla alla Rocca dei Maglioinfame.', },
    {'Presentati a rapporto da Okrilla alla Rocca dei Maglioinfame nelle Terre Devastate.', },
  },
  [28866] = {
    'Nel Nucleo di Pietra',
    {'Dici che questo Millhouse Manalampo e la Gran Sacerdotessa Azil dovevano incontrarsi nel Nucleo di Pietra?|n|nSembra una cosa grossa. Sarà meglio mettersi sulle loro tracce. Non vogliamo che il Martello del Crepuscolo ce la faccia sotto il naso.|n|nParla con il Custode della Terra Yrsa nel Nucleo di Pietra. Si trova lì per impedire che il Martello del Crepuscolo tenti di riconquistare il Tempio della Terra.', },
    {'Parla con il Custode della Terra Yrsa nel Nucleo di Pietra.', },
  },
  [28867] = {
    'Guardiafatua ha bisogno di te!',
    {'Guardiafatua ha bisogno di te, $C! Sono stata inviata qui dal Quartiermastro Lungertz per eliminare i malvagi lacchè di Okrilla e per reclutare $Gtutti gli eroi:tutte le eroine; dell\'Alleanza! Aiutaci a respingere l\'Orda!|n|nSe decidi di accettare, entra nel portale di fronte a me per recarti nelle Terre Devastate e parla con il Quartiermastro.', },
    {'Parla con il Quartiermastro Lungertz al Forte di Guardiafatua nelle Terre Devastate.', },
  },
  [28868] = {
    'La vista dal basso',
    {'Dobbiamo fermare la costruzione di questo villaggio dei Mantogelido, altrimenti poi sarà difficile cacciarli da qui.|n|nÈ il momento di mostrar loro il mondo dalla prospettiva di uno Gnomo! Prendi questo Equalizzatore di Punti di Vista gnomesco e usalo sui Costruttori Mantogelido per portarli al nostro livello. In questo modo non saranno più in grado di tenere in mano i loro attrezzi e dovranno interrompere la costruzione.', },
    {'Usa l\'Equalizzatore di Punti di Vista su 5 Costruttori Mantogelido al Riparo dei Mantogelido.', },
  },
  [28869] = {
    'Ciottolo',
    {'Se non te ne fossi $Gaccorto:accorta;, c\'è un elementale molto piccolo che ti ha $Gpreso:presa; in simpatia. Resta a terra per qualche istante e sono certo che apparirà.|n|nSembra tu abbia un talento naturale per farti degli amici. Una risorsa importante.', },
    {'Parla con Ciottolo nelle Guglie Frementi. Se resti a terra abbastanza a lungo, dovrebbe uscire dal suo nascondiglio.', },
  },
  [28870] = {
    'Ritorno alla Città Perduta',
    {'Avremo anche conquistato Neferset, ma hanno una nuova base operativa.|n|nGrazie a Siamat, il potente Djinn del vento meridionale, i Neferset sono diventati assai più pericolosi.|n|nAbbiamo appena saputo che parte del gruppo di ricognizione di Nadun caduto in un\'imboscata è riuscito a prendere il controllo dell\'entrata alla Città Perduta.|n|nTrova il Capitano Hadan e raccogli qualsiasi informazione che ti aiuti a eliminare Siamat e la feccia Neferset.', },
    {'Parla con il Capitano Hadan nella Città Perduta dei Tol\'vir.', },
  },
  [28871] = {
    'Distruggere i Granmartello',
    {'Ora che i Granmartello hanno il sostegno dell\'Alleanza, si sono fatti più arditi. Osano premere sul fiume... Devi respingili!|n|nTrova e distruggi i Guerriglieri dei Granmartello che combattono al fiume e tra le Rovine di Tuonocupo lungo la riva nord. I migliori tra loro portano dei fregi; consegnameli per dimostrarmi la tua dedizione alla causa delle Fauci di Drago.', },
    {'Uccidi i Guerriglieri dei Granmartello e prendi 8 Fregi dei Granmartello. Anche i personaggi di rilievo all\'interno delle Rovine di Tuonocupo possiedono dei fregi.', },
  },
  [28872] = {
    'Guerra totale',
    nil,
    {'Distruggi 10 Barilotti di Birra di Tuonocupo alle Rovine di Tuonocupo.', },
  },
  [28873] = {
    'Un\'altra bocca da sfamare',
    {'<Lo stomaco di Griff brontola.>|n|nAncora fame. Come... ogni giorno, ho fame.|n|nHo sentito che c\'è altro cibo da parte nelle Rovine di Tuonocupo oltre il fiume a nord, dove si sta combattendo. Portamene un po\'.', },
    {'Recupera 10 Scorte Alimentari dei Granmartello dalle Rovine di Tuonocupo.', },
  },
  [28874] = {
    'Agganciali',
    {'I Granmartello addestrano Grifoni da Guerra più rapidamente di quanto noi riusciamo a domare e controllare i drachi. Non possiamo permettere che ci superino in numero!|n|nDai la caccia ai Cavalieri di Grifoni che sorvolano il fiume a nord di Forra del Sangue. Prendi questo gancio e lanciaglielo mentre passano. Il colpo li disarcionerà e li farà cadere ai tuoi piedi. Uccidi i Cavalieri di Grifoni disarcionati!', },
    {'Usa la Catena con Gancio per disarcionare e uccidere 4 Cavalieri di Grifoni di Tuonocupo.', },
  },
  [28875] = {
    'Uccidi il Gran Sciamano',
    {'I nostri esploratori sul campo riferiscono che il Gran Sciamano MacKilligan ha lasciato Tuonocupo e sta combattendo tra le Rovine di Tuonocupo, a nord-ovest di qui, oltre il fiume.|n|nÈ pericoloso, $N, e responsabile della morte di molti membri delle Fauci di Drago. SARÀ distrutto, questo è fuori discussione.|n|nLa domanda è: sarai tu ad avere questo onore?', },
    {'Uccidi il Gran Sciamano MacKilligan.', },
  },
  [28876] = {
    'Al Bastione di Mor\'shan',
    {'Kadrak al Bastione di Mor\'shan a nord ha bisogno di aiuto.|n|nL\'avamposto si trova al confine tra le Savane Settentrionali e Valtetra, ed è in prima linea nella lotta contro l\'Alleanza.|n|nIl nostro obiettivo è scacciare gli Elfi della Notte dalla foresta per reclamarne le risorse in nome dell\'Orda!|n|nPer raggiungere il Bastione di Mor\'shan, prendi la Strada dell\'Oro a nord del Crocevia.|n|nIl destino chiama!', },
    {'Fai rapporto a Kadrak al Bastione di Mor\'shan al confine tra le Savane Settentrionali e Valtetra.', },
  },
  [28877] = {
    'Lo chiamano Dagalesta, uccide le Arpie',
    {'C\'è un Orco che vive a ovest, al limitare della scia di distruzione del Cataclisma.|n|nLo chiamano Dagalesta, $N. Lo chiamano così perché... lui... A dire il vero, penso sia il suo nome.|n|n<Scaldapignatta scrolla le spalle.>|n|nIn ogni caso, è una macchina uccidi-arpie. Adora uccidere le Arpie. Lo adora. È una vocazione. Vai a trovarlo! Impara come si fa. Vivi il sogno. Potrebbe diventare la tua carriera.', },
    {'Trova Darsok Dagalesta nelle Savane Settentrionali.', },
  },
  [28878] = {
    'Un regalo di Grande Inverno',
    nil,
    nil,
  },
  [28879] = {
    'Ritorno all\'orfanotrofio',
    nil,
    nil,
  },
  [28880] = {
    'Ritorno all\'orfanotrofio',
    nil,
    nil,
  },
  [28881] = {
    'Prospettore Gunstan',
    {'Dimmi... non hai ancora visitato le Rovine di Luna del Sud, vero? Oh, DEVI andarci. Hanno tutti i tipi di manufatti dei Titani. Dirigiti a ovest e cerca le tende della Lega degli Esploratori.', },
    {'Parla con Prospettore Gunstan alle Rovine di Luna del Sud a Tanaris.', },
  },
  [28882] = {
    'Vittoria a Tol Barad',
    {'Abbiamo combattuto duramente per creare un avamposto su questo dannato sasso... e non permetteremo all\'Orda di metterci i bastoni tra le ruote. La nostra priorità è mantenere il controllo di Tol Barad e abbiamo bisogno del tuo aiuto, $N. Combatti e vinci a Tol Barad e portami la notizia del tuo trionfo.', },
    {'Vinci una battaglia a Tol Barad e torna dal Maggiore Marsden al Campo Base di Baradin nella Penisola di Tol Barad.', },
  },
  [28884] = {
    'Vittoria a Tol Barad',
    {'Mantenere il controllo di Tol Barad è la chiave della nostra strategia qui nei Regni Orientali, $R. Dobbiamo fare tutto quello che serve per tenere l\'Alleanza fuori dall\'isola e questo vuol dire che abbiamo bisogno del tuo aiuto. Combatti al meglio per conquistare Tol Barad e portami la notizia della tua vittoria.', },
    {'Vinci una battaglia a Tol Barad e torna dal Colonnello Karzag all\'Avamposto di Malogrido nella Penisola di Tol Barad.', },
  },
  [28885] = {
    'La corsa del Signor Minadoro',
    {'Bene, $N, dobbiamo raggiungere il Portale della Terra sul fondo della caverna.|n|nMi sono "procurato" un mezzo di trasporto. Perché camminare... quando possiamo viaggiare con stile? Spero ti piacciano i carrelli minerari.|n|nFammi sapere quando sei $Gpronto:pronta;.', },
    {'Corri sul Carrello Minerario con l\'Iniziato Minadoro fino alla fine del binario.', },
  },
