  [28934] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto nell\'Uldum, appena a est della Tomba di Khartut, vicino all\'entrata dalla parte di Tanaris. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Tecnici dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona est della Tomba di Khartut nell\'Uldum. Poi, torna dall\'Ispettore Snip Catenaccio a Roccavento.', },
  },
  [28935] = {
    'Distruggere le Industrie F.lli Corona',
    {'Il Libro Mastro è pieno di luoghi. Questa storia è durata fin troppo a lungo: devi indagare ed entrare in azione!|n|nDa\' un\'occhiata a questa nota: cita un punto nell\'Uldum, a est della Tomba di Khartut e vicino all\'entrata dalla parte di Tanaris. Va\' lì e falli a pezzi.|n|nAh... Se vedi qualcosa di grosso e pericoloso da distruggere, tiragli questa bomba.', },
    {'Uccidi 5 Tecnici dei F.lli Corona e usa la Bomba Korio di Catenaccio per danneggiare un Vagone dei F.lli Corona est della Tomba di Khartut nell\'Uldum. Poi, torna dall\'Investigatore Snap Catenaccio a Orgrimmar.', },
  },
